// The line that arrives after the test has ended is the one that used to
// take the package with it.
//
// **Go panics on a log whose test and every parent are done**, which is
// what `testing`'s own destination() says at the site: a line from a
// completed subtest is handed to its live parent and nothing happens, so
// the window is narrower than it looks and the package dies only when the
// run itself is over. That is why it took a verbose `-count=150` loop over
// three connection-churning tests to see it once, and why a test that waits
// for it to happen is not a test.
//
// So what is asserted here is the rule that closes the window rather than
// the panic that follows from breaking it: once the test has ended, nothing
// is written to it. Watched against the real thing before it was written
// this way - a goroutine logging 300ms after its test, with a TestMain
// holding the run open long enough for the framework to have finished -
// which panicked with `Log in goroutine after TestALateLoggerIsSpawned has
// completed` on the writer as it was, and does not on the writer as it is.
func TestALogLineArrivingAfterItsTestIsDroppedRatherThanPanicking(t *testing.T) {
	target := &countingTarget{}
	w := newTestWriter(target)

	if _, err := w.Write([]byte("a line written while the test is running")); err != nil {
		t.Fatalf("writing during the test: %v", err)
	}
	if target.Lines != 1 {
		t.Fatalf("the writer wrote %d lines to a live test, want 1 - this test is "+
			"asserting nothing about the case below", target.Lines)
	}

	// The test ends. Its cleanups run, which is where the writer learns.
	target.End()

	// And this is the listener's read loop, reporting the connection that
	// was closed on the way out.
	late := []byte("a line written after the test has ended")
	n, err := w.Write(late)
	if err != nil {
		t.Errorf("a late line was refused: %v", err)
	}
	if n != len(late) {
		t.Errorf("a late line was reported as %d bytes of %d written; slog treats a "+
			"short write as an error and says so on the next line", n, len(late))
	}
	if target.Lines != 1 {
		t.Errorf("the writer logged to a test that had ended: Go panics on that and " +
			"takes the whole package with it, naming neither the test nor the reason")
	}
}

// --- append ------------------------------------------------------------

// RFC 0003 "`append` - Durable consumers"
//
// A consumer that did not exist when the records were published still
// reads them. This is the property an ordinary broker's bounded session
// queue cannot provide.
func TestAppendReplaysToALaterSubscriber(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}

	c := connect(t, h, "analytics", false, false)
	c.Sub(t, "events/#", 0)

	for i := 1; i <= 3; i++ {
		r, ok := c.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("replay: expected record %d, got nothing", i)
		}
		if want := fmt.Sprintf("order-%d", i); r.Payload != want {
			t.Fatalf("replay out of order: got %q, want %q", r.Payload, want)
		}
		if r.User["saguin-offset"] != fmt.Sprint(i) {
			t.Fatalf("offset: got %q, want %d", r.User["saguin-offset"], i)
		}
	}

	// And then tails live.
	p.Pub(t, "events/orders/4", "order-4")
	r, ok := c.Await(t, 2*time.Second)
	if !ok || r.Payload != "order-4" {
		t.Fatalf("live tail: got %q ok=%v", r.Payload, ok)
	}
}

// RFC 0003 "`append` - Durable consumers", invariant 13
//
// A backlog longer than one batch reaches a QoS 0 consumer whole. QoS 0
// has no PUBACK, so nothing calls pump again when a slot frees and the
// drain is pump's own loop - this is what says the loop is there.
//
// What it cannot say is the thing the loop exists for: that the channel is
// read a bounded batch at a time rather than materialised whole under the
// broker lock. Both shapes deliver the same records, so that half holds by
// reading pumpBatch rather than by running this. What running it catches
// is the regression that bound without draining, which would deliver the
// first batch and abandon the rest in silence.
func TestQoS0DrainsABacklogLongerThanOneBatch(t *testing.T) {
	// qos0Batch is 256, and this is unexported: one full batch and a
	// remainder. It has to stay above qos0Batch to be testing anything.
	const backlog = 100

	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= backlog; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}

	c := connect(t, h, "analytics", true, false)
	c.Sub(t, "events/#", 0)

	deadline := time.Now().Add(10 * time.Second)
	for c.Count() < backlog && time.Now().Before(deadline) {
		time.Sleep(20 * time.Millisecond)
	}
	if got := c.Count(); got != backlog {
		t.Fatalf("QoS 0 backlog: received %d of %d records", got, backlog)
	}
	for i, got := range c.Payloads() {
		if want := fmt.Sprintf("order-%d", i+1); got != want {
			t.Fatalf("record %d: got %q, want %q", i+1, got, want)
		}
	}
}

// RFC 0003 "`append` - Live subscription"
//
// A subscriber whose filter matches only part of a channel still receives
// a matching record that sits behind more than a window of non-matching
// ones. pump reads at most a window of records per call; when none of them
// match, nothing is put in flight, so no PUBACK ever calls pump again -
// and unless pump itself comes back for the next batch, the matching
// record beyond is never delivered while the channel is quiet.
func TestNarrowFilterIsFedPastAWindowOfNonMatchingRecords(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	// Five windows of records the consumer's filter does not match.
	for i := 1; i <= 40; i++ {
		p.Pub(t, fmt.Sprintf("events/noise/%d", i), fmt.Sprintf("noise-%d", i))
	}

	c := connectRx(t, h, "picky", true, false, 8)
	c.Sub(t, "events/wanted/#", 1)

	p.Pub(t, "events/wanted/1", "the-one")
	r, ok := c.Await(t, 5*time.Second)
	if !ok {
		t.Fatalf("the matching record was never delivered: the cursor stalled " +
			"behind a window of non-matching records")
	}
	if r.Payload != "the-one" {
		t.Fatalf("got %q, want %q", r.Payload, "the-one")
	}
}

// RFC 0003 "`append` - Live subscription"
//
// The same rule as the test above, for records published *after* the
// subscriber arrived rather than before it. That is the case pumpAll's
// filter changes: a publish a subscriber's filter cannot match no longer
// pumps it at all, so its cursor stays where it was and the whole run has
// to be read past when a record finally does match.
//
// Delivered incrementally the run is invisible. Deferred, it is a single
// catch-up longer than the window, which is the thing that stalls if
// pumpBatch does not come back for the next batch.
func TestNarrowFilterIsFedPastRecordsPublishedAfterItSubscribed(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	// Subscribed first, to an empty channel, with a small window.
	c := connectRx(t, h, "picky", true, false, 8)
	c.Sub(t, "events/wanted/#", 1)
	subscribed(t, c.C)

	// Five windows of records it does not want, published while it watches.
	for i := 1; i <= 40; i++ {
		p.Pub(t, fmt.Sprintf("events/noise/%d", i), fmt.Sprintf("noise-%d", i))
	}
	if _, got := c.Await(t, 300*time.Millisecond); got {
		t.Fatal("a record the subscriber's filter does not match was delivered to it")
	}

	p.Pub(t, "events/wanted/1", "the-one")
	r, ok := c.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("the matching record was never delivered: the cursor stalled behind the " +
			"run of non-matching records it had not been pumped over")
	}
	if r.Payload != "the-one" {
		t.Fatalf("got %q, want the-one", r.Payload)
	}
}

// RFC 0003 "Ordering" - append: total order by offset; each subscriber
// receives records in that order.
//
// The QoS 0 drain releases the broker lock between batches, and a publish
// landing in one of those gaps pumps the same consumer from the
// publisher's goroutine. Unless one drain runs at a time per consumer and
// channel, that second goroutine reads the next batch and writes it while
// the first is still writing the previous one, and the subscriber sees
// offsets out of order.
func TestQoS0BacklogStaysOrderedUnderALivePublisher(t *testing.T) {
	const backlog = 100
	const live = 300

	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= backlog; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), "backlog")
	}

	c := connect(t, h, "analytics", true, false)

	// Published while the backlog above is draining - the SUBACK is not
	// written until the subscribe-time drain returns, so the publisher has
	// to run beside the subscribe, not after it, for pumpAll to race the
	// drain loop for the same consumer.
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 1; i <= live; i++ {
			_, err := p.C.Publish(context.Background(), &paho.Publish{
				Topic: fmt.Sprintf("events/orders/live-%d", i), QoS: 1, Payload: []byte("live"),
			})
			if err != nil {
				t.Errorf("live publish %d: %v", i, err)
				return
			}
		}
	}()
	c.Sub(t, "events/#", 0)
	wg.Wait()

	deadline := time.Now().Add(15 * time.Second)
	for c.Count() < backlog+live && time.Now().Before(deadline) {
		time.Sleep(20 * time.Millisecond)
	}
	if got := c.Count(); got != backlog+live {
		t.Fatalf("received %d of %d records", got, backlog+live)
	}
	var last uint64
	for i, r := range c.All() {
		off, err := strconv.ParseUint(r.User["saguin-offset"], 10, 64)
		if err != nil {
			t.Fatalf("record %d: unreadable saguin-offset %q", i+1, r.User["saguin-offset"])
		}
		if off <= last {
			t.Fatalf("record %d arrived out of order: offset %d after %d", i+1, off, last)
		}
		last = off
	}
}

// RFC 0003 "`append` - A position advances on the acknowledgement, and QoS
// 0 has none", RFC 0002 "Disconnecting is the answer rather than dropping".
//
// **A durable position advances on the write when the grant is QoS 0, with
// no acknowledgement anywhere in it.** RFC 0002 says a durable consumer's
// position advances only on its `PUBACK`, which is the rule at QoS 1 and
// the reason a consumer disconnected mid-record loses nothing. The SUBACK
// table grants QoS 0 on an `append` channel, QoS 0 has no `PUBACK`, and
// until this ran nothing said which way that fell.
//
// **The broker is restarted rather than the client reconnected**, and that
// is the whole instrument. A reconnecting session re-sends its own
// unacknowledged packets and keeps the live cursor it had, so a client that
// merely reconnects is answered from the session either way and the stored
// position is never consulted - the first version of this test did exactly
// that, passed, and passed just as happily with the QoS 0 path mutated to
// hold its position back. A restart leaves no cursor, and the session that
// comes back holds no channel record: a channel keeps its records and the
// session holds a position in them, so nothing a restored session owns could
// answer the reads below. That is asserted rather than assumed, because it
// is what makes the rest of this about a stored position.
//
// **And the consumer never reads its socket**, which is what makes the two
// arms differ at all. A client library drains the socket whatever its
// handler is doing, so a consumer driven by one has taken every record
// before the link breaks. Five small records fit inside the kernel's own
// buffer, so the broker's write succeeds while nothing at the far end has
// seen a byte, and cutting the socket destroys exactly the records a QoS 1
// consumer is owed.
func TestAQoS0PositionAdvancesOnTheWriteWithNothingAcknowledged(t *testing.T) {
	for _, tc := range []struct {
		name      string
		qos       byte
		wantAgain int
		why       string
	}{
		{"QoS 0", 0, 0, "the position advanced on the write, so all five are behind it"},
		{"QoS 1", 1, 5, "nothing was acknowledged, so the position could not pass them"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			h := startDurable(t, dir)
			id := "deaf-durable-qos" + string(rune('0'+tc.qos))

			conn, err := net.Dial(h.Network, h.Addr)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			send := func(p pahopackets.Packet, kind byte) {
				t.Helper()
				cp := pahopackets.NewControlPacket(kind)
				cp.Content = p
				if _, err := cp.WriteTo(conn); err != nil {
					t.Fatalf("write %d: %v", kind, err)
				}
			}
			expiry := uint32(3600)
			send(&pahopackets.Connect{
				ClientID: id, CleanStart: false, KeepAlive: 0,
				ProtocolName: "MQTT", ProtocolVersion: 5,
				Properties: &pahopackets.Properties{SessionExpiryInterval: &expiry},
			}, pahopackets.CONNECT)
			ca, err := pahopackets.ReadPacket(conn)
			if err != nil {
				t.Fatalf("read the CONNACK: %v", err)
			}
			if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
				t.Fatalf("connect refused 0x%02X", got)
			}
			send(&pahopackets.Subscribe{
				PacketID:      1,
				Subscriptions: []pahopackets.SubOptions{{Topic: "events/#", QoS: tc.qos}},
			}, pahopackets.SUBSCRIBE)
			sa, err := pahopackets.ReadPacket(conn)
			if err != nil {
				t.Fatalf("read the SUBACK: %v", err)
			}
			if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got != tc.qos {
				t.Fatalf("the subscription was answered 0x%02X, want a grant at QoS %d", got, tc.qos)
			}

			// From here the socket is never read.

			p := connect(t, h, "producer", true, false)
			for i := 1; i <= 5; i++ {
				p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
			}
			// The far end reads nothing, so there is no acknowledgement to
			// wait on; what the broker did with the five is read from the
			// broker instead. At QoS 0 the position advances as each is
			// written, so the stored position reaching past the fifth says
			// all five went; at QoS 1 the five in flight say so.
			if tc.qos == 0 {
				awaitStoredPosition(t, h, "events", 6, 5*time.Second)
			} else {
				for deadline := time.Now().Add(5 * time.Second); ; time.Sleep(time.Millisecond) {
					if cl, ok := h.Srv.Clients.Get(id); ok && cl.State.Inflight.Len() == 5 {
						break
					}
					if time.Now().After(deadline) {
						t.Fatal("the five were not all in flight to the deaf consumer after 5s")
					}
				}
			}

			before := h.Disconnects.Snapshot(id)
			_ = conn.Close()
			sessionGoneAfter(t, h, id, before)

			// The restart is what removes the session and the live cursor,
			// so what the consumer is served next comes from the store.
			h.Stop()
			h2 := startDurable(t, dir)

			if cl, ok := h2.Srv.Clients.Get(id); !ok {
				t.Fatal("the session did not come back, so this test is no longer the " +
					"instrument it describes")
			} else if n := cl.State.Inflight.Len(); n != 0 {
				t.Fatalf("the restored session holds %d deliveries in flight: a channel's "+
					"records are not session state, and what arrives below could be the "+
					"session's own replay rather than the stored position", n)
			}
			again := connect(t, h2, id, false, false)
			if !again.SessionPresent {
				t.Fatal("the client that came back was told Session Present 0, so the " +
					"subscription below is a new one rather than the restored session's")
			}
			again.Sub(t, "events/#", 1)
			// An end marker, so "none came back" is an ordering rather than
			// a wait: it is stored after the five and served after any of
			// them (RFC 0003 "Ordering").
			connect(t, h2, "producer", true, false).Pub(t, "events/orders/marker", "marker")
			got := 0
			for {
				r, ok := again.Await(t, 5*time.Second)
				if !ok {
					t.Fatalf("the end marker never arrived; %d of the five before it", got)
				}
				if r.Payload == "marker" {
					break
				}
				got++
			}
			if got != tc.wantAgain {
				t.Fatalf("a durable consumer granted QoS %d had five records written at a socket "+
					"it never read; across a restart it was served %d of them, want %d - %s",
					tc.qos, got, tc.wantAgain, tc.why)
			}
		})
	}
}

// RFC 0003 "`append` - Durable consumers", delivery at the granted QoS
//
// Records a consumer acknowledged must not come back after it reconnects.
// Paho sends the PUBACK when the receive handler returns, so holding the
// handler open on the last record is a consumer that has received it and
// not confirmed it, and breaking the socket underneath is the link
// dropping at exactly that moment.
//
// The load-bearing assertion here is that order-1 and order-2 do *not*
// return. That order-3 does is weaker than it looks: a resuming MQTT
// session replays its own unacknowledged packet, so order-3 arrives even
// if saguin's stored position is wrong. The rule that the position is the
// lowest unacknowledged offset is asserted in position_test.go, where no
// session replay can stand in for it.
func TestUnacknowledgedRecordIsRedeliveredAndAcknowledgedOnesAreNot(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}

	// The first two are acknowledged as their handler returns. The third
	// stops in the handler, so it is received and never confirmed.
	hold := make(chan struct{})
	c := connectRx(t, h, "reader", false, false, 10)
	c.Mu.Lock()
	c.Hold, c.HoldPayload = hold, "order-3"
	c.Mu.Unlock()

	c.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatalf("expected record %d at QoS 1, got nothing", i)
		}
	}
	// The first two acknowledged at the broker, the third still held.
	awaitInFlight(t, c, 1)

	// Break the link while the record is unacknowledged. Releasing the
	// handler afterwards sends the PUBACK into a socket that is gone,
	// which is what a dropping connection does to a consumer mid-record.
	cut := h.Disconnects.Snapshot("reader")
	_ = c.Conn.Close()
	close(hold)
	sessionGoneAfter(t, h, "reader", cut)

	again := connectRx(t, h, "reader", false, false, 10)
	again.Sub(t, "events/#", 1)
	// The end marker: stored after everything above, so it arrives after
	// whatever the resume was going to send (RFC 0003 "Ordering").
	p.Pub(t, "events/orders/marker", "marker")

	// A record may arrive more than once - saguin resumes from the stored
	// position and the restored session replays its own unacknowledged
	// packet, and at-least-once permits both. What must not happen is an
	// acknowledged record coming back, or the unacknowledged one not.
	seen := map[string]bool{}
	for !seen["marker"] {
		r, ok := again.Await(t, 5*time.Second)
		if !ok {
			t.Fatalf("the end marker never arrived; seen %v", seen)
		}
		seen[r.Payload] = true
	}
	if !seen["order-3"] {
		t.Fatal("order-3 was never redelivered: the position advanced past a record " +
			"the consumer received and never acknowledged, and it is now unreachable")
	}
	if seen["order-1"] || seen["order-2"] {
		t.Fatalf("an acknowledged record was redelivered: %v", seen)
	}
}

// subscribed is a round trip after a SUBSCRIBE that publishes nothing: an
// UNSUBSCRIBE of a filter c never held. A client's packets are read and
// handled in order on one read loop, so its UNSUBACK says that loop has done
// everything it does for the SUBSCRIBE before it. It stands where a sleep of
// 150-300ms stood, and unlike settle it adds no publish for a test that counts
// them or an acl_file that refuses them.
func subscribed(t *testing.T, c *paho.Client) {
	t.Helper()
	if _, err := c.Unsubscribe(context.Background(), &paho.Unsubscribe{
		Topics: []string{"settle/never-subscribed"},
	}); err != nil {
		t.Fatalf("the round trip after a SUBSCRIBE failed: %v", err)
	}
}

// RFC 0003 "`append` - Durable consumers"
//
// A backlog larger than the in-flight window must still drain completely.
// Delivery stops at the window and can only continue when a PUBACK frees a
// slot, so a pump that runs on subscribe but not on acknowledgement leaves
// the consumer stalled at exactly Receive Maximum records for ever.
func TestBacklogLargerThanTheWindowStillDrains(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	const total = 8
	for i := 1; i <= total; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}

	c := connectRx(t, h, "slow", false, false, 2)
	c.Sub(t, "events/#", 1)

	for seen := 0; seen < total; seen++ {
		r, ok := c.Await(t, 10*time.Second)
		if !ok {
			t.Fatalf("only %d of %d records were delivered; the pump did not resume "+
				"when acknowledgements freed the window", seen, total)
		}
		if want := fmt.Sprintf("order-%d", seen+1); r.Payload != want {
			t.Fatalf("out of order: got %q, want %q", r.Payload, want)
		}
	}
}

// RFC 0002 "Publishing", invariant 1
//
// A client may declare a Maximum Packet Size on CONNECT, and MQTT forbids
// the server sending it anything larger (MQTT-3.1.2-24, -25). The write
// fails while the connection stays perfectly healthy, which is not what a
// failed write usually means: retried from the same offset it fails the
// same way on every publish and every PUBACK, and the consumer is never fed
// again with nothing reported anywhere.
//
// saguin disconnects instead. Skipping the record would leave the consumer
// processing everything after it in order and reporting success over one it
// never received. Disconnecting keeps the position at that record, so the
// consumer gets it as soon as it reconnects able to hold it - and one that
// reconnects with the same bound wedges loudly rather than in silence.
func TestRecordTooLargeForASubscriberDisconnectsIt(t *testing.T) {
	const maxPacket = 512
	big := strings.Repeat("x", 4*maxPacket)

	h := start(t)
	p := connect(t, h, "producer", true, false)

	c := connectMaxPacket(t, h, "narrow", maxPacket)
	c.Sub(t, "events/#", 1)

	// A record within the bound is delivered normally.
	p.Pub(t, "events/a/1", "small")
	if r, ok := c.Await(t, 3*time.Second); !ok || r.Payload != "small" {
		t.Fatalf("the first record: got %q ok=%v, want small", r.Payload, ok)
	}

	p.Pub(t, "events/a/2", big)
	p.Pub(t, "events/a/3", "after")

	select {
	case d := <-c.Gone:
		if d.ReasonCode != 0x95 {
			t.Fatalf("disconnected with %#x, want 0x95 Packet too large", d.ReasonCode)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("a record larger than the consumer's Maximum Packet Size neither reached " +
			"it nor disconnected it: the consumer is stopped at that offset and will " +
			"never be fed again, silently")
	}

	// The position stayed at the record it never received, so a consumer
	// coming back able to hold it gets that record. "small" may arrive a
	// second time - its PUBACK races the disconnect, and at-least-once
	// permits that. The oversized record being skipped is the failure.
	again := connect(t, h, "narrow", false, false)
	deadline := time.After(3 * time.Second)
	for {
		select {
		case r := <-again.Ch:
			if r.Payload == big {
				return
			}
			if r.Payload == "after" {
				t.Fatal("the consumer resumed past the record it never received: that " +
					"record is now unreachable and the consumer reports success over it")
			}
		case <-deadline:
			t.Fatal("after reconnecting without the bound, the oversized record never arrived")
		}
	}
}

// RFC 0003 "`append` - Durable consumers"
//
// A consumer whose link drops and who reconnects with its session intact
// does not subscribe again - the server restores its subscriptions and
// fires no subscribe hook. saguin must honour them anyway.
//
// Otherwise such a consumer is invisible to the broker: no backlog, no
// live records, and nothing reported. Clients that re-subscribe on every
// connect never meet it, which is what makes it easy to ship.
func TestResumedSessionReceivesWithoutSubscribingAgain(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	c := connect(t, h, "device", false, false)
	c.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/1", "first")
	if _, ok := c.Await(t, 3*time.Second); !ok {
		t.Fatal("no live delivery before the link dropped")
	}
	acknowledged(t, c) // the acknowledgement landed, so "first" is behind it

	linkCut(t, c)
	p.Pub(t, "events/a/2", "second") // published while it is away

	again := connect(t, h, "device", false, false)
	r, ok := again.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a resumed session with restored subscriptions received nothing: " +
			"saguin's subscription index was not rebuilt, so the consumer is invisible")
	}
	if r.Payload != "second" {
		t.Fatalf("resumed at the wrong position: got %q, want second", r.Payload)
	}

	p.Pub(t, "events/a/3", "third")
	if r, ok := again.Await(t, 3*time.Second); !ok || r.Payload != "third" {
		t.Fatalf("a resumed session received no live record: got %q ok=%v", r.Payload, ok)
	}
}

// RFC 0003 "`append` - Durable consumers"
//
// A second connection using the same client id takes the session over. The
// superseded connection's teardown runs afterwards and must not take the
// live session's subscriptions and cursors with it - they belong to the new
// connection now.
func TestTakeoverKeepsTheNewSessionSubscribed(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	first := connect(t, h, "device", false, false)
	first.Sub(t, "events/#", 1)
	subscribed(t, first.C)

	// Same client id, and deliberately no subscribe: everything each of
	// these connections has, it inherited.
	//
	// Repeated because the window is a race. The superseded connection's
	// teardown runs on its own goroutine and usually lands before the new
	// session is established, where it is harmless; the damage happens only
	// when it lands after. One round would be a coin flip.
	current := first
	delivered := map[string]bool{}
	for round := 1; round <= 15; round++ {
		superseded := h.Disconnects.Snapshot("device")
		next := connect(t, h, "device", false, false)
		// Once the superseded connection's teardown has landed, which is
		// when it would have taken the subscription: waited for, so every
		// round is the losing order rather than a coin flip.
		sessionGoneAfter(t, h, "device", superseded)
		_ = current
		current = next

		p.Pub(t, "events/a/1", fmt.Sprintf("round-%d", round))
		want := fmt.Sprintf("round-%d", round)
		for {
			r, ok := current.Await(t, 2*time.Second)
			if !ok {
				t.Fatalf("round %d: the session that took over received nothing - the "+
					"superseded connection's teardown removed the live session's "+
					"subscription", round)
			}
			if r.Payload == want {
				break
			}
			// A record from an earlier round can come back: the takeover can
			// cut its PUBACK off between the client sending it and the broker
			// processing it, and a record nobody acknowledged is redelivered.
			// That is at-least-once keeping its promise, not the failure this
			// test exists for. Anything else is.
			if !delivered[r.Payload] {
				t.Fatalf("round %d: got %q, want %q", round, r.Payload, want)
			}
		}
		delivered[want] = true
	}
}

// RFC 0003 "`append` - Durable consumers", invariant 13
//
// A position outlives its session for nobody. When the session is discarded
// - Session Expiry Interval 0 - the position goes with it, and the client id
// starts again as a consumer the broker has never seen.
//
// This is also what stops the position map growing for every client id that
// ever connects.
func TestExpiringSessionDiscardsThePosition(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/a/1", "one")
	p.Pub(t, "events/a/2", "two")

	c := connectExpiring(t, h, "temp")
	c.Sub(t, "events/#", 1)
	for i := 1; i <= 2; i++ {
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatalf("expected record %d before the disconnect", i)
		}
	}
	acknowledged(t, c) // its last PUBACK read, so the position stored is past it
	gone(t, c)

	again := connectExpiring(t, h, "temp")
	again.Sub(t, "events/#", 1)
	r, ok := again.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a session that had been discarded received no replay at all")
	}
	if r.Payload != "one" {
		t.Fatalf("replay started at %q, want one - the position outlived the "+
			"session it belonged to", r.Payload)
	}
}

// RFC 0002 "What a filter reaches" - invariant 11
//
// **A wildcard never reaches a queue, and reaches everything else.** This is
// the rule that changed when a channel stopped claiming its name: `#` is now
// served every append and latest channel it matches, because a client is
// meant to subscribe the way MQTT already works and never learn where the
// channels are. What is still impossible is the harm the invariant is
// written as - `mosquitto_sub -t '#'` draining a work queue into somebody's
// debugging session - because a queue admits one subscription form and this
// is not it.
//
// **The queue assertion is the one that can fail silently**, and it is the
// reason the counting below is exact rather than "at least the broadcast
// one": a `#` subscriber served the queue record too would still pass a test
// that only looked for what it expected to see.
func TestAWildcardReachesEverythingButAQueue(t *testing.T) {
	h := start(t)
	spy := connect(t, h, "spy", true, false)
	spy.Sub(t, "#", 1)
	subscribed(t, spy.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/orders/1", "channel record")
	p.Pub(t, "state/device/1", "current state")
	p.Pub(t, "jobs/a", "queue record")
	p.Pub(t, "weather/now", "broadcast record")

	// Everything but the queue's, whatever order the three arrive in.
	want := map[string]string{
		"events/orders/1": "channel record",
		"state/device/1":  "current state",
		"weather/now":     "broadcast record",
	}
	got := map[string]string{}
	for range len(want) {
		r, ok := spy.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("a `#` subscriber received %d of %d records: %v", len(got), len(want), got)
		}
		got[r.Topic] = r.Payload
	}
	for topic, payload := range want {
		if got[topic] != payload {
			t.Errorf("`#` received %q on %q, want %q - a filter is served every append and "+
				"latest channel it matches", got[topic], topic, payload)
		}
	}

	// **And nothing else at all**, which is where the queue record would show
	// up. A worker takes its jobs from a pinned shared subscription; a
	// wildcard that could take one instead would leave the job acknowledged
	// by a subscriber that was never asked to do it.
	if r, more := spy.Await(t, 500*time.Millisecond); more {
		t.Fatalf("a `#` subscriber received %q on %q as well - a wildcard reached a queue",
			r.Payload, r.Topic)
	}
}

// --- latest ------------------------------------------------------------

// RFC 0003 "`latest`", RFC 0002 "What each channel type admits - `latest`"
//
// A subscriber receives the current value of every topic its filter
// reaches, whenever it subscribes, and nothing older. Publishing replaces
// a value rather than adding to a history.
func TestLatestDeliversCurrentStateOnSubscribe(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	p.Pub(t, "state/device/1/temp", "20")
	p.Pub(t, "state/device/2/temp", "21")
	p.Pub(t, "state/device/1/temp", "22") // replaces, does not accumulate

	c := connect(t, h, "dashboard", true, false)
	c.Sub(t, "state/#", 1)

	got := map[string]string{}
	for range 2 {
		r, ok := c.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("expected the current value of two topics, got %d", len(got))
		}
		got[r.Topic] = r.Payload
		if !r.Retain {
			// Current state carries RETAIN; a live update does not. Without
			// it a client cannot tell catching up from something happening.
			t.Fatalf("current state for %q arrived without the RETAIN flag", r.Topic)
		}
	}
	if got["state/device/1/temp"] != "22" {
		t.Fatalf("device 1: got %q, want 22 - a replaced value was served",
			got["state/device/1/temp"])
	}
	if got["state/device/2/temp"] != "21" {
		t.Fatalf("device 2: got %q, want 21", got["state/device/2/temp"])
	}
	if extra, more := c.Await(t, time.Second); more {
		t.Fatalf("a latest channel delivered a third record: %q on %q - values are "+
			"replaced, not accumulated", extra.Payload, extra.Topic)
	}
}

// RFC 0003 "`latest`"
//
// A subscriber that is already connected sees updates as they happen, and
// a second subscriber arriving later sees only the newest value.
func TestLatestDeliversLiveUpdatesAndThenCurrentState(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	live := connect(t, h, "live", true, false)
	live.Sub(t, "state/#", 1)
	subscribed(t, live.C)

	for _, v := range []string{"1", "2", "3"} {
		p.Pub(t, "state/counter", v)
		r, ok := live.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("a connected subscriber did not receive the update %q", v)
		}
		if r.Payload != v {
			t.Fatalf("live update: got %q, want %q", r.Payload, v)
		}
		if r.Retain {
			t.Fatalf("live update %q carried the RETAIN flag; only current state does", v)
		}
	}

	later := connect(t, h, "later", true, false)
	later.Sub(t, "state/#", 1)
	r, ok := later.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a later subscriber received no current state")
	}
	if r.Payload != "3" {
		t.Fatalf("a later subscriber got %q, want only the newest value 3", r.Payload)
	}
}

// RFC 0003 "`latest`"
//
// A zero-length payload deletes the value, following MQTT's own retained
// convention. Connected subscribers see the empty message - that is how
// they learn the key is gone - and a later subscriber sees nothing at all.
func TestLatestZeroLengthPayloadDeletes(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "state/device/9/temp", "30")

	watcher := connect(t, h, "watcher", true, false)
	watcher.Sub(t, "state/#", 1)
	if r, ok := watcher.Await(t, 3*time.Second); !ok || r.Payload != "30" {
		t.Fatalf("current state before the delete: got %q ok=%v", r.Payload, ok)
	}

	p.Pub(t, "state/device/9/temp", "") // the delete
	r, ok := watcher.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a connected subscriber was not told the value was deleted")
	}
	if r.Payload != "" {
		t.Fatalf("delete delivered as %q, want an empty payload", r.Payload)
	}

	later := connect(t, h, "later", true, false)
	later.Sub(t, "state/#", 1)
	if extra, more := later.Await(t, 2*time.Second); more {
		t.Fatalf("a deleted value was still served as current state: %q on %q",
			extra.Payload, extra.Topic)
	}
}

// RFC 0002 "What a filter reaches" - invariant 11
//
// A latest channel's current state is served to a top-level wildcard, and
// it arrives **carrying RETAIN** - which is the half worth asserting rather
// than the count. A subscriber that cannot tell state it is catching up on
// from something that has just happened is a subscriber that acts on a
// three-week-old reading as though it were news, and the flag is the only
// thing that says which it is.
func TestLatestReachesATopLevelWildcardCarryingRetain(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "state/device/1/temp", "20")

	// Subscribing after the value was set: this one is catch-up.
	spy := connect(t, h, "spy", true, false)
	spy.Sub(t, "#", 1)

	caught, ok := spy.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a `#` subscriber was served no current state at all")
	}
	if caught.Topic != "state/device/1/temp" || caught.Payload != "20" {
		t.Fatalf("got %q on %q, want 20 on state/device/1/temp", caught.Payload, caught.Topic)
	}
	if !caught.Retain {
		t.Error("current state reached a `#` subscriber without RETAIN, so it cannot tell " +
			"a value it is catching up on from one that has just been set")
	}

	// And a change after subscribing is live, without the flag.
	p.Pub(t, "state/device/2/temp", "21")
	live, ok := spy.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a change to a latest channel did not reach a `#` subscriber")
	}
	if live.Payload != "21" {
		t.Fatalf("got %q, want 21", live.Payload)
	}
	if live.Retain {
		t.Error("a live update carried RETAIN, which says it is catch-up")
	}
}

// RFC 0003 "`latest`", invariant 1
//
// The same bound as the append path, on the path beside it. A subscriber
// is promised the current value of every topic its filter reaches, and a
// value larger than its declared Maximum Packet Size cannot be sent
// (MQTT-3.1.2-24, -25) - not now and not on any later subscribe, because
// nothing about it will have changed.
//
// Left out of the snapshot, it is a topic missing from the subscriber's
// view of current state with nothing anywhere saying so: a dashboard with
// one tile that never fills in. So the subscriber is disconnected instead,
// exactly as an oversized append record disconnects its consumer.
func TestLatestValueTooLargeForASubscriberDisconnectsIt(t *testing.T) {
	const maxPacket = 512
	big := strings.Repeat("x", 4*maxPacket)

	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "state/device/1/temp", "20")
	p.Pub(t, "state/device/2/blob", big)

	// Subscribed directly rather than through sub, which reports a refusal
	// as a fatal error: current state is delivered from inside the
	// subscribe, so the disconnect lands before the SUBACK does.
	c := connectMaxPacket(t, h, "narrow", maxPacket)
	_, _ = c.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "state/#", QoS: 1}},
	})

	select {
	case d := <-c.Gone:
		if d.ReasonCode != 0x95 {
			t.Fatalf("disconnected with %#x, want 0x95 Packet too large", d.ReasonCode)
		}
	case <-time.After(3 * time.Second):
		t.Fatalf("a value larger than the subscriber's Maximum Packet Size neither "+
			"reached it nor disconnected it: it holds %d of 2 topics and believes "+
			"that is the current state", c.Count())
	}

	// Nothing was consumed by the attempt: a subscriber able to hold the
	// value is still sent both topics.
	full := connect(t, h, "wide", true, false)
	full.Sub(t, "state/#", 1)
	got := map[string]string{}
	for range 2 {
		r, ok := full.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("a subscriber with no bound received %d of 2 topics", len(got))
		}
		got[r.Topic] = r.Payload
	}
	if got["state/device/1/temp"] != "20" || got["state/device/2/blob"] != big {
		t.Fatalf("current state after the refused delivery: %d topics, temp=%q",
			len(got), got["state/device/1/temp"])
	}
}

// RFC 0002 "What each channel type admits - `latest`", "Shared
// subscriptions"
//
// A shared subscription on a `latest` channel is granted and is served
// changes only. No pass of current state: MQTT does not deliver retained
// messages to a shared subscription, and current state is delivered
// carrying RETAIN.
//
// **The value set before it subscribed is the assertion**, not the count.
// A subscriber that receives the later change and not the earlier value
// has been served changes; one that receives both has been served state,
// and one that receives neither would pass a test written only against
// the first.
func TestASharedSubscriptionOnLatestGetsChangesAndNotCurrentState(t *testing.T) {
	h := start(t)
	p := connect(t, h, "setter", true, false)
	p.Pub(t, "state/device/1/temp", "before")

	c := connect(t, h, "reader", true, false)
	sa := c.Sub(t, "$share/dash/state/#", 1)
	if sa.Reasons[0] > 2 {
		t.Fatalf("a shared subscription on a latest channel was refused %#x: `$share` "+
			"is MQTT's and saguin refuses it for nothing it reaches", sa.Reasons[0])
	}

	// **The change is the end marker.** Current state served on subscribe
	// would reach the subscriber before a change published after it, so the
	// first thing it is sent being "after" says it was sent no state. The
	// round trip first, because a subscription's state is served once its
	// SUBACK is written: the next packet is read after that has returned.
	subscribed(t, c.C)
	p.Pub(t, "state/device/1/temp", "after")
	select {
	case r := <-c.Ch:
		if r.Payload != "after" {
			t.Fatalf("the shared subscriber was sent %q = %q before the live change: a "+
				"shared subscription is served changes, and current state carries "+
				"RETAIN, which MQTT does not deliver to one", r.Topic, r.Payload)
		}
		if r.Retain {
			t.Errorf("the live change reached the shared subscriber with RETAIN set: " +
				"nothing retained it, and a shared subscriber is served changes rather " +
				"than state")
		}
		for k := range r.User {
			if strings.HasPrefix(k, "saguin-") {
				t.Errorf("the shared delivery carries %q: a shared subscription is "+
					"served live MQTT and gets none of a channel's labels", k)
			}
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the shared subscriber received no live change: a shared subscription " +
			"on a latest channel is served changes, and receiving nothing at all is " +
			"the failure a refusal used to make loud")
	}
}

// RFC 0002 "Shared subscriptions" - invariant 1
//
// **Giving up a shared subscription must not take an ordinary one with
// it.** One client holding `events/#` and `$share/g/events/#` unsubscribes
// from the shared one; the durable subscription is still live and must go
// on being fed.
//
// The failure is silent from both ends: the client keeps a subscription the
// broker will not feed, its stored position stays where it was, and nothing
// is logged. It is reachable because saguin's index is keyed by the filter
// and the unsubscribe path used to strip `$share/` before comparing - which
// turned the shared filter into the ordinary one's key.
func TestUnsubscribingAShareLeavesTheOrdinarySubscriptionFed(t *testing.T) {
	h := start(t)
	c := connect(t, h, "both-then-one", true, false)
	c.Sub(t, "events/#", 1)
	c.Sub(t, "$share/g/events/#", 1)
	subscribed(t, c.C)

	if _, err := c.C.Unsubscribe(context.Background(), &paho.Unsubscribe{
		Topics: []string{"$share/g/events/#"},
	}); err != nil {
		t.Fatalf("unsubscribe: %v", err)
	}
	subscribed(t, c.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/after/1", "still fed")

	r, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the ordinary subscription received nothing after the shared one was " +
			"given up: saguin's index dropped it, so the consumer holds a live " +
			"subscription the broker will not feed and nothing says so")
	}
	if r.Payload != "still fed" {
		t.Fatalf("received %q", r.Payload)
	}
	// And exactly once: the shared subscription is gone, so the second copy
	// must not arrive.
	if extra, ok := c.Await(t, 500*time.Millisecond); ok {
		t.Errorf("a second copy arrived as %q on %q: the shared subscription was "+
			"unsubscribed and is still being fed", extra.Payload, extra.Topic)
	}
}

// RFC 0002 "Shared subscriptions" - invariant 1
//
// **The case that loses records silently if it is got wrong.** One client
// holding an ordinary durable subscription *and* a shared one over the same
// channel. The shared subscription must not widen what the durable one is
// served, and must not be fed through the durable one's path.
//
// The two subscriptions are deliberately different widths, because equal
// ones cannot tell the paths apart: the durable one is `events/keep/#` and
// the shared one is `events/#`. A record under `events/other/` therefore
// belongs to the shared group alone, and if saguin's index has recorded the
// shared filter against the channel, that record is *also* delivered by the
// pump - stamped, counted against the consumer's position, and matched
// against a filter the client never asked to be fed durably.
//
// **The label is what separates the paths.** saguin stamps every channel
// delivery it makes with `saguin-offset`; the substrate's shared delivery
// carries none. So "one copy, unstamped" is the whole assertion, and it
// fails in both directions - two copies if the shared filter was tracked,
// a stamped one if it was fed by the pump.
func TestASharedSubscriptionDoesNotWidenADurableOne(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/keep/1", "keep-1")
	p.Pub(t, "events/other/1", "other-1")

	c := connect(t, h, "both", false, false)
	c.Sub(t, "events/keep/#", 1)
	c.Sub(t, "$share/g/events/#", 1)

	// The durable replay, and only what its own filter matches. `other-1`
	// arriving here is the widening this test exists for.
	first, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the durable subscription replayed nothing, so nothing below is evidence")
	}
	if first.Payload != "keep-1" {
		t.Fatalf("the durable replay began with %q on %q, want keep-1: a shared "+
			"subscription has widened what the durable one is served",
			first.Payload, first.Topic)
	}
	if extra, ok := c.Await(t, time.Second); ok {
		t.Fatalf("the durable replay also served %q on %q: the shared filter was "+
			"recorded against the channel, so the pump is matching records against "+
			"it and moving this consumer's position over them",
			extra.Payload, extra.Topic)
	}

	// A live record only the shared filter matches. Exactly one copy, and
	// from the substrate rather than the pump.
	p.Pub(t, "events/other/2", "other-2")
	got, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the shared subscription received no live record, so this proved nothing")
	}
	if got.Payload != "other-2" {
		t.Fatalf("received %q, want other-2", got.Payload)
	}
	if off, stamped := got.User["saguin-offset"]; stamped {
		t.Errorf("the record arrived carrying saguin-offset=%q: it was delivered by "+
			"saguin's pump against this consumer's stored position, and a shared "+
			"subscription holds none", off)
	}
	if dup, ok := c.Await(t, time.Second); ok {
		t.Errorf("a second copy of the live record arrived as %q on %q: the client is "+
			"being fed once for the shared group and once for a durable subscription "+
			"whose filter does not match it", dup.Payload, dup.Topic)
	}

	// **And the durable position is still where its own acknowledgements
	// left it.** A reconnect replays nothing, which is what says the shared
	// traffic neither advanced it past keep-1 nor left it behind: a new
	// record arrives and the old one does not.
	c.Close()
	again := connect(t, h, "both", false, false)
	again.Sub(t, "events/keep/#", 1)
	if stale, ok := again.Await(t, time.Second); ok {
		t.Errorf("the resumed session was replayed %q on %q: its position moved "+
			"backwards over records it had already acknowledged", stale.Payload, stale.Topic)
	}
	p.Pub(t, "events/keep/2", "keep-2")
	next, ok := again.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the resumed session received no new record: its position was moved " +
			"past records it never saw, so nothing published now can reach it")
	}
	if next.Payload != "keep-2" {
		t.Fatalf("the resumed session received %q, want keep-2", next.Payload)
	}
}

// --- queue -------------------------------------------------------------

// RFC 0003 "`queue` - Delivery" and "Acknowledgement and return"
//
// The properties a worker needs to answer at all: Response Topic,
// Correlation Data, attempt number, and a Message ID to deduplicate on.
func TestQueueDeliverAndAck(t *testing.T) {
	h := start(t)
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/build", "job-1")

	r, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("worker received no job")
	}
	if r.Payload != "job-1" {
		t.Fatalf("payload: got %q", r.Payload)
	}
	if r.RespTopic != "$saguin/queue/jobs/response" {
		t.Fatalf("response topic: got %q", r.RespTopic)
	}
	if len(r.CorrData) == 0 {
		t.Fatal("no correlation data: the worker cannot answer")
	}
	if r.User["saguin-attempt"] != "1" {
		t.Fatalf("attempt: got %q, want 1", r.User["saguin-attempt"])
	}
	if r.User["saguin-id"] == "" {
		t.Fatal("no saguin-id: a consumer cannot deduplicate (invariant 8)")
	}

	w.Respond(t, r.RespTopic, "ack", r.CorrData)

	// Acknowledged work is not redelivered.
	if _, more := w.Await(t, visibility+time.Second); more {
		t.Fatal("an acknowledged job was redelivered")
	}
}

// RFC 0003 "`queue` - Attempts, timeout, and redelivery" - invariant 3
//
// The visibility timeout must fire on a worker that received the job and
// never acknowledged it at the application level, the redelivery must
// carry a different Delivery ID, and the superseded one must resolve
// nothing.
func TestQueueTimeoutRedelivers(t *testing.T) {
	h := start(t)
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/slow", "job-1")

	first, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("no first delivery")
	}

	second, ok := w.Await(t, visibility+3*time.Second)
	if !ok {
		t.Fatal("the job was never redelivered after the visibility timeout")
	}
	if second.Payload != first.Payload {
		t.Fatalf("redelivery payload changed: %q then %q", first.Payload, second.Payload)
	}
	if string(second.CorrData) == string(first.CorrData) {
		t.Fatal("redelivery reused the Delivery ID; a stale ack would resolve the new attempt (invariant 3)")
	}
	if second.User["saguin-attempt"] != "2" {
		t.Fatalf("redelivery attempt: got %q, want 2", second.User["saguin-attempt"])
	}
	// Invariant 8: identity is stable across redelivery.
	if second.User["saguin-id"] != first.User["saguin-id"] {
		t.Fatalf("Message ID changed on redelivery: %q then %q (invariant 8)",
			first.User["saguin-id"], second.User["saguin-id"])
	}

	// Invariant 3: the superseded Delivery ID resolves nothing.
	w.Respond(t, first.RespTopic, "ack", first.CorrData)
	third, ok := w.Await(t, visibility+3*time.Second)
	if !ok {
		t.Fatal("a superseded ack resolved the record: no further redelivery happened")
	}
	if third.Payload != first.Payload {
		t.Fatalf("unexpected payload after superseded ack: %q", third.Payload)
	}
}

// RFC 0003 "`queue` - Acknowledgement and return"
//
// return puts the job back immediately, without waiting for the deadline.
func TestQueueReturnIsImmediate(t *testing.T) {
	h := start(t)
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/flaky", "job-1")

	first, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("no delivery")
	}
	w.Respond(t, first.RespTopic, "return", first.CorrData)

	// Well inside the visibility timeout.
	if _, ok := w.Await(t, visibility-500*time.Millisecond); !ok {
		t.Fatal("a returned job was not redelivered promptly")
	}
}

// RFC 0003 "`queue` - Attempts, timeout, and redelivery"
//
// A worker that answers before its acknowledgement goes out must still
// burn an attempt. Paho sends the PUBACK when the receive handler returns,
// so a worker that returns the job from inside its handler returns it
// first - and counting the attempt only at PUBACK leaves it uncounted.
//
// The job then bounces between broker and worker for ever and never
// reaches the dead-letter channel: a poison message with no exit, and the
// redelivery loop is as fast as the network.
//
// Holding the handler open while the test sends the return is what makes
// that ordering certain rather than a race the test wins most of the time.
func TestReturnBeforeAcknowledgementStillBurnsAnAttempt(t *testing.T) {
	h := start(t)

	dlq := connect(t, h, "dlq-reader", true, false)
	dlq.Sub(t, "jobs/__dlq/#", 0)

	w := connect(t, h, "worker-flaky", true, false)
	hold := make(chan struct{})
	w.Mu.Lock()
	w.Hold, w.HoldPayload = hold, "job-bounced"
	w.Mu.Unlock()
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/bounced", "job-bounced")

	// Return each delivery from inside the handler, before it returns and
	// Paho acknowledges. maxAttempts of them must exhaust the record.
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		r, ok := w.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("attempt %d was never delivered", attempt)
		}
		w.Respond(t, r.RespTopic, "return", r.CorrData)
		w.Mu.Lock()
		next := make(chan struct{})
		w.Hold = next
		w.Mu.Unlock()
		close(hold) // release the handler; its PUBACK follows the return
		hold = next
	}
	close(hold)

	// The deadline is deliberately shorter than the visibility-timeout route
	// could manage - maxAttempts leases of `visibility` each. Given longer,
	// this test passes against its own defect: uncounted returns keep the job
	// bouncing, but a later delivery that is acknowledged and then left to
	// expire eventually dead-letters it anyway, by the wrong path.
	deadline := visibility - 200*time.Millisecond
	r, ok := dlq.Await(t, deadline)
	if !ok {
		t.Fatalf("a job returned %d times did not reach the dead-letter channel "+
			"within %s; returns that arrive before the acknowledgement are not "+
			"being counted, so it is redelivered for ever", maxAttempts, deadline)
	}
	if r.Payload != "job-bounced" {
		t.Fatalf("dlq payload: got %q", r.Payload)
	}
	if r.User["saguin-dlq-attempts"] != fmt.Sprint(maxAttempts) {
		t.Fatalf("dlq attempts: got %q, want %d", r.User["saguin-dlq-attempts"], maxAttempts)
	}
}

// RFC 0003 "`queue` - Dead-lettering", RFC 0002 "The dead-letter channel"
//
// Attempts exhausted moves the record to the derived dead-letter channel,
// which is an ordinary append channel a stock subscriber can read.
func TestQueueDeadLettersAfterMaxAttempts(t *testing.T) {
	h := start(t)

	dlq := connect(t, h, "dlq-reader", true, false)
	dlq.Sub(t, "jobs/__dlq/#", 0)

	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/doomed", "job-1")

	// Never acknowledge. Let every attempt time out.
	budget := time.Duration(maxAttempts+2) * (visibility + time.Second)
	r, ok := dlq.Await(t, budget)
	if !ok {
		t.Fatalf("nothing reached the dead-letter channel within %s", budget)
	}
	if r.Payload != "job-1" {
		t.Fatalf("dlq payload: got %q", r.Payload)
	}
	if r.User["saguin-dlq-reason"] != "attempts_exhausted" {
		t.Fatalf("dlq reason: got %q", r.User["saguin-dlq-reason"])
	}
	if r.User["saguin-dlq-attempts"] != fmt.Sprint(maxAttempts) {
		t.Fatalf("dlq attempts: got %q, want %d", r.User["saguin-dlq-attempts"], maxAttempts)
	}
	if r.User["saguin-dlq-channel"] != "jobs" {
		t.Fatalf("dlq origin: got %q", r.User["saguin-dlq-channel"])
	}

	// The job stops being redelivered once it is dead-lettered.
	drain(w)
	if _, more := w.Await(t, visibility+time.Second); more {
		t.Fatal("a dead-lettered job was redelivered")
	}
}

// RFC 0003 "Putting dead-lettered work back"
//
// **The document says a redrive is four lines of any MQTT client. This is
// those four lines.** Read the dead letter, take the `__dlq` level out of
// the topic, publish the payload back carrying the publisher's own
// properties and none of the `saguin-dlq-*` set, and a working consumer
// gets it.
//
// It is a test rather than a paragraph because the recipe is a claim about
// four separate behaviours - where the level is inserted, which properties
// survive the move, whether a publisher-set `saguin-id` is honoured on the
// way back, and whether the attempt count starts again - and a claim about
// behaviour is a thing to run. Three findings were a
// sentence of prose the code had stopped agreeing with.
func TestDeadLetteredWorkCanBePutBack(t *testing.T) {
	h := start(t)

	dlq := connect(t, h, "dlq-reader", true, false)
	dlq.Sub(t, "jobs/__dlq/#", 1)

	broken := connect(t, h, "worker-broken", true, false)
	broken.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, broken.C)

	// A job carrying the publisher's own identity and its own property,
	// which is what has to come back out the other end.
	p := connect(t, h, "producer", true, false)
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/j1", QoS: 1, Payload: []byte("work-1"),
		Properties: &paho.PublishProperties{User: paho.UserProperties{
			{Key: "tenant", Value: "acme"},
			{Key: "saguin-id", Value: "ID-ORIGINAL"},
		}},
	}); err != nil {
		t.Fatalf("publish the job: %v", err)
	}

	// Never acknowledged, so it exhausts its attempts.
	budget := time.Duration(maxAttempts+2) * (visibility + time.Second)
	dead, ok := dlq.Await(t, budget)
	if !ok {
		t.Fatalf("nothing reached the dead-letter channel within %s, so there is "+
			"nothing to put back and this run tested no redrive", budget)
	}
	dead.Ack()
	if dead.Topic != "jobs/__dlq/j1" {
		t.Fatalf("the dead letter arrived on %q, want jobs/__dlq/j1: the queue's "+
			"filter is jobs/#, so the level is inserted where the # begins",
			dead.Topic)
	}

	// The recipe: take the level out. The queue's filter ends in `#` at
	// level 1, so that is where the level sits.
	back := strings.Join(append([]string{"jobs"},
		strings.Split(dead.Topic, "/")[2:]...), "/")
	if back != "jobs/j1" {
		t.Fatalf("stripping the level gave %q, want jobs/j1", back)
	}

	// A worker that works this time.
	var mu sync.Mutex
	var done []string
	fixed := dialAt(t, h.Addr, h.Network, "worker-fixed", true, false, 0, 3600, 0, nil, nil)
	fixed.OnJob = func(payload string, answer func(string)) {
		mu.Lock()
		done = append(done, payload)
		mu.Unlock()
		answer("ack")
	}
	fixed.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, fixed.C)
	drain(broken)

	// **Publish it back carrying every property the dead letter had**, which
	// is the lazy thing a redriver would do and is the case worth testing.
	// The document says the failure metadata cannot ride along because
	// `saguin-` is reserved on a publish, so this copies the lot - including
	// the whole saguin-dlq- set - and the assertions below are what says the
	// broker refuses them rather than the redriver having been careful.
	var props paho.UserProperties
	for k, v := range dead.User {
		props = append(props, paho.UserProperty{Key: k, Value: v})
	}
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: back, QoS: 1, Payload: []byte(dead.Payload),
		Properties: &paho.PublishProperties{User: props},
	}); err != nil {
		t.Fatalf("redrive publish: %v", err)
	}

	deadline := time.Now().Add(10 * time.Second)
	for {
		mu.Lock()
		n := len(done)
		mu.Unlock()
		if n > 0 || time.Now().After(deadline) {
			break
		}
		time.Sleep(50 * time.Millisecond)
	}
	mu.Lock()
	defer mu.Unlock()
	if len(done) == 0 {
		t.Fatal("the redriven job never reached a worker, so the recipe RFC 0003 " +
			"gives does not put work back")
	}
	if done[0] != "work-1" {
		t.Errorf("the worker was given %q, want the original payload work-1", done[0])
	}

	// What the redriven delivery carried, which is the half of the recipe a
	// "did it arrive" check cannot see.
	var got received
	for _, r := range fixed.In {
		if r.Topic == back {
			got = r
		}
	}
	if got.Topic == "" {
		t.Fatal("the fixed worker's client kept no delivery on the redriven topic")
	}
	if got.User["saguin-id"] != "ID-ORIGINAL" {
		t.Errorf("the redriven job carries saguin-id %q, want ID-ORIGINAL: passing the "+
			"dead letter's identity back is what lets a consumer deduplicate across "+
			"the round trip (invariant 8)", got.User["saguin-id"])
	}
	if got.User["tenant"] != "acme" {
		t.Errorf("the redriven job carries tenant %q, want acme: the publisher's own "+
			"properties survive the move and the way back", got.User["tenant"])
	}
	if got.User["saguin-attempt"] != "1" {
		t.Errorf("the redriven job is on attempt %q, want 1: it is a new record and "+
			"its attempt count starts again, which is what the document promises",
			got.User["saguin-attempt"])
	}
	for k := range got.User {
		if strings.HasPrefix(k, "saguin-dlq-") {
			t.Errorf("the redriven job carries %q although the redrive above published "+
				"it as an ordinary client property: `saguin-` is reserved on a publish "+
				"and the broker drops it, which is what lets a redriver copy the whole "+
				"property set back without producing a job that reads as having failed "+
				"again", k)
		}
	}
}

// RFC 0002 "What each channel type admits - `queue`" - invariant 4
//
// Exactly one worker holds a record at a time. Every non-canonical
// subscription form is refused, because two spellings that both worked
// would be two populations of workers each taking a copy of every job.
func TestQueueRefusesNonCanonicalSubscriptions(t *testing.T) {
	h := start(t)
	c := connect(t, h, "worker", true, false)

	// Each refusal carries the code that describes what is wrong with it,
	// which needed a hook able to answer per filter. Before that every one
	// of these was 0x87, pointing a developer at their credentials rather
	// than at the shape of their filter.
	for _, tc := range []struct {
		filter string
		qos    byte
		want   byte
		why    string
	}{
		{"$saguin/queue/jobs/urgent", 1, 0x8F, "a level after the name: a channel name is one level"},
		{"$saguin/queue/jobs/#", 1, 0x8F, "straddles the work topic and the response topic"},
		{"$saguin/queue/#", 1, 0x8F, "every queue at once"},
		{"$saguin/queue/+", 1, 0x8F, "a wildcard where a channel name goes"},
		{"jobs/#", 1, 0x8F, "the queue's own filter: a broadcast consumer on a queue"},
		{"$saguin/queue/jobs", 0, 0x83, "QoS 0: no PUBACK to start a visibility timeout from"},
		// A name that is a channel of some other type. Both are *names*, and
		// neither is a queue - the dead-letter one is the trap the documents
		// invite, since they say failed work lands in `<queue>__dlq`.
		{"$saguin/queue/events", 1, 0x8F, "an append channel's name is not a queue's"},
		{"$saguin/queue/state", 1, 0x8F, "a latest channel's name is not a queue's"},
		{"$saguin/queue/jobs__dlq", 1, 0x8F, "the dead-letter channel's name, which is not where its records are"},
		{"$saguin/queue/nosuch", 1, 0x8F, "a name no channel has"},
	} {
		sa := c.Sub(t, tc.filter, tc.qos)
		if len(sa.Reasons) != 1 {
			t.Fatalf("%s: expected one reason code, got %v", tc.filter, sa.Reasons)
		}
		if sa.Reasons[0] <= 2 {
			t.Fatalf("%s was GRANTED (code %d) - %s (invariant 4)",
				tc.filter, sa.Reasons[0], tc.why)
		}
		if sa.Reasons[0] != tc.want {
			t.Errorf("%s refused with %#x, want %#x - %s", tc.filter, sa.Reasons[0], tc.want, tc.why)
		}
	}

	// And the client is still connected: a refusal says why rather than
	// closing the connection, which is what it had to do when a hook could
	// not answer per filter.
	select {
	case d := <-c.Gone:
		t.Fatalf("the broker disconnected a client for a refused subscription: %+v", d)
	default:
	}

	// The canonical form is granted.
	sa := c.Sub(t, "$saguin/queue/jobs", 1)
	if sa.Reasons[0] > 2 {
		t.Fatalf("the canonical queue subscription was refused: %#x", sa.Reasons[0])
	}
}

// RFC 0002 "What each channel type admits - `queue`" - invariant 4
//
// A QoS 2 request on the canonical form is granted at 1, never at 2. This
// harness offers exactly-once (`broker.qos2`), so the substrate's ceiling
// alone would answer "granted 2" - and the offer is sent at QoS 1 whatever
// the grant says (RFC 0003 "Delivery"), so an uncapped grant is one the
// delivery never honours. MQTT permits granting lower than was asked
// ([MQTT-3.8.4-8]); the SUBACK, the stored subscription and the delivery
// have to agree.
func TestQueueSubscriptionAtQoS2IsGrantedAtOne(t *testing.T) {
	h := start(t)
	w := connect(t, h, "worker-q2", true, false)

	sa := w.Sub(t, "$saguin/queue/jobs", 2)
	if len(sa.Reasons) != 1 {
		t.Fatalf("expected one reason code, got %v", sa.Reasons)
	}
	if sa.Reasons[0] != 1 {
		t.Fatalf("QoS 2 on the canonical form answered %#x, want 0x01: the offer "+
			"is sent at QoS 1, so any higher grant is one the delivery never honours",
			sa.Reasons[0])
	}

	// And the delivery agrees with the grant: the job arrives at QoS 1.
	p := connect(t, h, "producer-q2", true, false)
	p.Pub(t, "jobs/q2-grant", "j")
	job, ok := w.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("the worker granted at QoS 1 was never offered the job")
	}
	if job.QoS != 1 {
		t.Fatalf("the job arrived at QoS %d, want 1", job.QoS)
	}
}

// RFC 0003 "`queue` - States" - invariant 7
//
// A client refused for subscribing at QoS 0 is disconnected, but the
// server's topic index may still list its shared subscription. Selecting
// a worker from that index hands the record to a session that is gone -
// and a record in Delivering has no visibility deadline by design, so it
// is stranded permanently, with no worker holding it and no timer to
// notice. Workers must therefore be selected from saguin's own registry
// of live consumers.
func TestJobIsNotStrandedByADepartedSubscriber(t *testing.T) {
	h := start(t)

	// This one is refused: QoS 0 on a queue.
	ghost := connect(t, h, "ghost", true, false)
	_, _ = ghost.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "$saguin/queue/jobs", QoS: 0}},
	})
	subscribed(t, ghost.C)

	// A real worker, after the ghost.
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	// Several jobs, not one: the server picks among candidates at random,
	// so a single job would reach the live worker half the time and the
	// test would pass against the defect it exists to catch.
	const n = 8
	for i := 0; i < n; i++ {
		p.Pub(t, fmt.Sprintf("jobs/real/%d", i), fmt.Sprint(i))
	}

	seen := 0
	deadline := time.After(6 * time.Second)
	for seen < n {
		select {
		case r := <-w.Ch:
			seen++
			w.Respond(t, r.RespTopic, "ack", r.CorrData)
		case <-deadline:
			t.Fatalf("only %d of %d jobs reached the live worker; the rest went to a departed "+
				"session and are stranded in Delivering with no deadline to rescue them", seen, n)
		}
	}
}

// RFC 0003 "When a record is too large for a subscriber" - invariant 7
//
// The queue is the one delivery path saguin does not write itself: the
// delivery is injected, the server queues it on the worker's outbound
// channel, and a write that fails does so later in a goroutine that drops
// the error. So a job too large for its worker has to be caught before it
// is handed over, or nothing ever learns it was not delivered.
//
// Uncaught, the record holds a packet identifier and a slot of that
// worker's send quota, and no PUBACK ever starts its visibility deadline -
// so it is never redelivered, never dead-lettered, and never offered to a
// worker that could have done it. Measured before the fix: nothing in
// fifteen seconds, against a two second timeout and three attempts.
func TestQueueJobTooLargeForItsWorkerDisconnectsIt(t *testing.T) {
	const maxPacket = 512
	big := strings.Repeat("x", 4*maxPacket)

	h := start(t)
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	stopOps, err := h.B.ServeOperations(tcpOnly(ops), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(stopOps)

	// The only worker, and it cannot hold the job.
	narrow := connectMaxPacket(t, h, "narrow-worker", maxPacket)
	narrow.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, narrow.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/big", big)

	select {
	case d := <-narrow.Gone:
		if d.ReasonCode != 0x95 {
			t.Fatalf("disconnected with %#x, want 0x95 Packet too large", d.ReasonCode)
		}
	case r := <-narrow.Ch:
		t.Fatalf("the worker received a job above its Maximum Packet Size: %d bytes", len(r.Payload))
	case <-time.After(3 * time.Second):
		t.Fatal("a job larger than the worker's Maximum Packet Size neither reached it " +
			"nor disconnected it: the record is stranded in Delivering with no deadline " +
			"to rescue it and no attempt burnt, so nothing will ever look at it again")
	}

	// The job was not consumed by the attempt: a worker that can hold it
	// gets it, on its first attempt, because nothing was burnt.
	wide := connect(t, h, "wide-worker", true, false)
	wide.Sub(t, "$saguin/queue/jobs", 1)
	r, ok := wide.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("a worker with no bound never got the job: it is stranded rather than " +
			"back on the queue")
	}
	if r.Payload != big {
		t.Fatalf("wide worker got %d bytes, want %d", len(r.Payload), len(big))
	}
	if r.User["saguin-attempt"] != "1" {
		t.Fatalf("attempt %q, want 1 - a delivery the worker never received burnt an "+
			"attempt, so a job nobody can hold would dead-letter for the wrong reason",
			r.User["saguin-attempt"])
	}
	wide.Respond(t, r.RespTopic, "ack", r.CorrData)

	// **One delivery, not two.** The offer to the narrow worker was given
	// back before anybody held it, and counting it would put delivered_total
	// above what acknowledged, returned, redelivered and dead-lettered can
	// ever account for.
	if got := metricValue(t, ops, `saguin_queue_delivered_total{channel="jobs"}`); got != 1 {
		t.Errorf("saguin_queue_delivered_total is %v after one job reached one worker, want 1: "+
			"a hand-over the broker took back was counted as delivered", got)
	}
}

// RFC 0003 "`queue` - States" - invariant 7
//
// A record is offered to a worker only when that worker has room for it.
// Offering more than the live workers can hold strands the excess: the
// server registers each one in the worker's in-flight set, fires the hook
// that tells saguin a worker has it, and then withholds the packet because
// the worker's send quota is spent - and nothing resends it, because that
// happens only when a session resumes.
//
// The record is then Delivering with a worker that never received it. It has
// no visibility deadline by design, so it does not time out, is not
// redelivered, and never dead-letters; a second worker with room is not
// offered it either, because it is no longer available. Measured before the
// fix: four of six jobs vanished until the first worker's session ended.
func TestJobsBeyondAWorkersWindowAreNotStranded(t *testing.T) {
	const jobs = 6
	const window = 2

	h := start(t)

	// Receive Maximum 2, and manual acknowledgement that never comes: this
	// worker's in-flight window fills at two and stays full.
	full := connectRx(t, h, "worker-full", true, true, window)
	full.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, full.C)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= jobs; i++ {
		p.Pub(t, fmt.Sprintf("jobs/task/%d", i), fmt.Sprintf("job-%d", i))
	}
	if _, ok := full.Await(t, 3*time.Second); !ok {
		t.Fatal("the worker was offered nothing, so nothing here is about its window")
	}

	// The rest must still be available to a worker that has room.
	//
	// **And the worker that joins is the end marker for "one, not the
	// window".** Jobs are offered in offset order (RFC 0003 "Ordering"), so
	// its first fresh offer is job-2 unless the full worker was handed job-2
	// as well. A job whose lease ran out meanwhile comes back first, at a
	// later attempt, and is not the marker.
	spare := connect(t, h, "worker-spare", true, false)
	spare.Sub(t, "$saguin/queue/jobs", 1)

	seen := map[string]bool{}
	marked := false
	deadline := time.After(6 * time.Second)
	for len(seen) < jobs-1 {
		select {
		case r := <-spare.Ch:
			if !marked && r.User["saguin-attempt"] == "1" {
				marked = true
				if r.Payload != "job-2" {
					t.Fatalf("the worker that joined was first offered %s, want job-2 - the "+
						"next in offset order: the full worker took more than one", r.Payload)
				}
				// **One, not the window.** A worker holds one job from a queue
				// at a time (RFC 0003 "Delivery"), and a job whose PUBACK has
				// not come is still held - so the window of 2 is never reached
				// from this queue alone.
				if got := full.Count(); got != 1 {
					t.Fatalf("the worker received %d jobs with a window of %d and no PUBACK sent; "+
						"a worker holds one job from a queue at a time", got, window)
				}
			}
			seen[r.Payload] = true
			spare.Respond(t, r.RespTopic, "ack", r.CorrData)
		case <-deadline:
			t.Fatalf("a worker with room received %d of the %d jobs the full worker "+
				"was not holding; the rest are stranded in Delivering with no deadline "+
				"to rescue them and no worker holding them", len(seen), jobs-1)
		}
	}
}

// RFC 0003 "Delivery"
//
// **A worker holds one job from each queue at a time, and the queues do not
// wait on each other.** A job is held from its offer until the worker answers
// it, its visibility timeout runs out, or the worker goes; until then that
// worker is offered nothing more from that queue, whatever its Receive
// Maximum. A second queue is a second, independent hold.
//
// It used to be the transport window: a worker with no Receive Maximum was
// offered 10 of 10 jobs at once, measured, and one withholding its PUBACK
// held as many as its window.
//
// **One to four workers, on one queue and on two**, every worker subscribed
// to every queue. Two phases, because the rule has two halves:
//
//   - Nobody answers. Every worker must hold exactly one job from each queue
//     and be offered nothing more while work is still waiting, which proves
//     the hold and that one queue's hold does not stop the other's.
//   - Everybody answers at once, one job in five returned on its first
//     attempt. No worker may be offered a job from a queue while it holds an
//     unanswered one from it, every job is acknowledged exactly once, and the
//     drain is timed.
//
// **Receive Maximum is left unset**, so the window is 65,535 and cannot be
// what holds a worker to one.
//
// **The time is the answer path.** Offers run on a 200ms tick, so workers fed
// only by the tick take one job each per queue per tick: one worker on 36
// offers takes about seven seconds. An answer has to offer the next job at
// once.
func TestQueueWorkersHoldOneJobFromEachQueueAtATime(t *testing.T) {
	for _, queues := range []int{1, 2} {
		for workers := 1; workers <= 4; workers++ {
			t.Run(fmt.Sprintf("%d workers on %d queues", workers, queues), func(t *testing.T) {
				holdOneJobPerQueue(t, workers, queues)
			})
		}
	}
}

// RFC 0003 "Delivery"
//
// **A worker at Receive Maximum 1 is offered its next job when its window
// opens, not on the next tick.** Paho answers a job from its handler and
// sends the PUBACK after the handler returns, so the answer frees the worker
// of the job while the job's packet still fills its window, and the offer
// the answer asks for finds no room. The PUBACK is what opens the window, so
// it has to offer the next job too.
//
// Measured with examples/support/worker at -window 1 and -work 0s before it
// did: 300 jobs in 59.9s, 5.0 a second, which is the 200ms tick.
func TestAWorkerAtReceiveMaximumOneIsOfferedTheNextJobWhenItsWindowOpens(t *testing.T) {
	const backlog = 30

	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= backlog; i++ {
		p.Pub(t, fmt.Sprintf("jobs/task/%d", i), fmt.Sprintf("job-%d", i))
	}

	// Manual PUBACK, sent after the answer, which is Paho's own order.
	w := connectRx(t, h, "worker", true, true, 1)
	began := time.Now()
	w.Sub(t, "$saguin/queue/jobs", 1)
	for n := 0; n < backlog; n++ {
		r, ok := w.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("the worker stopped at %d of %d jobs", n, backlog)
		}
		w.Respond(t, r.RespTopic, "ack", r.CorrData)
		r.Ack()
	}
	// The tick alone takes six seconds over thirty jobs.
	if took := time.Since(began); took > 2*time.Second {
		t.Errorf("a worker at Receive Maximum 1 that answers before it acknowledges took "+
			"%v over %d jobs: its next job waited for the tick rather than for its window "+
			"to open", took, backlog)
	}
}

// RFC 0003 "Delivery"
//
// **A busy worker is not offered jobs that go straight back.** The selection
// passes over a worker that holds a job, so a job offered while every worker
// is busy finds nobody and is returned to the queue. That spends no attempt
// and starts no backoff, but it mints a Delivery ID, writes two state changes
// - a transaction each on SQLite - and logs a line, for every waiting job on
// every 200ms tick while the workers stay busy. The offer counts only the
// workers that hold nothing, so it never starts one.
//
// **The log is the instrument, and it is proved to be reading.** The worker
// leaves at the end, and the job it held must be seen going back. Read at
// DEBUG, where a job's return is logged (TestNothingPerRecordLogsAtInfo).
func TestABusyWorkerIsNotOfferedJobsThatGoStraightBack(t *testing.T) {
	var mu sync.Mutex
	bounced, departed := 0, 0
	h := startLoggingDebug(t, func(line string) {
		if !strings.Contains(line, "returned to available") {
			return
		}
		mu.Lock()
		defer mu.Unlock()
		switch {
		case strings.Contains(line, "no live worker with room and a grant"):
			bounced++
		case strings.Contains(line, "worker disconnected"):
			departed++
		}
	})

	w := connect(t, h, "busy-worker", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 5; i++ {
		p.Pub(t, fmt.Sprintf("jobs/task/%d", i), fmt.Sprintf("job-%d", i))
	}
	if _, ok := w.Await(t, 3*time.Second); !ok {
		t.Fatal("the worker was offered nothing, so the quiet below proves nothing")
	}

	// Five ticks holding one job with four waiting, inside the harness's
	// two-second visibility timeout, so nothing is taken back meanwhile.
	ticked(t, h, 5)
	mu.Lock()
	got := bounced
	mu.Unlock()
	if got != 0 {
		t.Errorf("%d jobs were offered while the only worker held one, and went straight "+
			"back to the queue for want of anyone to take them", got)
	}

	w.Close()
	if !waitUntil(3*time.Second, func() bool {
		mu.Lock()
		defer mu.Unlock()
		return departed > 0
	}) {
		t.Fatal("the job the worker held was not seen going back when it left, so this " +
			"reader sees no release at all and the zero above is not evidence")
	}
}

// RFC 0003 "`queue` - States" - invariant 7
//
// One worker, declaring a Receive Maximum, drains a backlog several times
// larger than it. That is the case a queue exists for, and it did not work.
//
// Two things had to be true for it to. The substrate was destroying its own
// delivery bookkeeping whenever a worker's answer carried a packet
// identifier the server had also used - the client's identifiers and the
// server's are independent spaces (MQTT-2.2.1), and both count from 1, so a
// worker answering every job collided on nearly every one. Each collision
// cost a slot of send quota that never came back, so the worker was offered
// nothing more once the quota reached zero: it stopped at twice its window,
// 22 of 300 against a real broker. That is fixed upstream
// (mochi-mqtt/server#519) and carried on the fork.
//
// And a record the wire never carried is returned to the queue by
// `returnUnsent`, since a Delivering record has no visibility deadline to
// rescue it (invariant 7). That is the backstop rather than the cure - with
// the substrate correct it does not fire at all, measured over 300 jobs -
// and it is what keeps a record from being stranded by any future way of
// registering a delivery that is never sent.
//
// **The backlog has to be several times the window, and both numbers are
// written out rather than derived from each other.** Below about twice the
// window the worker drains everything before it can starve, and the test
// then passes against the defect it was written for - which is how four
// separate measurements of this went wrong, one at a window of 100 against
// 60 jobs, one at 20 against 60, and one at 10 against 100 in a shape that
// let Paho acknowledge before the answer went out: it stopped at 94 on one
// run and drained on the next.
func TestAWorkerWithAWindowDrainsABacklogSeveralTimesIt(t *testing.T) {
	const backlog = 100
	const window = 10

	h := start(t)

	// Manual acknowledgement with the PUBACK sent after the job is answered:
	// what a worker doing actual work looks like, and the shape
	// examples/support/worker has. It is also the shape that made the defect
	// deterministic - twelve of a hundred, five runs out of five.
	w := connectRx(t, h, "worker", true, true, window)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= backlog; i++ {
		p.Pub(t, fmt.Sprintf("jobs/task/%d", i), fmt.Sprintf("job-%d", i))
	}

	// Idle rather than total, so a worker that has stopped being offered
	// work is reported as "stopped at n" rather than as a test that ran out
	// of time. The two look identical from a total deadline and only one of
	// them is this defect. Five seconds is twice the harness's visibility
	// timeout, so anything the queue was going to redeliver has had its
	// chance too.
	seen := map[string]int{}
	for len(seen) < backlog {
		select {
		case r := <-w.Ch:
			seen[r.Payload]++
			w.Respond(t, r.RespTopic, "ack", r.CorrData)
			r.Ack()
		case <-time.After(5 * time.Second):
			t.Fatalf("the worker stopped at %d of %d jobs with a window of %d; a worker "+
				"that acknowledges everything is offered work until the queue is empty, "+
				"and stopping at about twice the window is the send quota being spent "+
				"and never returned", len(seen), backlog, window)
		}
	}
}

// RFC 0002 "What each channel type admits - `append`", "Shared
// subscriptions"
//
// A shared subscription on an `append` channel is granted and is served
// new records only: no replay of what was there before it arrived, and
// none of the channel's labels.
func TestASharedSubscriptionOnAppendGetsLiveRecordsAndNoReplay(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/before/1", "before")

	c := connect(t, h, "reader", true, false)
	sa := c.Sub(t, "$share/analytics/events/#", 1)
	if sa.Reasons[0] > 2 {
		t.Fatalf("a shared subscription on an append channel was refused %#x: `$share` "+
			"is MQTT's and saguin refuses it for nothing it reaches", sa.Reasons[0])
	}

	// **The live record is the end marker.** A replay would reach the
	// subscriber before a record published after it subscribed - once the
	// replay that runs after the SUBACK has returned, which the round trip
	// says.
	subscribed(t, c.C)
	p.Pub(t, "events/after/1", "after")
	select {
	case r := <-c.Ch:
		if r.Payload != "after" {
			t.Fatalf("the shared subscriber was replayed %q = %q before the live record: a "+
				"shared subscription holds no position and is served new records only",
				r.Topic, r.Payload)
		}
		for k := range r.User {
			if strings.HasPrefix(k, "saguin-") {
				t.Errorf("the shared delivery carries %q: a shared subscription is "+
					"served live MQTT and gets no offsets", k)
			}
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the shared subscriber received no live record: a shared subscription " +
			"on an append channel is served new records, and receiving nothing at all " +
			"is the failure a refusal used to make loud")
	}
}

// RFC 0003 "When a record is too large for a subscriber", RFC 0002 "Shared
// subscriptions": a record too large for a shared member passes that member
// over - it is not disconnected, and nothing is counted lost - and reaches a
// member it fits. The trials offer the large record to each member first. A
// channel's group and a broadcast group alike.
func TestARecordTooLargeForASharedMemberIsPassedOverAndReachesAnother(t *testing.T) {
	const maxPacket = 512
	big := strings.Repeat("x", 4*maxPacket)
	for _, k := range []string{"events", "news"} {
		for trial := 0; trial < 4; trial++ {
			t.Run(fmt.Sprintf("%s/trial %d", k, trial), func(t *testing.T) {
				h := start(t)
				group := "$share/g/" + k + "/#"
				narrow := connectMaxPacket(t, h, "narrow", maxPacket)
				narrow.Sub(t, group, 1)
				wide := connect(t, h, "wide", true, false)
				wide.Sub(t, group, 1)
				p := connect(t, h, "producer", true, false)
				// The group's rotation moves one member a record, so the
				// trials between them offer the large one to each member first.
				for i := 0; i < trial; i++ {
					p.Pub(t, fmt.Sprintf("%s/small/%d", k, i), "small")
				}
				p.Pub(t, k+"/a/1", big)

				deadline := time.After(3 * time.Second)
			wait:
				for {
					select {
					case r := <-wide.Ch:
						if r.Payload == big {
							break wait
						}
					case <-deadline:
						t.Fatal("the record never reached the member it fits: it was lost for the group")
					}
				}
				select {
				case d := <-narrow.Gone:
					t.Fatalf("the narrow member was disconnected (%#x): a member the record does not "+
						"fit is passed over", d.ReasonCode)
				case <-time.After(300 * time.Millisecond):
				}
				for _, r := range narrow.All() {
					if r.Payload == big {
						t.Fatal("the narrow member was sent a record larger than its Maximum Packet Size")
					}
				}
			})
		}
	}
}

// Invariant 16, for a queue: **a worker too small for a job is hung up on by
// a goroutine of its own**, as a shared member is. The worker is chosen where
// the queue's jobs are offered, and a DISCONNECT written there waits for the
// lock a deaf worker's write loop holds - so the queue's next job, for a
// worker that is reading, waited for limits.write_timeout, here thirty
// seconds so that the deadline cannot be what rescues it. The third party is
// the assertion: the publisher is not held either way.
func TestADeafWorkerTooSmallForAJobDoesNotHoldTheQueue(t *testing.T) {
	brokertest.WriteDeadline = 30 * time.Second
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })
	var picked atomic.Int32
	brokertest.LogTo = func(l string) {
		if strings.Contains(l, "a job is larger than this worker's Maximum Packet Size") {
			picked.Add(1)
		}
	}
	t.Cleanup(func() { brokertest.LogTo = nil })
	h := startOn(t, "tcp")

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	send := func(pk pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = pk
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	maxPacket := uint32(512)
	send(&pahopackets.Connect{
		ClientID: "a-deaf-worker", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
		Properties: &pahopackets.Properties{MaximumPacketSize: &maxPacket},
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	for i, filter := range []string{"$saguin/queue/jobs", "news/#"} {
		qos := byte(1)
		if filter == "news/#" {
			qos = 0
		}
		send(&pahopackets.Subscribe{
			PacketID:      uint16(i + 1),
			Subscriptions: []pahopackets.SubOptions{{Topic: filter, QoS: qos}},
		}, pahopackets.SUBSCRIBE)
		if sa, err := pahopackets.ReadPacket(conn); err != nil {
			t.Fatalf("read the SUBACK: %v", err)
		} else if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got > 2 {
			t.Fatalf("the subscription to %s was refused 0x%02X", filter, got)
		}
	}
	// From here that socket is never read again. Broadcasts that fit are
	// sent until its write loop holds its lock in a write that cannot finish.
	p := connect(t, h, "impatient-publisher", true, false)
	fits := strings.Repeat("x", 400)
	for i := 0; i < 20000; i++ {
		ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
		ack, err := p.C.Publish(ctx, &paho.Publish{Topic: "news/fits", QoS: 1, Payload: []byte(fits)})
		cancel()
		if ack == nil {
			t.Fatalf("filling publish %d went unacknowledged: %v", i, err)
		}
	}
	deaf, ok := h.Srv.Clients.Get("a-deaf-worker")
	next := packets.Packet{FixedHeader: packets.FixedHeader{Type: packets.Publish},
		TopicName: "news/fits", Payload: []byte(fits)}
	if !ok || deaf.Closed() || deaf.OutboundHasRoom(next) {
		t.Fatalf("the deaf worker's queue is not full (known %v, closed %v), so nothing here "+
			"holds its lock and this exercised nothing", ok, ok && deaf.Closed())
	}

	// The job too large for it, while it is the queue's only worker. It is
	// chosen once, and then for nothing while it closes: chosen again, the
	// job went back to it on every offer until its write gave up.
	p.Pub(t, "jobs/big", strings.Repeat("x", 4*int(maxPacket)))
	ticked(t, h, 5)
	if n := picked.Load(); n != 1 {
		t.Errorf("the deaf worker was chosen for the job too large for it %d times in five "+
			"ticks, want 1: a worker being hung up on is chosen for nothing", n)
	}
	if deaf.Closed() {
		t.Fatal("the deaf worker closed within five ticks, so nothing here held its lock")
	}

	// A worker that reads, and can hold the job, is offered it at once: the
	// queue's offers are not waiting on the deaf worker's socket.
	big := strings.Repeat("x", 4*int(maxPacket))
	live := connect(t, h, "b-live-worker", true, false)
	start := time.Now()
	live.Sub(t, "$saguin/queue/jobs", 1)
	for {
		select {
		case r := <-live.Ch:
			if r.Payload != big {
				continue
			}
			if took := time.Since(start); took > 3*time.Second {
				t.Errorf("the reading worker was offered the job after %v, with "+
					"limits.write_timeout at %v: the deaf worker's DISCONNECT is being "+
					"written where the queue's jobs are offered", took, brokertest.WriteDeadline)
			}
			return
		case <-time.After(8 * time.Second):
			t.Fatalf("the reading worker was not offered the job within 8s, with "+
				"limits.write_timeout at %v: the queue is held by the deaf worker's socket "+
				"(deaf worker closed: %v)", brokertest.WriteDeadline, deaf.Closed())
		}
	}
}

// RFC 0002 "Shared subscriptions"
//
// **A publisher cannot forge a channel's labels into a shared delivery.**
// The stored record has the reserved prefix stripped so a publisher cannot
// claim to be the broker; the packet the substrate fans out to a shared
// group is the one the publisher sent, so it is stripped there too.
func TestASharedDeliveryCarriesNoForgedLabels(t *testing.T) {
	h := start(t)
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "$share/analytics/events/#", 1)
	subscribed(t, c.C)

	p := connect(t, h, "liar", true, false)
	p.PubProps(t, "events/forged/1", "x", &paho.PublishProperties{
		User: paho.UserProperties{
			{Key: "saguin-offset", Value: "999"},
			{Key: "mine", Value: "kept"},
		},
	})

	select {
	case r := <-c.Ch:
		if v, ok := r.User["saguin-offset"]; ok {
			t.Errorf("the shared delivery carries saguin-offset=%q, which the publisher "+
				"set: a consumer has no way to tell a forged label from one the broker "+
				"stamped", v)
		}
		if r.User["mine"] != "kept" {
			t.Errorf("the publisher's own property was dropped: %v", r.User)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the shared subscriber received nothing")
	}
}

// RFC 0003 "The guarantee, in one table" - invariant 4
//
// Two workers competing: each job goes to exactly one of them.
func TestQueueCompetingConsumers(t *testing.T) {
	h := start(t)
	w1 := connect(t, h, "worker-1", true, false)
	w2 := connect(t, h, "worker-2", true, false)
	w1.Sub(t, "$saguin/queue/jobs", 1)
	w2.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w1.C)
	subscribed(t, w2.C)

	p := connect(t, h, "producer", true, false)
	const n = 6
	for i := 0; i < n; i++ {
		p.Pub(t, fmt.Sprintf("jobs/task/%d", i), fmt.Sprint(i))
	}

	seen := map[string]int{}
	deadline := time.After(5 * time.Second)
	for len(seen) < n {
		select {
		case r := <-w1.Ch:
			seen[r.Payload]++
			w1.Respond(t, r.RespTopic, "ack", r.CorrData)
		case r := <-w2.Ch:
			seen[r.Payload]++
			w2.Respond(t, r.RespTopic, "ack", r.CorrData)
		case <-deadline:
			t.Fatalf("only %d of %d jobs were delivered: %v", len(seen), n, seen)
		}
	}

	for payload, times := range seen {
		if times != 1 {
			t.Fatalf("job %q was delivered %d times to competing consumers (invariant 4)", payload, times)
		}
	}
	if got := w1.Count() + w2.Count(); got != n {
		t.Fatalf("total deliveries %d, want %d", got, n)
	}
}

// RFC 0001 "Both protocols, and what each one gets", RFC 0002 "Which
// versions may connect"
//
// **A 3.1.1 CONNECT is admitted, and that is what the binary does.** This
// test and the guard beside it were each other's opposite until the gate
// moved: one asserted the refusal, the other held three RFC paragraphs
// saying they described a broker that did not exist yet. Both changed in
// the commit that opened the gate, which is exactly what the guard was
// built to force - a specification ahead of its binary is the one kind of
// stale nobody notices, and it stayed marked as such for as long as it was
// true and not one commit longer.
func TestMQTT311IsAdmitted(t *testing.T) {
	if !threeOneOneAdmitted(t) {
		t.Fatal(`an MQTT 3.1.1 client was refused by a default broker, and ` +
			`broker.mqtt.min_protocol_version defaults to "3.1.1"`)
	}
}

// RFC 0001, RFC 0002, RFC 0003
//
// **Nothing may still say the binary refuses 3.1.1**, now that it does not.
// The three paragraphs this replaces were removed with the gate; this is
// what stops one coming back, and what would have failed had the gate moved
// without them.
func TestNoRFCStillSaysThreeOneOneIsUnreachable(t *testing.T) {
	if !threeOneOneAdmitted(t) {
		t.Fatal("the gate is shut, so this check is about the wrong broker")
	}
	stale := []string{
		"**Not true of the binary yet.**",
		"**The binary does not accept this key yet.**",
		"**No 3.1.1 client can reach the broker yet.**",
	}
	rfcs, err := filepath.Glob(filepath.Join("..", "..", "docs", "rfcs", "*.md"))
	if err != nil || len(rfcs) == 0 {
		t.Fatalf("glob the RFCs: %v (%d found)", err, len(rfcs))
	}
	for _, path := range rfcs {
		md, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("read %s: %v", path, err)
		}
		for _, s := range stale {
			if strings.Contains(string(md), s) {
				t.Errorf("%s still carries %q, and a 3.1.1 client can now connect",
					filepath.Base(path), s)
			}
		}
	}
	t.Logf("%d RFCs checked", len(rfcs))
}

// RFC 0002 "Which versions may connect"
//
// **The earlier promise is one line away**, which is the whole reason the
// key exists: a deployment wanting only MQTT 5 in the door writes `5` and
// has it back. Driven at a socket rather than read, because a key that
// parses and changes nothing is the failure this is for.
func TestMinProtocolVersionFiveTurnsThreeOneOneAway(t *testing.T) {
	five := config.ProtocolVersion("5")
	if got := (config.MQTT{MinProtocolVersion: &five}).MinProtocol(); got != 5 {
		t.Fatalf(`min_protocol_version "5" resolves to %d, want 5`, got)
	}
	if got := (config.MQTT{}).MinProtocol(); got != 4 {
		t.Fatalf("an absent min_protocol_version resolves to %d, want 4 - the default "+
			"admits 3.1.1", got)
	}

	brokertest.OnlyFive = true
	t.Cleanup(func() { brokertest.OnlyFive = false })
	h := startOn(t, "tcp")
	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	if _, err := conn.Write([]byte{
		0x10, 0x0f, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, 0x02, 0x00, 0x3c,
		0x00, 0x03, 'o', 'l', 'd',
	}); err != nil {
		t.Fatalf("write: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	buf := make([]byte, 4)
	if _, err := io.ReadFull(conn, buf); err != nil {
		t.Logf("refused by closing the connection: %v", err)
		return
	}
	if buf[0] == 0x20 && buf[3] == 0x00 {
		t.Fatal("a 3.1.1 client was admitted by a broker configured MQTT 5 only")
	}
	t.Logf("refused with return code %#x", buf[3])
}

// RFC 0002 "Configuration"
//
// The broker is the same broker over a Unix socket as over TCP: nothing
// above the listener knows the difference, and every channel behaves
// identically.
//
// It matters on an edge box where the broker and its consumers share a
// machine - no TCP stack in the path, no port to firewall, and the socket
// file's permissions become the access control.
func TestUnixSocketListener(t *testing.T) {
	h := startOn(t, "unix")

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/orders/1", "over-a-socket")
	p.Pub(t, "state/device/1/temp", "20")
	time.Sleep(300 * time.Millisecond)

	// append replays to a consumer that did not exist yet...
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "events/#", 1)
	if r, ok := c.Await(t, 3*time.Second); !ok || r.Payload != "over-a-socket" {
		t.Fatalf("append over a unix socket: got %q ok=%v", r.Payload, ok)
	}

	// ...and latest still serves current state.
	s := connect(t, h, "dashboard", true, false)
	s.Sub(t, "state/#", 1)
	if r, ok := s.Await(t, 3*time.Second); !ok || r.Payload != "20" {
		t.Fatalf("latest over a unix socket: got %q ok=%v", r.Payload, ok)
	}

	// A queue subscription is refused for the same reason it is over TCP.
	w := connect(t, h, "worker", true, false)
	if sa := w.Sub(t, "jobs/#", 1); sa.Reasons[0] <= 2 {
		t.Fatalf("a non-canonical queue subscription was granted over a unix socket: %#x",
			sa.Reasons[0])
	}
}

// RFC 0002 "Publishing"
//
// The bounds are enforced against what the client actually sent, and the
// PUBACK says which bound was crossed. A publish that is refused is also
// not stored - a record admitted to the log after its refusal would be
// replayed to every later subscriber.
func TestPublishBoundsAreEnforced(t *testing.T) {
	h := start(t)
	c := connect(t, h, "producer", true, false)

	// Paho reports a non-success PUBACK as an error and still hands back
	// the acknowledgement, which is the thing under test here.
	code := func(t testing.TB, p *paho.Publish) byte {
		t.Helper()
		ack, err := c.C.Publish(context.Background(), p)
		if ack == nil {
			t.Fatalf("no PUBACK for %s: %v", p.Topic, err)
		}
		return ack.ReasonCode
	}

	long := "events/" + strings.Repeat("x", limits.MaxTopicLength)
	if got := code(t, &paho.Publish{Topic: long, QoS: 1, Payload: []byte("x")}); got != 0x90 {
		t.Fatalf("an over-long topic answered 0x%02X, want 0x90 Topic Name invalid", got)
	}

	many := &paho.PublishProperties{}
	for i := 0; i <= limits.MaxHeaderCount; i++ {
		many.User = append(many.User, paho.UserProperty{Key: "k", Value: "v"})
	}
	if got := code(t, &paho.Publish{
		Topic: "events/many", QoS: 1, Payload: []byte("x"), Properties: many,
	}); got != 0x97 {
		t.Fatalf("too many headers answered 0x%02X, want 0x97 Quota exceeded", got)
	}

	big := &paho.PublishProperties{User: paho.UserProperties{
		{Key: "k", Value: strings.Repeat("v", limits.MaxHeaderBytes)},
	}}
	if got := code(t, &paho.Publish{
		Topic: "events/big", QoS: 1, Payload: []byte("x"), Properties: big,
	}); got != 0x97 {
		t.Fatalf("oversized headers answered 0x%02X, want 0x97 Quota exceeded", got)
	}

	// Nothing refused above reached the log.
	c.Pub(t, "events/ok", "kept")
	sub := connect(t, h, "reader", true, false)
	sub.Sub(t, "events/#", 1)
	got, ok := sub.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("the accepted record never arrived")
	}
	if string(got.Payload) != "kept" {
		t.Fatalf("first replayed record is %q, want the only accepted one", got.Payload)
	}
	if n := sub.Count(); n != 1 {
		t.Fatalf("%d records replayed; a refused publish was stored", n)
	}
}

// RFC 0002 "Configuration"
//
// A browser cannot open a TCP socket, so MQTT over WebSocket is the only
// way a dashboard reaches the broker at all. It is the same broker: the
// channel rules hold, and nothing above the listener knows the framing
// changed.
func TestWebSocketListener(t *testing.T) {
	h := startOn(t, "ws")

	p := connect(t, h, "ws-producer", true, false)
	p.Pub(t, "events/ws", "over a websocket")

	c := connect(t, h, "ws-consumer", true, false)
	c.Sub(t, "events/#", 1)

	got, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("nothing arrived over the websocket")
	}
	if got.Payload != "over a websocket" {
		t.Fatalf("payload %q", got.Payload)
	}

	// **What a filter reaches is a broker rule, not a transport one**, and
	// the queue is the half of it that must hold whatever the framing is: a
	// wildcard is served the append channel and never the queue's work.
	w := connect(t, h, "ws-wildcard", true, false)
	w.Sub(t, "#", 1)
	p.Pub(t, "events/again", "reaches a wildcard")
	p.Pub(t, "jobs/ws", "does not")

	// Two, not one: `events/ws` was published before this subscriber existed
	// and an append channel replays a fresh consumer from its floor, which is
	// what an append channel promises and is now what `#` gets.
	seen := map[string]string{}
	for range 2 {
		r, ok := w.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("a `#` subscriber over a websocket was served %d append records, want 2: %v",
				len(seen), seen)
		}
		seen[r.Topic] = r.Payload
	}
	if seen["events/ws"] != "over a websocket" || seen["events/again"] != "reaches a wildcard" {
		t.Fatalf("a `#` subscriber received %v", seen)
	}
	if extra, more := w.Await(t, 500*time.Millisecond); more {
		t.Fatalf("a `#` subscriber over a websocket also received %q on %q - a wildcard "+
			"reached a queue", extra.Payload, extra.Topic)
	}
}

// --- restart -----------------------------------------------------------

// Invariants 9, 14 and 15, from the wire.
//
// The broker-level tests for these reach into the store, so they cannot
// see what a client actually receives - a regression that dropped a
// consumer's position, or redelivered a record it had acknowledged, would
// pass every one of them. This one stops a broker and starts another on
// the same directory, which is what an operator does, and then asks a
// stock Paho client what it gets.
func TestChannelsSurviveARestart(t *testing.T) {
	dir := t.TempDir()
	h := startDurable(t, dir)
	ops := operationsAt(t, h)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}
	p.Pub(t, "state/temp", "21.5")
	p.Pub(t, "jobs/build", "job-a")

	// A consumer that acknowledges the first two records and not the
	// third. Its position is the lowest it has not acknowledged, so it
	// must come back at the third and not at the first.
	reader := connect(t, h, "reader", false, true)
	reader.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := reader.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("before the restart: expected record %d, got nothing", i)
		}
		if i < 3 {
			r.Ack()
		}
	}

	// A worker takes the job at the transport level and never answers, so
	// the record is leased with a visibility deadline running when the
	// broker stops.
	worker := connect(t, h, "worker-1", true, false)
	worker.Sub(t, "$saguin/queue/jobs", 1)
	first, ok := worker.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("before the restart: the worker got no job")
	}
	if first.User["saguin-attempt"] != "1" {
		t.Fatalf("before the restart: attempt %q, want 1", first.User["saguin-attempt"])
	}
	awaitLeased(t, ops, "jobs", first)

	h.Stop()
	h2 := startDurable(t, dir)

	// The consumer resumes where it stopped. Paho gives a restarted broker
	// no session, so this is saguin's stored position and nothing else.
	reader2 := connect(t, h2, "reader", false, false)
	reader2.Sub(t, "events/#", 1)
	r, ok := reader2.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the restart: the consumer received nothing, so its position was lost forwards")
	}
	if r.Payload != "order-3" {
		t.Fatalf("after the restart: the consumer resumed at %q, want order-3 - "+
			"it is replaying records it had already acknowledged", r.Payload)
	}
	if extra, more := reader2.Await(t, 500*time.Millisecond); more {
		t.Fatalf("after the restart: the consumer also received %q", extra.Payload)
	}

	// A consumer that never existed before the restart reads the channel
	// whole, so the records are there and it is only the position that
	// moved.
	fresh := connect(t, h2, "fresh", true, false)
	fresh.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := fresh.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("after the restart: a fresh consumer expected record %d, got nothing", i)
		}
		if want := fmt.Sprintf("order-%d", i); r.Payload != want {
			t.Fatalf("after the restart: a fresh consumer got %q, want %q", r.Payload, want)
		}
		if r.User["saguin-offset"] != fmt.Sprint(i) {
			t.Fatalf("after the restart: offset %q, want %d", r.User["saguin-offset"], i)
		}
	}

	// Current state survives, and a new subscriber is sent it.
	st := connect(t, h2, "state-reader", true, false)
	st.Sub(t, "state/#", 1)
	if r, ok := st.Await(t, 2*time.Second); !ok || r.Payload != "21.5" {
		t.Fatalf("after the restart: current state is %q ok=%v, want 21.5", r.Payload, ok)
	}

	// Invariant 15. Closing the server disconnects the worker, which
	// returns the record to available before the snapshot is written, so a
	// graceful shutdown never stores a lease in the first place - the
	// guard against restoring one is in RestoreQueue and is tested there.
	// What this pins is the wire behaviour either way: the job is handed
	// out again well inside the visibility timeout rather than after it,
	// and its attempt count survived, so it still dead-letters rather than
	// starting over.
	worker2 := connect(t, h2, "worker-2", true, false)
	worker2.Sub(t, "$saguin/queue/jobs", 1)
	again, ok := worker2.Await(t, visibility/2)
	if !ok {
		t.Fatalf("after the restart: no job within %s, so a lease from before the restart is still running",
			visibility/2)
	}
	if again.Payload != "job-a" {
		t.Fatalf("after the restart: job %q, want job-a", again.Payload)
	}
	if again.User["saguin-attempt"] != "2" {
		t.Fatalf("after the restart: attempt %q, want 2 - the attempt count did not survive, "+
			"so this record will never exhaust its retries", again.User["saguin-attempt"])
	}
	if again.User["saguin-id"] != first.User["saguin-id"] {
		t.Fatalf("after the restart: message id %q, want %q - a restart made it a new message, "+
			"so a consumer deduplicating on identity will process it twice",
			again.User["saguin-id"], first.User["saguin-id"])
	}

	// And a new record continues the offsets rather than reusing one a
	// stored position already points at (invariant 9).
	p2 := connect(t, h2, "producer-2", true, false)
	p2.Pub(t, "events/orders/4", "order-4")
	if r, ok := reader2.Await(t, 2*time.Second); !ok || r.User["saguin-offset"] != "4" {
		t.Fatalf("after the restart: the next record took offset %q, want 4", r.User["saguin-offset"])
	}
}

// The whole difference a sqlite provider makes, seen from the wire: the
// records are there after a broker that never got to write anything at
// shutdown.
//
// A memory provider's durability is exactly its last snapshot, so the same
// sequence against one loses everything published since the broker
// started - which is invariant 14 working as specified, and exactly the
// limit an operator reaches for sqlite to escape.
func TestSQLiteChannelsSurviveAnUncleanStop(t *testing.T) {
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}
	p.Pub(t, "state/temp", "21.5")

	// A consumer that acknowledges the first two and not the third, so the
	// stored position has to come back at the third rather than at the
	// first or the fourth.
	reader := connect(t, h, "reader", false, true)
	reader.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := reader.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("before the crash: expected record %d, got nothing", i)
		}
		if i < 3 {
			r.Ack()
		}
	}
	// A position is stored on the broker's tick rather than on the publish
	// path, so an unclean stop can lose up to one tick of it - which costs a
	// replay, never a skip. What this test is about is the records
	// surviving, not how promptly a position is written, so it waits for the
	// position the store holds - at the third - rather than for two ticks.
	awaitStoredPosition(t, h, "events", 3, 5*time.Second)

	h.Crash()

	h2 := startDurableSQLite(t, path)

	// A consumer that never existed before reads the channel whole, so the
	// records themselves survived rather than only the counters.
	fresh := connect(t, h2, "fresh", true, false)
	fresh.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := fresh.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("after the crash: record %d is gone", i)
		}
		if want := fmt.Sprintf("order-%d", i); r.Payload != want {
			t.Fatalf("after the crash: record %d is %q, want %q", i, r.Payload, want)
		}
	}

	// The latest value is current state, delivered on subscribe.
	st := connect(t, h2, "state-reader", true, false)
	st.Sub(t, "state/#", 1)
	r, ok := st.Await(t, 2*time.Second)
	if !ok || r.Payload != "21.5" {
		t.Fatalf("after the crash: current state is %+v, want 21.5", r)
	}

	// And the position, which is the part that makes a replay a resume.
	reader2 := connect(t, h2, "reader", false, false)
	reader2.Sub(t, "events/#", 1)
	r, ok = reader2.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the crash: the consumer received nothing, so its position was lost forwards")
	}
	if r.Payload != "order-3" {
		t.Fatalf("after the crash: the consumer resumed at %q, want order-3", r.Payload)
	}
	if extra, more := reader2.Await(t, 500*time.Millisecond); more {
		t.Fatalf("after the crash: the consumer also received %q", extra.Payload)
	}

	// Invariant 9: the next record must not take an offset the stored
	// position already points at.
	p2 := connect(t, h2, "producer-2", true, false)
	p2.Pub(t, "events/orders/4", "order-4")
	r, ok = fresh.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the crash: a new record did not arrive")
	}
	if r.User["saguin-offset"] != "4" {
		t.Errorf("the first record after the crash took offset %q, want 4", r.User["saguin-offset"])
	}
}

// RFC 0003 "`queue` - Restart", invariants 14 and 15
//
// The whole reason a queue wants sqlite, from the wire: work outstanding
// when the broker is killed is still work when it comes back. On a memory
// provider the same sequence loses every job that had not been
// acknowledged, which is invariant 14 behaving exactly as written and the
// limit an operator reaches for sqlite to escape.
//
// It also pins what must *not* come back. The worker held the job with a
// visibility deadline running; after the restart no session holds anything,
// so the job is handed out again immediately rather than after a timeout
// nobody is racing - and its attempt count survived, so it still
// dead-letters rather than starting over.
func TestSQLiteQueueSurvivesAnUncleanStop(t *testing.T) {
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)
	ops := operationsAt(t, h)

	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/build", "job-a")
	p.Pub(t, "jobs/build", "job-b")

	first, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("before the crash: the worker got no job")
	}
	if first.User["saguin-attempt"] != "1" {
		t.Fatalf("before the crash: attempt %q, want 1", first.User["saguin-attempt"])
	}
	// Acknowledge one of them, so the crash finds one resolved and one not.
	w.Respond(t, first.RespTopic, "ack", first.CorrData)
	second, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("before the crash: only one job was delivered")
	}
	// The ack has landed: the broker resolves an answer before it
	// acknowledges it, and Respond waits for that acknowledgement.
	awaitLeased(t, ops, "jobs", second)

	h.Crash()
	h2 := startDurableSQLite(t, path)

	// The unacknowledged job is work again, at once.
	w2 := connect(t, h2, "worker-2", true, false)
	w2.Sub(t, "$saguin/queue/jobs", 1)
	again, ok := w2.Await(t, visibility/2)
	if !ok {
		t.Fatalf("after the crash: no job within %s - outstanding work did not survive "+
			"an unclean stop, which is the whole reason a queue is kept in sqlite",
			visibility/2)
	}
	if again.Payload != second.Payload {
		t.Fatalf("after the crash: got %q, want the unacknowledged %q - an acknowledged "+
			"job came back, or the wrong one did", again.Payload, second.Payload)
	}
	if again.User["saguin-id"] != second.User["saguin-id"] {
		t.Fatalf("after the crash: message id %q, want %q - a restart made it a new "+
			"message, so a consumer deduplicating on identity processes it twice",
			again.User["saguin-id"], second.User["saguin-id"])
	}
	if again.User["saguin-attempt"] != "2" {
		t.Fatalf("after the crash: attempt %q, want 2 - the attempt count did not "+
			"survive, so this record will never exhaust its retries",
			again.User["saguin-attempt"])
	}

	// The acknowledged one is gone for good.
	if extra, more := w2.Await(t, time.Second); more {
		t.Fatalf("after the crash: a second job arrived (%q); the acknowledged one was "+
			"resolved before the crash and must not come back", extra.Payload)
	}
}

// RFC 0003 "`queue` - Dead-lettering" - invariant 5, on a sqlite provider
//
// The move out of the queue and into the dead-letter channel is two tables
// in one file, and a stock subscriber reads the result. Nothing here is
// specific to sqlite from the wire, which is the point: the same sequence
// gives the same answers as it does on memory.
func TestSQLiteQueueDeadLetters(t *testing.T) {
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)

	dlq := connect(t, h, "dlq-reader", true, false)
	dlq.Sub(t, "jobs/__dlq/#", 0)

	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/doomed", "job-1")

	// Never acknowledged: every attempt times out.
	budget := time.Duration(maxAttempts+2) * (visibility + time.Second)
	r, ok := dlq.Await(t, budget)
	if !ok {
		t.Fatalf("nothing reached the dead-letter channel within %s", budget)
	}
	if r.Payload != "job-1" {
		t.Fatalf("dead-lettered payload %q", r.Payload)
	}
	if r.User["saguin-dlq-attempts"] != fmt.Sprint(maxAttempts) {
		t.Fatalf("dead-letter attempts %q, want %d", r.User["saguin-dlq-attempts"], maxAttempts)
	}
	if r.User["saguin-dlq-channel"] != "jobs" {
		t.Fatalf("dead-letter origin %q, want jobs", r.User["saguin-dlq-channel"])
	}

	// And it survives the restart, because it is an append channel in the
	// same file it was moved into.
	h.Crash()
	h2 := startDurableSQLite(t, path)

	after := connect(t, h2, "dlq-reader-2", true, false)
	after.Sub(t, "jobs/__dlq/#", 0)
	got, ok := after.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("after the crash: the dead-lettered record is gone; the move out of the " +
			"queue committed and the arrival did not (invariant 5)")
	}
	if got.Payload != "job-1" {
		t.Fatalf("after the crash: dead-letter payload %q", got.Payload)
	}
}

// RFC 0004 "Moving a channel between providers"
//
// The migration from the wire, which is the only place it can be judged:
// the store tests compare structures, and what an operator cares about is
// that the consumer they left behind carries on where it stopped.
//
// The offsets are the point, and asserting them takes some care. A channel
// running 1..n with nothing missing cannot tell a migration that carried
// its counters across from one that worked them out from the records that
// survive - both say n+1. The queue below is what makes the difference
// visible: resolution removes a record, which is the only gap reachable
// from the wire while retention does not exist.
func TestAMemoryChannelMovesToSQLiteThroughTheWire(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(t.TempDir(), "saguin.db")

	h := startDurable(t, dir)
	ops := operationsAt(t, h)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}
	p.Pub(t, "state/temp", "21.5")

	// Three jobs, two of them resolved. That leaves the queue holding one
	// record at offset 3 with a next of 4 - a gap, and the only one
	// reachable from the wire, because resolution is the one thing that
	// removes a record today. Without it every channel here runs 1..n with
	// nothing missing, and a migration that recomputed the next offset from
	// the records that survive would give the same answer as one that
	// carried it across.
	w0 := connect(t, h, "worker-0", true, false)
	w0.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w0.C)
	for i := 1; i <= 3; i++ {
		p.Pub(t, "jobs/work", fmt.Sprintf("job-%d", i))
	}
	for i := 1; i <= 2; i++ {
		job, ok := w0.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("before the move: job %d was not offered", i)
		}
		w0.Respond(t, job.RespTopic, "ack", job.CorrData)
	}
	// The third is left with the worker, then handed back by its session
	// ending, so it is unresolved work when the broker stops - with its
	// attempt counted first, because the count is what crosses the move.
	third, ok := w0.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("before the move: the third job was not offered")
	}
	awaitLeased(t, ops, "jobs", third)
	linkCut(t, w0)

	// Two of the three records acknowledged, so the position has somewhere
	// to be that is neither the beginning nor the end.
	reader := connect(t, h, "reader", false, true)
	reader.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := reader.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("before the move: record %d did not arrive", i)
		}
		if i < 3 {
			r.Ack()
		}
	}
	// A position is stored on the acknowledgement's own clock, and a stop
	// before it leaves the position behind the records acknowledged.
	eventually(t, "the position stored past the two acknowledged", 5*time.Second, func() bool {
		pos, ok, _ := h.B.ChannelPosition("events", "reader")
		return ok && pos == 3
	})
	h.Stop()

	migrateToSQLite(t, dir, path)

	h2 := startDurableSQLite(t, path)

	fresh := connect(t, h2, "fresh", true, false)
	fresh.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := fresh.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("after the move: record %d is gone", i)
		}
		if want := fmt.Sprintf("order-%d", i); r.Payload != want {
			t.Fatalf("after the move: record %d is %q, want %q", i, r.Payload, want)
		}
		if want := fmt.Sprint(i); r.User["saguin-offset"] != want {
			t.Errorf("after the move: record %d carries offset %q, want %q",
				i, r.User["saguin-offset"], want)
		}
	}

	st := connect(t, h2, "state-reader", true, false)
	st.Sub(t, "state/#", 1)
	if r, ok := st.Await(t, 2*time.Second); !ok || r.Payload != "21.5" {
		t.Fatalf("after the move: current state is %+v, want 21.5", r)
	}

	// The unresolved job, and only that one: resolved work stays resolved.
	w := connect(t, h2, "worker", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	job, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("after the move: the queue's outstanding work is gone")
	}
	if job.Payload != "job-3" {
		t.Errorf("after the move: the queue offered %q, want job-3 - the resolved jobs came back", job.Payload)
	}
	if job.User["saguin-offset"] != "3" {
		t.Errorf("after the move: the surviving job carries offset %q, want 3", job.User["saguin-offset"])
	}
	// Its attempt count came across: it had been delivered once already.
	if job.User["saguin-attempt"] != "2" {
		t.Errorf("after the move: the job is at attempt %q, want 2 - the count restarted",
			job.User["saguin-attempt"])
	}

	// The gap is what makes this bite. Two of the three jobs are gone, so a
	// migration that worked the next offset out from the one that survives
	// would say 2 - an offset already spent - where carrying it across says
	// 4. Invariant 9, from the wire.
	p3 := connect(t, h2, "producer-3", true, false)
	p3.Pub(t, "jobs/work", "job-4")
	w.Respond(t, job.RespTopic, "ack", job.CorrData)
	next, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("after the move: a job published afterwards was not offered")
	}
	if next.User["saguin-offset"] != "4" {
		t.Errorf("the first job after the move took offset %q, want 4: the queue was renumbered",
			next.User["saguin-offset"])
	}

	// The consumer resumes rather than replaying, which is the whole reason
	// positions are carried across.
	reader2 := connect(t, h2, "reader", false, false)
	reader2.Sub(t, "events/#", 1)
	r, ok := reader2.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the move: the consumer received nothing, so its position ran ahead")
	}
	if r.Payload != "order-3" {
		t.Fatalf("after the move: the consumer resumed at %q, want order-3", r.Payload)
	}
	if extra, more := reader2.Await(t, 500*time.Millisecond); more {
		t.Fatalf("after the move: the consumer also received %q, so it replayed", extra.Payload)
	}

	// The append channel carries on rather than starting again. Nothing has
	// been removed from it, so this catches a next offset that was not
	// carried at all and not one that was recomputed - the queue above is
	// where that distinction is made.
	p2 := connect(t, h2, "producer-2", true, false)
	p2.Pub(t, "events/orders/4", "order-4")
	r, ok = fresh.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the move: a new record did not arrive")
	}
	if r.User["saguin-offset"] != "4" {
		t.Errorf("the first record after the move took offset %q, want 4", r.User["saguin-offset"])
	}
}

// The same, the other way, so that moving to sqlite is not a one-way door.
func TestASQLiteChannelMovesBackToSnapshotsThroughTheWire(t *testing.T) {
	path := filepath.Join(t.TempDir(), "saguin.db")
	dir := t.TempDir()

	h := startDurableSQLite(t, path)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}

	reader := connect(t, h, "reader", false, true)
	reader.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := reader.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("before the move: record %d did not arrive", i)
		}
		if i < 3 {
			r.Ack()
		}
	}
	// A position is stored on the acknowledgement's own clock, and a stop
	// before it leaves the position behind the records acknowledged.
	eventually(t, "the position stored past the two acknowledged", 5*time.Second, func() bool {
		pos, ok, _ := h.B.ChannelPosition("events", "reader")
		return ok && pos == 3
	})
	h.Stop()

	migrateToSnapshots(t, path, dir)

	h2 := startDurable(t, dir)

	fresh := connect(t, h2, "fresh", true, false)
	fresh.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := fresh.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("after the move back: record %d is gone", i)
		}
		if want := fmt.Sprintf("order-%d", i); r.Payload != want {
			t.Fatalf("after the move back: record %d is %q, want %q", i, r.Payload, want)
		}
	}

	reader2 := connect(t, h2, "reader", false, false)
	reader2.Sub(t, "events/#", 1)
	r, ok := reader2.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the move back: the consumer received nothing")
	}
	if r.Payload != "order-3" {
		t.Fatalf("after the move back: the consumer resumed at %q, want order-3", r.Payload)
	}

	p2 := connect(t, h2, "producer-2", true, false)
	p2.Pub(t, "events/orders/4", "order-4")
	r, ok = fresh.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("after the move back: a new record did not arrive")
	}
	if r.User["saguin-offset"] != "4" {
		t.Errorf("the first record after the move back took offset %q, want 4", r.User["saguin-offset"])
	}
}

// RFC 0004 "What changing the name does on its own", and invariant 9's
// one exception.
//
// Changing a channel's provider without moving its records is permitted and
// starts the channel fresh. That is the operator's decision and saguin does
// not refuse it - but it is a decision rather than an accident, so it is
// pinned here: without this, somebody meeting the empty channel later
// "fixes" it into a startup error, and the staging step that makes a
// migration possible goes with it.
//
// It also fixes the cost in place. The offsets start again at 1, so the
// same numbers now name different records, and the records that were in the
// old provider are unreachable rather than gone.
func TestAChannelMovedWithoutItsRecordsStartsFresh(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(t.TempDir(), "saguin.db")

	h := startDurable(t, dir)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}
	h.Stop()

	// The same channel, on a provider that has never seen it, and no
	// migration in between.
	h2 := startDurableSQLite(t, path)

	empty := connect(t, h2, "fresh", true, false)
	empty.Sub(t, "events/#", 1)
	if r, more := empty.Await(t, time.Second); more {
		t.Fatalf("the channel came back holding %q: its records crossed providers, which nothing does", r.Payload)
	}

	p2 := connect(t, h2, "producer-2", true, false)
	p2.Pub(t, "events/orders/new", "a different record")
	r, ok := empty.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("the channel is not usable after the move")
	}
	if r.User["saguin-offset"] != "1" {
		t.Errorf("the first record on the new provider took offset %q, want 1", r.User["saguin-offset"])
	}

	// And the records left behind are still there, so "unreachable" is the
	// right word for them and "lost" is not: pointing the configuration back
	// finds them, offsets and all.
	h2.Stop()
	h3 := startDurable(t, dir)
	back := connect(t, h3, "back", true, false)
	back.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		r, ok := back.Await(t, 2*time.Second)
		if !ok {
			t.Fatalf("after moving back: record %d is gone", i)
		}
		if want := fmt.Sprintf("order-%d", i); r.Payload != want {
			t.Fatalf("after moving back: record %d is %q, want %q", i, r.Payload, want)
		}
	}
	// Offset 1 now names two different records, one in each provider. That
	// is what RFC 0004 warns an operator about, and it is why the migration
	// exists.
}

// RFC 0002 "Bounds on what a channel holds", RFC 0003 "At a size bound"
//
// A full channel and a broken disk are different answers to a producer,
// and collapsing them into one sends an operator after a fault that is not
// there. 0x97 says the channel is full and trying later works; 0x83 says
// the storage did not work and somebody should look at the disk.
//
// It runs against all three ways a store reaches a channel - built by the
// broker, attached by a provider that keeps its own records, and restored
// from a snapshot - because each is a separate place the bound can be
// dropped, and a channel that quietly stopped refusing is one nothing
// reports.
func TestAFullChannelAnswers0x97(t *testing.T) {
	// Room for one record of this size and not two.
	one := store.RecordSize(store.Record{
		MessageID: "0123456789012345678901234567890123456", // a UUIDv7 is 36
		Topic:     "events/orders/1",
		Payload:   []byte("0123456789"),
	})
	bounds := map[string]int64{"events": one + one/2}

	code := func(t testing.TB, c *client, topic, payload string) byte {
		t.Helper()
		// Paho reports a non-success PUBACK as an error and still hands
		// back the acknowledgement, which is the thing under test.
		ack, err := c.C.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Payload: []byte(payload),
		})
		if ack == nil {
			t.Fatalf("no PUBACK for %s: %v", topic, err)
		}
		return ack.ReasonCode
	}

	t.Run("a store the broker built", func(t *testing.T) {
		h := startBounded(t, "", bounds)
		c := connect(t, h, "producer", true, false)
		if got := code(t, c, "events/orders/1", "0123456789"); got != 0 {
			t.Fatalf("the first publish answered 0x%02X, want 0x00", got)
		}
		if got := code(t, c, "events/orders/2", "0123456789"); got != 0x97 {
			t.Fatalf("a publish past the bound answered 0x%02X, want 0x97 Quota exceeded", got)
		}

		// Refused rather than stored, and it took no offset behind it.
		reader := connect(t, h, "reader", true, false)
		reader.Sub(t, "events/#", 1)
		r, ok := reader.Await(t, 2*time.Second)
		if !ok {
			t.Fatal("the record that fit is not there")
		}
		if r.User["saguin-offset"] != "1" {
			t.Errorf("it carries offset %q, want 1", r.User["saguin-offset"])
		}
		if extra, more := reader.Await(t, 500*time.Millisecond); more {
			t.Fatalf("the refused publish was stored anyway: %q", extra.Payload)
		}
	})

	// A provider that keeps its own records replaces the store the broker
	// built, so the bound has to follow it there.
	t.Run("a store a provider attached", func(t *testing.T) {
		h := startBounded(t, filepath.Join(t.TempDir(), "saguin.db"), bounds)
		c := connect(t, h, "producer", true, false)
		if got := code(t, c, "events/orders/1", "0123456789"); got != 0 {
			t.Fatalf("the first publish answered 0x%02X, want 0x00", got)
		}
		if got := code(t, c, "events/orders/2", "0123456789"); got != 0x97 {
			t.Fatalf("a publish past the bound answered 0x%02X, want 0x97 - "+
				"the bound was lost when the provider replaced the store", got)
		}
	})

	// And a restored snapshot is a new store too, holding records that
	// already count against the bound.
	t.Run("a store restored from a snapshot", func(t *testing.T) {
		dir := t.TempDir()
		brokertest.Bound = bounds
		t.Cleanup(func() { brokertest.Bound = nil })

		h := startDurable(t, dir)
		c := connect(t, h, "producer", true, false)
		if got := code(t, c, "events/orders/1", "0123456789"); got != 0 {
			t.Fatalf("the first publish answered 0x%02X, want 0x00", got)
		}
		h.Stop()

		h2 := startDurable(t, dir)
		c2 := connect(t, h2, "producer-2", true, false)
		if got := code(t, c2, "events/orders/2", "0123456789"); got != 0x97 {
			t.Fatalf("after a restart a publish past the bound answered 0x%02X, want 0x97 - "+
				"the bound was lost when the snapshot replaced the store", got)
		}
	})
}

// RFC 0002 "Bridges"
//
// An inbound bridge must not acknowledge its upstream until saguin's own
// store has taken the record, so it has to be *told* when the record was
// refused - and the server will not tell it. mochi's InjectPacket returns
// nil either way, because at QoS 1 it answers a hook's reason code with a
// PUBACK written to the publishing client, and an in-process client has no
// connection for that PUBACK to go to.
//
// A bridge that believed that nil would send its own PUBACK upstream for a
// record it had dropped: acknowledged and lost, one hop further out than
// anywhere else saguin can produce it.
//
// This is the only test in the file with nothing on the wire, because a
// bridge is the only thing that publishes without a socket.
func TestABridgeIsToldWhenItsRecordWasRefused(t *testing.T) {
	one := store.RecordSize(store.Record{
		MessageID: "0123456789012345678901234567890123456", // a UUIDv7 is 36
		Topic:     "events/from-upstream",
		Payload:   []byte("0123456789"),
	})
	h := startBounded(t, "", map[string]int64{"events": one + one/2}) // room for one, not two
	bridge := h.B.NewBridgeClient("head-office")

	// A subscriber, so that "refused" can be told from "stored but the
	// answer went missing". The first is what should happen; the second is
	// what a bridge reading InjectPacket's nil would conclude.
	reader := connect(t, h, "reader", true, false)
	reader.Sub(t, "events/#", 1)

	if err := bridge.Publish("events/from-upstream", []byte("0123456789"), nil, store.Props{}); err != nil {
		t.Fatalf("the first bridged record was refused with %v, want it stored", err)
	}
	r, ok := reader.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("the first bridged record never arrived, so it did not go through the publish path")
	}
	if r.Payload != "0123456789" {
		t.Errorf("it arrived as %q", r.Payload)
	}
	// It took an offset, which is what proves it was stored by the channel
	// rather than merely fanned out to whoever was subscribed.
	if r.User["saguin-offset"] != "1" {
		t.Errorf("it carries offset %q, want 1 - a bridged record is stored like any other",
			r.User["saguin-offset"])
	}

	// Now the channel is full, and this is the answer the whole feature
	// rests on.
	err := bridge.Publish("events/from-upstream", []byte("0123456789"), nil, store.Props{})
	if err == nil {
		t.Fatal("a bridged record into a full channel reported success; " +
			"the bridge would acknowledge its upstream for a record saguin dropped")
	}
	var code packets.Code
	if !errors.As(err, &code) {
		t.Fatalf("it was refused with %v, which carries no reason code", err)
	}
	if code.Code != 0x97 {
		t.Errorf("it was refused with 0x%02X, want 0x97 Quota exceeded - "+
			"a full channel and a broken disk are different answers", code.Code)
	}
	if extra, more := reader.Await(t, 500*time.Millisecond); more {
		t.Fatalf("the refused record was delivered anyway: %q", extra.Payload)
	}

	// And a rule written `channel: none` publishes to a topic no channel
	// claims, which is the other half of the path and the half that would
	// break if a bridge were mistaken for the client saguin injects queue
	// deliveries as.
	broadcast := connect(t, h, "broadcast-reader", true, false)
	broadcast.Sub(t, "alerts/#", 1)
	if err := bridge.Publish("alerts/vessel-07/fire", []byte("smoke"), nil, store.Props{}); err != nil {
		t.Fatalf("a bridged broadcast record was refused with %v", err)
	}
	got, ok := broadcast.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("a bridged record on a topic no channel claims never reached a subscriber")
	}
	if got.Payload != "smoke" {
		t.Errorf("it arrived as %q, want %q", got.Payload, "smoke")
	}
}

// The property that makes a queue's bound flow control rather than a
// limit: resolution frees the space, so a queue that filled accepts work
// again with nobody acting. A bound that did not recover would turn one
// burst into a queue that refuses for ever.
func TestAQueueAtItsBoundAcceptsWorkAgainOnceItIsResolved(t *testing.T) {
	one := store.RecordSize(store.Record{
		MessageID: "0123456789012345678901234567890123456",
		Topic:     "jobs/work",
		Payload:   []byte("job-1"),
	})
	h := startBounded(t, "", map[string]int64{"jobs": one})

	p := connect(t, h, "producer", true, false)
	code := func(t testing.TB, payload string) byte {
		t.Helper()
		ack, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "jobs/work", QoS: 1, Payload: []byte(payload),
		})
		if ack == nil {
			t.Fatalf("no PUBACK: %v", err)
		}
		return ack.ReasonCode
	}

	if got := code(t, "job-1"); got != 0 {
		t.Fatalf("the first job answered 0x%02X, want 0x00", got)
	}
	if got := code(t, "job-2"); got != 0x97 {
		t.Fatalf("a job past the bound answered 0x%02X, want 0x97 Quota exceeded", got)
	}

	// A worker takes the one job and acknowledges it, which is the only
	// thing that frees a queue's space.
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	job, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the job was not offered")
	}
	w.Respond(t, job.RespTopic, "ack", job.CorrData)
	// Resolved: the queue holds nothing, read from the broker rather than
	// slept for.
	ops := operationsAt(t, h)
	for deadline := time.Now().Add(5 * time.Second); scrapeGauges(t, ops)[`saguin_queue_depth{channel="jobs"}`] != 0; time.Sleep(10 * time.Millisecond) {
		if time.Now().After(deadline) {
			t.Fatal("the acknowledged job was still in the queue after 5s")
		}
	}

	if got := code(t, "job-3"); got != 0 {
		t.Fatalf("after the queue drained it still answered 0x%02X, want 0x00 - "+
			"a bound that does not recover is a limit, not backpressure", got)
	}
	next, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the job accepted after the queue drained was never offered")
	}
	if next.Payload != "job-3" {
		t.Errorf("the worker was offered %q, want job-3", next.Payload)
	}
}

// RFC 0003 "`append` - Resuming below the retention floor"
//
// A consumer whose stored position retention has removed is told, with
// CONNACK Session Present = 0, and starts fresh at the channel's floor.
//
// The failure this replaces is the one invariant 1 exists to report: serve
// the oldest surviving record as though nothing were missing, and the
// consumer processes the remainder in order and reports success over
// everything that went - with the only notice in the broker's log, where
// the party that needs it is not looking.
//
// It was unreachable until retention existed, because no floor had ever
// moved.
func TestAConsumerBelowTheFloorIsToldItsSessionIsGone(t *testing.T) {
	// Small enough that a handful of records pushes the floor past the
	// consumer's position, and the size sweep runs every second.
	h := startTrimming(t, map[string]int64{"events": 200})
	p := connect(t, h, "producer", true, false)

	c := connect(t, h, "device", false, false)
	if c.SessionPresent {
		t.Fatal("a first connection reported a session that did not exist")
	}
	c.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/1", "first")
	if _, ok := c.Await(t, 3*time.Second); !ok {
		t.Fatal("no delivery before the link dropped")
	}
	awaitStoredPosition(t, h, "events", 2, 5*time.Second) // its position stored

	// Away, while enough is published to take the floor past where it was.
	linkCut(t, c)
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past the position

	again := connect(t, h, "device", false, false)
	if again.SessionPresent {
		t.Error("the broker kept a session whose position retention had removed: " +
			"the consumer is about to be served the oldest survivor and report success " +
			"over everything in between")
	}

	// And it is a working consumer afterwards rather than a discarded one:
	// it resubscribes, as Session Present = 0 tells every client to, and
	// receives what is published next.
	again.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/last", "after-the-gap")
	deadline := time.Now().Add(4 * time.Second)
	for time.Now().Before(deadline) {
		r, ok := again.Await(t, time.Second)
		if ok && r.Payload == "after-the-gap" {
			return
		}
	}
	t.Error("the consumer received nothing after being told to start again")
}

// RFC 0003 "Sessions": a CONNECT that takes over a session ending with its
// connection begins a new one, as a clean start does, and what retention did
// to the session it ended is not counted as a position lost to it: that
// session did not come back to find its position gone, it ended. A consumer
// with no Session Expiry Interval, connected and acknowledging nothing, has
// retention pass its stored position, and a Clean Start 0 CONNECT takes it
// over. The control is a consumer whose session outlives its connection,
// away while retention passes it: its position is lost, counted, which shows
// the floor did pass. It was counted for the first too, and logged as a
// consumer "away" that had been connected throughout.
func TestATakeoverBegunNewCountsNoPositionLostForTheSessionItEnded(t *testing.T) {
	for _, arm := range []struct {
		name   string
		expiry uint32
		lost   float64
	}{
		{"no Session Expiry Interval", 0, 0},
		{"a Session Expiry Interval (control)", 3600, 1},
	} {
		t.Run(arm.name, func(t *testing.T) {
			h := startTrimming(t, map[string]int64{"events": 200})
			ops := operationsAt(t, h)
			p := connect(t, h, "producer", true, false)
			c := dial(t, h, "device", true, true, 10, arm.expiry, 0)
			c.Sub(t, "events/#", 1)
			p.Pub(t, "events/a/1", "first")
			if _, ok := c.Await(t, 3*time.Second); !ok {
				t.Fatal("no delivery, so no position is stored")
			}
			// Never acknowledged (manual), so its position stays at the record.
			awaitStoredPosition(t, h, "events", 1, 5*time.Second)
			if arm.expiry > 0 {
				linkCut(t, c)
			}
			for i := range 30 {
				p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
			}
			awaitFloorPast(t, h, "events", 1, 5*time.Second) // the size sweep past the position
			const series = `saguin_channel_position_lost_total{channel="events"}`
			before := scrapeGauges(t, ops)[series]

			again := dial(t, h, "device", false, false, 10, 3600, 0)
			if again.SessionPresent {
				t.Error("the takeover was told Session Present 1")
			}
			if d := scrapeGauges(t, ops)[series] - before; d != arm.lost {
				t.Errorf("%s went up %v, want %v", series, d, arm.lost)
			}
		})
	}
}

// RFC 0003 "Sessions" - a session retention passed ends like any other, and a
// Will still waiting on it is published first.
//
// A device went away with a delayed Will, and retention passed its position
// while it was gone. When it comes back, the broker discards the session and
// answers Session Present 0: the session has ended. A Will is due when its
// session ends, whichever of that and its delay comes first, so the Will is
// published then. This path used to leave the Will where it was, and the
// resume that followed counted it cancelled - "the client connected again" -
// so a device whose session had just been thrown away was never announced.
func TestAWillWaitingOnASessionRetentionPassedIsPublishedOnce(t *testing.T) {
	h := startTrimming(t, map[string]int64{"events": 200})
	ops := operationsAt(t, h)
	p := connect(t, h, "producer", true, false)
	watch := connect(t, h, "watcher", true, false)
	watch.Sub(t, "loose/#", 1)

	conn := takeoverWillConn(t, h.Addr, "device", true, "OLD", 60)
	dev := &qos2Wire{T: t, C: conn}
	dev.Subscribe("events/#", 1)
	p.Pub(t, "events/a/1", "first")
	pub, ok := dev.Next(3 * time.Second).Content.(*pahopackets.Publish)
	if !ok {
		t.Fatal("no delivery before the link dropped")
	}
	dev.Puback(pub.PacketID)
	awaitStoredPosition(t, h, "events", 2, 5*time.Second) // its position stored

	// Away with its Will waiting out a minute's delay.
	_ = conn.Close()
	sessionGone(t, h, "device")
	if r, ok := watch.Await(t, 500*time.Millisecond); ok {
		t.Fatalf("%q was published at the cut: the Will was not held, so this proves nothing", r.Payload)
	}
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past the position

	takeoverWillConn(t, h.Addr, "device", false, "NEW", 60)
	if lost := scrapeGauges(t, ops)[`saguin_channel_position_lost_total{channel="events"}`]; lost != 1 {
		t.Fatalf("position lost %v, want 1: the resume did not find retention past its "+
			"position, so the session was not discarded and this proves nothing", lost)
	}
	r, ok := watch.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the session ended when its client came back past the floor, and the Will " +
			"waiting on it was never published")
	}
	if r.Payload != "OLD" {
		t.Errorf("published %q, want the ended session's Will", r.Payload)
	}
	if extra, more := watch.Await(t, time.Second); more {
		t.Errorf("the Will was published again: %q", extra.Payload)
	}
	g := scrapeGauges(t, ops)
	if got := g[`saguin_wills_published_total{cause="session_ended"}`]; got != 1 {
		t.Errorf("wills published for an ended session: %v, want 1", got)
	}
	if got := g["saguin_wills_cancelled_total"]; got != 0 {
		t.Errorf("wills cancelled: %v, want 0 - the session ended, it was not resumed", got)
	}
}

// invariant 1, and RFC 0005's `saguin_channel_position_lost_total`
//
// **A consumer whose stored position retention passed while it was away is
// the same loss as one passed while it was connected**, and the operator's
// number has to say so. The consumer is told here - Session Present = 0,
// which the test above holds - so this is not invariant 1's unreportable
// case; it is the reportable half of the same rule, whose other half the
// invariant states plainly: the broker tells the *operator* how many
// records went.
//
// It is the commonest shape of the loss rather than an exotic one - a
// device away longer than its channel's retention is the case saguin
// exists for - so a counter silent about it is silent about the case an
// operator most needs to see.
func TestAConsumerPassedWhileAwayIsCountedAsALoss(t *testing.T) {
	h := startTrimming(t, map[string]int64{"events": 200})

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	// No interval, for the reason the connected-consumer test gives: any
	// interval can answer the second scrape from the body built before the
	// floor moved, and the test reports that as nothing counted.
	stopOps, err := h.B.ServeOperations(tcpOnly(ops), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(stopOps)

	const lost = `saguin_channel_position_lost_total{channel="events"}`
	if got := metricValue(t, ops, lost); got != 0 {
		t.Fatalf("%s was already %v before anything was published, so a reading "+
			"of 1 afterwards would prove nothing", lost, got)
	}

	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "device", false, false)
	c.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/1", "first")
	if _, ok := c.Await(t, 3*time.Second); !ok {
		t.Fatal("no delivery before the link dropped, so the consumer never had a position to lose")
	}
	awaitStoredPosition(t, h, "events", 2, 5*time.Second) // its position stored

	linkCut(t, c)
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past the position

	again := connect(t, h, "device", false, false)
	if again.SessionPresent {
		t.Fatal("the broker kept a session whose position retention had removed, so this " +
			"test never reached the loss it is about")
	}

	if got := metricValue(t, ops, lost); got != 1 {
		t.Errorf("%s is %v after retention passed an away consumer's stored position, want 1.\n\t"+
			"The records between its position and the floor are gone and unreadable, and "+
			"nothing in the catalogue says so: an operator watching this number for "+
			"\"am I losing data\" sees nothing for the commonest way it happens", lost, got)
	}
}

// invariant 1, and RFC 0005's `saguin_channel_position_lost_total`
//
// **A stored position can outlive the session that owns it**, and when it
// does the loss used to reach nobody at all. `broker.session.storage`
// naming a memory provider while a channel sits on a database is the
// pairing (RFC 0002): a restart keeps the position and loses the session,
// so the device reconnects with records unreadable beneath it and mochi
// holding nothing to report. The accounting sat below the early return
// that state takes, so no line was written, no counter moved, and Session
// Present = 0 carried no signal because there was no session to miss.
//
// It is the one shape of this loss where the broker is the only party that
// can ever know: the connected case at least warns the operator, and the
// ordinary reconnect above warns and is told. Reached this way, the records
// went and every instrument said nothing.
//
// Driven rather than reasoned about: without the fix this test sees the
// counter at 0 and no line in the whole log.
func TestAPositionOutlivingItsSessionIsStillCountedAsALoss(t *testing.T) {
	path := filepath.Join(t.TempDir(), "outlives.db")
	brokertest.Retain = map[string]int64{"events": 200}
	t.Cleanup(func() { brokertest.Retain = nil })
	// Sessions in memory, channels on the database - the pairing that makes
	// a position outlive its session across the restart below.
	brokertest.SessionsInMemory = true
	t.Cleanup(func() { brokertest.SessionsInMemory = false })

	h := startDurableSQLite(t, path)
	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "device", false, false)
	c.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/1", "first")
	if _, ok := c.Await(t, 3*time.Second); !ok {
		t.Fatal("no delivery before the link dropped, so the consumer never had a position to lose")
	}
	awaitStoredPosition(t, h, "events", 2, 5*time.Second) // its position stored

	linkCut(t, c)
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past the position

	// No orderly shutdown, so the memory session store goes with the
	// process while the database keeps the position.
	h.Crash()

	var mu sync.Mutex
	var lines []string
	h2 := startLoggingSQLite(t, func(l string) {
		mu.Lock()
		lines = append(lines, l)
		mu.Unlock()
	}, path)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	stopOps, err := h2.B.ServeOperations(tcpOnly(ops), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(stopOps)

	again := connect(t, h2, "device", false, false)
	if again.SessionPresent {
		t.Fatal("the restarted broker reported a session, so the position did not outlive " +
			"one and this test never reached the state it is about")
	}
	// Counted by the hook that decided Session Present; read until it shows,
	// so a counter that never moves is the failure and not a slow one.
	const lost = `saguin_channel_position_lost_total{channel="events"}`
	got := metricValue(t, ops, lost)
	for deadline := time.Now().Add(5 * time.Second); got < 1 && time.Now().Before(deadline); {
		time.Sleep(10 * time.Millisecond)
		got = metricValue(t, ops, lost)
	}
	if got != 1 {
		t.Errorf("%s is %v after retention passed a position that outlived its session, want 1.\n\t"+
			"The position was dropped, the records beneath it are unreadable, and the "+
			"counter an operator watches for invariant 1 did not move", lost, got)
	}

	mu.Lock()
	defer mu.Unlock()
	var said string
	for _, l := range lines {
		if strings.Contains(l, "retention passed a stored position while its consumer was away") {
			said = l
		}
	}
	if said == "" {
		t.Fatalf("nothing in the broker's %d log lines says a position was passed, and this is "+
			"the one shape of the loss where the log is the operator's only sequential "+
			"record of it", len(lines))
	}
	// The line carries the arithmetic rather than leaving it to be done: the
	// route in front of this counter is keyed off the same numbers.
	missed, ok := brokertest.LogValue(said, "records_missed")
	if !ok {
		t.Fatalf("the line says a position was passed and not how much went:\n\t%s", said)
	}
	pos, okP := brokertest.LogValue(said, "position")
	floor, okF := brokertest.LogValue(said, "floor")
	if !okP || !okF {
		t.Fatalf("the line carries no position or floor to check records_missed against:\n\t%s", said)
	}
	if missed != floor-pos {
		t.Errorf("the line says records_missed=%d with position=%d and floor=%d, which do not "+
			"agree:\n\t%s", missed, pos, floor, said)
	}
	if missed == 0 {
		t.Errorf("the line reports a passing that lost nothing, so it is being written where "+
			"there is no loss:\n\t%s", said)
	}
}

// RFC 0005 "The /v1 routes" - and RFC 0003 "Resuming below the retention
// floor"
//
// **A session discarded because retention moved is not a refusal.** The
// broker ends that connection itself, so it passes the same helper every
// other ending does - and the instruments must stay quiet, because they
// report devices the broker turned away and this device did nothing wrong.
// Counted here, an operator alerting on the refusal rate would be paged by
// their own retention policy.
//
// **This site is the one saguin's first sweep missed**, since it names its
// client `existing` rather than `cl`, and reading it was not enough.
// It is driven here, and driving it needs a shape the other
// floor tests do not have: they cut the link first, so the old connection
// is already closed by the time the discard runs and both helpers do
// nothing. The old connection has to still be **open**, which means a
// consumer that stays connected while the floor passes it - watching a
// filter the padding does not match, so its position stands still while
// the channel fills.
//
// Measured while writing it: position 2, floor 40, old connection open.
func TestASessionDiscardedByRetentionIsNotCountedAsARefusal(t *testing.T) {
	h := startTrimming(t, map[string]int64{"events": 200})
	opsAddr := refusedRouteOn(t, h)
	p := connect(t, h, "producer", true, false)

	// A durable 3.1.1 consumer: the discard closes it with nothing said,
	// which is also how a refusal ends a connection below MQTT 5, so it is
	// the ending most easily mistaken for one.
	c, _ := legacyWithDefault(t, h, "esp-floor", false, nil)
	if tok := c.Subscribe("events/watched/#", 1, func(mqttv3.Client, mqttv3.Message) {}); !tok.WaitTimeout(3*time.Second) || tok.Error() != nil {
		t.Fatalf("subscribe: %v", tok.Error())
	}
	p.Pub(t, "events/watched/1", "first")
	awaitStoredPosition(t, h, "events", 2, 5*time.Second) // its position stored

	// The floor moves past it on records it is not watching, so it stays
	// connected and its position stays where it is.
	for i := range 40 {
		p.Pub(t, "events/other/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past the position

	// The same id arrives while the first connection is still open, which
	// is what puts a live client through the discard.
	// Read once the first connection's teardown is done, which is where a
	// discard mistaken for a refusal would be recorded.
	first := h.Disconnects.Snapshot("esp-floor")
	second, _ := legacyWithDefault(t, h, "esp-floor", false, nil)
	defer second.Disconnect(100)
	sessionGoneAfter(t, h, "esp-floor", first)

	if rows := refusedRows(t, opsAddr); len(rows) != 0 {
		t.Errorf("a session discarded because retention moved was recorded as a "+
			"refusal: %+v. These instruments count devices the broker turned away, "+
			"and an operator alerting on them would be paged by their own retention "+
			"policy", rows)
	}
}

// ticked waits until the broker's queue tick - what offers waiting jobs and
// notices expired leases - has finished n times from now. A test asserting
// what the offer loop did not do over some ticks counts the ticks; a sleep
// counted them only on a machine that kept up.
func ticked(t *testing.T, h *harness, n int64) {
	t.Helper()
	count, restore := broker.CountQueueTicks(h.B)
	defer restore()
	for deadline := time.Now().Add(10 * time.Second); count() < n; time.Sleep(5 * time.Millisecond) {
		if time.Now().After(deadline) {
			t.Fatalf("the queue tick finished %d times in 10s, want %d", count(), n)
		}
	}
}

// sweptTwice waits until the broker's size sweep has finished twice from now.
// The second began after this was called, so it saw everything stored
// before it - which is what "a sweep ran" means to a test asserting what a
// sweep left alone, and what a sleep through the sweep's period guessed at.
func sweptTwice(t *testing.T, h *harness) {
	t.Helper()
	count, restore := broker.CountSizeSweeps(h.B)
	defer restore()
	for deadline := time.Now().Add(10 * time.Second); count() < 2; time.Sleep(10 * time.Millisecond) {
		if time.Now().After(deadline) {
			t.Fatalf("the size sweep finished %d times in 10s, want 2", count())
		}
	}
}

// A consumer whose position is still above the floor keeps its session.
// Discarding one that did not need it costs a consumer its position and a
// replay of everything the channel still holds, so the check has to be the
// position rather than the mere existence of retention.
func TestAConsumerAboveTheFloorKeepsItsSession(t *testing.T) {
	h := startTrimming(t, map[string]int64{"events": 1 << 20})
	p := connect(t, h, "producer", true, false)

	c := connect(t, h, "device", false, false)
	c.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/1", "first")
	if _, ok := c.Await(t, 3*time.Second); !ok {
		t.Fatal("no delivery before the link dropped")
	}
	awaitStoredPosition(t, h, "events", 2, 5*time.Second)

	linkCut(t, c)
	p.Pub(t, "events/a/2", "second")
	sweptTwice(t, h) // a sweep runs and removes nothing

	again := connect(t, h, "device", false, false)
	if !again.SessionPresent {
		t.Error("a consumer whose position was still readable had its session discarded")
	}
	r, ok := again.Await(t, 3*time.Second)
	if !ok || r.Payload != "second" {
		t.Errorf("it resumed at the wrong place: got %q ok=%v, want second", r.Payload, ok)
	}
}

// RFC 0003 "`append` - Durable consumers", invariant 1
//
// The retention floor passing a consumer that is **connected and reading**
// is invariant 1's failure with the report going to the operator instead of
// the consumer, and this is that case driven rather than described.
//
// A consumer whose stored position retention removed is told at CONNECT,
// with Session Present = 0 - the test above this one. One that is connected
// when the floor passes it has no CONNECT to carry that signal, and MQTT
// gives the broker no other way to send it. So the broker restarts it at the
// floor and says how much went, in a log line only the operator sees, while
// the consumer reads on in order and reports success over the gap.
//
// **What is asserted is that the number in that line is true.** A warning
// nobody can check is worth less than none, so `records_missed` is measured
// against the offset the consumer is actually handed next: the position was
// 2, so the first record after the gap must be at offset `records_missed+2`.
//
// The consumer is held still rather than raced. Receive Maximum 1 and a
// handler that does not return leave it holding offset 1 unacknowledged with
// a full window, so no timing decides how far behind it is.
// The other half of that: **an arrival is not a loss.**
//
// The test above holds a consumer still and moves the floor past it, and
// asserts the warning and the counter. It says nothing about a subscriber
// that was never there - and that is the case the broker got wrong, because
// every fresh cursor started at offset 1 and the read from 1 was refused the
// moment retention had moved. A clean-start subscriber with no session at
// all was then counted as a consumer whose data had been deleted, and the
// warning told the operator how many records it had "missed" from before it
// existed.
//
// It fires once per arrival per channel older than its retention, so on a
// fleet it is every device that ever joins - which makes the one alert RFC
// 0005 builds the catalogue for unreadable, in the same way and for the same
// reason as the field that only fell.
//
// **What is asserted is both halves at once**, because either alone is
// satisfied by a broker that is wrong: a check that only counts arrivals
// passes on one that has stopped reporting real losses, and the test above
// passes on one that reports everything. So this drives an arrival and a
// genuine loss against the same broker and asserts the counter moved for one
// and not the other.
func TestAnArrivalAtATrimmedChannelIsNotALoss(t *testing.T) {
	var mu sync.Mutex
	var lines []string

	brokertest.Retain = map[string]int64{"events": 200}
	t.Cleanup(func() { brokertest.Retain = nil })
	h := startLogging(t, func(l string) {
		mu.Lock()
		lines = append(lines, l)
		mu.Unlock()
	})

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	// No interval, for the reason the test above gives: an early scrape is
	// answered from the previous body, so any interval could read the
	// numbers from before anything happened and call that proof.
	stopOps, err := h.B.ServeOperations(tcpOnly(ops), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(stopOps)

	p := connect(t, h, "producer", true, false)
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past offset 2

	const lost = `saguin_channel_position_lost_total{channel="events"}`
	if got := metricValue(t, ops, lost); got != 0 {
		t.Fatalf("%s is %v before anybody subscribed, so nothing below would mean anything", lost, got)
	}

	// **The floor has to have moved, or this test proves nothing.** A
	// channel still at offset 1 serves a fresh subscriber without ever
	// reaching the refused read, and every assertion below would hold on a
	// broker that counts arrivals.
	p.Pub(t, "events/a/1", "after-the-trim")
	arrival := connectRx(t, h, "arrival", true, false, 0)
	arrival.Sub(t, "events/#", 1)
	r, ok := arrival.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("the arriving subscriber was fed nothing, so it never reached the read this is about")
	}
	got, err := strconv.ParseUint(r.User["saguin-offset"], 10, 64)
	if err != nil {
		t.Fatalf("the record it was served carried no offset: %q", r.User["saguin-offset"])
	}
	if got <= 1 {
		t.Fatalf("it was served offset %d, so the floor had not moved and this proved nothing", got)
	}

	if v := metricValue(t, ops, lost); v != 0 {
		t.Errorf("%s is %v after a subscriber arrived at a trimmed channel and lost nothing.\n\t"+
			"It had no stored position and had read no record, so retention cannot have passed "+
			"it. Counting it fires the alert once per arrival, on every channel older than its "+
			"retention", lost, v)
	}
	mu.Lock()
	for _, l := range lines {
		if strings.Contains(l, "the retention floor passed a connected consumer") {
			t.Errorf("an arriving subscriber was warned about as one the floor passed:\n\t%s", l)
		}
	}
	mu.Unlock()
}

func TestTheFloorPassingAConnectedConsumerSaysHowMuchWent(t *testing.T) {
	var mu sync.Mutex
	var lines []string

	// Retention by size, small enough that thirty records take the floor
	// past a consumer stuck at the beginning. Set before startLogging,
	// because that is the call which starts the broker and both are read
	// once, at startup.
	brokertest.Retain = map[string]int64{"events": 200}
	t.Cleanup(func() { brokertest.Retain = nil })
	h := startLogging(t, func(l string) {
		mu.Lock()
		lines = append(lines, l)
		mu.Unlock()
	})

	p := connect(t, h, "producer", true, false)

	c := connectRx(t, h, "slow", false, false, 1)
	c.Hold = make(chan struct{})
	c.HoldPayload = "first"
	c.Sub(t, "events/#", 1)

	// Released on the way out however this test ends, and that is not
	// tidiness. A held consumer's receive handler never returns, so a
	// failure between here and the release below leaves that goroutine
	// blocked for ever and the harness's shutdown waiting on it: the test
	// hangs until the package-wide timeout kills it, taking every other
	// test's result with it, instead of printing the assertion that failed.
	var once sync.Once
	release := func() { once.Do(func() { close(c.Hold) }) }
	t.Cleanup(release)

	p.Pub(t, "events/a/1", "first")
	if r, ok := c.Await(t, 3*time.Second); !ok || r.Payload != "first" {
		t.Fatalf("the consumer never got the record it is held on: %v %q", ok, r.Payload)
	}

	// The operator's other signal, read the way an operator reads it -
	// over RFC 0005's /metrics on a real socket - rather than from a field.
	//
	// **No minimum scrape interval is the instrument, not a preference.**
	// metricsHandler answers an early scrape with the *previous* body rather
	// than refusing it, deliberately, so that Prometheus never records a
	// gap. With any interval the second reading below could return the
	// numbers from before the floor moved - a millisecond included, which a
	// loopback round trip can beat - and this test would report them as
	// proof that nothing was counted.
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	stopOps, err := h.B.ServeOperations(tcpOnly(ops), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(stopOps)

	const lost = `saguin_channel_position_lost_total{channel="events"}`
	if got := metricValue(t, ops, lost); got != 0 {
		t.Fatalf("%s was already %v before the floor passed anybody, so a reading "+
			"of 1 afterwards would prove nothing", lost, got)
	}

	// Enough to take the floor past it. The size sweep runs on its own
	// second, so this waits for one rather than for a number of records.
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past offset 2

	// Released. The PUBACK is what calls the pump, and the pump now reads
	// from a position below the floor.
	release()

	r, ok := c.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("the consumer was fed nothing at all after the floor passed it")
	}
	got, err := strconv.ParseUint(r.User["saguin-offset"], 10, 64)
	if err != nil {
		t.Fatalf("the record after the gap carried no offset: %q", r.User["saguin-offset"])
	}

	mu.Lock()
	var warned []string
	for _, l := range lines {
		if strings.Contains(l, "the retention floor passed a connected consumer") {
			warned = append(warned, l)
		}
	}
	mu.Unlock()
	if len(warned) != 1 {
		t.Fatalf("the floor passed a connected consumer and the operator was told "+
			"%d times, want exactly 1", len(warned))
	}

	missed, ok := logValue(warned[0], "records_missed")
	if !ok {
		t.Fatalf("the warning does not say how much went, which is the whole of "+
			"what it is for: %s", warned[0])
	}
	if missed == 0 {
		t.Fatal("the warning says nothing was missed, so either the floor did not " +
			"pass this consumer or the number is wrong")
	}
	if missed+2 != got {
		t.Errorf("the operator was told %d records went, and the consumer resumed at "+
			"offset %d - it was at 2, so those disagree by %d. The one number an "+
			"operator has for a gap nobody else is told about must be the true one.",
			missed, got, int64(got)-int64(missed+2))
	}

	// The counter is the signal an alert is built on, and the log line is
	// the one a human reads. They are two reports of one event, so they
	// have to agree about how many times it happened.
	if v := metricValue(t, ops, lost); v != 1 {
		t.Errorf("%s is %v after the floor passed a connected consumer once, want 1: "+
			"the log line said it happened and the number an operator alerts on "+
			"did not", lost, v)
	}
}

// Discarding a session takes the superseded connection down, and its
// teardown then runs on its own goroutine - after the replacement is
// established. mochi guards its own version of this with an unexported
// "taken over" flag that a hook cannot set, so what stops that teardown
// carrying the new session's subscriptions away with it is that the branch
// which would do so needs a session expiring the moment it disconnects,
// which a durable consumer by definition does not have.
//
// That is a reasoned argument, so it is run instead. Repeated, because the
// damage happens only when the teardown lands after the new session is
// serving - one round would be a coin flip rather than an assertion.
func TestDiscardingASessionDoesNotDisturbTheReplacement(t *testing.T) {
	h := startTrimming(t, map[string]int64{"events": 200})
	p := connect(t, h, "producer", true, false)

	for round := 1; round <= 8; round++ {
		c := connect(t, h, "device", false, false)
		c.Sub(t, "events/#", 1)
		p.Pub(t, "events/a/1", "seed")
		// The seed, past anything the resumed session is sent again first.
		var r received
		for r.Payload != "seed" {
			var ok bool
			if r, ok = c.Await(t, 3*time.Second); !ok {
				t.Fatalf("round %d: no delivery before the link dropped", round)
			}
		}
		seed, err := strconv.ParseUint(r.User["saguin-offset"], 10, 64)
		if err != nil {
			t.Fatalf("round %d: the seed carried no offset: %q", round, r.User["saguin-offset"])
		}
		awaitStoredPosition(t, h, "events", seed+1, 5*time.Second)

		linkCut(t, c)
		for i := range 30 {
			p.Pub(t, "events/a/x", fmt.Sprintf("round-%d-%02d-padded-to-push-the-floor", round, i))
		}
		awaitFloorPast(t, h, "events", seed+1, 5*time.Second) // the size sweep past it

		again := connect(t, h, "device", false, false)
		if again.SessionPresent {
			t.Fatalf("round %d: the session was not discarded, so this round proves nothing", round)
		}
		again.Sub(t, "events/#", 1)

		// The superseded connection's teardown has landed - linkCut waited
		// for it above - so the replacement is read after it, with no wait
		// for a teardown to come round.
		want := fmt.Sprintf("live-%d", round)
		p.Pub(t, "events/a/live", want)

		got := false
		deadline := time.Now().Add(3 * time.Second)
		for !got && time.Now().Before(deadline) {
			if r, ok := again.Await(t, time.Second); ok && r.Payload == want {
				got = true
			}
		}
		if !got {
			t.Fatalf("round %d: the replacement stopped receiving - the superseded "+
				"connection's teardown took the new session's subscriptions with it", round)
		}
		linkCut(t, again)
	}
}

// RFC 0003 "`queue` - Dead-lettering"
//
// A job older than its queue's job_expires_after is dead-lettered "without
// further delivery", with reason `expired`. Without further delivery is the
// part that decides where the check goes: a worker must never be handed
// work the broker has already decided is too old to do.
//
// It goes whatever the attempt count says, because it is out of time rather
// than out of attempts - this one expires before any worker exists to
// receive it, so it is dead-lettered on its first offer with no attempt
// spent at all.
func TestAnExpiredJobIsDeadLetteredInsteadOfDelivered(t *testing.T) {
	h := startExpiring(t, 1)
	p := connect(t, h, "producer", true, false)

	// Published with no worker connected, and left to go stale.
	p.Pub(t, "jobs/a", "too-old")
	time.Sleep(1500 * time.Millisecond)

	// A worker arrives only now. It must not be given the job.
	w := connect(t, h, "worker-1", false, true)
	w.Sub(t, "$saguin/queue/jobs", 1)

	// The dead-letter channel has it instead, with the reason and the
	// headers a stock client can read.
	d := connect(t, h, "dlq-reader", true, false)
	d.Sub(t, "jobs/__dlq/#", 1)

	r, ok := d.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("the expired job never reached the dead-letter channel")
	}
	if r.Payload != "too-old" {
		t.Errorf("the dead-lettered record is %q, want too-old", r.Payload)
	}
	if got := r.User["saguin-dlq-reason"]; got != "expired" {
		t.Errorf("dead-lettered with reason %q, want expired", got)
	}
	if got := r.User["saguin-dlq-attempts"]; got != "0" {
		t.Errorf("the expired job spent %q attempts; it was never delivered, so it should spend none", got)
	}

	// And the worker was never given it.
	if _, ok := w.Await(t, time.Second); ok {
		t.Error("a worker was handed a job the broker had already expired")
	}
}

// A job inside its expiry is delivered normally. The check has to be the
// age rather than the presence of an expiry, or configuring one would stop
// a queue working.
func TestAJobInsideItsExpiryIsDeliveredNormally(t *testing.T) {
	h := startExpiring(t, 3600)
	p := connect(t, h, "producer", true, false)

	w := connect(t, h, "worker-1", false, true)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p.Pub(t, "jobs/a", "fresh")
	r, ok := w.Await(t, 5*time.Second)
	if !ok {
		t.Fatal("a job well inside its expiry was not delivered")
	}
	if r.Payload != "fresh" {
		t.Errorf("the worker got %q, want fresh", r.Payload)
	}
}

// The half a worker cannot enforce: a queue whose workers have all gone
// away is never offered anything, so the check made at hand-over never
// runs - and expiry exists for work nobody is processing, which is exactly
// that queue.
//
// No worker connects here at all. The jobs go stale, the sweep moves them,
// and a reader of the dead-letter channel finds them with reason expired.
func TestJobsExpireWithNoWorkerEverConnecting(t *testing.T) {
	h := startExpiring(t, 1)
	p := connect(t, h, "producer", true, false)

	d := connect(t, h, "dlq-reader", true, false)
	d.Sub(t, "jobs/__dlq/#", 1)

	for _, m := range []string{"job-a", "job-b", "job-c"} {
		p.Pub(t, "jobs/"+m, m)
	}

	// The age sweep is a tenth of the shortest deadline, floored at one
	// second, so a couple of seconds covers it.
	seen := map[string]string{}
	deadline := time.Now().Add(6 * time.Second)
	for len(seen) < 3 && time.Now().Before(deadline) {
		r, ok := d.Await(t, time.Second)
		if !ok {
			continue
		}
		seen[r.Payload] = r.User["saguin-dlq-reason"]
	}

	if len(seen) != 3 {
		t.Fatalf("%d of 3 jobs expired with no worker connected: %v - a queue whose "+
			"workers have gone away holds its work for ever", len(seen), seen)
	}
	for job, reason := range seen {
		if reason != "expired" {
			t.Errorf("%s was dead-lettered with reason %q, want expired", job, reason)
		}
	}
}

// **A publisher's TTL never ends a job.** `job_expires_after` is the only
// clock that removes work from a queue, and it is the operator's. What a
// publisher's Message Expiry does instead is arrive on the delivery, as
// `saguin-expires`, and the worker decides: ignore it and acknowledge, or
// do it anyway and acknowledge.
//
// **This was the other way round for one commit, and the reasoning that
// changed it is worth keeping.** The argument for expiring was that a
// queue has no replay to tear a hole in, so invariant 1's reason for
// leaving channel records alone does not apply, and MQTT itself deletes an
// expired message that was never delivered. What that missed is whose
// decision it is. The operator has `job_expires_after` for exactly this
// and chose not to set one; a client should not be able to take work out of
// their queue. It also filed the job under `expired` beside
// `attempts_exhausted`, which reads as work that failed when it is work
// nobody ever attempted.
//
// So one rule rather than two: the publisher's clock removes nothing saguin
// was asked to store, on any channel type. It deletes only a retained value
// on a broadcast topic, which is MQTT's own store and has no consumer
// position to damage.
func TestAPublishersTTLDoesNotEndAJob(t *testing.T) {
	h := start(t) // no job_expires_after at all
	p := connect(t, h, "producer", true, false)

	d := connect(t, h, "dlq-reader", true, false)
	d.Sub(t, "jobs/__dlq/#", 1)

	pub := dialProps(t, h, "timed-producer")
	second := uint32(1)
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/spent", QoS: 1, Payload: []byte("spent"),
		Properties: &paho.PublishProperties{MessageExpiry: &second},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	_ = p

	// Well past the publisher's deadline, and past several turns of the
	// sweep at its one-second floor, so a sweep that was going to take it
	// has had its chance.
	time.Sleep(3 * time.Second)

	// Nothing was dead-lettered.
	if r, ok := d.Await(t, time.Second); ok {
		t.Errorf("a job was dead-lettered as %q on a publisher's TTL; only "+
			"job_expires_after removes work, and the operator set none",
			r.User["saguin-dlq-reason"])
	}

	// And a worker is still handed it, with the deadline on it so it can
	// decide for itself.
	w := dialProps(t, h, "worker-1")
	w.Sub(t, "$saguin/queue/jobs", 1)

	got := awaitProp(t, w)
	if got == nil {
		t.Fatal("the worker was handed nothing: the job was removed or withheld " +
			"on a clock that is not the operator's")
	}
	if string(got.Payload) != "spent" {
		t.Fatalf("payload %q, want \"spent\"", got.Payload)
	}

	var raw string
	for _, u := range got.Properties.User {
		if u.Key == "saguin-expires" {
			raw = u.Value
		}
	}
	if raw == "" {
		t.Fatal("the job arrived with no saguin-expires, so the worker has nothing " +
			"to decide on - which is the whole of what replaced expiring it")
	}
	at, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		t.Fatalf("saguin-expires is %q", raw)
	}
	if at > time.Now().UnixMilli() {
		t.Errorf("saguin-expires is %d, which is in the future for a job whose "+
			"publisher gave it one second three seconds ago", at)
	}
}

// The operator's clock still ends a job, and that is the half this change
// left alone: `job_expires_after` removes work whether or not a worker is
// there to be offered it, which is the case the sweep exists for.
func TestTheOperatorsClockStillEndsAJob(t *testing.T) {
	h := startExpiring(t, 1)
	p := connect(t, h, "producer", true, false)

	d := connect(t, h, "dlq-reader", true, false)
	d.Sub(t, "jobs/__dlq/#", 1)

	p.Pub(t, "jobs/a", "job-a")

	r, ok := d.Await(t, 6*time.Second)
	if !ok {
		t.Fatal("a job outlived job_expires_after with no worker connected")
	}
	if r.User["saguin-dlq-reason"] != "expired" {
		t.Errorf("dead-lettered with reason %q, want expired", r.User["saguin-dlq-reason"])
	}
}

// Invariant 10: the broker is the only enforcement point.
//
// OnSubscribe answers a reason code, and a hook that says "refuse this"
// depends on the server acting on it. mochi v2.7.9 does not - it ignores
// ReasonCodes - so for a while saguin logged a refusal and the
// subscription was granted anyway. A substrate obliging is not the broker
// enforcing.
//
// This asserts the harm rather than the SUBACK, because the SUBACK is
// exactly the thing that cannot be trusted here: an assertion about the
// reason code is true on one substrate, and an assertion about where the
// work ends up is true on any of them.
//
// The QoS 0 case is the one that loses work. Such a subscriber receives
// jobs, has no PUBACK to start a visibility deadline from (invariant 7),
// and takes them with it when it goes - no deadline ever runs, so nothing
// is redelivered and no worker is offered them again. That is invariant
// 2's failure reached through a subscription the broker believes it
// refused.
func TestWorkSurvivesASubscriptionSaguinRefused(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	// Refused: QoS 0 on the canonical queue form. If the substrate grants
	// it anyway, this client is handed the job below.
	ghost := connect(t, h, "ghost", true, false)
	_, _ = ghost.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "$saguin/queue/jobs", QoS: 0}},
	})
	ghost.Sub(t, "loose/marker/ghost", 1)

	p.Pub(t, "jobs/a", "work")
	fedOnlyTheMarker(t, h, p, ghost, "loose/marker/ghost", "a subscriber saguin refused "+
		"was handed the job: the substrate granted a subscription the broker said no to "+
		"(invariant 10)")

	// And the job is still there for a worker that subscribed properly -
	// which it is not if the ghost took it, because a QoS 0 delivery
	// starts no visibility deadline and nothing ever brings it back.
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	if r, ok := w.Await(t, 5*time.Second); !ok {
		t.Error("the job never reached a properly subscribed worker: it went to a " +
			"subscriber that cannot acknowledge, and no deadline was ever running " +
			"to bring it back (invariants 2 and 7)")
	} else if r.Payload != "work" {
		t.Errorf("the worker got %q, want work", r.Payload)
	}
}

// Invariant 4, the post-grant layer: a queue subscription saguin refused
// that the substrate grants anyway closes the connection rather than
// reaching a worker (OnSubscribed).
//
// Unreachable from the wire with this substrate, which honours every reason
// code at or above 0x80 before it touches the topic index - which is why no
// test noticed this layer's deletion. So
// the hook is handed what a substrate that ignored the code would hand it:
// the refused filter, with a granting reason code. The control asks the
// same filter over the wire first, and it must be refused there, or this
// would be testing a filter nothing refuses.
func TestAQueueSubscriptionGrantedDespiteItsRefusalClosesTheConnection(t *testing.T) {
	for _, f := range []packets.Subscription{
		{Filter: "jobs/+", Qos: 1}, // a wildcard reaching a queue
		{Filter: "jobs/#", Qos: 1},
		{Filter: "jobs/a", Qos: 0}, // a queue at QoS 0 starts no deadline
	} {
		t.Run(fmt.Sprintf("%s at QoS %d", f.Filter, f.Qos), func(t *testing.T) {
			h := start(t)
			ctl := connect(t, h, "control", true, false)
			// paho answers a refusal with the SUBACK and an error beside it,
			// so the SUBACK is what is read.
			ack, err := ctl.C.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{{Topic: f.Filter, QoS: f.Qos}}})
			if ack == nil || len(ack.Reasons) != 1 || ack.Reasons[0] < 0x80 {
				t.Fatalf("the control's SUBACK was %v (%v) for %s: nothing refuses this filter, "+
					"so the case below tests nothing", ack, err, f.Filter)
			}

			w := connect(t, h, "worker", true, false)
			cl, ok := h.Srv.Clients.Get("worker")
			if !ok {
				t.Fatal("the worker is not in the server's client table")
			}
			h.B.OnSubscribed(cl, packets.Packet{FixedHeader: packets.FixedHeader{Type: packets.Subscribe},
				Filters: packets.Subscriptions{f}}, []byte{f.Qos})
			select {
			case d := <-w.Gone:
				if d.ReasonCode != packets.ErrQosNotSupported.Code {
					t.Errorf("the connection was closed with 0x%02X, want 0x%02X",
						d.ReasonCode, packets.ErrQosNotSupported.Code)
				}
			case <-time.After(2 * time.Second):
				t.Fatalf("a refused subscription to %s granted at QoS %d left the connection open",
					f.Filter, f.Qos)
			}
		})
	}
}

// fedOnlyTheMarker publishes an end marker to a broadcast topic c holds a
// granted subscription to, and asserts it is the first and only thing c is
// sent - and still the only thing once the queue's offer loop has gone round
// twice more. What c must not be sent was published before the marker, so it
// would arrive first by the same publisher's road, and a queue's offer runs on
// that tick: a quiet period watched both for a while, this waits for both.
func fedOnlyTheMarker(t *testing.T, h *harness, p, c *client, marker, why string) {
	t.Helper()
	p.Pub(t, marker, "marker")
	r, ok := c.Await(t, 5*time.Second)
	if !ok {
		t.Fatalf("the end marker on %s never arrived, so nothing below is evidence", marker)
	}
	if r.Payload != "marker" {
		t.Errorf("%s: it was sent %q on %q before the end marker", why, r.Payload, r.Topic)
		return
	}
	ticked(t, h, 2)
	if n := c.Count(); n != 1 {
		t.Errorf("%s: it was sent %d messages, want only the end marker", why, n)
	}
}

// The other refused forms, asserted the same way: a refused subscriber
// receives nothing from the channel it asked for.
func TestARefusedSubscriberIsFedNothing(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	for _, tc := range []struct{ name, filter, topic, payload string }{
		{"a wildcard-free subscription to a queue topic", "jobs/build", "jobs/build", "job"},
		{"the queue's own filter", "jobs/#", "jobs/urgent", "job"},
		{"a level after the channel name", "$saguin/queue/jobs/urgent", "jobs/urgent/x", "job"},
		{"an append channel's name in the queue space", "$saguin/queue/events", "events/a", "event"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := connect(t, h, "refused-"+tc.topic, true, false)
			_, _ = c.C.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{{Topic: tc.filter, QoS: 1}},
			})
			marker := "loose/marker/" + tc.topic
			c.Sub(t, marker, 1)

			p.Pub(t, tc.topic, tc.payload)
			fedOnlyTheMarker(t, h, p, c, marker, tc.filter+": a refused subscriber was "+
				"sent a record (invariant 10)")
		})
	}
}

// RFC 0003 "Moving a consumer's position"
//
// A consumer that needs to replay after a bug, or to skip a backlog it no
// longer wants, moves its own position. Nothing about that requires an
// operator, and nothing about it removes a record.
func TestAConsumerMovesItsOwnPosition(t *testing.T) {
	h := start(t)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 4; i++ {
		p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
	}

	// Read the lot, so the stored position is past everything.
	c := connectDurable(t, h, "reader")
	c.Sub(t, "events/#", 1)
	for i := 1; i <= 4; i++ {
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatalf("record %d never arrived", i)
		}
	}

	if got := c.Seek(t, "events", "2").Payload; got != "2" {
		t.Fatalf("the reply was %q, want the offset it stored", got)
	}

	// The replay arrives on the connection that asked for it. Nothing is
	// disconnected, unsubscribed, or reconnected.
	var got []string
	for i := 0; i < 3; i++ {
		r, ok := c.Await(t, 3*time.Second)
		if !ok {
			break
		}
		got = append(got, r.Payload)
	}
	want := []string{"order-2", "order-3", "order-4"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("after seeking to 2 the consumer got %v, want %v", got, want)
	}
}

// A consumer says "the beginning" and "from now on" without asking the
// broker where either is, because the answer can change between the
// question and the seek.
func TestSeekSentinelsNeedNoKnowledgeOfTheChannel(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
	}

	t.Run("-1 is the end", func(t *testing.T) {
		c := connectDurable(t, h, "to-the-end")
		c.Sub(t, "events/#", 1)
		for i := 1; i <= 3; i++ {
			c.Await(t, 3*time.Second)
		}
		if got := c.Seek(t, "events", "-1").Payload; got != "4" {
			t.Fatalf("-1 stored %q, want 4 - the offset the next record gets", got)
		}
		gone(t, c)

		again := connectDurable(t, h, "to-the-end")
		again.Sub(t, "events/#", 1)
		if r, ok := again.Await(t, time.Second); ok {
			t.Errorf("a consumer at the end was sent %q", r.Payload)
		}
		p.Pub(t, "events/order/4", "order-4")
		r, ok := again.Await(t, 3*time.Second)
		if !ok || r.Payload != "order-4" {
			t.Errorf("a consumer at the end missed what came after it: %v %q", ok, r.Payload)
		}
	})

	t.Run("0 is the floor", func(t *testing.T) {
		c := connectDurable(t, h, "to-the-start")
		c.Sub(t, "events/#", 1)
		for i := 0; i < 4; i++ {
			c.Await(t, 3*time.Second)
		}
		if got := c.Seek(t, "events", "0").Payload; got != "1" {
			t.Fatalf("0 stored %q, want 1 - this channel's floor", got)
		}
		if r, ok := c.Await(t, 3*time.Second); !ok || r.Payload != "order-1" {
			t.Errorf("a consumer at the floor started at %q, want order-1", r.Payload)
		}
	})
}

// RFC 0003 "Moving a consumer's position"
//
// A refused seek says so on the acknowledgement, not only on the Response
// Topic.
//
// **The Response Topic is optional and the acknowledgement is not.** RFC
// 0003 says a client may set no Response Topic and `mosquitto_pub` never
// does - and for such a client every seek used to acknowledge 0x00, whether
// the broker had moved the position or thrown the request away as
// malformed. A consumer that believes it moved and did not goes on reading
// from somewhere other than where it thinks it is, and nothing anywhere
// says otherwise: the request reported success and did nothing, which is
// the failure this repository ranks above a crash.
//
// It was found by the link-churn soak, which issued 266 seeks carrying a
// payload this broker has never accepted and counted every one as a
// success, because that is all the acknowledgement gave it to count.
//
// 0x83 with the reason, which is what a refused point read already answers.
func TestARefusedSeekSaysSoOnTheAcknowledgement(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/a/1", "one")

	// No Response Topic anywhere here: this is the client that had nothing
	// to read, and the acknowledgement is the whole of what it gets.
	c := connectDurable(t, h, "quiet-seeker")
	c.Sub(t, "events/#", 1)

	for _, tc := range []struct {
		name    string
		payload string
		want    byte
	}{
		{"a valid offset", "-1", 0x00},
		{"the floor", "0", 0x00},
		{"not a number at all", `{"position":"start"}`, 0x83},
		{"beyond the end", "99999", 0x83},
		{"below the floor", "-7", 0x83},
		// Days are digits and a fraction, and a count a Duration can hold:
		// strconv would also read these, and the last two convert to a moment
		// in 1734 on amd64 and to whatever another platform makes of it.
		{"a week", "7d", 0x00},
		{"the most days a duration holds", "106751d", 0x00},
		{"not a number of days", "NaNd", 0x83},
		{"infinitely many days", "Infd", 0x83},
		{"days as an exponent", "1e300d", 0x83},
		{"days with a digit separator", "1_0d", 0x83},
		{"more days than a duration holds", "106752d", 0x83},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := c.SeekQuietly(t, "events", tc.payload); got != tc.want {
				t.Errorf("seeking to %q was acknowledged 0x%02X, want 0x%02X: a client "+
					"with no Response Topic reads the acknowledgement or nothing",
					tc.payload, got, tc.want)
			}
		})
	}
}

// Both bounds are refused rather than clamped. Clamping manufactures the
// state a position must never be in: a consumer that asked for one place,
// was silently given another, and processes the remainder concluding it
// saw everything.
func TestASeekOutsideTheChannelIsRefusedAtBothEnds(t *testing.T) {
	t.Run("beyond the end", func(t *testing.T) {
		h := start(t)
		connect(t, h, "producer", true, false).Pub(t, "events/one", "1")

		c := connectDurable(t, h, "greedy")
		r := c.Seek(t, "events", "99")
		if r.Payload != "beyond-end" {
			t.Fatalf("a seek past the end answered %q", r.Payload)
		}
		if r.User["saguin-next"] != "2" {
			t.Errorf("the reply does not say where the end is: %v", r.User)
		}
	})

	t.Run("below the floor", func(t *testing.T) {
		// Retention has to have removed something for a floor to be above
		// 1, which is the only way an offset can be below it.
		h := startTrimming(t, map[string]int64{"events": 1})
		p := connect(t, h, "producer", true, false)
		for i := 1; i <= 6; i++ {
			p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
		}

		// `0` answers with the floor, so it is how this test finds out
		// whether retention has moved yet - and it keeps "the floor never
		// rose" apart from "the seek was not refused", which are different
		// failures and would otherwise share one message.
		var floor string
		deadline := time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			c := connectDurable(t, h, fmt.Sprintf("probe-%d", time.Now().UnixNano()))
			floor = c.Seek(t, "events", "0").Payload
			_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
			if floor != "1" {
				break
			}
			time.Sleep(200 * time.Millisecond)
		}
		if floor == "1" {
			t.Fatal("retention never moved the floor, so nothing was below it")
		}

		c := connectDurable(t, h, "nostalgic")
		r := c.Seek(t, "events", "1")
		if r.Payload != "below-floor" {
			t.Fatalf("a seek to 1 under a floor of %s answered %q", floor, r.Payload)
		}
		if r.User["saguin-floor"] != floor {
			t.Errorf("the reply says the floor is %q, want %q", r.User["saguin-floor"], floor)
		}
	})
}

// A queue's records have exactly one consumer each and a latest channel
// holds no history, so neither has a position to move.
//
// The refusal is the `PUBACK`, not a reply, because which channel the topic
// names is a property of the topic (RFC 0002 "Publishing"). It is also the
// only answer that always arrives: a reply needs the client to have set a
// Response Topic and to have stayed connected, and `mosquitto_pub` does
// neither. The Reason String says which kind of channel it actually is,
// which is the whole difference between "fix the name" and "you wanted a
// different channel".
func TestSeekingIsRefusedWhereThereIsNoPositionToMove(t *testing.T) {
	h := start(t)
	for _, tc := range []struct{ name, ch, want string }{
		{"a queue", "jobs", "is a queue, not an append channel"},
		{"a latest channel", "state", "is a latest channel, not an append channel"},
		{"a channel that does not exist", "nowhere", "there is no channel named"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := connectAsking(t, h, "seeker-"+tc.ch)
			ack, err := c.Publish(context.Background(), &paho.Publish{
				Topic: "$saguin/consumer/" + tc.ch + "/seek", QoS: 1, Payload: []byte("1"),
			})
			if ack == nil {
				t.Fatalf("no PUBACK: %v", err)
			}
			if ack.ReasonCode != 0x90 {
				t.Fatalf("seeking %s answered 0x%02X, want 0x90 Topic Name invalid",
					tc.ch, ack.ReasonCode)
			}
			got := ""
			if ack.Properties != nil {
				got = ack.Properties.ReasonString
			}
			if !strings.Contains(got, tc.want) {
				t.Errorf("the reason is %q, which does not say %q", got, tc.want)
			}
			t.Logf("0x%02X %q", ack.ReasonCode, got)
		})
	}
}

// A worker answering on a topic that is not a queue's response topic is
// refused the same way and for the same reason, and this is the half that
// has no other way to be told: RFC 0003 gives a response no reply at all,
// so a worker with a typo would otherwise acknowledge into silence while
// its jobs were redelivered and dead-lettered as `attempts_exhausted`.
func TestRespondingToSomethingThatIsNotAQueueIsRefused(t *testing.T) {
	h := start(t)
	for _, tc := range []struct{ name, ch, want string }{
		{"an append channel", "events", "is an append channel, not a queue"},
		{"a latest channel", "state", "is a latest channel, not a queue"},
		{"a queue that does not exist", "nowhere", "there is no channel named"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := connectAsking(t, h, "worker-"+tc.ch)
			ack, err := c.Publish(context.Background(), &paho.Publish{
				Topic: "$saguin/queue/" + tc.ch + "/response", QoS: 1, Payload: []byte("ack"),
				Properties: &paho.PublishProperties{CorrelationData: []byte("whatever")},
			})
			if ack == nil {
				t.Fatalf("no PUBACK: %v", err)
			}
			if ack.ReasonCode != 0x90 {
				t.Fatalf("responding to %s answered 0x%02X, want 0x90 Topic Name invalid",
					tc.ch, ack.ReasonCode)
			}
			got := ""
			if ack.Properties != nil {
				got = ack.Properties.ReasonString
			}
			if !strings.Contains(got, tc.want) {
				t.Errorf("the reason is %q, which does not say %q", got, tc.want)
			}
			t.Logf("0x%02X %q", ack.ReasonCode, got)
		})
	}
}

// The dead-letter channel a queue derives is an append channel in every
// respect, and replaying one after fixing whatever dead-lettered the work
// is a normal thing to want.
func TestADeadLetterChannelAcceptsASeek(t *testing.T) {
	h := start(t)
	c := connectDurable(t, h, "dlq-reader")
	if got := c.Seek(t, "jobs__dlq", "0").Payload; got != "1" {
		t.Errorf("seeking the dead-letter channel answered %q, want its floor", got)
	}
}

// A position is stored per session. A client whose session ends with its
// connection has nothing that outlives it, so a seek would be stored and
// then discarded - worse than being told.
//
// **What decides that is the Session Expiry Interval, not Clean Start.**
// This test used to connect Clean Start = 1 *with* an expiry of an hour and
// assert the refusal, which pinned the defect rather than the rule: that is
// a durable session by MQTT 5, and the broker stored and honoured its
// position while refusing to move it. The session-less client is the one
// that sets no expiry.
func TestASeekNeedsADurableSession(t *testing.T) {
	h := start(t)
	c := connectExpiring(t, h, "ends-with-the-connection") // Session Expiry 0
	if got := c.Seek(t, "events", "1").Payload; got != "no-session" {
		t.Errorf("a client whose session ends with its connection seeked and got "+
			"%q, want no-session", got)
	}
}

// RFC 0003 "Moving a consumer's position"
//
// A consumer that opened Clean Start = 1 with a Session Expiry Interval can
// seek, and this is the ordinary case rather than an exotic one: starting
// from a known state and then reconnecting Clean Start = 0 is how a durable
// consumer is written.
//
// The broker refused it while storing its position anyway, so the two halves
// are asserted together - the seek is answered, and the same session comes
// back with Session Present = 1 having kept what the seek did to it. Either
// on its own passes with the contradiction still in place.
func TestACleanStartWithAnExpiryIsADurableSession(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 4; i++ {
		p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
	}

	// Clean Start = 1, Session Expiry 3600: a new session, and a durable one.
	c := connect(t, h, "first-timer", true, false)
	c.Sub(t, "events/#", 1)
	for i := 1; i <= 4; i++ {
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatalf("record %d never arrived", i)
		}
	}

	if got := c.Seek(t, "events", "2").Payload; got != "2" {
		t.Fatalf("a Clean Start = 1 consumer with an expiry seeked and got %q, want "+
			"the offset it stored: its session outlives this connection, so there "+
			"is a position to move", got)
	}

	// It takes effect here, as it does for any other durable consumer.
	for _, want := range []string{"order-2", "order-3", "order-4"} {
		r, ok := c.Await(t, 3*time.Second)
		if !ok || r.Payload != want {
			t.Fatalf("after seeking to 2 it got %v %q, want %q", ok, r.Payload, want)
		}
	}

	// And the session really was durable, which is what made the refusal a
	// contradiction rather than a policy.
	gone(t, c)
	again := connect(t, h, "first-timer", false, false)
	if !again.SessionPresent {
		t.Error("the session did not survive, so the refusal would have been right")
	}
}

// A seek payload is an offset, a duration, or an RFC 3339 moment, and
// anything else is refused rather than guessed at. `1.5` and `0x10` are
// the interesting rows: both are numbers a reader might expect the broker
// to take, and taking either would mean inventing a rule about what it
// meant.
func TestASeekPayloadIsOneNumber(t *testing.T) {
	h := start(t)
	for _, payload := range []string{"banana", "", "1.5", "-2", "0x10", "1 2",
		// A date that is not RFC 3339, and a word: both are close enough to
		// a valid request to be worth refusing loudly. A bare `12` is NOT
		// here, because a bare integer is an offset by design - that rule
		// is what stops 1763000000 being read as a Unix time by a broker
		// and as an offset by the client that sent it.
		"2026-08-14", "yesterday"} {
		c := connectDurable(t, h, "malformed-"+payload)
		if got := c.Seek(t, "events", payload).Payload; got != "malformed" {
			t.Errorf("payload %q answered %q, want malformed", payload, got)
		}
	}
}

// A consumer that has not started reading the channel has no stream to
// disturb, so there is nothing for the seek to wait for. Seek first and
// subscribe second and it applies in the same session; subscribe first and
// the reconnect is what applies it.
func TestASeekBeforeReadingAppliesToTheNextSubscribe(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 4; i++ {
		p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
	}

	c := connectDurable(t, h, "not-yet-reading")
	if got := c.Seek(t, "events", "3").Payload; got != "3" {
		t.Fatalf("the reply was %q, want 3", got)
	}
	c.Sub(t, "events/#", 1)

	r, ok := c.Await(t, 3*time.Second)
	if !ok || r.Payload != "order-3" {
		t.Errorf("a consumer that seeked before subscribing got %v %q, want order-3", ok, r.Payload)
	}
}

// A consumer that seeks and then carries on working must not have its seek
// quietly undone by the position its own reading would otherwise store.
//
// A seek used to be held until the next connect, so "carrying on" meant
// reading past the seek and the stored position had to survive it. It now
// reaches the stream the consumer is reading, so carrying on means reading
// the replay - and what must not happen is the offset the stream had already
// reached being written over the place the consumer asked for, which leaves
// the replay undelivered with nothing reported.
func TestASeekIsNotUndoneByTheReadingThatFollowsIt(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 4; i++ {
		p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
	}

	c := connectDurable(t, h, "still-working")
	c.Sub(t, "events/#", 1)
	for i := 1; i <= 4; i++ {
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatalf("record %d never arrived", i)
		}
	}

	c.SeekQuietly(t, "events", "2")

	for _, want := range []string{"order-2", "order-3", "order-4"} {
		r, ok := c.Await(t, 3*time.Second)
		if !ok || r.Payload != want {
			t.Fatalf("after seeking to 2 the consumer got %v %q, want %q", ok, r.Payload, want)
		}
	}

	// And the position followed the replay, rather than sticking at the seek
	// or being thrown back to where the stream had been.
	//
	// **`order-4` is a correct answer here and `order-2` is not**, which is
	// the whole of what this checks. On automatic acknowledgement Paho writes
	// the PUBACK from its own reading goroutine once the handler returns,
	// while `gone` sends its barrier publish from this one - so the barrier
	// can overtake the last acknowledgement, and the position is then
	// recorded one short. The consumer is redelivered `order-4`, which is
	// at-least-once working exactly as invariant 6 describes: a record whose
	// acknowledgement did not land is sent again.
	//
	// Demanding `order-5` demanded a durability MQTT does not offer at that
	// instant, and it failed under a loaded suite for that reason and no
	// other. What must not happen is the seek being undone - that shows up
	// as `order-2`, and the replay assertion above would have failed first.
	gone(t, c)
	again := connectDurable(t, h, "still-working")
	again.Sub(t, "events/#", 1)
	p.Pub(t, "events/order/5", "order-5")

	r, ok := again.Await(t, 3*time.Second)
	if !ok {
		t.Fatalf("after replaying, the consumer resumed and was sent nothing at all")
	}
	switch r.Payload {
	case "order-5":
		// The acknowledgement landed before the disconnect: the position is
		// exactly where the replay left it.
	case "order-4":
		// The last acknowledgement did not land in time, so the record is
		// redelivered and `order-5` is behind it.
		next, ok := again.Await(t, 3*time.Second)
		if !ok || next.Payload != "order-5" {
			t.Errorf("after the redelivered order-4 the consumer got %v %q, want order-5",
				ok, next.Payload)
		}
	default:
		t.Errorf("after replaying, the consumer resumed at %q - anything before order-4 "+
			"means the replay's position was thrown away rather than stored", r.Payload)
	}
}

// RFC 0003 "Moving a consumer's position"
//
// A seek reaches the stream the consumer is already reading. It waits for no
// reconnect, no unsubscribe, and nothing else the consumer has to remember
// to do.
//
// The records on the wire when it arrives are what makes this hard, and they
// are why the seek used to be held: a PUBACK for one of them landing
// afterwards would advance the position past where the consumer just asked
// to be - silently, in the direction that skips. The seek now discards what
// is outstanding and ends the cursor's era, so those acknowledgements stop
// counting. TestAStaleAcknowledgementCannotMoveThePositionPastASeek is that
// rule where a test can watch the acknowledgement arrive; this is the
// behaviour it buys.
func TestASeekReachesTheStreamTheConsumerIsReading(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, fmt.Sprintf("events/order/%d", i), fmt.Sprintf("order-%d", i))
	}

	c := connectDurable(t, h, "mid-session")
	c.Sub(t, "events/#", 1)
	for i := 1; i <= 3; i++ {
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatalf("record %d never arrived", i)
		}
	}

	c.SeekQuietly(t, "events", "0")

	// Restarted at the floor, on this connection.
	for _, want := range []string{"order-1", "order-2", "order-3"} {
		r, ok := c.Await(t, 3*time.Second)
		if !ok || r.Payload != want {
			t.Fatalf("after a seek to the floor the consumer got %v %q, want %q", ok, r.Payload, want)
		}
	}
}

// RFC 0002 "Bridges"
//
// The link itself, against a real second broker rather than a fake one: a
// bridge that only ever ran against a stub would pass while getting the MQTT
// wrong, and the MQTT is most of what a bridge is.
//
// It cuts the link mid-stream, because that is the case the whole design
// turns on. saguin holds no buffer of its own - the upstream's session is the
// buffer - so a bridge that reconnected without its session, or that
// acknowledged before storing, loses exactly the records published while it
// was away and nothing reports it.
func TestABridgeCarriesRecordsAcrossACutLink(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)

	// The bridge reaches the upstream through a proxy the test can cut, so
	// that the outage is a real one and lasts as long as the test says. A
	// server-side disconnect is not the same thing: autopaho reconnects
	// within a millisecond or two, so records "published while the link was
	// down" race the teardown and the test asserts whatever it won.
	link := newProxy(t, upstreamAddr)

	cfg := bridgeConfig(t, link.Addr)
	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	if testing.Verbose() {
		log = slog.New(slog.NewTextHandler(newTestWriter(t), &slog.HandlerOptions{Level: slog.LevelInfo}))
	}
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})

	// A consumer on saguin's side, reading what the bridge brings in.
	reader := connect(t, h, "reader", true, false)
	reader.Sub(t, "events/#", 1)

	// A producer on the upstream, which is a different broker entirely and
	// has never heard of a channel. It connects directly rather than through
	// the proxy, so that cutting the bridge's link does not cut its own.
	prod := dialUpstream(t, upstreamAddr, "vessel-sensor")
	send := func(t testing.TB, n int, from int) {
		t.Helper()
		for i := from; i < from+n; i++ {
			ack, err := prod.Publish(context.Background(), &paho.Publish{
				Topic:   "fleet/vessel-07/telemetry/hold/psi",
				QoS:     1,
				Payload: fmt.Appendf(nil, "reading-%d", i),
			})
			if err != nil || ack == nil || ack.ReasonCode > 1 {
				t.Fatalf("publish %d peer: %v", i, err)
			}
		}
	}

	// Wait for the bridge to be subscribed before publishing anything: a
	// record published before its SUBSCRIBE lands is not lost by the bridge,
	// it was never sent to it, and a test that raced there would be flaky
	// about the wrong thing.
	waitForBridge(t, upstream, cfg.ClientID)

	send(t, 5, 0)
	got := collect(t, reader, 5, 5*time.Second)
	if len(got) != 5 {
		t.Fatalf("before the cut: %d of 5 records arrived: %v", len(got), payloads(got))
	}

	// Cut it, and hold it down. The upstream stays up and keeps saguin's
	// session, which is exactly the deployment this is for: the link is what
	// fails, not the broker at the other end.
	link.Cut()

	// Published while the bridge is away, so the upstream's session is the
	// only thing holding them.
	send(t, 5, 5)

	// Nothing reaches saguin while the link is down. Without this the test
	// would pass just as well against a bridge that never lost the link at
	// all, which is the thing it is supposed to be testing.
	if extra, more := reader.Await(t, time.Second); more {
		t.Fatalf("a record arrived while the link was cut: %q", extra.Payload)
	}

	link.Restore()

	// autopaho reconnects on its own; the records follow. Collected by what
	// is still missing rather than by a count, because the reconnect may
	// also redeliver records saguin already has - see below.
	got = append(got, collectUntil(t, reader, 30*time.Second, func(have []received) bool {
		return len(distinct(append(append([]received(nil), got...), have...))) == 10
	})...)

	seen := distinct(got)
	for i := range 10 {
		if want := fmt.Sprintf("reading-%d", i); !seen[want] {
			t.Errorf("%s never arrived, so the upstream session did not hold what was "+
				"published while the link was down", want)
		}
	}

	// Every record that did arrive was stored rather than merely fanned out
	// to whoever was subscribed.
	for _, r := range got {
		if r.User["saguin-offset"] == "" {
			t.Errorf("%q carries no offset, so it was not stored", r.Payload)
		}
	}

	// Duplicates are permitted here and only here, and it is worth being
	// exact about why rather than tolerating them generally.
	//
	// Paho does not send a PUBACK when saguin acknowledges a record; it marks
	// it, and a ticker sends what has been marked. A link cut inside that
	// window leaves the upstream believing records it delivered are still
	// unacknowledged, so it redelivers them on the reconnect - and a record
	// from a foreign broker carries no saguin identity, so saguin mints a new
	// Message ID and it becomes a second record at its own offset. That is
	// the cost RFC 0002 accepts, and this is what it looks like.
	//
	// What is not permitted is a duplicate with no cut behind it, which is
	// why the five before the cut were counted exactly.
	if dup := len(got) - len(seen); dup > 0 {
		t.Logf("%d record(s) were redelivered across the cut and became separate records; "+
			"that is the duplicate RFC 0002 accepts, not a defect", dup)
	}
}

// RFC 0002 "Bridges"
//
// A saguin restart must not throw away the backlog the upstream is holding.
// The bridge connects with Clean Start off *on its first connection too*,
// which is the only thing standing between a restart and a silent gap: a
// bridge that cleared its session on startup would tell the upstream to
// discard everything it had kept, and the records published while saguin was
// down would go with no error anywhere.
//
// The cut-link test above does not cover this. autopaho applies Clean Start
// only to the first connection of a process, so a reconnect keeps the
// session whatever that setting says - and a bridge with it set wrongly
// passes that test and loses data here.
func TestABridgeResumesItsSessionAfterARestart(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)
	cfg := bridgeConfig(t, upstreamAddr)

	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	if testing.Verbose() {
		log = slog.New(slog.NewTextHandler(newTestWriter(t), &slog.HandlerOptions{Level: slog.LevelInfo}))
	}

	// run starts a bridge and returns the function that stops it, which is
	// what a saguin restart looks like from the upstream's point of view.
	run := func() func() {
		br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
		ctx, cancel := context.WithCancel(context.Background())
		done := make(chan struct{})
		go func() { defer close(done); _ = br.Run(ctx) }()
		return func() {
			cancel()
			select {
			case <-done:
			case <-time.After(5 * time.Second):
				t.Error("the bridge did not stop")
			}
		}
	}

	reader := connect(t, h, "reader", true, false)
	reader.Sub(t, "events/#", 1)
	prod := dialUpstream(t, upstreamAddr, "vessel-sensor")
	send := func(t testing.TB, from, n int) {
		t.Helper()
		for i := from; i < from+n; i++ {
			if _, err := prod.Publish(context.Background(), &paho.Publish{
				Topic: "fleet/vessel-07/telemetry/hold/psi", QoS: 1,
				Payload: fmt.Appendf(nil, "reading-%d", i),
			}); err != nil {
				t.Fatalf("publish %d peer: %v", i, err)
			}
		}
	}

	stop := run()
	waitForBridge(t, upstream, cfg.ClientID)
	send(t, 0, 3)
	if got := collect(t, reader, 3, 5*time.Second); len(got) != 3 {
		t.Fatalf("before the restart: %d of 3 records arrived: %v", len(got), payloads(got))
	}

	// saguin stops. The upstream keeps the session, because that is what it
	// was asked to do.
	stop()
	// And it is properly gone before anything else is published. A record
	// written to a connection that is still being torn down is lost by the
	// upstream rather than by the bridge, and a test that raced there would
	// report a data loss saguin did not cause.
	waitForBridgeGone(t, upstream, cfg.ClientID)

	// Published into a session with nobody attached to it.
	send(t, 3, 3)

	// saguin comes back, with the same identity at the far end.
	defer run()()

	// Waiting for these three by name rather than for a count of three. The
	// resumed session may also redeliver the records saguin already had -
	// they were acknowledged inside Paho's ack interval - and counting would
	// be satisfied by those, stopping before the ones this test is about
	// ever arrived.
	want := map[string]bool{"reading-3": true, "reading-4": true, "reading-5": true}
	got := collectUntil(t, reader, 30*time.Second, func(have []received) bool {
		seen := distinct(have)
		for w := range want {
			if !seen[w] {
				return false
			}
		}
		return true
	})
	seen := distinct(got)
	for i := 3; i < 6; i++ {
		if want := fmt.Sprintf("reading-%d", i); !seen[want] {
			t.Errorf("%s never arrived, so the restart discarded the backlog the "+
				"upstream was holding", want)
		}
	}
}

// RFC 0002 "Bridges", "The three keys that tune a link"
//
// Two of the three only exist on the wire, in the CONNECT saguin sends: a
// Receive Maximum the upstream never sees is not backpressure, and a Session
// Expiry the upstream never sees is a bridge that holds no backlog. Reading
// them out of the configuration is not the same as sending them, and every
// test above this one passes either way - the values are the defaults there,
// so a bridge ignoring its configuration entirely still behaves correctly.
//
// So this one sets both to something the defaults are not, and asks the
// upstream what it was told.
func TestTheTuningKeysReachTheUpstream(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)
	cfg := bridgeConfig(t, upstreamAddr,
		"    session_expiry: 2h\n",
		"    receive_maximum: 7\n",
	)

	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})
	waitForBridge(t, upstream, cfg.ClientID)

	cl, ok := upstream.Clients.Get(cfg.ClientID)
	if !ok {
		t.Fatal("the bridge is not connected upstream")
	}
	if got := cl.Properties.Props.ReceiveMaximum; got != 7 {
		t.Errorf("the upstream was told a Receive Maximum of %d, want 7 - "+
			"a window the far end never hears about is not backpressure", got)
	}
	if got := cl.Properties.Props.SessionExpiryInterval; got != 7200 {
		t.Errorf("the upstream was told a Session Expiry of %ds, want 7200 - "+
			"a bridge whose session expiry never arrives holds no backlog", got)
	}
}

// **The third tuning key, which is the one with no wire footprint.**
//
// `session_expiry` and `receive_maximum` reach the upstream in the CONNECT,
// and the test above asks it what it was told. `ack_interval` never does:
// it is a ticker inside Paho, so the only thing it changes is *when* saguin
// answers - and the field feeding it was set at one line in
// internal/bridge and asserted nowhere, which is the shape this suite has
// found unwired five times in a fortnight.
//
// **Not a latency floor on one record.** The ticker free-runs, so a single
// record's delay is uniform in [0, interval): a record arriving a
// millisecond before a tick is acknowledged almost at once however long the
// interval is, and a test asserting otherwise fails on its own arithmetic.
//
// What the interval actually decides is *batching*, which is what RFC 0002
// says the knob is for - "the only reason to delay an acknowledgement is to
// batch the ones behind it". So: records published far enough apart that a
// short interval must answer each one separately, and an interval long
// enough that a correct bridge answers them in a handful of flushes. Twelve
// records 80ms apart against a 500ms interval is two or three flushes; at
// Paho's own 50ms default, or at saguin's 5ms, it is twelve.
//
// **One-sided**, which is what makes it safe on a loaded machine: every way
// of being slow batches the acknowledgements *harder* and lowers the count.
// Nothing but a shorter interval than the one configured raises it.
func TestTheAckIntervalBatchesTheAcknowledgementsBehindIt(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	// Added after the server is serving, which mochi allows - Hooks.Add
	// takes the lock and stores atomically - and before any client exists.
	clock := &pubackClock{}
	if err := upstream.AddHook(clock, nil); err != nil {
		t.Fatalf("upstream hook: %v", err)
	}

	h := start(t)
	// Receive Maximum well above the batch: this test is about when the
	// acknowledgement is sent, and a window that fills would stop the
	// upstream sending and confound the two. mochi does not resume
	// delivery once a subscriber's window is used up (see startUpstream).
	cfg := bridgeConfig(t, upstreamAddr,
		"    receive_maximum: 100\n",
		"    ack_interval: 500ms\n",
	)
	clock.Watch(cfg.ClientID)

	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})
	waitForBridge(t, upstream, cfg.ClientID)

	const (
		records = 12
		// Far enough apart that a bridge acknowledging each on arrival
		// produces twelve arrivals this far apart, and comfortably more
		// than the window a single flush is collapsed into below.
		spacing = 80 * time.Millisecond
	)
	prod := dialUpstream(t, upstreamAddr, "vessel-sensor")
	for i := range records {
		ack, err := prod.Publish(context.Background(), &paho.Publish{
			Topic:   "fleet/vessel-07/telemetry/hold/psi",
			QoS:     1,
			Payload: fmt.Appendf(nil, "reading-%d", i),
		})
		if err != nil || ack == nil || ack.ReasonCode > 1 {
			t.Fatalf("publish %d peer: %v", i, err)
		}
		time.Sleep(spacing)
	}

	// **Proof it drove something**, before anything is said about how the
	// acknowledgements were grouped: a bridge that received nothing sends
	// no acknowledgements at all, and every grouping assertion below is
	// vacuously true of an empty set. saguin acknowledges only once its own
	// store holds the record, so twelve of them is twelve records stored.
	at := clock.Await(t, records, 10*time.Second)
	if len(at) != records {
		t.Fatalf("the upstream saw %d acknowledgements from the bridge, want %d - "+
			"nothing below is a statement about batching if the records never arrived",
			len(at), records)
	}

	// A flush is acknowledgements written back to back down one connection.
	// 25ms against the 80ms the records were published at: three times the
	// separation, so a flush has to be delayed past a third of the publish
	// spacing before this miscounts, and being slower only merges flushes.
	const flushWindow = 25 * time.Millisecond
	flushes := 1
	for i := 1; i < len(at); i++ {
		if at[i].Sub(at[i-1]) > flushWindow {
			flushes++
		}
	}
	// Two is what a 500ms interval gives over 960ms of publishing; three is
	// the same run with the first tick landing early. Four is already more
	// than the interval can produce.
	if flushes > 4 {
		t.Errorf("twelve records published %v apart were acknowledged in %d separate "+
			"flushes, want at most 4 - a 500ms ack_interval batches them, so this is a "+
			"bridge acknowledging on some interval that is not the one configured "+
			"(Paho's own default is 50ms, saguin's is 5ms, and either gives twelve)",
			spacing, flushes)
	}
}

// RFC 0002's publish table: `0x99 Payload format invalid` when the Payload
// Format Indicator says UTF-8 and the payload is not.
//
// saguin treats a payload as opaque bytes everywhere else and this is not an
// exception to that. The indicator is the one claim a publisher makes *about*
// the bytes, and it exists so a consumer can treat them as text without
// checking - so a record stored under a false one is a decoding failure at a
// consumer that has no way to know the producer lied.
func TestAPayloadThatIsNotTheUTF8ItClaimsIsRefused(t *testing.T) {
	h := start(t)
	c := connect(t, h, "producer", true, false)
	one, zero := byte(1), byte(0)

	for _, tc := range []struct {
		name    string
		topic   string
		payload []byte
		format  *byte
		want    byte
	}{
		{"invalid UTF-8 claiming to be UTF-8", "events/a", []byte{0xff, 0xfe}, &one, 0x99},
		{"the same bytes into broadcast", "loose/a", []byte{0xff, 0xfe}, &one, 0x99},
		{"valid UTF-8 claiming to be UTF-8", "events/b", []byte("hello ☺"), &one, 0x00},
		// Unset or 0 means "unspecified bytes", and saguin does not look.
		{"invalid UTF-8 claiming nothing", "events/c", []byte{0xff, 0xfe}, nil, 0x00},
		{"invalid UTF-8 declared as bytes", "events/d", []byte{0xff, 0xfe}, &zero, 0x00},
		// An empty payload is valid UTF-8, and on a latest channel it is a
		// delete - which must not start answering 0x99.
		{"an empty payload", "state/k", nil, &one, 0x00},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := &paho.Publish{Topic: tc.topic, QoS: 1, Payload: tc.payload}
			if tc.format != nil {
				p.Properties = &paho.PublishProperties{PayloadFormat: tc.format}
			}
			ack, err := c.C.Publish(context.Background(), p)
			if ack == nil {
				t.Fatalf("no PUBACK: %v", err)
			}
			if ack.ReasonCode != tc.want {
				t.Errorf("answered 0x%02X, want 0x%02X", ack.ReasonCode, tc.want)
			}
		})
	}
}

// RFC 0001 "The protocol is MQTT 5, unmodified": Message Expiry Interval is
// per-message expiry, so a delivery carries one when the producer asked for
// one and none when it did not.
//
// The substrate's default was 24 hours, applied to any publish with no
// expiry of its own, and it reached only two of saguin's four delivery
// paths because saguin writes append and latest itself. A broadcast
// subscriber and a queue worker were handed
// `message-expiry-interval: 86400` on a record nobody gave an expiry to,
// and an append or latest consumer got nothing for the same record. Two
// consumers of one broker reading different metadata is the defect; the
// number itself meant nothing either way.
func TestDeliveriesCarryOnlyTheExpiryTheProducerAskedFor(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	paths := []struct{ name, filter, topic string }{
		{"broadcast", "loose/#", "loose/thing"},
		{"append", "events/#", "events/thing"},
		{"latest", "state/#", "state/thing"},
		{"queue", "$saguin/queue/jobs", "jobs/thing"},
	}
	subs := map[string]*propClient{}
	for _, tc := range paths {
		c := dialProps(t, h, "sub-"+tc.name)
		c.Sub(t, tc.filter, 1)
		subs[tc.name] = c
		subscribed(t, c.C)
	}

	// A publish with no expiry on it: nothing may add one.
	for _, tc := range paths {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: tc.topic, QoS: 1, Payload: []byte("bare"),
		}); err != nil {
			t.Fatalf("publish %s: %v", tc.topic, err)
		}
		got := awaitProp(t, subs[tc.name])
		if got == nil {
			t.Fatalf("%s: nothing delivered", tc.name)
		}
		if got.Properties != nil && got.Properties.MessageExpiry != nil {
			t.Errorf("%s: delivered with message-expiry-interval %d, which nobody set",
				tc.name, *got.Properties.MessageExpiry)
		}
	}

	// One the producer did set arrives as sent rather than capped at a day.
	// Broadcast only: a record is six fields and Message Expiry is not among
	// them (RFC 0003 "From publish to record"), so the three channel paths deliver what
	// was stored and nothing about the packet it arrived in.
	want := uint32(60)
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "loose/timed", QoS: 1, Payload: []byte("timed"),
		Properties: &paho.PublishProperties{MessageExpiry: &want},
	}); err != nil {
		t.Fatalf("publish loose/timed: %v", err)
	}
	got := awaitProp(t, subs["broadcast"])
	if got == nil || got.Properties == nil || got.Properties.MessageExpiry == nil {
		t.Fatal("broadcast: delivered with no message-expiry-interval, want the 60 that was sent")
	}
	if *got.Properties.MessageExpiry != want {
		t.Errorf("message-expiry-interval %d, want %d as sent",
			*got.Properties.MessageExpiry, want)
	}
}

// RFC 0003: a channel delivery carries `saguin-expires` when its publisher
// set a Message Expiry Interval, giving the moment that interval runs out
// rather than the seconds left.
//
// **It exists because MQTT's own field cannot say "expired".** On a channel
// an expired record is still served - a publisher must not remove records
// from another consumer's replay - so the countdown reaches zero and stays
// there. MQTT has no way to send that: the specification deletes an expired
// message instead of delivering one, so a zero never arises and the
// substrate writes the field only above zero. A delivery past the deadline
// therefore carries no expiry field at all, which is what a message that
// never had one looks like. This property is the difference, in saguin's
// own namespace where saguin is entitled to define what it means.
//
// **The moment rather than a flag**, because it says when. It is also
// stable: two consumers reading one record an hour apart see the same
// value, where MQTT's countdown gives each of them a different one.
func TestAChannelDeliveryCarriesTheMomentItsExpirySetRunsOut(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	pub := dialProps(t, h, "timed-producer")
	fiveMinutes := uint32(300)
	before := time.Now()
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "events/timed", QoS: 1, Payload: []byte("timed"),
		Properties: &paho.PublishProperties{MessageExpiry: &fiveMinutes},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	p.Pub(t, "events/bare", "bare")
	settle(t, p)

	sub := dialProps(t, h, "reader")
	sub.Sub(t, "events/#", 1)

	got := map[string]*paho.Publish{}
	for range 2 {
		r := awaitProp(t, sub)
		if r == nil {
			break
		}
		got[r.Topic] = r
	}
	if len(got) != 2 {
		t.Fatalf("replayed %d of 2 records", len(got))
	}

	prop := func(m *paho.Publish, key string) (string, bool) {
		if m == nil || m.Properties == nil {
			return "", false
		}
		for _, u := range m.Properties.User {
			if u.Key == key {
				return u.Value, true
			}
		}
		return "", false
	}

	raw, ok := prop(got["events/timed"], "saguin-expires")
	if !ok {
		t.Fatal("a record whose publisher set an expiry carried no saguin-expires, " +
			"so a consumer cannot tell a passed deadline from no deadline at all")
	}
	at, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		t.Fatalf("saguin-expires is %q, which is not Unix milliseconds", raw)
	}
	// Five minutes past the moment the broker received it, within a second
	// either way for the wait around the publish.
	want := before.Add(300 * time.Second).UnixMilli()
	if at < want-2000 || at > want+2000 {
		t.Errorf("saguin-expires is %d, want about %d: it is the receipt time plus "+
			"the publisher's interval", at, want)
	}

	// Matching the timestamp it sits beside: same units, so the difference
	// between the two is the interval the publisher asked for.
	stamped, ok := prop(got["events/timed"], "saguin-timestamp")
	if !ok {
		t.Fatal("no saguin-timestamp to compare against")
	}
	recv, err := strconv.ParseInt(stamped, 10, 64)
	if err != nil {
		t.Fatalf("saguin-timestamp is %q", stamped)
	}
	if at-recv != 300_000 {
		t.Errorf("saguin-expires minus saguin-timestamp is %dms, want the 300000 the "+
			"publisher asked for", at-recv)
	}

	// And a record nobody timed carries neither the deadline nor a claim
	// about one.
	if v, ok := prop(got["events/bare"], "saguin-expires"); ok {
		t.Errorf("a record whose publisher set no expiry carried saguin-expires=%q", v)
	}
}

// The same property once the deadline has passed, which is the case it
// exists for: the record is still served, MQTT's own countdown is gone, and
// the moment is in the past.
func TestAnExpiredChannelRecordStillSaysWhenItExpired(t *testing.T) {
	h := start(t)

	pub := dialProps(t, h, "timed-producer")
	second := uint32(1)
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "events/spent", QoS: 1, Payload: []byte("spent"),
		Properties: &paho.PublishProperties{MessageExpiry: &second},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	time.Sleep(2100 * time.Millisecond)

	sub := dialProps(t, h, "reader")
	sub.Sub(t, "events/#", 1)
	got := awaitProp(t, sub)
	if got == nil {
		t.Fatal("an expired record was not replayed; a publisher's expiry deletes " +
			"nothing from a channel")
	}

	var raw string
	for _, u := range got.Properties.User {
		if u.Key == "saguin-expires" {
			raw = u.Value
		}
	}
	if raw == "" {
		t.Fatal("an expired record carried no saguin-expires, which is the whole case " +
			"this property exists for")
	}
	at, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		t.Fatalf("saguin-expires is %q", raw)
	}
	if at > time.Now().UnixMilli() {
		t.Errorf("saguin-expires is %d, which is in the future for a record whose "+
			"expiry ran out two seconds ago", at)
	}
	// MQTT's own field is gone, which is what makes the property necessary
	// rather than a second opinion.
	if got.Properties.MessageExpiry != nil {
		t.Errorf("the standard message expiry field arrived as %d on an expired "+
			"record; the two would then disagree", *got.Properties.MessageExpiry)
	}
}

// On a channel the client's Message Expiry Interval deletes nothing -
// retention there is the operator's (invariant 2), and a publisher removing
// records from another consumer's replay is the silent gap invariant 1
// exists to prevent - so what it does instead is report: the seconds left
// while it lasts, and no property at all where the publisher set none.
//
// **The third answer, 0 for a record whose time is up, is not on the wire
// and this test does not claim it is.** saguin sets it; the substrate's
// encoder writes the property only when the value is above zero, and
// `packets.Properties` carries no presence flag for this field the way it
// does for Session Expiry and Receive Maximum. So a spent record is
// delivered indistinguishable from an untimed one, which is a fork change
// rather than a saguin one.
func TestAChannelReplayReportsTheExpiryAndDeletesNothing(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	second, fiveMinutes := uint32(1), uint32(300)
	for _, pub := range []*paho.Publish{
		{Topic: "events/spent", QoS: 1, Payload: []byte("spent"),
			Properties: &paho.PublishProperties{MessageExpiry: &second}},
		{Topic: "events/running", QoS: 1, Payload: []byte("running"),
			Properties: &paho.PublishProperties{MessageExpiry: &fiveMinutes}},
		{Topic: "events/bare", QoS: 1, Payload: []byte("bare")},
	} {
		if _, err := p.C.Publish(context.Background(), pub); err != nil {
			t.Fatalf("publish %s: %v", pub.Topic, err)
		}
	}

	// Past the first record's expiry, and far enough past that scheduling
	// cannot bring it back.
	time.Sleep(2100 * time.Millisecond)

	// A consumer that was not there at the time, replaying from the start:
	// the case an expiry could otherwise silently empty.
	sub := dialProps(t, h, "reader")
	sub.Sub(t, "events/#", 1)

	got := map[string]*paho.Publish{}
	for range 3 {
		r := awaitProp(t, sub)
		if r == nil {
			break
		}
		got[r.Topic] = r
	}
	if len(got) != 3 {
		t.Fatalf("replayed %d of 3 records (%v); a publisher's expiry deletes nothing "+
			"from a channel", len(got), got)
	}

	// Whatever the wire can express, it must never be a stale countdown: a
	// spent record reporting the hour its publisher wrote would have a
	// consumer act on a deadline that passed.
	if spent := got["events/spent"]; spent.Properties != nil &&
		spent.Properties.MessageExpiry != nil && *spent.Properties.MessageExpiry != 0 {
		t.Errorf("a record whose expiry has run out was replayed reporting %d seconds left",
			*spent.Properties.MessageExpiry)
	}

	running := got["events/running"]
	if running.Properties == nil || running.Properties.MessageExpiry == nil {
		t.Fatal("a record inside its expiry was replayed with no countdown")
	}
	if left := *running.Properties.MessageExpiry; left < 250 || left > 298 {
		t.Errorf("the countdown is %d after a 2.1s wait on a 300s expiry, "+
			"want the publisher's remainder decremented (250..298)", left)
	}

	bare := got["events/bare"]
	if bare.Properties != nil && bare.Properties.MessageExpiry != nil {
		t.Errorf("a record whose publisher set no expiry was replayed carrying %d",
			*bare.Properties.MessageExpiry)
	}
}

// RFC 0002's publish table: `0x90 Topic Name invalid` for a publish in the
// reserved `$saguin/` space that is not one of the topics saguin defines
// there.
//
// It defines exactly two, `$saguin/consumer/<channel>/seek` and
// `$saguin/queue/<queue>/response`, and everything else under the prefix
// used to be answered Success after the broker had discarded it. Success is
// the worst of the three available answers: a producer told its publish
// failed can retry, correct the topic, or raise an alarm, and one told it
// succeeded can do none of those.
//
// The client asks for Problem Information, because MQTT-3.1.2-29 lets a
// server withhold the Reason String from a PUBACK when it does not - and
// Eclipse Paho does not by default. A probe that measured only that default
// reported saguin sending no Reason String for any refusal, which was the
// instrument rather than the broker.
func TestPublishingIntoTheReservedSpaceIsRefused(t *testing.T) {
	h := start(t)
	c := connectAsking(t, h, "producer")

	for _, tc := range []struct {
		name  string
		topic string
		want  byte
	}{
		{"nothing saguin defines", "$saguin/nonsense", 0x90},
		{"the prefix alone", "$saguin/", 0x90},
		{"a level too deep", "$saguin/queue/jobs/response/extra", 0x90},
		{"a channel name with a level in it", "$saguin/consumer/site/events/seek", 0x90},
		// A topic saguin defines names a channel that can answer it. The two
		// halves of that are tested next door, one per shape; what matters
		// here is that they are the same refusal as the shapes above.
		{"a response for a queue that does not exist", "$saguin/queue/nosuchqueue/response", 0x90},
		{"a seek for a channel that does not exist", "$saguin/consumer/nosuchchannel/seek", 0x90},
		// The two saguin does define, on channels that can answer them.
		// What is *inside* the message belongs to the handler and is not
		// judged here: this response carries no Correlation Data and this
		// seek is on a session that cannot hold a position, and both are
		// acknowledged.
		{"a response for a real queue", "$saguin/queue/jobs/response", 0x00},
		{"a seek for a real append channel", "$saguin/consumer/events/seek", 0x00},
		{"a seek for a dead-letter channel", "$saguin/consumer/jobs__dlq/seek", 0x00},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ack, err := c.Publish(context.Background(), &paho.Publish{
				Topic: tc.topic, QoS: 1, Payload: []byte("0"),
			})
			if ack == nil {
				t.Fatalf("no PUBACK: %v", err)
			}
			if ack.ReasonCode != tc.want {
				t.Errorf("answered 0x%02X, want 0x%02X", ack.ReasonCode, tc.want)
			}
			if tc.want == 0x00 {
				return
			}
			// Every non-success carries a Reason String (RFC 0002
			// "Publishing"), and it is the whole value of the refusal to an
			// operator: the code alone points at a topic that is perfectly
			// well formed.
			if ack.Properties == nil || ack.Properties.ReasonString == "" {
				t.Error("refused with no Reason String")
			} else {
				t.Logf("0x%02X %q", ack.ReasonCode, ack.Properties.ReasonString)
			}
		})
	}

	// A refused QoS 0 publish is dropped rather than refused and delivered:
	// the server has no branch for a reason code without a PUBACK to put it
	// in, so a refusal that is not turned into a rejection here reaches
	// every subscriber anyway.
	//
	// **Driven on an ordinary topic rather than in the reserved space.**
	// This once watched `$saguin/#`, and that
	// subscription is now refused - nothing is ever delivered under the
	// prefix, so granting one was a promise that could not be kept. Losing
	// it is no loss to this test and a gain: what is under test is that a
	// refused QoS 0 publish reaches nobody, and a refusal on a topic a
	// subscriber can actually hold exercises the path a deployment meets.
	// In the reserved space the property is now structural - MQTT stops `#`
	// matching a `$` topic, so no filter reaches it at all.
	//
	// The refusal used here is the retain flag on a broadcast topic with no
	// retained store, which this harness has none of.
	watcher := connect(t, h, "watcher", true, false)
	if sa := watcher.Sub(t, "loose/#", 1); sa.Reasons[0] > 2 {
		t.Fatalf("cannot watch an ordinary topic: SUBACK 0x%02X", sa.Reasons[0])
	}
	if _, err := c.Publish(context.Background(), &paho.Publish{
		Topic: "loose/keepme", QoS: 0, Retain: true, Payload: []byte("0"),
	}); err != nil {
		t.Fatalf("qos 0 publish: %v", err)
	}
	if got, ok := watcher.Await(t, 500*time.Millisecond); ok {
		t.Errorf("a refused QoS 0 publish was delivered to %q", got.Topic)
	}
}

// Observation: saguin's own reserved space answered a
// subscription 0x01 while `$SYS/#` beside it answered 0x87, and nothing was
// ever delivered under either.
//
// **A subscription that can never deliver is a promise this broker does not
// make.** Every topic under `$saguin/` is one a client publishes *to* - a
// seek, a point read, a queue's response - so there is nothing to receive
// there, and granting the filter sends somebody watching their worker's
// acknowledgements looking in the wrong place when the silence starts.
func TestSubscribingIntoTheReservedSpaceIsRefused(t *testing.T) {
	h := start(t)
	c := connect(t, h, "watcher", true, false)

	for _, filter := range []string{
		"$saguin/#",
		"$saguin/queue/jobs/response",
		"$saguin/consumer/events/seek",
		"$saguin/kv/get",
	} {
		if sa := c.Sub(t, filter, 1); sa.Reasons[0] <= 2 {
			t.Errorf("%s was granted 0x%02X: nothing is ever delivered there, so it is a "+
				"subscription that can only ever go quiet", filter, sa.Reasons[0])
		}
	}

	// Publishing into the space is how every one of those verbs is asked
	// for, and is untouched: a worker still answers its deliveries.
	if got := c.SeekQuietly(t, "events", "-1"); got != 0 {
		t.Errorf("a seek was refused 0x%02X: publishing into the reserved space is how "+
			"the verbs are asked for", got)
	}
	// And the queue's own subscription form is not in this space at all -
	// `$share/` is MQTT's prefix, not saguin's.
	if sa := c.Sub(t, "$saguin/queue/jobs", 1); sa.Reasons[0] > 2 {
		t.Errorf("the queue's canonical subscription form was refused 0x%02X", sa.Reasons[0])
	}
}

// RFC 0002 "Shared subscriptions" - MQTT 5 section 4.8.2
//
// **A shared subscription is `$share/<ShareName>/<filter>`, and the filter
// is judged as if it had been sent alone.** The wrapper names a group and
// nothing else, so it cannot be a way into a space the filter alone is
// refused, and it cannot wrap another wrapper.
//
// Both were granted `0x01` and then delivered nothing, which is what
// mosquitto 2.0.22 does too, measured: `$share/g/$SYS/#`,
// `$share/g/$saguin/queue/jobs` and `$share/g/$share/h/x` all granted, all
// silent. A queue reached through `$share` is the one that matters: its
// workers subscribe the form alone, and a worker told it had subscribed
// waits for jobs that never come.
//
// Every expected code is exact rather than "refused", because the two
// codes send a developer to different places: `0x87` at the space, `0x8F`
// at the spelling.
func TestASharedSubscriptionIsAGroupAndAFilterJudgedAlone(t *testing.T) {
	h := start(t)
	c := connect(t, h, "sharer", true, false)

	for _, tc := range []struct {
		filter string
		want   byte
		why    string
	}{
		{"$share/g/events/#", 0x01, "the ordinary shape, and the control for every row below"},
		{"$share/g/$other/x", 0x01, "a `$` level saguin does not reserve, granted alone and so shared too"},
		{"$share/g/$SYS/#", 0x87, "`$SYS/#` alone is refused 0x87"},
		{"$share/g/$saguin/#", 0x87, "`$saguin/#` alone is refused 0x87"},
		{"$share/g/$saguin/queue/jobs", 0x87, "a queue is consumed through its own form, never through a group"},
		{"$share/g/$saguin/consumer/events/seek/reply", 0x87, "a seek reply is written to one client's socket"},
		{"$share/g/$share/h/events/#", 0x8F, "a shared subscription inside another"},
		{"$share/g/$SHARE/h/events/#", 0x8F, "the same, spelled in another case"},
		{"$share//events/#", 0x8F, "a ShareName is at least one character (MQTT-4.8.2-1)"},
		{"$share/g+/events/#", 0x8F, "a ShareName holds no wildcard (MQTT-4.8.2-2)"},
		{"$share/g", 0x8F, "a ShareName followed by no filter (MQTT-4.8.2-2)"},
	} {
		sa := c.Sub(t, tc.filter, 1)
		if sa == nil || len(sa.Reasons) != 1 {
			t.Fatalf("no SUBACK for %s", tc.filter)
		}
		if got := sa.Reasons[0]; got != tc.want {
			t.Errorf("%s answered SUBACK 0x%02X, want 0x%02X: %s", tc.filter, got, tc.want, tc.why)
		}
	}
}

// RFC 0002 "Bridges"
//
// The upstream holding no session for a bridge means whatever it had queued
// is gone, and the CONNACK is the only moment saguin can say so. Everywhere
// else an outage costs nothing until retention catches up; here it costs
// whatever the far end decided to stop keeping, and no consumer downstream
// will ever learn that the gap exists.
//
// This test exists because the warning was written with `&& !first` on it,
// which suppressed it in exactly the case worth reporting. A bridge cannot
// tell its first connection ever from the first after a restart - nothing
// about it is stored - so a saguin down for longer than session_expiry came
// back to a discarded session and said nothing at all. Found by running it,
// not by reading it.
func TestABridgeSaysWhenTheUpstreamHasNoSessionForIt(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)
	cfg := bridgeConfig(t, upstreamAddr)

	var mu sync.Mutex
	var logged strings.Builder
	log := slog.New(slog.NewTextHandler(&lockedWriter{Mu: &mu, W: &logged},
		&slog.HandlerOptions{Level: slog.LevelWarn}))

	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})
	waitForBridge(t, upstream, cfg.ClientID)

	// **Waited for rather than read once.** `waitForBridge` returns when the
	// upstream has registered the subscription, and the bridge writes this
	// line *after* its Subscribe call returns - so the moment the test is
	// allowed to look is a moment before there is anything to see. Reading
	// the buffer once there fails whenever the machine is busy enough to put
	// those two events either side of the poll, which is what a full suite
	// under the race detector does.
	//
	// One-sided: a slow machine takes longer to write the line and this
	// waits longer for it. Nothing but the line never being written runs out
	// the clock.
	read := func() string {
		mu.Lock()
		defer mu.Unlock()
		return logged.String()
	}
	got := read()
	for deadline := time.Now().Add(10 * time.Second); !strings.Contains(got, "not holding a session") && time.Now().Before(deadline); {
		time.Sleep(20 * time.Millisecond)
		got = read()
	}

	// This *is* a first connection, and it is still worth a line: the
	// upstream has no session, and only the operator can say whether that is
	// because the bridge is new or because it was away too long.
	if !strings.Contains(got, "not holding a session") {
		t.Fatalf("nothing said the upstream held no session for the bridge, so a restart "+
			"across an expired session would be silent. The log was:\n%s", got)
	}
	if !strings.Contains(got, "cannot tell which") {
		t.Errorf("the line does not name the ambiguity, so a reader cannot tell a fresh "+
			"start from a lost backlog. The log was:\n%s", got)
	}
}

// MQTT-3.1.2-4, and invariant 1's shape at a different moment.
//
// A client connecting with Clean Start = 1 asks the server to **discard any
// existing session and start a new one**. saguin reports that faithfully -
// CONNACK carries Session Present = 0 - and then used to serve the client
// from the position of the session it had just said was not there. It asked
// to start fresh, was told it had nothing, and silently resumed mid-stream.
//
// Nothing tells the consumer. It reads from where the old session stopped,
// processes what it gets, and reports success over every record before that
// point - which is invariant 1's failure arriving through the one door
// invariant 1 does not watch, because no retention was involved and no floor
// moved. Clean Start discards mochi's session; saguin's position lives in
// saguin's own store, keyed by client id, and nothing there was told.
func TestCleanStartDiscardsAStoredPosition(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	pub := func(t testing.TB, s string) {
		t.Helper()
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/o", QoS: 1, Payload: []byte(s)}); err != nil {
			t.Fatalf("publish %q: %v", s, err)
		}
	}
	read := func(t testing.TB, c *client) []string {
		t.Helper()
		var got []string
		for {
			r, ok := c.Await(t, 700*time.Millisecond)
			if !ok {
				return got
			}
			got = append(got, r.Payload)
		}
	}

	for _, s := range []string{"a", "b", "c"} {
		pub(t, s)
	}

	// A durable consumer reads all three, which stores its position.
	d := dial(t, h, "consumer", false, false, 0, 300, 0)
	d.Sub(t, "events/#", 1)
	if got := read(t, d); len(got) != 3 {
		t.Fatalf("the durable consumer read %v, want all three", got)
	}
	acknowledged(t, d) // its last PUBACK read, so the position stored is past it
	gone(t, d)

	pub(t, "d")
	pub(t, "e")

	// The same client id, now asking for a clean start.
	cs := dial(t, h, "consumer", true, false, 0, 300, 0)
	if cs.SessionPresent {
		t.Fatal("Session Present = 1 after Clean Start = 1, which MQTT-3.1.2-4 forbids")
	}
	cs.Sub(t, "events/#", 1)
	got := read(t, cs)

	if len(got) != 5 {
		t.Fatalf("a clean start read %v, want all five - it was told Session Present = 0 "+
			"and then served from the position of the session it was told it did not have, "+
			"so %d record(s) before that point were skipped with nothing to say so",
			got, 5-len(got))
	}
}

// The same rule on a provider that keeps its own records, and a check that
// it was reached by the one operation rather than by the walk.
//
// **Why this is a second test rather than a case of the one above.** A
// clean start has to forget the client's positions, and asking channel by
// channel is a transaction per channel on this kind of provider - the cost
// of connecting rather than the cost of what the client stored. saguin asks
// the provider once instead, where the provider can answer that way, and
// falls back to the walk where it cannot. Both paths discard the position,
// so a test that only reads the records passes whichever one ran: the
// behaviour above is necessary and does not say which code did it.
//
// So this asserts the line as well as the records. `provider` and
// `discarded` are what the one-operation path writes; the walk writes
// `channel`, one line per channel it cleared. Reading the records alone
// would be a test that goes on passing if the capability stops being
// found - which is exactly how it would break, since it is an optional
// interface that a store simply fails to satisfy.
func TestACleanStartOnADatabaseForgetsThePositionsInOneOperation(t *testing.T) {
	var mu sync.Mutex
	var lines []string
	h := startLoggingSQLite(t, func(l string) {
		mu.Lock()
		lines = append(lines, l)
		mu.Unlock()
	}, filepath.Join(t.TempDir(), "clean.db"))

	p := connect(t, h, "producer", true, false)
	pub := func(t testing.TB, s string) {
		t.Helper()
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/o", QoS: 1, Payload: []byte(s)}); err != nil {
			t.Fatalf("publish %q: %v", s, err)
		}
	}
	for _, s := range []string{"a", "b", "c"} {
		pub(t, s)
	}

	read := func(t testing.TB, c *client) []string {
		t.Helper()
		var got []string
		for {
			r, ok := c.Await(t, 700*time.Millisecond)
			if !ok {
				return got
			}
			got = append(got, r.Payload)
		}
	}

	d := dial(t, h, "consumer", false, false, 0, 300, 0)
	d.Sub(t, "events/#", 1)
	if got := read(t, d); len(got) != 3 {
		t.Fatalf("the durable consumer read %v, want all three", got)
	}
	acknowledged(t, d) // its last PUBACK read, so the position stored is past it
	gone(t, d)

	pub(t, "d")
	pub(t, "e")

	cs := dial(t, h, "consumer", true, false, 0, 300, 0)
	if cs.SessionPresent {
		t.Fatal("Session Present = 1 after Clean Start = 1, which MQTT-3.1.2-4 forbids")
	}
	cs.Sub(t, "events/#", 1)
	if got := read(t, cs); len(got) != 5 {
		t.Fatalf("a clean start read %v, want all five: its stored position was not discarded", got)
	}

	mu.Lock()
	defer mu.Unlock()
	var said string
	for _, l := range lines {
		if strings.Contains(l, "stored positions went with it") && strings.Contains(l, "clean start") {
			said = l
		}
	}
	if said == "" {
		t.Fatalf("the records came back, but nothing said the provider forgot them in one "+
			"operation - so the walk ran instead, which is a transaction per channel on "+
			"the connect path. Lines: %d", len(lines))
	}
	if !strings.Contains(said, "discarded=1") {
		t.Errorf("the line does not say how many positions went: %s", said)
	}
}

// And the other half, or the fix above would be "always replay everything":
// a consumer that did *not* ask for a clean start still resumes.
func TestWithoutCleanStartAStoredPositionSurvives(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for _, s := range []string{"a", "b", "c"} {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/o", QoS: 1, Payload: []byte(s)}); err != nil {
			t.Fatal(err)
		}
	}

	d := dial(t, h, "consumer", false, false, 0, 300, 0)
	d.Sub(t, "events/#", 1)
	for range 3 {
		if _, ok := d.Await(t, 2*time.Second); !ok {
			t.Fatal("the durable consumer did not read the channel")
		}
	}
	// The assertion below is that nothing is re-read, and that holds only
	// once the last PUBACK has reached the broker: Paho sends it when the
	// handler returns, so a disconnect can overtake it, and the position
	// then stored is one record behind. The broker's own promise there is
	// that a record arrives twice rather than not at all, so a disconnect
	// racing the acknowledgement is the test asserting more than the broker
	// offers rather than the broker being wrong.
	acknowledged(t, d) // its last PUBACK read, so the position stored is past it
	gone(t, d)

	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "events/o", QoS: 1, Payload: []byte("d")}); err != nil {
		t.Fatal(err)
	}

	again := dial(t, h, "consumer", false, false, 0, 300, 0)
	if !again.SessionPresent {
		t.Fatal("Session Present = 0 for a consumer that kept its session")
	}
	again.Sub(t, "events/#", 1)
	r, ok := again.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("it received nothing, so its position was lost")
	}
	if r.Payload != "d" {
		t.Fatalf("it resumed at %q, want the one record published while it was away", r.Payload)
	}
	if extra, more := again.Await(t, 500*time.Millisecond); more {
		t.Fatalf("it re-read %q, so the position was discarded rather than resumed", extra.Payload)
	}
}

// RFC 0002 `append`: a position is per channel and not per filter.
//
// The cursor advances over every record the consumer was offered, including
// the ones its filter did not match - it has to, or a narrow filter would
// stall behind the first record it did not want. So a durable consumer that
// changes its filter cannot reach anything below the position it holds, and
// nothing reports that: it simply receives nothing.
//
// This is the price of a position being one integer, which is what makes a
// persistent session unable to overflow. It is written down as a test as
// well as in the RFC because it is the sort of property a later change could
// quietly reverse - into a per-filter cursor for every filter every client
// ever used, which is what invariant 13 refuses.
func TestAPositionIsPerChannelAndNotPerFilter(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	for _, m := range []struct{ topic, payload string }{
		{"events/a/1", "a1"}, {"events/b/1", "b1"},
		{"events/a/2", "a2"}, {"events/b/2", "b2"},
	} {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: m.topic, QoS: 1, Payload: []byte(m.payload)}); err != nil {
			t.Fatalf("publish %s: %v", m.topic, err)
		}
	}

	read := func(t testing.TB, c *client) []string {
		t.Helper()
		var got []string
		for {
			r, ok := c.Await(t, 700*time.Millisecond)
			if !ok {
				return got
			}
			got = append(got, r.Payload)
		}
	}

	// A narrow filter receives only what it matches, and its position moves
	// past everything in between.
	narrow := dial(t, h, "consumer", false, false, 0, 300, 0)
	narrow.Sub(t, "events/a/#", 1)
	if got := read(t, narrow); len(got) != 2 || got[0] != "a1" || got[1] != "a2" {
		t.Fatalf("the narrow filter read %v, want [a1 a2]", got)
	}
	acknowledged(t, narrow) // its last PUBACK read, so the position stored is past it
	gone(t, narrow)

	// The same client id on the other sub-tree reaches none of it.
	moved := dial(t, h, "consumer", false, false, 0, 300, 0)
	moved.Sub(t, "events/b/#", 1)
	if got := read(t, moved); len(got) != 0 {
		t.Fatalf("changing the filter read %v, want nothing - the position is per channel, "+
			"so a per-filter cursor has appeared from somewhere", got)
	}
	acknowledged(t, moved) // its last PUBACK read, so the position stored is past it
	gone(t, moved)

	// And Clean Start = 1 is the way back, which is the whole reason the
	// consequence is tolerable.
	fresh := dial(t, h, "consumer", true, false, 0, 300, 0)
	fresh.Sub(t, "events/b/#", 1)
	if got := read(t, fresh); len(got) != 2 || got[0] != "b1" || got[1] != "b2" {
		t.Fatalf("a clean start on the new filter read %v, want [b1 b2] - without this "+
			"there is no way to re-read a channel under a different filter at all", got)
	}
}

// TestAPublishAboveTheBoundIsRefusedOnTheWire covers the client that sends
// one anyway. The CONNACK above is the warning; this is what happens when it
// is ignored, and RFC 0002 promises a DISCONNECT carrying 0x95 rather than a
// bare reset the producer has to guess at.
//
// Raw bytes because a client library that honours the advertised Maximum
// Packet Size will not send this at all - through one of those the broker's
// answer cannot be seen, which is how this went unnoticed while the
// delivery direction was tested.
//
// The write runs in its own goroutine and its error is discarded on
// purpose: the broker refuses at the fixed header, so it stops reading and
// closes long before a megabyte has gone out, and the producer's write
// fails part-way. That is correct and it is not what is under test - a
// broker cannot read a packet it has refused just to be polite. What is
// under test is whether anything is said first.
func TestAPublishAboveTheBoundIsRefusedOnTheWire(t *testing.T) {
	h := start(t)

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	sendRawConnect(t, conn, "too-big")

	var body []byte
	body = append(body, 0x00, byte(len("loose/fat")))
	body = append(body, "loose/fat"...)
	body = append(body, 0x00) // property length
	body = append(body, make([]byte, int(limits.MaxMessageSize))...)
	go func() {
		_, _ = conn.Write(mqttPacket(0x30, body))
	}()

	// Everything the broker sends before it closes, rather than one packet:
	// the question is whether it said anything at all, and a helper that
	// fails on EOF answers "reading a packet: EOF" to a test whose subject
	// is silence.
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	got, _ := io.ReadAll(conn)

	if len(got) == 0 {
		t.Fatalf("a publish of %d bytes against a bound of %d got nothing on the wire: "+
			"the connection was reset, so the producer is left to guess at a limit this "+
			"broker advertised in its own CONNACK", len(body), limits.MaxMessageSize)
	}
	if got[0]>>4 != 14 {
		t.Fatalf("answered with packet type %d (% 02x), want a DISCONNECT", got[0]>>4, got)
	}
	if len(got) < 3 || got[2] != 0x95 {
		t.Errorf("disconnected with % 02x, want 0x95 Packet too large", got)
	}
}

// RFC 0002 "What a client may do"
//
// An acl_file restricts an authenticated client, on the wire, with the code
// RFC 0002 gives it.
//
// **Driven through a real client, because the question is what the broker
// answers rather than what the rules compute.** internal/authz has the rule
// model under test on its own; this is the half that says the rules are
// asked at all, on every path they are meant to be asked on - a publish, a
// subscription, and the control verbs, which are publishes to topics that
// resolve to no channel by prefix and so cannot be answered from a topic
// alone.
func TestAnACLFileRestrictsAnAuthenticatedClient(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  publisher:
    - channel: events
      allow: [write]
  worker:
    - channel: jobs
      allow: [consume]
users:
  "device-*": [publisher]
  worker-1:   [worker]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	// The identity a rule is about is the user name, which the harness's
	// clients do not set - so a rule granting "device-*" reaches nobody
	// here, and every one of these is the default: refuse.
	c := connect(t, h, "device-7", true, false)

	t.Run("a publish it may not make", func(t *testing.T) {
		ack, err := c.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/a", QoS: 1, Payload: []byte("x"),
		})
		if ack == nil {
			t.Fatalf("no acknowledgement: %v", err)
		}
		if ack.ReasonCode != 0x87 {
			t.Errorf("a publish by a client no role names was answered 0x%02X, want 0x87: "+
				"the default is refuse and it has to be visible", ack.ReasonCode)
		}
	})

	t.Run("a subscription it may not have", func(t *testing.T) {
		if sa := c.Sub(t, "events/#", 1); sa.Reasons[0] != 0x87 {
			t.Errorf("a subscription by a client no role names was granted 0x%02X, want "+
				"0x87", sa.Reasons[0])
		}
	})

	// The control verbs, which are the reason enforcement is not one hook:
	// a seek publishes to a topic resolving to no channel by prefix, and a
	// point read names its key in the payload.
	t.Run("a seek it may not make", func(t *testing.T) {
		if got := c.SeekQuietly(t, "events", "-1"); got != 0x87 {
			t.Errorf("a seek by a client no role names was acknowledged 0x%02X, want "+
				"0x87", got)
		}
	})

	t.Run("a point read it may not make", func(t *testing.T) {
		ack, err := c.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/kv/get", QoS: 1, Payload: []byte("state/a"),
			Properties: &paho.PublishProperties{ResponseTopic: "kv-reply"},
		})
		if ack == nil {
			t.Fatalf("no acknowledgement: %v", err)
		}
		if ack.ReasonCode != 0x87 {
			t.Errorf("a point read by a client no role names was answered 0x%02X, want "+
				"0x87: the key is in the payload, which is why this is not answered "+
				"where the subscription is", ack.ReasonCode)
		}
	})
}

// RFC 0003 "Saying which schema deserializes a payload"
//
// **The schema-registry convention is documented and adds no broker code,
// which is exactly why it needs a test.** Nothing in the broker knows the
// word "schema": the whole thing is a `latest` channel, a User Property
// carrying a topic, and a point read. So every piece of it is load-bearing
// somewhere else and could be changed by work that never mentions
// registries - and the documents would go on describing it.
//
// Four claims, all of which the documents make:
//   - a schema registers, resolves through a point read, and retires by
//     tombstone;
//   - the pointer survives the publish, and a `saguin-`-prefixed name for
//     it does not, because that prefix is reserved;
//   - one ACL rule confines a publisher to its own prefix, which is what
//     makes two teams choosing one name safe;
//   - and that rule only works where the channel's name is the topic's
//     first level, which is the constraint on where a registry may live.
func TestALatestChannelServesAsASchemaRegistry(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "schemas", Type: channel.Latest, Filter: "schemas/#"},
		{Name: "events", Type: channel.Append, Filter: "iot/+/events/+"},
	})

	const schemaTopic = "schemas/acme/weather/v1"
	const schemaText = "message WeatherReading { int32 temperature_c = 1; }"

	dev := connect(t, h, "acme-dev", true, false)
	dev.Pub(t, schemaTopic, schemaText)
	settle(t, dev)

	reader := connect(t, h, "viewer", true, false)
	reader.Sub(t, "iot/+/events/+", 1)
	reader.Sub(t, "reply/viewer", 1)

	// Produced with the pointer, and with the one name that cannot survive.
	if _, err := dev.C.Publish(context.Background(), &paho.Publish{
		Topic: "iot/acme/events/trk-001", QoS: 1, Payload: []byte{0x08, 0x1a},
		Properties: &paho.PublishProperties{
			ContentType: "application/x-protobuf",
			User: paho.UserProperties{
				{Key: "schema", Value: schemaTopic},
				{Key: "saguin-schema-id", Value: "reserved-and-dropped"},
			},
		},
	}); err != nil {
		t.Fatalf("produce the reading: %v", err)
	}

	rec, ok := reader.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the reading never arrived, so nothing below is about resolving one")
	}
	if rec.User["schema"] != schemaTopic {
		t.Errorf("the record carries schema %q, want %q: the pointer is an ordinary "+
			"User Property and saguin does not touch it", rec.User["schema"], schemaTopic)
	}
	if got := rec.User["saguin-schema-id"]; got != "" {
		t.Errorf("a publisher-set saguin-schema-id arrived as %q: `saguin-` is reserved "+
			"on a publish, which is why the documents tell an operator to name the "+
			"property something of their own", got)
	}

	// Resolved by a point read: one key, no subscription to the registry.
	read := func(key string) string {
		t.Helper()
		ack, err := reader.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/kv/get", QoS: 1, Payload: []byte(key),
			Properties: &paho.PublishProperties{ResponseTopic: "reply/viewer"},
		})
		if ack == nil {
			t.Fatalf("point read %q: no acknowledgement: %v", key, err)
		}
		if ack.ReasonCode != 0 {
			t.Fatalf("point read %q answered 0x%02X", key, ack.ReasonCode)
		}
		r, ok := reader.Await(t, 3*time.Second)
		if !ok {
			return ""
		}
		return r.Payload
	}
	if got := read(rec.User["schema"]); got != schemaText {
		t.Errorf("point-reading the pointer gave %q, want the schema text: a consumer "+
			"resolves a schema without subscribing to the registry", got)
	}

	// Retired by tombstone, which is how this channel type deletes.
	//
	// **Both readers, because they are different code paths** - the point
	// read answers from the store directly and the subscriber is served a
	// snapshot - and a retired schema has to be absent to both or a
	// consumer's answer depends on how it asked.
	//
	// **What neither can check, stated so the next reader does not try.**
	// "Deleted" and "stored as a zero-length value" are the same thing
	// here, not two things that happen to agree: a deletion *is* an
	// empty-payload record in the store, and Match skips it for every
	// reader but a copy. Disabling the delete branch entirely leaves both
	// assertions below green, because the publish falls through to an
	// ordinary store and the store reads it back as the deletion it is.
	// RFC 0003 makes the same point from the client side - an empty reply
	// means there is no value, so a key never set and a key deleted are
	// one answer.
	dev.Pub(t, schemaTopic, "")
	settle(t, dev)
	if got := read(schemaTopic); got != "" {
		t.Errorf("after a zero-length publish the schema still reads back as %q", got)
	}
	after := connect(t, h, "late-viewer", true, false)
	after.Sub(t, "schemas/#", 1)
	if r, ok := after.Await(t, time.Second); ok {
		t.Errorf("a subscriber joining after the tombstone was sent %q: a retired "+
			"schema is deleted rather than stored as an empty value, so it is not "+
			"in the snapshot a new subscriber receives", r.Topic)
	}
}

// The half of the convention that is a refusal rather than a value, and the
// constraint that comes with it.
//
// **A naming convention only asks people nicely; this refuses them.** Two
// publishers choosing `weather-v1` in different domains cannot reach each
// other's key, because one ACL rule confines each to its own prefix.
//
// **And it works wherever the registry lives**, which it did not always.
// A rule confining a publisher used to compare against what followed the
// *channel name*, so a registry named in the middle of its own filter left
// nothing to compare, matched no topic at all, and refused every publisher
// including for its own prefix - silently, since the file loaded and the
// grant printed. A rule's filter is compared against the whole topic now,
// so both layouts below confine and neither is a constraint to remember.
func TestASchemaRegistrysACLConfinesEachPublisher(t *testing.T) {
	for _, tc := range []struct {
		name, filter, rule string
		own, other         string
	}{
		{"named as the topic's first level", "schemas/#", "schemas/%u/#",
			"schemas/acme/weather/v1", "schemas/globex/weather/v1"},
		{"nested, which the suffix mechanism could not serve at all", "iot/+/schemas/+",
			"iot/%u/schemas/+",
			"iot/acme/schemas/v1", "iot/globex/schemas/v1"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := startRandom(t, []*channel.Channel{
				{Name: "schemas", Type: channel.Latest, Filter: tc.filter},
			})
			acl := filepath.Join(t.TempDir(), "acl.yaml")
			if err := os.WriteFile(acl, []byte(`
roles:
  device:
    - channel: schemas
      filter: "`+tc.rule+`"
      allow: [write, read, delete]
users:
  acme: [device]
  globex: [device]
`), 0o600); err != nil {
				t.Fatalf("write acl: %v", err)
			}
			f, err := authz.Load(acl, h.B.Registry(), 0)
			if err != nil {
				t.Fatalf("load acl: %v", err)
			}
			h.B.Authorize(authz.New(f, h.B.Registry()))

			publish := func(user, id, topic string) byte {
				t.Helper()
				c := dialWithUser(t, h, id, user)
				ack, err := c.C.Publish(context.Background(), &paho.Publish{
					Topic: topic, QoS: 1, Payload: []byte("x"),
				})
				if ack == nil {
					t.Fatalf("publish %s: no acknowledgement: %v", topic, err)
				}
				return ack.ReasonCode
			}

			if got := publish("acme", "conn-a", tc.own); got != 0x00 {
				t.Errorf("acme publishing its own %s was answered 0x%02X, want 0x00: a "+
					"rule that refuses the publisher it was written for is the failure "+
					"the whole-topic filter replaced the suffix to end", tc.own, got)
			}
			// Confined in both layouts now, and for the same reason in each.
			if got := publish("acme", "conn-b", tc.other); got != 0x87 {
				t.Errorf("acme publishing another publisher's %s was answered 0x%02X, "+
					"want 0x87: the rule confines each publisher to its own prefix, "+
					"which is what makes two teams choosing one name safe",
					tc.other, got)
			}
		})
	}
}

// The queue under an acl_file.
//
// **A worker granted `consume` takes a job and resolves it, end to end.**
// There was no such case before this one: the suite defined a worker role
// and never connected it, and asserted only that an events-only role was
// *refused* the queue subscription - which passed for the wrong reason,
// because every role was refused it, `consume` included.
//
// What that cost is the reason this is an end-to-end test rather than a
// unit one. `$saguin/queue/jobs` resolved to no channel, so permission
// fell through to broadcast: every legitimate worker was locked out, and a
// role holding a `topic:` rule was granted the queue's own form instead.
// That phantom worker held a share of the group, had every record refused
// at the delivery check, and the job it was offered was never re-offered,
// returned or dead-lettered - accepted, acknowledged, and wedged for the
// life of the process.
func TestAWorkerGrantedConsumeCanWork(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  worker:
    - channel: jobs
      allow: [consume]
  submit:
    - channel: jobs
      allow: [write]
users:
  "*": [worker, submit]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	// **No broadcast rule anywhere in that file**, and that is the point.
	// The first version of this test also granted `topic: "#"`, which is
	// what the defect matched - so the subscription was granted for the
	// wrong reason and the test passed against the bug it was written for.
	done := make(chan string, 1)
	worker := dialThrough(t, h.Addr, "worker-1", esp32, nil,
		func(payload string, reply func(string)) {
			reply("ack")
			done <- payload
		})
	if sa := worker.Sub(t, "$saguin/queue/jobs", 1); sa.Reasons[0] > 2 {
		t.Fatalf("a worker whose role carries consume was refused the queue's own "+
			"subscription form with 0x%02X: every legitimate worker is locked out and "+
			"the queue has no consumers", sa.Reasons[0])
	}

	producer := connect(t, h, "submitter", true, false)
	producer.Pub(t, "jobs/task-1", "the-work")

	select {
	case got := <-done:
		if got != "the-work" {
			t.Errorf("the worker was handed %q", got)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("a job submitted to a queue with a granted worker was never delivered")
	}
}

// RFC 0002 "Roles, and users matched by pattern": a client id goes into a
// %c rule as one level, never as the rule's syntax. A device calling itself
// `#`, `+` or `a/b` under `iot/health/%c` is granted nothing by that rule -
// not every device's topic for reading and writing, which is what `#` was -
// and a device with an ordinary id keeps its own.
func TestAClientIDHoldingFilterSyntaxWidensNoRule(t *testing.T) {
	h := start(t)
	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  sensor:
    - topic: iot/health/%c
      allow: [read, write]
users:
  "*": [sensor]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	north := connect(t, h, "north-17", true, false)
	if sa := north.Sub(t, "iot/health/north-17", 1); sa.Reasons[0] > 2 {
		t.Fatalf("north-17 was refused its own topic with 0x%02X, so this proves nothing", sa.Reasons[0])
	}
	if ack, err := north.C.Publish(context.Background(), &paho.Publish{Topic: "iot/health/north-17", QoS: 1, Payload: []byte("own")}); err != nil || ack.ReasonCode != 0 {
		t.Fatalf("north-17's publish to its own topic: %v (%v), so this proves nothing", err, ack)
	}

	for _, tc := range []struct{ id, filter string }{
		{"#", "iot/health/#"},
		{"+", "iot/health/+"},
		{"a/b", "iot/health/a/b"},
	} {
		c := connect(t, h, tc.id, true, false)
		if sa := c.Sub(t, tc.filter, 1); sa.Reasons[0] != 0x87 {
			t.Errorf("client id %q subscribing %s was answered 0x%02X, want 0x87", tc.id, tc.filter, sa.Reasons[0])
		}
		ack, err := c.C.Publish(context.Background(), &paho.Publish{Topic: "iot/health/north-17", QoS: 1, Payload: []byte("forged")})
		if ack == nil || ack.ReasonCode != 0x87 {
			t.Errorf("client id %q publishing to north-17's topic was answered %v (%v), want 0x87", tc.id, ack, err)
		}
	}
	for {
		r, ok := north.Await(t, 300*time.Millisecond)
		if !ok {
			break
		}
		if r.Payload != "own" {
			t.Errorf("north-17 was sent %q on its own topic, which no other device may write", r.Payload)
		}
	}
}

// The other half of the same finding, and the half that stranded the job: a
// role carrying only a `topic:` rule must not reach the queue's form. A
// topic rule governs broadcast - the topics no channel claims - and one
// that crosses into a channel is the widening the two rule kinds exist to
// make impossible.
func TestATopicRuleCannotReachTheQueueForm(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  broadcaster:
    - topic: "#"
      allow: [read, write]
users:
  "*": [broadcaster]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	c := connect(t, h, "bcast", true, false)
	if sa := c.Sub(t, "$saguin/queue/jobs", 1); sa.Reasons[0] <= 2 {
		t.Errorf("a role carrying only `topic: \"#\"` was granted the queue's own "+
			"subscription form with 0x%02X: it holds a share of the group, has every "+
			"record refused at the delivery check, and strands the job it is offered",
			sa.Reasons[0])
	}
	// It still reaches what a topic rule is for.
	if sa := c.Sub(t, "loose/#", 1); sa.Reasons[0] > 2 {
		t.Errorf("a broadcast rule no longer reaches broadcast: 0x%02X", sa.Reasons[0])
	}
}

// The direction that discriminates. Everything above would pass just as
// well against a broker that refused every client for every reason, and a
// permission model that grants nothing is as broken as one that grants
// everything - so the same paths are driven again for a client a rule does
// reach, and what it was *not* granted must still be refused.
func TestAnACLFileAllowsWhatItGrants(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	// `*` reaches every identity including the empty one, which is what the
	// harness's clients have.
	if err := os.WriteFile(acl, []byte(`
roles:
  publisher:
    - channel: events
      allow: [write, read, seek]
users:
  "*": [publisher]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	c := connectDurable(t, h, "granted")

	if sa := c.Sub(t, "events/#", 1); sa.Reasons[0] > 2 {
		t.Fatalf("a subscription the rules grant was refused 0x%02X", sa.Reasons[0])
	}
	ack, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: "events/a", QoS: 1, Payload: []byte("x"),
	})
	if ack == nil {
		t.Fatalf("no acknowledgement: %v", err)
	}
	if ack.ReasonCode != 0 {
		t.Errorf("a publish the rules grant was refused 0x%02X", ack.ReasonCode)
	}
	if got := c.SeekQuietly(t, "events", "-1"); got != 0 {
		t.Errorf("a seek the rules grant was refused 0x%02X", got)
	}

	// And what the role does not carry is still refused, on the same
	// connection: this is one rule narrowing, not a switch that was left on.
	if sa := c.Sub(t, "$saguin/queue/jobs", 1); sa.Reasons[0] <= 2 {
		t.Errorf("consuming from jobs was granted 0x%02X to a role that carries only "+
			"events: a grant reaches what it names and nothing else", sa.Reasons[0])
	}
}

// RFC 0002 "Authorization may only narrow", invariants 4 and 11
//
// **A grant may take permission away and may never give it.**
//
// saguin's structural refusals ride on the same hook as authorization -
// the queue subscription form and the wildcard boundary - and the substrate
// ORs its ACL hooks. So a permission model evaluated first, or instead,
// would grant a non-canonical queue subscription and put two workers on one
// job: invariant 4's exact failure, reached through a feature whose whole
// purpose is to restrict access.
//
// This is the test that sentence is worth writing, and it is written before
// any rule matching exists, because it is the half that cannot be
// retrofitted: by the time there are rules to get wrong, the order is load
// bearing everywhere.
func TestAGrantCannotWidenAStructuralRefusal(t *testing.T) {
	h := start(t)
	h.B.SetAuthorizer(allowEverything{})

	c := connect(t, h, "permitted", true, false)

	// **`$SYS/#` is the case that discriminates**, and the reason is worth
	// knowing before trusting the other two. Invariant 4 is held across
	// three hooks and not in any one alone - OnACLCheck refuses, OnSubscribe
	// answers the reason code, and OnSubscribed disconnects a client left
	// holding a filter anyway - so the queue filters below are still refused
	// when this hook wrongly grants them. Measured: with permission asked
	// first, they are granted here and caught downstream, and only `$SYS`
	// fails this test.
	//
	// They stay because defence in depth is the point of that arrangement
	// and a test that watches it is worth having. But `$SYS` is the one
	// standing between this rule and a silent regression, and a change that
	// gave the queue filters a fourth guard would leave it standing alone.
	for _, tc := range []struct {
		filter string
		why    string
	}{
		{"jobs/#", "the queue's own filter: a broadcast consumer on a queue"},
		{"$saguin/queue/jobs/#", "a filter straddling the work and response topics"},
		{"$saguin/queue/events", "an append channel's name in the queue space"},
		{"$SYS/#", "the substrate's own tree, which saguin does not serve"},
		{"$share/g/$SYS/#", "the same tree reached through a shared group"},
		{"$share/g/$saguin/queue/jobs", "a queue's form reached through a shared group"},
	} {
		sa := c.Sub(t, tc.filter, 1)
		if sa.Reasons[0] <= 2 {
			t.Errorf("%s was granted 0x%02X to a client an Authorizer allows everything "+
				"for (%s): permission answered before correctness, and a grant that can "+
				"undo a structural refusal is invariant 4's failure wearing a feature's "+
				"clothes", tc.filter, sa.Reasons[0], tc.why)
		}
	}
}

// The other direction, because a seam that is never reached passes the test
// above for the wrong reason.
func TestAnAuthorizerThatRefusesIsAsked(t *testing.T) {
	h := start(t)
	h.B.SetAuthorizer(denyEverything{})

	c := connect(t, h, "forbidden", true, false)
	if sa := c.Sub(t, "events/#", 1); sa.Reasons[0] <= 2 {
		t.Errorf("an ordinary subscription was granted 0x%02X while the Authorizer "+
			"refused everything: the rules are not being asked at all", sa.Reasons[0])
	}
}

// RFC 0002 "Publishing" and RFC 0003 "Retained messages": the CONNACK
// carries Maximum Packet Size, so that a conforming client never sends a
// packet this broker will refuse, and Retain Available, so that a client
// knows before it publishes rather than by being disconnected.
//
// Raw bytes rather than Paho, because the question is which identifiers
// reach the wire. A client library hands back a struct with a field for
// every property, and a field holding zero cannot be told from a property
// that was never sent - which is the entire distinction under test, and
// the direction that reads as "supported" when nothing was said.
func TestTheConnackCarriesTheBoundsItPromises(t *testing.T) {
	h := start(t)
	props, shown := connackProperties(t, h.Addr, "connack-bounds")

	got, ok := props[0x27]
	if !ok {
		t.Errorf("the CONNACK carries no Maximum Packet Size (0x27), so a client "+
			"learns max_message_size by having its connection reset: %s", shown)
	} else if want := limits.MaxMessageSize; len(got) != 4 ||
		binary.BigEndian.Uint32(got) != want {
		t.Errorf("Maximum Packet Size is % 02x, want %d: %s", got, want, shown)
	}

	// This broker holds a latest channel, so the flag can be honoured
	// there and 1 is the truth.
	if got, ok := props[0x25]; !ok {
		t.Errorf("the CONNACK carries no Retain Available (0x25), and MQTT reads "+
			"its absence as supported: %s", shown)
	} else if len(got) != 1 || got[0] != 1 {
		t.Errorf("Retain Available is % 02x, want 1 on a broker holding a latest "+
			"channel: %s", got, shown)
	}
}

// The other branch of the same rule. A broker with no latest channel can
// honour the retain flag nowhere, and a client that reads nothing about it
// concludes the opposite.
func TestTheConnackSaysRetainIsUnavailableWhenNothingCanKeepOne(t *testing.T) {
	h := startWithoutLatest(t)
	props, shown := connackProperties(t, h.Addr, "connack-noretain")

	got, ok := props[0x25]
	if !ok {
		t.Fatalf("the CONNACK carries no Retain Available (0x25) on a broker that "+
			"refuses every retained publish, and absence reads as supported: %s", shown)
	}
	if len(got) != 1 || got[0] != 0 {
		t.Errorf("Retain Available is % 02x, want 0 where no channel can keep one: %s",
			got, shown)
	}
}

// RFC 0001: Topic Alias is offered, capped at sixteen per connection and
// advertised so a client never has to guess.
//
// Raw bytes, because an alias is a wire-level saving and the question is
// what the broker does with the packet: a client library would either send
// one or not, and hide which.
//
// The cap is the whole design. Left at the substrate's default of 65,535
// the table is per connection and bounded by nothing saguin configures -
// 65,535 aliases over 900-byte topics measured 83MB on one connection
// against 5MB for the same traffic without - which is what invariant 13
// refuses.
func TestATopicAliasIsCappedAndAdvertised(t *testing.T) {
	h := start(t)

	props, shown := connackProperties(t, h.Addr, "aliaser")
	got, ok := props[0x22]
	if !ok {
		t.Fatalf("the CONNACK carries no Topic Alias Maximum (0x22), which a client reads as "+
			"none offered: %s", shown)
	}
	if len(got) != 2 || binary.BigEndian.Uint16(got) != 16 {
		t.Fatalf("Topic Alias Maximum is % 02x, want 16: %s", got, shown)
	}

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	sendRawConnect(t, conn, "alias-user")

	// An alias inside the cap: the topic once, then the alias alone.
	publishWithAlias(t, conn, "loose/a-very-long-topic-name-worth-aliasing", 7, "first")
	if code := awaitPuback(t, conn); code >= 0x80 {
		t.Fatalf("a publish carrying alias 7 was refused with 0x%02X", code)
	}
	publishWithAlias(t, conn, "", 7, "second")
	if code := awaitPuback(t, conn); code >= 0x80 {
		t.Fatalf("a publish using the established alias 7 was refused with 0x%02X", code)
	}

	// Past the cap: MQTT-3.3.2-9 asks for 0x94, and it is what bounds the
	// table to sixteen entries however many a client tries to use.
	publishWithAlias(t, conn, "loose/another", 17, "third")
	kind, body := awaitPacket(t, conn)
	if kind>>4 != 14 {
		t.Fatalf("an alias above the cap was answered with packet type %d (% 02x), "+
			"want a DISCONNECT", kind>>4, body)
	}
	if len(body) == 0 || body[0] != 0x94 {
		t.Errorf("disconnected with % 02x, want 0x94 Topic Alias invalid", body)
	}
}

// TestAPropertyTheSpecForbidsAtZeroIsRefused drives the three properties
// whose zero value MQTT calls a protocol error, and asserts the broker
// answers 0x82 rather than accepting them.
//
// Raw bytes rather than Paho, and not for tidiness: paho.golang sends
// Receive Maximum only from a non-nil pointer and will not put a 0 on the
// wire, so through any ordinary client "the broker refused it" and "the
// client never asked" are the same picture, and the second is the one that
// ships. The subscription identifier is the same story - a client library
// numbers its own subscriptions.
//
// All three were accepted before the sixteenth fork patch, and each was
// then acted on as the opposite of what was asked: a client asking to
// receive nothing was sent QoS 1 and 2 with no flow control at all, and one
// declaring packets of no size got no limit.
func TestAPropertyTheSpecForbidsAtZeroIsRefused(t *testing.T) {
	h := start(t)

	// The two that ride in CONNECT, where the refusal is a CONNACK. Its
	// body is the session-present flag then the reason code.
	for _, tc := range []struct {
		name  string
		id    string
		props []byte
		costs string
	}{
		{"receive maximum", "rm-zero", []byte{0x21, 0x00, 0x00},
			"a client that declared it may receive nothing is served as though it had " +
				"asked for everything, with no flow control at all"},
		{"maximum packet size", "mps-zero", []byte{0x27, 0x00, 0x00, 0x00, 0x00},
			"a client that declared packets of no size is served with no limit, which " +
				"is the opposite bound"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			conn, err := net.Dial("tcp", h.Addr)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			defer conn.Close()

			var body []byte
			body = append(body, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x05, 0x02, 0x00, 0x3c)
			body = append(body, byte(len(tc.props)))
			body = append(body, tc.props...)
			body = append(body, byte(len(tc.id)>>8), byte(len(tc.id)))
			body = append(body, tc.id...)
			if _, err := conn.Write(mqttPacket(0x10, body)); err != nil {
				t.Fatalf("write connect: %v", err)
			}

			kind, got := awaitPacket(t, conn)
			if kind>>4 != 2 {
				t.Fatalf("%s of 0 was answered with packet type %d (% 02x), want a CONNACK",
					tc.name, kind>>4, got)
			}
			if len(got) < 2 || got[1] != 0x82 {
				t.Fatalf("%s of 0 was answered CONNACK 0x%02X, want 0x82: %s (% 02x)",
					tc.name, got[1], tc.costs, got)
			}
		})
	}

	// The third rides in SUBSCRIBE, where the refusal is a DISCONNECT.
	t.Run("subscription identifier", func(t *testing.T) {
		conn, err := net.Dial("tcp", h.Addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		defer conn.Close()
		sendRawConnect(t, conn, "subid-zero")

		var body []byte
		body = append(body, 0x00, 0x01) // packet identifier
		body = append(body, 0x02)       // property length
		body = append(body, 0x0b, 0x00) // subscription identifier 0
		body = append(body, 0x00, byte(len("loose/probe")))
		body = append(body, "loose/probe"...)
		body = append(body, 0x01) // options: QoS 1
		if _, err := conn.Write(mqttPacket(0x82, body)); err != nil {
			t.Fatalf("write subscribe: %v", err)
		}

		kind, got := awaitPacket(t, conn)
		if kind>>4 != 14 {
			t.Fatalf("subscription identifier 0 was answered with packet type %d (% 02x), "+
				"want a DISCONNECT - a granted SUBACK here is a subscription stored as "+
				"though it carried no identifier", kind>>4, got)
		}
		if len(got) == 0 || got[0] != 0x82 {
			t.Errorf("disconnected with % 02x, want 0x82 protocol error", got)
		}
	})
}

// A Will is delivered through the ordinary publish path, so it gets what a
// publish gets - and it did not. The substrate's own `mqtt.Will` keeps a
// topic, a payload, a QoS, the retain flag, the delay and the User
// Properties, and nothing else: a Will's Content Type, Payload Format
// Indicator, Message Expiry Interval, Response Topic and Correlation Data
// are read off the CONNECT, validated, and then dropped before anything
// saguin can see.
//
// **The class rather than the flag.** Each of the five is a different kind
// of loss and none of them is visible from the wire: an availability
// message declaring `application/json` arrives as opaque bytes, a Will
// carrying a Response Topic so a monitor can answer it arrives with nowhere
// to answer, and a Will with an expiry becomes one that never expires.
//
// Both destinations, because they are two paths: a broadcast topic is fanned
// out by the substrate from the packet, and a channel's is stored and
// delivered from storage - so a record that did not keep them would pass the
// first half and fail the second.
func TestAWillKeepsEveryPublishPropertyItCarried(t *testing.T) {
	for _, tc := range []struct{ name, filter, topic string }{
		{"broadcast", "house/#", "house/device/status"},
		{"a latest channel", "state/#", "state/device/status"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := startRetaining(t, 0)

			watch := dialProps(t, h, "watcher")
			watch.Sub(t, tc.filter, 1)
			subscribed(t, watch.C)

			conn := connectWithWillProps(t, h, "dying", tc.topic, 0)
			kill(t, conn)

			got := awaitProp(t, watch)
			if got == nil {
				t.Fatal("the Will was not delivered at all")
			}
			if string(got.Payload) != "i-died" {
				t.Fatalf("payload %q, want \"i-died\"", got.Payload)
			}
			if got.Properties == nil {
				t.Fatal("the Will arrived carrying no properties at all")
			}
			pr := got.Properties

			if pr.ContentType != "application/json" {
				t.Errorf("content type %q, want application/json: a consumer holding "+
					"these bytes cannot find out what they are", pr.ContentType)
			}
			if pr.PayloadFormat == nil || *pr.PayloadFormat != 1 {
				t.Errorf("payload format indicator %v, want 1: the Will said its payload "+
					"was UTF-8", pr.PayloadFormat)
			}
			if pr.ResponseTopic != "where/to/answer" {
				t.Errorf("response topic %q, want where/to/answer: a monitor answering "+
					"this Will has nowhere to answer", pr.ResponseTopic)
			}
			if string(pr.CorrelationData) != "ticket-7" {
				t.Errorf("correlation data %q, want ticket-7", pr.CorrelationData)
			}
			if pr.MessageExpiry == nil {
				t.Error("no message expiry: a Will that asked to expire in a minute " +
					"became one that never expires")
			} else if *pr.MessageExpiry == 0 || *pr.MessageExpiry > 60 {
				t.Errorf("message expiry %d, want the 60 it set, decremented at most by "+
					"the wait", *pr.MessageExpiry)
			}

			// The one that already worked, asserted so a regression in the
			// other direction is caught by the same test.
			var tenant string
			for _, u := range pr.User {
				if u.Key == "tenant" {
					tenant = u.Value
				}
			}
			if tenant != "acme" {
				t.Errorf("the Will's own user property is %q, want acme", tenant)
			}
		})
	}

	// **A client that sent no client id at all**, which MQTT 5 allows: the
	// server assigns one and says so in the CONNACK. The properties are
	// kept at CONNECT, where the only id in hand is the one the *client*
	// sent - so if they are filed under that and read back under the
	// assigned one, every such client loses them and no other test would
	// see it.
	t.Run("a client the server had to name", func(t *testing.T) {
		h := startRetaining(t, 0)

		watch := dialProps(t, h, "watcher")
		watch.Sub(t, "house/#", 1)
		subscribed(t, watch.C)

		conn := connectWithWillProps(t, h, "", "house/device/status", 0)
		kill(t, conn)

		got := awaitProp(t, watch)
		if got == nil {
			t.Fatal("the Will of a client with no id of its own was not delivered")
		}
		if got.Properties == nil || got.Properties.ContentType != "application/json" {
			t.Errorf("it arrived without its content type: %+v; the properties are "+
				"filed under the id the client sent and read back under the one the "+
				"server assigned", got.Properties)
		}
	})

	// **The delayed path is a different carrier and so a different test.**
	// An immediate Will is published on the goroutine that read the
	// CONNECT-time properties; a delayed one fires from a timer long after
	// the client is gone and its entry has been dropped at disconnect, so
	// the properties travel with the held Will instead. A fix that only
	// covered the first would leave every device with a Will Delay Interval
	// - which is every device on a flapping link, the case a delay exists
	// for - losing them exactly as before.
	t.Run("a delayed Will", func(t *testing.T) {
		h := startRetaining(t, 0)

		watch := dialProps(t, h, "watcher")
		watch.Sub(t, "house/#", 1)
		subscribed(t, watch.C)

		conn := connectWithWillProps(t, h, "slow-dying", "house/device/status", 1)
		kill(t, conn)

		got := awaitProp(t, watch)
		if got == nil {
			t.Fatal("the delayed Will was not delivered")
		}
		if got.Properties == nil || got.Properties.ContentType != "application/json" {
			t.Errorf("a delayed Will arrived without its content type: %+v", got.Properties)
		}
		if got.Properties != nil && got.Properties.ResponseTopic != "where/to/answer" {
			t.Errorf("response topic %q, want where/to/answer", got.Properties.ResponseTopic)
		}
		if got.Properties != nil && string(got.Properties.CorrelationData) != "ticket-7" {
			t.Errorf("correlation data %q, want ticket-7", got.Properties.CorrelationData)
		}
	})
}

// willACL has one named user whose role writes every destination a Will is
// aimed at below, and gives everyone else - the watchers, and a named user
// with no rule of their own - a role that only reads them. A Will judged as
// anybody but its own client is therefore refused.
const willACL = "roles:\n" +
	"  sensor:\n" +
	"    - topic: \"house/#\"\n      allow: [write, read]\n" +
	"    - channel: state\n      allow: [write, read]\n" +
	"  reader:\n" +
	"    - topic: \"house/#\"\n      allow: [read]\n" +
	"    - channel: state\n      allow: [read]\n" +
	"users:\n  \"sensor-a\": [sensor]\n  \"*\": [reader]\n"

// willACLRevoked is willACL after a reload that took `write` away from the
// sensor role.
const willACLRevoked = "roles:\n" +
	"  sensor:\n" +
	"    - topic: \"house/#\"\n      allow: [read]\n" +
	"    - channel: state\n      allow: [read]\n" +
	"users:\n  \"sensor-a\": [sensor]\n  \"*\": [sensor]\n"

// connectNamedWithWill connects id as user with a QoS 1 Will on topic
// carrying two User Properties, and answers the raw connection, whose Close
// is a link cut, and the CONNACK's reason code. user "" connects anonymously.
func connectNamedWithWill(t *testing.T, h *brokertest.Harness, id, user, topic string, clean bool, delay, expiry uint32) (net.Conn, byte) {
	t.Helper()
	raw, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	t.Cleanup(func() { _ = raw.Close() })
	c := paho.NewClient(paho.ClientConfig{Conn: pahopackets.NewThreadSafeConn(raw)})
	cp := &paho.Connect{ClientID: id, CleanStart: clean, KeepAlive: 60,
		Properties:  &paho.ConnectProperties{SessionExpiryInterval: &expiry},
		WillMessage: &paho.WillMessage{Topic: topic, QoS: 1, Payload: []byte("i-died")},
		WillProperties: &paho.WillProperties{WillDelayInterval: &delay,
			User: paho.UserProperties{{Key: "tenant", Value: "acme"}, {Key: "site", Value: "7"}}}}
	if user != "" {
		cp.Username, cp.UsernameFlag = user, true
		cp.Password, cp.PasswordFlag = []byte(h.Authenticate(t, user)), true
	}
	ca, err := c.Connect(context.Background(), cp)
	if ca != nil {
		return raw, ca.ReasonCode
	}
	if err != nil {
		t.Fatalf("connect %s: %v", id, err)
	}
	return raw, 0
}

// RFC 0003 "Last Will": a Will published from its session's record - one
// that waited out its delay, one its session's ending owed, one a start found
// owed - is delivered with its User Properties, and is judged against the
// acl_file as the client that armed it.
//
// **The rules make the second half observable.** Only `sensor-a` may write
// where the Will goes, so a Will judged as anybody else - as nobody, which is
// what a record that lost the name would be judged as - is refused, and the
// watcher, which may only read, is never sent it. Each arm also proves its
// Will took the path it names, by the cause it was counted under.
func TestAWillFromItsRecordIsItsClientsWithItsUserProperties(t *testing.T) {
	for _, path := range []string{"delayed", "session_ended", "start"} {
		for _, p := range []string{"memory", "sqlite"} {
			t.Run(path+"/"+p, func(t *testing.T) {
				var r restartable
				for _, c := range restartables(t) {
					if c.name == p {
						r = c
					}
				}
				h := r.start(t)
				brokertest.WriteACL(t, h, willACL)
				w := dial(t, h, "watcher", false, false, 0, 3600, 0)
				w.Sub(t, "house/#", 1)

				delay := uint32(1)
				if path != "delayed" {
					delay = 30
				}
				if path == "start" {
					delay = 2
				}
				conn, code := connectNamedWithWill(t, h, "dev", "sensor-a", "house/dev", true, delay, 600)
				if code != 0 {
					t.Fatalf("sensor-a's CONNECT, whose role writes house/#, was answered 0x%02x", code)
				}
				_ = conn.Close()
				eventually(t, "the Will held for its delay", 5*time.Second, func() bool {
					_, ok := h.B.PendingWillFire("dev")
					return ok
				})
				switch path {
				case "session_ended":
					// A clean start under the id ends the session the Will
					// waited in.
					_ = connect(t, h, "dev", true, false)
				case "start":
					h.Stop()
					time.Sleep(2500 * time.Millisecond)
					brokertest.StartACL = willACL
					t.Cleanup(func() { brokertest.StartACL = "" })
					h = r.start(t)
					w = dial(t, h, "watcher", false, false, 0, 3600, 0)
				}
				got, ok := w.Await(t, 5*time.Second)
				if n := h.B.WillsPublished(path); n != 1 {
					t.Fatalf("%d Wills published as %s (refused %d), want 1: the Will did not take "+
						"this path, or was refused as someone other than sensor-a",
						n, path, h.B.PublishesRefused("not authorized"))
				}
				if !ok {
					t.Fatal("counted as published, and the watcher was sent nothing")
				}
				t.Logf("received: %+v", got)
				if got.Topic != "house/dev" || got.Payload != "i-died" {
					t.Fatalf("got %+v, want the Will", got)
				}
				if got.User["tenant"] != "acme" || got.User["site"] != "7" {
					t.Errorf("the Will arrived with User Properties %v, want tenant=acme and site=7", got.User)
				}
			})
		}
	}
}

// RFC 0003 "Last Will": a Will whose session ends with its connection is
// published at the disconnect, however long a delay it asked for, and Sagüin
// says so in its log, naming the client and the delay it asked for. A
// CONNECT says its session ends with it in two ways - leaving the Session
// Expiry Interval out, or stating 0 - and the line was written for the first
// only: the engine capped the delay to a stated expiry before Sagüin saw it.
func TestAWillDelayNotHonouredIsSaidHoweverTheExpiryIsWritten(t *testing.T) {
	var mu sync.Mutex
	var lines []string
	h := brokertest.StartLogging(t, func(l string) {
		mu.Lock()
		lines = append(lines, l)
		mu.Unlock()
	})
	said := func(id string) bool {
		mu.Lock()
		defer mu.Unlock()
		for _, l := range lines {
			if strings.Contains(l, "a Will delay was not honoured") && strings.Contains(l, id) &&
				strings.Contains(l, "asked_s=30") {
				return true
			}
		}
		return false
	}
	w := connect(t, h, "watcher", true, false)
	w.Sub(t, "house/#", 1)

	for _, tc := range []struct{ how, id string }{
		{"the Session Expiry Interval left out", "dev-a"},
		{"a Session Expiry Interval of 0 stated", "dev-b"},
	} {
		var conn net.Conn
		var code byte
		if tc.id == "dev-a" {
			conn, code = connectWithWillExpiring(t, h, tc.id, "house/"+tc.id, false, 30, 1, 0)
		} else {
			conn, code = connectNamedWithWill(t, h, tc.id, "", "house/"+tc.id, true, 30, 0)
		}
		if code != 0 {
			t.Fatalf("%s: connect answered %#x", tc.how, code)
		}
		_ = conn.Close()
		if got, ok := w.Await(t, 3*time.Second); !ok || got.Topic != "house/"+tc.id {
			t.Fatalf("%s: the Will was not published at the disconnect: ok=%v %+v", tc.how, ok, got)
		}
		eventually(t, tc.how+": the line saying the delay was not honoured", 2*time.Second,
			func() bool { return said(tc.id) })
	}
}

// A delayed Will is published before it is taken off its record, the order
// every other Will path keeps (RFC 0003 "Last Will": at least once across a
// crash). Taken off first, a crash between the two lost it. And the take that
// follows the publish takes only the Will it published: a connection that
// resumed the id meanwhile with a Will of its own keeps it.
func TestADelayedWillIsPublishedBeforeItLeavesItsRecord(t *testing.T) {
	for _, p := range []string{"memory", "sqlite"} {
		for _, claim := range []bool{false, true} {
			name := p
			if claim {
				name += "/the id resumed with its own Will meanwhile"
			}
			t.Run(name, func(t *testing.T) {
				r := freshRestartable(t, p)
				g := &willAppendGate{entered: make(chan struct{}), release: make(chan struct{})}
				gateLog(t, "events", func(lg broker.LogStore) broker.LogStore { g.LogStore = lg; return g })
				h := r.start(t)
				w := connect(t, h, "watcher", true, false)
				w.Sub(t, "events/wills/#", 1)
				var once sync.Once
				let := func() { once.Do(func() { close(g.release) }) }
				t.Cleanup(let)

				conn, code := connectNamedWithWill(t, h, "dev", "", "events/wills/dev", true, 1, 60)
				if code != 0 {
					t.Fatalf("connect: %#x", code)
				}
				g.armed.Store(true)
				_ = conn.Close()
				select {
				case <-g.entered:
				case <-time.After(5 * time.Second):
					t.Fatal("the delayed Will's Append was never entered, so this proves nothing")
				}
				rec, ok, _ := brokertest.HarnessSessions.Get("dev")
				if !ok || rec.Will == nil {
					t.Errorf("the record no longer held the Will as it was published: kept=%v Will=%+v", ok, rec.Will)
				}
				if claim {
					back, code := connectNamedWithWill(t, h, "dev", "", "events/wills/dev-new", false, 30, 60)
					if code != 0 {
						t.Fatalf("resume: %#x", code)
					}
					defer back.Close()
				}
				let()
				if got, ok := w.Await(t, 3*time.Second); !ok || got.Topic != "events/wills/dev" {
					t.Fatalf("the delayed Will was not delivered: ok=%v %+v", ok, got)
				}
				eventually(t, "the record settled", 3*time.Second, func() bool {
					rec, ok, _ := brokertest.HarnessSessions.Get("dev")
					if claim {
						return ok && rec.Will != nil && rec.Will.Topic == "events/wills/dev-new"
					}
					return ok && rec.Will == nil
				})
			})
		}
	}
}

// The take after a delayed Will's publish never takes a Will another
// connection armed. A Will whose due moment the store refused to stamp sits
// on its record with none, and a resume inside the publish window writes its
// own with none as well: the due moment alone took them for the same, and
// the resumed session's Will was taken from its record - an announcement
// lost (this test's first arm). The second arm has the
// store refuse the disconnect's write too, so the record's moment cannot
// tell them apart either, and what does is that a connection holds the id.
// The third has the resumed connection go again inside the window, its own
// stamp refused too: no connection holds the id and neither Will has a due
// moment, and what tells them apart is the moment the record says it went.
func TestAResumedWillIsNotTakenForOneWhoseStampWasRefused(t *testing.T) {
	for _, p := range []string{"memory", "sqlite"} {
		for _, arm := range []string{"", "the disconnect refused as well", "the id came and went meanwhile"} {
			disc, went := arm == "the disconnect refused as well", arm == "the id came and went meanwhile"
			name := p
			if arm != "" {
				name += "/" + arm
			}
			t.Run(name, func(t *testing.T) {
				r := freshRestartable(t, p)
				rt := &refusesWillTakeOff{}
				brokertest.WrapSessions = func(s broker.SessionStore) broker.SessionStore {
					rt.SessionStore = s
					return rt
				}
				t.Cleanup(func() { brokertest.WrapSessions = nil })
				g := &willAppendGate{entered: make(chan struct{}), release: make(chan struct{})}
				gateLog(t, "events", func(lg broker.LogStore) broker.LogStore { g.LogStore = lg; return g })
				h := r.start(t)
				w := connect(t, h, "watcher", true, false)
				w.Sub(t, "events/wills/#", 1)
				var once sync.Once
				let := func() { once.Do(func() { close(g.release) }) }
				t.Cleanup(let)

				conn, code := connectNamedWithWill(t, h, "dev", "", "events/wills/dev", true, 1, 60)
				if code != 0 {
					t.Fatalf("connect: %#x", code)
				}
				want := int32(1)
				rt.stamp.Store(true)
				if disc {
					rt.disc.Store(true)
					want = 2
				}
				g.armed.Store(true)
				_ = conn.Close()
				select {
				case <-g.entered:
				case <-time.After(5 * time.Second):
					t.Fatal("the delayed Will's Append was never entered, so this proves nothing")
				}
				if n := rt.failed.Load(); n != want {
					t.Fatalf("the store refused %d writes, want %d, so this proves nothing", n, want)
				}
				back, code := connectNamedWithWill(t, h, "dev", "", "events/wills/dev-new", false, 30, 60)
				if code != 0 {
					t.Fatalf("resume: %#x", code)
				}
				defer back.Close()
				if went {
					// Gone again, its own Will held with its stamp refused
					// too: no due moment on it, and no connection holding the
					// id, so only the moment it went tells the two apart.
					rt.stamps.Store(1)
					_ = back.Close()
					eventually(t, "the resumed connection's Will held", 3*time.Second, func() bool {
						_, ok := h.B.PendingWillFire("dev")
						return ok
					})
				}
				taken := make(chan struct{}, 1)
				t.Cleanup(broker.SetAfterWillTaken(func(id string) {
					if id == "dev" {
						select {
						case taken <- struct{}{}:
						default:
						}
					}
				}))
				let()
				if got, ok := w.Await(t, 3*time.Second); !ok || got.Topic != "events/wills/dev" {
					t.Fatalf("the delayed Will was not delivered: ok=%v %+v", ok, got)
				}
				// Past the take: the record still holds the resumed
				// connection's Will.
				select {
				case <-taken:
				case <-time.After(5 * time.Second):
					t.Fatal("the delayed Will's take never ran, so the record below says nothing about it")
				}
				rec, ok, _ := brokertest.HarnessSessions.Get("dev")
				if !ok || rec.Will == nil || rec.Will.Topic != "events/wills/dev-new" {
					t.Fatalf("the resumed connection's Will was taken from its record: kept=%v Will=%+v", ok, rec.Will)
				}
			})
		}
	}
}

// freshRestartable is the provider named, on storage of its own: a subtest
// sharing restartables' directory with the one before it restarts that one's
// sessions, and what they owe arrives in its own.
func freshRestartable(t *testing.T, name string) restartable {
	t.Helper()
	for _, r := range restartables(t) {
		if r.name == name {
			return r
		}
	}
	t.Fatalf("no provider %q", name)
	return restartable{}
}

// writesOnce passes its first write, the CONNACK, and refuses every later
// one, as a socket that dies straight after it would.
type writesOnce struct {
	net.Conn
	writes atomic.Int32
}

func (c *writesOnce) Write(b []byte) (int, error) {
	if c.writes.Add(1) > 1 {
		return 0, errors.New("refused for the test")
	}
	return c.Conn.Write(b)
}

// A connection that resumes a session and dies as its in-flight messages
// are resent is a device that died (RFC 0003 "Last Will"): its Will is
// published, and the session store is told it went, so its session ends
// at its expiry. The engine returned at the failed resend with neither -
// the Will never went, and the record went on saying the client was
// connected, which a later start reads as a Will with nothing to make it
// due.
func TestAConnectionThatDiesAtItsResendIsAnnouncedAndRecorded(t *testing.T) {
	for _, r := range restartables(t) {
		t.Run(r.name, func(t *testing.T) {
			h := r.start(t)
			w := connect(t, h, "watcher", true, false)
			w.Sub(t, "wills/#", 1)
			// A durable session holding a delivery it has not acknowledged,
			// so resuming it resends one.
			dev := dial(t, h, "dev", false, true, 0, 60, 0)
			dev.Sub(t, "news/#", 1)
			pub := connect(t, h, "pub", true, false)
			pub.Pub(t, "news/x", "hello")
			if _, ok := dev.Await(t, 3*time.Second); !ok {
				t.Fatal("dev was not sent the message it is to hold unacknowledged")
			}

			// Resumed through a socket that takes the CONNACK and nothing
			// after it: MQTT 5, Clean Start 0, a 60 s session and a Will
			// with no delay.
			body := []byte{0x00, 0x04, 'M', 'Q', 'T', 'T', 0x05, 0x04, 0x00, 0x3c,
				0x05, 0x11, 0x00, 0x00, 0x00, 0x3c}
			body = append(body, 0x00, 0x03, 'd', 'e', 'v', 0x00)
			for _, f := range []string{"wills/dev", "bye"} {
				body = append(body, byte(len(f)>>8), byte(len(f)))
				body = append(body, f...)
			}
			a, b := net.Pipe()
			defer b.Close()
			conn := &writesOnce{Conn: a}
			done := make(chan error, 1)
			go func() { done <- h.Srv.EstablishConnection("tcp", conn) }()
			go func() { _, _ = b.Write(append([]byte{0x10, byte(len(body))}, body...)) }()
			go func() { _, _ = io.Copy(io.Discard, b) }()
			select {
			case err := <-done:
				if err == nil || !strings.Contains(err.Error(), "resend inflight") {
					t.Fatalf("the connection ended with %v, not at its resend, so this proves nothing", err)
				}
			case <-time.After(5 * time.Second):
				t.Fatal("the resumed connection never ended")
			}

			if got, ok := w.Await(t, 3*time.Second); !ok || got.Payload != "bye" {
				t.Errorf("the Will of a connection that died at its resend was not published: ok=%v %+v", ok, got)
			}
			eventually(t, "the store told the client went", 3*time.Second, func() bool {
				rec, ok, _ := brokertest.HarnessSessions.Get("dev")
				return ok && !rec.DisconnectedAt.IsZero()
			})
		})
	}
}

// A Will is a publish the client asks the broker to make for it, so it
// meets the client's own write rules (RFC 0002 "What a client may do", RFC
// 0003 "Last Will"): at CONNECT, where the device can be told `0x87`, and
// again when it fires, because the acl_file may have been reloaded since.
// Without either, a role that only reads a `latest` channel overwrote its
// state by dropping its link.
func TestAWillIsJudgedAgainstItsClientsWriteRules(t *testing.T) {
	for _, tc := range []struct{ name, filter, topic string }{
		{"broadcast", "house/#", "house/dev"},
		{"a latest channel", "state/#", "state/dev"},
	} {
		t.Run(tc.name+"/at CONNECT", func(t *testing.T) {
			h := start(t)
			brokertest.WriteACL(t, h, willACL)
			w := connect(t, h, "watcher", true, false)
			w.Sub(t, tc.filter, 1)
			// **The subscription's catch-up has run before the control's
			// Will exists.** It runs after the SUBACK is written, so the
			// SUBACK says nothing about it: run late, it sent the control's
			// Will again, flagged retained (RFC 0003 "a subscriber receives
			// both"), and the check below read that copy as the refused
			// client's Will - offset 1 every time with the catch-up held
			// 300ms. w's next packet is read only after it returns, so a
			// second SUBACK is the proof; a SUBSCRIBE, because this role may
			// not publish the barrier settle would send, and to a topic
			// nothing here publishes.
			w.Sub(t, "house/settled", 1)

			// The control: the same Will from the role that writes there is
			// admitted and delivered, so a refusal below is about the rules.
			conn, code := connectNamedWithWill(t, h, "dev-a", "sensor-a", tc.topic, true, 0, 0)
			if code != 0 {
				t.Fatalf("sensor-a's CONNECT was answered 0x%02x, want 0x00", code)
			}
			_ = conn.Close()
			if got, ok := w.Await(t, 5*time.Second); !ok || got.Topic != tc.topic {
				t.Fatalf("sensor-a's Will: delivered=%v %+v, want it on %s", ok, got, tc.topic)
			}

			refusedBefore := h.B.PublishesRefused("not authorized")
			_, code = connectNamedWithWill(t, h, "dev-b", "reader-b", tc.topic, true, 0, 0)
			if code != 0x87 {
				t.Fatalf("a CONNECT whose Will is on %s, from a role that only reads it, was answered "+
					"0x%02x, want 0x87", tc.topic, code)
			}
			if got, ok := w.Await(t, 1500*time.Millisecond); ok {
				t.Fatalf("after the refused CONNECT the watcher was sent %+v, want nothing", got)
			}
			if n := h.B.PublishesRefused("not authorized") - refusedBefore; n != 0 {
				t.Errorf("a refused CONNECT counted %d refused publishes: it is a connection "+
					"refused, and publishes nothing", n)
			}
		})

		t.Run(tc.name+"/when it fires, after a reload", func(t *testing.T) {
			h := start(t)
			brokertest.WriteACL(t, h, willACL)
			w := connect(t, h, "watcher", true, false)
			w.Sub(t, tc.filter, 1)

			conn, code := connectNamedWithWill(t, h, "dev", "sensor-a", tc.topic, true, 1, 600)
			if code != 0 {
				t.Fatalf("sensor-a's CONNECT was answered 0x%02x, want 0x00", code)
			}
			brokertest.WriteACL(t, h, willACLRevoked)
			_ = conn.Close()
			eventually(t, "the held Will to fire", 5*time.Second, func() bool {
				_, ok := h.B.PendingWillFire("dev")
				return !ok
			})
			if got, ok := w.Await(t, 1500*time.Millisecond); ok {
				t.Fatalf("a Will whose client lost write on %s before it fired was published: %+v", tc.topic, got)
			}
			if n := h.B.PublishesRefused("not authorized"); n != 1 {
				t.Errorf("saguin_publish_refused_total{reason=\"not authorized\"} is %d, want 1", n)
			}
			if n := h.B.WillsPublished("delayed"); n != 0 {
				t.Errorf("a refused Will was counted published (%d)", n)
			}
		})
	}

	// The start judges an owed Will against the rules as the start found
	// them, not as they were when it was armed.
	for _, r := range restartables(t) {
		t.Run("at a start, after a reload/"+r.name, func(t *testing.T) {
			h := r.start(t)
			brokertest.WriteACL(t, h, willACL)
			w := dial(t, h, "watcher", false, false, 0, 3600, 0)
			w.Sub(t, "house/#", 1)
			conn, code := connectNamedWithWill(t, h, "dev", "sensor-a", "house/dev", true, 2, 600)
			if code != 0 {
				t.Fatalf("sensor-a's CONNECT was answered 0x%02x, want 0x00", code)
			}
			_ = conn.Close()
			eventually(t, "the Will held for its delay", 5*time.Second, func() bool {
				_, ok := h.B.PendingWillFire("dev")
				return ok
			})
			h.Stop()
			time.Sleep(2500 * time.Millisecond)
			brokertest.StartACL = willACLRevoked
			t.Cleanup(func() { brokertest.StartACL = "" })
			h = r.start(t)
			if n := h.B.PublishesRefused("not authorized"); n != 1 {
				t.Fatalf("the start refused %d publishes, want the owed Will's 1 (published as start: %d)",
					n, h.B.WillsPublished("start"))
			}
			w = dial(t, h, "watcher", false, false, 0, 3600, 0)
			if got, ok := w.Await(t, 1500*time.Millisecond); ok {
				t.Fatalf("a Will the reloaded rules refuse was published at the start: %+v", got)
			}
		})
	}
}

// RFC 0003 "Last Will": a Will is delivered through the ordinary publish
// path, so it reaches broadcast or any channel type and gets everything a
// publish gets.
//
// Each row fails differently if this breaks, which is why they are one
// test: a channel topic must be *stored* rather than merely reaching live
// subscribers, a queue must produce an ordinary job, and broadcast must
// still go out through the server's own fan-out.
// **Every destination at both QoS levels**, and the QoS is the axis that
// was missing rather than a thoroughness flourish. A Will is injected
// rather than sent to anybody, and a QoS 1 packet with no packet
// identifier is a protocol violation the substrate refuses - so every Will
// armed at QoS 1 was accepted at CONNECT, answered `0x00`, and then
// silently never delivered, with one WARN line on the broker and nothing at
// all reaching the client that armed it. That is the failure this project
// ranks worst: it reported success and lost the announcement.
//
// It survived eleven days because the table drove four destinations and
// every one of them at QoS 0.
func TestAWillIsDelivered(t *testing.T) {
	for _, tc := range []struct {
		name, topic string
		stored      bool
	}{
		{"a broadcast topic", "loose/from-a-will", false},
		{"an append channel", "events/from-a-will", true},
		{"a latest channel", "state/from-a-will", true},
		{"a queue", "jobs/from-a-will", true},
	} {
		for _, qos := range []byte{0, 1} {
			t.Run(fmt.Sprintf("%s at QoS %d", tc.name, qos), func(t *testing.T) {
				willDelivered(t, tc.topic, tc.stored, qos)
			})
		}
	}
}

// A Will that could never be delivered is refused at CONNECT, where the
// device is still there to be told. Every one of these is permanent for
// that client's configuration: trying again changes nothing, so silence
// would leave a fleet believing its monitoring was armed.
func TestAWillThatCannotBeDeliveredIsRefusedAtConnect(t *testing.T) {
	long := "x/" + strings.Repeat("y", 1100)
	for _, tc := range []struct {
		name, topic string
		retain      bool
		want        byte
	}{
		{"the reserved space", "$saguin/queue/jobs/response", false, 0x90},
		{"a dead-letter channel", "jobs/__dlq/from-a-will", false, 0x90},
		{"over max_topic_length", long, false, 0x90},
		{"retained, with nowhere to keep it", "loose/from-a-will", true, 0x9A},
		// A wildcard in a topic name is the one that costs durably. Stored,
		// it is at the head of the channel for ever: MQTT-3.3.2-2 forbids it
		// in a delivery as firmly as in a publish, so every conforming
		// consumer closes the connection on reaching it, and on a `latest`
		// channel no client can remove it - deleting a value means
		// publishing an empty payload to its topic, which is this same
		// refused publish. All four accepted before this test existed.
		{"a single-level wildcard, on a channel", "events/+", false, 0x90},
		{"a multi-level wildcard, on a channel", "events/#", false, 0x90},
		{"a wildcard alone, on broadcast", "#", false, 0x90},
		// And the tree the broker keeps about itself. A Will was the one way
		// to write to it: a publish there is answered 0x87.
		{"the reserved $SYS space", "$SYS/broker/version", false, 0x90},
		// **A retained Will into a queue is accepted**, and the row stays
		// to say so rather than being deleted. It is still the availability
		// pattern aimed at the wrong channel type - one worker takes it
		// once and the dashboard never sees it - but the publish path takes
		// a retained publish to a queue and drops the flag, so refusing the
		// same message here would mean a device could publish it all day
		// and be turned away at CONNECT for promising to send it.
		{"retained, into a queue", "jobs/from-a-will", true, 0x00},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			conn, code := connectWithWill(t, h, "dying", tc.topic, tc.retain, 0, 0)
			defer conn.Close()
			if code != tc.want {
				t.Fatalf("the connection was answered 0x%02X, want 0x%02X", code, tc.want)
			}
		})
	}
}

// saguin publishes nothing under `$SYS` (RFC 0005), and neither does the
// engine it carries: the upstream substrate published twenty counters there
// every second, and the in-tree engine has had no `$SYS` publisher since
// it was removed - which is why the hook that cleared the tree at start is gone.
// Two of those counters were wrong about saguin rather than merely
// irrelevant: `version` named the substrate, and `retained` counted a store
// saguin empties as fast as it fills. A dashboard reading a wrong number is
// worse off than one reading nothing, and `$SYS/broker/version` is the first
// thing anybody points at a new broker; this keeps it from coming back.
//
// Three things have to hold, and each fails differently:
//
//   - The wildcard filter is refused. This is the one somebody sweeps with.
//   - **The literal topic is refused too**, which is the half an obvious
//     implementation misses: saguin's authorization hook answers true early
//     for anything carrying no wildcard, so a check placed after that return
//     would silence `$SYS/#` and hand over `$SYS/broker/version` - the exact
//     topic the two wrong counters are on.
//   - The store stays empty *later*. Clearing the tree once passes while a
//     ticker rewrites it a second afterwards, so this waits past several of
//     the rounds that used to happen and reads the store again.
func TestNothingUnderSysIsServedOrRewritten(t *testing.T) {
	h := start(t)
	c := connect(t, h, "dashboard", true, false)

	// Read what the broker answered rather than what the client made of it.
	// `sub` returns the SUBACK whether or not Paho calls the refusal an
	// error, which is the whole reason it is the helper used here.
	for _, filter := range []string{"$SYS/#", "$SYS/broker/version", "$SYS/broker/retained"} {
		sa := c.Sub(t, filter, 0)
		if sa == nil || len(sa.Reasons) != 1 {
			t.Fatalf("subscribe %s: no SUBACK to read", filter)
		}
		if sa.Reasons[0] != 0x87 {
			t.Errorf("subscribe %s answered 0x%02X, want 0x87 (Not authorized)",
				filter, sa.Reasons[0])
		}
	}

	// Nothing arrives on any of the three, and nothing was handed over
	// retained on subscribe either - which is the delivery path a granted
	// subscription would have taken.
	if got, ok := c.Await(t, 2*time.Second); ok {
		t.Errorf("a client was delivered %q %q under $SYS", got.Topic, got.Payload)
	}

	// The refresh ran every second before this, so two rounds have now
	// passed. An empty store here is the ticker being stopped rather than
	// the tree merely having been cleared at startup.
	if left := h.B.RetainedElsewhere(); len(left) != 0 {
		t.Errorf("the substrate's retained store holds %d messages after 2s, want none: %q",
			len(left), left)
	}
}

// The same rule, asked of the publisher that has no CONNECT to be refused
// at. saguin has three in-process publishers - a queue delivery, a Will,
// and an inbound bridge - and the substrate's own topic-name check exempts
// all of them, because it asks how the publish arrived rather than what it
// says. Invariant 10: the broker is the only enforcement point, and an
// exemption keyed on the door is not one.
//
// A bridge is the one this test can drive, and what it proves is narrower
// than it first looks: `BridgeClient.Publish` reaches the publish path with
// such a topic, but **no bridge configuration can** - a rule producing a
// topic that begins with `$` is dropped by the bridge's own engine, and one
// naming it literally is refused when the file loads. So this asserts the
// broker's own guard rather than a hole an upstream broker could reach
// through. The hole that was reachable was the Will, which anyone who could
// open a socket could plant.
func TestAnInProcessPublisherIsHeldToTheTopicRule(t *testing.T) {
	h := start(t)

	watcher := dialProps(t, h, "watcher")
	// `events/#` only. This watched `$SYS/#` too, and could not now: saguin
	// refuses that subscription, which is what silences the tree. What
	// replaces it for the `$SYS` topic below is the substrate's own retained
	// store, checked at the end - a retained publish landing there is what a
	// hole in the refusal would look like, and it is a stronger reading than
	// a watcher's channel because it needs no waiting to be believed.
	watcher.Sub(t, "events/#", 0)

	bc := h.B.NewBridgeClient("upstream")
	for _, topic := range []string{"$SYS/broker/version", "events/+", "events/#"} {
		if err := bc.Publish(topic, []byte("from-upstream"), nil, store.Props{}); err == nil {
			t.Errorf("a bridge published to %q and the path accepted it", topic)
		}
	}

	deadline := time.After(2 * time.Second)
	for done := false; !done; {
		select {
		case m := <-watcher.Ch:
			if string(m.Payload) == "from-upstream" {
				t.Errorf("a bridged record reached a subscriber on %q", m.Topic)
				done = true
			}
		case <-deadline:
			done = true
		}
	}

	// And nothing was stored, which is the half a live subscriber cannot
	// see: a record in the channel stops every consumer that reads it.
	late := connect(t, h, "late", true, false)
	late.Sub(t, "events/#", 1)
	if got, ok := late.Await(t, 2*time.Second); ok {
		t.Errorf("the channel replayed %q %q, so a refused topic was stored anyway",
			got.Topic, got.Payload)
	}

	// The `$SYS` publish leaves the same evidence in the one store it could
	// have reached, and this reads it directly rather than inferring it from
	// silence on a filter that cannot be subscribed.
	if left := h.B.RetainedElsewhere(); len(left) != 0 {
		t.Errorf("the substrate's retained store holds %d messages, want none: %q",
			len(left), left)
	}
}

// The availability pattern, which is the reason this feature is worth
// having: a device sets a retained Will, dies, and a dashboard connecting
// afterwards is told it is offline.
func TestARetainedWillBecomesCurrentState(t *testing.T) {
	h := start(t)

	conn, code := connectWithWill(t, h, "device", "state/device/status", true, 0, 0)
	if code != 0x00 {
		t.Fatalf("a retained Will into a latest channel was refused with 0x%02X - "+
			"this is the standard availability pattern", code)
	}
	kill(t, conn)
	sessionGone(t, h, "device") // its Will published as the connection went

	dashboard := connect(t, h, "dashboard", true, false)
	dashboard.Sub(t, "state/#", 1)
	got, ok := dashboard.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a dashboard arriving after the device died was told nothing")
	}
	if got.Topic != "state/device/status" || got.Payload != "i-died" {
		t.Fatalf("received %q %q, want state/device/status i-died", got.Topic, got.Payload)
	}
}

// RFC 0003 "Retained messages": a broker with no retained store attached has
// nowhere to keep one, and saguin says so rather than dropping the flag and
// acknowledging the publish - which would tell a producer its state was
// kept when nothing kept it.
//
// The binary always attaches the store, so this is the defensive guard on
// the harness with none, which is the harness default. The other half of
// the rule has a harness of its own.
//
// Raw bytes, because a client library may refuse to send a retained publish
// on its own account and the question is what the broker does.
func TestARetainedPublishIsRefused(t *testing.T) {
	h := start(t)

	// Somebody who would see it if it were kept.
	watcher := connect(t, h, "watcher", true, false)
	watcher.Sub(t, "#", 1)
	subscribed(t, watcher.C)

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	connect := []byte{
		0x10, 0x11,
		0x00, 0x04, 'M', 'Q', 'T', 'T',
		0x05, 0x02, 0x00, 0x3c, 0x00,
		0x00, 0x04, 'k', 'e', 'e', 'p',
	}
	if _, err := conn.Write(connect); err != nil {
		t.Fatalf("write connect: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	fh := make([]byte, 2)
	if _, err := io.ReadFull(conn, fh); err != nil {
		t.Fatalf("no CONNACK: %v", err)
	}
	ca := make([]byte, int(fh[1]))
	if _, err := io.ReadFull(conn, ca); err != nil {
		t.Fatalf("short CONNACK: %v", err)
	}

	// PUBLISH QoS 1 with RETAIN set (fixed header 0x33).
	topic := []byte("loose/kept")
	var body []byte
	body = append(body, byte(len(topic)>>8), byte(len(topic)))
	body = append(body, topic...)
	body = append(body, 0x00, 0x01) // packet identifier
	body = append(body, 0x00)       // no properties
	body = append(body, 'x')
	if _, err := conn.Write(append([]byte{0x33, byte(len(body))}, body...)); err != nil {
		t.Fatalf("write publish: %v", err)
	}

	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	reply := make([]byte, 2)
	if _, err := io.ReadFull(conn, reply); err != nil {
		t.Fatalf("nothing came back for a retained publish: %v", err)
	}
	tail := make([]byte, int(reply[1]))
	_, _ = io.ReadFull(conn, tail)

	if reply[0]>>4 == 4 {
		t.Fatalf("a retained publish was acknowledged: PUBACK % 02x - "+
			"the flag would be dropped and the producer told it was kept", tail)
	}
	if got := reply[0] >> 4; got != 14 {
		t.Fatalf("answered packet type %d, want a DISCONNECT", got)
	}
	if len(tail) == 0 || tail[0] != 0x9A {
		t.Errorf("disconnected with % 02x, want 0x9A Retain not supported", tail)
	}

	// And it reached nobody, so it was refused rather than merely unstored.
	if got, ok := watcher.Await(t, 500*time.Millisecond); ok {
		t.Errorf("the refused publish was delivered to %q", got.Topic)
	}

	// **A channel that can keep one is the other half of the rule, and the
	// half the documentation recommends.** RFC 0003 tells an operator to
	// point a `homeassistant/` or `zigbee2mqtt/` tree at a `latest`
	// channel, and those tools set the flag on the publishes in question -
	// so such a channel must accept it. The flag is redundant there rather
	// than impossible: the record is stored, which is more than retain
	// promises.
	//
	// A queue is not in this list, and its own row is in
	// TestTheRetainFlagIsHonouredOrDroppedAndRefusedOnlyWithNoStore: it keeps
	// work rather than state, so the flag is dropped and the job taken as
	// ordinary work.
	live := connect2(t, h, "channelled")
	for _, topic := range []string{"state/dev1", "events/x"} {
		ack, err := live.C.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Retain: true, Payload: []byte("22"),
		})
		if ack == nil {
			t.Fatalf("%s with RETAIN got no PUBACK: %v", topic, err)
		}
		if ack.ReasonCode != 0x00 {
			t.Errorf("%s with RETAIN answered 0x%02X, want 0x00 - a channel is the store the flag asks for",
				topic, ack.ReasonCode)
		}
	}

	// And the latest value really is there, so accepting it was not a
	// silent drop of the client's intent.
	state := connect2(t, h, "state-reader")
	state.Sub(t, "state/#", 1)
	got, ok := state.Await(t, 2*time.Second)
	if !ok {
		t.Fatal("a retained publish to a latest channel stored nothing")
	}
	if !got.Retain {
		t.Error("the latest value arrived without the retain flag")
	}

	// A later subscriber sees nothing either: there is no retained store, so
	// the refused `loose/kept` above was kept nowhere.
	//
	// **The filter is the broadcast one rather than `#`**, and it has to be:
	// a filter now reaches every channel it matches, so `#` here would be
	// served the append record this test has just deliberately stored and
	// report it as something retained. That is the assertion reading a
	// healthy channel as the failure it is watching for.
	late := connect2(t, h, "late")
	late.Sub(t, "loose/#", 1)
	if got, ok := late.Await(t, time.Second); ok {
		t.Errorf("something was retained: %q %q", got.Topic, got.Payload)
	}
}

// RFC 0002 "Publishing": a dead-letter channel takes records only from the
// queue that derives it.
//
// RFC 0002 already wrote this rule against a bridge rule naming a `__dlq`,
// with its reason - a record placed there directly has no queue record
// behind it, so the link between a failure and the work that failed names
// nothing. Enforcing it against a configuration file and not against a
// client is the failure invariant 10 describes.
//
// Reading one is untouched, and the second half of this test is what says
// so: RFC 0002's "an ordinary append channel in every other respect" lists
// subscribing, replaying and holding a position, and every one is a read.
func TestPublishingIntoADeadLetterChannelIsRefused(t *testing.T) {
	h := start(t)
	c := connectAsking(t, h, "producer")

	ack, err := c.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/__dlq/injected", QoS: 1, Payload: []byte("i-was-never-a-job"),
	})
	if ack == nil {
		t.Fatalf("no PUBACK: %v", err)
	}
	if ack.ReasonCode != 0x87 {
		t.Errorf("answered 0x%02X, want 0x87 Not authorized", ack.ReasonCode)
	}
	if ack.Properties == nil || ack.Properties.ReasonString == "" {
		t.Error("refused with no Reason String")
	}

	// The queue itself is unaffected: this is about one derived channel,
	// not about writing to queues.
	if ack, _ := c.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/build", QoS: 1, Payload: []byte("a real job"),
	}); ack == nil || ack.ReasonCode != 0x00 {
		t.Error("publishing to the queue itself was refused")
	}

	// At QoS 0 there is no reply, so the record must simply not be there -
	// refused and published at the same time is the worst of both.
	if _, err := c.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/__dlq/injected2", QoS: 0, Payload: []byte("nor-was-i"),
	}); err != nil {
		t.Fatalf("qos 0 publish: %v", err)
	}

	// Reading the dead-letter channel is untouched.
	r := connect(t, h, "dlq-reader", true, false)
	if sa := r.Sub(t, "jobs/__dlq/#", 1); sa.Reasons[0] > 2 {
		t.Fatalf("subscribing to a dead-letter channel was refused: 0x%02X", sa.Reasons[0])
	}
	if got, ok := r.Await(t, 700*time.Millisecond); ok {
		t.Errorf("a refused publish reached the dead-letter channel: %q %q", got.Topic, got.Payload)
	}

	// And so is seeking one, which RFC 0003 requires.
	seeker := connectDurable(t, h, "dlq-seeker")
	if got := seeker.Seek(t, "jobs__dlq", "0").Payload; got == "" {
		t.Error("a seek on a dead-letter channel got no reply")
	}
}

// RFC 0002 "Publishing": a QoS 0 publish that cannot be accepted is
// dropped, because QoS 0 has no reply - which leaves the operator's log as
// the only place a refusal can be seen at all.
//
// refuseStore always logged; checkBounds did not, so a producer sending
// oversized topics or too many headers at QoS 0 was discarded in silence on
// both sides. The test drives the broker with a logger it can read back,
// which is the only way to assert on something whose whole point is that it
// reaches nobody else.
func TestABoundsRefusalIsLogged(t *testing.T) {
	var mu sync.Mutex
	var logged []string
	h := startLogging(t, func(line string) {
		mu.Lock()
		logged = append(logged, line)
		mu.Unlock()
	})

	c := connect(t, h, "producer", true, false)
	long := "events/" + strings.Repeat("x", limits.MaxTopicLength)

	// QoS 0: no reply by construction, so the log is the whole of it.
	if _, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: long, QoS: 0, Payload: []byte("x"),
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	// Read until it shows: a refusal that is never logged is the failure,
	// and one logged a moment later is not.
	for deadline := time.Now().Add(5 * time.Second); ; time.Sleep(10 * time.Millisecond) {
		mu.Lock()
		for _, l := range logged {
			if strings.Contains(l, "outside the configured bounds") && strings.Contains(l, "qos=0") {
				mu.Unlock()
				return
			}
		}
		n := len(logged)
		mu.Unlock()
		if time.Now().After(deadline) {
			t.Fatalf("a QoS 0 publish refused for its topic length was logged nowhere; %d lines seen", n)
		}
	}
}

// RFC 0002's publish table: `0x00 Success`. A successful QoS 1 PUBACK must
// carry a PUBACK reason code, and 0x01 is Granted QoS 1, a SUBACK one.
//
// Raw bytes, because the whole defect is a byte a client library reads as
// success either way: anything below 0x80 is success to Paho, so it cannot
// tell 0x00 from 0x01.
//
// It only appears when the publish carries a User Property, which RFC 0003
// invites on every publish - `saguin-id` is one, and User Properties
// becoming record headers is the whole header feature. With no properties
// the encoder omits the reason byte and its absence reads as 0x00.
func TestASuccessfulPubackCarriesAPubackReasonCode(t *testing.T) {
	h := start(t)
	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	hello := []byte{
		0x10, 0x11,
		0x00, 0x04, 'M', 'Q', 'T', 'T',
		0x05, 0x02, 0x00, 0x3c, 0x00,
		0x00, 0x04, 'p', 'u', 'b', 'a',
	}
	if _, err := conn.Write(hello); err != nil {
		t.Fatalf("write connect: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	fh := make([]byte, 2)
	if _, err := io.ReadFull(conn, fh); err != nil {
		t.Fatalf("no CONNACK: %v", err)
	}
	if _, err := io.ReadFull(conn, make([]byte, int(fh[1]))); err != nil {
		t.Fatalf("short CONNACK: %v", err)
	}

	// PUBLISH QoS 1 to a broadcast topic carrying one User Property, which
	// is what forces the reason byte onto the wire.
	topic := []byte("loose/acked")
	props := []byte{0x26, 0x00, 0x04, 'm', 'i', 'n', 'e', 0x00, 0x02, 'o', 'k'}
	var body []byte
	body = append(body, byte(len(topic)>>8), byte(len(topic)))
	body = append(body, topic...)
	body = append(body, 0x00, 0x07) // packet identifier
	body = append(body, byte(len(props)))
	body = append(body, props...)
	body = append(body, 'x')
	if _, err := conn.Write(append([]byte{0x32, byte(len(body))}, body...)); err != nil {
		t.Fatalf("write publish: %v", err)
	}

	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	reply := make([]byte, 2)
	if _, err := io.ReadFull(conn, reply); err != nil {
		t.Fatalf("no PUBACK: %v", err)
	}
	tail := make([]byte, int(reply[1]))
	if _, err := io.ReadFull(conn, tail); err != nil {
		t.Fatalf("short PUBACK: %v", err)
	}
	if got := reply[0] >> 4; got != 4 {
		t.Fatalf("answered packet type %d, want a PUBACK", got)
	}
	// **Either shape is right, and the assertion is about the byte when
	// there is one.** MQTT 5 section 3.4.2.1: with a Remaining Length of 2
	// there is no Reason Code and 0x00 Success is used. saguin sends no
	// User Property back on an acknowledgement any more (server.go), so a
	// successful PUBACK is now the short form - and the defect this guards
	// is unchanged, because a wrong code is a non-zero byte and a non-zero
	// byte is always encoded.
	//
	// It used to force the long form by publishing with a User Property and
	// relying on the echo. That was the test leaning on behaviour it was
	// not about, and it broke the day the echo went.
	switch {
	case len(tail) == 2:
		// The short form, which is Success by definition.
	case len(tail) >= 3 && tail[2] != 0x00:
		t.Errorf("PUBACK reason 0x%02X, want 0x00 - 0x01 is Granted QoS 1, a SUBACK code", tail[2])
	}
}

// A refusal must not copy an unbounded client string into the log.
//
// The two lines that can are the two that see a topic no bound has been
// applied to: checkBounds logs one because it broke `max_topic_length`, and
// a Will topic arrives in CONNECT and never reaches checkBounds. MQTT
// length-prefixes a topic with two bytes, so the ceiling is 65,535
// characters, and at QoS 0 a client can send them as fast as it can write.
//
// The test asserts the size of what was logged rather than its text,
// because the defect is volume: a diagnostic that names the topic is wanted,
// a verbatim 65kB copy of it is not.
func TestARefusalDoesNotLogAnUnboundedClientString(t *testing.T) {
	var mu sync.Mutex
	var total int
	h := startLogging(t, func(line string) {
		mu.Lock()
		total += len(line)
		mu.Unlock()
	})

	big := strings.Repeat("x", 65_000)
	c := connect(t, h, "producer", true, false)

	// Every refusal path that logs something a client chose. They are
	// together because the defect is a class rather than a line: each one
	// logs a string precisely where no bound has been applied to it.
	for range 5 {
		// a publish topic, refused for its length
		if _, err := c.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/" + big, QoS: 0, Payload: []byte("x"),
		}); err != nil {
			t.Fatalf("publish: %v", err)
		}
		// a subscribe filter, which no bound is applied to at all
		c.Sub(t, "jobs/"+big, 1)
		// a seek payload, bounded only by max_message_size
		c.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/consumer/events/seek", QoS: 0, Payload: []byte(big),
		})
		// a queue response payload, the same
		c.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/queue/jobs/response", QoS: 0, Payload: []byte(big),
		})
	}
	// The QoS 0 refusals are logged on c's read loop as each is read, so a
	// round trip after them says every one has been.
	settle(t, c)

	mu.Lock()
	got := total
	mu.Unlock()

	// Four refusals a round, five rounds, each allowed the configured bound
	// plus a generous allowance for the rest of its line. Copied verbatim
	// this measures well over a million bytes.
	if max := 20 * (limits.MaxTopicLength + 512); got > max {
		t.Errorf("twenty refusals logged %d bytes, want under %d - "+
			"a client-chosen string is being copied verbatim", got, max)
	}
	if got == 0 {
		t.Error("nothing was logged at all, so the refusal is invisible again")
	}
}

// A client id longer than `max_client_id_length` is refused at CONNECT with
// `0x85`, and that refusal is what bounds everything downstream of it.
//
// A client id is not merely logged. A durable consumer's stored position is
// keyed by it, so an unbounded one is written into SQLite and into the
// snapshot files and stays there for the session expiry interval, across
// restarts - durable state whose size an anonymous client chooses, which is
// invariant 13. Measured before this bound existed: twenty connections with
// 60,000-byte ids, eight seconds, 1,260,124 bytes of reader names in a 2.6MB
// database, every CONNECT answered `0x00`.
//
// So the refusal is the assertion. There is no reachable code path that
// stores or logs an oversized id once the connection carrying it is gone,
// which is the whole reason for bounding it at the door rather than
// truncating it at each of the twenty-eight places it is written.
//
// The row at exactly the bound is what stops a later simplification passing
// this test by refusing every connection.
func TestAnOversizedClientIDIsRefusedAtConnect(t *testing.T) {
	var mu sync.Mutex
	var total int
	h := startLogging(t, func(line string) {
		mu.Lock()
		total += len(line)
		mu.Unlock()
	})

	// Paho does not check the length, which is why the suite is driven by
	// it: mosquitto_pub refuses an oversized id before the socket, so
	// through that tool a broker that accepts one looks like a broker that
	// refuses it.
	reason := func(id string) byte {
		conn, err := net.Dial("tcp", h.Addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		defer conn.Close()
		c := paho.NewClient(paho.ClientConfig{Conn: conn})
		ca, err := c.Connect(context.Background(), &paho.Connect{
			ClientID: id, CleanStart: true, KeepAlive: 0,
		})
		if ca == nil {
			// No CONNACK at all is a different failure from a refusal, and
			// the two must not be reported as one.
			t.Fatalf("a %d-byte client id produced no CONNACK: %v", len(id), err)
		}
		return ca.ReasonCode
	}

	for _, tc := range []struct {
		bytes int
		want  byte
		why   string
	}{
		{limits.MaxClientIDLength, 0x00, "at the bound, which must still connect"},
		{limits.MaxClientIDLength + 1, 0x85, "one byte over"},
		{60_000, 0x85, "what the wire allows"},
	} {
		if got := reason(strings.Repeat("z", tc.bytes)); got != tc.want {
			t.Errorf("a %d-byte client id (%s) answered %#02x, want %#02x",
				tc.bytes, tc.why, got, tc.want)
		}
	}

	time.Sleep(200 * time.Millisecond)
	mu.Lock()
	got := total
	mu.Unlock()

	// Three connects, one accepted and two refused. Copied verbatim the two
	// refusals alone measure over 120,000 bytes.
	if max := 3 * (limits.MaxTopicLength + 512); got > max {
		t.Errorf("three connects logged %d bytes, want under %d - "+
			"the client id is being copied verbatim", got, max)
	}
	if got == 0 {
		t.Error("nothing was logged at all, so the refusal is invisible to an operator")
	}
}

// RFC 0002 "Bridges": an inbound rule pointing at a `latest` channel
// replaces rather than accumulates, which is the mitigation for the one
// duplicate an operator can actually choose to avoid.
//
// A bridge that loses its upstream session resubscribes, and the upstream
// answers a subscription with its whole retained set - so an `append`
// channel gains the lot again, deterministically, on every reconnect that
// finds Session Present = 0. On a `latest` channel the same records replace
// the values already there, so the channel holds what the upstream holds
// however many times the link is rebuilt.
func TestABridgeIntoALatestChannelReplaces(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)

	yaml := fmt.Sprintf(`broker:
  id: t
`+memStorage+`channels:
  state:
    type: latest
bridges:
  head-office:
    peer: tcp://%s
    client_id: vessel-07
    topics:
      - filter: fleet/+/telemetry/#
        topic: state/telemetry/$1/$#
        direction: in
`, upstreamAddr)
	path := filepath.Join(t.TempDir(), "saguin.yaml")
	if err := os.WriteFile(path, []byte(yaml), 0o600); err != nil {
		t.Fatalf("write: %v", err)
	}
	f, _, err := config.Load(path)
	if err != nil {
		t.Fatalf("the test's own configuration does not load: %v", err)
	}
	cfg := f.BridgeSet()[0]

	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		<-done
	})
	waitForBridge(t, upstream, cfg.ClientID)

	// A watcher on the channel before anything arrives: its having the
	// newer value is what says the bridge has stored both, where a pause
	// after each upstream publish guessed at it.
	watch := connect(t, h, "bridge-watch", true, false)
	watch.Sub(t, "state/telemetry/#", 1)

	// The same upstream topic twice, which is what a resubscribe against a
	// retained value looks like from saguin's side.
	for _, v := range []string{"31.4", "31.9"} {
		if err := upstream.Publish("fleet/vessel-07/telemetry/psi", []byte(v), false, 1); err != nil {
			t.Fatalf("upstream publish: %v", err)
		}
	}
	for {
		r, ok := watch.Await(t, 5*time.Second)
		if !ok {
			t.Fatal("the bridged values never reached the channel")
		}
		if r.Payload == "31.9" {
			break
		}
	}

	// A fresh subscriber is sent current state, so it sees one value and it
	// is the newer one. An append channel would replay both.
	sub := connect(t, h, "state-reader", true, false)
	sub.Sub(t, "state/#", 1)
	got, ok := sub.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("nothing was bridged into the latest channel")
	}
	if got.Payload != "31.9" {
		t.Errorf("current value is %q, want the newer 31.9", got.Payload)
	}
	// A value published on the same topic now is the end marker: a latest
	// channel is ordered per topic, so an accumulated older value would
	// reach the subscriber before it.
	connect(t, h, "marker", true, false).Pub(t, "state/telemetry/vessel-07/psi", "marker")
	if r, ok := sub.Await(t, 5*time.Second); !ok || r.Payload != "marker" {
		t.Errorf("after the current value the subscriber was sent %q (%v) before the end "+
			"marker - a latest channel must replace, not accumulate", r.Payload, ok)
	}
}

// RFC 0003 "Retained messages": with a store configured, a retained
// publish to a broadcast topic is kept and handed to whoever subscribes
// next - and is still delivered live to whoever is subscribed at the time,
// because it is still a broadcast.
//
// Paho, because what matters here is what a stock client sees: the flag on
// the way out, and one copy rather than two.
func TestARetainedBroadcastIsKeptAndDeliveredToALaterSubscriber(t *testing.T) {
	h := startRetaining(t, 0)

	// Somebody subscribed at the time of the publish gets it live.
	live := dialProps(t, h, "live")
	live.Sub(t, "house/#", 1)
	subscribed(t, live.C)

	pub := dialProps(t, h, "publisher")
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "house/kitchen/lamp", QoS: 1, Retain: true, Payload: []byte("on"),
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}

	got := awaitProp(t, live)
	if got == nil {
		t.Fatal("a subscriber connected at the time received nothing: a retained publish is still a broadcast")
	}
	if got.Retain {
		t.Errorf("the live delivery carried the retain flag; it is an update, not state")
	}

	// And somebody arriving afterwards is served from the store.
	late := dialProps(t, h, "late")
	late.Sub(t, "house/#", 1)

	kept := awaitProp(t, late)
	if kept == nil {
		t.Fatal("a later subscriber received nothing, so the retained publish was not kept")
	}
	if !kept.Retain {
		t.Errorf("the stored value arrived without the retain flag, so a client cannot tell state from an update")
	}
	if string(kept.Payload) != "on" {
		t.Errorf("payload %q, want \"on\"", kept.Payload)
	}
	if kept.Topic != "house/kitchen/lamp" {
		t.Errorf("topic %q, want house/kitchen/lamp", kept.Topic)
	}
	// A broadcast message has no record identity and no position. Stamping
	// one on the way out would make broadcast look like a channel to
	// whichever client happened to subscribe late.
	for _, u := range kept.Properties.User {
		if strings.HasPrefix(u.Key, "saguin-") {
			t.Errorf("a retained broadcast carried %s=%q; nothing saguin adds rides on these",
				u.Key, u.Value)
		}
	}

	// Exactly one. Two would mean the substrate's own retained store is
	// holding a copy beside saguin's, which is the second unbounded store
	// invariant 13 refuses.
	if extra := awaitProp(t, late); extra != nil {
		t.Errorf("a second copy arrived (%q), so something else is keeping one too", extra.Topic)
	}
}

// MQTT-3.3.2-5: a retained message whose Message Expiry Interval has passed
// is discarded, and a later subscriber is not sent it - even before the
// sweep that reclaims its bytes has run, which is why the operator period
// here is an hour: its sweep interval is minutes, so nothing but the
// delivery path can be answering. And MQTT-3.3.2-6: a value that is sent
// carries the publisher's countdown, decremented by its wait - never the
// operator's period, and no property at all where the publisher set none.
func TestAnExpiredRetainedBroadcastIsGoneAndALiveOneCountsDown(t *testing.T) {
	h := startRetaining(t, 3600)

	pub := dialProps(t, h, "publisher")
	second, fiveMinutes := uint32(1), uint32(300)
	for _, p := range []*paho.Publish{
		{Topic: "house/hall/lamp", QoS: 1, Retain: true, Payload: []byte("on"),
			Properties: &paho.PublishProperties{MessageExpiry: &second}},
		{Topic: "house/porch/lamp", QoS: 1, Retain: true, Payload: []byte("on"),
			Properties: &paho.PublishProperties{MessageExpiry: &fiveMinutes}},
		{Topic: "house/hall/switch", QoS: 1, Retain: true, Payload: []byte("up")},
	} {
		if _, err := pub.C.Publish(context.Background(), p); err != nil {
			t.Fatalf("publish %s: %v", p.Topic, err)
		}
	}

	// Past the first value's expiry, and far enough past it that a second
	// of scheduling cannot bring it back. The other two are still live.
	time.Sleep(2100 * time.Millisecond)

	late := dialProps(t, h, "late")
	late.Sub(t, "house/#", 1)

	got := map[string]*paho.Publish{}
	for range 3 {
		p := awaitProp(t, late)
		if p == nil {
			break
		}
		got[p.Topic] = p
	}

	if p, ok := got["house/hall/lamp"]; ok {
		t.Errorf("an expired retained value was served (%q); MQTT-3.3.2-5 discards it", p.Payload)
	}

	porch, ok := got["house/porch/lamp"]
	if !ok {
		t.Fatal("a retained value inside its expiry was not served")
	}
	if porch.Properties == nil || porch.Properties.MessageExpiry == nil {
		t.Fatal("a retained value with a Message Expiry arrived without one; " +
			"MQTT-3.3.2-6 sends the remaining countdown")
	}
	if left := *porch.Properties.MessageExpiry; left < 250 || left > 298 {
		t.Errorf("the countdown is %d after a 2.1s wait on a 300s expiry, "+
			"want the publisher's remainder (250..298), never the operator's period", left)
	}

	sw, ok := got["house/hall/switch"]
	if !ok {
		t.Fatal("a retained value with no expiry was not served")
	}
	if sw.Properties != nil && sw.Properties.MessageExpiry != nil {
		t.Errorf("a value whose publisher set no expiry arrived with a countdown of %d; "+
			"the operator's period is not the publisher's to hear about",
			*sw.Properties.MessageExpiry)
	}
}

// MQTT-3.3.1-13: a subscriber that asked for Retain As Published sees the
// retain flag as the publisher set it. MQTT-3.3.1-12: everybody else sees
// it down. Both halves here, because the pair is the rule - a broker that
// always sets the flag is as wrong as one that never does.
//
// saguin used to always clear it, to keep the substrate's own retained
// store empty; it empties that store instead now, which is what lets the
// flag through.
func TestARetainedBroadcastKeepsTheFlagForRetainAsPublished(t *testing.T) {
	h := startRetaining(t, 0)

	rap := dialProps(t, h, "rap")
	if sa, err := rap.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{
			{Topic: "house/#", QoS: 1, RetainAsPublished: true},
		},
	}); sa == nil {
		t.Fatalf("subscribe: %v", err)
	}
	// Each subscription's own work done before the publish, as in
	// TestRetainAsPublishedIsHonouredOnAChannel.
	subscribed(t, rap.C)
	plain := dialProps(t, h, "plain")
	plain.Sub(t, "house/#", 1)
	subscribed(t, plain.C)

	pub := dialProps(t, h, "publisher")
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "house/study/lamp", QoS: 1, Retain: true, Payload: []byte("on"),
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}

	got := awaitProp(t, rap)
	if got == nil {
		t.Fatal("the Retain As Published subscriber received nothing")
	}
	if !got.Retain {
		t.Error("a Retain As Published subscriber was sent the flag at 0; " +
			"MQTT-3.3.1-13 says it sees the flag the publisher set")
	}

	got = awaitProp(t, plain)
	if got == nil {
		t.Fatal("the ordinary subscriber received nothing")
	}
	if got.Retain {
		t.Error("an ordinary subscriber was sent the flag at 1; " +
			"MQTT-3.3.1-12 says a live delivery has it down")
	}

	// And the flag surviving must not leave a second store holding the
	// value, which is the whole of what clearing it used to buy. That store
	// is broker-wide with no bound and no retention, so anything left in it
	// is invariant 13.
	if left := h.B.RetainedElsewhere(); len(left) != 0 {
		t.Errorf("the substrate's own retained store holds %d message(s) (%q); "+
			"saguin's is meant to be the only one there is", len(left), left)
	}
	// It is empty because it was emptied, not because nothing arrived. A
	// zero here would mean the flag never reached the substrate at all, so
	// the assertion above would be passing for a reason that has nothing to
	// do with what this test is about.
	if n := h.B.RetakenFromSubstrate(); n == 0 {
		t.Error("nothing was ever taken back out of the substrate's retained store, " +
			"so it is empty by accident rather than by OnRetainMessage")
	}
}

// The retain flag now survives OnPublish, so every branch of it is asked
// the same question rather than the broadcast one being asked alone. A
// channel's record reaching the substrate's retained store would be
// reachable through a wildcard at channel depth, which is invariant 11 -
// worse than the unbounded store, and the reason this is a test and not a
// reading of the code.
func TestARetainedPublishToAChannelReachesNoOtherStore(t *testing.T) {
	h := startRetaining(t, 0)
	pub := dialProps(t, h, "publisher")

	// A queue is not here: a retained publish to one is taken as ordinary
	// work with the flag dropped, which is
	// TestTheRetainFlagIsHonouredOrDroppedAndRefusedOnlyWithNoStore's row
	// rather than this test's subject.
	for _, topic := range []string{
		"events/sensor/1", // append
		"state/device/1",  // latest
	} {
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Retain: true, Payload: []byte("x"),
		}); err != nil {
			t.Fatalf("publish %s: %v", topic, err)
		}
		// Never stored, rather than stored and taken back: while it sits
		// there a wildcard at channel depth can reach it, so the end state
		// being empty is not the assertion worth making here.
		if n := h.B.RetakenFromSubstrate(); n != 0 {
			t.Fatalf("a retained publish to %s reached the substrate's retained store "+
				"(%d taken back), where a wildcard at channel depth can reach it", topic, n)
		}
		if left := h.B.RetainedElsewhere(); len(left) != 0 {
			t.Fatalf("a retained publish to %s left %d message(s) in the substrate's "+
				"retained store: %q", topic, len(left), left)
		}
	}
}

// RFC 0003 "Retained messages": on a `latest` channel the retain flag is
// redundant, because that channel holds the current value of every topic
// beneath it whether or not anyone set the flag. So the newest publish
// wins, in both directions - a plain publish supersedes a retained one and
// a retained one supersedes a plain one - and the flag decides nothing
// about what is kept.
//
// **The direction worth having a test for is a plain publish over a
// retained one.** A broker that treated the flag as "this is the one to
// keep" would pin the retained value and answer every later subscriber
// with state three updates old, while every client connected at the time
// saw the truth. Nothing in the log would say so.
func TestALatestChannelKeepsTheNewestValueWhateverTheRetainFlagSaid(t *testing.T) {
	h := start(t)
	pub := dialProps(t, h, "publisher")

	for _, step := range []struct {
		payload string
		retain  bool
	}{
		{"off", false},
		{"on", true},   // a retained publish over a plain one
		{"dim", false}, // and a plain one over the retained value
	} {
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "state/lamp", QoS: 1, Retain: step.retain, Payload: []byte(step.payload),
		}); err != nil {
			t.Fatalf("publish %q: %v", step.payload, err)
		}
	}

	late := dialProps(t, h, "late")
	late.Sub(t, "state/#", 1)

	got := awaitProp(t, late)
	if got == nil {
		t.Fatal("a subscriber arriving afterwards was sent no current value")
	}
	if string(got.Payload) != "dim" {
		t.Errorf("current state is %q, want \"dim\": the newest publish is the value, "+
			"and the retain flag does not pin an older one", got.Payload)
	}
	// A current-state pass carries the flag whatever the publisher set,
	// because it is state rather than an update - that is how a client
	// tells "what I missed" from "this just happened".
	if !got.Retain {
		t.Error("the current value arrived without the retain flag")
	}
	if extra := awaitProp(t, late); extra != nil {
		t.Errorf("a second value arrived (%q); a latest channel holds one per topic",
			extra.Payload)
	}
}

// The same rule on the other path that retains: a Will. It reaches the
// substrate's store through a different call, so it is asked separately
// rather than assumed to follow.
func TestARetainedWillLeavesNothingInTheSubstratesStore(t *testing.T) {
	h := startRetaining(t, 0)

	conn, code := connectWithWill(t, h, "device", "house/device/status", true, 0, 0)
	if code != 0x00 {
		t.Fatalf("a retained Will on a broadcast topic was refused with 0x%02X", code)
	}
	kill(t, conn)
	sessionGone(t, h, "device") // its Will published as the connection went

	if left := h.B.RetainedElsewhere(); len(left) != 0 {
		t.Errorf("the substrate's own retained store holds %d message(s) after a Will: %q",
			len(left), left)
	}

	// It is saguin's store that has it, and exactly one copy of it: two
	// would mean both stores answered.
	dashboard := dialProps(t, h, "dashboard")
	dashboard.Sub(t, "house/#", 1)

	got := awaitProp(t, dashboard)
	if got == nil {
		t.Fatal("a client arriving after the device died was told nothing")
	}
	if got.Topic != "house/device/status" || string(got.Payload) != "i-died" {
		t.Fatalf("received %q %q, want house/device/status i-died", got.Topic, got.Payload)
	}
	// A retained value is sent on SUBSCRIBE, before anything published after
	// it, so a marker published now arrives next unless a second copy does -
	// at QoS 0, as the Will was armed, since QoS 0 and QoS 1 deliveries reach
	// a subscriber by different roads that nothing orders.
	connect(t, h, "marker", true, false).PubPlainAt(t, "house/marker", "marker", 0)
	if next := awaitProp(t, dashboard); next == nil || string(next.Payload) != "marker" {
		t.Errorf("the next thing after the retained Will was %v, want the marker: a second "+
			"copy means something else is keeping one too", next)
	}
}

// The CONNACK says Maximum QoS 1, so nothing saguin sends may carry QoS 2
// - MQTT-3.2.2-9 - and a delivery's QoS is the lower of the published and
// the granted, which is MQTT-3.8.4-8.
//
// A client asking for QoS 2 is granted 1 in its SUBACK, and was then sent
// every delivery at 2 anyway: the SUBACK and the packets disagreed. All
// three paths saguin writes itself did it, so all three are asked here.
//
// Invisible through `mosquitto_sub`, which completes the QoS 2 handshake
// the server started and reports nothing amiss; the QoS is on the packet
// rather than in the output.
func TestNothingIsDeliveredAboveTheAdvertisedMaximumQos(t *testing.T) {
	for _, tc := range []struct{ name, publish, filter string }{
		{"an append channel", "events/one", "events/#"},
		{"a latest channel", "state/one", "state/#"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			// **A client denied `qos2`**, which is what makes this case exist:
			// its CONNACK says Maximum QoS 1, so that is the ceiling it is held to.
			h := start(t)
			denyFeatures(t, h, "    - broker: features\n      deny: [qos2]\n")
			pub := dialProps(t, h, "publisher")
			if _, err := pub.C.Publish(context.Background(), &paho.Publish{
				Topic: tc.publish, QoS: 1, Payload: []byte("v"),
			}); err != nil {
				t.Fatalf("publish: %v", err)
			}

			c := dialProps(t, h, "asks-for-two")
			sa, err := c.C.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{{Topic: tc.filter, QoS: 2}},
			})
			if sa == nil {
				t.Fatalf("subscribe: %v", err)
			}
			if sa.Reasons[0] != 1 {
				t.Fatalf("granted QoS %d, want 1 - the client was told Maximum QoS 1",
					sa.Reasons[0])
			}

			got := awaitProp(t, c)
			if got == nil {
				t.Fatal("nothing was delivered")
			}
			if got.QoS > sa.Reasons[0] {
				t.Errorf("delivered at QoS %d, above the granted %d: the SUBACK and the "+
					"packet disagree, and MQTT-3.2.2-9 forbids exceeding the advertised maximum",
					got.QoS, sa.Reasons[0])
			}

			// And a live delivery, which takes a different road from the
			// replay above.
			if _, err := pub.C.Publish(context.Background(), &paho.Publish{
				Topic: tc.publish, QoS: 1, Payload: []byte("v2"),
			}); err != nil {
				t.Fatalf("publish again: %v", err)
			}
			if live := awaitProp(t, c); live != nil && live.QoS > sa.Reasons[0] {
				t.Errorf("a live delivery arrived at QoS %d, above the granted %d",
					live.QoS, sa.Reasons[0])
			}
		})
	}

	t.Run("the retained store", func(t *testing.T) {
		h := startRetaining(t, 0)
		pub := dialProps(t, h, "publisher")
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "house/lamp", QoS: 1, Retain: true, Payload: []byte("on"),
		}); err != nil {
			t.Fatalf("publish: %v", err)
		}

		c := dialProps(t, h, "asks-for-two")
		sa, err := c.C.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{{Topic: "house/#", QoS: 2}},
		})
		if sa == nil {
			t.Fatalf("subscribe: %v", err)
		}
		got := awaitProp(t, c)
		if got == nil {
			t.Fatal("the retained value was not delivered")
		}
		if got.QoS > sa.Reasons[0] {
			t.Errorf("a retained value arrived at QoS %d, above the granted %d",
				got.QoS, sa.Reasons[0])
		}
	})
}

// The other half of the queue row, on the wire: the flag is dropped and the
// message is work. A worker receives it with RETAIN down, because what it
// was handed is a job rather than state - and nothing is left in the
// substrate's own retained store, which is where a surviving flag would put
// a copy on the way past, reachable through a wildcard at channel depth
// (invariant 11).
func TestARetainedPublishToAQueueReachesAWorkerAsOrdinaryWork(t *testing.T) {
	h := start(t)

	w := dialProps(t, h, "worker-1")
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	pub := dialProps(t, h, "publisher")
	pa, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/build/1", QoS: 1, Retain: true, Payload: []byte("work"),
	})
	if pa == nil {
		t.Fatalf("a retained publish to a queue was refused: %v", err)
	}
	if pa.ReasonCode != 0x00 {
		t.Fatalf("answered 0x%02X, want 0x00: the job is storable and the flag is not "+
			"the job", pa.ReasonCode)
	}

	got := awaitProp(t, w)
	if got == nil {
		t.Fatal("the worker was handed nothing, so a retained publish was acknowledged " +
			"and then not enqueued - work acknowledged and lost")
	}
	if string(got.Payload) != "work" {
		t.Errorf("the worker got %q, want \"work\"", got.Payload)
	}
	if got.Retain {
		t.Error("the job arrived with RETAIN set; a queue delivery is work rather than state")
	}
	if left := h.B.RetainedElsewhere(); len(left) != 0 {
		t.Errorf("the substrate's retained store holds %d message(s) (%q) after a retained "+
			"publish to a queue, where a wildcard at channel depth reaches it",
			len(left), left)
	}
}

// RFC 0003: the retain flag is honoured wherever there is a store to
// honour it with, dropped on a queue, and refused only where the publish
// would otherwise claim a store that does not exist. This is the whole rule
// in one table - every channel type, and broadcast both ways.
//
// **The queue row is a dropped flag rather than a refusal**, which is the
// one place these two answers meet. Nothing on a queue can keep a retained
// value and nothing on one could ever be served it, so the flag cannot be
// honoured either way - but the job can be, and a PUBACK on a queue says
// the work was stored rather than that any state was kept, so accepting it
// tells the producer nothing untrue. The refusal that remains is broadcast
// with no store, where the PUBACK really would be claiming a store the
// broker does not have.
func TestTheRetainFlagIsHonouredOrDroppedAndRefusedOnlyWithNoStore(t *testing.T) {
	for _, tc := range []struct {
		name, topic string
		retaining   bool // is a broker.retained store configured?
		wantRefused bool
	}{
		{"an append channel stores it", "events/state", false, false},
		{"a latest channel is that store", "state/thing", false, false},
		{"a queue takes the work and drops the flag", "jobs/work", false, false},
		{"broadcast with a store", "house/lamp", true, false},
		{"broadcast without one", "house/lamp", false, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var h *harness
			if tc.retaining {
				h = startRetaining(t, 0)
			} else {
				h = start(t)
			}

			c := dialProps(t, h, "publisher")
			pa, err := c.C.Publish(context.Background(), &paho.Publish{
				Topic: tc.topic, QoS: 1, Retain: true, Payload: []byte("v1"),
			})
			if !tc.wantRefused {
				if pa == nil {
					t.Fatalf("a retained publish was refused: %v", err)
				}
				if pa.ReasonCode != 0x00 {
					t.Fatalf("answered 0x%02X, want 0x00: this channel can honour the flag",
						pa.ReasonCode)
				}
				return
			}
			// Refused with a DISCONNECT, so there is no PUBACK to read: the
			// connection goes. MQTT makes it a protocol error rather than a
			// reason code, because 0x9A is not one a PUBACK may carry.
			if pa != nil && pa.ReasonCode == 0x00 {
				t.Fatalf("a retained publish to %s was accepted with 0x00; nothing there "+
					"can keep it, so the producer has been told something untrue", tc.topic)
			}
		})
	}
}

// More state than fits in the subscriber's in-flight window at once, from
// both stores that serve state: a `latest` channel and the retained store.
//
// What does not fit waits, and each acknowledgement frees a slot and pulls
// the next one - so the whole of current state arrives eventually or the
// consumer stalls holding part of it and is told nothing. There was no test
// for a window smaller than the state on either store, and the two share
// the code that pulls the next value.
// drained waits until nothing waits on c's list for the channel - an empty
// list, or no delivery record left to hold one - and nothing is in flight to
// it.
func drained(t *testing.T, h *brokertest.Harness, c *brokertest.Client, ch string) {
	t.Helper()
	acknowledged(t, c)
	if !waitUntil(5*time.Second, func() bool { return broker.LatestPending(h.B, c.ID, ch) <= 0 }) {
		t.Fatalf("%d values still wait for %s on %s", broker.LatestPending(h.B, c.ID, ch), c.ID, ch)
	}
	acknowledged(t, c)
}

func TestStateLargerThanTheWindowIsDrainedInFull(t *testing.T) {
	const values = 6

	t.Run("a latest channel", func(t *testing.T) {
		h := start(t)
		pub := connect(t, h, "publisher", true, false)
		for i := range values {
			pub.Pub(t, fmt.Sprintf("state/thing%d", i), "v")
		}

		c := connectRx(t, h, "slow", true, false, 1)
		c.Sub(t, "state/#", 1)
		awaitCount(t, c, values, 10*time.Second)
		// **Counted once the drain has nothing left, not once the count is
		// reached.** A value sent twice would still be waiting on the list
		// or in flight behind the window of one.
		drained(t, h, c, "state")
		if got := c.Count(); got != values {
			t.Errorf("a subscriber with a window of one received %d of %d values; "+
				"the drain stopped part-way and said nothing", got, values)
		}
	})

	t.Run("the retained store", func(t *testing.T) {
		h := startRetaining(t, 0)
		pub := dialProps(t, h, "publisher")
		for i := range values {
			if _, err := pub.C.Publish(context.Background(), &paho.Publish{
				Topic: fmt.Sprintf("house/thing%d", i), QoS: 1,
				Retain: true, Payload: []byte("v"),
			}); err != nil {
				t.Fatalf("publish: %v", err)
			}
		}

		c := connectRx(t, h, "slow", true, false, 1)
		c.Sub(t, "house/#", 1)
		awaitCount(t, c, values, 10*time.Second)
		drained(t, h, c, broker.RetainedStoreName)
		if got := c.Count(); got != values {
			t.Errorf("a subscriber with a window of one received %d of %d retained values", got, values)
		}
	})
}

// A resumed session is sent nothing from the retained store, which is what
// a standard broker does and what RFC 0003 promises: retained messages are
// delivered at SUBSCRIBE and nowhere else. A `latest` channel deliberately
// differs, and that difference is the reason to write this one down - the
// two use the same delivery machinery, so it would be easy for the store to
// acquire a channel's behaviour by accident.
func TestAResumedSessionIsSentNothingFromTheRetainedStore(t *testing.T) {
	h := startRetaining(t, 0)

	// Through the barrier: `watcher` subscribes immediately below and is
	// then counted, and a live copy caught from the pending fan-out makes
	// that count 2 (see fannedOut).
	fannedOut(t, h, "attic", "house/attic/lamp", "on", true)

	// A durable session subscribes and is served the stored value.
	c := dial(t, h, "watcher", false, false, 0, 3600, 0)
	c.Sub(t, "house/#", 1)
	// Waited for rather than slept through. The barrier has already ruled
	// out a second copy, so counting up to one and stopping there is safe:
	// the only delivery that can reach this client is the retained one.
	awaitCount(t, c, 1, 10*time.Second)
	if got := c.Count(); got != 1 {
		t.Fatalf("a new subscription was served %d value(s), want the one retained", got)
	}
	// Waited for, not slept through: reconnecting before the broker has
	// finished with this id takes the live session over, and what the new
	// connection then receives is the old one's.
	gone(t, c)

	// Back on the same session, without subscribing again.
	back := dial(t, h, "watcher", false, false, 0, 3600, 0)
	// **An absence read against an end marker, not a duration.** A value the
	// resume sent from the retained store is sent as the session is
	// established, before a message published on its restored subscription
	// afterwards.
	subscribed(t, back.C)
	connect(t, h, "marker", true, false).Pub(t, "house/marker", "marker")
	awaitCount(t, back, 1, 5*time.Second)
	if got := back.Payloads(); len(got) != 1 || got[0] != "marker" {
		t.Errorf("a resumed session was sent %v before the end marker; MQTT delivers "+
			"retained messages at SUBSCRIBE and nowhere else", got)
	}

	// And subscribing again does serve it, so the emptiness above is the
	// rule rather than the value having gone: after the marker, the one
	// retained value and nothing else.
	back.Sub(t, "house/#", 1)
	awaitCount(t, back, 2, 10*time.Second)
	if got := back.Payloads(); len(got) != 2 || got[1] != "on" {
		t.Errorf("subscribing again served %v after the end marker, want the one retained", got[1:])
	}
}

// MQTT's own convention: a zero-length payload deletes the entry, and the
// delete is still broadcast live, because that is how a subscriber that is
// connected learns the topic is gone.
func TestAZeroLengthRetainedBroadcastDeletesIt(t *testing.T) {
	h := startRetaining(t, 0)

	// Both through the barrier: each is delivered live to whoever is
	// subscribed, and `late` below must not be caught inside either
	// delivery (see fannedOut).
	fannedOut(t, h, "set", "house/hall/lamp", "on", true)
	fannedOut(t, h, "del", "house/hall/lamp", "", true)

	late := dialProps(t, h, "late")
	late.Sub(t, "house/#", 1)
	if got := awaitProp(t, late); got != nil {
		t.Fatalf("a deleted topic was still served: %q %q", got.Topic, got.Payload)
	}
}

// The three rules MQTT states about who is sent retained messages, which
// saguin follows exactly on a broadcast topic - the whole point being that
// an unmodified client works.
func TestRetainedBroadcastFollowsRetainHandling(t *testing.T) {
	h := startRetaining(t, 0)

	// Through the barrier, because every subtest below connects a *new*
	// client and three of them assert that it is sent nothing. Reaching one
	// of those inside the substrate's pending fan-out hands it this message
	// live, with the retain flag clear, and the subtest reports the rule
	// broken (see fannedOut).
	fannedOut(t, h, "porch", "house/porch/lamp", "on", true)

	t.Run("2 sends none", func(t *testing.T) {
		c := dialProps(t, h, "rh2")
		sa, err := c.C.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{
				{Topic: "house/#", QoS: 1, RetainHandling: 2},
			},
		})
		if sa == nil {
			t.Fatalf("subscribe: %v", err)
		}
		if got := awaitProp(t, c); got != nil {
			t.Fatalf("a client asking for no retained messages was sent %q", got.Topic)
		}
	})

	t.Run("1 sends them on a new subscription and not on a repeat", func(t *testing.T) {
		c := dialProps(t, h, "rh1")
		sub := &paho.Subscribe{Subscriptions: []paho.SubscribeOptions{
			{Topic: "house/#", QoS: 1, RetainHandling: 1},
		}}
		if sa, err := c.C.Subscribe(context.Background(), sub); sa == nil {
			t.Fatalf("subscribe: %v", err)
		}
		if got := awaitProp(t, c); got == nil {
			t.Fatal("a new subscription asking for retained messages was sent none")
		}
		// The same filter again: the subscription now exists, so MQTT says
		// send nothing.
		if sa, err := c.C.Subscribe(context.Background(), sub); sa == nil {
			t.Fatalf("re-subscribe: %v", err)
		}
		if got := awaitProp(t, c); got != nil {
			t.Fatalf("a repeated subscription was sent %q again", got.Topic)
		}
	})

	t.Run("a shared subscription is sent none", func(t *testing.T) {
		c := dialProps(t, h, "shared")
		sa, err := c.C.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{
				{Topic: "$share/g/house/#", QoS: 1},
			},
		})
		if sa == nil {
			t.Fatalf("subscribe: %v", err)
		}
		if sa.Reasons[0] > 2 {
			t.Skipf("the broker refused a shared subscription on broadcast with 0x%02X", sa.Reasons[0])
		}
		if got := awaitProp(t, c); got != nil {
			t.Fatalf("a shared subscription was sent the retained message %q", got.Topic)
		}
	})
}

// RFC 0003 "`latest`": a channel's state is delivered with the retain flag
// set, so Retain Handling governs it too - it is MQTT's own way for a
// client to say "live updates only", and today there is no other way to
// ask a latest channel for that.
func TestALatestChannelFollowsRetainHandling(t *testing.T) {
	h := start(t)

	// This was a 100ms sleep, and it was here for the reason fannedOut now
	// states outright - the sleep was somebody working around the pending
	// fan-out without a name for it. A duration is the wrong instrument: it
	// is chosen on an idle machine and needed on a busy one.
	fannedOut(t, h, "room", "state/room", "warm", false)

	// A publisher of its own for the live update at the end, which is a
	// presence assertion and so needs no barrier: it waits for the delivery
	// rather than for the absence of one.
	pub := dialProps(t, h, "publisher")

	// The default asks for state and gets it, which is the behaviour every
	// other test in this file relies on.
	want := dialProps(t, h, "wants-state")
	want.Sub(t, "state/#", 1)
	if got := awaitProp(t, want); got == nil {
		t.Fatal("a subscriber taking the default was sent no current state")
	}

	// Asking for none is answered with none.
	live := dialProps(t, h, "live-only")
	sa, err := live.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{
			{Topic: "state/#", QoS: 1, RetainHandling: 2},
		},
	})
	if sa == nil {
		t.Fatalf("subscribe: %v", err)
	}
	if got := awaitProp(t, live); got != nil {
		t.Fatalf("a subscriber asking for no retained messages was sent state: %q", got.Topic)
	}

	// And it is a subscription, not a mute: the next change arrives.
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "state/room", QoS: 1, Payload: []byte("cold"),
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	got := awaitProp(t, live)
	if got == nil {
		t.Fatal("a live-only subscriber received no update either, so it was muted rather than served")
	}
	if string(got.Payload) != "cold" {
		t.Errorf("payload %q, want \"cold\"", got.Payload)
	}
}

// An `append` channel's replay follows Retain Handling, the same option a
// `latest` channel and the retained store already read. Nothing else in
// MQTT lets a subscriber say "live only", and a consumer that wants it
// otherwise has to seek - which needs a durable session and a second round
// trip, so a client that merely wanted to watch had to become a consumer
// with a stored position first.
//
// **This is saguin extending the option rather than applying it.** A
// replayed record is not a retained message: it has no retain flag, it is
// one of many rather than the current value of a topic, and MQTT says
// nothing about either. What carries across is the client's meaning -
// "send me what is happening, not what happened" - and RFC 0003 says so
// rather than leaving it to look like conformance.
//
// 0 and 1 are the same answer here, deliberately. 1 means "only if the
// subscription is new", which is a rule about not re-sending one topic's
// current value; a replay has no equivalent, so treating 1 as 0 is the
// reading that does not invent behaviour.
func TestAnAppendReplayFollowsRetainHandling(t *testing.T) {
	t.Run("no saved position", func(t *testing.T) {
		h := start(t)
		p := connect(t, h, "producer", true, false)
		for _, m := range []string{"one", "two"} {
			p.Pub(t, "events/"+m, m)
		}
		settle(t, p)

		// The default replays, which is what every other test relies on.
		d := dialProps(t, h, "default")
		d.Sub(t, "events/#", 1)
		if got := awaitProp(t, d); got == nil {
			t.Fatal("a subscriber taking the default was sent no backlog")
		}

		// And 2 asks for nothing older than now.
		live := dialProps(t, h, "live-only")
		if sa, err := live.C.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{
				{Topic: "events/#", QoS: 1, RetainHandling: 2},
			},
		}); sa == nil {
			t.Fatalf("subscribe: %v", err)
		}
		if got := awaitProp(t, live); got != nil {
			t.Fatalf("a subscriber asking for no replay was sent %q", got.Topic)
		}

		// A subscription rather than a mute: what happens next arrives.
		p.Pub(t, "events/three", "three")
		got := awaitProp(t, live)
		if got == nil {
			t.Fatal("the live-only subscriber received no new record either, " +
				"so it was muted rather than served")
		}
		if string(got.Payload) != "three" {
			t.Errorf("payload %q, want \"three\"", got.Payload)
		}
	})

	// **The durable half is a unit test and says why there.** 2 also
	// commits the position at the head, and neither end-to-end shape can
	// see that: a cursor lives as long as the session, so reconnecting
	// without ending it reuses the cursor already at the head and passes
	// with the commit removed, while ending the session to force a rebuild
	// drops the stored position too. The test named for that in
	// position_test.go reads the store directly, which is the only thing
	// that can tell a committed skip from one held in memory.
}

// MQTT-3.3.1-13: a subscriber that asked for Retain As Published is sent
// the retain flag as the publisher set it. Broadcast has honoured it since
// OnRetainMessage; a channel cleared it for everybody, so a RAP subscriber
// reading a `latest` or `append` channel saw 0 on every delivery whatever
// its publishers did.
//
// **The current-state pass is the exception, and it is the same exception
// broadcast makes.** A value served at SUBSCRIBE carries RETAIN for
// everybody, RAP subscriber or not, because that flag is saguin saying
// "this is what you are catching up on" rather than a publisher's word -
// which is the whole reason a `latest` channel sets it. RAP changes the
// live delivery, where saguin was overwriting the publisher.
func TestRetainAsPublishedIsHonouredOnAChannel(t *testing.T) {
	for _, tc := range []struct{ name, filter, topic string }{
		{"latest", "state/#", "state/lamp"},
		{"append", "events/#", "events/thing"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)

			rap := dialProps(t, h, "rap")
			if sa, err := rap.C.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{
					{Topic: tc.filter, QoS: 1, RetainAsPublished: true},
				},
			}); sa == nil {
				t.Fatalf("subscribe: %v", err)
			}
			// Both subscriptions' own work done before anything is
			// published: a latest subscription's current state is read
			// after its SUBACK, and a value published meanwhile reaches it
			// live and again as state, carrying RETAIN (see
			// TestALiveValueRacingASubscriptionsStateIsNeitherLostNorStale).
			subscribed(t, rap.C)
			plain := dialProps(t, h, "plain")
			plain.Sub(t, tc.filter, 1)
			subscribed(t, plain.C)

			pub := dialProps(t, h, "publisher")
			for _, set := range []bool{true, false} {
				if _, err := pub.C.Publish(context.Background(), &paho.Publish{
					Topic: tc.topic, QoS: 1, Retain: set, Payload: []byte("v"),
				}); err != nil {
					t.Fatalf("publish retain=%v: %v", set, err)
				}

				got := awaitProp(t, rap)
				if got == nil {
					t.Fatalf("the Retain As Published subscriber received nothing for retain=%v", set)
				}
				if got.Retain != set {
					t.Errorf("a Retain As Published subscriber saw the flag as %v for a "+
						"publish that set it %v; MQTT-3.3.1-13 sends it as published",
						got.Retain, set)
				}

				// MQTT-3.3.1-12, the other half: everybody else sees it down
				// on a live delivery, because that is an update.
				got = awaitProp(t, plain)
				if got == nil {
					t.Fatalf("the ordinary subscriber received nothing for retain=%v", set)
				}
				if got.Retain {
					t.Errorf("an ordinary subscriber saw the flag up on a live delivery "+
						"of a publish that set it %v", set)
				}
			}
		})
	}

	// And the pass that is saguin's own word rather than a publisher's: a
	// `latest` channel's catch-up carries RETAIN even for a subscriber that
	// asked for the publisher's flag, and even where no publisher ever set
	// one. Broadcast does the same, and a client that could not tell state
	// from an update on the channel type built for state would have lost the
	// one signal MQTT gives it.
	t.Run("a latest catch-up still carries the flag", func(t *testing.T) {
		h := start(t)
		fannedOut(t, h, "seed", "state/room", "warm", false)

		rap := dialProps(t, h, "rap")
		if sa, err := rap.C.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{
				{Topic: "state/#", QoS: 1, RetainAsPublished: true},
			},
		}); sa == nil {
			t.Fatalf("subscribe: %v", err)
		}
		got := awaitProp(t, rap)
		if got == nil {
			t.Fatal("the Retain As Published subscriber was sent no current state")
		}
		if !got.Retain {
			t.Error("a current-state value arrived without RETAIN for a Retain As " +
				"Published subscriber; the catch-up flag is saguin's word, not the " +
				"publisher's, and without it a client cannot tell state from an update")
		}
	})
}

// The other branch of the CONNACK rule: a broker with no `latest` channel
// can still honour the retain flag when an operator configured a store for
// broadcast topics, and must say so.
func TestTheConnackSaysRetainIsAvailableWhenOnlyTheStoreCanKeepOne(t *testing.T) {
	brokertest.WithoutLatest = true
	t.Cleanup(func() { brokertest.WithoutLatest = false })
	h := startRetaining(t, 0)

	props, shown := connackProperties(t, h.Addr, "connack-store-only")
	got, ok := props[0x25]
	if !ok {
		t.Fatalf("the CONNACK carries no Retain Available (0x25): %s", shown)
	}
	if len(got) != 1 || got[0] != 1 {
		t.Errorf("Retain Available is % 02x, want 1 on a broker with a retained store: %s",
			got, shown)
	}
}

// Durability, for the retained store, which is the same promise its
// provider makes about every channel on it (invariant 14): a memory
// provider survives a graceful shutdown, a database survives a crash.
//
// The whole reason this matters: a Home Assistant deployment publishes its
// device tree once, retained, and expects it to be there after a broker
// restart. Without this the tree is gone and every entity goes unavailable.
func TestRetainedMessagesSurviveARestart(t *testing.T) {
	t.Run("a memory provider, across a graceful shutdown", func(t *testing.T) {
		dir := t.TempDir()
		h := startRetainingDurably(t, dir, "")

		pub := dialProps(t, h, "publisher")
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "house/study/lamp", QoS: 1, Retain: true, Payload: []byte("on"),
		}); err != nil {
			t.Fatalf("publish: %v", err)
		}
		h.Stop()

		next := startRetainingDurably(t, dir, "")
		late := dialProps(t, next, "late")
		late.Sub(t, "house/#", 1)

		got := awaitProp(t, late)
		if got == nil {
			t.Fatal("nothing came back after a restart: the retained store was not written or not read")
		}
		if got.Topic != "house/study/lamp" || string(got.Payload) != "on" {
			t.Errorf("came back as %q %q, want house/study/lamp \"on\"", got.Topic, got.Payload)
		}
		if !got.Retain {
			t.Error("came back without the retain flag, so a client cannot tell state from an update")
		}
		// A retained delivery is capped at the QoS the value was published
		// at, so a snapshot that dropped it sent this at most once.
		if got.QoS != 1 {
			t.Errorf("came back at QoS %d, want the 1 it was published and subscribed at", got.QoS)
		}
	})

	t.Run("a database, across a crash", func(t *testing.T) {
		path := filepath.Join(t.TempDir(), "saguin.db")
		h := startRetainingDurably(t, "", path)

		pub := dialProps(t, h, "publisher")
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "house/attic/lamp", QoS: 1, Retain: true, Payload: []byte("off"),
		}); err != nil {
			t.Fatalf("publish: %v", err)
		}
		// No snapshot and no close: the difference between a store that
		// writes as it goes and one that writes at the end.
		h.Crash()

		next := startRetainingDurably(t, "", path)
		late := dialProps(t, next, "late")
		late.Sub(t, "house/#", 1)

		got := awaitProp(t, late)
		if got == nil {
			t.Fatal("nothing came back after a crash, so the database was not written as it went")
		}
		if got.Topic != "house/attic/lamp" || string(got.Payload) != "off" {
			t.Errorf("came back as %q %q, want house/attic/lamp \"off\"", got.Topic, got.Payload)
		}
		if got.QoS != 1 {
			t.Errorf("came back at QoS %d, want the 1 it was published and subscribed at", got.QoS)
		}
	})

	// Two topics, one of them deleted before the restart. One survivor is
	// the assertion: "nothing came back" would also be true of a store
	// that lost everything, so a test that only looked for the absence
	// would pass against exactly the defect the case above is about.
	t.Run("a deletion survives too", func(t *testing.T) {
		dir := t.TempDir()
		h := startRetainingDurably(t, dir, "")

		pub := dialProps(t, h, "publisher")
		for _, p := range []struct {
			topic   string
			payload []byte
		}{
			{"house/cellar/lamp", []byte("on")},
			{"house/garage/lamp", []byte("on")},
			{"house/cellar/lamp", nil}, // deleted
		} {
			if _, err := pub.C.Publish(context.Background(), &paho.Publish{
				Topic: p.topic, QoS: 1, Retain: true, Payload: p.payload,
			}); err != nil {
				t.Fatalf("publish: %v", err)
			}
		}
		h.Stop()

		next := startRetainingDurably(t, dir, "")
		late := dialProps(t, next, "late")
		late.Sub(t, "house/#", 1)

		got := awaitProp(t, late)
		if got == nil {
			t.Fatal("nothing came back at all, so the store did not survive the restart")
		}
		if got.Topic != "house/garage/lamp" {
			t.Fatalf("a deleted topic came back after a restart: %q %q", got.Topic, got.Payload)
		}
		if extra := awaitProp(t, late); extra != nil {
			t.Fatalf("the deleted topic came back as well: %q %q", extra.Topic, extra.Payload)
		}
	})
}

// refusesWillTakeOff is a session store that refuses, each once when armed,
// the write taking a Will off dev's record - a Save of it with no Will - and
// the write stamping its due moment, as a store failing at either moment
// would.
type refusesWillTakeOff struct {
	broker.SessionStore
	take, stamp, disc atomic.Bool
	// holding refuses every write taking dev's Will off - the broker's own
	// retries of the refused one among them - until the test lets them land,
	// so a retry cannot land before the test looks at the record.
	holding atomic.Bool
	failed  atomic.Int32
	// stamps is how many more stamps to refuse after the one stamp arms.
	stamps atomic.Int32
}

// Disconnected refuses dev's, once when disc is armed.
func (s *refusesWillTakeOff) Disconnected(client string, at time.Time, dropWill bool, expiry uint32) error {
	if client == "dev" && dropWill && s.holding.Load() {
		return errors.New("refused for the test")
	}
	if client == "dev" && s.disc.CompareAndSwap(true, false) {
		s.failed.Add(1)
		return errors.New("refused for the test")
	}
	return s.SessionStore.Disconnected(client, at, dropWill, expiry)
}

func (s *refusesWillTakeOff) Unwrap() broker.SessionStore { return s.SessionStore }

// Snapshot is the memory store's, so a stop still writes the sessions file
// through the wrapper: without it the memory arm restarted with no sessions
// at all, and "the next start publishes nothing" held for the wrong reason.
func (s *refusesWillTakeOff) Snapshot() *store.SessionsSnapshot {
	if ex, ok := s.SessionStore.(interface {
		Snapshot() *store.SessionsSnapshot
	}); ok {
		return ex.Snapshot()
	}
	return nil
}

func (s *refusesWillTakeOff) Save(sess store.Session) error {
	if sess.Client == "dev" && (sess.Will == nil && s.take.CompareAndSwap(true, false) ||
		sess.Will != nil && !sess.Will.DueAt.IsZero() && (s.stamp.CompareAndSwap(true, false) || s.stamps.Add(-1) >= 0)) {
		s.failed.Add(1)
		return errors.New("refused for the test")
	}
	if sess.Client == "dev" && sess.Will == nil && s.holding.Load() {
		return errors.New("refused for the test")
	}
	return s.SessionStore.Save(sess)
}

// A Will is published once (RFC 0003 "Last Will"). One the store refused to
// take off its record is published all the same, and the record still
// holding it is not a Will owed: not at the next start, which read it as
// one whose delay passed while the broker was stopped, and not when its
// session ends, where a Will whose moment the store also refused to stamp
// read as one nothing had made due yet. The refused write is remembered and
// written as the broker stops, as a refused disconnect is.
func TestAWillTheStoreWouldNotTakeOffIsPublishedOnce(t *testing.T) {
	for _, when := range []string{"at the next start", "when its session ends"} {
		for _, p := range []string{"memory", "sqlite"} {
			t.Run(when+"/"+p, func(t *testing.T) {
				rt := &refusesWillTakeOff{}
				brokertest.WrapSessions = func(s broker.SessionStore) broker.SessionStore {
					rt.SessionStore = s
					return rt
				}
				t.Cleanup(func() { brokertest.WrapSessions = nil })
				var r restartable
				for _, c := range restartables(t) {
					if c.name == p {
						r = c
					}
				}
				h := r.start(t)
				w := dial(t, h, "watcher", false, false, 0, 3600, 0)
				w.Sub(t, "events/wills/#", 1)
				expiry, refusals := uint32(60), int32(1)
				rt.take.Store(true)
				// **Held in both arms.** The owed-write retry tries the
				// refused take-off again each second, and one landing
				// before the record is looked at below took the Will off
				// it: at one P the session-end arm lost that race. The
				// session-end arm holds it until the session has ended.
				rt.holding.Store(true)
				if when == "when its session ends" {
					expiry, refusals = 3, 2
					rt.stamp.Store(true)
				}
				conn, code := connectWithWillExpiring(t, h, "dev", "events/wills/dev", false, 1, 1, expiry)
				if code != 0 {
					t.Fatalf("connect: %#x", code)
				}
				_ = conn.Close()
				eventually(t, "the delayed Will published", 5*time.Second, func() bool {
					return h.B.WillsPublished("delayed") == 1
				})
				// The take-off is written after the publish, so its refusal
				// is waited for, not read the moment the Will is counted.
				eventually(t, "the store's refusals", 5*time.Second, func() bool {
					return rt.failed.Load() >= refusals
				})
				if n := rt.failed.Load(); n != refusals {
					t.Fatalf("the store refused %d writes, want %d, so this proves nothing", n, refusals)
				}
				if _, ok := w.Await(t, 3*time.Second); !ok {
					t.Fatal("the watcher was not sent the delayed Will")
				}
				if rec, ok, _ := brokertest.HarnessSessions.Get("dev"); !ok || rec.Will == nil {
					t.Fatalf("the record is kept=%v with Will %+v; the refused take-off should have "+
						"left the Will on it, so this proves nothing", ok, rec.Will)
				}

				if when == "at the next start" {
					// The watcher's PUBACK for the Will is processed before
					// the stop, or the next start replays the unacknowledged
					// record and it reads as a second publish.
					settle(t, w)
					rt.holding.Store(false)
					h.Stop()
					if rec, _, _ := brokertest.HarnessSessions.Get("dev"); rec.Will != nil {
						t.Errorf("the stop left the published Will on the record: %+v", rec.Will)
					}
					h = r.start(t)
					if _, ok, _ := brokertest.HarnessSessions.Get("dev"); !ok {
						t.Error("the start ended dev's session, still inside its 60 s: the stop's write " +
							"did not keep the record's expiry")
					}
					if n := h.B.WillsPublished("start"); n != 0 {
						t.Errorf("the next start published %d Wills, want none: the Will was published "+
							"before the stop", n)
					}
					w = dial(t, h, "watcher", false, false, 0, 3600, 0)
				} else {
					eventually(t, "the session ended", 10*time.Second, func() bool {
						_, ok, _ := brokertest.HarnessSessions.Get("dev")
						return !ok
					})
					rt.holding.Store(false)
					if n := h.B.WillsPublished("session_ended"); n != 0 {
						t.Errorf("the session's end published its Will %d more time(s)", n)
					}
				}
				if got, ok := w.Await(t, 1500*time.Millisecond); ok {
					t.Fatalf("the watcher was sent the Will again: %q %q", got.Topic, got.Payload)
				}
			})
		}
	}
}

// willAppendGate holds one Append of dev's Will still until it is let go,
// so a stop can begin while OnWill is publishing.
type willAppendGate struct {
	broker.LogStore
	armed   atomic.Bool
	entered chan struct{}
	release chan struct{}
}

// Unwrap is the store the gate holds calls in front of, so the broker's
// type questions - a snapshot's among them - see through the gate.
func (g *willAppendGate) Unwrap() broker.LogStore { return g.LogStore }

// gateLog installs a gate over one append channel's log in each harness the
// test starts from here on, before it serves and beneath the counting
// wrapper (brokertest.WrapLogs). set hands the gate the log it wraps and
// answers the gate. A gate is armed later; unarmed, it passes every call.
func gateLog(t *testing.T, channel string, set func(broker.LogStore) broker.LogStore) {
	t.Helper()
	brokertest.WrapLogs = func(name string, l broker.LogStore) broker.LogStore {
		if name != channel {
			return l
		}
		return set(l)
	}
	t.Cleanup(func() { brokertest.WrapLogs = nil })
}

func (g *willAppendGate) Append(rec store.Record) (store.Record, error) {
	if rec.Topic == "events/wills/dev" && g.armed.CompareAndSwap(true, false) {
		close(g.entered)
		<-g.release
	}
	return g.LogStore.Append(rec)
}

// A Will published as the broker begins to stop is gone, like any Will that
// fired: the device did die. It was taken off its record by the disconnect,
// which asked a second time whether the broker was stopping - so a stop
// beginning between the publish and the disconnect kept it, with no moment,
// and the next start published it again when the session expired.
func TestAnImmediateWillPublishedAsTheBrokerStopsIsNotPublishedAgain(t *testing.T) {
	for _, r := range restartables(t) {
		t.Run(r.name, func(t *testing.T) {
			g := &willAppendGate{entered: make(chan struct{}), release: make(chan struct{})}
			gateLog(t, "events", func(lg broker.LogStore) broker.LogStore { g.LogStore = lg; return g })
			h := r.start(t)
			w := dial(t, h, "watcher", false, false, 0, 3600, 0)
			w.Sub(t, "events/wills/#", 1)
			var once sync.Once
			let := func() { once.Do(func() { close(g.release) }) }
			t.Cleanup(let)

			conn, code := connectWithWillExpiring(t, h, "dev", "events/wills/dev", false, 0, 1, 3)
			if code != 0 {
				t.Fatalf("connect: %#x", code)
			}
			g.armed.Store(true)
			_ = conn.Close()
			select {
			case <-g.entered:
			case <-time.After(5 * time.Second):
				t.Fatal("the Will's Append was never entered, so this proves nothing")
			}
			// The gate stays: the stop's snapshot sees through it (Unwrap), and
			// the Append it holds carries on into the store beneath it.
			stopped := make(chan struct{})
			go func() { h.Stop(); close(stopped) }()
			eventually(t, "the stop begun", 5*time.Second, h.B.Stopping)
			let()
			select {
			case <-stopped:
			case <-time.After(20 * time.Second):
				t.Fatal("the stop never finished")
			}
			if n := h.B.WillsPublished("immediate"); n != 1 {
				t.Fatalf("the stopping broker published %d immediate Wills, want the one, so this proves nothing", n)
			}

			h = r.start(t)
			w = dial(t, h, "watcher", false, false, 0, 3600, 0)
			if got, ok := w.Await(t, 3*time.Second); !ok || got.Payload != "i-died" {
				t.Fatalf("the watcher's session did not keep the Will published at the stop: ok=%v %+v", ok, got)
			}
			eventually(t, "the session ended", 10*time.Second, func() bool {
				_, ok, _ := brokertest.HarnessSessions.Get("dev")
				return !ok
			})
			if n := h.B.WillsPublished("session_ended") + h.B.WillsPublished("start"); n != 0 {
				t.Errorf("after the restart the same Will was published %d more time(s)", n)
			}
			if got, ok := w.Await(t, 1500*time.Millisecond); ok {
				t.Fatalf("the watcher was sent the Will again: %q %q", got.Topic, got.Payload)
			}
		})
	}
}

// refusesDisconnected is a session store that refuses to record one client's
// disconnect once armed, as a store failing at that moment would - or, while
// always is set, every time it is asked, as a store failing for a while does.
// A disconnect the store refuses is written again (OnDisconnect, and every
// tick), so a test about what a refusal leaves behind refuses for as long as
// it looks.
type refusesDisconnected struct {
	broker.SessionStore
	client string
	armed  atomic.Bool
	always atomic.Bool
	failed atomic.Int32
}

func (s *refusesDisconnected) Unwrap() broker.SessionStore { return s.SessionStore }

func (s *refusesDisconnected) Disconnected(client string, at time.Time, dropWill bool, expiry uint32) error {
	if client == s.client && (s.always.Load() || s.armed.CompareAndSwap(true, false)) {
		s.failed.Add(1)
		return errors.New("refused for the test")
	}
	return s.SessionStore.Disconnected(client, at, dropWill, expiry)
}

// refuseDisconnectOf wraps the next sqlite harness's session store so that it
// refuses one disconnect of client, and answers the wrapper and the store.
func refuseDisconnectOf(t *testing.T, client string) (*refusesDisconnected, func() broker.SessionStore) {
	t.Helper()
	rd := &refusesDisconnected{client: client}
	var inner broker.SessionStore
	brokertest.WrapSessions = func(s broker.SessionStore) broker.SessionStore {
		inner, rd.SessionStore = s, s
		return rd
	}
	t.Cleanup(func() { brokertest.WrapSessions = nil })
	return rd, func() broker.SessionStore { return inner }
}

// RFC 0003 "Sessions": a session the store could not be told the client left
// still ends when its expiry says. The record goes on reading as connected,
// so the running broker's own clock is what ends it; and after a crash the
// start reads it as connected at the stop, and it ends one interval after
// that start. Never kept for good (invariant 13). And nothing about it is
// remembered once it has ended.
func TestASessionWhoseDisconnectWasNotRecordedStillExpires(t *testing.T) {
	for _, how := range []string{"running", "across a crash"} {
		t.Run(how, func(t *testing.T) {
			rd, inner := refuseDisconnectOf(t, "dev")
			path := filepath.Join(t.TempDir(), "saguin.db")
			h := startDurableSQLite(t, path)
			c := brokertest.Dial(t, h, "dev", true, false, 10, 2, 0)
			c.Sub(t, "news/#", 1)
			rd.always.Store(true)
			before := h.Disconnects.Snapshot("dev")
			c.Close()
			sessionGoneAfter(t, h, "dev", before)
			if rd.failed.Load() == 0 {
				t.Fatal("the store was never asked to record the disconnect, so this proves nothing")
			}
			if rec, ok, _ := inner().Get("dev"); !ok || !rec.DisconnectedAt.IsZero() {
				t.Fatalf("the record is kept=%v disconnected=%v; want kept and never told, so this proves nothing",
					ok, rec.DisconnectedAt)
			}
			within := 5 * time.Second
			if how == "across a crash" {
				h.Crash()
				time.Sleep(2500 * time.Millisecond) // past its expiry, while nothing runs
				h = startDurableSQLite(t, path)
				if _, ok, _ := inner().Get("dev"); !ok {
					t.Fatal("the start ended a session it reads as connected at the stop, so this proves nothing")
				}
			}
			eventually(t, "the session ended", within, func() bool {
				_, ok, _ := inner().Get("dev")
				return !ok
			})
			if n := h.B.UnwrittenDisconnects(); n != 0 {
				t.Errorf("%d unwritten disconnects are still remembered after the session ended", n)
			}
		})
	}
}

// MQTT-3.1.2-10: a Will is not published after its client disconnects with
// reason 0x00 - not at the disconnect, and not when the session ends. The
// store refusing to record the disconnect leaves the Will on the record; the
// broker remembers it was withdrawn, and the session's ending publishes
// nothing, with no delay and with one. A link cut, where the Will is owed,
// shows the watcher would have seen it. And a client that comes back arms a
// Will of its own, which the withdrawal before it does not reach.
func TestAWillWithdrawnWhenTheStoreRefusedToHearItIsNotPublished(t *testing.T) {
	for _, tc := range []struct {
		name  string
		delay uint32
		clean bool
		back  bool
	}{
		{"no delay", 0, true, false},
		{"a delay", 1, true, false},
		{"a link cut, owed", 0, false, false},
		{"withdrawn, then back with a Will its link cut owes", 0, true, true},
		{"withdrawn, then resumed with a Will its session's end owes", 0, true, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			rd, inner := refuseDisconnectOf(t, "dev")
			h := startDurableSQLite(t, filepath.Join(t.TempDir(), "saguin.db"))
			w := connect(t, h, "watcher", true, false)
			w.Sub(t, "wills/#", 1)
			conn, code := connectWithWillExpiring(t, h, "dev", "wills/dev", false, tc.delay, 1, 2)
			if code != 0 {
				t.Fatalf("connect: %#x", code)
			}
			rd.always.Store(true)
			if tc.clean {
				if _, err := conn.Write([]byte{0xE0, 0x00}); err != nil {
					t.Fatal(err)
				}
			}
			_ = conn.Close()
			if tc.back {
				eventually(t, "the refusal", 5*time.Second, func() bool { return rd.failed.Load() >= 1 })
				// The store recovers before the client comes back, or its
				// CONNECT would be refused for the write still owed.
				rd.always.Store(false)
				var again net.Conn
				if strings.HasPrefix(tc.name, "withdrawn, then resumed") {
					// Clean Start 0, so no session ends and only the CONNACK can
					// forget what was unwritten; and a delay past its expiry, so
					// the Will is the session's end's to publish.
					again = resumeWithWill(t, h, "dev", "wills/dev", 5, 2)
				} else {
					var code byte
					if again, code = connectWithWillExpiring(t, h, "dev", "wills/dev", false, 0, 1, 2); code != 0 {
						t.Fatalf("connect again: %#x", code)
					}
				}
				// Cleared as the CONNACK is written, which the client may read first.
				eventually(t, "the id's unwritten disconnect forgotten once it is connected again",
					2*time.Second, func() bool { return h.B.UnwrittenDisconnects() == 0 })
				_ = again.Close() // a link cut: this Will is owed
			}
			eventually(t, "the session ended", 6*time.Second, func() bool {
				_, ok, _ := inner().Get("dev")
				return !ok
			})
			if tc.clean && rd.failed.Load() == 0 {
				t.Fatal("the store refused no disconnect, so this proves nothing")
			}
			want := 0
			if !tc.clean || tc.back {
				want = 1
			}
			// The Will that is owed waited for, then counted against an end
			// marker: one its end published twice, or a withdrawn one, is in
			// the watcher's outbound queue ahead of it.
			awaitCount(t, w, want, 5*time.Second)
			connect(t, h, "marker", true, false).Pub(t, "wills/marker", "marker")
			for deadline := time.Now().Add(5 * time.Second); !slices.Contains(w.Payloads(), "marker"); time.Sleep(5 * time.Millisecond) {
				if time.Now().After(deadline) {
					t.Fatalf("the end marker never reached the watcher; it holds %v", w.Payloads())
				}
			}
			if got := w.Count() - 1; got != want {
				t.Errorf("the watcher received %d Wills %v, want %d", got, w.Payloads(), want)
			}
			if n := h.B.UnwrittenDisconnects(); n != 0 {
				t.Errorf("%d unwritten disconnects are still remembered after the session ended", n)
			}
		})
	}
}

// resumeWithWill connects id with Clean Start 0 and a Will on topic, and
// answers the connection, whose Close is a link cut.
func resumeWithWill(t *testing.T, h *brokertest.Harness, id, topic string, delay, expiry uint32) net.Conn {
	t.Helper()
	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	t.Cleanup(func() { _ = conn.Close() })
	c := paho.NewClient(paho.ClientConfig{Conn: conn})
	ca, err := c.Connect(context.Background(), &paho.Connect{ClientID: id, CleanStart: false, KeepAlive: 60,
		WillMessage:    &paho.WillMessage{Topic: topic, QoS: 1, Payload: []byte("i-died")},
		WillProperties: &paho.WillProperties{WillDelayInterval: &delay},
		Properties:     &paho.ConnectProperties{SessionExpiryInterval: &expiry}})
	if err != nil || ca.ReasonCode != 0 || !ca.SessionPresent {
		t.Fatalf("resume %s: %v %+v, want its session present", id, err, ca)
	}
	return conn
}

// A delayed Will falling due while the broker stops is not published by the
// stopping broker: its timer fires where Shutdown, having waited for its
// drains, used to still have it armed, and publishes nothing and changes
// nothing. Published there, its record could land after the channel's
// snapshot, beside a session store saved without the Will, and nothing
// counted the drain it started. The Will and its due moment are still on
// the session's record after the stop, and the next start publishes it,
// once. On both session stores.
func TestADelayedWillDueDuringAStopIsPublishedByTheNextStart(t *testing.T) {
	dir, path := t.TempDir(), filepath.Join(t.TempDir(), "saguin.db")
	for _, p := range []struct {
		name  string
		start func() *brokertest.Harness
	}{
		{"memory", func() *brokertest.Harness { return startDurable(t, dir) }},
		{"sqlite", func() *brokertest.Harness { return startDurableSQLite(t, path) }},
	} {
		t.Run(p.name, func(t *testing.T) {
			h := p.start()
			conn, code := connectWithWillExpiring(t, h, "dev", "events/wills/dev", false, 3, 1, 30)
			if code != 0 {
				t.Fatalf("connect: %#x", code)
			}
			_ = conn.Close()
			var fire func()
			eventually(t, "the Will held for its delay", 5*time.Second, func() bool {
				f, ok := h.B.PendingWillFire("dev")
				fire = f
				return ok
			})
			fired := false
			broker.AfterDrainsWait(t, func() { fired = true; fire() })
			stopping := h.B
			h.Stop()
			if !fired {
				t.Fatal("the Will's timer never ran inside the stop, so this proves nothing")
			}
			if n := stopping.WillsPublished("delayed"); n != 0 {
				t.Fatalf("the stopping broker published %d delayed Will(s): its timer fired into it after "+
					"its drains were waited for", n)
			}

			h = p.start()
			// Read as the start begins, so the start may already have
			// published the Will, which also shows it survived the stop.
			rec, ok, err := brokertest.HarnessSessions.Get("dev")
			kept := err == nil && ok && rec.Will != nil && !rec.Will.DueAt.IsZero()
			if !kept && h.B.WillsPublished("delayed") == 0 {
				t.Fatalf("after the stop the session is kept=%v (err %v) with Will %+v, and nothing was "+
					"published: the refused fire took the Will or its due moment, and the next start "+
					"has nothing to publish", ok, err, rec.Will)
			}
			eventually(t, "the Will published by the next start", 10*time.Second, func() bool {
				return h.B.WillsPublished("delayed") == 1
			})
			time.Sleep(500 * time.Millisecond)
			if n := h.B.WillsPublished("delayed"); n != 1 {
				t.Fatalf("the next start published %d delayed Wills, want 1", n)
			}
			h.Stop()
		})
	}
}

// A disconnect the store refused while the broker ran is written as it stops,
// so the next start reads the session as its client left it: gone at that
// moment, its Will withdrawn. The memory that kept the Will from being
// published does not survive the stop, so it is the record that has to say
// so; and when the session ends at the broker that comes back, nothing is
// published.
func TestAStopWritesTheDisconnectsTheStoreRefused(t *testing.T) {
	rd, inner := refuseDisconnectOf(t, "dev")
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)
	conn, code := connectWithWillExpiring(t, h, "dev", "wills/dev", false, 0, 1, 3)
	if code != 0 {
		t.Fatalf("connect: %#x", code)
	}
	rd.always.Store(true)
	if _, err := conn.Write([]byte{0xE0, 0x00}); err != nil {
		t.Fatal(err)
	}
	_ = conn.Close()
	eventually(t, "the refusal", 5*time.Second, func() bool { return rd.failed.Load() >= 2 })
	if n := h.B.UnwrittenDisconnects(); n != 1 {
		t.Fatalf("%d unwritten disconnects remembered, want the one, so this proves nothing", n)
	}
	// The store recovers as the broker stops: the stop is what writes it.
	rd.always.Store(false)
	h.Stop()

	h = startDurableSQLite(t, path)
	rec, ok, _ := inner().Get("dev")
	if !ok || rec.DisconnectedAt.IsZero() || rec.Will != nil {
		t.Fatalf("after the stop the record is kept=%v disconnected=%v Will=%v; want kept, with the "+
			"disconnect and the withdrawal written", ok, rec.DisconnectedAt, rec.Will)
	}
	w := connect(t, h, "watcher", true, false)
	w.Sub(t, "wills/#", 1)
	eventually(t, "the session ended", 6*time.Second, func() bool {
		_, ok, _ := inner().Get("dev")
		return !ok
	})
	// A marker published after the session ended arrives first and alone
	// unless the withdrawn Will went out when it ended.
	connect(t, h, "marker", true, false).Pub(t, "wills/marker", "marker")
	if r, ok := w.Await(t, 5*time.Second); !ok || r.Payload != "marker" {
		t.Errorf("the watcher was sent %q (%v) before the marker: a Will its client withdrew "+
			"was published", r.Payload, ok)
	}
}

// A Will Delay Interval is honoured by saguin rather than by the
// substrate, and this is the test that says why it had to be.
//
// Measured against the substrate directly, as it was: a Will carrying a
// delay fired OnWill at the disconnection and then nothing - not OnPublish,
// not even the OnWillSent it then had - while the message reached
// subscribers regardless. So a
// delayed Will left to it is one that skips the publish path entirely,
// which is the configuration a flapping link makes people set.
func TestAWillWithADelayWaitsAndThenFires(t *testing.T) {
	h := start(t)

	// A channel rather than a broadcast topic, and that is the whole
	// design of this test. The substrate delays a Will of its own accord
	// too - so a broadcast target cannot tell "saguin held it and routed
	// it" from "the substrate held it and published past every hook", and
	// an earlier version of this test passed with saguin's half disabled.
	// A channel can tell them apart, because only one of those two stores
	// the record.
	watcher := connect(t, h, "watcher", true, false)
	watcher.Sub(t, "events/#", 1)
	subscribed(t, watcher.C)

	// **A session for the delay to wait in**, which is what a delay needs: a
	// Will is discarded when its session ends, and a Clean Start session with
	// no expiry ends at the disconnect - so a delay armed on one is published
	// at once rather than waited out (RFC 0003, and MQTT 5 3.1.3.2.2). This
	// test is about the wait, so it asks for a session that outlives the
	// connection.
	conn, code := connectWithWillExpiring(t, h, "slow-dier", "events/delayed", false, 1, 0, 300)
	if code != 0x00 {
		t.Fatalf("refused with 0x%02X", code)
	}
	kill(t, conn)

	// Nothing yet: the delay has not passed.
	if got, ok := watcher.Await(t, 400*time.Millisecond); ok {
		t.Fatalf("the Will fired immediately (%q), so its delay was ignored", got.Payload)
	}

	got, ok := watcher.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the Will never fired, so a delayed Will is a Will that is lost")
	}
	if got.Topic != "events/delayed" || got.Payload != "i-died" {
		t.Fatalf("received %q %q, want events/delayed i-died", got.Topic, got.Payload)
	}
	if got.User["saguin-id"] == "" {
		t.Error("the delayed Will arrived with no saguin-id, so it was published past the " +
			"publish path rather than through it")
	}

	// And it is in the channel, which is the half a Will published past the
	// publish path never has: a consumer arriving afterwards sees it.
	late := connect(t, h, "late", true, false)
	late.Sub(t, "events/#", 1)
	if _, ok := late.Await(t, 3*time.Second); !ok {
		t.Fatal("a consumer arriving after the delay received nothing, so the delayed Will " +
			"reached live subscribers and was stored nowhere")
	}
}

// The other half, and the reason a delay exists at all: a device that
// reconnects inside its delay, resuming its session, has not died, and
// announcing that it has is the false alarm the interval is for. A clean
// start ends the session and publishes the Will instead (RFC 0003
// "Sessions"; TestAWillIsItsOwnSessionsAcrossATakeover).
func TestAWillWithADelayIsCancelledByAReconnect(t *testing.T) {
	h := start(t)

	watcher := connect(t, h, "watcher", true, false)
	watcher.Sub(t, "loose/#", 1)
	subscribed(t, watcher.C)

	// **On a session that outlives the connection**, because that is what a
	// delay waits inside: flap protection is a session expiry at least as
	// long as the delay, and a Clean Start client asking for a delay is
	// asking for a wait its own session will not allow (RFC 0003).
	conn, code := connectWithWillExpiring(t, h, "flapper", "loose/flapped", false, 1, 0, 300)
	if code != 0x00 {
		t.Fatalf("refused with 0x%02X", code)
	}
	kill(t, conn)

	// Back inside the delay, resuming, which is what a bad link looks like -
	// once the broker has finished with the connection that died.
	sessionGone(t, h, "flapper")
	again := brokertest.WillResumeWithExpiry(t, h, "flapper", "loose/flapped", 1, 300)
	defer again.Close()

	// Well past the original delay: nothing should have been announced.
	if got, ok := watcher.Await(t, 2*time.Second); ok {
		t.Fatalf("a Will fired for a device that had already reconnected: %q %q - "+
			"every flap on a bad link would announce a device that is still there",
			got.Topic, got.Payload)
	}
}

// **A CONNECT that is refused changes nothing** (MQTT-3.1.4-2: a server that
// rejects a CONNECT "MUST NOT process any data sent by the Client after the
// CONNECT packet"; nor does a refused one become the connection whose client
// id it named). Before this, the broker acted on the CONNECT before its
// password was checked, so anyone who could reach the port could, by naming
// a client id and no valid credential:
//
//   - cancel that client's delayed Will, so a device that died is never
//     announced (MQTT-3.1.3-9 cancels it for a *connection*, which a refused
//     CONNECT is not);
//   - replace the properties of a Will a live client had armed;
//   - move the counters RFC 0005 defines over connections the broker took.
//
// Each case runs the same steps without the refused CONNECT as its control,
// so a Will that never fires or a counter that never moves cannot pass it.
func TestARefusedConnectChangesNothing(t *testing.T) {
	t.Run("it does not cancel another client's delayed Will", func(t *testing.T) {
		for _, refused := range []bool{false, true} {
			h := start(t)
			watcher := connect(t, h, "watcher", true, false)
			watcher.Sub(t, "loose/#", 1)
			time.Sleep(150 * time.Millisecond)

			conn, code := connectWithWill(t, h, "victim", "loose/victim-died", false, 2, 0)
			if code != 0x00 {
				t.Fatalf("the victim was refused 0x%02X", code)
			}
			kill(t, conn)
			requirePasswords(t, h)
			if refused {
				time.Sleep(200 * time.Millisecond)
				if got := connectAs(t, h, "victim", "real", "wrong"); got != 0x86 {
					t.Fatalf("the wrong password answered 0x%02X, want 0x86", got)
				}
			}
			if _, ok := watcher.Await(t, 4*time.Second); !ok {
				t.Fatalf("refused=%v: the victim's delayed Will never fired - a CONNECT "+
					"under its id that was not accepted cancelled it", refused)
			}
		}
	})

	t.Run("it does not replace a live client's Will properties", func(t *testing.T) {
		for _, refused := range []bool{false, true} {
			h := startRetaining(t, 0)
			watch := dialProps(t, h, "watcher")
			watch.Sub(t, "house/#", 1)
			time.Sleep(150 * time.Millisecond)

			victim := connectWithWillProps(t, h, "victim", "house/device/status", 0)
			requirePasswords(t, h)
			if refused {
				// A Will with no properties at all, under the victim's id,
				// from a client with no credential.
				c, code := connectWithWill(t, h, "victim", "house/device/status", false, 0, 0)
				_ = c.Close()
				if code == 0x00 {
					t.Fatal("an anonymous CONNECT was accepted after passwords were required")
				}
			}
			kill(t, victim)

			got := awaitProp(t, watch)
			if got == nil {
				t.Fatalf("refused=%v: the victim's Will was not delivered", refused)
			}
			if got.Properties == nil || got.Properties.ContentType != "application/json" {
				t.Errorf("refused=%v: the victim's Will arrived without the content type it "+
					"armed: %+v", refused, got.Properties)
			}
		}
	})

	t.Run("it is not counted as a connection the broker took", func(t *testing.T) {
		h := start(t)
		ops := operationsAt(t, h)
		requirePasswords(t, h)
		// More than the cap, so a CONNECT that is counted as shortened can be.
		huge := uint32(0xFFFFFFFF)
		dial := func(password string) byte {
			conn, err := net.Dial(h.Network, h.Addr)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			defer conn.Close()
			c := paho.NewClient(paho.ClientConfig{Conn: conn})
			ca, err := c.Connect(context.Background(), &paho.Connect{
				ClientID: "counted", CleanStart: true, Username: "real", Password: []byte(password),
				UsernameFlag: true, PasswordFlag: true,
				Properties: &paho.ConnectProperties{SessionExpiryInterval: &huge},
			})
			if ca == nil {
				t.Fatalf("no CONNACK: %v", err)
			}
			if ca.ReasonCode == 0 {
				_ = c.Disconnect(&paho.Disconnect{})
			}
			return ca.ReasonCode
		}
		const accepted = "saguin_connections_total"
		const shortened = "saguin_session_expiry_shortened_total"

		before := scrapeGauges(t, ops)
		if code := dial("wrong"); code != 0x86 {
			t.Fatalf("the wrong password answered 0x%02X, want 0x86", code)
		}
		time.Sleep(20 * time.Millisecond)
		afterRefused := scrapeGauges(t, ops)
		if code := dial("hunter2"); code != 0x00 {
			t.Fatalf("the right password answered 0x%02X", code)
		}
		time.Sleep(20 * time.Millisecond)
		afterAccepted := scrapeGauges(t, ops)

		for _, series := range []string{accepted, shortened} {
			if d := afterRefused[series] - before[series]; d != 0 {
				t.Errorf("%s moved by %v for a CONNECT that was refused", series, d)
			}
			if d := afterAccepted[series] - afterRefused[series]; d != 1 {
				t.Errorf("%s moved by %v for a CONNECT that was accepted, want 1 - "+
					"without this the refused half proves nothing", series, d)
			}
		}
	})
}

// **A connection that takes over a client id keeps its own Will
// properties.** The superseded connection's teardown runs after the new
// one has armed its Will, and it used to drop that client id's entry - so
// the Will of the connection that replaced it fired without the properties
// it carried.
func TestATakeoverKeepsTheNewConnectionsWillProperties(t *testing.T) {
	h := startRetaining(t, 0)
	watch := dialProps(t, h, "watcher")
	watch.Sub(t, "house/#", 1)
	subscribed(t, watch.C)

	first := connectWithWillProps(t, h, "device", "house/device/first", 0)
	defer first.Close()
	superseded := h.Disconnects.Snapshot("device")
	second := connectWithWillProps(t, h, "device", "house/device/second", 0)
	// The superseded connection's Will and teardown finished first.
	sessionGoneAfter(t, h, "device", superseded)
	for drained := false; !drained; {
		select {
		case <-watch.Ch:
		case <-time.After(300 * time.Millisecond):
			drained = true
		}
	}
	kill(t, second)

	got := awaitProp(t, watch)
	if got == nil {
		t.Fatal("the new connection's Will was not delivered")
	}
	if got.Topic != "house/device/second" {
		t.Fatalf("received the Will on %q, want house/device/second", got.Topic)
	}
	if got.Properties == nil || got.Properties.ContentType != "application/json" {
		t.Errorf("the Will of the connection that took over arrived without its "+
			"content type: %+v", got.Properties)
	}
}

// RFC 0003 "Every value says when it was set": a channel delivery carries
// saguin-timestamp, the moment the broker received the publish, as Unix
// milliseconds.
//
// This is the failure retained messages are best known for: a reading from
// a sensor that died three weeks ago looks exactly like one from a second
// ago, and no MQTT client can tell them apart. Read with the channel's
// retention period it stops being a diagnostic and becomes a promise -
// nothing older than the period is served, and what is served says how old
// it is.
func TestEveryChannelDeliveryCarriesItsTimestamp(t *testing.T) {
	h := start(t)
	before := time.Now().Add(-time.Second).UnixMilli()

	pub := dialProps(t, h, "publisher")
	for _, topic := range []string{"events/timed", "state/timed"} {
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Payload: []byte("v"),
		}); err != nil {
			t.Fatalf("publish %s: %v", topic, err)
		}
	}
	time.Sleep(150 * time.Millisecond)
	after := time.Now().Add(time.Second).UnixMilli()

	for _, tc := range []struct{ name, filter string }{
		{"an append channel", "events/#"},
		{"a latest channel", "state/#"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := dialProps(t, h, "reader-"+tc.filter[:5])
			c.Sub(t, tc.filter, 1)

			got := awaitProp(t, c)
			if got == nil {
				t.Fatal("no delivery")
			}
			var stamp string
			for _, u := range got.Properties.User {
				if u.Key == "saguin-timestamp" {
					stamp = u.Value
				}
			}
			if stamp == "" {
				t.Fatalf("the delivery carries no saguin-timestamp: %v", got.Properties.User)
			}
			ms, err := strconv.ParseInt(stamp, 10, 64)
			if err != nil {
				t.Fatalf("saguin-timestamp %q is not a decimal integer: %v", stamp, err)
			}
			// A real moment, not a zero value and not the far future: the
			// two failures a timestamp can have are being absent and being
			// wrong, and only one of them is visible without a bound.
			if ms < before || ms > after {
				t.Errorf("saguin-timestamp is %d, outside the window [%d, %d] the publish happened in",
					ms, before, after)
			}
		})
	}
}

// RFC 0003 "Moving a consumer's position": a seek may name a moment
// instead of an offset, and the shape of the payload is what tells them
// apart.
//
// A bare integer goes on meaning an offset, and that is the whole reason
// there is no flag: 1763000000 is a plausible offset and a plausible Unix
// time, and a consumer that seeks to the wrong one reads from there in
// order and reports success - a silent skip, which is the one failure a
// position must never produce.
func TestAConsumerSeeksByTime(t *testing.T) {
	h := start(t)

	// Six records, published now. A consumer asking for the last hour
	// should get all of them; one asking for a moment after them should
	// get none and wait.
	pub := connect(t, h, "publisher", true, false)
	for i := range 6 {
		pub.Pub(t, "events/timed", fmt.Sprintf("r%d", i))
	}
	time.Sleep(200 * time.Millisecond)

	for _, tc := range []struct {
		name, payload string
		want          int
	}{
		{"a relative duration", "-1h", 6},
		{"the same without a sign, because the future has no records", "1h", 6},
		{"days, which Go's own parser does not know", "-2d", 6},
		{"an absolute RFC 3339 moment before them", "2020-01-01T00:00:00Z", 6},
		{"a moment after them, which is the end", "2200-01-01T00:00:00Z", 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			id := "seeker-" + strings.Map(func(r rune) rune {
				if r == ' ' || r == ',' {
					return -1
				}
				return r
			}, tc.name)

			c := dial(t, h, id, false, false, 0, 3600, 0)
			c.Seek(t, "events", tc.payload)
			_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
			time.Sleep(100 * time.Millisecond)

			back := dial(t, h, id, false, false, 0, 3600, 0)
			back.Sub(t, "events/#", 1)
			// Long enough for a backlog to arrive, and long enough to be
			// sure an empty result is empty rather than early.
			time.Sleep(500 * time.Millisecond)
			if got := back.Count(); got != tc.want {
				t.Fatalf("after seeking to %q the consumer read %d record(s), want %d: %v",
					tc.payload, got, tc.want, back.Payloads())
			}
		})
	}
}

// A time older than the oldest surviving record has two causes, and only
// one of them is safe to answer. With the floor still at 1 nothing was
// ever removed, so serving from the start is a complete answer. Once
// retention has moved the floor, the records asked for are gone and the
// consumer is told rather than served the oldest survivor and left to
// report success over the gap (invariant 1).
func TestSeekingToATimeRetentionHasPassedIsRefused(t *testing.T) {
	h := startTrimming(t, map[string]int64{"events": 1})

	pub := connect(t, h, "publisher", true, false)
	for i := range 4 {
		pub.Pub(t, "events/trimmed", fmt.Sprintf("r%d", i))
	}
	// Long enough for the size sweep, which runs every second.
	time.Sleep(1500 * time.Millisecond)

	c := dial(t, h, "late-seeker", false, false, 0, 3600, 0)
	reply := c.Seek(t, "events", "-1h")
	if reply.Payload != "below-floor" {
		t.Fatalf("seeking to a time retention has passed answered %q, want below-floor", reply.Payload)
	}
	if reply.User["saguin-floor"] == "" {
		t.Error("the refusal carries no saguin-floor, so a consumer cannot tell how much it missed")
	}
}

// RFC 0003 "What a reconnecting consumer receives": a session resumed
// without a new SUBSCRIBE is served only the topics whose value changed
// while it was away.
//
// This is the reconnect a bad link produces, and the case a standard
// broker answers with nothing at all - leaving a client stale until it
// subscribes again - while sending everything costs a fleet with ten
// thousand state topics ten thousand messages every time the link blinks.
// The reason logged for an undelivered `latest` value has to be the reason
// it happened. There are four, and only writeLatest can tell them apart -
// the caller named one of them unconditionally, so a value refused for
// being larger than the subscriber's own Maximum Packet Size was reported
// as a slow consumer, on the line directly below the one that had just said
// otherwise. An operator reading the second line alone was sent to look at
// throughput for a bound they had set themselves.
func TestAnUndeliveredLatestValueLogsWhyItWasNotDelivered(t *testing.T) {
	t.Run("too large for the subscriber", func(t *testing.T) {
		var mu sync.Mutex
		var lines []string
		h := startLogging(t, func(s string) { mu.Lock(); lines = append(lines, s); mu.Unlock() })

		pub := connect(t, h, "publisher", true, false)
		// A Maximum Packet Size no value of this size can fit in.
		c := dial(t, h, "small", true, false, 0, 3600, 256)
		c.Sub(t, "state/#", 1)
		// The subscription's own work runs after its SUBACK; its next
		// packet is read once that returns, so this answer is the proof.
		settle(t, c)

		pub.Pub(t, "state/big", strings.Repeat("x", 4096))
		// The line is written by the subscriber's drain, on a goroutine of
		// its own: read the capture until it has one.
		waitUntil(5*time.Second, func() bool {
			mu.Lock()
			defer mu.Unlock()
			for _, l := range lines {
				if strings.Contains(l, "was not delivered") {
					return true
				}
			}
			return false
		})

		mu.Lock()
		defer mu.Unlock()
		var found bool
		for _, l := range lines {
			if !strings.Contains(l, "was not delivered") {
				continue
			}
			found = true
			if strings.Contains(l, "window is full") {
				t.Errorf("a value too large for the subscriber was logged as a full window: %s",
					strings.TrimSpace(l))
			}
			if !strings.Contains(l, "Maximum Packet Size") {
				t.Errorf("the line does not say why: %s", strings.TrimSpace(l))
			}
		}
		if !found {
			t.Fatal("nothing logged the undelivered value at all")
		}
	})

	// A full window is no longer one of the reasons: a live value that finds
	// it full waits for room and is sent when there is some, and nothing is
	// logged (TestALatestUpdateThatFindsTheWindowFullWaitsForRoom).
}

// awaitPending waits until n values wait in a subscriber's list for a
// channel: queued and not yet sent, which is what "it waited" means, read
// from the list rather than from a quiet moment on the wire.
func awaitPending(t *testing.T, h *harness, id, ch string, n int) {
	t.Helper()
	if !waitUntil(5*time.Second, func() bool { return broker.LatestPending(h.B, id, ch) == n }) {
		t.Fatalf("%d value(s) wait for %s on %q, want %d", broker.LatestPending(h.B, id, ch), id, ch, n)
	}
}

// throughMarkers publishes a marker on each topic and reads c until every
// marker has arrived, acknowledging as it goes, and answers the payloads c
// was sent before them, markers left out.
//
// **A marker per topic, never one for all.** A `latest` channel is ordered
// per topic and not across topics (RFC 0003 "Ordering"), so a topic's marker
// arriving says only that topic has nothing more on its way.
func throughMarkers(t *testing.T, c, pub *brokertest.Client, topics ...string) []string {
	t.Helper()
	var got []string
	for _, r := range receivedThroughMarkers(t, c, pub, topics...) {
		got = append(got, r.Payload)
	}
	return got
}

// receivedThroughMarkers is throughMarkers answering the deliveries whole.
func receivedThroughMarkers(t *testing.T, c, pub *brokertest.Client, topics ...string) []brokertest.Received {
	t.Helper()
	marks := map[string]bool{}
	for _, topic := range topics {
		m := "marker:" + topic
		marks[m] = true
		pub.Pub(t, topic, m)
	}
	acked := len(c.All()) // what came before the markers is the caller's to answer
	for deadline := time.Now().Add(5 * time.Second); ; time.Sleep(5 * time.Millisecond) {
		all := c.All()
		for _, r := range all[acked:] { // each once: an identifier is reused
			if r.Ack != nil {
				r.Ack()
			}
		}
		acked = len(all)
		var got []brokertest.Received
		seen := 0
		for _, r := range all {
			if marks[r.Payload] {
				seen++
				continue
			}
			got = append(got, r)
		}
		if seen >= len(marks) {
			return got
		}
		if time.Now().After(deadline) {
			t.Fatalf("%d of %d markers arrived; the subscriber was sent %v", seen, len(marks), c.Payloads())
		}
	}
}

// Current state that was still queued when a consumer went away is
// re-sent, rather than stepped over by the resume.
//
// A subscribe queues the whole of current state and drains it a window at
// a time. That queue is thrown away at the disconnect, and the resume mark
// was held back only by values the broker had *dropped* - so a value that
// was merely still waiting was undelivered and nothing knew it. (Now every
// value still waiting holds it back, live or snapshot; see forgetConsumer.) Whenever
// its offset was below what the consumer had already acknowledged, the
// resume stepped over it and the consumer held a view of current state
// with topics missing from it, permanently and in silence.
//
// The route here is what a client actually does: widen a subscription to a
// prefix whose topics were written earlier, so the newly matched values
// carry lower offsets than the ones already acknowledged. Receive Maximum
// 1 makes the drain stall after one value, which is what leaves the rest
// queued at the disconnect - the same state a slow consumer or a dropped
// link reaches by itself.
func TestStateStillQueuedWhenAConsumerLeavesIsResent(t *testing.T) {
	h := start(t)
	pub := connect(t, h, "publisher", true, false)

	// The older tree first, so it holds the lower offsets.
	for i := range 4 {
		pub.Pub(t, fmt.Sprintf("state/old/%d", i), "v")
	}
	for i := range 2 {
		pub.Pub(t, fmt.Sprintf("state/new/%d", i), "v")
	}
	// Each PUBACK follows its value's store, so current state holds all six.

	// One at a time through a window one wide, each acknowledged once it has
	// arrived, and the last acknowledgement taken by the broker before the
	// widening below - it is what puts the mark above the older tree.
	c := dial(t, h, "watcher", false, true, 1, 3600, 0)
	c.Sub(t, "state/new/#", 1)
	awaitCount(t, c, 1, 5*time.Second)
	ackAll(c)
	awaitCount(t, c, 2, 5*time.Second)
	ackAll(c)
	acknowledged(t, c)
	if got := len(c.All()); got != 2 {
		t.Fatalf("the first subscription received %d value(s), want 2 - the mark "+
			"has to be above the older tree for this test to be about anything", got)
	}

	// Widen it. This queues the whole of current state, whose lower offsets
	// are below what has just been acknowledged, and the window stalls the
	// drain after one.
	c.Sub(t, "state/old/#", 1)
	// The first of the older tree is sent and fills the window, so the
	// other three are queued behind it when the consumer leaves.
	awaitCount(t, c, 3, 5*time.Second)
	if got := len(c.All()); got != 3 {
		t.Fatalf("the widened subscription was sent %d value(s) through a window one wide, "+
			"want 3 - nothing would be left queued", got)
	}
	_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
	sessionGone(t, h, "watcher")

	back := dial(t, h, "watcher", false, false, 0, 3600, 0)

	// Read until every one of the older tree has been seen, or the deadline
	// says one never will be.
	var missing []string
	waitUntil(5*time.Second, func() bool {
		seen := map[string]bool{}
		for _, m := range append(c.All(), back.All()...) {
			seen[m.Topic] = true
		}
		missing = nil
		for i := range 4 {
			if topic := fmt.Sprintf("state/old/%d", i); !seen[topic] {
				missing = append(missing, topic)
			}
		}
		return len(missing) == 0
	})
	if len(missing) > 0 {
		t.Errorf("current state never delivered: %v - the resume stepped over values "+
			"that were still queued when the consumer left", missing)
	}
}

// RFC 0003: **a subscriber is promised the current value, not every
// intermediate one.** A live update that finds the subscriber's in-flight
// window full waits for room, and when room comes the subscriber is sent what
// is current then - a newer value for the same topic replaces a waiting one.
// It used to be dropped and recorded as missed, which kept a busy subscriber
// short of values it had room for a moment later.
//
// And a value still waiting when the consumer leaves is not stepped over by
// the resume: the position is the lowest offset not yet delivered, never the
// highest delivered, and a waiting value is undelivered (forgetConsumer).
//
// It needs Receive Maximum 1 and manual acknowledgement: with the default
// window nothing ever waits.
func TestALatestUpdateThatFindsTheWindowFullWaitsForRoom(t *testing.T) {
	t.Run("sent the newest value when room comes, and nothing said missed", func(t *testing.T) {
		var mu sync.Mutex
		var lines []string
		h := startLogging(t, func(s string) { mu.Lock(); lines = append(lines, s); mu.Unlock() })
		pub := connect(t, h, "publisher", true, false)
		c := dial(t, h, "slow", false, true, 1, 3600, 0)
		c.Sub(t, "state/#", 1)
		settle(t, c) // its subscription's own work has returned

		pub.Pub(t, "state/a", "a1")
		first, ok := c.Await(t, 3*time.Second)
		if !ok || first.Payload != "a1" {
			t.Fatalf("the subscriber never received a1: %v %q", ok, first.Payload)
		}
		// a1 is unacknowledged and the window is one wide, so these wait -
		// and a2 with them: a value in flight is not the current one once a
		// newer exists, so its acknowledgement covers nothing after it.
		pub.Pub(t, "state/b", "b1")
		pub.Pub(t, "state/b", "b2")
		pub.Pub(t, "state/a", "a2")
		// **Waiting, read from the subscriber's list**: b2 in b1's place and
		// a2 behind it. A quiet moment said only that nothing had arrived yet.
		awaitPending(t, h, "slow", "state", 2)
		if got := c.Count(); got != 1 {
			t.Fatalf("the subscriber holds %d values with a one-wide window full: %v - nothing "+
				"waited, so this test is not about what it says", got, c.Payloads())
		}

		first.Ack()
		next, ok := c.Await(t, 3*time.Second)
		if !ok {
			t.Fatal("room came and the waiting value was never sent")
		}
		if next.Payload != "b2" {
			t.Errorf("the subscriber was sent %q when room came, want b2: the current value, "+
				"not an intermediate one", next.Payload)
		}
		next.Ack()
		last, ok := c.Await(t, 3*time.Second)
		if !ok || last.Payload != "a2" {
			t.Errorf("after b2 the subscriber was sent %q (%v), want a2: a newer value for a "+
				"topic whose older one was in flight", last.Payload, ok)
		} else {
			last.Ack()
		}
		// A marker on each topic, after everything above: a topic's values
		// arrive in order (RFC 0003 "Ordering"), so anything still to come
		// on either arrives before its marker.
		got := throughMarkers(t, c, pub, "state/a", "state/b")
		if strings.Join(got, ",") != "a1,b2,a2" {
			t.Errorf("the subscriber was sent %v, want [a1 b2 a2]: each topic's current value, "+
				"in the order they were published, and nothing it replaced", got)
		}
		// b1 waited and b2 replaced it: one value this subscriber was never
		// sent, and the one thing that says so (RFC 0005).
		want := `saguin_latest_superseded_total{channel="state"} 1`
		if got := awaitScrape(t, h, `saguin_latest_superseded_total{channel="state"}`, 3*time.Second); got != want {
			t.Errorf("b1 was replaced by b2 while it waited, and the scrape says %q, want %q", got, want)
		}

		mu.Lock()
		defer mu.Unlock()
		// **The capture is proved before its silence is believed**: the
		// broker's own start-up line has to be in it, or "nothing said
		// missed" below is a capture that caught nothing.
		captured := false
		for _, l := range lines {
			if strings.Contains(l, "saguin mqtt engine started") {
				captured = true
			}
			if strings.Contains(l, "was not delivered") {
				t.Errorf("a value that waited for room and was delivered was logged as not "+
					"delivered: %s", strings.TrimSpace(l))
			}
		}
		if !captured {
			t.Errorf("the log capture caught %d lines and not the broker's start-up line, so "+
				"its silence about undelivered values says nothing", len(lines))
		}
	})

	t.Run("still waiting when a new connection takes the session over", func(t *testing.T) {
		h := start(t)
		pub := connect(t, h, "publisher", true, false)
		c := dial(t, h, "watcher", false, true, 1, 3600, 0)
		c.Sub(t, "state/#", 1)
		settle(t, c)

		pub.Pub(t, "state/a", "a1")
		if first, ok := c.Await(t, 3*time.Second); !ok || first.Payload != "a1" {
			t.Fatalf("the subscriber never received a1: %v %q", ok, first.Payload)
		}
		pub.Pub(t, "state/b", "b1") // waits: a1 fills the window
		awaitPending(t, h, "watcher", "state", 1)
		if got := c.Count(); got != 1 {
			t.Fatalf("the subscriber holds %d values: b1 did not wait, so this proves nothing", got)
		}

		// The same client id on a new connection, with the old one still
		// open: the session is taken over rather than resumed after a gap.
		back := dial(t, h, "watcher", false, false, 0, 3600, 0)
		if !waitUntil(3*time.Second, func() bool {
			for _, m := range back.All() {
				if m.Topic == "state/b" && m.Payload == "b1" {
					return true
				}
			}
			return false
		}) {
			t.Fatalf("the new connection was never sent b1, which was waiting on the old one: %v",
				back.Payloads())
		}
		// A second copy of b1 would arrive before state/b's marker, published
		// once the takeover's own work on back is done.
		settle(t, back)
		n := 0
		for _, p := range throughMarkers(t, back, pub, "state/b") {
			if p == "b1" {
				n++
			}
		}
		if n != 1 {
			t.Errorf("the new connection was sent state/b %d times, want once: %v", n, back.Payloads())
		}
	})

	t.Run("still waiting when another subscription's state is queued", func(t *testing.T) {
		// A second SUBSCRIBE queues its own current state for the same
		// channel, and must add it to what is waiting rather than put it in
		// its place - a live value waiting there is in neither the new
		// filter's state nor anywhere else.
		h := start(t)
		pub := connect(t, h, "publisher", true, false)
		pub.Pub(t, "state/other/1", "z1")
		c := dial(t, h, "watcher", false, true, 1, 3600, 0)
		c.Sub(t, "state/a/#", 1)
		settle(t, c)

		pub.Pub(t, "state/a/1", "x1")
		first, ok := c.Await(t, 3*time.Second)
		if !ok || first.Payload != "x1" {
			t.Fatalf("the subscriber never received x1: %v %q", ok, first.Payload)
		}
		pub.Pub(t, "state/a/2", "y1") // waits: x1 fills the window
		awaitPending(t, h, "watcher", "state", 1)
		if got := c.Count(); got != 1 {
			t.Fatalf("the subscriber holds %d values: y1 did not wait, so this proves nothing", got)
		}
		c.Sub(t, "state/other/#", 1) // its state, z1, joins y1 in the list
		awaitPending(t, h, "watcher", "state", 2)

		first.Ack()
		if !waitUntil(3*time.Second, func() bool {
			ackAll(c)
			got := map[string]bool{}
			for _, m := range c.All() {
				got[m.Payload] = true
			}
			return got["y1"] && got["z1"]
		}) {
			t.Errorf("the subscriber was sent %v, want y1 and z1 after x1: a waiting live value "+
				"was dropped when another subscription's state was queued", c.Payloads())
		}
	})

	t.Run("still waiting when the consumer leaves, re-sent on resume", func(t *testing.T) {
		h := start(t)
		pub := connect(t, h, "publisher", true, false)
		c := dial(t, h, "watcher", false, true, 1, 3600, 0)
		c.Sub(t, "state/#", 1)
		settle(t, c)

		pub.Pub(t, "state/a", "a1")
		if first, ok := c.Await(t, 3*time.Second); !ok || first.Payload != "a1" {
			t.Fatalf("the subscriber never received a1: %v %q", ok, first.Payload)
		}
		pub.Pub(t, "state/b", "b1") // waits: a1 fills the window
		awaitPending(t, h, "watcher", "state", 1)
		if got := c.Count(); got != 1 {
			t.Fatalf("the subscriber holds %d values: b1 did not wait, so this proves nothing", got)
		}

		// Gone without acknowledging anything, on a durable session.
		_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
		sessionGone(t, h, "watcher")

		back := dial(t, h, "watcher", false, false, 0, 3600, 0)
		if !waitUntil(3*time.Second, func() bool {
			for _, m := range back.All() {
				if m.Topic == "state/b" && m.Payload == "b1" {
					return true
				}
			}
			return false
		}) {
			t.Errorf("the resume did not carry state/b, which was waiting when the consumer "+
				"left and never delivered: %v", back.Payloads())
		}
	})
}

// A value published between a subscription entering the index and its current
// state being read reaches the subscriber both ways - live, because the
// subscription already matches, and in the state, because it is current - and
// what the subscriber must end holding is that value, never an older one
// after it, and never nothing.
//
// **Twice is the honest answer, and it is not new.** The state a new
// subscription is owed includes values below anything it has been sent, so
// no position can tell a value already sent live from one it is owed as
// state; only a value still waiting is merged rather than queued again
// (enqueueLatest). The second copy carries RETAIN - saguin saying "this
// is current state" - and is the same value. What this test rules out is the
// failure that matters: the live value lost because the state was read before
// it and the list holding it was replaced, which is what deliverLatest did
// before its state was merged into the list instead.
func TestALiveValueRacingASubscriptionsStateIsNeitherLostNorStale(t *testing.T) {
	h := start(t)
	pub := connect(t, h, "publisher", true, false)
	pub.Pub(t, "state/x", "v1") // stored before its PUBACK, so current state holds it

	sub := connect(t, h, "reader", true, false)
	var once sync.Once
	raced := make(chan string, 1)
	restore := broker.SetLatestBeforeState(func(id string) {
		if id != "reader" {
			return
		}
		once.Do(func() {
			// From a goroutine, and waited for: this runs on the reader's
			// SUBSCRIBE, where a failing helper's t.Fatal would end the
			// wrong goroutine.
			done := make(chan struct{})
			go func() { pub.Pub(t, "state/x", "v2"); close(done) }()
			select {
			case <-done:
			case <-time.After(3 * time.Second):
				raced <- "v2 was never acknowledged"
				return
			}
			if !waitUntil(3*time.Second, func() bool { return sub.Count() > 0 }) {
				raced <- "v2 was not delivered live before the state was read"
				return
			}
			raced <- ""
		})
	})
	t.Cleanup(restore)

	sub.Sub(t, "state/#", 1)
	select {
	case why := <-raced:
		if why != "" {
			t.Fatalf("the race was not built: %s", why)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the seam never ran for the reader, so no live value met its state")
	}

	// The state is merged on the SUBSCRIBE's own read loop, so sub's next
	// packet is answered once that is done; the live copy and the state's
	// are then both before a marker published on the same topic, and so is
	// a stale v1 if one is coming.
	settle(t, sub)
	got := receivedThroughMarkers(t, sub, pub, "state/x")
	if len(got) == 0 {
		t.Fatal("the reader received nothing: the live value was lost and the state never served")
	}
	for i, m := range got {
		if m.Payload != "v2" {
			t.Errorf("delivery %d of %d was %q, want v2 every time: v1 had been replaced before "+
				"the reader subscribed - %v", i+1, len(got), m.Payload, sub.Payloads())
		}
	}
	if len(got) > 2 {
		t.Errorf("v2 was delivered %d times, want at most twice (live, then as state): %v",
			len(got), sub.Payloads())
	}
	t.Logf("v2 delivered %d time(s); retain flags %v", len(got), func() []bool {
		var r []bool
		for _, m := range got {
			r = append(r, m.Retain)
		}
		return r
	}())
}

// Every subscriber ends holding every topic's current value, however its
// deliveries raced its publishers. **The drain's claim is what is under test**:
// a value queued, or a window slot freed, while a subscriber's drain is
// running has to be noticed before the drain lets go, or it waits with nobody
// to send it - for good, once the publishers stop. Eight publishers, each on
// topics of its own so that no two write one topic (that race is scenario 23,
// not this), against one subscriber whose small window keeps values waiting.
// Repeated, since the interleaving is the scheduler's.
func TestALatestSubscriberSettlesOnEveryTopicsCurrentValue(t *testing.T) {
	for trial := 0; trial < 3; trial++ {
		h := start(t)
		reader := dial(t, h, fmt.Sprintf("reader-%d", trial), true, false, 2, 3600, 0)
		reader.Sub(t, "state/#", 1)
		settle(t, reader) // its subscription's own work has returned

		const pubs, topics, each = 8, 4, 60
		want := map[string]string{}
		var wg sync.WaitGroup
		var mu sync.Mutex
		for p := 0; p < pubs; p++ {
			pc := connect(t, h, fmt.Sprintf("pub-%d-%d", trial, p), true, false)
			wg.Add(1)
			go func(p int, pc *brokertest.Client) {
				defer wg.Done()
				for i := 0; i < each; i++ {
					topic := fmt.Sprintf("state/p%d/t%d", p, i%topics)
					val := fmt.Sprintf("p%d-%d", p, i)
					if _, err := pc.C.Publish(context.Background(), &paho.Publish{
						Topic: topic, QoS: 1, Payload: []byte(val),
					}); err != nil {
						t.Errorf("publish %s: %v", topic, err)
						return
					}
					mu.Lock()
					want[topic] = val
					mu.Unlock()
				}
			}(p, pc)
		}
		wg.Wait()

		holds := func() map[string]string {
			got := map[string]string{}
			for _, m := range reader.All() {
				got[m.Topic] = m.Payload
			}
			return got
		}
		settled := waitUntil(5*time.Second, func() bool {
			got := holds()
			for topic, val := range want {
				if got[topic] != val {
					return false
				}
			}
			return true
		})
		if !settled {
			got := holds()
			var stale []string
			for topic, val := range want {
				if got[topic] != val {
					stale = append(stale, fmt.Sprintf("%s: holds %q, current %q", topic, got[topic], val))
				}
			}
			sort.Strings(stale)
			t.Fatalf("trial %d: the reader never settled on current state, %d of %d topics "+
				"stale: %v", trial, len(stale), len(want), stale)
		}
		if len(want) != pubs*topics {
			t.Fatalf("trial %d: %d topics were published, want %d - the case is not the one "+
				"this test describes", trial, len(want), pubs*topics)
		}
	}
}

func TestAResumedSessionReceivesOnlyWhatChanged(t *testing.T) {
	h := start(t)

	pub := connect(t, h, "publisher", true, false)
	for _, topic := range []string{"state/a", "state/b", "state/c"} {
		pub.Pub(t, topic, "first")
	}

	// A durable consumer takes the lot on its first subscribe.
	c := dial(t, h, "watcher", false, false, 0, 3600, 0)
	c.Sub(t, "state/#", 1)
	awaitCount(t, c, 3, 5*time.Second)
	if got := c.Count(); got != 3 {
		t.Fatalf("a new subscription received %d value(s), want the whole of current state (3): %v",
			got, c.Payloads())
	}
	// **Away once the broker has its acknowledgements**, not once the client
	// has the values: the client acknowledges after its handler returns, so a
	// DISCONNECT sent the moment they arrive can reach the broker first, and
	// the values it never saw acknowledged are rightly sent again on resume.
	eventually(t, "the watcher's acknowledgements to reach the broker", 5*time.Second, func() bool {
		cl, ok := h.Srv.Clients.Get("watcher")
		return ok && cl.State.Inflight.Len() == 0
	})
	away := h.Disconnects.Snapshot("watcher")
	_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
	sessionGoneAfter(t, h, "watcher", away)

	// One topic changes while it is away; the other two do not.
	pub.Pub(t, "state/b", "second")

	// Back, on the same session, without subscribing again. A marker on
	// every topic says what the resume sent is all there is.
	// The resume's state is queued as the session is established, before
	// back's first packet is read, so the settle's answer follows it; a
	// marker published earlier would be newer than what the resume reads,
	// and rightly overtake it.
	back := dial(t, h, "watcher", false, false, 0, 3600, 0)
	settle(t, back)
	got := throughMarkers(t, back, pub, "state/a", "state/b", "state/c")
	if len(got) != 1 {
		t.Fatalf("a resumed session received %d value(s), want only the one that changed: %v",
			len(got), got)
	}
	if got[0] != "second" {
		t.Errorf("received %q, want the changed value \"second\"", got[0])
	}
}

// The other half of the same rule: subscribing again is how a client asks
// for the whole of current state, and it must still get it. A client that
// clears its own cache and rebuilds from what arrives depends on this, and
// it is the escape from the one hole a delta leaves - a topic deleted
// while the consumer was away has nothing left to send.
func TestSubscribingAgainStillDeliversEverything(t *testing.T) {
	h := start(t)

	pub := connect(t, h, "publisher", true, false)
	for _, topic := range []string{"state/a", "state/b"} {
		pub.Pub(t, topic, "first")
	}

	c := dial(t, h, "rebuilder", false, false, 0, 3600, 0)
	c.Sub(t, "state/#", 1)
	awaitCount(t, c, 2, 5*time.Second)
	if got := c.Count(); got != 2 {
		t.Fatalf("first subscribe received %d, want 2", got)
	}
	acknowledged(t, c)
	away := h.Disconnects.Snapshot("rebuilder")
	_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
	sessionGoneAfter(t, h, "rebuilder", away)

	back := dial(t, h, "rebuilder", false, false, 0, 3600, 0)
	back.Sub(t, "state/#", 1)
	settle(t, back) // the SUBSCRIBE's state is queued before its next packet is read
	if got := throughMarkers(t, back, pub, "state/a", "state/b"); len(got) != 2 {
		t.Fatalf("re-subscribing received %d value(s), want the whole of current state (2): %v",
			len(got), got)
	}
}

// Invariant 13: a `latest` channel's position outlives a disconnect on
// purpose, so the only thing that can clear it for a session that never
// returns is the server giving up on that session.
//
// Without the hook this holds one map per client id that ever read a
// latest channel, for the life of the process - bounded by the number of
// client ids a fleet has ever used, which is not a bound.
func TestALatestPositionGoesWithAnExpiredSession(t *testing.T) {
	h := start(t)

	pub := connect(t, h, "publisher", true, false)
	pub.Pub(t, "state/x", "v") // stored before its PUBACK

	// A durable session with the shortest expiry MQTT can express.
	c := dial(t, h, "brief", false, false, 0, 1, 0)
	c.Sub(t, "state/#", 1)
	if _, ok := c.Await(t, 2*time.Second); !ok {
		t.Fatal("no current state")
	}
	// The position moves on the acknowledgement, which the client sends
	// after its handler returns: held once the broker has read it.
	waitUntil(5*time.Second, func() bool { return h.B.LatestPositionsHeld() == 1 })
	if got := h.B.LatestPositionsHeld(); got != 1 {
		t.Fatalf("the broker holds %d latest position(s) while the session is live, want 1", got)
	}
	_ = c.C.Disconnect(&paho.Disconnect{ReasonCode: 0})

	// The server sweeps expired sessions on its own clock, once a second.
	deadline := time.Now().Add(6 * time.Second)
	for time.Now().Before(deadline) {
		if h.B.LatestPositionsHeld() == 0 {
			return
		}
		time.Sleep(200 * time.Millisecond)
	}
	t.Fatalf("the position is still held %v after the session expired, so nothing ever clears it",
		time.Since(deadline))
}

// RFC 0002 "Configuration - `limits`" - invariant 13
//
// A client asking to keep its session for longer than `max_session_expiry`
// is given the cap, and told so in the CONNACK.
//
// What it bounds is durable state an anonymous client chooses the size of.
// A durable consumer's position is keyed by its client id and outlives the
// connection for as long as the session does, so a client asking for
// 0xFFFFFFFF - about 136 years, and the substrate's own default - leaves a
// row nothing ever removes. That is the shape saguin already refused twice,
// for Topic Alias and for the client id, and this is the only one of the
// three whose state is written to a store.
//
// Raw bytes rather than Paho, and reading the CONNACK rather than trusting
// the capability: a client library hands back a struct where a field
// holding zero cannot be told from a property that was never sent, and
// "never sent" is exactly what this used to be. MQTT reads an absent
// Session Expiry Interval in a CONNACK as "you got what you asked for", so
// silence here is the wrong answer rather than no answer.
func TestASessionExpiryAboveTheCapIsShortenedAndSaidSo(t *testing.T) {
	h := start(t)

	// Session Expiry Interval (0x11), 0xFFFFFFFF.
	asking := []byte{0x11, 0xFF, 0xFF, 0xFF, 0xFF}
	props, shown := connackPropertiesAsking(t, h.Addr, "expiry-capped", asking)

	got, ok := props[0x11]
	if !ok {
		t.Fatalf("the CONNACK carries no Session Expiry Interval (0x11), which MQTT "+
			"reads as the 136 years the client asked for: %s", shown)
	}
	want := limits.MaxSessionExpiry
	if len(got) != 4 || binary.BigEndian.Uint32(got) != want {
		t.Fatalf("Session Expiry Interval is % 02x, want %d seconds: %s", got, want, shown)
	}
}

// The other half, and it is what keeps the cap from being a blunt override:
// a client asking for less than the cap is given what it asked for.
//
// MQTT only requires the server to say something when it shortens the
// value, so an unchanged one may be answered with silence - which is why
// this asserts "not shortened" rather than a property being present.
func TestASessionExpiryBelowTheCapIsLeftAlone(t *testing.T) {
	h := start(t)

	// Session Expiry Interval (0x11), one hour.
	asking := []byte{0x11, 0x00, 0x00, 0x0E, 0x10}
	props, shown := connackPropertiesAsking(t, h.Addr, "expiry-untouched", asking)

	if got, ok := props[0x11]; ok && binary.BigEndian.Uint32(got) != 3600 {
		t.Fatalf("a client asking for an hour was answered % 02x, so the cap is "+
			"overriding rather than bounding: %s", got, shown)
	}
}

// RFC 0002 `retry.backoff` - RFC 0003 "`queue` - Acknowledgement and return"
//
// **The wiring, which is the half no store test can reach.** Both stores are
// held to the gap by the conformance tests beside them, driven by calling
// Offer directly. What those cannot see is whether the configured policy
// ever arrives at the store: with the call that applies it removed, every
// one of them still passes and a real broker offers a returned job on the
// next tick as though the keys had never been written.
//
// So this is measured on the wire, through a worker that returns a job and
// waits for it to come back. Two seconds of gap against a 200ms tick, which
// is far enough apart that the tick cannot be mistaken for the gap.
func TestAReturnedJobWaitsForItsBackoffBeforeItIsOfferedAgain(t *testing.T) {
	h := startBackingOff(t, store.Backoff{Kind: store.BackoffLinear, Base: 2 * time.Second})
	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/flaky", "job-1")

	first, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("no first delivery")
	}
	if first.User["saguin-attempt"] != "1" {
		t.Fatalf("first delivery says attempt %q, want 1", first.User["saguin-attempt"])
	}

	// Hand it straight back. Without a backoff this returns in about 199ms,
	// which was measured before this feature existed and is what it exists to
	// change.
	returned := time.Now()
	w.Respond(t, first.RespTopic, "return", first.CorrData)

	second, ok := w.Await(t, 8*time.Second)
	if !ok {
		t.Fatal("the returned job was never offered again")
	}
	waited := time.Since(returned)

	// The gap, less one tick of slack: the job becomes available at two
	// seconds and is offered on the next 200ms tick, so the arrival is at or
	// after the gap and never before it. Asserting the lower bound is the
	// whole test - an upper bound would be asserting on the scheduler.
	if waited < 2*time.Second-200*time.Millisecond {
		t.Fatalf("the job came back %v after it was returned, want at least the 2s backoff: "+
			"the configured policy is not reaching the queue's store", waited)
	}
	if second.User["saguin-attempt"] != "2" {
		t.Fatalf("the redelivery says attempt %q, want 2", second.User["saguin-attempt"])
	}
	if string(second.CorrData) == string(first.CorrData) {
		t.Fatal("the redelivery reused the Delivery ID (invariant 3)")
	}
}

// RFC 0003 "Reading one value"
//
// A `latest` channel is a key-value store, and this is the read that does
// not make the caller a subscriber. SET is an ordinary publish and DELETE is
// a publish with a zero-length payload; both are exercised here because the
// point of a GET is to answer about what they did.
func TestAPointReadAnswersTheCurrentValue(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "kv-reply", 1)

	p.Pub(t, "state/tank/1/level", "72")
	p.Pub(t, "state/tank/2/level", "13")
	time.Sleep(200 * time.Millisecond)

	if got := string(c.KvGet(t, "state/tank/1/level", nil).Payload); got != "72" {
		t.Errorf("reading state/tank/1/level gave %q, want 72", got)
	}

	// The current value rather than the first: a read that answered with a
	// superseded value would be worse than no read at all.
	p.Pub(t, "state/tank/1/level", "80")
	time.Sleep(200 * time.Millisecond)
	if got := string(c.KvGet(t, "state/tank/1/level", nil).Payload); got != "80" {
		t.Errorf("after an update the read gave %q, want 80", got)
	}

	// And it answers about the topic asked for, not whichever one the store
	// reaches first.
	if got := string(c.KvGet(t, "state/tank/2/level", nil).Payload); got != "13" {
		t.Errorf("reading state/tank/2/level gave %q, want 13", got)
	}

	// Reading does not enrol the caller in later updates, which is the whole
	// reason the verb exists. Nothing new must arrive on the reply topic.
	p.Pub(t, "state/tank/1/level", "99")
	if r, ok := c.Await(t, time.Second); ok {
		t.Errorf("a point read left the caller subscribed: %q arrived on %q", r.Payload, r.Topic)
	}
}

// RFC 0003 "Reading one value"
//
// Every reply carries Correlation Data: the caller's when it set some, and
// otherwise the key it asked about. A client with several reads outstanding
// can tell the answers apart without keeping a table of its own, and one
// that wants its own bookkeeping still has it.
func TestAPointReadAlwaysSaysWhatItIsAnswering(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "kv-reply", 1)

	p.Pub(t, "state/tank/1/level", "72")
	time.Sleep(200 * time.Millisecond)

	if got := string(c.KvGet(t, "state/tank/1/level", nil).CorrData); got != "state/tank/1/level" {
		t.Errorf("a read that set no Correlation Data was answered with %q, want the key", got)
	}
	if got := string(c.KvGet(t, "state/tank/1/level", []byte("mine-7")).CorrData); got != "mine-7" {
		t.Errorf("a read that set Correlation Data was answered with %q, want mine-7", got)
	}
}

// RFC 0003 "Reading one value", invariant 1's shape at the key-value level
//
// An empty reply means there is no value, and that is the distinction the
// verb exists to make: subscribing to ask answers an absent key with silence,
// which is indistinguishable from a slow one.
//
// Never-set and deleted are the same answer, deliberately. A `latest` channel
// keeps one value per topic and a zero-length payload is how MQTT already
// says "gone", so absence needs no new vocabulary here.
func TestAPointReadSaysWhenThereIsNoValue(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "kv-reply", 1)

	p.Pub(t, "state/tank/1/level", "72")
	time.Sleep(200 * time.Millisecond)

	if got := c.KvGet(t, "state/tank/9/level", nil); len(got.Payload) != 0 {
		t.Errorf("a topic nobody has published to answered %q, want an empty payload", got.Payload)
	}

	// Deleted, MQTT's own way: a publish with a zero-length payload.
	p.Pub(t, "state/tank/1/level", "")
	time.Sleep(200 * time.Millisecond)
	if got := c.KvGet(t, "state/tank/1/level", nil); len(got.Payload) != 0 {
		t.Errorf("a deleted topic answered %q, want an empty payload", got.Payload)
	}
}

// RFC 0003 "Reading one value"
//
// **Everything wrong with the request is a refused PUBACK.** The Response
// Topic only ever carries an answer, which is what keeps an empty reply
// meaning exactly one thing.
//
// The two codes are split by what is wrong rather than by where the check
// sits, because the code is what `saguin_publish_refused_total` carries:
// 0x83 says the request cannot be acted on, 0x90 says the key is not a topic
// this broker holds a value for.
func TestAPointReadRefusesWhatItCannotAnswer(t *testing.T) {
	h := start(t)

	// Two clients, because no one client can see both halves. MQTT-3.1.2-29
	// lets a server withhold the Reason String from a client that did not
	// set Request Problem Information, and Paho does not set it by default -
	// so the sentence is only visible to `asking`. The wrapper client is the
	// one that can watch the reply topic and prove nothing arrived on it.
	asking := connectAsking(t, h, "asker")
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "kv-reply", 1)

	for _, tc := range []struct {
		name, key string
		respTopic string
		want      byte
		reason    string
	}{
		{"no response topic", "state/tank/1/level", "", 0x83, "needs a Response Topic"},
		{"no key at all", "", "kv-reply", 0x83, "it is empty"},
		{"a wildcard key", "state/tank/+/level", "kv-reply", 0x90, "no wildcard"},
		{"a key in the reserved space", "$saguin/kv/get", "kv-reply", 0x90, "reserved topic space"},
		{"a key in the $SYS tree", "$SYS/broker/version", "kv-reply", 0x90, "reserved topic space"},
		{"a topic no channel claims", "nowhere/at/all", "kv-reply", 0x90, "claimed by no channel"},
		{"an append channel", "events/order/1", "kv-reply", 0x90, "which is an append channel"},
		{"a queue", "jobs/work/1", "kv-reply", 0x90, "which is a queue"},
		// Past limits.max_topic_length, which bounds a key as it bounds any
		// topic: the harness sets 1,024.
		{"a key longer than max_topic_length", "state/" + strings.Repeat("k", 1024), "kv-reply", 0x90, "longer than max_topic_length"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			props := &paho.PublishProperties{}
			if tc.respTopic != "" {
				props.ResponseTopic = tc.respTopic
			}
			req := &paho.Publish{
				Topic: channelKVGet, QoS: 1, Payload: []byte(tc.key), Properties: props,
			}

			ack, err := asking.Publish(context.Background(), req)
			if ack == nil {
				t.Fatalf("no PUBACK: %v", err)
			}
			if ack.ReasonCode != tc.want {
				t.Fatalf("answered 0x%02X, want 0x%02X: %s", ack.ReasonCode, tc.want, ackReason(ack))
			}
			if got := ackReason(ack); !strings.Contains(got, tc.reason) {
				t.Errorf("the reason string was %q, which does not say %q", got, tc.reason)
			}

			// And nothing reached the reply topic, so an empty reply still
			// means exactly one thing. Asked again from the client that is
			// subscribed to it, because the one above cannot watch it.
			// The error here is the refusal itself - Paho reports a
			// non-zero PUBACK as one - and it is the outcome already
			// asserted above. What is being watched for is the reply topic.
			_, _ = c.C.Publish(context.Background(), req)
			if r, ok := c.Await(t, 500*time.Millisecond); ok {
				t.Errorf("a refused read answered on the response topic too: %q", r.Payload)
			}
		})
	}
}

// RFC 0003 "Reading one value"
//
// A point read published at QoS 0 is dropped. There is no PUBACK to carry a
// refusal, so accepting it would leave every mistake in the request answered
// by silence - which is also what "there is no value" looks like.
func TestAPointReadAtQoS0IsDropped(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "reader", true, false)
	c.Sub(t, "kv-reply", 1)

	p.Pub(t, "state/tank/1/level", "72")
	time.Sleep(200 * time.Millisecond)

	if _, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: channelKVGet, QoS: 0, Payload: []byte("state/tank/1/level"),
		Properties: &paho.PublishProperties{ResponseTopic: "kv-reply"},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	if r, ok := c.Await(t, time.Second); ok {
		t.Errorf("a QoS 0 point read was answered with %q; it has no PUBACK to be refused in", r.Payload)
	}

	// The same read at QoS 1 works, so the test above is about the QoS and
	// not about the request being wrong in some other way.
	if got := string(c.KvGet(t, "state/tank/1/level", nil).Payload); got != "72" {
		t.Errorf("the same read at QoS 1 gave %q, want 72", got)
	}
}

// RFC 0003 "Reading one value"
//
// The reply goes to the session that asked and to nobody else. It looks like
// an ordinary publish and is not: it is written to the asking connection, so
// the asker needs no subscription to its own response topic, and a third
// party subscribed to that topic is told nothing.
//
// **This needs a test of its own because the obvious one cannot see it.** A
// client that both asks and subscribes to the reply topic passes whichever
// way the broker sends the answer, and every other test in this file is that
// client. What the gap costs is not hypothetical: it produced a README
// example telling the reader to listen on the reply topic in a second
// terminal, where nothing would ever have arrived.
func TestAPointReadAnswersOnlyTheSessionThatAsked(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "state/tank/1/level", "72")
	time.Sleep(200 * time.Millisecond)

	// Subscribed to the reply topic, and not the one asking.
	listener := connect(t, h, "listener", true, false)
	listener.Sub(t, "kv-reply", 1)

	// Asking, and deliberately not subscribed to its own response topic.
	asker := connect(t, h, "asker", true, false)
	ack, err := asker.C.Publish(context.Background(), &paho.Publish{
		Topic: channelKVGet, QoS: 1, Payload: []byte("state/tank/1/level"),
		Properties: &paho.PublishProperties{ResponseTopic: "kv-reply"},
	})
	if ack == nil || ack.ReasonCode != 0 {
		t.Fatalf("the read was not accepted: %v %v", ack, err)
	}

	r, ok := asker.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the asking session received no reply, though it is the one the " +
			"answer is written to - a subscription to the response topic is not " +
			"needed and must not be")
	}
	if string(r.Payload) != "72" {
		t.Errorf("the asking session got %q, want 72", r.Payload)
	}

	if r, ok := listener.Await(t, time.Second); ok {
		t.Errorf("a third party subscribed to the response topic received %q: a "+
			"point read is one client's question, and broadcasting the answer "+
			"tells everyone else what somebody is reading", r.Payload)
	}
}

// RFC 0002 `broker.mqtt.password_file` and `broker.mqtt.allow_anonymous`.
//
// **`client_ids:` reaches the door, which is the only place it can.**
// authz has this as a unit test; a user name and a client id are two
// strings in one CONNECT packet and this is the rule that ties them
// together, so it has to hold over a socket rather than in a function
// (invariant 10).
//
// The shape is the one an operator writes: a cohort of devices sharing one
// credential, each with its own client id, and a pattern saying which ids
// that credential may carry. What it buys is the boundary *between*
// cohorts - a device holding the northern password cannot connect as a
// southern one. Inside a cohort it buys nothing and cannot, because those
// devices share a secret and are therefore one principal.
//
// **The last case is the one that stops this passing for the wrong
// reason.** A broker refusing every connection satisfies the refusals
// above on its own, and an earlier ACL test here measured exactly nothing
// that way.
func TestTheACLFilesClientIDsReachTheDoor(t *testing.T) {
	h := start(t)

	path := filepath.Join(t.TempDir(), "clients.passwd")
	pf := passwd.New(path)
	for _, u := range []string{"cohort-north", "device-7"} {
		if err := pf.Set(u, "hunter2"); err != nil {
			t.Fatalf("set %s: %v", u, err)
		}
	}
	if err := pf.Save(); err != nil {
		t.Fatalf("save: %v", err)
	}
	users, err := passwd.Load(path)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	h.B.SetCredentials(users, false)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  sensor:
    - topic: "loose/#"
      allow: [write, read]
users:
  "cohort-north":
    roles: [sensor]
    client_ids: "north-*"
  "device-*":
    roles: [sensor]
    client_ids: "%u"
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	const badCredential = 0x86 // ErrBadUsernameOrPassword

	for _, tc := range []struct {
		name, id, user, password string
		want                     byte
	}{
		{"a device inside the cohort", "north-17", "cohort-north", "hunter2", 0x00},
		{"another, further along the fleet", "north-204", "cohort-north", "hunter2", 0x00},
		{"the northern credential carrying a southern id", "south-3", "cohort-north", "hunter2", badCredential},
		{"%u: connecting under the name it logged in as", "device-7", "device-7", "hunter2", 0x00},
		{"%u: and not under another device's", "device-8", "device-7", "hunter2", badCredential},
		// The right client id and a wrong password: both checks are live,
		// and they answer the same code on purpose - saying which of the
		// two failed would tell an unauthenticated caller that the
		// credential is good.
		{"the right id and a wrong password", "north-17", "cohort-north", "hunter3", badCredential},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := connectAs(t, h, tc.id, tc.user, tc.password); got != tc.want {
				t.Errorf("client id %q as %q answered 0x%02X, want 0x%02X",
					tc.id, tc.user, got, tc.want)
			}
		})
	}
}

// **A wrong credential and a missing one get the same code**, 0x86, on
// purpose: distinguishing them tells an unauthenticated caller which user
// names exist.
func TestAClientAuthenticatesAgainstThePasswordFile(t *testing.T) {
	h := start(t)

	path := filepath.Join(t.TempDir(), "clients.passwd")
	pf := passwd.New(path)
	if err := pf.Set("device-7", "hunter2"); err != nil {
		t.Fatalf("set: %v", err)
	}
	if err := pf.Save(); err != nil {
		t.Fatalf("save: %v", err)
	}
	users, err := passwd.Load(path)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	const badCredential = 0x86 // ErrBadUsernameOrPassword

	t.Run("a password file, and anonymous refused", func(t *testing.T) {
		h.B.SetCredentials(users, false)

		if got := connectAs(t, h, "right", "device-7", "hunter2"); got != 0 {
			t.Errorf("the right credential was refused with 0x%02X", got)
		}
		for _, tc := range []struct{ name, user, password string }{
			{"the wrong password", "device-7", "hunter3"},
			{"a user the file does not have", "device-8", "hunter2"},
			{"no credential at all", "", ""},
			{"a user name and no password", "device-7", ""},
		} {
			if got := connectAs(t, h, "wrong", tc.user, tc.password); got != badCredential {
				t.Errorf("%s answered 0x%02X, want 0x86", tc.name, got)
			}
		}
	})

	// Mosquitto's mixed mode: the file names some clients and the rest are
	// let in anyway. It is a real deployment - a fleet migrating one batch
	// at a time - and it is why allow_anonymous is a key rather than a
	// property of whether the file exists.
	t.Run("a password file, and anonymous allowed", func(t *testing.T) {
		h.B.SetCredentials(users, true)

		if got := connectAs(t, h, "anon", "", ""); got != 0 {
			t.Errorf("an anonymous client was refused 0x%02X while anonymous connections "+
				"are allowed", got)
		}
		if got := connectAs(t, h, "right", "device-7", "hunter2"); got != 0 {
			t.Errorf("a named client was refused 0x%02X", got)
		}
		// A named client with the wrong password is still refused: allowing
		// anonymous connections is not "ignore the file".
		if got := connectAs(t, h, "wrong", "device-7", "hunter3"); got != badCredential {
			t.Errorf("a wrong password answered 0x%02X while anonymous connections are "+
				"allowed, so the file is being ignored rather than added to", got)
		}
	})

	t.Run("no password file at all", func(t *testing.T) {
		h.B.SetCredentials(nil, true)
		if got := connectAs(t, h, "anon", "", ""); got != 0 {
			t.Errorf("a broker with no password file refused a client 0x%02X", got)
		}
		// A client that offers a credential to a broker with nothing to
		// check it against is admitted, which is what Mosquitto does.
		if got := connectAs(t, h, "named", "device-7", "hunter2"); got != 0 {
			t.Errorf("a client offering a credential to a broker with no password file "+
				"was refused 0x%02X", got)
		}
	})
}

// RFC 0002 `broker.mqtt.listen.tcp.tls`: the MQTT listener serves TLS.
//
// **Driven through a real handshake with Paho**, because the whole point is
// what a client can verify. A configuration that parsed and a listener that
// answers are different claims, and the second is the feature.
func TestTheMQTTListenerServesTLS(t *testing.T) {
	certFile, keyFile, pool := selfSigned(t, "localhost")
	pair, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	reg, err := channel.NewRegistry([]*channel.Channel{
		{Name: "events", Type: channel.Append},
	})
	if err != nil {
		t.Fatalf("registry: %v", err)
	}
	srv, b, err := broker.NewServer(reg, config.Limits{}.Resolve(),
		slog.New(slog.NewTextHandler(io.Discard, nil)))
	if err != nil {
		t.Fatalf("server: %v", err)
	}
	tcp := listeners.NewTCP(listeners.Config{
		ID: "tls", Address: "127.0.0.1:0",
		TLSConfig: &tls.Config{Certificates: []tls.Certificate{pair}, MinVersion: tls.VersionTLS12},
	})
	if err := srv.AddListener(tcp); err != nil {
		t.Fatalf("add listener: %v", err)
	}
	addr := tcp.Address()
	go func() { _ = srv.Serve() }()
	t.Cleanup(func() { _ = srv.Close(); b.Stop() })

	// A client that knows the certificate connects, publishes, and the
	// record lands in the channel - the ordinary path, over TLS.
	conn, err := tls.Dial("tcp", addr, &tls.Config{RootCAs: pool, MinVersion: tls.VersionTLS12})
	if err != nil {
		t.Fatalf("tls dial: %v", err)
	}
	defer conn.Close()
	if v := conn.ConnectionState().Version; v < tls.VersionTLS12 {
		t.Errorf("negotiated TLS 0x%04X, below the 1.2 floor", v)
	}

	c := paho.NewClient(paho.ClientConfig{Conn: conn})
	var expiry uint32
	ca, err := c.Connect(context.Background(), &paho.Connect{
		ClientID: "over-tls", CleanStart: true, KeepAlive: 0,
		Properties: &paho.ConnectProperties{SessionExpiryInterval: &expiry},
	})
	if err != nil {
		t.Fatalf("connect over TLS: %v", err)
	}
	if ca.ReasonCode != 0 {
		t.Fatalf("connect over TLS refused: 0x%02X", ca.ReasonCode)
	}
	if _, err := c.Publish(context.Background(), &paho.Publish{
		Topic: "events/x", QoS: 1, Payload: []byte("hello"),
	}); err != nil {
		t.Fatalf("publish over TLS: %v", err)
	}
	_ = c.Disconnect(&paho.Disconnect{ReasonCode: 0})

	// A plaintext MQTT client must not get a session. Without this the test
	// would pass against a listener that ignored the certificate entirely.
	plain, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer plain.Close()
	_ = plain.SetDeadline(time.Now().Add(2 * time.Second))
	pc := paho.NewClient(paho.ClientConfig{Conn: plain})
	if _, err := pc.Connect(context.Background(), &paho.Connect{
		ClientID: "plain", CleanStart: true, KeepAlive: 0,
	}); err == nil {
		t.Error("a plaintext client connected to a TLS listener")
	}
}

// RFC 0002 "Authorization": rules are about the name a client authenticates
// under, so a name nothing checked is never the identity an acl_file is
// asked about. Three routes made it one: a door with no password file took
// the user name a client typed (`admin` was granted admin's rules); the ws
// door never read the certificate its handshake verified; and a verified
// certificate naming nobody fell through to the typed name. Each is driven
// beside a control that shows the rule it is refused under does grant.
func TestANameNothingCheckedIsNeverTheIdentity(t *testing.T) {
	aclPath := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(aclPath, []byte(`
roles:
  admin:
    - topic: "secret/#"
      allow: [read, write]
users:
  admin: [admin]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	certFile, keyFile, serverPool := selfSigned(t, "localhost")
	serverPair, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		t.Fatalf("server pair: %v", err)
	}
	// serve starts a broker with the acl_file and the given credentials on
	// one listener, and answers its address and server.
	serve := func(t *testing.T, users *passwd.File, l func(*mqtt.Server) listeners.Listener) (string, *mqtt.Server) {
		t.Helper()
		reg, err := channel.NewRegistry([]*channel.Channel{{Name: "events", Type: channel.Append}})
		if err != nil {
			t.Fatalf("registry: %v", err)
		}
		srv, b, err := broker.NewServer(reg, config.Limits{}.Resolve(), slog.New(slog.NewTextHandler(io.Discard, nil)))
		if err != nil {
			t.Fatalf("server: %v", err)
		}
		b.SetCredentials(users, users == nil)
		f, err := authz.Load(aclPath, reg, 0)
		if err != nil {
			t.Fatalf("load acl: %v", err)
		}
		b.Authorize(authz.New(f, reg))
		lis := l(srv)
		if err := srv.AddListener(lis); err != nil {
			t.Fatalf("add listener: %v", err)
		}
		go func() { _ = srv.Serve() }()
		t.Cleanup(func() { _ = srv.Close(); b.Stop() })
		return lis.Address(), srv
	}
	// connectAs connects over conn and answers the CONNACK's code, the name
	// the broker gave the client, and SUBSCRIBE secret/#'s answer.
	connectAs := func(t *testing.T, srv *mqtt.Server, conn net.Conn, id, user, password string) (byte, string, byte) {
		t.Helper()
		c := paho.NewClient(paho.ClientConfig{Conn: conn})
		cp := &paho.Connect{ClientID: id, CleanStart: true, KeepAlive: 0}
		if user != "" {
			cp.Username, cp.UsernameFlag = user, true
		}
		if password != "" {
			cp.Password, cp.PasswordFlag = []byte(password), true
		}
		ca, err := c.Connect(context.Background(), cp)
		if ca == nil {
			t.Fatalf("%s: no CONNACK: %v", id, err)
		}
		if ca.ReasonCode != 0 {
			return ca.ReasonCode, "", 0
		}
		cl := awaitRegistered(t, srv, id, 2*time.Second)
		sa, err := c.Subscribe(context.Background(), &paho.Subscribe{Subscriptions: []paho.SubscribeOptions{{Topic: "secret/#", QoS: 1}}})
		if sa == nil {
			t.Fatalf("%s: no SUBACK: %v", id, err)
		}
		return 0, string(cl.Properties.Username), sa.Reasons[0]
	}
	plain := func(*mqtt.Server) listeners.Listener {
		return listeners.NewTCP(listeners.Config{ID: "tcp", Address: "127.0.0.1:0"})
	}

	t.Run("a door with no password file", func(t *testing.T) {
		addr, srv := serve(t, nil, plain)
		conn, err := net.Dial("tcp", addr)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { _ = conn.Close() })
		code, name, sub := connectAs(t, srv, conn, "typed-admin", "admin", "")
		if code != 0 || name != "" || sub != 0x87 {
			t.Errorf("a client typing admin on a door with no password file: CONNACK 0x%02X, named %q, "+
				"SUBSCRIBE secret/# 0x%02X; want 0x00, named nobody, 0x87", code, name, sub)
		}
	})
	t.Run("the control: admin, authenticated", func(t *testing.T) {
		pf := passwd.New(filepath.Join(t.TempDir(), "clients.passwd"))
		if err := pf.Set("admin", "hunter2"); err != nil {
			t.Fatal(err)
		}
		addr, srv := serve(t, pf, plain)
		conn, err := net.Dial("tcp", addr)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { _ = conn.Close() })
		if code, name, sub := connectAs(t, srv, conn, "real-admin", "admin", "hunter2"); code != 0 || name != "admin" || sub != 0x01 {
			t.Fatalf("admin with its password: CONNACK 0x%02X, named %q, SUBSCRIBE 0x%02X; want 0x00, admin, "+
				"0x01 - the rule does not grant, so this proves nothing", code, name, sub)
		}
	})

	wss := func(t *testing.T, users *passwd.File, cn string, user string) (byte, string, byte) {
		t.Helper()
		client, clientCAs := clientCert(t, cn)
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatal(err)
		}
		address := ln.Addr().String()
		_ = ln.Close()
		_, srv := serve(t, users, func(*mqtt.Server) listeners.Listener {
			return listeners.NewWebsocket(listeners.Config{ID: "ws", Address: address, TLSConfig: &tls.Config{
				Certificates: []tls.Certificate{serverPair}, MinVersion: tls.VersionTLS12,
				ClientCAs: clientCAs, ClientAuth: tls.RequireAndVerifyClientCert}})
		})
		d := &websocket.Dialer{Subprotocols: []string{"mqtt"}, TLSClientConfig: &tls.Config{
			RootCAs: serverPool, MinVersion: tls.VersionTLS12, Certificates: []tls.Certificate{client}}}
		var wc *websocket.Conn
		for deadline := time.Now().Add(3 * time.Second); ; time.Sleep(10 * time.Millisecond) {
			c, _, err := d.Dial("wss://"+address+"/", nil)
			if err == nil {
				wc = c
				break
			}
			if time.Now().After(deadline) {
				t.Fatalf("wss dial: %v", err)
			}
		}
		conn := &brokertest.WSConn{Conn: wc}
		t.Cleanup(func() { _ = conn.Close() })
		return connectAs(t, srv, conn, "ws-"+cn, user, "")
	}
	t.Run("the ws door reads the certificate it verified", func(t *testing.T) {
		if code, name, sub := wss(t, nil, "admin", ""); code != 0 || name != "admin" || sub != 0x01 {
			t.Errorf("a certificate naming admin on the ws door: CONNACK 0x%02X, named %q, SUBSCRIBE 0x%02X; "+
				"want 0x00, admin, 0x01", code, name, sub)
		}
		if code, name, sub := wss(t, nil, "device-7", "admin"); code != 0 || name != "device-7" || sub != 0x87 {
			t.Errorf("a certificate naming device-7 on the ws door, typing admin: CONNACK 0x%02X, named %q, "+
				"SUBSCRIBE 0x%02X; want 0x00, device-7, 0x87", code, name, sub)
		}
		pf := passwd.New(filepath.Join(t.TempDir(), "clients.passwd"))
		if err := pf.Set("somebody-else", "hunter2"); err != nil {
			t.Fatal(err)
		}
		if code, name, _ := wss(t, pf, "device-7", ""); code != 0 || name != "device-7" {
			t.Errorf("a certificate on the ws door beside a password file not naming it: CONNACK 0x%02X, "+
				"named %q; want 0x00 and device-7, as on the tcp door", code, name)
		}
	})
	t.Run("a verified certificate naming nobody", func(t *testing.T) {
		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
		if err != nil {
			t.Fatal(err)
		}
		// No Common Name and no DNS name: an e-mail address names nobody
		// here, where a DNS name alone would be the name (RFC 0002).
		tmpl := x509.Certificate{SerialNumber: big.NewInt(9), EmailAddresses: []string{"device-7@example.net"},
			NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour),
			KeyUsage:    x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
			ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, IsCA: true}
		der, err := x509.CreateCertificate(rand.Reader, &tmpl, &tmpl, &key.PublicKey, key)
		if err != nil {
			t.Fatal(err)
		}
		leaf, _ := x509.ParseCertificate(der)
		pool := x509.NewCertPool()
		pool.AddCert(leaf)
		addr, srv := serve(t, nil, func(*mqtt.Server) listeners.Listener {
			return listeners.NewTCP(listeners.Config{ID: "mtls", Address: "127.0.0.1:0", TLSConfig: &tls.Config{
				Certificates: []tls.Certificate{serverPair}, MinVersion: tls.VersionTLS12,
				ClientCAs: pool, ClientAuth: tls.RequireAndVerifyClientCert}})
		})
		conn, err := tls.Dial("tcp", addr, &tls.Config{RootCAs: serverPool, MinVersion: tls.VersionTLS12,
			Certificates: []tls.Certificate{{Certificate: [][]byte{der}, PrivateKey: key, Leaf: leaf}}})
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { _ = conn.Close() })
		if code, name, sub := connectAs(t, srv, conn, "san-only", "admin", ""); code != 0 || name != "" || sub != 0x87 {
			t.Errorf("a certificate naming nobody, typing admin: CONNACK 0x%02X, named %q, SUBSCRIBE 0x%02X; "+
				"want 0x00, named nobody, 0x87", code, name, sub)
		}
	})
}

// RFC 0002 "Client certificates": **a certificate's name is its Common
// Name, else its first DNS name**, at the MQTT door as at the operations
// door. This door took the Common Name alone, so a certificate carrying only
// a subject alternative name named nobody here and an operator there.
//
// A DNS name is an authority's string, as a Common Name is, and once it is
// an identity it meets every rule an identity does. Driven over real TLS
// against an acl_file whose one rule names %u, and one whose entry writes
// client_ids: ["%u"]:
//   - the first DNS name is the name, and the %u rule grants its subtree and
//     nobody else's;
//   - a wildcard DNS name, `*.example.com`, is that name as written: `*` is
//     not MQTT syntax, so the %u rule grants `devices/*.example.com/#` and no
//     other device's; under client_ids it would be the pattern's own glob,
//     so it matches no client id and the connection is refused 0x86;
//   - a DNS name holding `/` would be a level in the rule, so the %u rule
//     grants it nothing;
//   - a DNS name holding a control character is nobody's, refused 0x86.
func TestACertificateWithOnlyDNSNamesIsNamedByTheFirst(t *testing.T) {
	certFile, keyFile, serverPool := selfSigned(t, "localhost")
	serverPair, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		t.Fatalf("server pair: %v", err)
	}
	const byTopic = `
roles:
  own:
    - topic: "devices/%u/#"
      allow: [read, write]
users:
  "*": [own]
`
	const byClientID = `
roles:
  own:
    - topic: "devices/%u/#"
      allow: [read, write]
users:
  "*":
    roles: [own]
    client_ids: ["%u"]
`
	// run serves one mutual-TLS listener under acl, connects a certificate
	// naming dns with client id id, and answers the CONNACK's code, the name
	// the broker gave the client, and each filter's SUBACK reason.
	run := func(t *testing.T, acl string, dns []string, id string, filters ...string) (byte, string, []byte) {
		t.Helper()
		aclPath := filepath.Join(t.TempDir(), "acl.yaml")
		if err := os.WriteFile(aclPath, []byte(acl), 0o600); err != nil {
			t.Fatalf("write acl: %v", err)
		}
		reg, err := channel.NewRegistry([]*channel.Channel{{Name: "events", Type: channel.Append}})
		if err != nil {
			t.Fatalf("registry: %v", err)
		}
		srv, b, err := broker.NewServer(reg, config.Limits{}.Resolve(), slog.New(slog.NewTextHandler(io.Discard, nil)))
		if err != nil {
			t.Fatalf("server: %v", err)
		}
		b.SetCredentials(nil, false)
		f, err := authz.Load(aclPath, reg, 0)
		if err != nil {
			t.Fatalf("load acl: %v", err)
		}
		b.Authorize(authz.New(f, reg))
		client, clientCAs := certNaming(t, "", dns...)
		l := listeners.NewTCP(listeners.Config{ID: "mtls", Address: "127.0.0.1:0", TLSConfig: &tls.Config{
			Certificates: []tls.Certificate{serverPair}, MinVersion: tls.VersionTLS12,
			ClientCAs: clientCAs, ClientAuth: tls.RequireAndVerifyClientCert}})
		if err := srv.AddListener(l); err != nil {
			t.Fatalf("add listener: %v", err)
		}
		go func() { _ = srv.Serve() }()
		t.Cleanup(func() { _ = srv.Close(); b.Stop() })

		conn, err := tls.Dial("tcp", l.Address(), &tls.Config{RootCAs: serverPool, MinVersion: tls.VersionTLS12,
			Certificates: []tls.Certificate{client}})
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		t.Cleanup(func() { _ = conn.Close() })
		c := paho.NewClient(paho.ClientConfig{Conn: conn})
		ca, err := c.Connect(context.Background(), &paho.Connect{ClientID: id, CleanStart: true, KeepAlive: 0})
		if ca == nil {
			t.Fatalf("%s: no CONNACK: %v", id, err)
		}
		if ca.ReasonCode != 0 {
			return ca.ReasonCode, "", nil
		}
		cl := awaitRegistered(t, srv, id, 2*time.Second)
		var reasons []byte
		for _, filter := range filters {
			sa, err := c.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{{Topic: filter, QoS: 1}}})
			if sa == nil {
				t.Fatalf("%s: no SUBACK for %s: %v", id, filter, err)
			}
			reasons = append(reasons, sa.Reasons[0])
		}
		return 0, string(cl.Properties.Username), reasons
	}

	for _, tc := range []struct {
		what    string
		acl     string
		dns     []string
		id      string
		filters []string
		code    byte
		name    string
		reasons []byte
	}{
		{what: "the first DNS name is the name", acl: byTopic,
			dns: []string{"device-8.example.net", "other.example.net"}, id: "c1",
			filters: []string{"devices/device-8.example.net/#", "devices/other.example.net/#"},
			name:    "device-8.example.net", reasons: []byte{0x01, 0x87}},
		{what: "a wildcard DNS name is that name as written", acl: byTopic,
			dns: []string{"*.example.com"}, id: "c2",
			filters: []string{"devices/*.example.com/#", "devices/north.example.com/#"},
			name:    "*.example.com", reasons: []byte{0x01, 0x87}},
		{what: "a DNS name holding a level separator is granted nothing by %u", acl: byTopic,
			dns: []string{"a/b.example"}, id: "c3",
			filters: []string{"devices/a/b.example/#", "devices/a/#"},
			name:    "a/b.example", reasons: []byte{0x87, 0x87}},
		{what: "a DNS name holding a control character is nobody's", acl: byTopic,
			dns: []string{"dev\x01.example"}, id: "c4", code: 0x86},
		{what: "the control: client_ids %u admits the name it names", acl: byClientID,
			dns: []string{"device-8.example.net"}, id: "device-8.example.net",
			filters: []string{"devices/device-8.example.net/#"},
			name:    "device-8.example.net", reasons: []byte{0x01}},
		{what: "a wildcard DNS name is no client_ids glob", acl: byClientID,
			dns: []string{"*.example.com"}, id: "*.example.com", code: 0x86},
	} {
		t.Run(tc.what, func(t *testing.T) {
			code, name, reasons := run(t, tc.acl, tc.dns, tc.id, tc.filters...)
			if code != tc.code || name != tc.name || !slices.Equal(reasons, tc.reasons) {
				t.Errorf("a certificate naming only DNS %q, client id %q: CONNACK 0x%02X, named %q, "+
					"SUBACK %x for %q; want 0x%02X, %q, %x", tc.dns, tc.id, code, name, reasons, tc.filters,
					tc.code, tc.name, tc.reasons)
			}
		})
	}
}

// RFC 0002 "TLS on a listener", the mutual half: a client presenting a
// certificate this broker's authority signed is authenticated by it, and
// **the Common Name becomes its user name**.
//
// The password file is not consulted for such a client: the authority has
// already made the statement the file exists to make, and requiring both
// would mean no device could be issued a certificate without also being
// given a password to keep somewhere.
func TestAClientCertificateAuthenticatesAndNamesTheClient(t *testing.T) {
	certFile, keyFile, serverPool := selfSigned(t, "localhost")
	serverPair, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		t.Fatalf("server pair: %v", err)
	}
	client, clientCAs := clientCert(t, "device-7")

	// A password file that does NOT name device-7, so anything that gets in
	// got in on its certificate.
	passwdPath := filepath.Join(t.TempDir(), "clients.passwd")
	pf := passwd.New(passwdPath)
	if err := pf.Set("somebody-else", "hunter2"); err != nil {
		t.Fatalf("set: %v", err)
	}
	if err := pf.Save(); err != nil {
		t.Fatalf("save: %v", err)
	}
	users, err := passwd.Load(passwdPath)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	serve := func(t *testing.T, clientAuth tls.ClientAuthType) (string, *mqtt.Server) {
		t.Helper()
		reg, err := channel.NewRegistry([]*channel.Channel{{Name: "events", Type: channel.Append}})
		if err != nil {
			t.Fatalf("registry: %v", err)
		}
		srv, b, err := broker.NewServer(reg, config.Limits{}.Resolve(),
			slog.New(slog.NewTextHandler(io.Discard, nil)))
		if err != nil {
			t.Fatalf("server: %v", err)
		}
		b.SetCredentials(users, false)
		l := listeners.NewTCP(listeners.Config{
			ID: "mtls", Address: "127.0.0.1:0",
			TLSConfig: &tls.Config{
				Certificates: []tls.Certificate{serverPair},
				MinVersion:   tls.VersionTLS12,
				ClientCAs:    clientCAs,
				ClientAuth:   clientAuth,
			},
		})
		if err := srv.AddListener(l); err != nil {
			t.Fatalf("add listener: %v", err)
		}
		go func() { _ = srv.Serve() }()
		t.Cleanup(func() { _ = srv.Close(); b.Stop() })
		return l.Address(), srv
	}

	connect := func(t *testing.T, addr, id string, certs []tls.Certificate) (byte, error) {
		t.Helper()
		conn, err := tls.Dial("tcp", addr, &tls.Config{
			RootCAs: serverPool, MinVersion: tls.VersionTLS12, Certificates: certs,
		})
		if err != nil {
			return 0, err
		}
		t.Cleanup(func() { _ = conn.Close() })
		c := paho.NewClient(paho.ClientConfig{Conn: conn})
		var expiry uint32
		ca, err := c.Connect(context.Background(), &paho.Connect{
			ClientID: id, CleanStart: true, KeepAlive: 0,
			Properties: &paho.ConnectProperties{SessionExpiryInterval: &expiry},
		})
		if ca == nil {
			return 0, err
		}
		return ca.ReasonCode, nil
	}

	t.Run("a certificate is the credential, and the CN is the name", func(t *testing.T) {
		addr, srv := serve(t, tls.RequireAndVerifyClientCert)

		code, err := connect(t, addr, "cert-client", []tls.Certificate{client})
		if err != nil {
			t.Fatalf("connect with a client certificate: %v", err)
		}
		if code != 0 {
			t.Fatalf("a verified certificate was refused 0x%02X, though the password file "+
				"does not name it and was not supposed to be consulted", code)
		}

		// The claim the RFC makes, asked of the broker rather than assumed:
		// the CN is what this client is called.
		cl := awaitRegistered(t, srv, "cert-client", 2*time.Second)
		if got := string(cl.Properties.Username); got != "device-7" {
			t.Errorf("the client is named %q, want the certificate's Common Name device-7", got)
		}
	})

	// Required means required: the refusal is the handshake's, before any
	// MQTT packet exists to carry a reason code.
	t.Run("no certificate, where one is required", func(t *testing.T) {
		addr, _ := serve(t, tls.RequireAndVerifyClientCert)
		if _, err := connect(t, addr, "no-cert", nil); err == nil {
			t.Error("a client with no certificate connected to a listener that requires one")
		}
	})

	// The mixed mode a fleet migrating in batches needs: no certificate
	// falls through to the password file, which does not name this client.
	t.Run("no certificate, where one is optional", func(t *testing.T) {
		addr, _ := serve(t, tls.VerifyClientCertIfGiven)
		code, err := connect(t, addr, "no-cert", nil)
		if err != nil {
			t.Fatalf("the handshake refused a client where a certificate is optional: %v", err)
		}
		if code != 0x86 {
			t.Errorf("answered 0x%02X, want 0x86: with no certificate this client falls "+
				"through to the password file, which does not name it", code)
		}
	})
}

// RFC 0002 "Bridges": a `tls://` upstream whose certificate comes from a
// private authority, which is the shape an estate actually runs.
//
// **The bridge verifies it, and there is no way to turn that off.** A
// bridge carries records out of this broker; a link that accepts any
// certificate accepts whatever machine answered first, and the records go
// there. So the two cases are "named the right authority" and "did not
// connect".
func TestABridgeVerifiesAPrivateUpstream(t *testing.T) {
	certFile, keyFile, _ := selfSigned(t, "localhost")
	pair, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	// An upstream serving TLS with that certificate, which no public root
	// vouches for.
	up := mqtt.New(&mqtt.Options{
		Logger: slog.New(slog.NewTextHandler(io.Discard, nil)), InlineClient: true,
	})
	if err := up.AddHook(new(auth.AllowHook), nil); err != nil {
		t.Fatalf("upstream hook: %v", err)
	}
	upl := listeners.NewTCP(listeners.Config{
		ID: "up", Address: "127.0.0.1:0",
		TLSConfig: &tls.Config{Certificates: []tls.Certificate{pair}, MinVersion: tls.VersionTLS12},
	})
	if err := up.AddListener(upl); err != nil {
		t.Fatalf("upstream listener: %v", err)
	}
	go func() { _ = up.Serve() }()
	t.Cleanup(func() { _ = up.Close() })

	h := start(t)
	connected := func(t *testing.T, caFile string) bool {
		t.Helper()
		cfg := bridgeConfig(t, upl.Address())
		cfg.Peer = "tls://" + upl.Address()
		cfg.CAFile = caFile

		br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits,
			slog.New(slog.NewTextHandler(io.Discard, nil)), nil)
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		done := make(chan struct{})
		go func() { defer close(done); _ = br.Run(ctx) }()

		// Up, or not up within the window. autopaho retries silently, so
		// "never connected" can only be observed as time passing.
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			if br.Connected() {
				cancel()
				<-done
				return true
			}
			time.Sleep(20 * time.Millisecond)
		}
		cancel()
		<-done
		return false
	}

	t.Run("with the authority named, the link comes up", func(t *testing.T) {
		if !connected(t, certFile) {
			t.Error("a bridge naming the upstream's own authority did not connect")
		}
	})

	// The point of the feature: without it, this is what an estate with a
	// private CA gets, and it is not a hang or a silent plaintext fallback.
	t.Run("without it, the system roots do not vouch for this upstream", func(t *testing.T) {
		if connected(t, "") {
			t.Error("a bridge with no authority named connected to an upstream no public " +
				"root vouches for, so it verified nothing")
		}
	})
}

// RFC 0002 "On a bridge, dialling out", the other half of `ca_file`: the
// certificate saguin presents when the upstream asks for one.
//
// **The upstream here is a saguin**, running the strongest setting a
// listener offers - `client_ca_file` with `require_certificate: true` - so
// what this proves is the pair of brokers the feature exists for. It cannot
// be written with a stub: whether a certificate reached the far end is a
// fact about the handshake, and the far end is the only witness to it.
func TestABridgePresentsItsCertificateToAnUpstream(t *testing.T) {
	serverCert, serverKey, _ := selfSigned(t, "localhost")
	serverPair, err := tls.LoadX509KeyPair(serverCert, serverKey)
	if err != nil {
		t.Fatalf("server pair: %v", err)
	}
	pair, clientCAs := clientCert(t, "vessel-07")
	certFile, keyFile := writeClientPair(t, pair)

	// A second authority the upstream has never heard of, for the certificate
	// that has to be *sent* to be refused. Its name differs from the trusted
	// one deliberately: that name is the whole of what crypto/tls filters on.
	stranger, _ := clientCertFrom(t, "Some Other CA", "vessel-07")
	strangerCert, strangerKey := writeClientPair(t, stranger)

	// A password file naming somebody else, and no anonymous connection, so
	// nothing gets into this upstream except on a certificate.
	passwdPath := filepath.Join(t.TempDir(), "clients.passwd")
	pf := passwd.New(passwdPath)
	if err := pf.Set("somebody-else", "hunter2"); err != nil {
		t.Fatalf("set: %v", err)
	}
	if err := pf.Save(); err != nil {
		t.Fatalf("save: %v", err)
	}
	users, err := passwd.Load(passwdPath)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	// The upstream saguin, on TLS, verifying what a client presents against
	// an authority no public root knows.
	//
	// `anonymous` is the gate below this one, and each case sets it for what
	// it is asking. A case about who the certificate says the bridge is wants
	// the password file to be the only other way in, so it refuses anonymous
	// clients; a case about whether a certificate was *sent* wants the
	// handshake to be the only thing that can refuse, so it admits them.
	serve := func(t *testing.T, clientAuth tls.ClientAuthType, anonymous bool) (string, *mqtt.Server) {
		t.Helper()
		reg, err := channel.NewRegistry([]*channel.Channel{{Name: "fleet", Type: channel.Append}})
		if err != nil {
			t.Fatalf("registry: %v", err)
		}
		srv, b, err := broker.NewServer(reg, config.Limits{}.Resolve(),
			slog.New(slog.NewTextHandler(io.Discard, nil)))
		if err != nil {
			t.Fatalf("server: %v", err)
		}
		b.SetCredentials(users, anonymous)
		l := listeners.NewTCP(listeners.Config{
			ID: "up", Address: "127.0.0.1:0",
			TLSConfig: &tls.Config{
				Certificates: []tls.Certificate{serverPair},
				MinVersion:   tls.VersionTLS12,
				ClientCAs:    clientCAs,
				ClientAuth:   clientAuth,
			},
		})
		if err := srv.AddListener(l); err != nil {
			t.Fatalf("add listener: %v", err)
		}
		go func() { _ = srv.Serve() }()
		t.Cleanup(func() { _ = srv.Close(); b.Stop() })
		return l.Address(), srv
	}

	h := start(t)
	connected := func(t *testing.T, addr, cert, key string) bool {
		t.Helper()
		cfg := bridgeConfig(t, addr)
		cfg.Peer = "tls://" + addr
		cfg.CAFile = serverCert
		cfg.CertFile, cfg.KeyFile = cert, key

		br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits,
			slog.New(slog.NewTextHandler(io.Discard, nil)), nil)
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		done := make(chan struct{})
		go func() { defer close(done); _ = br.Run(ctx) }()

		// Up, or not up within the window. autopaho retries silently, so
		// "never connected" can only be observed as time passing.
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			if br.Connected() {
				cancel()
				<-done
				return true
			}
			time.Sleep(20 * time.Millisecond)
		}
		cancel()
		<-done
		return false
	}

	// The whole point of the item: two saguins, one requiring a certificate
	// and the other holding one.
	t.Run("the link comes up where the upstream requires a certificate", func(t *testing.T) {
		addr, srv := serve(t, tls.RequireAndVerifyClientCert, false)
		if !connected(t, addr, certFile, keyFile) {
			t.Fatal("a bridge holding a certificate from the upstream's own authority did " +
				"not connect to an upstream that requires one")
		}
		// Asked of the upstream rather than assumed: it is not only that a
		// handshake completed, it is that the certificate is who the bridge
		// is. The password file names somebody else and anonymous is off, so
		// nothing else could have let it in.
		cl := awaitRegistered(t, srv, "vessel-07", 2*time.Second)
		if got := string(cl.Properties.Username); got != "vessel-07" {
			t.Errorf("the upstream calls the bridge %q, want the certificate's Common Name "+
				"vessel-07", got)
		}
	})

	// Without the pair this is what an operator gets, and it is the state the
	// feature exists to leave behind. Anonymous connections are admitted
	// here, so the handshake is the only thing that can refuse this bridge.
	t.Run("without one, the handshake never completes", func(t *testing.T) {
		addr, _ := serve(t, tls.RequireAndVerifyClientCert, true)
		if connected(t, addr, "", "") {
			t.Error("a bridge with no certificate connected to an upstream that requires one")
		}
	})

	// **Why GetClientCertificate rather than TlsCfg.Certificates.** crypto/tls
	// matches Certificates against the authorities the far end advertises and
	// sends nothing at all when none of them match - no error, no log line -
	// so a certificate issued by the wrong authority would become a link that
	// comes up carrying no identity, wherever the upstream takes a client
	// without one. Saguin sends what the operator configured and lets the far
	// end be the one that refuses it.
	//
	// The two runs differ in one thing: whether a certificate exists to be
	// presented. The upstream examines a certificate only if it is given one
	// and admits anonymous clients, so the first run proves this bridge is
	// otherwise welcome, and the second can then only fail because saguin
	// presented something.
	t.Run("a certificate from an authority the upstream does not know is still sent",
		func(t *testing.T) {
			addr, _ := serve(t, tls.VerifyClientCertIfGiven, true)
			if !connected(t, addr, "", "") {
				t.Fatal("the control run failed: a bridge with no certificate could not " +
					"connect, so the case below would prove nothing")
			}
			if connected(t, addr, strangerCert, strangerKey) {
				t.Error("a bridge holding a certificate from an authority the upstream does " +
					"not know connected to a listener that verifies what it is given, so " +
					"saguin presented nothing and the link came up with no identity on it")
			}
		})
}

// RFC 0003: a subscription that asks is sent a latest channel's deletions
// along with its current state, and one that does not is not.
//
// **This is what closes the case a copy could not otherwise learn.** A
// subscriber is handed current state, and a set of current values cannot say
// that a topic is gone - so a topic deleted while a copy's link was down
// would live on that copy for ever. Asking is how a copy is told.
func TestASubscriptionMayAskForDeletions(t *testing.T) {
	h := start(t)
	producer := connect(t, h, "producer", true, false)
	producer.Pub(t, "state/boat-7/fuel", "40")
	producer.Pub(t, "state/boat-9/fuel", "55")
	settle(t, producer)
	producer.Pub(t, "state/boat-7/fuel", "") // decommissioned
	settle(t, producer)

	// The control: an ordinary subscriber is told nothing about the deleted
	// topic, which is what every client has always been told.
	plain := connect(t, h, "plain", true, false)
	plain.Sub(t, "state/#", 1)
	if got := collect(t, plain, 1, 2*time.Second); len(got) != 1 ||
		got[0].Topic != "state/boat-9/fuel" {
		t.Fatalf("an ordinary subscriber was sent %v, want only the topic with a value", got)
	}

	// And one that asks is sent both, the deletion as an empty payload at
	// the offset it was stored at.
	asking := dialAsking(t, h, "copy-link", "state/#")
	got := collect(t, asking, 2, 2*time.Second)
	if len(got) != 2 {
		t.Fatalf("a subscription asking for deletions was sent %d records, want 2: %v",
			len(got), got)
	}
	byTopic := map[string]received{}
	for _, r := range got {
		byTopic[r.Topic] = r
	}
	gone, ok := byTopic["state/boat-7/fuel"]
	if !ok {
		t.Fatalf("the deletion was not sent to a subscription that asked: %v", got)
	}
	if gone.Payload != "" {
		t.Errorf("the deletion arrived carrying %q, want no payload", gone.Payload)
	}
	if off := gone.User["saguin-offset"]; off == "" || off == "0" {
		t.Errorf("the deletion arrived at offset %q, so a copy cannot order it", off)
	}
	if _, ok := byTopic["state/boat-9/fuel"]; !ok {
		t.Errorf("the topic with a value was not sent: %v", got)
	}
}

// A dead-letter channel that is not a copy is unchanged: it takes records
// from its queue and from nothing else, whoever asks.
func TestAnOrdinaryDeadLetterChannelStillRefusesEverybody(t *testing.T) {
	h := start(t)
	producer := connect(t, h, "producer", true, false)
	ack, err := producer.C.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/__dlq/failed", QoS: 1, Payload: []byte("mine"),
	})
	if ack == nil {
		t.Fatalf("no PUBACK: %v", err)
	}
	if ack.ReasonCode != 0x87 {
		t.Errorf("a publish into an ordinary dead-letter channel answered 0x%02X, want 0x87",
			ack.ReasonCode)
	}
}

// **A publisher's User Properties reach a consumer unaltered and in order,
// repeats and all** - MQTT 5's rule, and what saguin did on a broadcast
// topic while losing it on every channel.
//
// The loss was in the record: headers were a map, so the same name twice
// kept only the last of them, and what survived came back in Go map order.
// Two consequences, both silent. Three properties named `tag` arrived as
// one. And the order differed run to run, so a consumer reading a record
// live and reading it again on replay was handed two different lists - the
// same record, described two ways.
//
// Broadcast never had it, because a topic no channel claims is passed
// through as the packet it arrived as. That is what made this a channel
// defect rather than a broker one, and it is why broadcast is the control
// here: if the two disagree, saguin is not one broker.
//
// **Live and replayed are both asked**, because they are different paths
// and only one of them was ever provably wrong: live carried the packet's
// own order and looked correct, while replay went through the map.
func TestUserPropertiesSurviveAChannelInOrderWithRepeats(t *testing.T) {
	sent := paho.UserProperties{
		{Key: "zeta", Value: "1"},
		{Key: "alpha", Value: "2"},
		{Key: "tag", Value: "first"},
		{Key: "tag", Value: "second"},
		{Key: "tag", Value: "third"},
		{Key: "mid", Value: "3"},
	}
	// What a consumer must see, after saguin's own three are skipped.
	want := []string{"zeta=1", "alpha=2", "tag=first", "tag=second", "tag=third", "mid=3"}

	// publish sends the set above and returns what arrived, saguin's own
	// reserved properties removed - they are stamped by the broker and are
	// not what this is about.
	arrived := func(t *testing.T, got *paho.Publish) []string {
		t.Helper()
		if got == nil || got.Properties == nil {
			t.Fatal("nothing arrived, so this asserts nothing")
		}
		var out []string
		for _, u := range got.Properties.User {
			if strings.HasPrefix(u.Key, "saguin-") {
				continue
			}
			out = append(out, u.Key+"="+u.Value)
		}
		return out
	}

	for _, tc := range []struct {
		name  string
		topic string
		late  bool
	}{
		{"broadcast, the control", "weather/oslo", false},
		{"an append channel, live", "events/thing", false},
		{"an append channel, replayed", "events/thing", true},
		{"a latest channel, replayed", "state/room", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			filter := strings.SplitN(tc.topic, "/", 2)[0] + "/#"

			var sub *propClient
			if !tc.late {
				sub = dialProps(t, h, "reader")
				if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
					Subscriptions: []paho.SubscribeOptions{{Topic: filter, QoS: 1}},
				}); err != nil {
					t.Fatalf("subscribe: %v", err)
				}
			}

			pub := dialProps(t, h, "writer")
			if _, err := pub.C.Publish(context.Background(), &paho.Publish{
				Topic: tc.topic, QoS: 1, Payload: []byte("x"),
				Properties: &paho.PublishProperties{User: sent},
			}); err != nil {
				t.Fatalf("publish: %v", err)
			}

			if tc.late {
				// Reading it back out of the channel rather than watching it
				// go past, which is the path the map was on.
				sub = dialProps(t, h, "late-reader")
				if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
					Subscriptions: []paho.SubscribeOptions{{Topic: filter, QoS: 1}},
				}); err != nil {
					t.Fatalf("subscribe: %v", err)
				}
			}

			got := arrived(t, awaitProp(t, sub))
			if !slices.Equal(got, want) {
				t.Errorf("the consumer was given\n  %v\nwant\n  %v\n"+
					"in that order and with every repeat - a name kept once is a value "+
					"the publisher sent and nobody received", got, want)
			}
		})
	}
}

// **The publish properties that are not User Properties survive a channel**,
// which they did not: content type, response topic, correlation data, the
// payload format indicator and the message expiry interval reached the
// broker, reached a subscriber of a broadcast topic, and were dropped the
// moment a channel claimed the topic. RFC 0003 specified that, and this is
// the commit that changes it.
//
// Broadcast is the control again, for the same reason as the User Property
// test above: it was always right, so a run where broadcast fails is a
// broken test rather than a finding.
//
// **The queue is the deliberate exception and it is asserted here rather
// than described.** A job delivery's Response Topic is where the worker
// answers and its Correlation Data is the Delivery ID - that pair is the
// acknowledgement protocol, and MQTT gives one of each per packet. So the
// publisher's pair is held back there and nowhere else, while content type
// and the format indicator come through untouched.
func TestPublishPropertiesSurviveAChannel(t *testing.T) {
	expiry := uint32(3600)
	format := byte(1)
	send := &paho.PublishProperties{
		ContentType:     "application/json",
		CorrelationData: []byte("corr-42"),
		ResponseTopic:   "replies/here",
		MessageExpiry:   &expiry,
		PayloadFormat:   &format,
	}

	for _, tc := range []struct {
		name       string
		topic      string
		filter     string
		late       bool
		queueOwned bool
	}{
		{"broadcast, the control", "weather/oslo", "weather/#", false, false},
		{"an append channel, replayed", "events/thing", "events/#", true, false},
		{"a latest channel, replayed", "state/room", "state/#", true, false},
		{"a queue keeps its own reply pair", "jobs/w/1", "$saguin/queue/jobs", false, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)

			var sub *propClient
			subscribe := func(id string) {
				sub = dialProps(t, h, id)
				if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
					Subscriptions: []paho.SubscribeOptions{{Topic: tc.filter, QoS: 1}},
				}); err != nil {
					t.Fatalf("subscribe %s: %v", tc.filter, err)
				}
			}
			if !tc.late {
				subscribe("reader")
			}

			pub := dialProps(t, h, "writer")
			if _, err := pub.C.Publish(context.Background(), &paho.Publish{
				Topic: tc.topic, QoS: 1, Payload: []byte(`{"a":1}`), Properties: send,
			}); err != nil {
				t.Fatalf("publish: %v", err)
			}
			if tc.late {
				subscribe("late-reader")
			}

			got := awaitProp(t, sub)
			if got == nil || got.Properties == nil {
				t.Fatal("nothing arrived, so this asserts nothing")
			}
			p := got.Properties

			if p.ContentType != "application/json" {
				t.Errorf("content type %q, want application/json", p.ContentType)
			}
			if p.PayloadFormat == nil || *p.PayloadFormat != 1 {
				t.Errorf("payload format %v, want 1", p.PayloadFormat)
			}
			// Decremented, as MQTT requires, so it must not still be the
			// hour the publisher wrote - but it has not had time to move
			// far, which is what makes the upper bound safe.
			if p.MessageExpiry == nil {
				t.Errorf("no message expiry was delivered, so the publisher's ceiling is lost")
			} else if *p.MessageExpiry > expiry {
				t.Errorf("message expiry came back as %d, above the %d published - it must "+
					"be the remainder, never more", *p.MessageExpiry, expiry)
			}

			if tc.queueOwned {
				if p.ResponseTopic == "replies/here" {
					t.Error("a job delivery carried the publisher's response topic, so the " +
						"worker would answer somewhere the broker is not listening and the " +
						"job could never be acknowledged")
				}
				if !strings.HasPrefix(p.ResponseTopic, "$saguin/queue/") {
					t.Errorf("a job delivery's response topic is %q, want saguin's own",
						p.ResponseTopic)
				}
				return
			}
			if p.ResponseTopic != "replies/here" {
				t.Errorf("response topic %q, want replies/here", p.ResponseTopic)
			}
			if string(p.CorrelationData) != "corr-42" {
				t.Errorf("correlation data %q, want corr-42", p.CorrelationData)
			}
		})
	}
}

// **A copy takes the publish properties its source held**, the way it takes
// the stamped three - so a consumer that fails over to the copy reads the
// same records, described the same way.
//
// This drives the real bridge against a real upstream rather than injecting
// through the copy's write path, because the question is whether the five
// survive *the link*: they are read off the upstream's delivery, carried
// through the Publisher interface, and stored. Injecting would test the last
// step only, which was never the doubtful one.
//
// Message Expiry is checked as "arrived and did not grow". A conforming
// upstream sends the remainder rather than the publisher's original, and the
// copy's own clock starts when it stores the record - so the exact number is
// the upstream's business and the assertion is on the property crossing at
// all, not on arithmetic this test does not own.
func TestACopyTakesThePublishPropertiesItsSourceHeld(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)
	cfg := bridgeConfig(t, upstreamAddr)

	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(10 * time.Second):
			t.Error("the bridge did not stop")
		}
	})

	reader := dialProps(t, h, "reader")
	if _, err := reader.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "events/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	waitForBridge(t, upstream, cfg.ClientID)

	prod := dialUpstream(t, upstreamAddr, "vessel-sensor")
	expiry := uint32(3600)
	format := byte(1)
	if _, err := prod.Publish(context.Background(), &paho.Publish{
		Topic: "fleet/vessel-07/telemetry/hold/psi", QoS: 1, Payload: []byte(`{"psi":31}`),
		Properties: &paho.PublishProperties{
			ContentType:     "application/json",
			CorrelationData: []byte("corr-42"),
			ResponseTopic:   "replies/here",
			MessageExpiry:   &expiry,
			PayloadFormat:   &format,
		},
	}); err != nil {
		t.Fatalf("publish peer: %v", err)
	}

	got := awaitProp(t, reader)
	if got == nil || got.Properties == nil {
		t.Fatal("nothing crossed the link, so this asserts nothing")
	}
	p := got.Properties
	if p.ContentType != "application/json" {
		t.Errorf("content type %q crossed, want application/json", p.ContentType)
	}
	if p.ResponseTopic != "replies/here" {
		t.Errorf("response topic %q crossed, want replies/here", p.ResponseTopic)
	}
	if string(p.CorrelationData) != "corr-42" {
		t.Errorf("correlation data %q crossed, want corr-42", p.CorrelationData)
	}
	if p.PayloadFormat == nil || *p.PayloadFormat != 1 {
		t.Errorf("payload format %v crossed, want 1", p.PayloadFormat)
	}
	if p.MessageExpiry == nil {
		t.Error("no message expiry crossed, so the publisher's ceiling is lost at the copy")
	} else if *p.MessageExpiry > expiry {
		t.Errorf("message expiry crossed as %d, above the %d published", *p.MessageExpiry, expiry)
	}
}

// **A keepalive ceiling reaches the client in its CONNACK**, which is the
// only place MQTT lets a server impose one (MQTT-3.1.2-21).
//
// saguin set no ceiling at all, so a device asking for eighteen hours - or
// for zero, which MQTT defines as "never disconnect me for being idle" -
// held a session the broker had no way to tell was dead until the session
// expiry ran out. That is a much longer clock by design, and it is the one
// that decides when a durable consumer's stored position is released.
//
// Asked of the CONNACK rather than of the configuration, because a ceiling
// the client is never told about is not a ceiling: the client goes on using
// its own number and the broker closes a connection the client believed was
// healthy.
func TestAKeepaliveCeilingReachesTheClient(t *testing.T) {
	for name, tc := range map[string]struct {
		asked uint16
		want  uint16
	}{
		"a client asking for longer is given the ceiling": {3600, 30},
		"a client asking for zero is given it too":        {0, 30},
		"a client already inside it is left alone":        {10, 0},
	} {
		t.Run(name, func(t *testing.T) {
			brokertest.KeepaliveCeiling = 30
			t.Cleanup(func() { brokertest.KeepaliveCeiling = 0 })
			h := start(t)

			conn, err := net.Dial("tcp", h.Addr)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			c := paho.NewClient(paho.ClientConfig{Conn: conn})
			ca, err := c.Connect(context.Background(), &paho.Connect{
				ClientID: "device", CleanStart: true, KeepAlive: tc.asked,
			})
			if err != nil {
				t.Fatalf("connect: %v", err)
			}
			t.Cleanup(func() { _ = c.Disconnect(&paho.Disconnect{ReasonCode: 0}) })
			if ca.ReasonCode != 0 {
				t.Fatalf("connack 0x%02X", ca.ReasonCode)
			}

			var got uint16
			if ca.Properties != nil && ca.Properties.ServerKeepAlive != nil {
				got = *ca.Properties.ServerKeepAlive
			}
			if got != tc.want {
				t.Errorf("the CONNACK carried a server keepalive of %d, want %d - "+
					"a ceiling the client is not told about is one it will not use, "+
					"and the broker then closes a connection the client thought was fine",
					got, tc.want)
			}
		})
	}
}

// **A listener's own credentials beat the broker's**, which is the whole
// point of the key: an operator can say "the Unix socket admits anybody
// local, the TCP port demands a credential" without the two answers being
// one answer.
//
// Asked at the CONNACK on a real connection rather than of the resolution,
// because a pair that resolves correctly and never reaches the hook is a
// listener still running on the broker-wide answer - and that failure looks
// exactly like a working broker until somebody connects to the wrong door.
func TestAListenersCredentialsBeatTheBrokers(t *testing.T) {
	h := start(t)
	path := filepath.Join(t.TempDir(), "clients.passwd")
	pf := passwd.New(path)
	if err := pf.Set("device-7", "hunter2"); err != nil {
		t.Fatalf("set: %v", err)
	}
	if err := pf.Save(); err != nil {
		t.Fatalf("save: %v", err)
	}
	users, err := passwd.Load(path)
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	const badCredential = 0x86 // ErrBadUsernameOrPassword

	// The broker as a whole demands a credential.
	h.B.SetCredentials(users, false)
	if got := connectAs(t, h, "no-cred-broker", "", ""); got != badCredential {
		t.Fatalf("with only the broker-wide pair set, an anonymous client answered 0x%02X, "+
			"want 0x86 - the rest of this test means nothing if that is not refused", got)
	}

	// This listener says otherwise. "t" is the id the harness opens its TCP
	// listener under, and the id is the only thing a CONNECT carries that
	// says which door it came through.
	h.B.SetListenerCredentials("t", nil, true)
	if got := connectAs(t, h, "no-cred-listener", "", ""); got != 0 {
		t.Errorf("the listener allows anonymous connections and one was refused 0x%02X, "+
			"so the listener's answer never reached the decision", got)
	}

	// And back the other way, so the override is a value being read rather
	// than a flag that only ever loosens.
	h.B.SetListenerCredentials("t", users, false)
	if got := connectAs(t, h, "tight-again", "", ""); got != badCredential {
		t.Errorf("the listener demands a credential and an anonymous client answered "+
			"0x%02X, want 0x86", got)
	}
	if got := connectAs(t, h, "right-again", "device-7", "hunter2"); got != 0 {
		t.Errorf("the right credential was refused with 0x%02X on the listener that "+
			"names the file holding it", got)
	}
}

// **A dead-lettered record carries the publisher's publish properties**,
// which is what RFC 0003 promises and where they matter most: the reply
// address and correlation of a job that failed, at the channel somebody
// reads to find out what failed.
//
// The queue delivery is the one place the publisher's Response Topic and
// Correlation Data are held back, because saguin's own pair carries the
// worker's reply address and the Delivery ID. The dead-letter channel is an
// ordinary `append` channel with nothing to collide with, so they come
// back - and `deadLettered` builds its record field by field, which is
// exactly the shape that keeps only what somebody remembered to list.
//
// Both halves are asserted together on purpose. A test that checked only
// the worker's delivery passes against a broker that drops them at the
// move, which is how this reached a release.
func TestADeadLetteredRecordKeepsThePublishersProperties(t *testing.T) {
	h := start(t)

	dlq := dialProps(t, h, "dlq-reader")
	if _, err := dlq.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "jobs/__dlq/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe to the dead-letter channel: %v", err)
	}

	// A worker that returns every job, so the record exhausts its attempts.
	w := connect(t, h, "worker", true, false)
	w.OnJob = func(payload string, answer func(string)) { answer("return") }
	w.Sub(t, "$saguin/queue/jobs", 1)

	pub := dialProps(t, h, "producer")
	expiry := uint32(3600)
	format := byte(1)
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/a", QoS: 1, Payload: []byte(`{"job":1}`),
		Properties: &paho.PublishProperties{
			ContentType:     "application/json",
			CorrelationData: []byte("corr-42"),
			ResponseTopic:   "replies/here",
			MessageExpiry:   &expiry,
			PayloadFormat:   &format,
		},
	}); err != nil {
		t.Fatalf("publish the job: %v", err)
	}

	got := awaitProp(t, dlq)
	if got == nil || got.Properties == nil {
		t.Fatal("nothing reached the dead-letter channel, so this asserts nothing")
	}
	p := got.Properties

	if p.ContentType != "application/json" {
		t.Errorf("content type %q, want application/json", p.ContentType)
	}
	if p.ResponseTopic != "replies/here" {
		t.Errorf("response topic %q, want the publisher's replies/here - the reply "+
			"address of a failed job is lost at the one channel that exists to be "+
			"read after it failed", p.ResponseTopic)
	}
	if string(p.CorrelationData) != "corr-42" {
		t.Errorf("correlation data %q, want corr-42 - nothing ties the dead-lettered "+
			"record back to the request that produced it", p.CorrelationData)
	}
	if p.PayloadFormat == nil || *p.PayloadFormat != 1 {
		t.Errorf("payload format %v, want 1", p.PayloadFormat)
	}
	if p.MessageExpiry == nil {
		t.Error("no message expiry reached the dead-letter channel")
	} else if *p.MessageExpiry > expiry {
		t.Errorf("message expiry %d, above the %d published", *p.MessageExpiry, expiry)
	}

	// The dead-letter metadata is still there beside them, so the properties
	// were added to the record rather than in place of anything.
	var reason string
	for _, u := range p.User {
		if u.Key == "saguin-dlq-reason" {
			reason = u.Value
		}
	}
	if reason != "attempts_exhausted" {
		t.Errorf("saguin-dlq-reason is %q, want attempts_exhausted", reason)
	}
}

// **The expiry sweep works on a database, not only in memory** - and the
// distinction is the whole finding: every SQLite store is wrapped for
// metrics, and a wrapper cannot answer the question the SQLite queue asks
// its dead-letter log.
//
// The move out of a queue is one transaction or it is neither half
// (invariant 5), so the queue asks the log by type assertion whether it can
// be written inside that transaction. `releaseWith` unwraps before asking;
// the sweep did not, so on SQLite every sweep failed. It logged an ERROR and
// counted a storage error once per tick - from the first sweep, on an empty
// queue, before anything was published - and a job with no worker was held
// until one connected, which is the one case the sweep exists for.
//
// **The counter is asserted as well as the record**, because the failure
// reported itself as a disk problem: an operator alerting on
// `saguin_storage_errors_total`, which RFC 0005 gives them for a failing
// disk, got it from a healthy one.
//
// The memory version of this test passed throughout, which is why this one
// runs on a database.
func TestTheExpirySweepWorksOnADatabase(t *testing.T) {
	// The broker's own lines, because the failure announced itself there
	// once per sweep and the counter behind saguin_storage_errors_total is
	// not reachable from outside this package.
	var mu sync.Mutex
	var logged strings.Builder
	brokertest.LogTo = func(line string) {
		mu.Lock()
		defer mu.Unlock()
		logged.WriteString(line)
	}
	t.Cleanup(func() { brokertest.LogTo = nil })

	h := startExpiringOnSQLite(t, 1, filepath.Join(t.TempDir(), "saguin.db"))

	dlq := connect(t, h, "dlq-reader", true, false)
	dlq.Sub(t, "jobs/__dlq/#", 1)

	// No worker anywhere: the job can only leave the queue by ageing out,
	// which is the path the sweep owns.
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "jobs/stale", "nobody is coming")

	r, ok := dlq.Await(t, 20*time.Second)
	if !ok {
		t.Fatal("a job with no worker was never dead-lettered on a database; the sweep " +
			"is the only thing that could move it, and on SQLite it was failing every " +
			"tick with the dead-letter log wrapped for metrics")
	}
	if r.Payload != "nobody is coming" {
		t.Errorf("dead-lettered payload %q", r.Payload)
	}
	if got := r.User["saguin-dlq-reason"]; got != "expired" {
		t.Errorf("dead-lettered for reason %q, want expired - a job that aged out with "+
			"no worker attached did not come through the sweep", got)
	}

	// And the sweep never reported a storage failure. This is the half that
	// makes the defect operational rather than merely quiet: the error was
	// counted into saguin_storage_errors_total, which RFC 0005 gives an
	// operator for a failing disk, once per tick on a healthy one.
	mu.Lock()
	out := logged.String()
	mu.Unlock()
	// **It has to prove it read something first.** An assertion that a
	// string is absent passes against an empty log, so a handler that never
	// attached - a shape that has happened, where `-v` replaced one
	// silently and the test read zero lines and passed for the wrong reason
	// - would report this half as covered. A broker that started writes a
	// good deal more than three lines at info.
	if n := strings.Count(out, "\n"); n < 3 {
		t.Fatalf("the log handler read %d lines, which is too few to believe - the "+
			"absence checked below would be absent from an empty log too", n)
	}
	if strings.Contains(out, "cannot expire waiting jobs") {
		t.Errorf("the sweep reported a storage failure on a healthy database, which is "+
			"what an operator alerting on a failing disk would be woken by:\n%s", out)
	}
}

// **A dead-lettered record's Message Expiry is what is left of it**, not
// what the publisher wrote.
//
// RFC 0003: the interval is delivered decremented by the time the record has
// waited. The dead-letter move builds a new record stamped with the moment
// of the move, so copying the publisher's interval onto it starts the clock
// again - a job that spent most of its life in the queue arrives in the
// dead-letter channel claiming a full interval, and a consumer reading it to
// find out what failed is told the failure is fresher than it is.
//
// Asserted against the queue delivery in the same run, because the two are
// the same number seen twice: what the worker was told is the ceiling for
// what the dead-letter channel may say.
func TestADeadLetteredRecordCarriesWhatIsLeftOfItsExpiry(t *testing.T) {
	h := startExpiring(t, 0) // no sweep; this job dies by attempts
	dlq := dialProps(t, h, "dlq-reader")
	if _, err := dlq.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "jobs/__dlq/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe: %v", err)
	}

	pub := dialProps(t, h, "producer")
	expiry := uint32(3600)
	if _, err := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "jobs/slow", QoS: 1, Payload: []byte("body"),
		Properties: &paho.PublishProperties{MessageExpiry: &expiry},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}

	// **The record has to age before anybody moves it**, because MQTT
	// carries the interval in whole seconds: a job published and
	// dead-lettered inside one second has lost nothing to round down, and
	// the assertion below would pass against a broker that restarts the
	// clock. So the worker arrives late and the record is already old.
	const aged = 2 * time.Second
	time.Sleep(aged)

	// Returns every job, so the record spends its attempts and is moved.
	w := connect(t, h, "worker", true, false)
	w.OnJob = func(payload string, answer func(string)) { answer("return") }
	w.Sub(t, "$saguin/queue/jobs", 1)

	got := awaitProp(t, dlq)
	if got == nil || got.Properties == nil {
		t.Fatal("nothing was dead-lettered, so this asserts nothing")
	}
	if got.Properties.MessageExpiry == nil {
		t.Fatal("the dead-lettered record carries no message expiry at all")
	}
	// At least the two seconds it was left to age, and one-sided: a slower
	// machine takes longer and the remaining interval only falls further.
	// Equal to the published value means the clock restarted at the move.
	want := expiry - uint32(aged/time.Second)
	if left := *got.Properties.MessageExpiry; left > want {
		t.Errorf("the dead-lettered record claims %d seconds of a %d-second expiry after "+
			"ageing %v in the queue, want at most %d - the clock restarted at the move, "+
			"so a consumer reading the dead-letter channel is told the failure is "+
			"fresher than it is", left, expiry, aged, want)
	}
}

// **A job a departing worker was holding goes back to the queue**, so the
// next worker gets it without anybody reconnecting.
//
// **What this does not prove, stated because it is easy to assume it does.**
// It does not show that `linkCut` waits for saguin's `OnDisconnect` rather
// than for the socket. The substrate calls `cl.Stop` before the disconnect
// hooks, so `cl.Closed()` goes true while the job is still held (measured at twelve early
// returns in 1,200 rounds) - and this test cannot see the difference: the wait below is generous
// enough that a `linkCut` returning early still finds the job back by the
// time it looks. Mutated to the old signal, it passed 250 rounds.
//
// That ordering is structural rather than testable here. `broker.NewServer`
// registers saguin's hook, the harness registers its own afterwards, and the
// substrate runs them in the order they were added, so the hook `linkCut`
// waits on cannot fire before saguin's has returned. A test that reordered
// them would be caught by that construction breaking, not by this.
func TestCuttingALinkWaitsForTheBrokerToReleaseTheJob(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	// A worker that takes the job and never answers.
	held := make(chan struct{}, 1)
	w := connect(t, h, "worker-holds", true, false)
	w.OnJob = func(payload string, answer func(string)) {
		select {
		case held <- struct{}{}:
		default:
		}
	}
	w.Sub(t, "$saguin/queue/jobs", 1)
	p.Pub(t, "jobs/one", "work")

	select {
	case <-held:
	case <-time.After(5 * time.Second):
		t.Fatal("the worker was never offered the job, so nothing is being held")
	}

	// A second worker, waiting. The job is with the first one, so nothing
	// reaches this until the first session ends.
	next := connect(t, h, "worker-next", true, false)
	next.Sub(t, "$saguin/queue/jobs", 1)

	linkCut(t, w)

	// The job comes back in saguin's OnDisconnect. Three seconds is slack
	// rather than precision - see the note above about what that costs this
	// test's reach.
	if _, ok := next.Await(t, 3*time.Second); !ok {
		t.Error("the job was not back with the queue when linkCut returned, so the wait " +
			"ended before saguin had finished with the session - which is what a wait " +
			"on cl.Closed() does")
	}
}

// RFC 0002 "Roles, and users matched by pattern": `%u` stands for the
// client's identity, and a rule naming a **topic** takes it exactly as one
// naming a suffix does.
//
// **Driven on the wire, because everywhere else the defect was invisible.**
// When only the suffix was substituted, this file loaded, `--check-config`
// reported ok, and `--acl explain` printed the rule with a literal `%u` in
// it - which reads as a grant that is there. The one place it showed was a
// device refused 0x87 for the topic its operator had granted on purpose,
// with the same code a real refusal carries.
func TestATopicRuleFollowsTheClientIdentity(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  alerting:
    - topic: alerts/%u/#
      allow: [write, read]
users:
  "device-*": [alerting]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	c := connectNamed(t, h, "device-7", "device-7")
	pub := func(topic string) byte {
		t.Helper()
		ack, err := c.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Payload: []byte("x"),
		})
		if ack == nil {
			t.Fatalf("publish %s: no acknowledgement: %v", topic, err)
		}
		return ack.ReasonCode
	}
	sub := func(filter string) byte {
		t.Helper()
		sa, err := c.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{{Topic: filter, QoS: 1}},
		})
		if sa == nil {
			t.Fatalf("subscribe %s: no SUBACK at all: %v", filter, err)
		}
		return sa.Reasons[0]
	}

	if got := pub("alerts/device-7/fire"); got != 0 {
		t.Errorf("a publish to the topic this client's own rule names was answered "+
			"0x%02X, want 0x00: %%u is the identity the broker holds for it, and a "+
			"topic rule takes the substitution as a suffix does", got)
	}
	if got := sub("alerts/device-7/#"); got > 2 {
		t.Errorf("a subscription the same rule grants was refused 0x%02X", got)
	}

	// The direction that discriminates: a rule scoped by identity that
	// grants the whole prefix has granted the fleet, and would pass every
	// assertion above.
	if got := pub("alerts/device-8/fire"); got != 0x87 {
		t.Errorf("a publish to another device's topic was answered 0x%02X, want 0x87: "+
			"the substitution is the whole of what scopes this rule", got)
	}
	if got := sub("alerts/device-8/#"); got != 0x87 {
		t.Errorf("a subscription to another device's topic was granted 0x%02X, want "+
			"0x87", got)
	}

	// And the literal is not a back door. Before the fix this was the only
	// thing the rule matched, so a client publishing the substitution
	// unexpanded was the one client it worked for.
	if got := pub("alerts/%u/fire"); got != 0x87 {
		t.Errorf("a publish to the unsubstituted topic was answered 0x%02X, want 0x87: "+
			"%%u is what the rule means, not a topic level anybody may claim", got)
	}
}

// **A filter reaching channels and broadcast is granted whole or refused**
// (RFC 0002 "Three rule kinds"). `+/x` touches all three of the harness's
// channels and every broadcast topic `<anything>/x`. Granted on its
// channels alone it was answered 0x01, and `other/x` was published and
// never delivered, with nothing logged. The same role with a topic rule is
// granted it and receives `other/x`; and `events/#`, inside one channel, is
// granted on that channel alone - so a rule demanding a topic grant of
// every wildcard fails here too.
func TestAFilterReachingBroadcastNeedsTheTopicRuleAsWell(t *testing.T) {
	for _, tc := range []struct {
		why      string
		topic    string
		want     byte
		receives bool
	}{
		{"channel rules alone", "", 0x87, false},
		{"channel rules and a topic rule", "    - topic: \"#\"\n      allow: [read]\n", 0x01, true},
	} {
		t.Run(tc.why, func(t *testing.T) {
			h := start(t)
			acl := filepath.Join(t.TempDir(), "acl.yaml")
			if err := os.WriteFile(acl, []byte("roles:\n  reader:\n"+
				"    - channel: events\n      allow: [read]\n"+
				"    - channel: state\n      allow: [read]\n"+
				"    - channel: jobs\n      allow: [consume]\n"+tc.topic+
				"  publisher:\n    - topic: \"#\"\n      allow: [write]\n"+
				"users:\n  reader: [reader]\n  publisher: [publisher]\n"), 0o600); err != nil {
				t.Fatalf("write acl: %v", err)
			}
			f, err := authz.Load(acl, h.B.Registry(), 0)
			if err != nil {
				t.Fatalf("load acl: %v", err)
			}
			h.B.Authorize(authz.New(f, h.B.Registry()))

			got := make(chan string, 4)
			r := connectNamed(t, h, "r", "reader")
			r.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
				got <- pr.Packet.Topic
				return true, nil
			})
			sub := func(filter string) byte {
				t.Helper()
				sa, err := r.Subscribe(context.Background(), &paho.Subscribe{
					Subscriptions: []paho.SubscribeOptions{{Topic: filter, QoS: 1}},
				})
				if sa == nil {
					t.Fatalf("subscribe %s: no SUBACK at all: %v", filter, err)
				}
				return sa.Reasons[0]
			}
			if code := sub("events/#"); code != 0x01 {
				t.Errorf("events/#, inside the events channel, was answered 0x%02X, want 0x01 "+
					"on the channel rule alone", code)
			}
			if code := sub("+/x"); code != tc.want {
				t.Fatalf("+/x, reaching three channels and every broadcast <anything>/x, was "+
					"answered 0x%02X, want 0x%02X", code, tc.want)
			}

			p := connectNamed(t, h, "p", "publisher")
			ack, err := p.Publish(context.Background(), &paho.Publish{Topic: "other/x", QoS: 1, Payload: []byte("v")})
			if ack == nil || ack.ReasonCode != 0 {
				t.Fatalf("the publisher's other/x was not accepted: %v %v", ack, err)
			}
			select {
			case topic := <-got:
				if !tc.receives {
					t.Errorf("received %q with the subscription refused", topic)
				}
			case <-time.After(2 * time.Second):
				if tc.receives {
					t.Error("other/x was published under a granted +/x and never delivered")
				}
			}
		})
	}
}

// RFC 0005 `saguin_deliveries_dropped_total`, invariant 13.
//
// **This is the broadcast half, and broadcast is all this counter covers.**
// A channel consumer that stops reading is disconnected under
// `limits.write_timeout` instead, because it has a stored position to
// resume from and dropping would throw away records a reconnect would
// replay - TestADeafConsumerCannotHoldAPublisher is that half. Broadcast
// keeps no position, so there is nothing to resume and dropping is the
// honest answer.
//
// **A subscriber that stops reading its socket is shed rather than
// served**, and the shedding is visible. The bound was always there - a client's
// outbound queue is MaximumClientWritesPending packets and the substrate
// discards past it, which is what keeps one slow consumer from becoming a
// dead broker. What was missing was any way to know from outside, so a
// fleet could shed for a week in silence.
//
// **Driven rather than poked.** The counter is trivial to assert by adding
// to it, and that tests the render and nothing else - the question here is
// whether the hook is reached at all, which needs a real consumer that has
// really stopped reading. The harness's hold does that: the receive
// handler never returns, so paho never drains the socket, the kernel
// buffer fills, the broker's writer blocks and the queue behind it fills.
//
// QoS 0 on purpose. At QoS 1 the client's Receive Maximum stops the broker
// long before the queue fills - it would sit at the flow-control window
// politely and never drop anything, so the test would pass against a
// broker with no bound at all.
func TestASlowConsumerIsShedAndCounted(t *testing.T) {
	h := start(t)

	// **A raw socket, because a client library will not stop reading.**
	// The harness's hold stalls the acknowledgement and not the read: paho
	// drains the socket into its own buffers whatever the handler is doing,
	// so a held consumer absorbed 61MB without the broker ever backing up,
	// and the first version of this test reported a broker that dropped
	// nothing when nothing had been offered to drop. What fills a client's
	// outbound queue is a socket nobody is reading, and the only way to
	// have one is to do the handshake by hand and then stop.
	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()

	send := func(p pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = p
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID:        "deaf",
		CleanStart:      true,
		KeepAlive:       0,
		ProtocolName:    "MQTT",
		ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	ca, err := pahopackets.ReadPacket(conn)
	if err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	}
	if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}

	send(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "loose/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	sa, err := pahopackets.ReadPacket(conn)
	if err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	}
	if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got > 2 {
		t.Fatalf("the subscription was refused 0x%02X", got)
	}

	// From here the socket is never read again, which is the whole point.

	p := connect(t, h, "firehose", true, false)

	// QoS 0 on purpose. At QoS 1 the client's Receive Maximum stops the
	// broker long before its queue fills - it would sit at the flow-control
	// window politely and drop nothing, so this would pass against a broker
	// with no bound at all.
	//
	// 4KiB a packet and 15,000 of them: the queue is 8,192 deep, so this is
	// well past it even after the kernel has buffered what it will.
	payload := strings.Repeat("x", 4096)
	const flood = 15000
	sent := 0
	for i := 0; i < flood; i++ {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/x", QoS: 0, Payload: []byte(payload),
		}); err != nil {
			break
		}
		sent++
	}

	// Read from /metrics rather than from the tally, because the tally
	// moving is not what was missing - an operator being able to see it is,
	// and this is that surface.
	line := awaitScrape(t, h, "saguin_deliveries_dropped_total", 30*time.Second)
	if strings.HasSuffix(line, " 0") {
		t.Fatalf("a consumer that stopped reading its socket was sent %d packets of "+
			"%d bytes and the scrape still says %q: either the bound is not being "+
			"reached or the hook is not wired to it, and a metric stuck at zero "+
			"looks the same either way", sent, len(payload), line)
	}
	t.Logf("%s after %d packets", line, sent)

	// **And it is hung up on as well, once the socket stops taking writes.**
	// This flood is fast enough to finish inside `limits.write_timeout`, so
	// the shedding above is all it can show - and reading that as the whole
	// rule is exactly what happened: three documents came to say a QoS 0
	// broadcast subscriber stays connected. Dropping is what replaces
	// buffering, never what replaces the deadline.
	// TestADeafBroadcastSubscriberIsShedAndThenDisconnected drives the
	// second half, because it needs a publisher that keeps going past the
	// deadline rather than one that stops.
	if h.Disconnects.Count("deaf") != 0 {
		t.Logf("note: the flood outlasted write_timeout here, so this consumer was hung " +
			"up on too - which is correct, and the sibling test is what asserts it")
	}
}

// RFC 0003 "broadcast", RFC 0002 "write_timeout", invariant 16.
//
// **A deaf QoS 0 broadcast subscriber is shed *and then* disconnected**,
// and the second half is what three documents got wrong. The test above
// publishes a fixed number of packets as fast as it can, which finishes
// inside the five-second write deadline - so it sees the drops, and nothing
// in the suite held the claim that the client stays connected. It does not.
//
// The publisher here is bounded by the clock rather than by a count, which
// is the whole difference: it keeps going until the deadline has had time
// to fire.
func TestADeafBroadcastSubscriberIsShedAndThenDisconnected(t *testing.T) {
	h := start(t)

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	send := func(p pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = p
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID: "deaf-for-longer", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5, Properties: &pahopackets.Properties{},
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	send(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "loose/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	if _, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	}
	// From here the socket is never read.

	p := connect(t, h, "firehose", true, false)
	payload := strings.Repeat("x", 4096)
	// Past the default write_timeout of 5s, with room for the deadline to
	// fire and the disconnect to be recorded.
	deadline := time.Now().Add(9 * time.Second)
	sent := 0
	for time.Now().Before(deadline) {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/x", QoS: 0, Payload: []byte(payload),
		}); err != nil {
			break
		}
		sent++
	}
	if sent == 0 {
		t.Fatal("nothing was published, so nothing was offered to the deaf subscriber")
	}

	if got := h.Disconnects.Count("deaf-for-longer"); got == 0 {
		t.Fatalf("a QoS 0 broadcast subscriber stopped reading its socket, %d packets were "+
			"published at it over nine seconds, and the broker never hung up on it: "+
			"dropping is what replaces buffering, not what replaces write_timeout", sent)
	}
	line := awaitScrape(t, h, "saguin_deliveries_dropped_total", 30*time.Second)
	if strings.HasSuffix(line, " 0") {
		t.Errorf("%q: it was disconnected without anything being shed first, so the two "+
			"bounds are not both reaching it", line)
	}
	t.Logf("shed and hung up on after %d packets: %s", sent, strings.TrimSpace(line))
}

// A client that goes away is logged with its whole packet, payload
// included: driven rather than reasoned about.
//
// **This is the ordinary case, not a corner.** A publisher whose socket has
// gone while the broker is writing its PUBACK produces an error that is not
// a `packets.Code`, and the substrate logs the whole packet struct for
// those - 2,409 bytes for a 36-byte payload, with `Payload:[80 65 84 …]` in
// it byte for byte and the `Connect` struct's `Password` field beside it.
// Devices sleep, radios drop, gateways reboot; this is what a broker does
// all day.
//
// **Winning the race is the work here.** Closing the socket politely is not
// enough - the broker reads EOF first and takes a different path, which is
// what the first version of this did and it reported nothing wrong. Two
// hundred publishes in flight and `SetLinger(0)` so the close is a reset:
// one of the acknowledgements then lands on a connection that is already
// gone. The test says so rather than passing quietly if it never fires.
func TestAVanishingPublisherIsNotLoggedWithItsPayload(t *testing.T) {
	const secret = "PATIENT-42-BLOODPRESSURE-160-OVER-95"

	var mu sync.Mutex
	var lines []string
	h := startLogging(t, func(l string) {
		mu.Lock()
		lines = append(lines, l)
		mu.Unlock()
	})

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	send := func(p pahopackets.Packet, kind byte) {
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = p
		_, _ = cp.WriteTo(conn)
	}
	send(&pahopackets.Connect{
		ClientID: "vanishing", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
		Properties: &pahopackets.Properties{},
	}, pahopackets.CONNECT)
	if _, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	}
	for i := 0; i < 200; i++ {
		send(&pahopackets.Publish{
			Topic: "sensors/ward-3", QoS: 1, PacketID: uint16(i + 1),
			Payload: []byte(secret), Properties: &pahopackets.Properties{},
		}, pahopackets.PUBLISH)
	}
	if tc, ok := conn.(*net.TCPConn); ok {
		// A reset rather than a graceful close, so the broker's write fails
		// instead of draining into a socket that is politely shutting down.
		_ = tc.SetLinger(0)
	}
	_ = conn.Close()
	// Read until the failed write is logged, which is the line this is
	// about; the check below still fails if it never is.
	waitUntil(5*time.Second, func() bool {
		mu.Lock()
		defer mu.Unlock()
		for _, l := range lines {
			if strings.Contains(l, "error processing packet") {
				return true
			}
		}
		return false
	})

	mu.Lock()
	defer mu.Unlock()

	// **It proves it drove something.** A test that never reached the
	// branch would pass every assertion below by reading nothing.
	fired := false
	for _, l := range lines {
		if strings.Contains(l, "error processing packet") {
			fired = true
			if len(l) > 512 {
				t.Errorf("the line is %d bytes:\n%s", len(l), l)
			}
			if !strings.Contains(l, "payload=36 bytes") {
				t.Errorf("the line does not say how big the payload was, which is the "+
					"diagnostic the dump was hiding:\n%s", l)
			}
		}
	}
	if !fired {
		t.Skip("the write never landed on the broken connection; nothing to assert about")
	}

	// The payload renders as decimal bytes inside a struct dump, so that is
	// what to look for rather than the text.
	var decimal []string
	for _, b := range []byte(secret) {
		decimal = append(decimal, strconv.Itoa(int(b)))
	}
	whole := strings.Join(lines, "\n")
	if strings.Contains(whole, strings.Join(decimal, " ")) {
		t.Error("the application payload reached the operator's log")
	}
	// The first seven bytes are enough to catch a partial dump too.
	if strings.Contains(whole, strings.Join(decimal[:7], " ")) {
		t.Error("part of the application payload reached the operator's log")
	}
}

// RFC 0002 `limits.session_queue_bytes` and `limits.write_timeout`, RFC 0003
// "broadcast", RFC 0005 `saguin_deliveries_dropped_total`.
//
// **The other half of the test above.** RFC 0005 splits a slow broadcast
// subscriber by the QoS it is served at: QoS 0 is shed from the outbound
// queue, and everything else is held within its session's bound and never
// reaches that queue. The test above drives the shedding; this drives a
// subscriber granted QoS 1 that stops reading.
//
// **Within a bound its socket absorbs, it stays connected.** No more than
// half the bound is written to it, the kernel takes that without blocking,
// and the write deadline has nothing to time. It holds no more than the
// bound, and once it reads again it is sent the newest of what it missed,
// with every message it never receives counted. **Past what its socket
// absorbs, it is hung up on**: a write blocks, and the deadline ends it.
//
// **The publisher publishes at QoS 1 on purpose.** A delivery goes out at
// the lower of the publish and the grant, so a QoS 0 publish to a QoS 1
// subscriber is a QoS 0 delivery - the first version of this test did that
// and measured the shedding path a second time.
//
// **And the socket is not read, not even to find out.** Reading to see
// whether the connection closed drains what is supposed to be filling, so
// the oracle is the broker's own disconnect hook.
func TestADeafBroadcastSubscriberAtQoS1HoldsItsBoundAndIsHungUpOnWhenItsSocketFills(t *testing.T) {
	deaf := func(t *testing.T, network, addr, id string) net.Conn {
		t.Helper()
		conn, err := net.Dial(network, addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		t.Cleanup(func() { _ = conn.Close() })
		send := func(p pahopackets.Packet, kind byte) {
			t.Helper()
			cp := pahopackets.NewControlPacket(kind)
			cp.Content = p
			if _, err := cp.WriteTo(conn); err != nil {
				t.Fatalf("write %d: %v", kind, err)
			}
		}
		send(&pahopackets.Connect{
			ClientID:        id,
			CleanStart:      true,
			KeepAlive:       0,
			ProtocolName:    "MQTT",
			ProtocolVersion: 5,
			Properties:      &pahopackets.Properties{},
		}, pahopackets.CONNECT)
		ca, err := pahopackets.ReadPacket(conn)
		if err != nil {
			t.Fatalf("read the CONNACK: %v", err)
		}
		if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
			t.Fatalf("connect refused 0x%02X", got)
		}
		send(&pahopackets.Subscribe{
			PacketID:      1,
			Subscriptions: []pahopackets.SubOptions{{Topic: "loose/#", QoS: 1}},
		}, pahopackets.SUBSCRIBE)
		sa, err := pahopackets.ReadPacket(conn)
		if err != nil {
			t.Fatalf("read the SUBACK: %v", err)
		}
		if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got != 1 {
			t.Fatalf("the subscription was answered 0x%02X, want 0x01 granted at QoS 1", got)
		}
		return conn
	}
	pad := strings.Repeat("x", 4096)

	t.Run("a bound its socket absorbs keeps it connected with the newest", func(t *testing.T) {
		const (
			bound     = 1 << 20
			published = 2000
		)
		brokertest.SessionQueueBytes = bound
		t.Cleanup(func() { brokertest.SessionQueueBytes = 0 })
		h := start(t)
		ops := operationsAt(t, h)
		conn := deaf(t, h.Network, h.Addr, "deaf-within")

		p := connect(t, h, "firehose-within", true, false)
		for i := 1; i <= published; i++ {
			pa, err := p.C.Publish(context.Background(), &paho.Publish{
				Topic: "loose/x", QoS: 1, Payload: []byte(strconv.Itoa(i) + " " + pad),
			})
			if err != nil || pa.ReasonCode != 0 {
				t.Fatalf("publish %d was not accepted: %v %v", i, err, pa)
			}
		}
		cl, ok := h.Srv.Clients.Get("deaf-within")
		if !ok {
			t.Fatal("the deaf subscriber is not connected after the flood")
		}

		wait := brokertest.WriteDeadline + time.Second
		if brokertest.WriteDeadline <= 0 {
			wait = 6 * time.Second
		}
		time.Sleep(wait)
		if n := h.Disconnects.Count("deaf-within"); n != 0 {
			t.Fatalf("a subscriber holding no more than its %d-byte bound was hung up on", bound)
		}
		held, kept := cl.State.Inflight.Bytes(), int(cl.State.Inflight.Messages())
		if held > bound {
			t.Errorf("the session holds %d bytes against a bound of %d", held, bound)
		}
		dropped := scrapeGauges(t, ops)[`saguin_session_deliveries_dropped_total{cause="session_queue_full"}`]
		if dropped == 0 {
			t.Fatal("nothing was given up, so the bound was never reached and this says nothing about it")
		}
		if dropped != float64(published-kept) {
			t.Errorf("session_queue_full is %v, and %d of %d published are not in the session", dropped, published-kept, published)
		}

		// Recovered: it reads and acknowledges everything.
		var got []int
		for {
			_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
			cp, err := pahopackets.ReadPacket(conn)
			if err != nil {
				break
			}
			pub, ok := cp.Content.(*pahopackets.Publish)
			if !ok {
				continue
			}
			number, _, _ := strings.Cut(string(pub.Payload), " ")
			n, _ := strconv.Atoi(number)
			got = append(got, n)
			ack := pahopackets.NewControlPacket(pahopackets.PUBACK)
			ack.Content.(*pahopackets.Puback).PacketID = pub.PacketID
			if _, err := ack.WriteTo(conn); err != nil {
				t.Fatalf("write PUBACK: %v", err)
			}
		}
		if len(got) != kept {
			t.Errorf("recovered, it was sent %d messages, and its session held %d", len(got), kept)
		}
		// The oldest it was written, 1 onwards, then the newest, through the last.
		gap := 1
		for gap < len(got) && got[gap] == got[gap-1]+1 {
			gap++
		}
		if len(got) == 0 || got[0] != 1 {
			t.Fatalf("recovered, the first message it was sent is not 1: %v", got[:min(len(got), 5)])
		}
		for k := gap; k < len(got); k++ {
			if want := published - (len(got) - gap) + 1 + (k - gap); got[k] != want {
				t.Fatalf("recovered, after the oldest 1 to %d it was sent message %d at %d, want %d: the newest are kept, in order", gap, got[k], k, want)
			}
		}
		if got[len(got)-1] != published {
			t.Errorf("recovered, the last message it was sent is %d, want %d", got[len(got)-1], published)
		}
		t.Logf("recovered to messages 1 to %d and %d to %d, %v given up", gap, published-(len(got)-gap)+1, published, dropped)
	})

	t.Run("a bound past its socket hangs it up", func(t *testing.T) {
		brokertest.SessionQueueBytes = 256 << 20
		t.Cleanup(func() { brokertest.SessionQueueBytes = 0 })
		h := start(t)
		deaf(t, h.Network, h.Addr, "deaf-past")

		p := connect(t, h, "firehose-past", true, false)
		const flood = 15000
		sent := 0
		for i := 0; i < flood; i++ {
			if _, err := p.C.Publish(context.Background(), &paho.Publish{
				Topic: "loose/x", QoS: 1, Payload: []byte(pad),
			}); err != nil {
				break
			}
			sent++
		}
		if sent == 0 {
			t.Fatal("nothing was published, so nothing was offered to the deaf subscriber")
		}

		deadline := time.Now().Add(30 * time.Second)
		for h.Disconnects.Count("deaf-past") == 0 && time.Now().Before(deadline) {
			time.Sleep(100 * time.Millisecond)
		}
		if h.Disconnects.Count("deaf-past") == 0 {
			t.Fatalf("a broadcast subscriber granted QoS 1 stopped reading its socket, %d packets "+
				"of %d bytes were published at it within a bound larger than its socket takes, "+
				"and the write deadline never hung up on it", sent, len(pad))
		}

		// And it was hung up on rather than shed.
		line := awaitScrape(t, h, "saguin_deliveries_dropped_total", 10*time.Second)
		if !strings.HasSuffix(line, " 0") {
			t.Errorf("%q: a QoS 1 subscriber was disconnected *and* something was shed, so the "+
				"split RFC 0005 states is not the one the broker keeps", line)
		}
		t.Logf("hung up on after %d packets, and %s", sent, line)
	})
}

// RFC 0005 `saguin_deliveries_expired_total`.
//
// **A delivery the publisher put a clock on, and the clock ran out before
// the delivery was sent.** MQTT-3.3.2-5: a Message Expiry Interval that
// passes before a message is forwarded means it is not forwarded. That is
// the publisher's own instruction being carried out, which is exactly why it
// is a separate number from the drops above - an operator does nothing about
// these, and added to the drops they would hide a consumer that was failing.
//
// **And one already sent is not expired**, whatever its session: the
// sender of a QoS 2 PUBLISH must not apply message expiry once it is sent
// (MQTT-4.3.3-7), and RFC 0005 counts only what expired unsent. This test
// used to hold that a sent, unacknowledged delivery to a session ending with
// its connection is discarded by expiry and counted; that was the RFC's rule
// and the RFC was wrong, so the oracle is now the corrected row: the
// delivery on the wire stays until it is acknowledged, and the one behind it
// that the client's window never admitted is the one counted.
//
// The harness's hold is the right instrument here, where it was the wrong
// one for the drops: it stalls the acknowledgement, which keeps the window
// of one full. Paho sends the PUBACK when the handler returns, so a handler
// that has not returned is a delivery in flight.
func TestADeliveryThatExpiresInFlightIsCounted(t *testing.T) {
	h := start(t)

	// A session that ends with its connection, whose deliveries are held in
	// its client's in-flight table; one that outlives it is served from the
	// broadcast log (TestAMessageThatExpiresWhileItWaitsIsSkippedAndCountedOnce).
	// A window of one, so the second delivery waits unsent behind the first.
	c := brokertest.Dial(t, h, "dawdler", true, false, 1, 0, 0)
	hold := make(chan struct{})
	c.Hold, c.HoldPayload = hold, "on the wire"
	var once sync.Once
	release := func() { once.Do(func() { close(hold) }) }
	defer release()

	if sa := c.Sub(t, "loose/#", 1); sa.Reasons[0] > 2 {
		t.Fatalf("the subscription was refused 0x%02X", sa.Reasons[0])
	}

	p := connect(t, h, "impatient", true, false)
	expiry := uint32(1)
	for _, payload := range []string{"on the wire", "never sent"} {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/x", QoS: 1, Payload: []byte(payload),
			Properties: &paho.PublishProperties{MessageExpiry: &expiry},
		}); err != nil {
			t.Fatalf("publish: %v", err)
		}
	}
	if !waitUntil(3*time.Second, func() bool { return c.Count() == 1 }) {
		t.Fatalf("the consumer received %d, want the first delivery on the wire", c.Count())
	}
	dawdler, ok := h.Srv.Clients.Get("dawdler")
	if !ok {
		t.Fatal("the consumer is not connected")
	}

	// One second of expiry, and the substrate sweeps for them once a
	// second, so this is two ticks rather than one - a deadline only just
	// past the interval is a test that fails on a slow morning. The second
	// is published after the first, so when it has expired the first's
	// deadline has passed too, and a sweep that expired sent deliveries took
	// both in the same pass.
	// **Exactly one, not merely non-zero.** The first version of this test
	// asserted "not zero" and passed against a counter that read 7 for this
	// one expiry: the substrate fires the hook from Client.ClearExpiredInflights
	// and then again from Server.clearExpiredInflights for the same packet,
	// and a third time per in-flight packet whenever a session is discarded.
	// A weak assertion is how that shipped.
	line := awaitScrape(t, h, "saguin_deliveries_expired_total", 30*time.Second)
	inFlight := dawdler.State.Inflight.Len()
	t.Logf("%s; %d still in flight, %d received", line, inFlight, c.Count())
	if got, want := line, "saguin_deliveries_expired_total 1"; got != want {
		t.Fatalf("one delivery expired unsent and the scrape says %q, want %q: the hook fires "+
			"more than once per expiry, or for a delivery already sent", got, want)
	}
	if inFlight != 1 {
		t.Errorf("%d in flight after the expiry, want the one on the wire: a sent delivery was "+
			"expired, or the unsent one was not (MQTT-4.3.3-7)", inFlight)
	}
	release()
	if !waitUntil(3*time.Second, func() bool { return dawdler.State.Inflight.Len() == 0 }) {
		t.Fatalf("acknowledged, the consumer still has %d in flight", dawdler.State.Inflight.Len())
	}
	if after := awaitScrape(t, h, "saguin_deliveries_expired_total", time.Second); after != line ||
		c.Count() != 1 {
		t.Errorf("after the acknowledgement the scrape says %q and the consumer received %d, want "+
			"%q and 1: the delivery on the wire was counted expired, or the expired one was sent",
			after, c.Count(), line)
	}

	// The other half of the same defect: a session discarded with packets
	// still in flight fires the same hook for every one of them, and none of
	// those expired. The counter must not move.
	t.Run("a discarded session is not an expiry", func(t *testing.T) {
		// **manualAck rather than the hold**, because what this needs is
		// packets that are received and never acknowledged, not a handler
		// that never returns: a blocked handler cannot be disconnected, and
		// the first version of this deadlocked closing it.
		d := connect(t, h, "abandoner", true, true)
		if sa := d.Sub(t, "loose/#", 1); sa.Reasons[0] > 2 {
			t.Fatalf("the subscription was refused 0x%02X", sa.Reasons[0])
		}
		for i := 0; i < 5; i++ {
			if _, err := p.C.Publish(context.Background(), &paho.Publish{
				Topic: "loose/x", QoS: 1, Payload: []byte("held"),
			}); err != nil {
				t.Fatalf("publish: %v", err)
			}
		}
		if !waitUntil(3*time.Second, func() bool { return d.Count() == 5 }) {
			t.Fatalf("the consumer received %d of 5 before the session was discarded, "+
				"so there is nothing in flight to be miscounted", d.Count())
		}
		// Gone, with five unacknowledged packets, taking them with it.
		d.Close()

		after := awaitScrape(t, h, "saguin_deliveries_expired_total", 3*time.Second)
		if after != "saguin_deliveries_expired_total 1" {
			t.Errorf("discarding a session with packets in flight moved the expiry "+
				"counter to %q: those packets carried no expiry and none of them "+
				"reached one", after)
		}
	})
}

// RFC 0002 `limits.write_timeout`.
//
// **A consumer that stops reading must not be able to hold a publisher, or
// duplicate that publisher's record.** Channel deliveries are written on
// the goroutine that published them, so before the deadline existed a
// client that subscribed and then stopped reading its socket blocked an
// unrelated publisher indefinitely: the record was stored, the PUBACK was
// never sent, the publisher's library concluded the broker was gone and
// re-sent it, and the channel held it twice. Measured at the time: stuck at
// the 644th record, and 645 records read back with 644 distinct values.
//
// **The raw socket is the instrument**, for the reason
// TestASlowConsumerIsShedAndCounted gives: a client library keeps draining
// into its own buffers whatever its handler does, so only a socket nobody
// reads leaves the broker's write with nowhere to go.
func TestADeafConsumerCannotHoldAPublisher(t *testing.T) {
	brokertest.WriteDeadline = 300 * time.Millisecond
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })

	// The log line is asserted here and in the queue test because RFC 0005
	// says it is what reports a slow consumer - the counter cannot, and for
	// one route there was once no line at all at the default level.
	var mu sync.Mutex
	var told int
	h := startLogging(t, func(line string) {
		if strings.Contains(line, "disconnected a consumer that stopped reading") {
			mu.Lock()
			told++
			mu.Unlock()
		}
	})

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()

	send := func(p pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = p
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID: "deaf-on-a-channel", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	send(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "events/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	if sa, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	} else if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got > 2 {
		t.Fatalf("the subscription was refused 0x%02X", got)
	}
	// From here that socket is never read again.

	p := connect(t, h, "publisher", true, false)

	// Enough to fill the kernel's buffer and reach a write that cannot
	// complete. Every one of these must be acknowledged: the deadline turns
	// a blocked write into a failed one and a disconnected consumer, and
	// the publisher is not part of that transaction.
	payload := strings.Repeat("x", 4096)
	const records = 3000
	for i := 0; i < records; i++ {
		ack, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte(payload),
		})
		if ack == nil {
			t.Fatalf("publish %d was never acknowledged: %v - a consumer that stopped "+
				"reading is holding the publisher, which is how a record it had "+
				"already stored comes to be published twice", i, err)
		}
		if ack.ReasonCode != 0 {
			t.Fatalf("publish %d answered 0x%02X", i, ack.ReasonCode)
		}
	}

	if !waitUntil(5*time.Second, func() bool {
		mu.Lock()
		defer mu.Unlock()
		return told > 0
	}) {
		t.Error("nothing said that a consumer was hung up on: the counter cannot report " +
			"this and RFC 0005 says the log line is what does, so an operator at the " +
			"default level would be told nothing at all")
	}
}

// Invariant 16 on the latest route: **a publisher waits on storage and on
// nothing another client does**, and "no bound on that write removes it".
//
// TestADeafConsumerCannotHoldAPublisher asks whether every publish is
// acknowledged, which a publisher kept waiting for one whole write deadline
// still is. This asks how long. A latest value was written to every
// subscriber on the publishing goroutine, before the PUBACK, so a subscriber
// that stopped reading held the publisher for as long as the write deadline
// let it - the wait invariant 16 says no bound removes, because a publisher
// less patient than the bound gives up inside it and re-sends.
//
// **The raw socket is the instrument**, for the reason the test above gives,
// and QoS 0 on it so that no in-flight window stops the broker writing before
// the socket fills. The hang-up is what proves the socket did fill and a
// write to it blocked for the whole deadline; the publishes acknowledged
// inside that deadline are what prove the publisher was served meanwhile. A
// fast publisher on its own would prove nothing - it may simply have finished
// before any write blocked, which is how this test's first version passed
// over an empty case.
func TestADeafLatestSubscriberDoesNotDelayAPublisher(t *testing.T) {
	const deadline = 2 * time.Second
	brokertest.WriteDeadline = deadline
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })

	var mu sync.Mutex
	hungUp := false
	var hungAt time.Time
	h := startLogging(t, func(line string) {
		if strings.Contains(line, "disconnected a consumer that stopped reading") {
			mu.Lock()
			if !hungUp {
				hungUp, hungAt = true, time.Now()
			}
			mu.Unlock()
		}
	})

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	send := func(p pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = p
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID: "deaf-on-latest", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	send(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "state/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	if sa, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	} else if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got > 2 {
		t.Fatalf("the subscription was refused 0x%02X", got)
	}
	// From here that socket is never read again.

	// A third party reading the same channel, which must go on being served
	// while the deaf subscriber's write is blocked: invariant 16 is that no
	// client can hold another's delivery, not only its publisher.
	watcher := connect(t, h, "watcher", true, false)
	watcher.Sub(t, "state/#", 0)

	p := connect(t, h, "publisher", true, false)
	payload := []byte(strings.Repeat("x", 64<<10))
	var worst time.Duration
	var acked []time.Time
	var watched []int
	worstAt, published, afterHangUp := -1, 0, 0
	// Paced, so that the deadline is spent publishing rather than copying
	// gigabytes, and bounded by time rather than by count: the case is over
	// when the deaf subscriber has been hung up on.
	until := time.Now().Add(4 * deadline)
	for i := 0; afterHangUp < 20 && time.Now().Before(until); i++ {
		time.Sleep(time.Millisecond)
		at := time.Now()
		ack, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: fmt.Sprintf("state/v%d", i%50), QoS: 1, Payload: payload,
		})
		took := time.Since(at)
		if ack == nil {
			t.Fatalf("publish %d was never acknowledged: %v", i, err)
		}
		if ack.ReasonCode != 0 {
			t.Fatalf("publish %d answered 0x%02X", i, ack.ReasonCode)
		}
		published++
		acked = append(acked, time.Now())
		watched = append(watched, watcher.Count())
		if took > worst {
			worst, worstAt = took, i
		}
		mu.Lock()
		if hungUp {
			afterHangUp++
		}
		mu.Unlock()
	}

	mu.Lock()
	proved, blockedFrom, blockedTo := hungUp, hungAt.Add(-deadline), hungAt
	mu.Unlock()
	if !proved {
		t.Fatalf("the deaf subscriber was never hung up on after %d values of %d bytes, so no "+
			"write to it ever blocked and the publisher's times below say nothing", published, len(payload))
	}
	// Acknowledged while the write that ended in the hang-up was blocked -
	// the middle of that deadline, clear of either edge.
	during, seenFrom, seenTo := 0, -1, -1
	for i, at := range acked {
		if at.After(blockedFrom.Add(deadline/4)) && at.Before(blockedTo.Add(-deadline/4)) {
			during++
			if seenFrom < 0 {
				seenFrom = watched[i]
			}
			seenTo = watched[i]
		}
	}
	if during == 0 {
		t.Errorf("no publish was acknowledged while the write to the deaf subscriber was "+
			"blocked (%d published): the publisher waited for it", published)
	} else if seenTo <= seenFrom {
		t.Errorf("the watcher received nothing while the deaf subscriber's write was blocked "+
			"(held %d values throughout): one subscriber's socket held another's delivery", seenFrom)
	}
	if worst >= deadline/2 {
		t.Errorf("publish %d of %d waited %v for its acknowledgement, with a write deadline of %v: "+
			"a subscriber that stopped reading held the publisher, which invariant 16 says no "+
			"client can do", worstAt, published, worst.Round(time.Millisecond), deadline)
	}
	t.Logf("%d values published, %d acknowledged while the deaf subscriber's write was blocked, "+
		"the slowest acknowledgement %v (publish %d)", published, during, worst.Round(time.Millisecond), worstAt)
}

// Invariant 16 on the queue route.
//
// **The assertion is a third party still being served**, and getting that
// wrong twice is why this comment is long. The first version watched the
// publisher, which a deaf worker never holds, and passed while the
// broker's housekeeping was frozen. The second watched a worker on a
// second queue that the harness does not configure, so it was really
// watching ordinary broadcast - a path the frozen loop never touches - and
// passed for a different wrong reason.
//
// One queue, two workers in its share group: one that stops reading and
// one that does not. Offers for every record go through Broker.Run, so a
// loop stuck writing to the deaf worker starves the live one as surely as
// it starves job expiry and the retention sweeps. The live worker is what
// this watches.
func TestADeafQueueWorkerDoesNotStarveItsGroup(t *testing.T) {
	brokertest.WriteDeadline = 300 * time.Millisecond
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })

	// This is the route that said nothing: its writes are the substrate's,
	// so the line written beside saguin's own writes never covered it, and
	// a worker was hung up on in silence.
	var mu sync.Mutex
	var told int
	h := startLogging(t, func(line string) {
		if strings.Contains(line, "disconnected a consumer that stopped reading") {
			mu.Lock()
			told++
			mu.Unlock()
		}
	})

	live := connect(t, h, "live-worker", true, false)
	if sa := live.Sub(t, "$saguin/queue/jobs", 1); sa.Reasons[0] > 2 {
		t.Fatalf("the live worker's subscription was refused 0x%02X", sa.Reasons[0])
	}
	p := connect(t, h, "job-publisher", true, false)
	p.Pub(t, "jobs/warmup", "before")
	if !waitUntil(5*time.Second, func() bool { return live.Count() >= 1 }) {
		t.Fatal("the live worker was not fed before the deaf one arrived, so this test " +
			"cannot tell a starved queue from a broken fixture")
	}

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	send := func(pk pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = pk
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID: "deaf-worker", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	// **A broadcast subscription beside the queue's, and it is what fills
	// the socket.** A worker holds one job from a queue at a time (RFC 0003
	// "Delivery"), so a deaf worker is sent one job and never another - the
	// jobs below cannot wedge its connection any more. Broadcast is written by
	// the substrate too, which is the route this test is about, and nothing
	// bounds it but the write deadline.
	send(&pahopackets.Subscribe{
		PacketID: 1,
		Subscriptions: []pahopackets.SubOptions{
			{Topic: "$saguin/queue/jobs", QoS: 1},
			{Topic: "flood/#", QoS: 0},
		},
	}, pahopackets.SUBSCRIBE)
	if sa, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	} else {
		for i, got := range sa.Content.(*pahopackets.Suback).Reasons {
			if got > 2 {
				t.Fatalf("the deaf worker's subscription %d was refused 0x%02X", i, got)
			}
		}
	}
	// From here that socket is never read again - but it goes on sending.
	//
	// **A deaf client that keeps publishing is the case that matters**, and
	// it needs no intent: a device whose receive side has wedged while its
	// sensor loop carries on is exactly this. The substrate refreshes the
	// keepalive deadline on every packet it reads, and a keepalive deadline
	// covers reads and writes together, so each of these QoS 0 publishes
	// cleared the deadline the write below had armed.
	// A PINGREQ does not do it: the PINGRESP queues behind the same lock.
	stop := make(chan struct{})
	defer close(stop)
	go func() {
		for {
			select {
			case <-stop:
				return
			case <-time.After(200 * time.Millisecond):
			}
			cp := pahopackets.NewControlPacket(pahopackets.PUBLISH)
			cp.Content = &pahopackets.Publish{Topic: "noise/x", QoS: 0, Payload: []byte("tick")}
			if _, err := cp.WriteTo(conn); err != nil {
				return
			}
		}
	}()

	payload := strings.Repeat("j", 4096)
	// **Published until the socket wedges, rather than a fixed number of
	// times.** What this needs is a broker write that blocks long enough for
	// the deadline to fire, and how many records that takes is the machine's
	// answer rather than a constant. A count calibrated on one machine wedges
	// nothing on a slower one: at 4000 on a 32-bit target only 764 packets
	// ever reached the socket - the rest were dropped as slow-subscriber
	// before they got there - which is under the socket pair's capacity, so
	// nothing blocked, the deadline never fired, and the run failed naming
	// the log line it never got instead of the fixture that never armed it.
	//
	// The bound below is a stop, not a target: the loop leaves as soon as the
	// hang-up is seen, and `wedged` is what tells the two failures apart
	// afterwards.
	const mostFloods = 40000
	published, wedged := 0, false
	for i := 0; i < mostFloods && !wedged; i++ {
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "jobs/x", QoS: 1, Payload: []byte(payload),
		}); err != nil {
			t.Fatalf("job %d: %v", i, err)
		}
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "flood/x", QoS: 0, Payload: []byte(payload),
		}); err != nil {
			t.Fatalf("broadcast %d: %v", i, err)
		}
		published++
		// Asked periodically rather than every time round: the lock is the
		// one the write loop wants, and taking it per record would change
		// the thing being measured.
		if i%200 == 199 {
			mu.Lock()
			wedged = told > 0
			mu.Unlock()
		}
	}

	// The live worker must go on being offered records. Unbounded, the loop
	// that offers them is stuck writing to the deaf one.
	before := live.Count()
	if !waitUntil(25*time.Second, func() bool { return live.Count() > before }) {
		t.Fatalf("a live worker in the same share group received nothing more after a "+
			"deaf worker joined it (stuck at %d): the loop that offers every queue's "+
			"records, expires jobs and runs both retention sweeps is blocked on that "+
			"worker's client lock", before)
	}

	if !waitUntil(5*time.Second, func() bool {
		mu.Lock()
		defer mu.Unlock()
		return told > 0
	}) {
		// **Two different failures, and they are told apart here.** A fixture
		// that never wedged the socket exercised nothing, and reporting that
		// as a missing log line sends the next reader to OnDisconnect for a
		// defect that is not there.
		if !wedged {
			t.Fatalf("%d records of %d bytes went out and the deaf client's socket "+
				"never wedged, so no broker write ever blocked and the deadline was "+
				"never armed: this run exercised nothing, and the fixture is what "+
				"failed rather than the broker", published, len(payload))
		}
		t.Error("the deaf worker was hung up on and nothing above debug said so: the " +
			"line is written in OnDisconnect precisely so that it covers this route " +
			"as well as saguin's own writes")
	}
}

// A WebSocket consumer that stops reading is bounded by the same deadline
// as a TCP one - the assertion that the deadline reaches a listener whose
// library writes the frames, rather than the socket saguin armed.
func TestADeafWebSocketConsumerIsAlsoBounded(t *testing.T) {
	brokertest.WriteDeadline = 300 * time.Millisecond
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })

	var mu sync.Mutex
	var told int
	brokertest.LogTo = func(line string) {
		if strings.Contains(line, "disconnected a consumer that stopped reading") {
			mu.Lock()
			told++
			mu.Unlock()
		}
	}
	t.Cleanup(func() { brokertest.LogTo = nil })
	h := startOn(t, "ws")

	deaf, err := dialWS(h.Addr)
	if err != nil {
		t.Fatalf("dial ws: %v", err)
	}
	defer deaf.Close()

	send := func(pk pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = pk
		if _, err := cp.WriteTo(deaf); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID: "deaf-ws", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(deaf); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	send(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "events/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	if sa, err := pahopackets.ReadPacket(deaf); err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	} else if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got > 2 {
		t.Fatalf("subscription refused 0x%02X", got)
	}
	// From here that WebSocket is never read again - but it goes on
	// sending, which is the variant that broke every other listener. The
	// keepalive refresh reaches this connection's read deadline while the
	// write deadline lives on the websocket connection above the socket,
	// so by reading the two cannot collide; reading was wrong twice about
	// this listener already, so it is
	// driven.
	stop := make(chan struct{})
	defer close(stop)
	go func() {
		for {
			select {
			case <-stop:
				return
			case <-time.After(200 * time.Millisecond):
			}
			cp := pahopackets.NewControlPacket(pahopackets.PUBLISH)
			cp.Content = &pahopackets.Publish{Topic: "noise/x", QoS: 0, Payload: []byte("tick")}
			if _, err := cp.WriteTo(deaf); err != nil {
				return
			}
		}
	}()

	p := connect(t, h, "ws-publisher", true, false)
	payload := strings.Repeat("x", 4096)
	for i := 0; i < 3000; i++ {
		ack, _ := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte(payload),
		})
		if ack == nil {
			t.Fatalf("publish %d was never acknowledged: a deaf WebSocket client is "+
				"holding the publisher, so the write deadline does not reach it", i)
		}
	}
	if !waitUntil(5*time.Second, func() bool {
		mu.Lock()
		defer mu.Unlock()
		return told > 0
	}) {
		t.Error("a deaf WebSocket consumer was never hung up on")
	}
}

// A publisher waits on its own storage and on nothing else. The deadline
// on a delivery write stopped a deaf consumer holding a publisher for
// ever; this is the rest of it, because a publisher whose own patience is
// shorter than `limits.write_timeout` gives up inside that window and
// re-sends a record the broker has already stored.
func TestAPublisherNeverWaitsOnAConsumersSocket(t *testing.T) {
	// Long on purpose: the deadline must not be what rescues the publisher
	// here. Thirty seconds is a write nobody would call bounded.
	brokertest.WriteDeadline = 30 * time.Second
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })

	h := startOn(t, "tcp")

	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	send := func(pk pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = pk
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	send(&pahopackets.Connect{
		ClientID: "deaf-reader", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	send(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "events/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	if sa, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the SUBACK: %v", err)
	} else if got := sa.Content.(*pahopackets.Suback).Reasons[0]; got > 2 {
		t.Fatalf("the subscription was refused 0x%02X", got)
	}
	// From here that socket is never read again.

	p := connect(t, h, "impatient-publisher", true, false)
	payload := strings.Repeat("x", 4096)
	var worst time.Duration
	var worstAt int
	for i := 0; i < 2000; i++ {
		ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
		start := time.Now()
		ack, err := p.C.Publish(ctx, &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte(payload),
		})
		took := time.Since(start)
		cancel()
		if ack == nil {
			t.Fatalf("publish %d waited %v for an acknowledgement and gave up (%v): it is "+
				"waiting on a consumer that stopped reading, and a publisher that gives "+
				"up re-sends a record the channel already holds", i, took, err)
		}
		if took > worst {
			worst, worstAt = took, i
		}
	}
	if worst > 3*time.Second {
		t.Errorf("publish %d waited %v for its acknowledgement with limits.write_timeout "+
			"at %v: the delivery is being written on the publishing goroutine, so a "+
			"publisher less patient than that window gives up inside it and re-sends",
			worstAt, worst, brokertest.WriteDeadline)
	}
}

// The bridge's side of the rule above: **a link never waits on a consumer's
// socket either.**
//
// An inbound bridge stores what it carries and then wakes the consumers
// that match it. That waking is pumpAll, which hands each
// consumer's drain to a goroutine of its own - so the goroutine carrying
// the link writes to no consumer at all, and one that has stopped reading
// cannot stop records crossing. That was true by reading and had never been
// run, which is the whole reason this exists: the same reasoning was
// applied three times in one day to one listener and was wrong every time.
//
// **The assertion is a third party** - a live consumer on the bridged
// channel, fed by records that can only have crossed the link after the
// deaf one wedged. Watching the producer upstream would prove nothing: it
// publishes to the other broker and never waits on saguin at all, which is
// the same mistake as watching a publisher that a deaf queue worker never
// holds, and that one passed for two rounds before anybody noticed.
//
// **The deadline is long on purpose**, as in the test above. At the
// ordinary few seconds the deaf consumer is hung up on before a stall could
// be seen, and this would pass just as well against a link that had waited
// for it - the deadline would be doing the work the goroutine is there to
// do. Thirty seconds is longer than this test runs, and that it never fired
// is asserted rather than assumed.
func TestADeafConsumerDoesNotStopABridgesLink(t *testing.T) {
	brokertest.WriteDeadline = 30 * time.Second
	t.Cleanup(func() { brokertest.WriteDeadline = 0 })

	var mu sync.Mutex
	var told int
	upstream, upstreamAddr := startUpstream(t)
	h := startLogging(t, func(line string) {
		if strings.Contains(line, "disconnected a consumer that stopped reading") {
			mu.Lock()
			told++
			mu.Unlock()
		}
	})

	cfg := bridgeConfig(t, upstreamAddr)
	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	if testing.Verbose() {
		log = slog.New(slog.NewTextHandler(newTestWriter(t), &slog.HandlerOptions{Level: slog.LevelInfo}))
	}
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})

	live := connect(t, h, "live-reader", true, false)
	if sa := live.Sub(t, "events/#", 1); sa.Reasons[0] > 2 {
		t.Fatalf("the live consumer's subscription was refused 0x%02X", sa.Reasons[0])
	}

	prod := dialUpstream(t, upstreamAddr, "vessel-sensor")

	// **Few records and big ones, rather than many small.** What has to
	// happen is that a write to the deaf consumer's socket cannot complete,
	// and that is a question of bytes rather than of records: put the drain
	// back on the storing goroutine and 13 of these 40 cross before the link
	// stops, so an unread socket here swallows something like six megabytes.
	// Twenty is past that comfortably.
	//
	// Reaching the same twenty megabytes in four-kilobyte records does not
	// work: at 2000 records only 1213 and 1706 of them ever arrived, in two
	// runs *with no deaf consumer at all*. Where they went was not chased -
	// what matters is that the fixture, not the broker, is what loses them,
	// and a test built on it would have reported a stalled link.
	payload := strings.Repeat("x", 512*1024)
	send := func(t testing.TB, n, from int) {
		t.Helper()
		for i := from; i < from+n; i++ {
			ack, err := prod.Publish(context.Background(), &paho.Publish{
				Topic:   "fleet/vessel-07/telemetry/hold/psi",
				QoS:     1,
				Payload: fmt.Appendf(nil, "reading-%d-%s", i, payload),
			})
			if err != nil || ack == nil || ack.ReasonCode > 1 {
				t.Fatalf("publish %d peer: %v", i, err)
			}
		}
	}

	waitForBridge(t, upstream, cfg.ClientID)

	// The link carries records and the live consumer is fed by it, before
	// the deaf one arrives. Without this the assertion below cannot tell a
	// link stopped by a deaf consumer from a fixture that never carried
	// anything - which is the failure this shape is prone to.
	send(t, 5, 0)
	if got := collect(t, live, 5, 10*time.Second); len(got) != 5 {
		t.Fatalf("only %d of 5 records crossed the link before the deaf consumer arrived: "+
			"this test cannot tell a stopped link from a fixture that was never carrying "+
			"records", len(got))
	}

	// A second consumer on the same channel, whose socket is never read.
	conn, err := net.Dial(h.Network, h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	sendPacket := func(pk pahopackets.Packet, kind byte) {
		t.Helper()
		cp := pahopackets.NewControlPacket(kind)
		cp.Content = pk
		if _, err := cp.WriteTo(conn); err != nil {
			t.Fatalf("write %d: %v", kind, err)
		}
	}
	sendPacket(&pahopackets.Connect{
		ClientID: "deaf-reader-on-a-bridged-channel", CleanStart: true, KeepAlive: 0,
		ProtocolName: "MQTT", ProtocolVersion: 5,
	}, pahopackets.CONNECT)
	if ca, err := pahopackets.ReadPacket(conn); err != nil {
		t.Fatalf("read the CONNACK: %v", err)
	} else if got := ca.Content.(*pahopackets.Connack).ReasonCode; got != 0 {
		t.Fatalf("connect refused 0x%02X", got)
	}
	// **QoS 0 on purpose.** A window is a bound of its own: a QoS 1 consumer
	// stops being written to once its in-flight window fills, so it would
	// hold the goroutine feeding it for a few packets rather than for as
	// long as its socket stays full, and this would be asking a much
	// smaller question than it looks.
	sendPacket(&pahopackets.Subscribe{
		PacketID:      1,
		Subscriptions: []pahopackets.SubOptions{{Topic: "events/#", QoS: 0}},
	}, pahopackets.SUBSCRIBE)
	// **Read until the SUBACK rather than reading one packet and asserting
	// what it is.** This channel already holds records, so the replay
	// arrives in the same breath as the SUBACK and reaches the socket first
	// - and a test that asserted on that packet would report a refused
	// subscription about a broker that granted it and was already
	// delivering. The records read here are the five above; from the last
	// line of this loop the socket is never read again.
	granted := byte(0xFF)
	for granted == 0xFF {
		pk, err := pahopackets.ReadPacket(conn)
		if err != nil {
			t.Fatalf("read the SUBACK: %v", err)
		}
		if sa, ok := pk.Content.(*pahopackets.Suback); ok {
			granted = sa.Reasons[0]
		}
	}
	if granted > 2 {
		t.Fatalf("the deaf consumer's subscription was refused 0x%02X", granted)
	}

	// want is well short of records because the bar is not "the link is
	// perfect", it is "the link is running". Without the drain on its own
	// goroutine the deaf consumer's socket absorbs a few records and then
	// the link stops dead, which is nowhere near this number.
	const records = 40
	const want = 30
	before := live.Count()
	send(t, records, 5)

	if !waitUntil(20*time.Second, func() bool { return live.Count() >= before+want }) {
		t.Fatalf("a live consumer on a bridged channel received %d more records after a "+
			"deaf one subscribed to it, of %d the link was given: the goroutine carrying "+
			"the link is writing to that consumer's socket, so a device that stopped "+
			"reading stops the link for everybody",
			live.Count()-before, records)
	}

	mu.Lock()
	n := told
	mu.Unlock()
	if n > 0 {
		t.Errorf("the deaf consumer was hung up on %d time(s) with limits.write_timeout at "+
			"%v: the deadline rescued the link inside this test, so what it proved is that "+
			"the deadline works and not that the link never waited",
			n, brokertest.WriteDeadline)
	}
}

// A bridge's wake-up for an append channel is a hint over a stored position
// (BridgeClient.Watch), so the broker coalesces it rather than waits: a link
// that has stopped reading its wake-ups never holds a publisher. Without that
// every publish to the channel would wait for the slowest bridge on the
// broker - invariant 16's failure, reached through a hint. The guard had no
// test that filled it.
//
// The watcher here is never read. Each publish must still be acknowledged,
// and the one wake-up it holds is the proof the broker did signal it.
func TestABridgeThatNeverTakesItsWakeupsHoldsNoPublisher(t *testing.T) {
	h := start(t)
	ch, stop := h.B.NewBridgeClient("held").Watch("events")
	// Taken in the cleanup rather than never, so a broker that blocked on
	// this channel lets its publisher go and the harness can stop.
	t.Cleanup(func() {
		for {
			select {
			case <-ch:
				continue
			case <-time.After(100 * time.Millisecond):
			}
			break
		}
		stop()
	})

	p := connect(t, h, "producer", true, false)
	const n = 5
	for i := range n {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		_, err := p.C.Publish(ctx, &paho.Publish{Topic: "events/x", QoS: 1, Payload: []byte("v")})
		cancel()
		if err != nil {
			t.Fatalf("publish %d of %d, with a bridge that takes no wake-ups: %v", i+1, n, err)
		}
	}
	if got := len(ch); got != 1 {
		t.Fatalf("the unread watcher holds %d wake-ups after %d publishes, want 1", got, n)
	}
}

// Group commit, through the wire: publishes that arrive together are stored
// in one transaction, and every one of them is still acknowledged.
//
// **What makes this worth driving through MQTT rather than at the store** is
// that a batch changes when a PUBACK is sent. Every publisher here waits for
// its own acknowledgement - paho's QoS 1 Publish returns on the PUBACK - so
// a broker that answered the batch's leader and forgot the rest, or that
// answered everybody but stored one record, fails here and passes every
// store-level test.
//
// The transaction count is asserted because nothing else can tell a
// provider that collected the publishes from one that ignored the setting
// and was merely quick.
func TestPublishesCollectedIntoOneTransactionAreEachAcknowledged(t *testing.T) {
	const publishers = 40

	collectPublishes(t, 100*time.Millisecond, publishers)
	h := startDurableSQLite(t, filepath.Join(t.TempDir(), "saguin.db"))

	// Connected before anything is timed, and released together. A client
	// that connects inside the window spreads its publish across the
	// interval by however long its CONNECT took, and then the batches are
	// small for a reason that has nothing to do with the broker.
	clients := make([]*client, publishers)
	for i := range publishers {
		clients[i] = connect(t, h, fmt.Sprintf("pub-%d", i), true, false)
		defer clients[i].Close()
	}

	before := h.DB.Commits()
	release := make(chan struct{})
	var wg sync.WaitGroup
	for i := range publishers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-release
			// Blocks until the broker's PUBACK arrives, which is the whole
			// question: a record collected into somebody else's transaction
			// still has to be answered.
			clients[i].Pub(t, "events/x", fmt.Sprintf("record-%d", i))
		}()
	}
	close(release)
	wg.Wait()
	stored := h.DB.Commits() - before

	// The subscriber comes after the publishes, so that the position it
	// saves for every record it acknowledges is not counted as one of the
	// transactions the records were stored in.
	reader := connectDurable(t, h, "reader")
	reader.Sub(t, "events/#", 1)

	// Every record delivered.
	deadline := time.After(20 * time.Second)
	for reader.Count() < publishers {
		select {
		case <-deadline:
			t.Fatalf("%d of %d records reached the subscriber", reader.Count(), publishers)
		case <-time.After(20 * time.Millisecond):
		}
	}
	seen := map[string]bool{}
	for _, p := range reader.Payloads() {
		if seen[p] {
			t.Fatalf("record %q was delivered twice", p)
		}
		seen[p] = true
	}
	for i := range publishers {
		if want := fmt.Sprintf("record-%d", i); !seen[want] {
			t.Fatalf("%q was acknowledged and never delivered", want)
		}
	}

	// Fewer transactions than publishes is the claim this can make: the
	// window also holds whatever else the provider committed, and under the
	// race detector the publishes spread far enough apart to form several
	// groups rather than one. The strong version - two hundred publishes in
	// a single transaction - is asserted at the store, where nothing else
	// is committing.
	if stored >= publishers {
		t.Fatalf("%d publishes took %d transactions: they were not collected, so this test proved nothing "+
			"about group commit", publishers, stored)
	}
	t.Logf("%d publishes, each acknowledged, stored in %d transactions", publishers, stored)
}

// A publisher on its own never fills a batch, so the interval is the only
// thing that can answer it. This is the case that hangs for ever if the
// timer is wrong, and it is worth its own test because every other test
// here has enough traffic to close a batch on the record count.
//
// It also asserts the wait is roughly the interval rather than a multiple
// of it: a batch that started its clock when the previous one ended, rather
// than when the publish arrived, answers eventually and answers late.
//
// **Both bounds, and the upper one close enough to mean it.** This said the
// same sentence when the only assertion was a three-second ceiling, which
// fifty intervals pass - the prose was holding a
// rule the code was not. Measured under `-race` on a sixteen-core box the
// waits are 61–63ms against 60ms, so three intervals is generous for a
// loaded machine and still excludes every multiple.
func TestALonePublisherIsAnsweredByTheIntervalAlone(t *testing.T) {
	const interval = 60 * time.Millisecond

	collectPublishes(t, interval, 1000)
	h := startDurableSQLite(t, filepath.Join(t.TempDir(), "saguin.db"))

	c := connect(t, h, "lonely", true, false)
	defer c.Close()

	for i := range 5 {
		start := time.Now()
		c.Pub(t, "events/x", fmt.Sprintf("record-%d", i))
		took := time.Since(start)
		switch {
		case took < interval/2:
			t.Fatalf("publish %d was answered in %v, under half of the %v interval: something other "+
				"than the timer closed a batch a lone publisher cannot fill, so this test is no "+
				"longer about the interval", i, took, interval)
		case took > 3*interval:
			t.Fatalf("publish %d waited %v, more than three times the %v interval: the batch's clock "+
				"is not starting when the publish arrives", i, took, interval)
		}
	}

	reader := connectDurable(t, h, "reader")
	reader.Sub(t, "events/#", 1)
	deadline := time.After(20 * time.Second)
	for reader.Count() < 5 {
		select {
		case <-deadline:
			t.Fatalf("%d of 5 records were stored", reader.Count())
		case <-time.After(20 * time.Millisecond):
		}
	}
}

// The interval is a wait on storage, and invariant 16 says a publisher
// waits on storage and on nothing else. A batch collecting on one channel
// must not hold up a publisher on another - and it will if a lock is taken
// too early, which is exactly the shape of defect this whole write path was
// rearranged to avoid.
//
// The third party here is a queue, which is a different table in the same
// file and therefore the same connection: if anything is going to be held
// behind an open batch, it is this.
func TestABatchCollectingOnOneChannelDoesNotHoldAnother(t *testing.T) {
	// Large enough that the append channel's batch never fills, so it is
	// always the interval that closes it and a batch is always open.
	collectPublishes(t, 50*time.Millisecond, 10000)
	h := startDurableSQLite(t, filepath.Join(t.TempDir(), "saguin.db"))

	slow := connect(t, h, "appender", true, false)
	defer slow.Close()
	done := make(chan struct{})
	go func() {
		defer close(done)
		for i := range 20 {
			slow.Pub(t, "events/x", fmt.Sprintf("record-%d", i))
		}
	}()

	other := connect(t, h, "enqueuer", true, false)
	defer other.Close()
	start := time.Now()
	for i := range 20 {
		other.Pub(t, "jobs/x", fmt.Sprintf("job-%d", i))
	}
	took := time.Since(start)

	<-done
	// Twenty publishes to a second channel, each waiting out its own 50ms
	// interval, is a second. Several times that means they were queued
	// behind the other channel's batches as well as their own.
	if took > 10*time.Second {
		t.Fatalf("twenty publishes to a queue took %v while an append channel was collecting: "+
			"they were held behind another channel's transaction", took)
	}
	t.Logf("twenty publishes to a second channel took %v while a batch was open on the first", took)
}

// **What fills a batch is connections, not records in flight** - which is
// the fact the configuration advice rests on, so it is driven rather than
// reasoned about.
//
// MQTT lets a client keep several publishes outstanding, up to the Receive
// Maximum, and it would be reasonable to expect twenty of them from one
// client to fill a batch of twenty. They do not: a connection's packets are
// read and answered in turn, so the second PUBLISH is not taken off the
// socket until the first has been stored and acknowledged. Each therefore
// waits out its own interval, one after another.
//
// It matters because it is the difference between advice that works and
// advice that makes a broker six times slower. publish_commit_max_records is set
// against the number of connections publishing at once, and a test that
// nobody wrote is how "up to the Receive Maximum" would have stayed in the
// RFC as though it counted.
func TestOneConnectionFillsABatchByOneHoweverManyItHasInFlight(t *testing.T) {
	const (
		publishes = 20
		interval  = 50 * time.Millisecond
	)

	// A record count no single connection could reach, so the interval is
	// the only thing that can close a batch and the arithmetic below is
	// about how many intervals were spent.
	collectPublishes(t, interval, 1000)
	h := startDurableSQLite(t, filepath.Join(t.TempDir(), "saguin.db"))
	c := connect(t, h, "pipeliner", true, false)
	defer c.Close()

	start := time.Now()
	var wg sync.WaitGroup
	for i := range publishes {
		wg.Add(1)
		go func() {
			defer wg.Done()
			// Straight to paho rather than through c.pub, because every one
			// of these has to be in flight at the same time.
			if _, err := c.C.Publish(context.Background(), &paho.Publish{
				Topic: "events/x", QoS: 1, Payload: []byte(fmt.Sprintf("r-%d", i)),
			}); err != nil {
				t.Errorf("publish %d: %v", i, err)
			}
		}()
	}
	wg.Wait()
	took := time.Since(start)

	// Half the publishes' worth of intervals is far below anything the
	// serial path can produce and far above what a single batch would take,
	// so it separates the two without asserting a duration the machine
	// decides.
	if took < publishes/2*interval {
		t.Fatalf("%d publishes outstanding on one connection took %v, under half the %d intervals the "+
			"serial path costs: a connection now fills a batch by more than one, and the advice in "+
			"RFC 0002 for setting publish_commit_max_records against the number of publishing connections "+
			"needs rewriting", publishes, took, publishes)
	}
	if n := c.Count(); n != 0 {
		t.Fatalf("the publisher received %d records it never subscribed to", n)
	}

	// And every one of them was stored, which is what says the wait bought
	// something rather than being lost time.
	reader := connectDurable(t, h, "reader")
	reader.Sub(t, "events/#", 1)
	deadline := time.After(20 * time.Second)
	for reader.Count() < publishes {
		select {
		case <-deadline:
			t.Fatalf("%d of %d records were stored", reader.Count(), publishes)
		case <-time.After(20 * time.Millisecond):
		}
	}
	t.Logf("%d publishes outstanding on one connection took %v - %d intervals of %v, one each",
		publishes, took.Round(time.Millisecond), int(took/interval), interval)
}

// --- channels placed by filter -----------------------------------------

// RFC 0002 "The topic space", "Which channel a topic belongs to" - invariant 12
//
// **Four semantics under one `iot/` hierarchy**, which is the thing a
// channel claiming a first topic level could not express: a domain holds
// telemetry, current state and work at once, and whichever type that root
// was given, the other two got the wrong one.
//
// The two water filters overlap deliberately - `iot/water/+/location/#` and
// `iot/water/+/+/#` both match `iot/water/w-7/location` - so every row here
// is also a test of the rule that settles them: the filter spelling the
// topic out most exactly holds it.
//
// **The broadcast rows are the ones that would pass silently if resolution
// were wrong**, which is why each is checked by what a later Clean Start = 1
// subscriber is *not* replayed rather than by what arrived live. A topic
// wrongly claimed by an append channel is delivered live exactly like a
// broadcast one, and only the replay tells them apart.
func TestAFilterPlacesFourSemanticsUnderOneHierarchy(t *testing.T) {
	h := startNested(t)
	p := connect(t, h, "producer", true, false)

	// A latest channel: the current value, served with RETAIN on subscribe.
	// It matches the append channel's filter too, and loses to the more
	// exact one.
	p.Pub(t, "iot/water/w-7/location", "51.5,-0.1")
	time.Sleep(200 * time.Millisecond)

	state := connect(t, h, "state-reader", true, false)
	state.Sub(t, "iot/water/+/location/#", 1)
	got, ok := state.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("iot/water/w-7/location was not held as current state, so the more exact " +
			"of the two filters that match it did not win")
	}
	if got.Payload != "51.5,-0.1" || !got.Retain {
		t.Fatalf("current state: %q retain=%v, want the value carrying RETAIN",
			got.Payload, got.Retain)
	}

	// An append channel: replayed to a consumer that was not connected.
	p.Pub(t, "iot/water/w-7/flow", "12.4")
	time.Sleep(200 * time.Millisecond)

	log := connect(t, h, "log-reader", true, false)
	log.Sub(t, "iot/water/w-7/#", 1)
	seen := map[string]string{}
	for range 2 {
		r, ok := log.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("a device's own subtree was served %d of 2 records: %v", len(seen), seen)
		}
		seen[r.Topic] = r.Payload
	}
	if seen["iot/water/w-7/flow"] != "12.4" {
		t.Errorf("the reading was not replayed: %v", seen)
	}
	if seen["iot/water/w-7/location"] != "51.5,-0.1" {
		t.Errorf("the location was not served as current state beside it: %v", seen)
	}

	// **Broadcast, and it must stay broadcast.** `iot/weather/+/{data,events}`
	// carries no `#`, so it matches four-level topics and no others - which
	// is the line of a filter an operator writes by accident.
	p.Pub(t, "iot/weather/st-3/data", "stored")
	p.Pub(t, "iot/weather/st-3/data/raw", "not stored")
	p.Pub(t, "iot/weather/st-3/status", "not stored either")
	time.Sleep(300 * time.Millisecond)

	later := connect(t, h, "later", true, false)
	later.Sub(t, "iot/weather/#", 1)
	replayed := map[string]string{}
	for {
		r, ok := later.Await(t, 1500*time.Millisecond)
		if !ok {
			break
		}
		replayed[r.Topic] = r.Payload
	}
	if replayed["iot/weather/st-3/data"] != "stored" {
		t.Errorf("the four-level topic was not stored by the append channel: %v", replayed)
	}
	for _, topic := range []string{"iot/weather/st-3/data/raw", "iot/weather/st-3/status"} {
		if v, held := replayed[topic]; held {
			t.Errorf("%q was replayed as %q: no filter claims it, so it is broadcast and "+
				"a later subscriber must never see it again", topic, v)
		}
	}
}

// RFC 0002 the `queue` section, "The dead-letter channel" - invariants 4, 11
//
// A queue is consumed through `$saguin/queue/` plus the channel's **name**,
// whatever its filter says, and its dead letters take the queue's own topic
// with a `__dlq` level inserted.
//
// **The channel's own filter is the case that matters here**, and until
// 2026-09-03 it was the form a worker sent. A worker naming the channel
// instead crossed a queue filtered `iot/water/+/inspect` nowhere, so it was
// not a queue subscription being refused: it was granted, connected and
// empty for ever. Both are in the table below, so neither can quietly
// become the other again.
//
// **Every refusal prints the reason code the broker sent** rather than the
// client library's error, because a probe that reports its own wrapper says
// "SUBSCRIBE ERROR" where the broker answered precisely. Driven with Paho,
// which does not validate filters before the socket: a refusal a client
// declines to send is a refusal that cannot be tested.
// RFC 0002 the `queue` section - invariants 4, 11
//
// A worker's pin names its channel, so it *matches* every topic under that
// name - and those topics are not the queue's. `work` is filtered
// `iot/water/+/inspect` here, so `work/anything` belongs to no channel at
// all and is ordinary broadcast.
//
// **Left in the substrate's matched set it reaches the worker as a stray**:
// no Delivery ID, no attempt, outside every count and position saguin
// keeps, and at the worker indistinguishable from a job it must answer.
//
// The shape of the form is what makes this true or false, and it has been
// both. While the form was the queue's filter, every topic it matched
// resolved to the queue and the hazard did not exist; while it was
// `$share/saguin/<name>/#` it matched every broadcast topic under the
// channel's name and the hazard was live; it is `$saguin/queue/<name>` now,
// which matches itself and nothing else. This holds the property across all
// three rather than any one mechanism.
//
// The control is the second half: the same broadcast must still reach an
// ordinary subscriber, or this would pass by delivering nothing to anybody.
// RFC 0002 the `queue` section - invariant 4
//
// `$saguin/queue/` is the broker's own, and consuming a queue is the only
// thing in it. Anything else under it is refused rather than granted over
// topics no queue holds.
//
// **Every row here is one keystroke from a correct line**, which is why the
// rule exists rather than a warning. The sharpest is the dead-letter
// channel's *name*: the documents say failed work lands in `<queue>__dlq`
// and that a queue is consumed through `$saguin/queue/<name>`, so putting
// the two together is the obvious reading - and while the form was a shared
// subscription it produced `0x01 Granted`, a connected worker, and no
// record for ever.
//
// **The controls are half the test.** A refusal proves nothing alone: the
// form must still be granted, and a shared subscription - which saguin
// refuses for nothing it reaches - must still be ordinary MQTT, including
// over the queue's own topics.
func TestTheQueueSpaceIsReservedForConsumingAQueue(t *testing.T) {
	h := startNested(t)

	for _, tc := range []struct {
		why, filter string
		want        byte
	}{
		// Refused: the queue space over names no queue answers to.
		{"a misspelt channel name", "$saguin/queue/wrok", 0x8F},
		{"a dead-letter channel's name, which is not where its records are",
			"$saguin/queue/work__dlq", 0x8F},
		{"an append channel's name, same reason", "$saguin/queue/water-measurement", 0x8F},
		{"a name with a level after it", "$saguin/queue/work/w-7", 0x8F},
		{"a wildcard where a channel name goes", "$saguin/queue/#", 0x8F},

		// Controls.
		{"the form itself", "$saguin/queue/work", 0x01},
		// **A shared subscription is refused for nothing it reaches**, which
		// is the half of this rule that used to be a page of refusals. Each
		// of these is granted and served live messages only - including the
		// one over the queue's own topics, which receives nothing because
		// queue records leave through the queue's own form.
		{"a shared subscription on an append channel", "$share/g/iot/weather/+/data", 0x01},
		{"a shared subscription over the queue's own filter",
			"$share/g/iot/water/+/inspect", 0x01},
		{"a shared subscription over the queue's name", "$share/g/work/#", 0x01},
		{"a shared subscription on ordinary broadcast", "$share/lb/anything/#", 0x01},
	} {
		c := connect(t, h, "rs-"+strings.ReplaceAll(tc.why, " ", "-"), true, false)
		sa := c.Sub(t, tc.filter, 1)
		if sa == nil || len(sa.Reasons) != 1 {
			t.Fatalf("%s: no SUBACK for %q", tc.why, tc.filter)
		}
		if sa.Reasons[0] != tc.want {
			t.Errorf("%s: %q answered SUBACK 0x%02X, want 0x%02X",
				tc.why, tc.filter, sa.Reasons[0], tc.want)
		}
	}

	// **A refusal answers its own filter and no other.** One SUBSCRIBE,
	// several filters, the refused one moved through the packet: MQTT gives
	// a code per filter and saguin decides each inside a loop over them, so
	// a refusal written into the wrong slot, or applied to the whole packet,
	// takes down filters the client is entitled to. Both go red here.
	//
	// **What it does not catch, said so the next reader does not assume it
	// does**: a refusal that leaves the hook early. saguin's array carries
	// only the refusals - a granted filter is left at zero and the substrate
	// fills in the QoS it granted - so returning early loses nothing, and a
	// mutation doing it passes this test. That is why it cannot hurt, not a
	// gap in the case. The commit that added this rule claimed the case
	// guards the early return; it does not, and this is the correction.
	for _, tc := range []struct {
		where   string
		filters []string
		want    []byte
	}{
		// The granted neighbours are a plain filter and a shared one -
		// deliberately not the queue's form, because a client
		// that subscribed to it would join the consumer group and take the
		// job the coda below is waiting for. (It did, the first time.)
		{"first", []string{"$saguin/queue/work__dlq", "orders/#", "$share/lb/anything/#"},
			[]byte{0x8F, 0x01, 0x01}},
		{"in the middle", []string{"orders/#", "$saguin/queue/work__dlq", "$share/lb/anything/#"},
			[]byte{0x01, 0x8F, 0x01}},
		{"last", []string{"orders/#", "$share/lb/anything/#", "$saguin/queue/work__dlq"},
			[]byte{0x01, 0x01, 0x8F}},
	} {
		c := connect(t, h, "many-"+strings.ReplaceAll(tc.where, " ", "-"), true, false)
		got := c.SubMany(t, tc.filters, 1)
		if len(got) != len(tc.want) {
			t.Fatalf("refusal %s: %d reason codes for %d filters", tc.where, len(got), len(tc.filters))
		}
		for i := range got {
			if got[i] != tc.want[i] {
				t.Errorf("refusal %s: %q answered 0x%02X, want 0x%02X - a refusal must "+
					"answer its own filter and no other",
					tc.where, tc.filters[i], got[i], tc.want[i])
			}
		}
	}

	// And the queue still delivers through the one form, so the rule above
	// did not close the door it exists to keep open.
	w := connect(t, h, "worker", true, false)
	w.Sub(t, "$saguin/queue/work", 1)
	subscribed(t, w.C)
	connect(t, h, "producer", true, false).Pub(t, "iot/water/w-7/inspect", "check the valve")
	if job, ok := w.Await(t, 3*time.Second); !ok {
		t.Fatal("the worker was offered nothing, so every refusal above proves nothing")
	} else if job.Topic != "iot/water/w-7/inspect" {
		t.Fatalf("the worker got %q, want the job", job.Topic)
	}
}

func TestAWorkersPinIsNotServedBroadcastUnderItsChannelName(t *testing.T) {
	h := startNested(t)

	w := connect(t, h, "worker", true, false)
	w.Sub(t, "$saguin/queue/work", 1)
	onlooker := connect(t, h, "onlooker", true, false)
	onlooker.Sub(t, "work/#", 1)
	subscribed(t, w.C)
	subscribed(t, onlooker.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "work/not-a-job", "broadcast")

	if got, ok := onlooker.Await(t, 3*time.Second); !ok {
		t.Fatal("the broadcast reached no ordinary subscriber, so this test drove nothing")
	} else if got.Topic != "work/not-a-job" {
		t.Fatalf("the onlooker got %q, want work/not-a-job", got.Topic)
	}
	// And the queue still works, so the clearing above did not take the
	// jobs with it.
	//
	// **The job is the end marker for the broadcast.** The onlooker having
	// the broadcast says its fan-out has run (FannedOut), so a copy handed
	// to the worker is already in the worker's outbound queue, ahead of a
	// job offered after it.
	p.Pub(t, "iot/water/w-7/inspect", "check the valve")
	job, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the worker was offered no job, so the broadcast check proves nothing")
	}
	if job.Topic == "work/not-a-job" {
		t.Fatalf("a worker on the pin was handed %q, a broadcast topic its queue does "+
			"not hold: the pin names the channel and matches topics the channel has "+
			"no claim on, and this one arrives with no ticket to answer it with",
			job.Topic)
	}
	if job.Topic != "iot/water/w-7/inspect" {
		t.Fatalf("the worker got %q, want the job", job.Topic)
	}
}

func TestAQueueIsPinnedToItsNameWhateverItsFilter(t *testing.T) {
	h := startNested(t)

	// The pin, and nothing else.
	for _, tc := range []struct {
		why, filter string
		want        byte
	}{
		{"the form", "$saguin/queue/work", 0x01},
		{"the channel's filter, which is not the form", "iot/water/+/inspect", 0x8F},
		{"one topic inside the queue's filter", "iot/water/w-7/inspect", 0x8F},
		{"a level after the name", "$saguin/queue/work/w-7", 0x8F},
		{"the response topic's own level", "$saguin/queue/work/response", 0x8F},

		// A filter that merely *crosses* the queue is granted and served
		// everything except its records - otherwise `mosquitto_sub -t '#'`,
		// the first thing anyone types at a new broker, would be refused.
		{"a filter crossing the queue", "iot/water/w-7/#", 0x01},
	} {
		c := connect(t, h, "sub-"+strings.ReplaceAll(tc.why, " ", "-"), true, false)
		sa := c.Sub(t, tc.filter, 1)
		if sa == nil || len(sa.Reasons) != 1 {
			t.Fatalf("%s: no SUBACK for %q", tc.why, tc.filter)
		}
		if sa.Reasons[0] != tc.want {
			t.Errorf("%s: %q answered SUBACK 0x%02X, want 0x%02X",
				tc.why, tc.filter, sa.Reasons[0], tc.want)
		}
	}

	// And the pin actually carries work, so the row above is not a grant
	// over a subscription that receives nothing.
	w := connect(t, h, "worker", true, false)
	w.Sub(t, "$saguin/queue/work", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "iot/water/w-7/inspect", "check the valve")

	job, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a worker on the pin was offered nothing")
	}
	if job.Topic != "iot/water/w-7/inspect" || job.Payload != "check the valve" {
		t.Fatalf("the worker got %q on %q", job.Payload, job.Topic)
	}

	// Fail it to exhaustion and read it out of the dead-letter channel at
	// the derived topic. The channel keeps its flat name `work__dlq`, which
	// is what a seek and a snapshot file are built from; only the topic
	// gained a level.
	reader := connect(t, h, "dlq-reader", true, false)
	reader.Sub(t, "iot/water/+/inspect/__dlq", 1)

	for range maxAttempts {
		w.Respond(t, job.RespTopic, "return", job.CorrData)
		next, ok := w.Await(t, 3*time.Second)
		if !ok {
			break
		}
		job = next
	}

	dead, ok := reader.Await(t, 10*time.Second)
	if !ok {
		t.Fatal("a job that ran out of attempts reached no dead-letter reader: the topic " +
			"rewrite is what makes a dead letter reachable at all")
	}
	if dead.Topic != "iot/water/w-7/inspect/__dlq" {
		t.Errorf("the dead letter took the topic %q, want iot/water/w-7/inspect/__dlq",
			dead.Topic)
	}
	if dead.User["saguin-dlq-channel"] != "work" {
		t.Errorf("saguin-dlq-channel is %q, want work - the channel keeps its flat name",
			dead.User["saguin-dlq-channel"])
	}
}

// RFC 0002 "What a filter reaches", side effect 1 - invariants 4 and 11
//
// **A worker is offered nothing that a more exact filter took.** This is the
// case a channel claiming its name could not produce, and it is the one that
// hands a record to a worker outside every count saguin keeps: the worker's
// pin matches topics an append channel holds, so the substrate would deliver
// one as a stray message with no Delivery ID.
//
// It is a separate test from the one above because it fails silently - the
// worker simply receives one extra message - and because the guard it
// exercises is a single line that nothing else would notice the loss of.
func TestAWorkerIsOfferedNothingAnotherChannelHolds(t *testing.T) {
	h := startNested(t)

	w := connect(t, h, "worker", true, false)
	w.Sub(t, "$saguin/queue/work", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	// Every one of these matches the worker's pin under ordinary MQTT
	// matching, or sits one level below it, and none of them is the queue's.
	p.Pub(t, "iot/water/w-7/flow", "an append record")
	p.Pub(t, "iot/water/w-7/location", "current state")
	p.Pub(t, "iot/water/w-7/inspect/notes", "one level below the pin")

	if got, ok := w.Await(t, 1500*time.Millisecond); ok {
		t.Fatalf("a worker received %q on %q - it is subscribed to one queue and that "+
			"record belongs to another channel, so it arrived with no Delivery ID and "+
			"nothing to acknowledge it with", got.Payload, got.Topic)
	}

	// And the queue still works afterwards, so the guard did not simply
	// stop delivering to the worker altogether.
	p.Pub(t, "iot/water/w-7/inspect", "real work")
	job, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the worker was offered no work at all, so the guard above proves nothing")
	}
	if job.Payload != "real work" {
		t.Fatalf("the worker got %q, want the queue record", job.Payload)
	}
}

// RFC 0002 the `queue` section, "Shared subscriptions" - invariants 4 and 11
//
// **A shared subscription crossing a queue is granted and gets none of its
// records.** A broker whose only channel is a queue isolates that: a record
// reaching the shared subscriber here came from the queue and from nowhere
// else.
//
// It used to be a refusal, and giving `$share` back to MQTT replaced it
// with a structural answer. Queue records never enter the substrate's
// fan-out at all - they are injected to the one worker saguin chose - so a
// shared group over a queue's topics cannot be fed by the path that feeds
// every other shared group. Refusing it as well would mean working out
// which channels a filter touches, which is the analysis this change
// removed.
//
// **The grant is the weaker half and the silence is the test.** A refusal
// nobody drove for delivery could be granted and empty; this drives a real
// job past it and proves the worker got it and the shared subscriber did
// not.
func TestASharedSubscriptionCrossingAQueueGetsNoRecords(t *testing.T) {
	h := startQueueOnly(t)

	// **`+/urgent`, not `#`**, and the difference is what makes this a test
	// rather than a formality. This filter meets `jobs/#` at `jobs/urgent`
	// and meets nothing else: it lies inside no channel's filter, and the
	// `__dlq` level puts the dead-letter channel out of its way. It is the
	// shape that would get through any containment test.
	const crossing = "$share/g/+/urgent"
	spy := connect(t, h, "spy", true, false)
	sa := spy.Sub(t, crossing, 1)
	if sa == nil || len(sa.Reasons) != 1 {
		t.Fatalf("no SUBACK for %s", crossing)
	}
	if sa.Reasons[0] > 2 {
		t.Errorf("%s answered SUBACK 0x%02X - `$share` is MQTT's and saguin refuses it "+
			"for nothing it reaches", crossing, sa.Reasons[0])
	}

	// A worker on the form, and a job. The shared subscriber must receive
	// nothing, and the worker must receive the job - the second half being
	// what stops this passing against a broker that delivered to nobody.
	w := connect(t, h, "worker", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p := connect(t, h, "producer", true, false)
	// On the topic the shared filter matches, so a broker that fanned queue
	// records out has something to hand it.
	p.Pub(t, "jobs/urgent", "real work")

	job, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the worker was offered nothing, so the silence below proves nothing")
	}
	if job.Payload != "real work" {
		t.Fatalf("the worker got %q", job.Payload)
	}
	if got, ok := spy.Await(t, 500*time.Millisecond); ok {
		t.Fatalf("a shared subscriber received %q on %q - queue records leave through "+
			"the queue's own form and no other, and this one has no ticket to answer "+
			"it with (invariant 4)", got.Payload, got.Topic)
	}
}

// **One consumer, two append channels, one Receive Maximum between them.**
//
// A channel that fills the window leaves the others no room, and a PUBACK
// re-pumping only the acknowledged packet's channel sends every slot it
// frees straight back to itself. When that channel runs dry the
// acknowledgements stop and the others are never woken again: a consumer
// frozen part-way through with its position intact and nothing in any log.
//
// **The soak found this and is the wrong place to guard it**, which is why
// this exists beside it rather than instead of it. A frozen channel stays
// frozen only until the next record published to it, and the soak's
// producers publish for the whole dial - so only a freeze left standing at
// the very end can be seen, and the longer the soak the smaller that tail
// is in proportion. The guard weakened as the dial lengthened, which is the
// opposite of what a longer soak is for: reverted, the soak goes red at the
// short dial and green at `SOAK=2m`.
//
// Here nothing publishes after the backlog exists, so there is nothing to
// wake a starved channel and the freeze is the whole of what is measured.
// It holds at any dial because there is no dial.
func TestOneConsumerIsServedEveryChannelItsFilterReaches(t *testing.T) {
	h := startSoaking(t, filepath.Join(t.TempDir(), "starve.db"))

	// A backlog in each, before the consumer exists. `iot/hq/events/<i>`
	// belongs to `hq` and `iot/site/events/<i>` to `events`, because a
	// spelled-out level beats `+` at level 1.
	const each = 60
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= each; i++ {
		p.Pub(t, fmt.Sprintf("iot/site/events/%d", i), fmt.Sprintf("s%d", i))
		p.Pub(t, fmt.Sprintf("iot/hq/events/%d", i), fmt.Sprintf("h%d", i))
	}
	time.Sleep(300 * time.Millisecond)

	// **A window smaller than either backlog**, which is what makes the two
	// channels compete for it. With room for both there is nothing to
	// starve, and this test would pass over the defect it is named for.
	got := map[string]int{}
	var mu sync.Mutex
	c := dialAt(t, h.Addr, h.Network, "starved", true, false, 4, 300, 0,
		func(topic string, _ uint64) {
			mu.Lock()
			defer mu.Unlock()
			if strings.HasPrefix(topic, "iot/hq/") {
				got["hq"]++
			} else {
				got["events"]++
			}
		}, nil)
	c.Sub(t, "#", 1)

	// Both drain, or one of them does not. 20s is far past what 120 records
	// take when nothing is starved - the run below settles in about one -
	// and it is the difference between "slow" and "stuck" that this waits
	// out rather than assumes.
	deadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		done := got["events"] >= each && got["hq"] >= each
		mu.Unlock()
		if done {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}

	mu.Lock()
	defer mu.Unlock()
	for _, ch := range []string{"events", "hq"} {
		if got[ch] < each {
			t.Errorf("the consumer received %d of %d records from channel %q, and %d from "+
				"the other: one filter reaches both channels and they share one Receive "+
				"Maximum, so a channel that fills the window must not keep every slot it "+
				"frees. A freed slot belongs to the client",
				got[ch], each, ch, got[map[string]string{"events": "hq", "hq": "events"}[ch]])
		}
	}
}

// RFC 0002 "Retained messages on a broadcast topic": *the value goes back
// out as it was published.*
//
// **It did not carry what the publisher sent.** The payload was kept and
// its User Properties and Content Type were not, so a device retaining a
// Content Type on its status topic - which is what Content Type is for -
// had it seen by whoever happened to be subscribed at that moment and by
// nobody who subscribed later. The same message read two ways depending on
// when you arrived.
//
// **The live delivery is the yardstick rather than a list written here.**
// Asserting a remembered set would go stale the moment a property is added
// to the packet; asserting that the stored copy matches the live one says
// the rule, and the rule is that they are the same message. A `latest`
// channel - which RFC 0002 calls the same thing under a different name -
// kept them throughout, which is what made this a defect rather than a
// decision.
//
// What saguin adds is still not stamped on: a broadcast message has no
// record identity and no position, and giving it one on the way out would
// make broadcast look like a channel.
func TestARetainedValueKeepsWhatThePublisherSent(t *testing.T) {
	h := startRetaining(t, 0)

	live := connect(t, h, "live", true, false)
	live.Sub(t, "loose/#", 1)
	time.Sleep(150 * time.Millisecond)

	p := connect(t, h, "producer", true, false)
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "loose/kept", QoS: 1, Retain: true, Payload: []byte("v2"),
		Properties: &paho.PublishProperties{
			ContentType: "text/plain",
			// Repeated on purpose: MQTT 5 allows one name more than once
			// and that is the standard way to carry a list, so a store that
			// kept only the last would lose data the publisher sent.
			User: paho.UserProperties{
				{Key: "mine", Value: "kept"},
				{Key: "tag", Value: "a"},
				{Key: "tag", Value: "b"},
			},
		},
	}); err != nil {
		t.Fatalf("retained publish: %v", err)
	}

	fromWire, ok := live.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the retained publish reached nobody live")
	}

	// A subscriber that was not there: served from saguin's own store.
	later := connect(t, h, "later", true, false)
	later.Sub(t, "loose/#", 1)
	fromStore, ok := later.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("a later subscriber was served no retained value")
	}

	if !fromStore.Retain {
		t.Error("the stored copy arrived without the retain flag, so a client cannot tell " +
			"catch-up from something that has just happened")
	}
	if fromStore.Payload != fromWire.Payload {
		t.Fatalf("payload %q from the store, %q live", fromStore.Payload, fromWire.Payload)
	}
	for k, v := range fromWire.User {
		if fromStore.User[k] != v {
			t.Errorf("the stored copy lost the publisher's %q: %q live, %q from the store",
				k, v, fromStore.User[k])
		}
	}
	// And nothing saguin adds: broadcast has no identity and no position.
	for _, k := range []string{"saguin-id", "saguin-offset"} {
		if _, stamped := fromStore.User[k]; stamped {
			t.Errorf("the stored copy gained %q, which makes broadcast look like a channel", k)
		}
	}
}

// **A durable consumer resumed mid-replay is still owed its backlog**, and
// it stopped receiving one.
//
// A consumer whose socket dies with records unacknowledged leaves those
// packets in the session. The substrate restores them on resume and
// re-sends them - but saguin forgot its own record of them at the
// disconnect, so their acknowledgements arrive as packets it has never
// heard of, and the window room they free is used by nothing. The
// resume-time pump has already run and found the window full. The consumer
// then sits connected with `Session Present` = 1 and its position intact,
// receiving none of what it is owed, until an unrelated publish to one of
// its channels wakes it. Nothing is logged, because from the broker's side
// nothing went wrong.
//
// **Nothing is published after the resume**, which is the whole design of
// this test. A freeze here is only visible while the channels are quiet:
// any later record wakes it and delivers the backlog behind it, which is
// why the soak passes over this and why its own comment says it is not the
// guard for this shape either.
//
// **Manual acknowledgement, and it is not a detail.** With auto-acknowledge
// a small backlog drains faster than a kill can land, and the state this is
// about is a socket dying with packets still in flight. The first version
// of this probe killed a consumer that had already received everything and
// proved nothing.
func TestAResumedConsumerIsStillOwedItsBacklog(t *testing.T) {
	h := startSoaking(t, filepath.Join(t.TempDir(), "resume.db"))

	// A backlog in each of the two append channels one filter reaches.
	const each = 40
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= each; i++ {
		p.Pub(t, fmt.Sprintf("iot/site/events/%d", i), fmt.Sprintf("s%d", i))
		p.Pub(t, fmt.Sprintf("iot/hq/events/%d", i), fmt.Sprintf("h%d", i))
	}
	time.Sleep(300 * time.Millisecond)

	var mu sync.Mutex
	seen := map[string]map[string]bool{"events": {}, "hq": {}}
	count := func() int {
		mu.Lock()
		defer mu.Unlock()
		return len(seen["events"]) + len(seen["hq"])
	}
	record := func(topic string, _ uint64) {
		mu.Lock()
		defer mu.Unlock()
		if strings.HasPrefix(topic, "iot/hq/") {
			seen["hq"][topic] = true
		} else {
			seen["events"][topic] = true
		}
	}

	// Clean Start = 0 and a real expiry, so the session survives the kill.
	// Manual acknowledgement paces it: the records arrive and are held.
	first := dialAt(t, h.Addr, h.Network, "resumer", false, true, 4, 600, 0, record, nil)
	first.Sub(t, "#", 1)

	deadline := time.Now().Add(10 * time.Second)
	for count() < 8 && time.Now().Before(deadline) {
		time.Sleep(20 * time.Millisecond)
	}
	if count() == 0 {
		t.Fatal("the consumer received nothing at all before the kill, so nothing below " +
			"is about a resume")
	}
	// The link dies rather than closing politely: unacknowledged packets
	// stay in the session and are re-sent on resume, which is the state
	// this is about.
	_ = first.Conn.Close()
	time.Sleep(500 * time.Millisecond)

	second := dialAt(t, h.Addr, h.Network, "resumer", false, false, 4, 600, 0, record, nil)
	if !second.SessionPresent {
		t.Fatal("the resumed session was not present, so this drove a fresh consumer " +
			"rather than a resume")
	}

	// Nothing is published from here on: the backlog is all there is.
	settled := time.Now().Add(15 * time.Second)
	for count() < each*2 && time.Now().Before(settled) {
		time.Sleep(100 * time.Millisecond)
	}

	mu.Lock()
	defer mu.Unlock()
	for _, ch := range []string{"events", "hq"} {
		if len(seen[ch]) < each {
			t.Errorf("after resuming, the consumer holds %d of %d records from channel %q "+
				"(%d from the other) and nothing more arrived: a resumed session is owed "+
				"its backlog, and a freed in-flight slot belongs to the client whatever "+
				"freed it - including a packet the broker no longer recognises, which is "+
				"what its own re-sent deliveries become",
				len(seen[ch]), each, ch,
				len(seen[map[string]string{"events": "hq", "hq": "events"}[ch]]))
		}
	}
}

// **The lowest stored position is a reading, and this is what it is a
// reading from.**
//
// On its own that gauge cannot tell one straggler in a fleet of three
// hundred from a single consumer that has stopped: both read as one number
// a long way behind, and one of those is a device to replace in the morning
// while the other is a page tonight. The denominator separates them.
//
// **The discriminating case is the last one**, and it is why this is not a
// test that two consumers make the gauge say two. A count that merely
// counted *connections*, or one taken from the same walk but reported for
// the wrong channel, would satisfy everything above it - so the check is
// that the two gauges disagree in the way they should: two consumers, one
// far behind, giving `consumers = 2` and `position_min` equal to the low
// one rather than to either the high one or the count.
func TestTheConsumerCountIsWhatTheLowestPositionIsAReadingFrom(t *testing.T) {
	h := startDurable(t, t.TempDir())

	scrape := func() map[string]string {
		t.Helper()
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatalf("pick a port: %v", err)
		}
		addr := ln.Addr().String()
		_ = ln.Close()
		stop, err := h.B.ServeOperations(tcpOnly(addr), 0, nil, nil)
		if err != nil {
			t.Fatalf("serve operations: %v", err)
		}
		defer stop()
		resp, err := http.Get("http://" + addr + "/metrics")
		if err != nil {
			t.Fatalf("scrape: %v", err)
		}
		body, err := io.ReadAll(resp.Body)
		resp.Body.Close()
		if err != nil {
			t.Fatalf("read the scrape: %v", err)
		}
		out := map[string]string{}
		for _, l := range strings.Split(string(body), "\n") {
			if i := strings.LastIndex(l, " "); i > 0 && !strings.HasPrefix(l, "#") {
				out[l[:i]] = strings.TrimSpace(l[i:])
			}
		}
		return out
	}

	const series = `saguin_channel_consumers{channel="events"}`

	// **Zero is a fact and carries a series.** An absent one would read as a
	// channel that cannot have consumers, which is what a `latest` or a
	// queue channel is - and the difference is what an operator checks when
	// a fleet has gone quiet.
	if got, ok := scrape()[series]; !ok || got != "0" {
		t.Fatalf("a channel nobody reads reports %q (present=%v), want 0: an absent "+
			"series reads as a channel that cannot have consumers", got, ok)
	}

	p := connect(t, h, "publisher", true, false)
	for i := 1; i <= 4; i++ {
		p.Pub(t, "events/orders", fmt.Sprintf("order-%d", i))
	}

	// Two durable consumers, one of which acknowledges everything and one
	// of which stops after the first record.
	ahead := connect(t, h, "ahead", false, true)
	ahead.Sub(t, "events/#", 1)
	for range 4 {
		r, ok := ahead.Await(t, 3*time.Second)
		if !ok {
			t.Fatal("the caught-up consumer did not receive all four")
		}
		r.Ack()
	}
	behind := connect(t, h, "behind", false, true)
	behind.Sub(t, "events/#", 1)
	// **Two, so that the count and the position cannot be the same number.**
	// With one acknowledged the straggler sits at position 2 and the count
	// is also 2, and a gauge reporting the wrong one of the two reads
	// correct - which a mutation proved, on the first version of this test,
	// under a comment claiming it could not.
	for range 2 {
		r, ok := behind.Await(t, 3*time.Second)
		if !ok {
			t.Fatal("the straggler received nothing")
		}
		r.Ack()
	}

	// Waited for rather than slept through: positions are written on the
	// broker's tick, after Paho's own acknowledgement ticker.
	awaitStoredPosition(t, h, "events", 3, 5*time.Second)

	got := scrape()
	if got[series] != "2" {
		t.Errorf("two durable consumers hold a position and the gauge says %q - and "+
			"the lowest position is 3, so this cannot be right by reporting that "+
			"instead", got[series])
	}
	// The discriminating half: the two gauges report different facts about
	// one fleet, and the numbers differ, so neither can stand in for the
	// other unnoticed.
	if low := got[`saguin_channel_consumer_position_min{channel="events"}`]; low != "3" {
		t.Errorf("the lowest stored position is %q, want 3 - the straggler's, and not "+
			"the count of 2", low)
	}
}

// RFC 0003 "What a reconnecting consumer receives", docs/invariants.md 1
//
// **A resumed session is served the records it is owed, and not the ones it
// already holds.** A socket that dies with records in flight leaves those
// packets in the session, and MQTT requires the session to re-send them
// (§4.4, with their original packet identifiers and the DUP flag set). If
// saguin also serves them from its stored position, every one of them
// arrives twice per reconnect - the second copy carrying a fresh packet
// identifier and no DUP flag, so a consumer cannot even tell it apart from a
// new record by looking at the packet.
//
// **Why this outranked everything else it was found beside.** The cost is
// bounded by the consumer's Receive Maximum, which sounds small and is not,
// because it compounds: the extra copies take the consumer's time, so it
// falls further behind, so more records are in flight when the link next
// drops. Measured at a window of 256 with the link dropping once a second, a
// consumer that did not deduplicate never caught up at all - 55,000
// deliveries to make 713 records of progress against a backlog of 4,000 -
// where the same consumer drained it in 18s with the cursor kept.
//
// The counting is by offset and not by topic, which is the whole difference
// between this test and the one above it: that one holds a set of topics, so
// a record arriving twice is invisible to it, and it passed against this
// defect throughout.
func TestAResumedConsumerIsNotServedItsInFlightRecordsTwice(t *testing.T) {
	h := startSoaking(t, filepath.Join(t.TempDir(), "twice.db"))

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "iot/hq/events/x", "p1")
	p.Pub(t, "iot/z/events/q", "p2")
	settle(t, p)

	var mu sync.Mutex
	deliveries := map[string]int{}
	note := func(topic string, _ uint64) {
		mu.Lock()
		defer mu.Unlock()
		deliveries[topic]++
	}
	count := func() int {
		mu.Lock()
		defer mu.Unlock()
		n := 0
		for _, v := range deliveries {
			n += v
		}
		return n
	}

	// Manual acknowledgement and nothing acknowledged, so both records are
	// in flight when the link dies. With auto-acknowledge they are answered
	// before the kill lands and this drives nothing.
	first := dialAt(t, h.Addr, h.Network, "resumer", false, true, 4, 600, 0, note, nil)
	first.H, first.ID = h, "resumer" // for linkCut, below
	first.Sub(t, "iot/+/events/+", 1)
	deadline := time.Now().Add(10 * time.Second)
	for count() < 2 && time.Now().Before(deadline) {
		time.Sleep(20 * time.Millisecond)
	}
	if count() != 2 {
		t.Fatalf("the consumer holds %d of 2 records before the kill, so nothing below "+
			"is about a resume", count())
	}
	linkCut(t, first)

	// One more record, so the resume has something genuinely owed to it and
	// a run that delivered nothing at all cannot pass.
	p.Pub(t, "iot/z/events/late", "p3")
	settle(t, p)

	second := dialAt(t, h.Addr, h.Network, "resumer", false, false, 4, 600, 0, note, nil)
	if !second.SessionPresent {
		t.Fatal("the resumed session was not present, so this drove a fresh consumer " +
			"rather than a resume")
	}
	// **An end marker rather than a second's quiet**: a record published
	// now is stored after every copy saguin could serve from the position,
	// and an append channel is served in offset order, so once it has
	// arrived any second copy has too. The session's own re-send goes
	// first of all, at the resume.
	p.Pub(t, "iot/z/events/marker", "marker")
	if !waitUntil(10*time.Second, func() bool {
		mu.Lock()
		defer mu.Unlock()
		return deliveries["iot/z/events/marker"] > 0
	}) {
		t.Fatal("the end marker never reached the resumed consumer")
	}

	mu.Lock()
	defer mu.Unlock()
	if deliveries["iot/z/events/late"] == 0 {
		t.Error("the record published while the consumer was away never arrived, so the " +
			"counts below are about a resume that delivered nothing")
	}
	for _, topic := range []string{"iot/hq/events/x", "iot/z/events/q"} {
		// Two: once before the kill, once as the session's own re-send.
		if n := deliveries[topic]; n > 2 {
			t.Errorf("%s was delivered %d times - once before the link died, once as "+
				"the session's re-send, and %d more from saguin serving its stored "+
				"position over the top of it", topic, n, n-2)
		}
	}
}

// The same rule on a `latest` channel, which reaches it by a different
// route: there is no cursor there, and the position is one number per
// channel. It was the same defect - the number was the highest offset
// *acknowledged*, so everything sent and unacknowledged was served again
// beside the session's own re-send.
func TestAResumedLatestSubscriberIsNotServedItsInFlightValuesTwice(t *testing.T) {
	h := startSoaking(t, filepath.Join(t.TempDir(), "twice-latest.db"))

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "iot/a/state/temp", "t1")
	p.Pub(t, "iot/b/state/temp", "t2")
	settle(t, p)

	var mu sync.Mutex
	deliveries := map[string]int{}
	offsets := map[string][]uint64{}
	note := func(topic string, offset uint64) {
		mu.Lock()
		defer mu.Unlock()
		deliveries[topic]++
		offsets[topic] = append(offsets[topic], offset)
	}
	count := func() int {
		mu.Lock()
		defer mu.Unlock()
		n := 0
		for _, v := range deliveries {
			n += v
		}
		return n
	}

	first := dialAt(t, h.Addr, h.Network, "latest-resumer", false, true, 4, 600, 0, note, nil)
	first.H, first.ID = h, "latest-resumer" // for linkCut, below
	first.Sub(t, "iot/+/state/+", 1)
	deadline := time.Now().Add(10 * time.Second)
	for count() < 2 && time.Now().Before(deadline) {
		time.Sleep(20 * time.Millisecond)
	}
	if count() != 2 {
		t.Fatalf("the subscriber holds %d of 2 values before the kill", count())
	}
	linkCut(t, first)

	p.Pub(t, "iot/c/state/temp", "t3")
	settle(t, p)

	second := dialAt(t, h.Addr, h.Network, "latest-resumer", false, false, 4, 600, 0, note, nil)
	if !second.SessionPresent {
		t.Fatal("the resumed session was not present")
	}
	deadline = time.Now().Add(10 * time.Second)
	for count() < 5 && time.Now().Before(deadline) {
		time.Sleep(50 * time.Millisecond)
	}

	// **A marker on each topic rather than a second's quiet.** A latest
	// channel is ordered per topic, so a value published on a topic now
	// reaches the subscriber after any copy of that topic's older value -
	// and, offsets rising across the channel, it is the one delivery above
	// everything seen so far.
	mu.Lock()
	var seen uint64
	for _, offs := range offsets {
		for _, o := range offs {
			seen = max(seen, o)
		}
	}
	mu.Unlock()
	topics := []string{"iot/a/state/temp", "iot/b/state/temp"}
	for _, topic := range topics {
		p.Pub(t, topic, "marker")
	}
	marked := func() bool {
		mu.Lock()
		defer mu.Unlock()
		for _, topic := range topics {
			if slices.Max(append([]uint64{0}, offsets[topic]...)) <= seen {
				return false
			}
		}
		return true
	}
	if !waitUntil(10*time.Second, marked) {
		t.Fatalf("the end markers never reached the subscriber: %v", offsets)
	}

	mu.Lock()
	defer mu.Unlock()
	for _, topic := range topics {
		deliveries[topic]-- // the marker
	}
	if deliveries["iot/c/state/temp"] == 0 {
		t.Error("the value written while the subscriber was away never arrived: a resumed " +
			"session is served what changed while it was gone")
	}
	for _, topic := range []string{"iot/a/state/temp", "iot/b/state/temp"} {
		if n := deliveries[topic]; n > 2 {
			t.Errorf("%s was delivered %d times, %d more than the session's own re-send",
				topic, n, n-2)
		}
	}
}

// **The control for both of the above, and the reason the stored position is
// still the lowest unacknowledged offset.**
//
// A resumed *session* re-sends what was in flight, so saguin does not have
// to. A **restart** has no session to do it: the substrate's in-flight set
// is memory and invariant 15 says no delivery comes back as live. So the
// stored position must still sit below every unacknowledged record, and the
// consumer must be served them again - the alternative is a consumer resumed
// above records it never received, told it is caught up, which is invariant
// 1's failure and is worse than the duplicate the tests above are about.
//
// Without this, "keep the position above what was sent" reads as a tidier
// rule everywhere and loses data in exactly one place.
func TestARestartStillResendsWhatWasNeverAcknowledged(t *testing.T) {
	dir := t.TempDir()
	h := startDurable(t, dir)

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 4; i++ {
		p.Pub(t, fmt.Sprintf("events/r/%d", i), fmt.Sprintf("v%d", i))
	}
	settle(t, p)

	// Acknowledges the first two and holds the rest.
	reader := connect(t, h, "reader", false, true)
	reader.Sub(t, "events/#", 1)
	var held []received
	for i := 1; i <= 4; i++ {
		r, ok := reader.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("before the restart the consumer received %d of 4", i-1)
		}
		if i <= 2 {
			r.Ack()
		} else {
			held = append(held, r)
		}
	}
	if len(held) != 2 {
		t.Fatalf("setup: %d records held unacknowledged, want 2", len(held))
	}
	// **Waited for, not slept through, and the difference decides whether
	// this test discriminates at all.** Paho batches manual acknowledgements
	// on a 50ms ticker of its own, and positions are written on the broker's
	// tick after that. Stopping the broker before both have run leaves the
	// stored position at the floor, so the restart re-serves the whole
	// channel - which contains v3 and v4, so the assertions below pass while
	// proving nothing. Measured: the first version of this saw v1 v2 v3 v4.
	awaitStoredPosition(t, h, "events", 3, 5*time.Second)

	h.Stop()
	h2 := startDurable(t, dir)

	// A restarted broker has no session for it, so what arrives here is
	// saguin's stored position and nothing that MQTT re-sent.
	back := connect(t, h2, "reader", false, false)
	back.Sub(t, "events/#", 1)
	got := map[string]bool{}
	for range 4 {
		r, ok := back.Await(t, 3*time.Second)
		if !ok {
			break
		}
		got[r.Payload] = true
	}
	// The acknowledged pair is not re-served, which is what says the stored
	// position was the lowest unacknowledged offset rather than the floor.
	for _, acked := range []string{"v1", "v2"} {
		if got[acked] {
			t.Errorf("%q was served again after the restart although it was "+
				"acknowledged, so the position under test was the floor and this "+
				"run proves nothing about it", acked)
		}
	}
	for _, want := range []string{"v3", "v4"} {
		if !got[want] {
			t.Errorf("after the restart the consumer was not served %q, which it had "+
				"never acknowledged: nothing re-sends it across a restart, so a "+
				"position above it is a record delivered to nobody (invariant 1). "+
				"Got %v", want, got)
		}
	}
}

// **The sibling to check whenever the cursor outlives the connection.** A
// client that had a durable session and comes back asking for a clean one is
// told Session Present = 0, and RFC 0003 says it starts fresh at the
// channel's retention floor. Inheriting the cursor it was just told it did
// not have would serve it from where the old session stopped instead -
// silently, since the signal and the behaviour would disagree with nothing
// reporting it.
func TestACleanStartAfterADurableSessionStartsFresh(t *testing.T) {
	h := startDurableSQLite(t, filepath.Join(t.TempDir(), "clean.db"))

	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 6; i++ {
		p.Pub(t, fmt.Sprintf("events/r/%d", i), fmt.Sprintf("v%d", i))
	}
	settle(t, p)

	first := connect(t, h, "reader", false, false)
	first.Sub(t, "events/#", 1)
	for i := 1; i <= 6; i++ {
		if _, ok := first.Await(t, 3*time.Second); !ok {
			t.Fatalf("the durable session read %d of 6, so it never reached the end", i-1)
		}
	}
	gone(t, first)

	second := connect(t, h, "reader", true, false)
	if second.SessionPresent {
		t.Fatal("Clean Start = 1 was answered Session Present = 1")
	}
	second.Sub(t, "events/#", 1)
	seen := map[string]bool{}
	for range 6 {
		r, ok := second.Await(t, 3*time.Second)
		if !ok {
			break
		}
		seen[r.Payload] = true
	}
	if len(seen) != 6 {
		t.Errorf("a clean session was served %d of the 6 records in the channel: it was "+
			"told it had no session, so it starts at the floor and is owed all of "+
			"them. Got %v", len(seen), seen)
	}
}

// **A publish above the advertised Maximum QoS is refused, not downgraded.**
//
// Raw bytes, because no conforming client will send this: the CONNACK says
// Maximum QoS 1 and [MQTT-3.2.2-9] forbids a client exceeding it. A client
// that does anyway is covered by section 3.2.2.3.4, and what it names is not
// a negotiation - *"If a Server receives a PUBLISH packet with a QoS greater
// than the Maximum QoS then it MUST respond with a DISCONNECT packet
// containing Reason Code 0x9B."*
//
// **What made this worth a MUST is the failure it prevents.** The substrate
// rewrote the packet's QoS to 1 and acknowledged it, so a QoS 2 PUBLISH was
// answered `PUBACK` reason `0x00`, Success. The publisher asked for
// exactly-once, was told it had it, and got at-least-once: a guarantee
// downgraded and reported as met, which is the shape docs/invariants.md puts
// ahead of a crash because nobody goes looking for it. Found by running the
// Eclipse Paho MQTT 5 interoperability suite against saguin, where it
// accounted for most of the failures.
//
// The PUBACK is asserted against by packet type as well as by reason code,
// because the defect's whole signature was a *successful-looking* answer.
func TestAPublishAboveTheAdvertisedMaximumQoSIsRefused(t *testing.T) {
	// **A client denied `qos2`**, which is what this case is about: the
	// refusal exists for a client whose CONNACK said Maximum QoS 1.
	h := start(t)
	denyFeatures(t, h, "    - broker: features\n      deny: [qos2]\n")

	// Somebody who would see it if it were accepted and downgraded. On the
	// topic's own prefix rather than `#`, which measured nothing delivered
	// under the acl_file this harness installs - and a watcher that can see
	// nothing makes "it reached nobody" pass on its own.
	watcher := connect(t, h, "qos-watcher", true, false)
	watcher.Sub(t, "loose/#", 1)
	time.Sleep(100 * time.Millisecond)

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	connect := []byte{
		0x10, 0x11,
		0x00, 0x04, 'M', 'Q', 'T', 'T',
		0x05, 0x02, 0x00, 0x3c, 0x00,
		0x00, 0x04, 'q', 'o', 's', '2',
	}
	if _, err := conn.Write(connect); err != nil {
		t.Fatalf("write connect: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	fh := make([]byte, 2)
	if _, err := io.ReadFull(conn, fh); err != nil {
		t.Fatalf("no CONNACK: %v", err)
	}
	ca := make([]byte, int(fh[1]))
	if _, err := io.ReadFull(conn, ca); err != nil {
		t.Fatalf("short CONNACK: %v", err)
	}

	// PUBLISH at QoS 2: fixed header 0x30 with the QoS bits set to 2.
	topic := []byte("loose/too-high")
	var body []byte
	body = append(body, byte(len(topic)>>8), byte(len(topic)))
	body = append(body, topic...)
	body = append(body, 0x00, 0x01) // packet identifier
	body = append(body, 0x00)       // no properties
	body = append(body, 'x')
	if _, err := conn.Write(append([]byte{0x30 | (2 << 1), byte(len(body))}, body...)); err != nil {
		t.Fatalf("write publish: %v", err)
	}

	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	reply := make([]byte, 2)
	if _, err := io.ReadFull(conn, reply); err != nil {
		t.Fatalf("nothing came back for a QoS 2 publish: %v", err)
	}
	tail := make([]byte, int(reply[1]))
	_, _ = io.ReadFull(conn, tail)

	switch reply[0] >> 4 {
	case 4:
		t.Fatalf("a QoS 2 publish was acknowledged: PUBACK % 02x - the publisher "+
			"asked for exactly-once and has been told it got it", tail)
	case 5:
		t.Fatalf("a QoS 2 publish was answered PUBREC % 02x, which begins the "+
			"handshake for a QoS saguin does not implement", tail)
	case 14:
		// A DISCONNECT, which is the answer the specification names.
	default:
		t.Fatalf("answered packet type %d, want a DISCONNECT", reply[0]>>4)
	}
	if len(tail) == 0 || tail[0] != 0x9B {
		t.Errorf("disconnected with % 02x, want 0x9B QoS not supported", tail)
	}

	// And it reached nobody: refused rather than delivered at a QoS the
	// publisher did not ask for.
	if got, ok := watcher.Await(t, 500*time.Millisecond); ok {
		t.Errorf("the refused publish was delivered to %q", got.Topic)
	}

	// The watcher is proved live, so "reached nobody" is about the refusal
	// rather than about a subscription that never worked.
	// dial rather than connect, which the raw CONNECT bytes above shadow.
	dial(t, h, "qos-control", true, false, 0, 3600, 0).Pub(t, "loose/control", "ok")
	if got, ok := watcher.Await(t, 3*time.Second); !ok || got.Topic != "loose/control" {
		t.Fatalf("the watcher did not receive an ordinary publish (%q, %v), so this test proved nothing",
			got.Topic, ok)
	}

	// **Counted twice, once in each series**, as a refused retained publish
	// is (RFC 0005): a refused publish, and the connection it cost. Counted
	// only as a connection, the ratio of the two read as a connection lost to
	// a publish nobody refused.
	got := scrapeGauges(t, operationsAt(t, h))
	for _, series := range []string{
		`saguin_publish_refused_total{reason="qos not supported"}`,
		`saguin_connections_refused_total{reason="qos not supported"}`,
	} {
		if got[series] != 1 {
			t.Errorf("%s is %v after one refused QoS 2 publish, want 1", series, got[series])
		}
	}
}

// The other half of the same rule, and the half that must not change: QoS 0
// and QoS 1 are at or below the advertised maximum and are ordinary
// publishes. A refusal written as "anything but QoS 1" would pass the test
// above and break every publisher there is.
func TestPublishesAtOrBelowTheMaximumQoSAreUnaffected(t *testing.T) {
	// **A client denied `qos2`**, which is what this case is about: the
	// refusal exists for a client whose CONNACK said Maximum QoS 1.
	h := start(t)
	denyFeatures(t, h, "    - broker: features\n      deny: [qos2]\n")
	watcher := connect(t, h, "qos-ok-watcher", true, false)
	watcher.Sub(t, "loose/#", 1)
	time.Sleep(100 * time.Millisecond)

	pub := connect(t, h, "qos-ok-pub", true, false)
	for _, qos := range []byte{0, 1} {
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/fine", QoS: qos, Payload: []byte("x"),
		}); err != nil {
			t.Fatalf("publish at QoS %d: %v", qos, err)
		}
		if _, ok := watcher.Await(t, 3*time.Second); !ok {
			t.Fatalf("a QoS %d publish was not delivered", qos)
		}
	}
}

// **A channel's records carry the Subscription Identifier, as MQTT 5
// section 3.3.4 makes a MUST.**
//
// The failure this prevents is not that a field is missing; it is that the
// *same client on the same connection* got two behaviours. Broadcast is
// fanned out by the substrate and carried its identifier; a channel's
// records are written by saguin and carried none. Which of the two a
// message got depended on whether an operator had placed a channel over
// that topic - and RFC 0002 "What a filter reaches" says a client is
// deliberately not told where the channels are.
//
// So a device works against a broker with no channels, an operator adds
// one, and the device stops handling those messages with nothing to point
// at: a library routing callbacks by identifier, which is what the field
// is for, sends them to its fallback handler or drops them.
//
// Broadcast is asserted here beside the two channel types rather than
// trusted, because it is the half that already worked and the comparison
// is the whole point.
func TestAChannelDeliveryCarriesItsSubscriptionIdentifier(t *testing.T) {
	h := start(t)
	c := connect(t, h, "ident-reader", true, false)

	for _, tc := range []struct {
		what   string
		filter string
		topic  string
		id     int
	}{
		{"an append channel", "events/#", "events/one", 7},
		{"a latest channel", "state/#", "state/one", 8},
		{"broadcast, which the substrate delivers", "loose/#", "loose/one", 9},
	} {
		t.Run(tc.what, func(t *testing.T) {
			c.SubWithID(t, tc.filter, 1, tc.id)
			pub := connect(t, h, "ident-writer-"+tc.topic, true, false)
			pub.Pub(t, tc.topic, "x")

			got, ok := c.Await(t, 3*time.Second)
			if !ok {
				t.Fatalf("nothing was delivered for %s", tc.filter)
			}
			if got.Topic != tc.topic {
				t.Fatalf("delivered %q, want %q", got.Topic, tc.topic)
			}
			if len(got.SubIDs) == 0 {
				t.Fatalf("%s delivered with no Subscription Identifier: a client "+
					"routing by it sends this to its fallback handler", tc.what)
			}
			if got.SubIDs[0] != tc.id {
				t.Errorf("Subscription Identifier %d, want %d", got.SubIDs[0], tc.id)
			}
		})
	}
}

// **A retained value carries it too**, and this is the pair that made the
// gap visible: a live broadcast message and the retained value on the same
// topic are the same client's same subscription, and they were answered
// differently. The live one is written by the substrate and carried its
// identifier; the retained one is written by saguin, out of a store that is
// not a channel and whose subscribers are therefore not in saguin's index,
// and carried none.
func TestARetainedDeliveryCarriesItsSubscriptionIdentifier(t *testing.T) {
	h := startRetaining(t, 0)

	pub := connect(t, h, "retain-writer", true, false)
	pub.PubRetained(t, "loose/kept", "v")
	settle(t, pub)

	c := connect(t, h, "retain-reader", true, false)
	c.SubWithID(t, "loose/#", 1, 31)

	got, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the retained value was not delivered")
	}
	if !got.Retain {
		t.Errorf("delivered without the RETAIN flag, so this is not the stored value")
	}
	if len(got.SubIDs) == 0 || got.SubIDs[0] != 31 {
		t.Errorf("Subscription Identifier %v, want [31] - the live message on this "+
			"topic carries one and the stored value must not differ", got.SubIDs)
	}
}

// MQTT 5 §3.8.4 permits a server to "start sending PUBLISH packets matching
// the Subscription before the Server sends the SUBACK", so both orders are
// legal and this is not a conformance rule. It is a compatibility one.
//
// **saguin was the only broker in the room doing it.** The substrate writes
// the SUBACK and then sends its own retained messages; mosquitto 2.0.22,
// measured as the control, does the same. saguin sent its retained values,
// its replays and its latest state first, because the hook that decides
// them runs one line before the write. A client library that reads one
// packet expecting its acknowledgement got a message instead:
// `sammiq/mqtt_test` reported nine separate rules as failures on that
// alone, each reading a message where the SUBACK was due and then reading
// the SUBACK as the next test's message.
//
// Driven on a raw socket because the ordering is the whole question and a
// client library hides it: Paho reads both packets and dispatches each to
// the right place whichever came first.
func TestASubscriptionIsAcknowledgedBeforeAnythingItEarns(t *testing.T) {
	for _, tc := range []struct {
		name, filter, what string
		setUp              func(t *testing.T, h *harness)
	}{
		{"a retained value", "loose/#", "the retained value", func(t *testing.T, h *harness) {
			pub := connect(t, h, "order-retain-writer", true, false)
			pub.PubRetained(t, "loose/kept", "v")
			settle(t, pub)
		}},
		{"an append channel's replay", "events/#", "the replayed record",
			func(t *testing.T, h *harness) {
				pub := connect(t, h, "order-append-writer", true, false)
				pub.Pub(t, "events/orders/1", "order-1")
				settle(t, pub)
			}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := startRetaining(t, 0)
			tc.setUp(t, h)

			r := rawDialTo(t, h.Addr)
			r.write(connectPacket(5, 0x02, []byte("order-reader")))
			if no, how := refused(t, r); no {
				t.Fatalf("the connection itself was refused (%s), so this says "+
					"nothing about the ordering", how)
			}
			r.write(subscribePacket(5, 1, tc.filter, 0x00))

			first := r.answer(3 * time.Second)
			if !first.got {
				t.Fatal("the SUBSCRIBE was neither answered nor refused")
			}
			if first.kind != 9 {
				t.Fatalf("the first packet after the SUBSCRIBE was type %d, want 9 "+
					"(SUBACK). A client reading one packet for its acknowledgement "+
					"has been handed a message instead (body % 02x)",
					first.kind, first.body)
			}

			// **The guard that makes the assertion above worth making.** A
			// broker that answered the SUBACK first and then sent nothing
			// would pass the check above and have lost the delivery
			// entirely, which is the failure worth more than the ordering.
			second := r.answer(3 * time.Second)
			if !second.got || second.kind != 3 {
				t.Fatalf("%s did not follow the SUBACK (packet type %d, arrived %v). "+
					"Ordering the acknowledgement first must not cost the delivery",
					tc.what, second.kind, second.got)
			}
		})
	}
}

// MQTT 5 §3.3.4 [MQTT-3.3.4-3], and the test above one delivery further on.
//
// **A retained snapshot is sent a window at a time, and the identifier has
// to survive the gap.** The subscriber here declares Receive Maximum 1, so
// only the first value goes out in answer to the SUBSCRIBE and every one
// after it is pulled by an acknowledgement - which arrives at OnQosComplete
// knowing the channel and the packet and nothing about the SUBSCRIBE that
// started the drain. Told the identifier once for the whole drain, it had
// none to pass on: the measurement was [9], then bare, bare, bare.
//
// **Wrong in a way that reads as working**, which is why the window is the
// whole point of the test. At the default window all four values go out in
// the answer to the SUBSCRIBE and all four carry the identifier, so the
// test above passes and a client on an ordinary connection sees nothing -
// until a subscriber declares a small window, and then its first retained
// value routes to one handler and the rest to the fallback.
func TestEveryRetainedDeliveryCarriesItsSubscriptionIdentifier(t *testing.T) {
	h := startRetaining(t, 0)

	pub := connect(t, h, "retain-writer", true, false)
	for _, s := range []string{"a", "b", "c", "d"} {
		pub.PubRetained(t, "loose/"+s, "v-"+s)
	}
	settle(t, pub)

	// Receive Maximum 1 and manual acknowledgement: one value on the wire at
	// a time, so every value after the first is a continuation.
	c := dialAt(t, h.Addr, h.Network, "retain-reader", true, true, 1, 600, 0, nil, nil)
	c.SubWithID(t, "loose/#", 1, 9)

	for i := 1; i <= 4; i++ {
		got, ok := c.Await(t, 3*time.Second)
		if !ok {
			t.Fatalf("only %d of the 4 retained values arrived", i-1)
		}
		if !got.Retain {
			t.Errorf("value %d (%s) arrived without the RETAIN flag", i, got.Topic)
		}
		if len(got.SubIDs) == 0 || got.SubIDs[0] != 9 {
			t.Errorf("retained value %d (%s) carried Subscription Identifier %v, want "+
				"[9]: MQTT requires it on every delivery made for a subscription that "+
				"asked for one, and this one is a window behind the SUBSCRIBE rather "+
				"than a different kind of delivery", i, got.Topic, got.SubIDs)
		}
		if got.Ack != nil {
			got.Ack()
		}
	}
}

// The class behind the test above, rather than the one case that was found.
//
// One client, two subscriptions, two identifiers. The retained store's
// pending list is per client and appended to rather than replaced, so both
// subscriptions' values queue into it together - and a drain told a single
// identifier for the whole list would hand the second subscription's number
// to whatever was left of the first. The window of 1 is what makes the two
// overlap: the first snapshot is still queued when the second SUBSCRIBE
// arrives.
func TestTwoSubscriptionsRetainedValuesKeepTheirOwnIdentifiers(t *testing.T) {
	h := startRetaining(t, 0)

	pub := connect(t, h, "retain-writer", true, false)
	for i := 0; i < 3; i++ {
		pub.PubRetained(t, fmt.Sprintf("loose/x/%d", i), "x")
		pub.PubRetained(t, fmt.Sprintf("loose/y/%d", i), "y")
	}
	settle(t, pub)

	c := dialAt(t, h.Addr, h.Network, "retain-reader", true, true, 1, 600, 0, nil, nil)
	c.SubWithID(t, "loose/x/#", 1, 5)
	c.SubWithID(t, "loose/y/#", 1, 6)

	seen := 0
	for i := 1; i <= 6; i++ {
		got, ok := c.Await(t, 3*time.Second)
		if !ok {
			break
		}
		seen++
		want := 5
		if strings.HasPrefix(got.Topic, "loose/y/") {
			want = 6
		}
		if len(got.SubIDs) == 0 || got.SubIDs[0] != want {
			t.Errorf("%s carried Subscription Identifier %v, want [%d] - it answers the "+
				"subscription whose filter reaches it and not whichever one drained "+
				"last", got.Topic, got.SubIDs, want)
		}
		if got.Ack != nil {
			got.Ack()
		}
	}
	if seen != 6 {
		t.Errorf("%d of 6 retained values arrived, so this checked identifiers on a "+
			"delivery that mostly did not happen", seen)
	}
}

// **A client that sent no identifier is sent none, even while another of
// its subscriptions has one.**
//
// The client here holds two subscriptions into the same append channel: one
// carrying 55 and one carrying nothing. A record matching only the second
// must arrive bare. Collecting identifiers per delivery is what makes that
// possible to get wrong - a collector that returned every identifier the
// client holds, rather than every one whose filter matches this topic,
// passes the tests above and fails here.
//
// **What this cannot check** is saguin storing a zero and stamping it: the
// substrate's encoder writes the property only for a value above zero, so a
// zero never reaches the wire whatever saguin does. The guard in
// identifiersForLocked is there so the answer does not depend on that, and
// it is stated here rather than left as a claim no test makes.
func TestNoSubscriptionIdentifierIsSentWhenTheClientAskedForNone(t *testing.T) {
	h := start(t)
	c := connect(t, h, "plain-reader", true, false)
	c.SubWithID(t, "events/identified/+", 1, 55)
	c.Sub(t, "events/bare/+", 1)

	pub := connect(t, h, "plain-writer", true, false)
	pub.Pub(t, "events/bare/one", "x")

	got, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("nothing was delivered")
	}
	if got.Topic != "events/bare/one" {
		t.Fatalf("delivered %q, want events/bare/one", got.Topic)
	}
	if len(got.SubIDs) != 0 {
		t.Errorf("a subscription carrying no identifier was answered with %v - "+
			"that is the other subscription's, on a record its filter does not match",
			got.SubIDs)
	}
}

// **One copy of a record carries every one of the client's matching
// Subscription Identifiers.**
//
// MQTT 5 section 3.3.4: where a message matches several of one client's
// subscriptions, a server sending a single copy MUST include all of their
// identifiers. saguin does send a single copy - asserted below, because the
// rule only applies to a server that behaves this way - so the delivery has
// to carry both.
//
// **Raw bytes, because no Go client here can see the answer.** paho.golang
// models the property as one `*int` rather than the list MQTT allows, so
// through it a delivery carrying 7 and 21 is indistinguishable from one
// carrying either alone. That is a known shape: a layer between
// the test and the broker turning an answer into a non-answer, and it would
// have made this test pass against a fix that stamped only the first match.
func TestOneCopyCarriesEveryMatchingSubscriptionIdentifier(t *testing.T) {
	h := start(t)

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	// Named rather than `connect`, which is this file's own dial helper and
	// is called below: shadowing it here made the call a compile error.
	connectPacket := []byte{
		0x10, 0x13,
		0x00, 0x04, 'M', 'Q', 'T', 'T',
		0x05, 0x02, 0x00, 0x3c, 0x00,
		0x00, 0x06, 't', 'w', 'i', 'c', 'e', 'r',
	}
	if _, err := conn.Write(connectPacket); err != nil {
		t.Fatalf("write connect: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	if _, _, err := readRawPacket(conn); err != nil {
		t.Fatalf("no CONNACK: %v", err)
	}

	// Two filters, both reaching the `events` append channel, both matching
	// the one topic published below.
	for i, s := range []struct {
		filter string
		id     byte
	}{{"events/+", 7}, {"events/one", 21}} {
		var body []byte
		body = append(body, 0x00, byte(i+1)) // packet identifier
		// Properties: one Subscription Identifier, a variable byte integer
		// small enough here to be a single byte.
		body = append(body, 0x02, 0x0B, s.id)
		body = append(body, byte(len(s.filter)>>8), byte(len(s.filter)))
		body = append(body, s.filter...)
		body = append(body, 0x01) // options: QoS 1
		if _, err := conn.Write(append([]byte{0x82, byte(len(body))}, body...)); err != nil {
			t.Fatalf("write subscribe %s: %v", s.filter, err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
		typ, sub, err := readRawPacket(conn)
		if err != nil {
			t.Fatalf("no SUBACK for %s: %v", s.filter, err)
		}
		if typ>>4 != 9 {
			t.Fatalf("answered packet type %d for a SUBSCRIBE, want a SUBACK", typ>>4)
		}
		// The reason code is the last byte: granted QoS, or a refusal.
		if code := sub[len(sub)-1]; code > 2 {
			t.Fatalf("subscribe %s refused 0x%02X", s.filter, code)
		}
	}

	pub := connect(t, h, "twice-writer", true, false)
	pub.Pub(t, "events/one", "x")

	_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	typ, body, err := readRawPacket(conn)
	if err != nil {
		t.Fatalf("no delivery: %v", err)
	}
	if typ>>4 != 3 {
		t.Fatalf("packet type %d, want a PUBLISH", typ>>4)
	}
	ids := subscriptionIdentifiersIn(t, body, (typ>>1)&0x03 > 0)
	sort.Ints(ids)
	if len(ids) != 2 || ids[0] != 7 || ids[1] != 21 {
		t.Fatalf("the delivery carried identifiers %v, want [7 21] - a record "+
			"matching two of this client's subscriptions must carry both", ids)
	}

	// The rule above is about a server that sends ONE copy. Assert that is
	// what this is, or the requirement being tested is the wrong one.
	_ = conn.SetReadDeadline(time.Now().Add(700 * time.Millisecond))
	if _, extra, err := readRawPacket(conn); err == nil {
		t.Errorf("a second copy arrived (%d bytes), so saguin sends one per "+
			"subscription and this test asserts the wrong half of 3.3.4", len(extra))
	}
}

// **One client publishing as fast as it can cannot take the broker with
// it**, which is a claim saguin could not make: every bound it had was a
// size, and a broadcast topic has no size bound at all. A device with a
// firmware bug looping on one was answered as fast as the broker could go,
// for as long as it liked (invariant 13, whose reasoning is exactly this
// deployment).
//
// The bound is per client, because the failure is one device harming the
// others. The box is bounded by max_connections times this.
//
// **`0x97 Quota exceeded` and no disconnect.** It is the word saguin
// already uses for a channel at its bound and means the same thing here:
// come back later. Hanging up would turn a burst into a reconnect storm,
// and a client that ignores the code is already bounded - the refusal
// happens before anything is stored, so what invariant 13 protects holds.
//
// **The reason code is read off the PUBACK rather than from an error.** A
// refused publish is an answered publish, not a failed one, and a test that
// only checked `err` would call every one of these a success - which is the
// shape this repository keeps finding.
func TestOneClientCannotPublishFasterThanItsRate(t *testing.T) {
	brokertest.PublishCeiling = 5
	t.Cleanup(func() { brokertest.PublishCeiling = 0 })
	h := start(t)

	pub := connect(t, h, "fast-publisher", true, false)

	// The bucket holds one second's worth, so the first few are the burst a
	// quiet client is allowed and the rest are over it.
	refused, accepted := 0, 0
	for i := 0; i < 40; i++ {
		// **The error is not the answer, the reason code is.** paho returns
		// both for a refused publish - the PUBACK it received *and* an
		// error made from it - so a test that stopped at `err != nil` would
		// call a refusal a broken client. The response is what the broker
		// said.
		resp, _ := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/flood", QoS: 1, Payload: []byte("x"),
		})
		if resp == nil {
			t.Fatalf("publish %d came back with no PUBACK at all", i)
		}
		switch resp.ReasonCode {
		case 0x00:
			accepted++
		case 0x97:
			refused++
		default:
			t.Fatalf("publish %d answered 0x%02X, want 0x00 or 0x97", i, resp.ReasonCode)
		}
	}
	if refused == 0 {
		t.Fatalf("40 publishes at a ceiling of %d/s were all accepted: nothing bounds "+
			"the rate, and one looping device is answered as fast as the broker can go",
			brokertest.PublishCeiling)
	}
	if accepted == 0 {
		t.Errorf("every one of the 40 was refused, including the first: a client within " +
			"its rate has to get through")
	}
	t.Logf("  %d accepted, %d refused 0x97 at a ceiling of %d/s",
		accepted, refused, brokertest.PublishCeiling)
	// **And the operator is told which 0x97 it was** (RFC 0005
	// saguin_publish_refused_total): the rate is split out of `quota
	// exceeded` by name, which no test read.
	const series = `saguin_publish_refused_total{reason="publish rate exceeded"}`
	if got := metricValue(t, operationsAt(t, h), series); got != float64(refused) {
		t.Errorf("%s is %v after %d publishes refused for the rate", series, got, refused)
	}
}

// RFC 0002 "publish_rate and publish_bytes", docs/invariants.md 13
//
// **A budget is what one client may send in a second, so reconnecting must
// not hand it another one.** The budget used to be dropped at OnDisconnect,
// which read as tidy and was a way round the limit: a client spent its
// second's worth, was refused, reconnected under the same id and spent a
// second's worth again - bounded only by how fast it could reconnect, which
// nothing bounds.
//
// It does not take a client trying to get round anything. A library that
// treats the 0x97 as a fatal error and reconnects does exactly this by
// itself, and turns a rate limit into a reconnect storm - which costs the
// broker more than the publishes it was refusing.
//
// The whole run is inside one bucket period, or the refill would be the
// explanation rather than the defect.
func TestAClientCannotRefillItsPublishBudgetByReconnecting(t *testing.T) {
	brokertest.PublishCeiling = 5
	t.Cleanup(func() { brokertest.PublishCeiling = 0 })
	h := start(t)

	spend := func(c *client, n int) (accepted, refused int) {
		t.Helper()
		for i := 0; i < n; i++ {
			resp, _ := c.C.Publish(context.Background(), &paho.Publish{
				Topic: "loose/refill", QoS: 1, Payload: []byte("x"),
			})
			if resp == nil {
				t.Fatalf("publish %d came back with no PUBACK at all", i)
			}
			switch resp.ReasonCode {
			case 0x00:
				accepted++
			case 0x97:
				refused++
			default:
				t.Fatalf("publish %d answered 0x%02X, want 0x00 or 0x97", i, resp.ReasonCode)
			}
		}
		return accepted, refused
	}

	started := time.Now()
	first := connect(t, h, "refiller", true, false)
	acceptedFirst, refusedFirst := spend(first, 12)
	if refusedFirst == 0 {
		t.Fatalf("the first connection had all 12 accepted at a ceiling of %d/s, so it "+
			"never reached the limit and nothing below is about refilling it",
			brokertest.PublishCeiling)
	}
	// Disconnected without `gone`, which publishes a barrier first: the
	// barrier is a publish like any other and this client has just spent its
	// budget, so the helper meant to settle the connection is refused 0x97
	// and fails the test. An instrument that cannot run against the thing it
	// is measuring.
	before := h.Disconnects.Snapshot("refiller")
	_ = first.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
	sessionGoneAfter(t, h, "refiller", before)

	second := connect(t, h, "refiller", true, false)
	acceptedSecond, _ := spend(second, 12)

	elapsed := time.Since(started)
	if elapsed > 900*time.Millisecond {
		t.Skipf("the run took %s, which is long enough for the bucket to have refilled "+
			"honestly; this machine is too slow for this measurement", elapsed)
	}

	// One bucket across both connections, plus whatever genuinely refilled
	// while the run was going on, plus one for the rounding.
	//
	// **Derived from the elapsed time rather than picked**, because the
	// first version allowed `publishCeiling*2` - which is precisely the
	// doubling this test exists to catch. Against the defect it read "5
	// accepted then 5 accepted" and passed, a test green over its own bug.
	allowed := brokertest.PublishCeiling + int(elapsed.Seconds()*float64(brokertest.PublishCeiling)) + 1
	if total := acceptedFirst + acceptedSecond; total > allowed {
		t.Errorf("a client held to %d/s got %d publishes through in %s across a "+
			"reconnect (%d then %d), where %d is all that had been earned: the budget "+
			"is per client, and dropping it when the connection went let the client "+
			"fetch a new one",
			brokertest.PublishCeiling, total, elapsed.Round(time.Millisecond),
			acceptedFirst, acceptedSecond, allowed)
	}
	t.Logf("  %d accepted then %d accepted across a reconnect in %s, at a ceiling of %d/s",
		acceptedFirst, acceptedSecond, elapsed.Round(time.Millisecond), brokertest.PublishCeiling)
}

// RFC 0005, and the operator rather than the protocol.
//
// **A refusal says which numbers the client was held to.** An acl_file gives
// a device its own, and the line printed the broker-wide floor whatever they
// were - so a device the file limits to 2 a second and one it limits to 200
// both logged the floor, and an operator reading the line to explain a
// throttle was sent to the wrong knob. The metric was right throughout,
// which is why this was only ever cosmetic and is still worth fixing: the
// log line is what somebody reads *after* the metric has told them there is
// something to look at.
//
// **Read at debug, which is where the line is** and is not an accident: a
// client being held to its rate writes one of these per refused publish, and
// a limiter that floods the log under load has moved the problem rather than
// solved it. A reader at Info sees none of them and passes by reading
// nothing, which is what the first version of this did.
func TestARefusalNamesTheLimitsTheClientWasHeldTo(t *testing.T) {
	var mu sync.Mutex
	var lines []string
	h := startLoggingDebug(t, func(line string) {
		if strings.Contains(line, "refusing publish: over the client's publish rate") {
			mu.Lock()
			lines = append(lines, line)
			mu.Unlock()
		}
	})

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  publisher:
    - topic: "loose/#"
      allow: [write, read]
users:
  "device-*":
    roles: [publisher]
    limits:
      publish_rate: 2
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	// The user name is what the acl_file's patterns are about, so the client
	// carries one; the id differs from it deliberately, because the budget
	// is per id and the numbers come from the name.
	c := dialWithUser(t, h, "conn-a", "device-3")
	for i := 0; i < 12; i++ {
		_, _ = c.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/throttled", QoS: 1, Payload: []byte("x"),
		})
	}

	mu.Lock()
	defer mu.Unlock()
	if len(lines) == 0 {
		t.Fatal("no refusal was logged at all, so this checked the text of a line that " +
			"never happened")
	}
	wrong := 0
	for _, l := range lines {
		if !strings.Contains(l, "rate=2") {
			wrong++
			t.Errorf("a refusal for a device the acl_file limits to 2/s logged %q: it "+
				"names the numbers this client was held to, not the broker-wide floor", l)
		}
	}
	// **The count is the evidence, the claim is not.** Written
	// unconditionally, this line reported "all naming the client's own rate"
	// directly beneath ten errors saying rate=0 - the test's own report
	// contradicting the test. How many refusals were seen still matters when
	// it fails, because a run that logged none checked nothing; what the
	// line must not do is say they were right.
	if wrong == 0 {
		t.Logf("  %d refusals logged, all naming the client's own rate of 2/s", len(lines))
	} else {
		t.Logf("  %d refusals logged, %d of them naming a rate the client was not held to",
			len(lines), wrong)
	}
}

// **One client's flood does not spend another client's budget.** A shared
// counter would be a broker-wide bound wearing a per-client name, and the
// failure it is for - one device harming the others - is exactly what it
// would then cause.
func TestOneClientsFloodDoesNotSpendAnothers(t *testing.T) {
	brokertest.PublishCeiling = 5
	t.Cleanup(func() { brokertest.PublishCeiling = 0 })
	h := start(t)

	flooder := connect(t, h, "flooder", true, false)
	floodRefused := 0
	for i := 0; i < 40; i++ {
		resp, _ := flooder.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/flood", QoS: 1, Payload: []byte("x"),
		})
		if resp != nil && resp.ReasonCode == 0x97 {
			floodRefused++
		}
	}
	if floodRefused == 0 {
		t.Fatal("the flooder was never refused, so this proves nothing about the other client")
	}

	quiet := connect(t, h, "quiet", true, false)
	for i := 0; i < 3; i++ {
		resp, _ := quiet.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/quiet", QoS: 1, Payload: []byte("x"),
		})
		if resp == nil {
			t.Fatalf("the quiet client's publish %d came back with no PUBACK", i)
		}
		if resp.ReasonCode == 0x97 {
			t.Fatalf("a client publishing three times was refused while another was " +
				"flooding: the budget is shared, so one device can starve the rest")
		}
	}
}

// **Unwritten means no bound**, which is the default and the control for
// the two above: without it, a ceiling that silently defaulted to something
// small would leave them passing while throttling every deployment that
// never asked for one.
//
// **The resolved value is asserted before any publishing**, because a loop
// is a weak control here and this one was weaker than it looked: it sent
// sixty and a silent default of 100/s let every one through, so the
// mutation that introduced exactly the fault this test names went green.
// A count can always be smaller than somebody's default; zero cannot be
// anything but zero.
func TestNoPublishRateMeansNoBound(t *testing.T) {
	resolved := (config.Limits{}).Resolve()
	if resolved.PublishRate != 0 || resolved.PublishBytes != 0 {
		t.Fatalf("a configuration writing neither publish limit resolves to %d/s and "+
			"%d bytes/s: every deployment that never asked for a bound has one",
			resolved.PublishRate, resolved.PublishBytes)
	}

	h := start(t)
	pub := connect(t, h, "unbounded", true, false)
	// Well past any figure somebody might quietly default to.
	for i := 0; i < 500; i++ {
		resp, _ := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/plenty", QoS: 1, Payload: []byte("x"),
		})
		if resp == nil {
			t.Fatalf("publish %d came back with no PUBACK at all", i)
		}
		if resp.ReasonCode == 0x97 {
			t.Fatalf("publish %d of 500 was refused 0x97 on a broker with no "+
				"publish_rate: a limit nobody configured is throttling them", i)
		}
	}
}

// **Bytes bound what messages cannot.** A client sending ten one-megabyte
// publishes makes ten operations and ten megabytes; one sending a thousand
// one-byte publishes makes a kilobyte and a thousand store writes. Either
// alone leaves the other hole open, so both are counted and whichever is
// reached first refuses.
//
// **The size is the packet as the client sent it** - topic, packet
// identifier, properties and payload - which is what the wire length
// already says. saguin adds its own `saguin-*` properties on delivery and
// never to what arrives, so nothing has to be subtracted.
func TestAClientIsBoundedByBytesAsWellAsMessages(t *testing.T) {
	// Generous in messages, tight in bytes: whatever refuses here refused
	// on the byte budget, because the message budget is nowhere near spent.
	brokertest.PublishCeiling = 1000
	brokertest.PublishByteCeiling = 8 << 10
	t.Cleanup(func() { brokertest.PublishCeiling, brokertest.PublishByteCeiling = 0, 0 })
	h := start(t)

	pub := connect(t, h, "fat-publisher", true, false)
	payload := strings.Repeat("x", 2048)

	accepted, refused := 0, 0
	for i := 0; i < 20; i++ {
		resp, _ := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/fat", QoS: 1, Payload: []byte(payload),
		})
		if resp == nil {
			t.Fatalf("publish %d came back with no PUBACK", i)
		}
		switch resp.ReasonCode {
		case 0x00:
			accepted++
		case 0x97:
			refused++
		default:
			t.Fatalf("publish %d answered 0x%02X", i, resp.ReasonCode)
		}
	}
	if refused == 0 {
		t.Fatalf("20 publishes of 2KiB against an 8KiB/s byte ceiling were all "+
			"accepted (%d messages of a %d/s allowance used): nothing bounds the "+
			"bytes, so ten large messages pass where a thousand small ones would "+
			"not", accepted, brokertest.PublishCeiling)
	}
	if accepted == 0 {
		t.Error("every one was refused, including the first: a client within its " +
			"byte budget has to get through")
	}
	t.Logf("  %d accepted, %d refused against %d bytes/s", accepted, refused,
		brokertest.PublishByteCeiling)
}

// **A message larger than the whole per-second budget is admitted, slowly,
// rather than refused for ever.** A 1MiB publish against a 64KiB/s ceiling
// can never fit a full bucket, and refusing it every time would make the
// limit a silent ban on large messages - a different feature from a rate,
// and one nobody asked for. It spends the budget into deficit instead and
// the client waits longer for the next one.
func TestAMessageLargerThanTheBudgetStillGetsThrough(t *testing.T) {
	brokertest.PublishByteCeiling = 1 << 10 // 1KiB a second
	t.Cleanup(func() { brokertest.PublishByteCeiling = 0 })
	h := start(t)

	pub := connect(t, h, "oversized", true, false)
	resp, _ := pub.C.Publish(context.Background(), &paho.Publish{
		Topic: "loose/big", QoS: 1, Payload: []byte(strings.Repeat("x", 4096)),
	})
	if resp == nil {
		t.Fatal("no PUBACK at all")
	}
	if resp.ReasonCode != 0x00 {
		t.Fatalf("a 4KiB publish against a 1KiB/s ceiling answered 0x%02X: a message "+
			"larger than the budget can never fit one, so refusing it makes the "+
			"limit a ban on large messages rather than a rate", resp.ReasonCode)
	}
}

// **The acl_file's limits reach the broker, and the most specific pattern
// supplies them.** authz has this as a unit test; this is the same rule
// arriving at a real publish, which is where it has to hold.
//
// The two clients here are the case an operator actually has: a fleet on
// one pattern and one device that needs different numbers. `device-7`'s
// are *looser* than the fleet's, which a bound that could only tighten
// could not express - and that is most of why per-client limits exist.
func TestTheACLFilesLimitsReachThePublishPath(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  publisher:
    - topic: "loose/#"
      allow: [write, read]
users:
  "device-*":
    roles: [publisher]
    limits:
      publish_rate: 3
  "device-7":
    roles: [publisher]
    limits:
      publish_rate: 200
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	// **The user name is what the acl_file's patterns are about**, for
	// roles and for limits alike - so these clients carry one. A client id
	// alone reaches no pattern and every publish would be refused 0x87 by
	// the substrate before saguin's rate check ran at all, which is how the
	// first version of this test measured nothing.
	//
	// The id differs from the name on purpose: it is what proves the budget
	// is per connection rather than per name.
	refusals := func(user, id string, n int) int {
		t.Helper()
		c := dialWithUser(t, h, id, user)
		refused := 0
		for i := 0; i < n; i++ {
			resp, _ := c.C.Publish(context.Background(), &paho.Publish{
				Topic: "loose/x", QoS: 1, Payload: []byte("x"),
			})
			if resp != nil && resp.ReasonCode == 0x97 {
				refused++
			}
		}
		return refused
	}

	if got := refusals("device-1", "conn-a", 20); got == 0 {
		t.Errorf("device-1 sent 20 against a ceiling of 3/s and was refused none: " +
			"the acl_file's limits are not reaching the publish path")
	}
	if got := refusals("device-7", "conn-b", 20); got != 0 {
		t.Errorf("device-7 sent 20 against its own ceiling of 200/s and was refused "+
			"%d: the fleet pattern is supplying its limits instead of the exact id, "+
			"so an exception cannot be looser than the fleet it sits in", got)
	}
}

// **The entry that applies supplies the roles too, and this is that rule
// arriving at a real publish.** authz has it as a unit test; invariant 10
// says the broker is the only enforcement point, and what changed here is
// what a client may do, so it has to hold over a socket rather than only in
// a function.
//
// The shape is the one an operator writes: a fleet entry carrying two roles
// and one device that should have fewer. Under the union this replaced,
// `device-7` held `admin` from the fleet line and there was no way to write
// an exception that took anything away.
//
// **The third assertion is what stops this passing for the wrong reason.**
// A client refused everything - because its user name reached no pattern,
// or because the file failed to load - satisfies the first two on its own,
// and that is exactly how an earlier ACL test here measured nothing. So
// `device-7` is also shown doing the thing its own entry does grant.
func TestTheEntryThatAppliesSuppliesTheRolesAtTheBroker(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  telemetry:
    - topic: "loose/#"
      allow: [write, read]
  admin:
    - topic: "admin/#"
      allow: [write, read]
users:
  "device-*": [telemetry, admin]
  "device-7": [telemetry]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	// The user name is what the patterns are about, so these clients carry
	// one; the id differs from it deliberately, because nothing about
	// authorization is decided by the id.
	publish := func(user, id, topic string) byte {
		t.Helper()
		c := dialWithUser(t, h, id, user)
		resp, _ := c.C.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Payload: []byte("x"),
		})
		if resp == nil {
			t.Fatalf("no PUBACK for %s publishing to %q", user, topic)
		}
		return resp.ReasonCode
	}

	if got := publish("device-9", "conn-a", "admin/x"); got != 0x00 {
		t.Errorf("device-9 was answered 0x%02X publishing to admin/x, which the only "+
			"entry matching it grants through the admin role", got)
	}
	if got := publish("device-7", "conn-b", "admin/x"); got != 0x87 {
		t.Errorf("device-7 was answered 0x%02X publishing to admin/x, want 0x87: only "+
			"the fleet entry grants admin, and device-7's own entry applies instead "+
			"of it. A client still holding a role from an entry it shadows means the "+
			"broker is unioning the entries and an exception cannot take anything "+
			"away", got)
	}
	if got := publish("device-7", "conn-c", "loose/x"); got != 0x00 {
		t.Errorf("device-7 was answered 0x%02X publishing to loose/x, which its own "+
			"entry grants: it is being refused everything rather than refused the "+
			"one role it does not hold, so the assertion above proves nothing", got)
	}
}

// **A consumer whose filter reaches two channels is told which one each
// record came from, and one whose filter reaches one is not.**
//
// Two channels, one subscription, and the two channels' offsets interleave:
// a consumer tracking "I have seen up to offset 3" is silently wrong about
// one of them. It cannot work the channel out from the topic either without
// knowing where the boundaries are, which is precisely what placing a
// channel with a filter exists to spare it.
//
// **This is not hypothetical.** The link-churn soak had this defect: its
// gap check keyed by offset alone, two channels' offsets interleaved, and a
// gap in one was filled by a record from the other - the check passed while
// a consumer missed records. It was fixed by parsing the topic prefix to
// recover the channel, which is the reverse-engineering a real consumer
// would otherwise have to do.
//
// **The second half is what keeps it from costing everybody.** The property
// is 26 bytes for a channel called `events`, which is 17% of a packet
// carrying a 20-byte reading - and that packet on a metered radio is the
// target rather than an edge case. A consumer whose filter reaches one
// channel already knows which, so it pays nothing; a test asserting only
// the presence would pass a build that stamped every delivery.
func TestAChannelIsNamedOnlyWhereAConsumerCannotTell(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "events", Type: channel.Append, Filter: "iot/+/events/+"},
		{Name: "hq", Type: channel.Append, Filter: "iot/hq/#"},
	})

	// `iot/hq/events/1` matches both filters and `hq` spells its second
	// level out, so invariant 12 gives it to `hq`; `iot/site/events/1` goes
	// to `events`. One subscription reaches both.
	p := connect(t, h, "publisher", true, false)
	for i := 1; i <= 2; i++ {
		p.Pub(t, fmt.Sprintf("iot/hq/events/%d", i), fmt.Sprintf("hq-%d", i))
		p.Pub(t, fmt.Sprintf("iot/site/events/%d", i), fmt.Sprintf("site-%d", i))
	}

	t.Run("a filter reaching both is told which", func(t *testing.T) {
		c := connect(t, h, "wide", true, false)
		c.Sub(t, "iot/#", 1)
		seen := map[string]string{}
		for range 4 {
			r, ok := c.Await(t, 3*time.Second)
			if !ok {
				t.Fatalf("expected four records, got %d: %v", len(seen), seen)
			}
			seen[r.Topic] = r.User["saguin-channel"]
		}
		for topic, want := range map[string]string{
			"iot/hq/events/1":   "hq",
			"iot/hq/events/2":   "hq",
			"iot/site/events/1": "events",
			"iot/site/events/2": "events",
		} {
			if seen[topic] != want {
				t.Errorf("%s arrived carrying saguin-channel %q, want %q: the two "+
					"channels' offsets interleave and this is the only thing saying "+
					"which sequence a record belongs to", topic, seen[topic], want)
			}
		}
	})

	t.Run("a filter reaching one is not", func(t *testing.T) {
		c := connect(t, h, "narrow", true, false)
		c.Sub(t, "iot/site/events/+", 1)
		for range 2 {
			r, ok := c.Await(t, 3*time.Second)
			if !ok {
				t.Fatal("expected the two records of the one channel this filter reaches")
			}
			if got, carried := r.User["saguin-channel"]; carried {
				t.Errorf("%s carried saguin-channel %q to a consumer whose filter reaches "+
					"one channel: it already knows which, and 26 bytes a record on a "+
					"metered link is what this costs when it answers nothing",
					r.Topic, got)
			}
		}
	})
}

// **A cohort: many devices, one credential, and a topic each.** This is the
// deployment `%u` alone cannot serve and the reason `%c` exists.
//
// A thousand sensors on five passwords is an operator's trade - five things
// to manage rather than a thousand - and the broker then has one proved
// name for two hundred devices. `%u` scopes them all to the same topic.
// `%c` is the id each device chose, so it gives each one its own; and
// `client_ids:` keeps the northern credential from reaching a southern id
// at all.
//
// **Written together, they say different halves of one sentence.** The
// proved name fixes which cohort, and the chosen id picks the device inside
// it. `%c` alone would let any credential reach any device's topic; `%u`
// alone cannot tell two devices in one cohort apart.
//
// **What it does not do is in the last case.** Inside a cohort the devices
// share a secret and are one principal, so one can take another's id - it
// has to displace the real device to do it, which is MQTT taking the
// session over, and that is the whole of the protection. Asserted here
// because a reader who has got this far will want to know, and because a
// test claiming more than the mechanism gives is worse than none.
func TestAClientIDScopesACohortAtTheBroker(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  sensor:
    - topic: iot/%u/health/%c
      allow: [write, read]
users:
  "cohort-*":
    roles: [sensor]
    client_ids: "north-*"
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	publish := func(user, id, topic string) byte {
		t.Helper()
		c := dialWithUser(t, h, id, user)
		ack, err := c.C.Publish(context.Background(), &paho.Publish{
			Topic: topic, QoS: 1, Payload: []byte("x"),
		})
		if ack == nil {
			t.Fatalf("publish %s as %s: no acknowledgement: %v", topic, user, err)
		}
		return ack.ReasonCode
	}

	for _, tc := range []struct {
		name, user, id, topic string
		want                  byte
	}{
		{"a device writes its own topic", "cohort-north", "north-17",
			"iot/cohort-north/health/north-17", 0x00},
		{"and another in the same cohort writes its own", "cohort-north", "north-18",
			"iot/cohort-north/health/north-18", 0x00},
		{"neither reaches the other's, though they share a credential",
			"cohort-north", "north-17", "iot/cohort-north/health/north-18", 0x87},
		{"and the credential fixes the cohort, so a southern name cannot reach north",
			"cohort-south", "north-17", "iot/cohort-north/health/north-17", 0x87},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := publish(tc.user, tc.id, tc.topic); got != tc.want {
				t.Errorf("%s as %s publishing %q answered 0x%02X, want 0x%02X",
					tc.id, tc.user, tc.topic, got, tc.want)
			}
		})
	}
}

// **A broker with an acl_file and no limits in it pays nothing per
// publish**, which is most brokers that have one. Without this the rate
// check cannot take its early return - the file exists, so it would look
// up a bucket on every publish for a feature nobody configured.
//
// Asserted by behaviour rather than by reading the branch: a client
// publishing far more than any plausible bucket allows is refused none of
// it.
func TestAnACLWithNoLimitsBoundsNothing(t *testing.T) {
	h := start(t)

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  publisher:
    - topic: "loose/#"
      allow: [write, read]
users:
  "device-*": [publisher]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	if f.HasLimits() {
		t.Fatal("an acl_file naming no limits reports that it has some, so the rate " +
			"check will run on every publish for a feature nobody configured")
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	c := connect(t, h, "device-1", true, false)
	for i := 0; i < 500; i++ {
		resp, _ := c.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/x", QoS: 1, Payload: []byte("x"),
		})
		if resp != nil && resp.ReasonCode == 0x97 {
			t.Fatalf("publish %d of 500 was refused on a broker whose acl_file names "+
				"no limits and whose config sets none", i)
		}
	}
}

// RFC 0002 "What each channel type admits", "Publishing"
//
// **The substrate compares `$share` case-insensitively and every ordinary
// topic level exactly**, so it builds a working shared subscription out of
// `$SHARE/…` and hands it records its filter does not match. saguin's rules
// read the filter as MQTT spells it, so every one of them was walked past:
// each row below was granted before this, and the client then received
// nothing for ever having been told it succeeded.
//
// Driven rather than reasoned about, because the whole defect was invisible
// to reading - the lower-case twin of every row is refused today and looks
// like proof the rule holds.
func TestAShareSpelledWithTheWrongCaseIsRefused(t *testing.T) {
	h := start(t)

	for _, tc := range []struct{ name, filter string }{
		{"a queue's topics", "$SHARE/saguin/jobs/#"},
		{"another group over the same", "$SHARE/workers/jobs/#"},
		{"mixed case", "$Share/workers/jobs/#"},
		{"an append channel", "$SHARE/grp/events/#"},
		{"a latest channel", "$SHARE/grp/state/#"},
		{"a filter reaching no channel", "$SHARE/grp/nothing-here/#"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := connect(t, h, "case-"+tc.filter, true, false)
			sa, err := c.C.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{{Topic: tc.filter, QoS: 1}},
			})
			// Paho reports a wholly-refused SUBSCRIBE as an error and gives
			// no packet, so the refusal is proved either way round.
			if err != nil {
				t.Logf("%s refused: %v", tc.filter, err)
				return
			}
			if sa.Reasons[0] <= 2 {
				t.Fatalf("%s was granted at QoS %d: the substrate reads it as a shared "+
					"subscription, saguin's rules do not, and the client receives nothing "+
					"for ever", tc.filter, sa.Reasons[0])
			}
			if sa.Reasons[0] != 0x8F {
				t.Errorf("%s refused 0x%02x, want 0x8F (Topic Filter invalid): the filter is "+
					"what is wrong with it, not the client's permissions", tc.filter, sa.Reasons[0])
			}
		})
	}

	// **The spelling MQTT does define still works**, which is what says the
	// check above refuses a case rather than a prefix.
	c := connect(t, h, "correct", true, false)
	if sa := c.Sub(t, "$saguin/queue/jobs", 1); sa.Reasons[0] > 2 {
		t.Fatalf("the canonical queue form was refused 0x%02x", sa.Reasons[0])
	}
}

// RFC 0002 "Publishing"
//
// A publish to `$share/…` was answered `0x00` and reached nobody, and could
// reach nobody: every subscription beginning `$share/` is read as a shared
// subscription rather than as a topic, and a channel filter beginning `$`
// is refused when the file loads. Accepted, discarded, and reported as
// having succeeded.
//
// **The reader is here to prove the refusal is not the only reason nothing
// arrives.** Without it the test would pass against a broker that accepted
// the publish and simply had no subscribers.
func TestAPublishToTheShareFormIsRefused(t *testing.T) {
	h := start(t)

	seen := make(chan string, 8)
	r := connect(t, h, "reader", true, false)
	r.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		seen <- pr.Packet.Topic
		return true, nil
	})
	r.Sub(t, "#", 1)
	r.Sub(t, "$saguin/queue/jobs", 1)

	p := connect(t, h, "producer", true, false)
	ack, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "$share/grp/jobs/x", QoS: 1, Payload: []byte("work"),
	})
	switch {
	case err == nil && ack != nil && ack.ReasonCode == 0:
		t.Fatal("a publish to $share/grp/jobs/x was answered Success: nothing can " +
			"subscribe to that topic, so the record was accepted, discarded, and reported " +
			"as kept")
	case err == nil && ack != nil && ack.ReasonCode != packets.ErrTopicNameInvalid.Code:
		t.Errorf("refused 0x%02x, want 0x90 (Topic Name invalid)", ack.ReasonCode)
	default:
		t.Logf("refused: %v", err)
	}

	// The ordinary topic one level along is untouched: `$SHARE/…` is a
	// topic MQTT allows, and a publish to one is legitimate.
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "$SHARE/docs/x", QoS: 1, Payload: []byte("ordinary"),
	}); err != nil {
		t.Errorf("a publish to $SHARE/docs/x was refused, and it is an ordinary topic "+
			"name that MQTT allows: %v", err)
	}

	// And the producer still works, so the refusals above are about the
	// topic rather than about a broken session.
	p.Pub(t, "jobs/build", "real-job")
	select {
	case topic := <-seen:
		if topic != "jobs/build" {
			t.Fatalf("the reader received %q", topic)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the reader received nothing at all, so this test proved nothing")
	}
}

// RFC 0001 "Both protocols, and what each one gets", RFC 0002 "Publishing"
//
// **The trap this whole feature turns on.** 3.1.1's PUBACK carries no
// reason code, and the substrate turns saguin's refusal into a
// PUBACK-with-code inside a branch reading `ProtocolVersion == 5`. Below
// that the code matches nothing and the packet carries on down the same
// function: delivered to every broadcast subscriber and answered PUBACK
// success. Refused and published at the same time.
//
// So the assertion that matters is not "the client was disconnected" - it
// is **that a watching subscriber received nothing**. A test asserting only
// the disconnection passes against a broker that delivered the record and
// then hung up, which is the defect wearing the fix's clothes.
//
// Driven by Eclipse Paho's 3.1.1 client rather than by an MQTT 5 client
// with a flag, because what is under test is what a real 3.1.1 library
// makes of the answer.
func TestARefusedPublishFromA311ClientIsNotPublished(t *testing.T) {
	h := startAdmitting311(t)

	// The watcher is MQTT 5 and subscribes to everything a refused publish
	// could reach. It is the whole point of the test.
	seen := make(chan string, 32)
	w := connect(t, h, "watcher", true, false)
	w.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		seen <- pr.Packet.Topic
		return true, nil
	})
	w.Sub(t, "#", 1)
	w.Sub(t, "$saguin/#", 1)

	c, lost := legacy(t, h, "legacy-publisher", true)

	// **A topic a subscriber would actually be served**, which is what makes
	// the "and nothing was published" assertion below mean something. The
	// first version used `$saguin/not/a/verb`: refused, but never delivered
	// to anybody on any protocol version, so the delivery half of the trap
	// could not have failed and the test would have passed over it. An
	// over-length broadcast topic is refused `0x90` for a different reason
	// and is an ordinary topic that `#` reaches.
	topic := "bcast/" + strings.Repeat("x", 1100)
	tok := c.Publish(topic, 1, false, []byte("refused"))

	// **The PUBACK must not arrive.** A 3.1.1 PUBACK can only say success,
	// so one arriving is saguin reporting a record it threw away.
	//
	// **Both halves of this condition are load-bearing**, and the first
	// version had only one: Paho completes a publish token when the
	// connection drops as well as when a PUBACK lands, so `WaitTimeout`
	// alone reported an acknowledgement that never came and failed against
	// a working broker. The token completing with an error is the
	// disconnection; completing without one is the acknowledgement.
	if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
		t.Errorf("the 3.1.1 publisher was answered a PUBACK for a %d-character topic, which "+
			"can only mean success - the record was refused and acknowledged at the same "+
			"time", len(topic))
	} else if err := tok.Error(); err != nil {
		t.Logf("the publish ended with %v, which is the closed connection rather than an "+
			"acknowledgement", err)
	}

	select {
	case <-lost:
	case <-time.After(5 * time.Second):
		t.Error("the connection was not closed: 3.1.1 has no way to carry the refusal, so " +
			"closing it is the only thing left that is true")
	}

	// **And nothing was published**, read against an end marker: the refused
	// publish was read before its connection closed, so anything it handed
	// the watcher is in the watcher's outbound queue ahead of a publish made
	// now. It also says the broker is still serving everybody else, so the
	// assertions above are about one connection rather than about a broker
	// that fell over. A broadcast topic, not `jobs/…`: a queue's records go
	// to its workers through the shared subscription and never to an
	// ordinary subscriber, so the first version of this check waited for a
	// delivery that was never coming and reported the watcher deaf.
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "bcast/after", "after")
	select {
	case got := <-seen:
		if got != "bcast/after" {
			t.Fatalf("a subscriber received %q before the end marker: the publish was "+
				"refused and delivered at the same time, which is the worst of both", got)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the watcher received nothing after the disconnect, so it was never " +
			"listening and this test proved nothing")
	}
}

// RFC 0001 "Both protocols", RFC 0002 "Every reason code, in one place"
//
// **QoS 2 from a 3.1.1 client closes the connection**, where before it
// was let through on the grounds that such a client was never told a
// Maximum QoS and cannot be sent a DISCONNECT explaining one.
//
// Both of those are true and neither was a reason to let the packet
// through: the substrate's downgrade does not check the protocol version,
// so the publish was rewritten to QoS 1, stored, and answered Success. The
// publisher asked for exactly-once and was told it got it - the failure the
// invariants put ahead of a crash, because nobody goes looking for it.
//
// So the assertion that matters is that **nothing was stored**, not that
// the client was disconnected.
func TestAQoS2PublishFromA311ClientIsRefused(t *testing.T) {
	h := startAdmitting311(t)
	denyFeatures(t, h, "    - broker: features\n      deny: [qos2]\n")

	seen := make(chan string, 8)
	w := connect(t, h, "watcher", true, false)
	w.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		seen <- pr.Packet.Topic
		return true, nil
	})
	// The two prefixes this test uses rather than `#`, which measured nothing
	// delivered under the acl_file this harness installs.
	w.Sub(t, "events/#", 1)
	w.Sub(t, "bcast/#", 1)

	// **A channel topic, not a broadcast one**, and the difference is the
	// whole test. On a broadcast topic a refused QoS 2 delivery waits on a
	// PUBREL that never comes, so a watcher sees nothing and this passes
	// against a broker that stored the record - which is exactly what the
	// first version of this test did. saguin's intake stores a channel
	// record at receipt, before any handshake, so a channel topic is the
	// one surface where "refused and published at the same time" can
	// actually be seen.
	c, lost := legacy(t, h, "legacy-qos2", true)
	tok := c.Publish("events/orders/1", 2, false, []byte("x"))
	if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
		t.Error("the 3.1.1 publisher's QoS 2 publish was acknowledged: it asked for " +
			"exactly-once, was told it succeeded, and would have got at-least-once")
	}
	select {
	case <-lost:
	case <-time.After(5 * time.Second):
		t.Error("the connection was not closed")
	}

	// The watcher is proved live, so "received nothing" is about the
	// refusal rather than about a subscription that never worked - and the
	// live publish is the end marker: the refused one was read before its
	// connection closed, so anything it handed the watcher is in the
	// watcher's outbound queue ahead of this.
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "bcast/ordinary", "ok")
	select {
	case got := <-seen:
		if got != "bcast/ordinary" {
			t.Fatalf("a subscriber received %q before the end marker: the QoS 2 publish "+
				"was downgraded and delivered rather than refused", got)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the watcher received nothing at all, so this test proved nothing")
	}

	// **And nothing was stored**, which is the half a live watcher cannot
	// see: a channel keeps what it accepted, so a later reader replaying it
	// is what tells a refusal apart from a refusal that stored the record
	// anyway. A conforming QoS 2 publisher never gets its PUBREC and
	// re-sends on every reconnect, so a stored copy here is one per attempt.
	// A record published after the reader subscribes is the end marker: it
	// is stored after anything the refused publish stored, and served after.
	replayed := make(chan string, 8)
	r := connect(t, h, "replaying-reader", true, false)
	r.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		replayed <- string(pr.Packet.Payload)
		return true, nil
	})
	r.Sub(t, "events/#", 1)
	p.Pub(t, "events/marker", "marker")
	select {
	case got := <-replayed:
		if got != "marker" {
			t.Errorf("a reader replaying the channel was served %q: the QoS 2 publish was "+
				"refused, never acknowledged, and stored anyway", got)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the replaying reader was never served the end marker")
	}
}

// RFC 0003 "Moving a consumer's position: seek", RFC 0002 "Publishing"
//
// **A refused 3.1.1 seek needed no code of its own.** A seek is a publish to
// `$saguin/consumer/<channel>/seek`, so a refused one answers a reason code
// on the publish path, and the branch that closes a 3.1.1 connection for a
// refused publish (RFC 0002 "Every reason code, in one place") closes it.
// That is a
// claim about how two rules compose, which is a thing to drive rather than
// to assert - and driving it is also what would notice if the seek path
// ever stopped answering through `OnPublish`.
//
// A clean-session 3.1.1 client is the sharpest case: it has no durable
// session, so RFC 0003 refuses its seek outright, and 3.1.1 gives it no
// Session Expiry Interval with which to ask for one. Both routes to
// history are closed to such a client and the refusal is where it learns.
func TestARefusedSeekFromA311ClientClosesTheConnection(t *testing.T) {
	h := startAdmitting311(t)

	c, lost := legacy(t, h, "legacy-seeker", true)
	tok := c.Publish("$saguin/consumer/events/seek", 1, false, []byte("0"))
	if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
		t.Error("the seek was acknowledged: a 3.1.1 PUBACK can only say success, and this " +
			"seek was refused")
	}
	select {
	case <-lost:
	case <-time.After(5 * time.Second):
		t.Fatal("the connection was not closed after a refused seek")
	}

	// **At QoS 0 it is a silent, counted drop instead**, which is the rule
	// every refused QoS 0 publish already follows - there is no reply
	// packet to withhold. The client stays connected, which is the whole
	// difference and is what this half asserts.
	c2, lost2 := legacy(t, h, "legacy-seeker-qos0", true)
	tok2 := c2.Publish("$saguin/consumer/events/seek", 0, false, []byte("0"))
	if !tok2.WaitTimeout(3 * time.Second) {
		t.Error("the QoS 0 publish never completed locally")
	}
	select {
	case <-lost2:
		t.Error("a refused seek at QoS 0 closed the connection: there is no reply to " +
			"withhold at QoS 0, so it is dropped and counted like any other refused " +
			"QoS 0 publish")
	case <-time.After(2 * time.Second):
	}
	if !c2.IsConnected() {
		t.Error("the QoS 0 seeker is no longer connected")
	}
}

// RFC 0002 "What each channel type admits: the SUBACK codes", RFC 0001
//
// **A queue cannot be consumed from 3.1.1**, and the reason it must be
// refused rather than left alone is that it worked. Measured before this
// existed: a 3.1.1 worker subscribing to the canonical form was granted and
// received 3 of 3 jobs.
//
// **The refusal has moved once and could be lost silently.** While a queue
// was consumed through `$share/saguin/<name>/#` it was carried by the
// shared-subscription rule, which hangs off the `$share/` prefix; the form
// is `$saguin/queue/<name>` now and has no such prefix, so it needs a
// refusal of its own (queueRefusal). Without one this test is the only
// thing standing between a 3.1.1 worker and a queue.
//
// **Receiving them is worse than receiving nothing.** A worker acknowledges
// by publishing to the Response Topic carrying the Correlation Data its
// delivery arrived with, and a 3.1.1 delivery can carry neither - so such a
// worker takes work it has no way to complete. Every job it holds times
// out, redelivers, and eventually dead-letters, and nothing anywhere says
// why.
//
// So the assertions are that the subscription is refused **and that no job
// reaches it**, the second being the one that would catch a refusal the
// substrate granted anyway.
func TestAQueueCannotBeConsumedFromA311Client(t *testing.T) {
	h := startAdmitting311(t)

	var mu sync.Mutex
	var got []string
	// **The default handler too, not only the subscription's.** A job
	// arrives on its own topic (jobs/build), which Paho v3 does not route to
	// a handler registered for $saguin/queue/jobs: with no default it would
	// acknowledge the job, drop it, and this test would read none.
	record := func(_ mqttv3.Client, m mqttv3.Message) {
		mu.Lock()
		got = append(got, m.Topic())
		mu.Unlock()
	}
	c, _ := legacyWithDefault(t, h, "legacy-worker", true, record)
	code := subscribeCode(t, c, "$saguin/queue/jobs", record)
	if code != 0x80 {
		t.Errorf("a 3.1.1 client was answered 0x%02x for a queue's canonical form: a "+
			"delivery carries its Response Topic and Correlation Data as MQTT 5 "+
			"properties, so such a worker can never acknowledge the work it is given "+
			"and every job it takes dead-letters on attempt exhaustion", code)
	}

	// A real MQTT 5 worker, so the jobs below have somewhere correct to go
	// and "the 3.1.1 client received none" is not because none were sent.
	w := connect(t, h, "worker", true, true)
	took := make(chan string, 8)
	w.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		took <- pr.Packet.Topic
		return true, nil
	})
	w.Sub(t, "$saguin/queue/jobs", 1)

	p := connect(t, h, "producer", true, false)
	for i := 0; i < 3; i++ {
		p.Pub(t, "jobs/build", "job")
	}

	select {
	case <-took:
	case <-time.After(5 * time.Second):
		t.Fatal("the MQTT 5 worker received no job at all, so this test proved nothing " +
			"about which worker the jobs went to")
	}
	// Two jobs still waiting and the MQTT 5 worker holding one: the offer
	// loop going round three times is what would have handed them to the
	// 3.1.1 client, counted rather than slept through.
	ticked(t, h, 3)

	mu.Lock()
	defer mu.Unlock()
	if len(got) != 0 {
		t.Errorf("the 3.1.1 client received %d jobs %v: it has no way to acknowledge one, "+
			"so each of those times out, redelivers and dead-letters", len(got), got)
	}
}

// RFC 0002 "What each channel type admits"
//
// **Any `$share/` filter is refused to a 3.1.1 client, whatever it
// reaches**, because in that protocol the characters mean nothing: the
// filter reaches topics literally under `$share/`, which no client can
// publish to and no channel may claim. Granting it hands such a client
// messages its own specification says it did not ask for.
//
// It is the one shared-subscription refusal left that is not a spelling,
// and it asks nothing about the configuration - which is why it survived
// the change that granted `$share` on every channel type.
//
// **And a wildcard that merely crosses a queue is still served**, which is
// the half that says this refuses a form rather than a subtree. It is the
// same rule MQTT 5 gets, and breaking it would break `mosquitto_sub -t '#'`
// for every 3.1.1 device in the fleet.
func TestA311ClientIsRefusedEveryShareFormButKeepsOrdinaryOnes(t *testing.T) {
	h := startAdmitting311(t)

	c, _ := legacy(t, h, "legacy-subscriber", true)
	for _, filter := range []string{
		"$share/grp/events/#",  // an append channel
		"$share/grp/state/#",   // a latest channel
		"$share/grp/nothing/#", // no channel at all
		"$share/grp/#",         // everything, including a queue's topics
	} {
		if code := subscribeCode(t, c, filter, nil); code != 0x80 {
			t.Errorf("%s was answered 0x%02x to a 3.1.1 client, which has no shared "+
				"subscriptions: the filter reaches topics under $share/ that nothing "+
				"can publish to", filter, code)
		}
	}

	// **The queue's own form is refused too, and by a different rule.** It
	// carries no `$share/` prefix, so nothing above reaches it - see
	// TestAQueueCannotBeConsumedFromA311Client for the reason and the cost.
	if code := subscribeCode(t, c, "$saguin/queue/jobs", nil); code != 0x80 {
		t.Errorf("a queue's own form was answered 0x%02x to a 3.1.1 client", code)
	}

	// The ordinary forms are untouched, and the wildcard is served
	// everything it matches except the queue's records.
	seen := make(chan string, 8)
	c2, _ := legacy(t, h, "legacy-broadcast", true)
	if code := subscribeCode(t, c2, "#", func(_ mqttv3.Client, m mqttv3.Message) {
		seen <- m.Topic()
	}); code > 2 {
		t.Fatalf("a 3.1.1 client was answered 0x%02x for `#`, which every device types "+
			"first", code)
	}
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "bcast/x", "m")
	select {
	case got := <-seen:
		if got != "bcast/x" {
			t.Fatalf("received %q", got)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the 3.1.1 wildcard subscriber received nothing, so the refusals above " +
			"were a broker refusing everything rather than one form")
	}
}

// RFC 0003 "`append` - Where a subscription starts"
//
// **The channel decides where a reader with no position starts, and both
// protocols get the same answer.** This test used to assert the opposite -
// that a 3.1.1 subscriber began at the tail and an MQTT 5 one at the floor
// - and the divergence was real but it was the wrong rule: one application
// behaved two ways depending on the library it linked, and a clean-session
// 3.1.1 device could read no history at all, because it started at the tail
// and a seek needs a durable session it did not have.
//
// **Both protocols are driven against both settings**, which is the whole
// of the claim: four combinations, one rule.
func TestWhereASubscriptionStartsIsTheChannelsAnswerNotTheProtocols(t *testing.T) {
	for _, tc := range []struct {
		name    string
		tail    bool
		replays bool
	}{
		{"the default, floor", false, true},
		{"start: tail", true, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			brokertest.StartTail = tc.tail
			t.Cleanup(func() { brokertest.StartTail = false })
			h := startAdmitting311(t)

			p := connect(t, h, "producer", true, false)
			for i := 1; i <= 3; i++ {
				p.Pub(t, "events/orders/1", fmt.Sprintf("before-%d", i))
			}
			time.Sleep(300 * time.Millisecond)

			var mu sync.Mutex
			var old []string
			c, _ := legacy(t, h, "legacy-reader", true)
			if code := subscribeCode(t, c, "events/#",
				func(_ mqttv3.Client, m mqttv3.Message) {
					mu.Lock()
					old = append(old, string(m.Payload()))
					mu.Unlock()
				}); code > 2 {
				t.Fatalf("the 3.1.1 subscriber was refused 0x%02x", code)
			}

			five := connect(t, h, "modern-reader", true, false)
			got5 := make(chan string, 8)
			five.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
				got5 <- string(pr.Packet.Payload)
				return true, nil
			})
			five.Sub(t, "events/#", 1)

			time.Sleep(1200 * time.Millisecond)
			var modern []string
			for {
				select {
				case v := <-got5:
					modern = append(modern, v)
					continue
				default:
				}
				break
			}
			mu.Lock()
			legacySaw := append([]string(nil), old...)
			mu.Unlock()

			want := 0
			if tc.replays {
				want = 3
			}
			if len(legacySaw) != want || len(modern) != want {
				t.Fatalf("with %s the 3.1.1 reader saw %v and the MQTT 5 reader saw %v, "+
					"and both should have seen %d records: the channel decides this, "+
					"not the protocol", tc.name, legacySaw, modern, want)
			}
			t.Logf("%s: both protocols saw %d of the 3 records published before they "+
				"subscribed", tc.name, want)

			// **And both are live either way**, so "saw nothing" is a tail
			// start rather than a subscription that never worked.
			p.Pub(t, "events/orders/1", "after")
			deadline := time.After(4 * time.Second)
			for {
				mu.Lock()
				n := len(old)
				mu.Unlock()
				if n > len(legacySaw) {
					break
				}
				select {
				case <-deadline:
					t.Fatal("the 3.1.1 reader received nothing published after it " +
						"subscribed, so this case proved nothing")
				case <-time.After(100 * time.Millisecond):
				}
			}
			select {
			case <-got5:
			case <-time.After(4 * time.Second):
				t.Fatal("the MQTT 5 reader received nothing published after it subscribed")
			}
		})
	}
}

// RFC 0003 "`append` - Durable consumers", RFC 0002 "max_session_expiry"
//
// **A 3.1.1 durable consumer is `cleanSession = 0` and nothing else to
// choose**. That protocol has no Session Expiry Interval, so its clean
// flag is the whole of the question and the expiry it gets is the broker's
// ceiling - the same one that caps what an MQTT 5 client may ask for.
// Before this it read as zero for every 3.1.1 client, which made three
// things wrong at once: no stored position, a cursor that expired
// immediately, and a seek refused for want of a durable session.
//
// **The broker is restarted in the middle, and that is the whole test.**
// The first version simply disconnected and reconnected, and it passed
// against the defect: the substrate keeps its own per-session queue for an
// offline persistent session, so the records arrived from *that* and the
// test could not tell saguin's stored position from a buffer it does not
// use. A restart is the discriminator, because the buffer dies with the
// process and a position stored beside the records does not - which is the
// property the README leads with and the reason a persistent session here
// cannot overflow.
func TestA311DurableConsumerResumesAcrossARestart(t *testing.T) {
	admitting311(t)
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)

	p := connect(t, h, "producer", true, false)

	var mu sync.Mutex
	var got []string
	record := func(_ mqttv3.Client, m mqttv3.Message) {
		mu.Lock()
		got = append(got, string(m.Payload()))
		mu.Unlock()
	}
	take := func(c mqttv3.Client) {
		if code := subscribeCode(t, c, "events/#", record); code > 2 {
			t.Fatalf("the durable 3.1.1 consumer was refused 0x%02x", code)
		}
	}
	waitFor := func(n int, what string) {
		t.Helper()
		deadline := time.After(8 * time.Second)
		for {
			mu.Lock()
			have := len(got)
			snapshot := append([]string(nil), got...)
			mu.Unlock()
			if have >= n {
				return
			}
			select {
			case <-deadline:
				t.Fatalf("%s: received %v", what, snapshot)
			case <-time.After(100 * time.Millisecond):
			}
		}
	}

	c, _ := legacy(t, h, "legacy-durable", false) // cleanSession = 0
	take(c)
	p.Pub(t, "events/orders/1", "first")
	waitFor(1, "the durable 3.1.1 consumer received nothing while connected")

	// Away, cleanly, so the position is written; then records it misses.
	c.Disconnect(100)
	time.Sleep(500 * time.Millisecond)
	for i := 1; i <= 2; i++ {
		p.Pub(t, "events/orders/1", fmt.Sprintf("missed-%d", i))
	}
	time.Sleep(500 * time.Millisecond)

	// **The substrate's session queue dies here and saguin's position does
	// not.** Anything served after this came from the stored position.
	h.Crash()
	h2 := startDurableSQLite(t, path)

	// The handler is on before CONNECT, for the reason
	// TestA311DurableConsumerAtQoS0KeepsItsPosition gives: the resumed
	// session's backlog is sent ahead of the SUBSCRIBE below.
	c2, _ := legacyWithDefault(t, h2, "legacy-durable", false, record)
	take(c2)
	waitFor(3, "the 3.1.1 consumer resumed after a restart and was not served what the "+
		"outage missed, so its position was never stored")

	mu.Lock()
	defer mu.Unlock()
	for i, want := range []string{"first", "missed-1", "missed-2"} {
		if got[i] != want {
			t.Errorf("record %d was %q, want %q - in order, from the stored position",
				i, got[i], want)
		}
	}
}

// RFC 0003 "From publish to record: identity and headers"
//
// **The delivery-path walk** (step 5), driven rather than read. Every
// version-conditional between a stored record and a socket is exercised by
// putting a 3.1.1 consumer and an MQTT 5 consumer on the same records and
// comparing what each is given.
//
// What a 3.1.1 client must get: the topic and the payload, unchanged, in a
// frame its own library can parse. What it must not get: a corrupt frame
// from MQTT 5 properties written into a packet that has nowhere to put
// them. The records are identical either way - what differs is only what
// the wire can carry.
func TestWhatAChannelDeliveryLosesOnItsWayToA311Socket(t *testing.T) {
	h := startAdmitting311(t)

	var mu sync.Mutex
	var old []mqttv3.Message
	c, _ := legacy(t, h, "legacy-consumer", true)
	if code := subscribeCode(t, c, "events/#", func(_ mqttv3.Client, m mqttv3.Message) {
		mu.Lock()
		old = append(old, m)
		mu.Unlock()
	}); code > 2 {
		t.Fatalf("refused 0x%02x", code)
	}

	five := connect(t, h, "modern-consumer", true, false)
	got5 := make(chan *paho.Publish, 8)
	five.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		got5 <- pr.Packet
		return true, nil
	})
	five.Sub(t, "events/#", 1)

	// A record carrying everything MQTT 5 can attach and 3.1.1 cannot.
	p := connect(t, h, "producer", true, false)
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "events/orders/7", QoS: 1, Payload: []byte("payload-7"),
		Properties: &paho.PublishProperties{
			ContentType:     "application/json",
			CorrelationData: []byte("corr"),
			User:            paho.UserProperties{{Key: "trace", Value: "abc"}},
		},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}

	select {
	case pk := <-got5:
		// The MQTT 5 consumer is the control: it proves the record carries
		// what a 3.1.1 delivery is about to be missing.
		if pk.Properties == nil || len(pk.Properties.User) == 0 {
			t.Error("the MQTT 5 consumer received no user properties, so this test cannot " +
				"say what the 3.1.1 one lost")
		}
		var sawOffset bool
		for _, u := range pk.Properties.User {
			if u.Key == "saguin-offset" {
				sawOffset = true
			}
		}
		if !sawOffset {
			t.Error("the MQTT 5 consumer received no saguin-offset")
		}
	case <-time.After(4 * time.Second):
		t.Fatal("the MQTT 5 consumer received nothing")
	}

	deadline := time.After(4 * time.Second)
	for {
		mu.Lock()
		n := len(old)
		mu.Unlock()
		if n > 0 {
			break
		}
		select {
		case <-deadline:
			t.Fatal("the 3.1.1 consumer received nothing: a channel delivery is injected " +
				"carrying MQTT 5 properties, and if the writer corrupted the frame this " +
				"is where it would show")
		case <-time.After(100 * time.Millisecond):
		}
	}

	mu.Lock()
	defer mu.Unlock()
	m := old[0]
	if m.Topic() != "events/orders/7" {
		t.Errorf("the 3.1.1 consumer received topic %q", m.Topic())
	}
	if string(m.Payload()) != "payload-7" {
		t.Errorf("the 3.1.1 consumer received payload %q", string(m.Payload()))
	}
	if m.Qos() != 1 {
		t.Errorf("the 3.1.1 consumer was delivered at QoS %d", m.Qos())
	}
	t.Logf("the 3.1.1 consumer received %s %q at QoS %d, with no properties - the frame "+
		"has nowhere to put them and was not corrupted by them",
		m.Topic(), string(m.Payload()), m.Qos())
}

// RFC 0003 "From publish to record", RFC 0002
//
// **The substrate's message-expiry sweep reads the packet's protocol
// version, not the record's** - `tk.ProtocolVersion == 5` - so a delivery
// in flight to a 3.1.1 client is never dropped for having expired, where
// one to an MQTT 5 client is. The plan named this as the first thing the
// delivery-path walk should check.
//
// This drives it: an MQTT 5 publisher sets a short Message Expiry Interval
// on a broadcast topic, both a 3.1.1 and an MQTT 5 persistent session are
// away while it passes, and both come back. The question is whether the
// two are served the same thing.
func TestAnExpiredBroadcastReachesBothProtocolsAlike(t *testing.T) {
	h := startAdmitting311(t)

	// Both sessions subscribe, then leave.
	c, _ := legacy(t, h, "legacy-away", false)
	if code := subscribeCode(t, c, "bcast/#", nil); code > 2 {
		t.Fatalf("refused 0x%02x", code)
	}
	c.Disconnect(100)

	five := connect(t, h, "modern-away", false, false)
	five.Sub(t, "bcast/#", 1)
	gone(t, five)
	time.Sleep(300 * time.Millisecond)

	// **Two messages, and the second is the control.** One carries a short
	// expiry and one carries none, so a run where neither arrives can be
	// told from a run where the expiry did the work. Without it this test
	// passed with both sides empty, which proves nothing at all.
	p := connect(t, h, "producer", true, false)
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "bcast/perishable", QoS: 1, Payload: []byte("stale"),
		Properties: &paho.PublishProperties{MessageExpiry: uint32Ptr(1)},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "bcast/keeps", QoS: 1, Payload: []byte("no-expiry"),
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	time.Sleep(3 * time.Second) // well past the interval

	// **The route is attached before connecting, not with the subscribe.**
	// A resumed session is redelivered its backlog immediately after
	// CONNACK, which beats a SUBSCRIBE sent after it - and Paho v3
	// acknowledges a QoS 1 publish it has no route for and drops it, so the
	// control was consumed and this test read `[]` about a broker that had
	// delivered. Measured: it failed the full run and 1 of 6 isolated runs
	// with exactly that signature, while ten raw-socket rounds of the same
	// sequence were served the message 10 of 10.
	var mu sync.Mutex
	var oldGot []string
	collect := func(_ mqttv3.Client, m mqttv3.Message) {
		mu.Lock()
		oldGot = append(oldGot, string(m.Payload()))
		mu.Unlock()
	}
	c2, _ := legacyWithDefault(t, h, "legacy-away", false, collect)
	if code := subscribeCode(t, c2, "bcast/#", collect); code > 2 {
		t.Fatalf("refused 0x%02x", code)
	}

	// The MQTT 5 side reads what the client itself recorded, from a handler
	// set before its CONNECT, for the reason the 3.1.1 side's route is: one
	// added after Connect missed the resumed backlog once Dial waited for
	// the registration (5 runs in 400 saw nothing, the control included).
	five2 := connect(t, h, "modern-away", false, false)
	five2.Sub(t, "bcast/#", 1)

	time.Sleep(2 * time.Second)
	mu.Lock()
	legacySaw := append([]string(nil), oldGot...)
	mu.Unlock()
	modernSaw := five2.Payloads()

	sort.Strings(legacySaw)
	sort.Strings(modernSaw)
	t.Logf("away 3s, one broadcast with a 1s expiry and one with none: "+
		"the 3.1.1 session saw %v, the MQTT 5 session saw %v", legacySaw, modernSaw)

	// **The property is that the two protocols agree**, whatever the answer
	// is. The substrate's expiry sweep reads the packet's protocol version,
	// so if anything is queued for an offline session it is expired for one
	// protocol and not the other - and that difference is what this refuses.
	if !slices.Equal(legacySaw, modernSaw) {
		t.Errorf("the two protocols were served differently: 3.1.1 saw %v and MQTT 5 saw "+
			"%v. The substrate's expiry sweep is gated on the packet's protocol version, "+
			"so a message a 5.0 subscriber never sees must not reach a 3.1.1 one",
			legacySaw, modernSaw)
	}

	// **And what the control says about the shape of the answer.** If the
	// message with no expiry is absent too, nothing is queued for an
	// offline broadcast subscriber on either protocol - which is what
	// RFC 0001 promises, and it is also why the sweep above cannot reach
	// anybody here. Recorded rather than asserted, because it is the
	// substrate's queueing rather than saguin's rule.
	if len(modernSaw) == 0 {
		t.Log("neither session was served the control either, so a broadcast is not " +
			"queued for an offline persistent session on either protocol - the channel " +
			"is saguin's answer to that, for both (RFC 0001)")
	}
}

// RFC 0005 "The catalogue"
//
// **What an operator sees when a fleet is in a reconnect loop**. A
// counter says how many devices were hung up on and for what; a gauge says
// how much of the fleet is still on the older protocol. Neither is a number
// a client chooses, so nothing here is an unbounded series.
//
// Driven end to end rather than by calling the counter: the point is that a
// real 3.1.1 client tripping a real refusal moves the number.
func TestALegacyDisconnectIsCountedAndTheFleetMixIsVisible(t *testing.T) {
	h := startAdmitting311(t)

	// Connected, and nothing refused yet.
	c, lost := legacy(t, h, "legacy-counted", true)
	five := connect(t, h, "modern-counted", true, false)
	_ = five
	time.Sleep(300 * time.Millisecond)

	// **A minimum scrape interval of zero**, because this reads the
	// catalogue twice and a scrape inside the interval is answered with the
	// *previous* one - which would compare a body against itself and read
	// as a gauge that did not move.
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	addr := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(addr), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(func() { stop() })

	scrape := func() string {
		t.Helper()
		resp, err := http.Get("http://" + addr + "/metrics")
		if err != nil {
			t.Fatalf("scrape: %v", err)
		}
		body, err := io.ReadAll(resp.Body)
		_ = resp.Body.Close()
		if err != nil {
			t.Fatalf("read: %v", err)
		}
		return string(body)
	}
	mix := func() map[string]string {
		t.Helper()
		out := map[string]string{}
		for _, line := range strings.Split(scrape(), "\n") {
			if strings.HasPrefix(line, "saguin_connections_by_protocol{") {
				f := strings.Fields(line)
				out[f[0]] = f[1]
			}
		}
		return out
	}
	before := mix()
	if before[`saguin_connections_by_protocol{protocol="3.1.1"}`] == "" ||
		before[`saguin_connections_by_protocol{protocol="5"}`] == "" {
		t.Fatalf("the fleet mix does not show both protocols connected: %v", before)
	}
	t.Logf("fleet mix with one of each connected: %v", before)

	// A refusal the 3.1.1 client cannot be told about.
	tok := c.Publish("$saguin/not/a/verb", 1, false, []byte("x"))
	tok.WaitTimeout(3 * time.Second)
	select {
	case <-lost:
	case <-time.After(5 * time.Second):
		t.Fatal("the connection was not closed, so nothing should be counted either")
	}
	time.Sleep(500 * time.Millisecond)

	var counted string
	for _, line := range strings.Split(scrape(), "\n") {
		if strings.HasPrefix(line, "saguin_connections_refused_total{") {
			counted = line
		}
	}
	if counted == "" {
		t.Fatal("a 3.1.1 client was hung up on for a refusal and " +
			"saguin_connections_refused_total has no series at all: this is the number " +
			"behind a fleet in a reconnect loop")
	}
	t.Logf("counted: %s", counted)
	if !strings.Contains(counted, "reason=") {
		t.Errorf("the counter carries no reason label: %s", counted)
	}

	// **And the gauge followed the disconnection**, which is what says it is
	// counted from the client table rather than kept by increments.
	after := mix()
	if after[`saguin_connections_by_protocol{protocol="3.1.1"}`] ==
		before[`saguin_connections_by_protocol{protocol="3.1.1"}`] {
		t.Errorf("the 3.1.1 gauge did not move after that client was disconnected: "+
			"before %v, after %v", before, after)
	}
	t.Logf("fleet mix after the disconnection: %v", after)
}

// RFC 0005 "The /v1 routes"
//
// **Which device, which a counter must never say**. A client id is a
// string a client chose, so a metric labelled with one is a series count
// chosen by whoever connects - the catalogue is closed against exactly
// that. The question is real all the same, and it is the operator's second
// question every time: the rate will not come down, which of my three
// hundred devices is it?
func TestTheLegacyRouteNamesWhichDeviceIsFlapping(t *testing.T) {
	h := startAdmitting311(t)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	addr := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(addr), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(func() { stop() })

	read := func() struct {
		Clients []struct {
			ClientID string `json:"client_id"`
			User     string `json:"user"`
			Reason   string `json:"reason"`
			Count    uint64 `json:"count"`
			LastSeen string `json:"last_seen"`
		} `json:"clients"`
		Returned int    `json:"returned"`
		Tracked  int    `json:"tracked"`
		Beyond   uint64 `json:"beyond"`
	} {
		t.Helper()
		resp, err := http.Get("http://" + addr + "/v1/operations/refused")
		if err != nil {
			t.Fatalf("GET: %v", err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("answered %d, want 200", resp.StatusCode)
		}
		if ct := resp.Header.Get("Content-Type"); !strings.Contains(ct, "application/json") {
			t.Errorf("Content-Type %q", ct)
		}
		var out struct {
			Clients []struct {
				ClientID string `json:"client_id"`
				User     string `json:"user"`
				Reason   string `json:"reason"`
				Count    uint64 `json:"count"`
				LastSeen string `json:"last_seen"`
			} `json:"clients"`
			Returned int    `json:"returned"`
			Tracked  int    `json:"tracked"`
			Beyond   uint64 `json:"beyond"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			t.Fatalf("decode: %v", err)
		}
		return out
	}

	// Nothing has flapped, so the route is empty rather than absent.
	if got := read(); got.Tracked != 0 || len(got.Clients) != 0 {
		t.Fatalf("a broker where nothing has been refused reports %+v", got)
	}

	// One device flaps twice, another once, so the ordering has something
	// to order.
	flap := func(id string, times int) {
		for i := 0; i < times; i++ {
			c, lost := legacy(t, h, id, true)
			tok := c.Publish("$saguin/not/a/verb", 1, false, []byte("x"))
			tok.WaitTimeout(2 * time.Second)
			select {
			case <-lost:
			case <-time.After(5 * time.Second):
				t.Fatalf("%s was not disconnected", id)
			}
		}
	}
	flap("noisy-device", 2)
	flap("quiet-device", 1)
	time.Sleep(300 * time.Millisecond)

	got := read()
	if got.Tracked != 2 || got.Returned != 2 {
		t.Fatalf("two devices flapped and the route reports tracked=%d returned=%d: %+v",
			got.Tracked, got.Returned, got)
	}
	// **Worst first**, which is what makes the hundred-row cap safe: the
	// rows that fall off the end are the ones nobody was looking for.
	if got.Clients[0].ClientID != "noisy-device" {
		t.Errorf("the first row is %q, want the device that flapped most",
			got.Clients[0].ClientID)
	}
	if got.Clients[0].Count != 2 {
		t.Errorf("noisy-device flapped twice and the route counts %d", got.Clients[0].Count)
	}
	if got.Clients[0].Reason == "" || got.Clients[0].LastSeen == "" {
		t.Errorf("a row says nothing about why or when: %+v", got.Clients[0])
	}
	t.Logf("route: %+v", got.Clients)
}

// RFC 0002 "Every reason code, in one place", RFC 0001
//
// **The refusal matrix**. Every refusal a 3.1.1 client can
// reach, at both QoS levels, driven by a real 3.1.1 client.
//
// The two columns are the whole rule and they are opposites: at QoS 1 the
// connection is closed, because a 3.1.1 `PUBACK` can only say success and
// answering one for a record the broker threw away is the lie this project
// will not ship; at QoS 0 there is no reply to withhold, so it is the
// silent counted drop every refused QoS 0 publish already is and the
// client stays connected.
//
// **A row that stayed connected at QoS 1 would look identical to a row
// that was never refused**, so each case publishes something ordinary
// afterwards and requires it to arrive - proving the connection is alive
// rather than assuming it.
func TestEveryRefusalA311ClientCanReachAtBothQoS(t *testing.T) {
	for _, tc := range []struct{ name, topic string }{
		{"the reserved space", "$saguin/not/a/verb"},
		{"a seek that cannot apply", "$saguin/consumer/events/seek"},
		{"a topic too long", "bcast/" + strings.Repeat("x", 1100)},
		{"a subscription form", "$share/grp/jobs/x"},
	} {
		t.Run(tc.name+" at QoS 1 closes the connection", func(t *testing.T) {
			h := startAdmitting311(t)
			c, lost := legacy(t, h, "q1-"+tc.name, true)
			tok := c.Publish(tc.topic, 1, false, []byte("x"))
			if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
				t.Error("acknowledged: a 3.1.1 PUBACK can only say success")
			}
			select {
			case <-lost:
			case <-time.After(5 * time.Second):
				t.Error("the connection was not closed")
			}
		})

		t.Run(tc.name+" at QoS 0 is a silent drop", func(t *testing.T) {
			h := startAdmitting311(t)
			seen := make(chan string, 4)
			c, lost := legacy(t, h, "q0-"+tc.name, true)
			if code := subscribeCode(t, c, "bcast/#",
				func(_ mqttv3.Client, m mqttv3.Message) { seen <- m.Topic() }); code > 2 {
				t.Fatalf("refused 0x%02x", code)
			}
			tok := c.Publish(tc.topic, 0, false, []byte("x"))
			tok.WaitTimeout(3 * time.Second)

			select {
			case <-lost:
				t.Fatal("the connection was closed for a QoS 0 refusal: there is no reply " +
					"to withhold, so it is dropped and counted like any other")
			case <-time.After(1500 * time.Millisecond):
			}

			// **Alive, proved rather than assumed.** Without this the case
			// above would read the same for a broker that never refused.
			p := connect(t, h, "prod-"+tc.name, true, false)
			p.Pub(t, "bcast/alive", "yes")
			select {
			case got := <-seen:
				if got != "bcast/alive" {
					t.Fatalf("received %q", got)
				}
			case <-time.After(4 * time.Second):
				t.Fatal("the 3.1.1 client received nothing after the QoS 0 refusal, so it " +
					"was not connected and this case proved nothing")
			}
		})
	}
}

// RFC 0002 "Every reason code, in one place" - the publish table's 0x87 row
//
// **The two rows the refusal matrix above does not reach.** That test drives
// four causes and all four are refused on one route, in the topic check. The
// table makes the same "the connection is closed" claim for 0x87 and 0x97,
// which are refused elsewhere: 0x87 by the channel deciding a record may not
// come from here, and 0x97 by the store refusing to keep it.
//
// **They reach the same gate, and that is the property worth holding.** The
// close is one site, on the common return where a refusal has produced an
// error, so what these cases prove is not a second route to it but that a
// refusal raised deep in the channel or the store still arrives there as an
// error rather than being swallowed into a success. A refusal that returned
// nil would leave a 3.1.1 client acknowledged for a record nobody kept,
// which is the lie the gate exists to prevent.
//
// A derived `<queue>__dlq` is the cause that needs no identity: a dead-letter
// channel takes its records from its queue and from nowhere else, so a client
// publishing there is refused whatever its roles say.
func TestA311ClientRefusedNotAuthorizedIsClosedAtQoS1AndDroppedAtQoS0(t *testing.T) {
	const dlq = "jobs/__dlq/failed"

	// **Which row this drives, asserted rather than assumed.** A 3.1.1
	// client is told no code at all, so without this the test would keep
	// passing if the dead-letter refusal moved to another code and would
	// then be evidence for a row it no longer touches.
	t.Run("the same publish answers 0x87 to a client that can be told", func(t *testing.T) {
		h := start(t)
		c := connect(t, h, "dlq-v5", true, false)
		ack, err := c.C.Publish(context.Background(), &paho.Publish{
			Topic: dlq, QoS: 1, Payload: []byte("x"),
		})
		if ack == nil {
			t.Fatalf("no PUBACK: %v", err)
		}
		if ack.ReasonCode != 0x87 {
			t.Fatalf("a publish to a derived dead-letter channel answered 0x%02X, "+
				"want 0x87: the cases below drive the 0x87 row and cannot see "+
				"the code themselves", ack.ReasonCode)
		}
	})

	t.Run("at QoS 1 the connection is closed", func(t *testing.T) {
		h := startAdmitting311(t)
		c, lost := legacy(t, h, "dlq-q1", true)
		tok := c.Publish(dlq, 1, false, []byte("x"))
		if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
			t.Error("acknowledged: a 3.1.1 PUBACK can only say success, so a " +
				"record the broker would not take cannot be answered with one")
		}
		select {
		case <-lost:
		case <-time.After(5 * time.Second):
			t.Error("the connection was not closed: a 3.1.1 client has no reason " +
				"code to be told 0x87 with, so the close is the whole of the answer")
		}
	})

	t.Run("at QoS 0 it is a silent drop", func(t *testing.T) {
		h := startAdmitting311(t)
		seen := make(chan string, 4)
		c, lost := legacy(t, h, "dlq-q0", true)
		if code := subscribeCode(t, c, "bcast/#",
			func(_ mqttv3.Client, m mqttv3.Message) { seen <- m.Topic() }); code > 2 {
			t.Fatalf("refused 0x%02x", code)
		}
		tok := c.Publish(dlq, 0, false, []byte("x"))
		tok.WaitTimeout(3 * time.Second)

		select {
		case <-lost:
			t.Fatal("the connection was closed for a QoS 0 refusal: there is no " +
				"reply to withhold, so it is dropped and counted like any other")
		case <-time.After(1500 * time.Millisecond):
		}

		// Alive, proved rather than assumed: without this the case above
		// would read the same for a broker that never refused.
		p := connect(t, h, "dlq-prod", true, false)
		p.Pub(t, "bcast/alive", "yes")
		select {
		case got := <-seen:
			if got != "bcast/alive" {
				t.Fatalf("received %q", got)
			}
		case <-time.After(4 * time.Second):
			t.Fatal("the 3.1.1 client received nothing after the QoS 0 refusal, " +
				"so it was not connected and this case proved nothing")
		}
	})
}

// RFC 0002 "Every reason code, in one place" - the publish table's 0x97 row,
// and "Bounds on what a channel holds"
//
// The other half of the pair above. 0x97 is raised by the store rather than
// by the topic check, and the table claims the same close for a 3.1.1 client.
//
// **Two of that row's three causes are unreachable from 3.1.1, and the third
// is what this drives.** `max_header_count` and `max_header_bytes` bound User
// Properties, which 3.1.1 does not have, so a full channel is the only way a
// legacy client meets this code at all.
func TestA311ClientRefusedQuotaExceededIsClosedAtQoS1AndDroppedAtQoS0(t *testing.T) {
	// Room for one record of this size and not two, sized as the v5 case is.
	one := store.RecordSize(store.Record{
		MessageID: "0123456789012345678901234567890123456", // a UUIDv7 is 36
		Topic:     "events/orders/1",
		Payload:   []byte("0123456789"),
	})
	bounds := map[string]int64{"events": one + one/2}

	t.Run("at QoS 1 the connection is closed", func(t *testing.T) {
		h := startBounded(t, "", bounds)
		c, lost := legacy(t, h, "full-q1", true)

		// The first fits, and it has to be acknowledged: a test whose first
		// publish was already refused would close the connection for the
		// wrong reason and still pass.
		tok := c.Publish("events/orders/1", 1, false, []byte("0123456789"))
		if !tok.WaitTimeout(5*time.Second) || tok.Error() != nil {
			t.Fatalf("the publish that fits was not acknowledged: %v", tok.Error())
		}

		tok = c.Publish("events/orders/2", 1, false, []byte("0123456789"))
		if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
			t.Error("the publish past the bound was acknowledged: a 3.1.1 PUBACK " +
				"can only say success, and the record was not kept")
		}
		select {
		case <-lost:
		case <-time.After(5 * time.Second):
			t.Error("the connection was not closed: a full channel refuses at " +
				"0x97 and a 3.1.1 client cannot be told a reason code")
		}
	})

	t.Run("at QoS 0 it is a silent drop", func(t *testing.T) {
		h := startBounded(t, "", bounds)
		seen := make(chan string, 4)
		c, lost := legacy(t, h, "full-q0", true)
		if code := subscribeCode(t, c, "bcast/#",
			func(_ mqttv3.Client, m mqttv3.Message) { seen <- m.Topic() }); code > 2 {
			t.Fatalf("refused 0x%02x", code)
		}
		for _, n := range []string{"1", "2", "3"} {
			tok := c.Publish("events/orders/"+n, 0, false, []byte("0123456789"))
			tok.WaitTimeout(2 * time.Second)
		}

		select {
		case <-lost:
			t.Fatal("the connection was closed for a QoS 0 refusal: there is no " +
				"reply to withhold, so it is dropped and counted like any other")
		case <-time.After(1500 * time.Millisecond):
		}

		p := connect(t, h, "full-prod", true, false)
		p.Pub(t, "bcast/alive", "yes")
		select {
		case got := <-seen:
			if got != "bcast/alive" {
				t.Fatalf("received %q", got)
			}
		case <-time.After(4 * time.Second):
			t.Fatal("the 3.1.1 client received nothing after the QoS 0 refusals, " +
				"so it was not connected and this case proved nothing")
		}
	})
}

// RFC 0002 "Every reason code, in one place" - the CONNECT table
//
// A device that connects with a retained Will and then publishes a retained
// birth message is a common firmware pattern; against a broker with no
// retained store attached every one of them is turned away at CONNECT
// before it publishes anything. The binary always attaches the store, so
// this is the harness-only guard.
//
// Both halves are driven, because the interesting claim is that the *same*
// client is admitted once a store exists.
func TestARetainedWillFromA311ClientNeedsAStore(t *testing.T) {
	connectWithRetainedWill := func(t *testing.T, h *harness, id string) error {
		t.Helper()
		opts := mqttv3.NewClientOptions().
			AddBroker("tcp://"+h.Addr).
			SetClientID(id).
			SetProtocolVersion(4).
			SetCleanSession(true).
			SetAutoReconnect(false).
			SetConnectTimeout(4*time.Second).
			SetWill("bcast/status/"+id, "offline", 1, true)
		c := mqttv3.NewClient(opts)
		tok := c.Connect()
		if !tok.WaitTimeout(6 * time.Second) {
			return fmt.Errorf("the CONNECT never completed")
		}
		if tok.Error() != nil {
			return tok.Error()
		}
		t.Cleanup(func() { c.Disconnect(100) })
		return nil
	}

	// **Read at the socket, not through the client library.** Paho v3
	// reported this refusal with a nil error while the CONNACK carried a
	// code 3.1.1 does not define, before the broker mapped it to one that
	// protocol does (RFC 0002 "Every reason code, in one place"). So the
	// return code is read from the wire: it
	// is the broker's answer either way, and reading it is what tells a
	// refusal apart from an admission whatever the library makes of it.
	returnCode := func(t *testing.T, h *harness, id string, retained bool) byte {
		t.Helper()
		conn, err := net.Dial("tcp", h.Addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		defer conn.Close()
		will := "bcast/status/" + id
		flags := byte(0x06) // clean session, will flag
		if retained {
			flags |= 0x20 // will retain
		}
		var body []byte
		body = append(body, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, flags, 0x00, 0x3c)
		put := func(s string) {
			body = append(body, byte(len(s)>>8), byte(len(s)))
			body = append(body, s...)
		}
		put(id)
		put(will)
		put("offline")
		pkt := append([]byte{0x10, byte(len(body))}, body...)
		if _, err := conn.Write(pkt); err != nil {
			t.Fatalf("write: %v", err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(4 * time.Second))
		buf := make([]byte, 4)
		if _, err := io.ReadFull(conn, buf); err != nil {
			t.Fatalf("no CONNACK: %v", err)
		}
		if buf[0] != 0x20 {
			t.Fatalf("expected a CONNACK, got %#x", buf[0])
		}
		return buf[3]
	}

	t.Run("no retained store: refused at CONNECT", func(t *testing.T) {
		h := startAdmitting311(t)
		code := returnCode(t, h, "tasmota-a", true)
		if code == 0x00 {
			t.Fatal("a 3.1.1 client with a retained Will was admitted by a broker with no " +
				"retained store: its Will could never be kept, and admitting it means the " +
				"broker promised something it cannot do")
		}
		t.Logf("refused with return code %#x", code)
		// **The code must be one 3.1.1 defines**. Its CONNACK carries
		// one of five, and saguin's `0x9A` is not among them - a device is
		// told something its own specification has no meaning for.
		if code > 0x05 {
			t.Errorf("the CONNACK carries %#x, which is an MQTT 5 reason code: 3.1.1 "+
				"defines five return codes and this is not one of them, so the device "+
				"cannot read its own refusal (RFC 0002, the CONNECT table)", code)
		}
	})

	// **The route must show this one above all** (RFC 0005
	// `/v1/operations/refused`). A fleet of devices
	// refused at CONNECT for a retained Will never publishes anything, so a
	// record fed only from the publish path would be empty for exactly the
	// flap an operator is most likely to meet.
	t.Run("the refusal reaches the operations route", func(t *testing.T) {
		h := startAdmitting311(t)
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatalf("pick a port: %v", err)
		}
		opsAddr := ln.Addr().String()
		_ = ln.Close()
		stop, err := h.B.ServeOperations(tcpOnly(opsAddr), 0, nil, nil)
		if err != nil {
			t.Fatalf("serve operations: %v", err)
		}
		t.Cleanup(func() { stop() })

		for i := 0; i < 2; i++ {
			if code := returnCode(t, h, "tasmota-loop", true); code == 0x00 {
				t.Fatal("admitted")
			}
		}
		resp, err := http.Get("http://" + opsAddr + "/v1/operations/refused")
		if err != nil {
			t.Fatalf("GET: %v", err)
		}
		defer resp.Body.Close()
		var out struct {
			Clients []struct {
				ClientID string `json:"client_id"`
				Reason   string `json:"reason"`
				Count    uint64 `json:"count"`
			} `json:"clients"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			t.Fatalf("decode: %v", err)
		}
		if len(out.Clients) == 0 {
			t.Fatal("a device was turned away twice at CONNECT for a retained Will and the " +
				"route names nobody: this is the loop the route exists to show an operator, " +
				"and it happens before a single publish")
		}
		if out.Clients[0].ClientID != "tasmota-loop" || out.Clients[0].Count != 2 {
			t.Errorf("the route says %+v, want tasmota-loop counted twice", out.Clients[0])
		}
		if out.Clients[0].Reason == "" {
			t.Error("the row says nothing about why")
		}
		t.Logf("route: %+v", out.Clients[0])
	})

	t.Run("a retained store: admitted", func(t *testing.T) {
		h := startRetaining(t, 0)
		if err := connectWithRetainedWill(t, h, "tasmota-b"); err != nil {
			t.Errorf("a 3.1.1 client with a retained Will was refused by a broker that has "+
				"a store to keep it in: %v", err)
		}
	})
}

// RFC 0002 "How long a client may go quiet: limits.max_keepalive"
//
// **A 3.1.1 client keeps the keepalive it asked for**. Server Keep
// Alive is an MQTT 5 CONNACK property with no 3.1.1 equivalent, so there is
// no way to tell such a client a shorter value - and enforcing one it
// cannot know is a disconnection every time its own timer is the longer,
// which is a flap loop written into the configuration file.
//
// The assertion is that it stays connected well past the ceiling while
// sending nothing, which is exactly what enforcing the cap would break.
func TestA311ClientKeepsTheKeepaliveItAskedFor(t *testing.T) {
	brokertest.KeepaliveCeiling = 1 // one second, far below what the client asks
	t.Cleanup(func() { brokertest.KeepaliveCeiling = 0 })
	h := startAdmitting311(t)

	opts := mqttv3.NewClientOptions().
		AddBroker("tcp://" + h.Addr).
		SetClientID("chatty-later").
		SetProtocolVersion(4).
		SetCleanSession(true).
		SetAutoReconnect(false).
		SetKeepAlive(60 * time.Second)
	lost := make(chan struct{}, 1)
	opts.SetConnectionLostHandler(func(mqttv3.Client, error) {
		select {
		case lost <- struct{}{}:
		default:
		}
	})
	c := mqttv3.NewClient(opts)
	if tok := c.Connect(); !tok.WaitTimeout(5*time.Second) || tok.Error() != nil {
		t.Fatalf("connect: %v", tok.Error())
	}
	t.Cleanup(func() { c.Disconnect(100) })

	select {
	case <-lost:
		t.Fatal("a 3.1.1 client asking for a 60s keepalive was disconnected by a broker " +
			"with a 1s ceiling: it cannot be told the ceiling, so enforcing one is a " +
			"flap loop by configuration (RFC 0002 limits.max_keepalive)")
	case <-time.After(4 * time.Second):
	}
	if !c.IsConnected() {
		t.Fatal("the client is no longer connected")
	}
	if tok := c.Publish("bcast/still-here", 1, false, []byte("x")); !tok.WaitTimeout(3*time.Second) ||
		tok.Error() != nil {
		t.Fatalf("the connection is not usable after the ceiling passed: %v", tok.Error())
	}
}

// RFC 0002 "Every reason code, in one place" - the CONNECT table
//
// **Every CONNECT refusal a 3.1.1 client can reach must be a code 3.1.1
// defines**. Its CONNACK carries one of five; saguin has more reasons
// than five, so the mapping is saguin's to make and the substrate's own is
// both incomplete and, for a credential, not what this broker wants.
//
// Read at the socket, because the client library is exactly what cannot be
// trusted here: Paho v3 reported the unmapped `0x9A` as no error at all.
func TestEveryCONNECTRefusalReachesA311ClientAsACodeItDefines(t *testing.T) {
	// **The clean flag is a parameter**, because one of the cases below is
	// about the *pair* - an empty client id with `cleanSession = 0` - and a
	// helper that always set it tested the admitted case twice while
	// claiming to test both.
	connackFlags := func(t *testing.T, addr string, clean bool,
		clientID, user, pass string) byte {
		t.Helper()
		conn, err := net.Dial("tcp", addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		defer conn.Close()
		var flags byte
		if clean {
			flags = 0x02
		}
		if user != "" {
			flags |= 0x80
		}
		if pass != "" {
			flags |= 0x40
		}
		var body []byte
		body = append(body, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, flags, 0x00, 0x3c)
		put := func(s string) {
			body = append(body, byte(len(s)>>8), byte(len(s)))
			body = append(body, s...)
		}
		put(clientID)
		if user != "" {
			put(user)
		}
		if pass != "" {
			put(pass)
		}
		// **The remaining length is a varint, and a single byte is a probe
		// defect rather than a shortcut**: the over-long client id below
		// makes a body past 255 bytes, and truncating the length into one
		// byte sends a malformed packet the broker refuses for a reason
		// that has nothing to do with what is under test.
		pkt := []byte{0x10}
		for n := len(body); ; {
			d := byte(n % 128)
			n /= 128
			if n > 0 {
				d |= 0x80
			}
			pkt = append(pkt, d)
			if n == 0 {
				break
			}
		}
		pkt = append(pkt, body...)
		if _, err := conn.Write(pkt); err != nil {
			t.Fatalf("write: %v", err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(4 * time.Second))
		buf := make([]byte, 4)
		if _, err := io.ReadFull(conn, buf); err != nil {
			t.Fatalf("no CONNACK: %v", err)
		}
		if buf[0] != 0x20 {
			t.Fatalf("expected a CONNACK, got %#x", buf[0])
		}
		return buf[3]
	}

	connack := func(t *testing.T, addr string, clientID, user, pass string) byte {
		t.Helper()
		return connackFlags(t, addr, true, clientID, user, pass)
	}

	t.Run("a client id over the bound is 0x02", func(t *testing.T) {
		h := startAdmitting311(t)
		got := connack(t, h.Addr, strings.Repeat("n", limits.MaxClientIDLength+1), "", "")
		if got != 0x02 {
			t.Errorf("a client id over max_client_id_length answered %#x, want 0x02 "+
				"(Identifier rejected) - an MQTT 5 client gets 0x85 here", got)
		}
	})

	// **The row that decided where the translation lives.** A wrong
	// credential is refused by the substrate before any saguin hook is
	// asked, so translating at saguin's own CONNACK sends would have left
	// the refusal a fleet meets most often answering a code 3.1.1 does not
	// define. Rewriting at the encode hook catches every CONNACK whoever
	// sent it.
	t.Run("a wrong credential is 0x04, not 0x05", func(t *testing.T) {
		h := startAdmitting311(t)
		path := filepath.Join(t.TempDir(), "clients.passwd")
		pf := passwd.New(path)
		if err := pf.Set("device", "right"); err != nil {
			t.Fatalf("set: %v", err)
		}
		if err := pf.Save(); err != nil {
			t.Fatalf("save: %v", err)
		}
		users, err := passwd.Load(path)
		if err != nil {
			t.Fatalf("load: %v", err)
		}
		h.B.SetCredentials(users, false)

		got := connack(t, h.Addr, "device", "device", "wrong")
		if got != 0x04 {
			t.Errorf("a wrong credential answered %#x, want 0x04 (Bad user name or "+
				"password). 0x05 is where the three Will refusals go, and collapsing the "+
				"two sends whoever is holding the device to the wrong file - which is what "+
				"the substrate's own mapping does", got)
		}
	})

	// **A zero-byte client id with `cleanSession = 0` is `0x02`**, which
	// 3.1.1 names for itself (MQTT-3.1.3-8): the session it asks the broker
	// to keep has no id to keep it under. It was answered `0x05`, which
	// sends whoever holds the device to check credentials when the fix is
	// an id or the clean flag.
	t.Run("an empty client id with cleanSession 0 is 0x02", func(t *testing.T) {
		h := startAdmitting311(t)
		if got := connackFlags(t, h.Addr, false, "", "", ""); got != 0x02 {
			t.Errorf("an empty client id with cleanSession = 0 answered %#x, want 0x02 "+
				"(Identifier rejected)", got)
		}
	})

	// **And what the operator is told about it.** The device gets `0x02`
	// above; this is the other half, and it is the row where a bad name
	// costs the most - the client id is empty, that being the refusal, so
	// "which device" cannot be answered and "why" is all the operator has.
	// The substrate refuses with `0x80`, whose ordinary name is "unspecified
	// error", which is true and answers nothing.
	t.Run("the operator is told the condition, not 0x80's generic name", func(t *testing.T) {
		h := startAdmitting311(t)
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatalf("pick a port: %v", err)
		}
		opsAddr := ln.Addr().String()
		_ = ln.Close()
		stop, err := h.B.ServeOperations(tcpOnly(opsAddr), 0, nil, nil)
		if err != nil {
			t.Fatalf("serve operations: %v", err)
		}
		t.Cleanup(func() { stop() })

		if got := connackFlags(t, h.Addr, false, "", "", ""); got != 0x02 {
			t.Fatalf("the refusal under test did not happen: %#x", got)
		}
		resp, err := http.Get("http://" + opsAddr + "/v1/operations/refused")
		if err != nil {
			t.Fatalf("GET: %v", err)
		}
		defer resp.Body.Close()
		var out struct {
			Clients []struct {
				ClientID string `json:"client_id"`
				Reason   string `json:"reason"`
			} `json:"clients"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			t.Fatalf("decode: %v", err)
		}
		if len(out.Clients) != 1 {
			t.Fatalf("the refusal reached the route as %+v, want one row", out.Clients)
		}
		if out.Clients[0].Reason != "client identifier not valid" {
			t.Errorf("the route names the reason %q, want \"client identifier not valid\" "+
				"- the condition in the same words the too-long-id refusal uses. This is "+
				"the one row whose device cannot be named, so the reason is the whole of "+
				"what an operator has to act on", out.Clients[0].Reason)
		}
	})

	// **And the same id with `cleanSession = 1` is admitted**, which is what
	// says the rule above is about the pair rather than about an empty id:
	// a session that ends with the connection needs no name to be kept
	// under, and the broker assigns one.
	t.Run("an empty client id with cleanSession 1 is admitted", func(t *testing.T) {
		h := startAdmitting311(t)
		if got := connackFlags(t, h.Addr, true, "", "", ""); got != 0x00 {
			t.Errorf("an empty client id with cleanSession = 1 answered %#x, want 0x00", got)
		}
	})

	// Every answer above is one of 3.1.1's five, which is the rule rather
	// than a property of these two rows.
	t.Run("no answer is an MQTT 5 code", func(t *testing.T) {
		h := startAdmitting311(t)
		if got := connack(t, h.Addr, "ordinary", "", ""); got != 0x00 {
			t.Fatalf("an ordinary 3.1.1 CONNECT answered %#x", got)
		}
	})
}

// RFC 0005 `/v1/operations/consumers`, RFC 0003 "Durable consumers"
//
// **The per-channel consumer gauges and `/v1/operations/consumers` include
// a 3.1.1 consumer once it holds a position**, which is a claim about two
// existing instruments rather than a new one, so it is driven rather than
// assumed. A durable 3.1.1 consumer holds a position exactly as an MQTT 5
// one does; an operator asking which consumers are behind must see it, or
// half the fleet is invisible on the route that exists to find stragglers.
func TestA311ConsumerAppearsOnTheConsumersRoute(t *testing.T) {
	admitting311(t)
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	opsAddr := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(opsAddr), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(func() { stop() })

	got := make(chan string, 4)
	c, _ := legacy(t, h, "legacy-consumer-seen", false) // durable
	if code := subscribeCode(t, c, "events/#", func(_ mqttv3.Client, m mqttv3.Message) {
		got <- string(m.Payload())
	}); code > 2 {
		t.Fatalf("refused 0x%02x", code)
	}
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/orders/1", "one")
	select {
	case <-got:
	case <-time.After(4 * time.Second):
		t.Fatal("the 3.1.1 consumer received nothing, so it holds no position to report")
	}
	// The position is written on the broker's own clock and at disconnect.
	c.Disconnect(100)
	time.Sleep(700 * time.Millisecond)

	resp, err := http.Get("http://" + opsAddr + "/v1/operations/consumers")
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if !strings.Contains(string(body), "legacy-consumer-seen") {
		t.Fatalf("a durable 3.1.1 consumer holds a position and /v1/operations/consumers "+
			"does not name it, so an operator looking for stragglers cannot see half a "+
			"mixed fleet: %s", string(body))
	}
	t.Logf("the consumers route names the 3.1.1 reader")
}

// RFC 0003 "`latest` - A 3.1.1 subscriber", "`append` - Durable consumers"
//
// **The RETAIN flag is how a 3.1.1 client tells state from an event**,
// and it is the one thing that separates the two channel types on the wire
// for a client that can see nothing else. A `latest` value arrives with the
// flag set, because a value *is* current state and RETAIN is MQTT's own way
// of saying so - it has no offset, no timestamp and no id to work it out
// from.
//
// **And an `append` record never carries it.** Dressing the newest record
// as retained would look like a cheap replay for a client that starts at
// the tail, and it is the opposite: a rebooting device would act on a stale
// event a second time, believing it current.
func TestA311ClientTellsStateFromAnEventByTheRetainFlag(t *testing.T) {
	h := startAdmitting311(t)

	// **Only the latest value is published before subscribing.** The append
	// record comes after, because where a reader with no position starts is
	// the channel's business now and is tested on its own - mixing the two
	// made this test assert a start rule while claiming to be about a flag,
	// and it broke the day that rule moved.
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "state/sensor-4", "22.5")
	time.Sleep(400 * time.Millisecond)

	type msg struct {
		topic    string
		retained bool
	}
	seen := make(chan msg, 8)
	c, _ := legacy(t, h, "legacy-reader", true)
	handler := func(_ mqttv3.Client, m mqttv3.Message) {
		seen <- msg{m.Topic(), m.Retained()}
	}
	if code := subscribeCode(t, c, "state/#", handler); code > 2 {
		t.Fatalf("state refused 0x%02x", code)
	}
	if code := subscribeCode(t, c, "events/#", handler); code > 2 {
		t.Fatalf("events refused 0x%02x", code)
	}

	// **Current state arrives on subscribe, with the flag.**
	select {
	case got := <-seen:
		if got.topic != "state/sensor-4" {
			t.Fatalf("the first delivery was %q, want the latest channel's current value",
				got.topic)
		}
		if !got.retained {
			t.Error("the current value arrived without the RETAIN flag: a 3.1.1 client has " +
				"no offset or timestamp to tell state from an event, and this flag is the " +
				"only thing that does")
		}
	case <-time.After(4 * time.Second):
		t.Fatal("no current state was delivered on subscribe")
	}

	// **And an append record never carries the flag**, whenever it arrives.
	p.Pub(t, "events/orders/10", "later")
	select {
	case got := <-seen:
		if got.topic != "events/orders/10" {
			t.Fatalf("received %q, want the append record", got.topic)
		}
		if got.retained {
			t.Error("an append delivery carried the RETAIN flag: to a client that starts " +
				"at the tail that reads as current state, and a rebooting device would " +
				"act on a stale event a second time")
		}
	case <-time.After(4 * time.Second):
		t.Fatal("the append record published after the subscription never arrived")
	}
}

// RFC 0003 "Moving a consumer's position: seek" - the matrix's seek row
//
// **Four seek payloads from a durable 3.1.1 session**. Two are never
// refused on one - `0`, everything the channel still holds, and `-1`, from
// now on - and those are the two the documentation leads with, because a
// duration races retention and an offset can fall below the floor. The
// refused ones close the connection, since a 3.1.1 `PUBACK` cannot carry a
// reason.
//
// This is where the tail rule earns the seek: a 3.1.1 consumer starts at
// the tail, so `0` is the only way it ever reads history at all.
func TestA311DurableSessionSeeksAndIsRefusedTheRest(t *testing.T) {
	for _, tc := range []struct {
		name    string
		payload string
		refused bool
	}{
		{"the floor", "0", false},
		{"from now on", "-1", false},
		{"an in-range offset", "2", false},
		{"an offset past the end", "99999", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := startAdmitting311(t)
			p := connect(t, h, "producer", true, false)
			for i := 1; i <= 3; i++ {
				p.Pub(t, "events/orders/1", fmt.Sprintf("r%d", i))
			}
			time.Sleep(300 * time.Millisecond)

			c, lost := legacy(t, h, "seeker-"+tc.name, false) // durable
			if code := subscribeCode(t, c, "events/#", nil); code > 2 {
				t.Fatalf("subscribe refused 0x%02x", code)
			}
			tok := c.Publish("$saguin/consumer/events/seek", 1, false, []byte(tc.payload))
			acked := tok.WaitTimeout(3*time.Second) && tok.Error() == nil

			if tc.refused {
				if acked {
					t.Error("the seek was acknowledged: a 3.1.1 PUBACK can only say success")
				}
				select {
				case <-lost:
				case <-time.After(5 * time.Second):
					t.Error("a refused seek left the connection open")
				}
				return
			}
			if !acked {
				t.Errorf("a seek to %q was not acknowledged, and it is one a durable "+
					"session may always send", tc.payload)
			}
			select {
			case <-lost:
				t.Errorf("a seek to %q closed the connection, and it is never refused on "+
					"a durable session", tc.payload)
			case <-time.After(1200 * time.Millisecond):
			}
		})
	}
}

// RFC 0002 "Publishing", RFC 0003 "Retained messages" - the matrix's
// retained-publish row
//
// **A retained publish from a 3.1.1 client, with a store and without one.**
// Without, there is nowhere to keep it and the answer cannot be carried in
// a 3.1.1 `PUBACK`, so the connection closes - the same rule as every other
// refusal it cannot be told about. With one, it is an ordinary publish and
// a later subscriber is served the value.
func TestARetainedPublishFromA311ClientNeedsAStore(t *testing.T) {
	// **And at QoS 1 too, which is where the double-count was.** Both QoS
	// levels reach the same refusal by different paths, so both are driven:
	// a fix that makes one right and the other wrong is what happened here
	// once already.
	t.Run("counted once at QoS 1", func(t *testing.T) {
		h := startAdmitting311(t)
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatalf("pick a port: %v", err)
		}
		opsAddr := ln.Addr().String()
		_ = ln.Close()
		stop, err := h.B.ServeOperations(tcpOnly(opsAddr), 0, nil, nil)
		if err != nil {
			t.Fatalf("serve operations: %v", err)
		}
		t.Cleanup(func() { stop() })

		c, lost := legacy(t, h, "retain-once", true)
		c.Publish("bcast/keepme", 1, true, []byte("v")).WaitTimeout(3 * time.Second)
		select {
		case <-lost:
		case <-time.After(5 * time.Second):
			t.Fatal("the QoS 1 retained publish did not cost the connection")
		}
		time.Sleep(400 * time.Millisecond)

		resp, err := http.Get("http://" + opsAddr + "/v1/operations/refused")
		if err != nil {
			t.Fatalf("GET: %v", err)
		}
		defer resp.Body.Close()
		var out struct {
			Clients []struct {
				ClientID string `json:"client_id"`
				Count    uint64 `json:"count"`
			} `json:"clients"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			t.Fatalf("decode: %v", err)
		}
		if len(out.Clients) != 1 || out.Clients[0].Count != 1 {
			t.Errorf("one QoS 1 retained publish produced %+v, want one row counted once",
				out.Clients)
		}
	})

	t.Run("no store: the connection closes", func(t *testing.T) {
		h := startAdmitting311(t)
		c, lost := legacy(t, h, "retainer-a", true)
		tok := c.Publish("bcast/keepme", 1, true, []byte("v"))
		if tok.WaitTimeout(3*time.Second) && tok.Error() == nil {
			t.Error("a retained publish was acknowledged by a broker with nowhere to keep " +
				"it: the acknowledgement would say a value is kept that is not")
		}
		select {
		case <-lost:
		case <-time.After(5 * time.Second):
			t.Error("the connection stayed open")
		}
	})

	t.Run("a store: kept and served to the next subscriber", func(t *testing.T) {
		h := startRetaining(t, 0)
		c, lost := legacy(t, h, "retainer-b", true)
		tok := c.Publish("bcast/keepme", 1, true, []byte("v"))
		if !tok.WaitTimeout(4*time.Second) || tok.Error() != nil {
			t.Fatalf("a retained publish was refused by a broker with a store: %v",
				tok.Error())
		}
		select {
		case <-lost:
			t.Fatal("the connection was closed")
		case <-time.After(500 * time.Millisecond):
		}

		got := make(chan bool, 4)
		r, _ := legacy(t, h, "retainer-reader", true)
		if code := subscribeCode(t, r, "bcast/#", func(_ mqttv3.Client, m mqttv3.Message) {
			got <- m.Retained()
		}); code > 2 {
			t.Fatalf("subscribe refused 0x%02x", code)
		}
		select {
		case retained := <-got:
			if !retained {
				t.Error("the value arrived without the RETAIN flag, so a 3.1.1 reader " +
					"cannot tell it from something published just now")
			}
		case <-time.After(4 * time.Second):
			t.Fatal("a retained publish was accepted and the next subscriber was served " +
				"nothing, so it was kept nowhere")
		}
	})
}

// RFC 0003 "`append` - Durable consumers" - the matrix's QoS 0 row
//
// **A durable 3.1.1 consumer granted QoS 0 is at-most-once from the socket
// onward**, by RFC 0003's version-neutral rule: a position advances on the
// acknowledgement, and QoS 0 has none, so it advances as each record is
// written instead. The consumer is still durable - it resumes rather than
// re-reading - and what it gives up is the guarantee, not the position.
//
// Driven because the rule is stated as version-neutral, and a rule stated
// that way is one somebody will assume has an exception here.
func TestA311DurableConsumerAtQoS0KeepsItsPosition(t *testing.T) {
	admitting311(t)
	path := filepath.Join(t.TempDir(), "saguin.db")
	h := startDurableSQLite(t, path)
	p := connect(t, h, "producer", true, false)

	var mu sync.Mutex
	var got []string
	record := func(_ mqttv3.Client, m mqttv3.Message) {
		mu.Lock()
		got = append(got, string(m.Payload()))
		mu.Unlock()
	}
	take := func(c mqttv3.Client) {
		t.Helper()
		tok := c.Subscribe("events/#", 0, record)
		if !tok.WaitTimeout(5*time.Second) || tok.Error() != nil {
			t.Fatalf("subscribe: %v", tok.Error())
		}
	}

	c, _ := legacy(t, h, "qos0-durable", false)
	take(c)
	p.Pub(t, "events/orders/1", "first")
	deadline := time.After(5 * time.Second)
	for {
		mu.Lock()
		n := len(got)
		mu.Unlock()
		if n >= 1 {
			break
		}
		select {
		case <-deadline:
			t.Fatal("the QoS 0 consumer received nothing while connected")
		case <-time.After(100 * time.Millisecond):
		}
	}

	c.Disconnect(100)
	time.Sleep(600 * time.Millisecond)
	p.Pub(t, "events/orders/1", "second")
	time.Sleep(400 * time.Millisecond)

	// **It resumes rather than re-reading**, which is what says the position
	// is stored: a consumer starting again at the tail would miss "second",
	// and one with no position at all would re-read "first".
	//
	// **The handler is on before CONNECT** (legacyWithDefault): the resumed
	// session is sent "second" straight after its CONNACK, ahead of the
	// SUBSCRIBE below, and Paho v3 drops a message it has no route for -
	// at QoS 0, with the position already past it, so the test read the
	// instrument's loss as the broker's.
	c2, _ := legacyWithDefault(t, h, "qos0-durable", false, record)
	take(c2)
	deadline = time.After(6 * time.Second)
	for {
		mu.Lock()
		n := len(got)
		mu.Unlock()
		if n >= 2 {
			break
		}
		select {
		case <-deadline:
			mu.Lock()
			t.Fatalf("the QoS 0 durable consumer resumed and received %v, so it holds no "+
				"position", got)
		case <-time.After(100 * time.Millisecond):
		}
	}
	mu.Lock()
	defer mu.Unlock()
	if got[0] != "first" || got[1] != "second" {
		t.Errorf("received %v, want first then second - resumed, not re-read", got)
	}
}

// RFC 0003 "`append` - Durable consumers" - the matrix's QoS 0 row, across a
// restart
//
// **The position a 3.1.1 consumer at QoS 0 holds is a stored one.** The test
// above reconnects into a running broker, which answers from the live
// session and never consults the store: it passed with the QoS 0 path
// mutated to hold its position back. A restart leaves no live cursor, so
// what the consumer is served next comes from the stored position - on each
// provider, because each stores it its own way.
//
// **What comes first is the oracle, so no quiet period is needed.** A
// consumer is served in offset order, so one whose first record after the
// restart is "second" was not handed "first" again; "third", published after
// it, is the end marker that says the replay is complete.
func TestA311DurableConsumerAtQoS0StoresItsPositionAcrossARestart(t *testing.T) {
	admitting311(t)
	for _, provider := range []string{"memory", "sqlite"} {
		t.Run(provider, func(t *testing.T) {
			start, stop := func() *harness { return nil }, func(*harness) {}
			if provider == "memory" {
				// A memory channel keeps what a graceful stop snapshots.
				dir := t.TempDir()
				start = func() *harness { return startDurable(t, dir) }
				stop = func(h *harness) { h.Stop() }
			} else {
				// A clean DISCONNECT stores the position before the
				// connection closes (invariant 18), so a crash after it
				// keeps it.
				path := filepath.Join(t.TempDir(), "saguin.db")
				start = func() *harness { return startDurableSQLite(t, path) }
				stop = func(h *harness) { h.Crash() }
			}

			var mu sync.Mutex
			var got []string
			record := func(_ mqttv3.Client, m mqttv3.Message) {
				mu.Lock()
				got = append(got, string(m.Payload()))
				mu.Unlock()
			}
			take := func(c mqttv3.Client) {
				t.Helper()
				tok := c.Subscribe("events/#", 0, record)
				if !tok.WaitTimeout(5*time.Second) || tok.Error() != nil {
					t.Fatalf("subscribe: %v", tok.Error())
				}
			}
			// until waits for a record and returns everything received.
			until := func(last, what string) []string {
				t.Helper()
				for deadline := time.Now().Add(8 * time.Second); ; time.Sleep(10 * time.Millisecond) {
					mu.Lock()
					snap := append([]string(nil), got...)
					mu.Unlock()
					if slices.Contains(snap, last) {
						return snap
					}
					if time.Now().After(deadline) {
						t.Fatalf("%s: received %v", what, snap)
					}
				}
			}

			h := start()
			c, _ := legacy(t, h, "qos0-stored", false)
			take(c)
			connect(t, h, "producer", true, false).Pub(t, "events/orders/1", "first")
			until("first", "the QoS 0 consumer received nothing while connected")

			before := h.Disconnects.Snapshot("qos0-stored")
			c.Disconnect(100)
			sessionGoneAfter(t, h, "qos0-stored", before)
			stop(h)

			h2 := start()
			p := connect(t, h2, "producer", true, false)
			p.Pub(t, "events/orders/1", "second")
			mu.Lock()
			got = nil
			mu.Unlock()
			// The handler is on before CONNECT, for the reason
			// TestA311DurableConsumerAtQoS0KeepsItsPosition gives.
			c2, _ := legacyWithDefault(t, h2, "qos0-stored", false, record)
			take(c2)
			p.Pub(t, "events/orders/1", "third")

			served := until("third", "the end marker never reached the resumed consumer")
			if !slices.Equal(served, []string{"second", "third"}) {
				t.Errorf("after a restart the QoS 0 consumer was served %v, want [second "+
					"third]: anything before \"second\" means the stored position was "+
					"behind what the consumer had been written", served)
			}
		})
	}
}

// RFC 0003 "Last Will"
//
// **A 3.1.1 client's Will fires, and it fires immediately.** The item's
// analysis lists Will Delay Interval among the "smaller losses to decide
// rather than discover" - 3.1.1 has none, so there is nothing to delay
// with and the Will goes when the connection does.
//
// This is worth its own test rather than being assumed, because it is the
// case the whole feature is aimed at: a Tasmota-shaped device publishes a
// retained birth message and leaves a retained Will saying `offline`, and
// the availability pattern the fleet is monitored by is that Will arriving
// when the device drops. saguin holds delayed Wills itself rather than
// letting the substrate do it, so a path that assumed an MQTT 5 property
// would have broken exactly this.
func TestA311ClientsWillFiresWhenItDrops(t *testing.T) {
	// **Every client is denied `qos2`**, and that is forceCloseLegacy's doing
	// rather than anything this case is about: it drops the socket by
	// publishing at QoS 2 and relying on the refusal, which only a client
	// denied exactly-once meets. Allowed it, the publish succeeds, the client
	// stays connected, and the Will has no reason to fire.
	h := startRetaining(t, 0) // a store, so a retained Will is admitted
	denyFeatures(t, h, "    - broker: features\n      deny: [qos2]\n")

	got := make(chan string, 4)
	w := connect(t, h, "watcher", true, false)
	w.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
		got <- string(pr.Packet.Payload)
		return true, nil
	})
	w.Sub(t, "bcast/status/#", 1)

	opts := mqttv3.NewClientOptions().
		AddBroker("tcp://"+h.Addr).
		SetClientID("tasmota-will").
		SetProtocolVersion(4).
		SetCleanSession(true).
		SetAutoReconnect(false).
		SetWill("bcast/status/tasmota-will", "offline", 1, true)
	c := mqttv3.NewClient(opts)
	if tok := c.Connect(); !tok.WaitTimeout(5*time.Second) || tok.Error() != nil {
		t.Fatalf("a 3.1.1 client with a retained Will could not connect: %v", tok.Error())
	}

	// The birth message, as the firmware pattern sends it.
	if tok := c.Publish("bcast/status/tasmota-will", 1, true, []byte("online")); !tok.WaitTimeout(4*time.Second) ||
		tok.Error() != nil {
		t.Fatalf("the retained birth message was refused: %v", tok.Error())
	}
	select {
	case v := <-got:
		if v != "online" {
			t.Fatalf("the watcher received %q, want the birth message", v)
		}
	case <-time.After(4 * time.Second):
		t.Fatal("the birth message never arrived, so this test cannot say anything about " +
			"the Will")
	}

	// **Dropped rather than disconnected**, because a clean DISCONNECT
	// discards the Will by MQTT's own rule and would test nothing.
	if err := forceCloseLegacy(c); err != nil {
		t.Fatalf("could not drop the connection: %v", err)
	}

	select {
	case v := <-got:
		if v != "offline" {
			t.Fatalf("the Will payload was %q, want offline", v)
		}
		t.Log("the birth message arrived, the connection was dropped, and the Will " +
			"followed it - in that order, which is what says the Will fired rather " +
			"than something else arriving")
	case <-time.After(8 * time.Second):
		t.Fatal("a 3.1.1 client dropped its connection and its Will never fired: this is " +
			"the availability pattern the whole fleet is monitored by, and 3.1.1 has no " +
			"Will Delay Interval to be waiting on")
	}
}

// RFC 0003 "Moving a consumer's position: seek"
//
// **A 3.1.1 client reads the answer to its own seek** (phase two). Response
// Topic is an MQTT 5 property, so such a client had no way to ask for a
// reply: its seek applied and it learned nothing, or it was refused and its
// connection closed with nothing said. The reserved reply topic is where it
// reads the answer instead, and an MQTT 5 client that simply set no
// Response Topic gains the same.
//
// **The subscription is for routing, not for privacy.** The answer is
// written to the seeking client's socket rather than published, so what a
// subscriber here receives is its own replies and never anybody else's -
// which is what keeps a seek a private correction without putting a
// client-chosen id into a topic name.
func TestA311ClientReadsTheAnswerToItsOwnSeek(t *testing.T) {
	h := startAdmitting311(t)
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 3; i++ {
		p.Pub(t, "events/orders/1", fmt.Sprintf("r%d", i))
	}
	time.Sleep(300 * time.Millisecond)

	replies := make(chan string, 4)
	c, _ := legacy(t, h, "seek-reader", false) // durable, so a seek is allowed
	if code := subscribeCode(t, c, "$saguin/consumer/events/seek/reply",
		func(_ mqttv3.Client, m mqttv3.Message) { replies <- string(m.Payload()) }); code > 2 {
		t.Fatalf("a 3.1.1 client was refused the seek reply topic 0x%02x: it is the only "+
			"topic under $saguin/ a client may subscribe to", code)
	}
	if code := subscribeCode(t, c, "events/#", nil); code > 2 {
		t.Fatalf("subscribe refused 0x%02x", code)
	}

	if tok := c.Publish("$saguin/consumer/events/seek", 1, false, []byte("0")); !tok.WaitTimeout(4*time.Second) ||
		tok.Error() != nil {
		t.Fatalf("the seek was not accepted: %v", tok.Error())
	}

	select {
	case got := <-replies:
		t.Logf("the 3.1.1 client read its own seek answer: %q", got)
	case <-time.After(5 * time.Second):
		t.Fatal("a 3.1.1 client sought and read nothing: it cannot set a Response Topic, " +
			"so the reserved reply topic is the only way it learns what happened")
	}
}

// RFC 0003 "Moving a consumer's position: seek", RFC 0002 "Publishing"
//
// **The reply topic is subscribable and not publishable**, which is the
// whole of the exception it makes to the reserved space. It is not one of
// the topics saguin defines to be published to, so a publish here is
// refused exactly as any other invention under the prefix is - and a 3.1.1
// client, which cannot be told the code, has its connection closed.
//
// **And a Response Topic still wins**, so no client that set one behaves
// differently than it did before.
func TestTheSeekReplyTopicIsReadOnlyAndYieldsToAResponseTopic(t *testing.T) {
	// **A broker each**, because these cases publish into the same channel
	// and an MQTT 5 consumer with no stored position is served it from the
	// floor: sharing one, the third case read a record the second had left
	// behind and called it the wrong reply.
	t.Run("publishing to it is refused", func(t *testing.T) {
		h := startAdmitting311(t)
		five := connect(t, h, "publisher", true, false)
		ack, err := five.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/consumer/events/seek/reply", QoS: 1, Payload: []byte("x"),
		})
		if err == nil && ack != nil && ack.ReasonCode == 0 {
			t.Error("a client published to the seek reply topic and was answered Success: " +
				"it is not one of the topics saguin defines to be published to")
		}
	})

	// **A client that subscribed to nothing is sent nothing**, which is the
	// rule the first version of this got wrong. The reply is written to the
	// socket rather than published, so nothing else would stop it reaching a
	// consumer that never asked - and it arrived in the middle of the
	// records that consumer was reading. Naming a Response Topic *is* the
	// request; subscribing to the reserved topic is the other way of making
	// it, and a client that did neither has asked for no reply.
	t.Run("a client that did not subscribe is sent nothing", func(t *testing.T) {
		h := startAdmitting311(t)
		five := connect(t, h, "quiet-seeker", false, false)
		got := make(chan string, 8)
		five.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
			got <- pr.Packet.Topic
			return true, nil
		})
		five.Sub(t, "events/#", 1)
		if _, err := five.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/consumer/events/seek", QoS: 1, Payload: []byte("-1"),
		}); err != nil {
			t.Fatalf("seek: %v", err)
		}
		// A record after the seek, so the channel is proved live and the
		// assertion is about what did *not* arrive before it.
		p := connect(t, h, "prod-quiet", true, false)
		p.Pub(t, "events/orders/1", "after-the-seek")
		select {
		case topic := <-got:
			if strings.HasPrefix(topic, "$saguin/") {
				t.Errorf("a consumer that never subscribed to the reply topic was sent %q: "+
					"the reply is written to the socket, so nothing else stops it reaching "+
					"a client that asked for no reply at all", topic)
			}
		case <-time.After(4 * time.Second):
			t.Fatal("the consumer received nothing at all, so this proved nothing")
		}
	})

	t.Run("a Response Topic still wins", func(t *testing.T) {
		h := startAdmitting311(t)
		five := connect(t, h, "modern-seeker", false, false)
		got := make(chan string, 4)
		five.C.AddOnPublishReceived(func(pr paho.PublishReceived) (bool, error) {
			got <- pr.Packet.Topic
			return true, nil
		})
		five.Sub(t, "my/own/reply", 1)
		five.Sub(t, "events/#", 1)
		if _, err := five.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/consumer/events/seek", QoS: 1, Payload: []byte("-1"),
			Properties: &paho.PublishProperties{ResponseTopic: "my/own/reply"},
		}); err != nil {
			t.Fatalf("seek: %v", err)
		}
		select {
		case topic := <-got:
			if topic != "my/own/reply" {
				t.Errorf("the reply went to %q, and this client asked for my/own/reply - "+
					"a client that set a Response Topic must not start receiving its "+
					"answers somewhere else", topic)
			}
		case <-time.After(4 * time.Second):
			t.Fatal("the MQTT 5 seeker received no reply on the topic it asked for")
		}
	})
}

// RFC 0001 "Both protocols, and what each one gets"
//
// **A 3.1.1 client is never sent a server DISCONNECT**, because 3.1.1 does
// not define one: the packet type exists only client-to-server there, and a
// device reading `0xE0` is reading something its own specification has no
// meaning for.
//
// **This is a class test rather than a case test**, and it is written that
// way because the rule was applied three times and missed four. The
// refused publish and the QoS 2 publish converted the two sites they were
// about; `refuseRetain`, both
// packet-too-large paths and two of the three OnSubscribed guards went on
// encoding one. Measured at the wire before the fix: a retained publish to
// a broker with no store read `0xe0` before the close.
//
// Driven with a raw socket, because a client library is exactly what hides
// this - most of them drop an unknown packet without a word.
func TestNoServerDisconnectIsSentToA311Client(t *testing.T) {
	h := startAdmitting311(t) // no retained store, so the publish is refused

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	if _, err := conn.Write([]byte{
		0x10, 0x0e, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, 0x02, 0x00, 0x3c,
		0x00, 0x02, 'r', 'p',
	}); err != nil {
		t.Fatalf("connect: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(4 * time.Second))
	ack := make([]byte, 4)
	if _, err := io.ReadFull(conn, ack); err != nil || ack[3] != 0 {
		t.Fatalf("the 3.1.1 CONNECT was not accepted: %v %#x", err, ack)
	}

	// A retained publish this broker has nowhere to keep: refused, and the
	// refusal costs the connection.
	if _, err := conn.Write([]byte{
		0x33, 0x0c, 0x00, 0x07, 'b', 'c', 'a', 's', 't', '/', 'r', 0x00, 0x01, 'v',
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}

	_ = conn.SetReadDeadline(time.Now().Add(4 * time.Second))
	one := make([]byte, 1)
	switch _, err := io.ReadFull(conn, one); {
	case err != nil:
		t.Logf("the connection was closed with nothing sent: %v", err)
	default:
		t.Errorf("the 3.1.1 client was sent packet type %#x before the close. 3.1.1 has no "+
			"server-to-client DISCONNECT, so this is a byte its specification does not "+
			"define - every refusal it cannot be told about closes the socket and says "+
			"nothing", one[0])
	}
}

// RFC 0001 "Both protocols, and what each one gets"
//
// **The same rule where the ending is not a refusal.** A 3.1.1 socket must
// not be handed a packet its protocol does not define, and that is true of
// the endings nobody is at fault for as much as of the refusals: a session
// taken over is the client's own doing, and a shutdown is the operator's.
//
// **Both of these were the substrate's to fix, and it has.** They are here
// because they are saguin's promise whoever implements them - a claim about
// behaviour is a thing to run, not a thing to write once, and a substrate
// bump is exactly the event that would quietly take one back. The takeover
// site was also missed by saguin's own first sweep, which grepped for a
// pattern carrying a variable name; it is driven rather than read for that
// reason.
//
// **And neither may be counted.** The instruments report refusals. Folding
// in an ending nobody can act on would inflate the number an operator
// alerts on.
func TestAnEndingA311ClientDidNotCauseSendsItNoPacket(t *testing.T) {
	// dial completes a 3.1.1 CONNECT by hand, because the question is what
	// the broker puts on the wire and a client library would digest it.
	dial := func(t *testing.T, addr, id string) net.Conn {
		t.Helper()
		conn, err := net.Dial("tcp", addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		var body []byte
		body = append(body, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, 0x02, 0x00, 0x3c)
		body = append(body, byte(len(id)>>8), byte(len(id)))
		body = append(body, id...)
		if _, err := conn.Write(append([]byte{0x10, byte(len(body))}, body...)); err != nil {
			t.Fatalf("write: %v", err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(4 * time.Second))
		ack := make([]byte, 4)
		if _, err := io.ReadFull(conn, ack); err != nil || ack[3] != 0 {
			t.Fatalf("CONNECT refused: %v %#x", err, ack)
		}
		return conn
	}
	// nothingArrives reads the socket and requires the close to be silent.
	nothingArrives := func(t *testing.T, conn net.Conn, what string) {
		t.Helper()
		_ = conn.SetReadDeadline(time.Now().Add(4 * time.Second))
		one := make([]byte, 1)
		switch _, err := io.ReadFull(conn, one); {
		case err != nil:
			t.Logf("%s closed with nothing sent: %v", what, err)
		case one[0] == 0xE0:
			t.Errorf("%s was sent 0xE0, the server-to-client DISCONNECT. 3.1.1 has no "+
				"such packet - it defines DISCONNECT in the other direction only - so "+
				"this is a byte the client's own specification does not define", what)
		default:
			t.Errorf("%s was sent packet type %#x before the close", what, one[0])
		}
	}

	t.Run("a session taken over", func(t *testing.T) {
		h := startAdmitting311(t)
		opsAddr := refusedRouteOn(t, h)

		first := dial(t, h.Addr, "twin")
		defer first.Close()
		second := dial(t, h.Addr, "twin") // the same id takes the session over
		defer second.Close()

		nothingArrives(t, first, "the displaced 3.1.1 connection")

		if rows := refusedRows(t, opsAddr); len(rows) != 0 {
			t.Errorf("a session takeover was recorded as a refusal: %+v. These "+
				"instruments report connections the broker refused, and a client "+
				"reconnecting under its own id is not one", rows)
		}
	})

	t.Run("a broker shutting down", func(t *testing.T) {
		h := startAdmitting311(t)
		opsAddr := refusedRouteOn(t, h)

		conn := dial(t, h.Addr, "still-here")
		defer conn.Close()

		rows := refusedRows(t, opsAddr) // read before the route goes with the broker
		h.Stop()

		nothingArrives(t, conn, "a 3.1.1 client connected at shutdown")

		if len(rows) != 0 {
			t.Errorf("a connected client was recorded as a refusal before shutdown: "+
				"%+v", rows)
		}
	})
}

// RFC 0005 "The catalogue", "The /v1 routes"
//
// **A QoS 0 refusal that costs the connection is counted too.** The
// instruments count every connection the broker refused, and a retained
// publish with no store is exactly that at either QoS - `refuseRetain` disconnects whatever the QoS, because there
// is nowhere to keep the value either way.
//
// It used to be counted only above QoS 0, because the counting lived in the
// publish path's own branch and that branch is gated on a reply existing.
// So the most Tasmota-shaped flap there is - a retained birth message
// against a broker with no retained store - appeared in neither the counter
// nor the route, which is the fleet the route was built for.
func TestAQoS0RefusalThatCostsTheConnectionIsCounted(t *testing.T) {
	h := startAdmitting311(t) // no retained store

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	opsAddr := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(opsAddr), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(func() { stop() })

	c, lost := legacy(t, h, "qos0-birth", true)
	c.Publish("bcast/status/qos0-birth", 0, true, []byte("online")).
		WaitTimeout(3 * time.Second)
	select {
	case <-lost:
	case <-time.After(5 * time.Second):
		t.Fatal("a QoS 0 retained publish with no store did not cost the connection, so " +
			"there is nothing for the instruments to report")
	}
	time.Sleep(400 * time.Millisecond)

	resp, err := http.Get("http://" + opsAddr + "/v1/operations/refused")
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	defer resp.Body.Close()
	var out struct {
		Clients []struct {
			ClientID string `json:"client_id"`
			Reason   string `json:"reason"`
			Count    uint64 `json:"count"`
		} `json:"clients"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		t.Fatalf("decode: %v", err)
	}
	var named bool
	for _, r := range out.Clients {
		if r.ClientID == "qos0-birth" {
			named = true
			t.Logf("the route names it: %+v", r)
			// **Once, and the count is the assertion.** Fixing the QoS 0
			// case by moving the recording into the disconnect helper made
			// the QoS 1 case record twice: `refuseRetain` ends the
			// connection there, and the wrapped code it returns then
			// reaches the publish path's own legacy branch, which ends it
			// again. The stop is idempotent; the counting was not, and a
			// route row reading 2 for one event is a number an operator
			// alerts on.
			if r.Count != 1 {
				t.Errorf("one refusal was recorded %d times: the route's counts and the "+
					"counter's rate are read as numbers, and this is the refusal most "+
					"likely to be alerted on", r.Count)
			}
		}
	}
	if !named {
		t.Errorf("a 3.1.1 client was hung up on for a QoS 0 retained publish and the route "+
			"names nobody: %+v. A retained birth message against a broker with no "+
			"retained store is the flap this route exists for", out.Clients)
	}
}

// RFC 0005 "The /v1 routes"
//
// **An operator who closes the door needs to know who is still knocking.**
// `broker.mqtt.min_protocol_version: "5"` turns an older fleet away, and
// every refused device is told correctly in its own vocabulary - but until
// the fork carried a hook for it, nothing recorded *which* devices, because
// the substrate refuses the CONNECT before any saguin hook runs. The moment
// an operator makes that change is the moment they most want the list: it
// is how they find the devices nobody remembered to upgrade.
func TestDevicesTurnedAwayAtTheDoorAreNamed(t *testing.T) {
	brokertest.OnlyFive = true
	t.Cleanup(func() { brokertest.OnlyFive = false })
	h := startOn(t, "tcp")

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	opsAddr := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(opsAddr), 0, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	t.Cleanup(func() { stop() })

	// The same device knocks twice, as one in a reconnect loop does.
	knock := func(id string) {
		t.Helper()
		conn, err := net.Dial("tcp", h.Addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		defer conn.Close()
		var body []byte
		body = append(body, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, 0x02, 0x00, 0x3c)
		body = append(body, byte(len(id)>>8), byte(len(id)))
		body = append(body, id...)
		if _, err := conn.Write(append([]byte{0x10, byte(len(body))}, body...)); err != nil {
			t.Fatalf("write: %v", err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
		buf := make([]byte, 4)
		if _, err := io.ReadFull(conn, buf); err != nil {
			t.Fatalf("no CONNACK: %v", err)
		}
		if buf[3] != 0x01 {
			t.Fatalf("a 3.1.1 CONNECT against a broker set to MQTT 5 answered %#x, want "+
				"0x01 unacceptable protocol version", buf[3])
		}
	}
	knock("tasmota-old")
	knock("tasmota-old")
	knock("arduino-older")
	time.Sleep(400 * time.Millisecond)

	resp, err := http.Get("http://" + opsAddr + "/v1/operations/refused")
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	defer resp.Body.Close()
	var out struct {
		Clients []struct {
			ClientID string `json:"client_id"`
			Reason   string `json:"reason"`
			Count    uint64 `json:"count"`
		} `json:"clients"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(out.Clients) != 2 {
		t.Fatalf("two devices were turned away at the door and the route lists %d: %+v. "+
			"The refusal happens before any saguin hook runs, so without the substrate "+
			"telling it, the broker never learns which device it was", len(out.Clients), out.Clients)
	}
	// **Worst first**, so the device in the tightest loop is the one an
	// operator reads.
	if out.Clients[0].ClientID != "tasmota-old" || out.Clients[0].Count != 2 {
		t.Errorf("the first row is %+v, want tasmota-old counted twice", out.Clients[0])
	}
	if out.Clients[0].Reason == "" {
		t.Error("the row says nothing about why the device was turned away")
	}
	t.Logf("the route names them: %+v", out.Clients)
}

// RFC 0005 "The /v1 routes", invariant 13
//
// **The record keeps a refused client's user name bounded, as it does its
// client id.** The user name arrives in the CONNECT from whoever connected,
// up to 65,535 bytes, and the record outlives the connection. Measured on
// the binary before this: a thousand 3.1.1 CONNECTs refused for their
// version, each with a 65,000-byte user name, held all thousand whole - the
// process grew from 13.6 MB to 110.6 MB, and one read of the route was 6.5 MB.
//
// Both ways a user name reaches the record, since each passed it
// separately: the engine's refusal hook, which reads the packet, and saguin's
// own refusals, which read the client.
func TestTheRefusalRecordBoundsTheUserNameItKeeps(t *testing.T) {
	long := strings.Repeat("u", 5000)
	bounded := func(t *testing.T, opsAddr, id string) {
		t.Helper()
		row, ok := refusalRecord(t, opsAddr)[id]
		if !ok {
			t.Fatalf("%s was refused and is not in the record, so this bounded nothing", id)
		}
		if !strings.HasPrefix(row.User, "uuuu") {
			t.Fatalf("the record carries the user name %.40q, not the one sent", row.User)
		}
		if len(row.User) > limits.MaxTopicLength+64 {
			t.Errorf("the record keeps a %d-byte user name for %s, want at most %d: a stranger's "+
				"string held after the connection is gone", len(row.User), id, limits.MaxTopicLength+64)
		}
	}

	t.Run("refused by the engine, before a saguin hook runs", func(t *testing.T) {
		brokertest.OnlyFive = true
		t.Cleanup(func() { brokertest.OnlyFive = false })
		h := startOn(t, "tcp")
		opsAddr := refusedRouteOn(t, h)
		if _, code := refusalDial(t, h, refusalConnect(4, "long-user-engine", long, "pw", nil)); code != 0x01 {
			t.Fatalf("a 3.1.1 CONNECT against a broker set to MQTT 5 answered %#x, want 0x01", code)
		}
		time.Sleep(200 * time.Millisecond)
		bounded(t, opsAddr, "long-user-engine")
	})

	t.Run("refused by saguin's password check", func(t *testing.T) {
		h := startAdmitting311(t)
		requirePasswords(t, h)
		opsAddr := refusedRouteOn(t, h)
		if _, code := refusalDial(t, h, refusalConnect(5, "long-user-auth", long, "wrong", nil)); code != 0x86 {
			t.Fatalf("a wrong password answered %#x, want 0x86", code)
		}
		time.Sleep(200 * time.Millisecond)
		bounded(t, opsAddr, "long-user-auth")
	})
}

// RFC 0005 "The catalogue" and "The /v1 routes"
//
// **A refusal is counted whatever protocol the client speaks, and once.**
// The instruments answer which devices this broker turned away and why, and
// that question does not change with how well the device was answered. They
// used to count MQTT 5 only where the engine refused the CONNECT: a wrong
// password, saguin's own CONNECT checks and a connection ended for a refusal
// were counted below MQTT 5 alone, so the same broker answered the same
// question two ways depending on the device - which is what made an
// instrument named for older clients also carry newer ones.
//
// One of each, on one broker with a password file and no retained store,
// and a 3.1.1 wrong password beside them because that refusal is written by
// saguin and also reaches the engine, which is where a second count would
// come from.
func TestARefusalIsCountedOnceWhateverTheProtocol(t *testing.T) {
	h := startAdmitting311(t) // no retained store
	requirePasswords(t, h)
	opsAddr := refusedRouteOn(t, h)

	authMethod := []byte{0x15, 0x00, 0x05, 'S', 'C', 'R', 'A', 'M'}
	for _, tc := range []struct {
		id      string
		connect []byte
		want    byte
	}{
		{"five-bad-password", refusalConnect(5, "five-bad-password", "real", "wrong", nil), 0x86},
		{"old-bad-password", refusalConnect(4, "old-bad-password", "real", "wrong", nil), 0x04},
		{"five-auth-method", refusalConnect(5, "five-auth-method", "real", "hunter2", authMethod), 0x8C},
	} {
		if _, code := refusalDial(t, h, tc.connect); code != tc.want {
			t.Fatalf("%s answered %#x, want %#x", tc.id, code, tc.want)
		}
	}

	// Ended after connecting: an MQTT 5 retained publish, with no store to
	// keep it, is answered with a DISCONNECT.
	conn, code := refusalDial(t, h, refusalConnect(5, "five-retained", "real", "hunter2", nil))
	if code != 0x00 {
		t.Fatalf("the good credential answered %#x", code)
	}
	publish := []byte{0x31, 0x0d, 0x00, 0x0a, 'b', 'c', 'a', 's', 't', '/', 'f', 'i', 'v', 'e', 0x00, 'o', 'n'}
	publish[1] = byte(len(publish) - 2)
	if _, err := conn.Write(publish); err != nil {
		t.Fatalf("publish: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	got, _ := io.ReadAll(conn)
	if len(got) == 0 || got[0] != 0xE0 {
		t.Fatalf("a retained publish with no store was answered % x, want a DISCONNECT", got)
	}
	time.Sleep(300 * time.Millisecond)

	rows := refusalRecord(t, opsAddr)
	for _, id := range []string{"five-bad-password", "old-bad-password", "five-auth-method", "five-retained"} {
		row, ok := rows[id]
		switch {
		case !ok:
			t.Errorf("%s was refused and the route does not name it: %+v", id, rows)
		case row.Count != 1:
			t.Errorf("%s was refused once and recorded %d times", id, row.Count)
		case row.Reason == "":
			t.Errorf("%s is recorded with no reason", id)
		}
	}

	resp, err := http.Get("http://" + opsAddr + "/metrics")
	if err != nil {
		t.Fatalf("GET /metrics: %v", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	var total float64
	var series int
	for _, line := range strings.Split(string(body), "\n") {
		if !strings.HasPrefix(line, "saguin_connections_refused_total{") {
			continue
		}
		series++
		var v float64
		if _, err := fmt.Sscan(line[strings.LastIndex(line, " ")+1:], &v); err != nil {
			t.Fatalf("reading %q: %v", line, err)
		}
		total += v
	}
	if series == 0 {
		t.Fatal("saguin_connections_refused_total has no series after four refusals")
	}
	if total != 4 {
		t.Errorf("four refusals, one per client, and saguin_connections_refused_total sums to %v",
			total)
	}
}

// RFC 0005 "What the box moved"
//
// **The four counters an operator draws a throughput from**, and the only
// ones in the catalogue that are about the wire rather than about a record
// saguin decided to keep. They are read from counters the substrate
// maintains as it reads and writes sockets, so this test is the one thing
// that says those really are the numbers being read: everything else about
// them is a claim that a field is wired to a name.
//
// Driven over a socket rather than in process, because bytes on a wire is
// what they count and an in-process publish crosses none.
func TestWhatCrossedTheWireIsCounted(t *testing.T) {
	h := start(t)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	// **Every scrape recomputed, which a deployment never does.** The
	// catalogue is answered from the previous one for a whole minute
	// otherwise, so the second reading below would be the first reading
	// again - and four counters that had not moved would look exactly like
	// four counters that cannot. That trap is what this test is about, so
	// it must not be the thing the test walks into.
	stop, err := h.B.ServeOperations(tcpOnly(ops), time.Nanosecond, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	defer stop()

	// One number per name, from a scrape read as a scraper reads it.
	scrape := func(t *testing.T) map[string]float64 {
		t.Helper()
		resp, err := http.Get("http://" + ops + "/metrics")
		if err != nil {
			t.Fatalf("scrape: %v", err)
		}
		defer resp.Body.Close()
		raw, err := io.ReadAll(resp.Body)
		if err != nil {
			t.Fatalf("read the scrape: %v", err)
		}
		out := map[string]float64{}
		for _, line := range strings.Split(string(raw), "\n") {
			if strings.HasPrefix(line, "#") {
				continue
			}
			f := strings.Fields(line)
			if len(f) != 2 || strings.Contains(f[0], "{") {
				continue
			}
			v, err := strconv.ParseFloat(f[1], 64)
			if err != nil {
				continue
			}
			out[f[0]] = v
		}
		if len(out) == 0 {
			t.Fatalf("the scrape carried no unlabelled series at all:\n%s", raw)
		}
		return out
	}

	// **Two subscribers, so that arrivals and deliveries are different
	// numbers.** With one, every publish is one delivery and the two
	// counters agree - and a scrape that read the same field for both
	// would pass every check below. Two readers makes the read side twice
	// the write side, which is a difference a wrong wiring cannot fake.
	const sent = 20
	subs := []*client{
		connect(t, h, "reader-a", true, false),
		connect(t, h, "reader-b", true, false),
	}
	for _, sub := range subs {
		sub.Sub(t, "events/#", 1)
	}
	pub := connect(t, h, "writer", true, false)
	for i := range sent {
		pub.Pub(t, "events/wire", fmt.Sprintf("payload-%02d", i))
	}
	for _, sub := range subs {
		for range sent {
			if _, ok := sub.Await(t, 5*time.Second); !ok {
				t.Fatalf("only %d of %d deliveries reached a subscriber, so the "+
					"counters below are about a run that did not finish",
					sub.Count(), sent)
			}
		}
	}

	got := scrape(t)

	if n := got["saguin_publishes_received_total"]; n != sent {
		t.Errorf("the broker counts %v publishes arriving, want exactly %d", n, sent)
	}
	// **Twice, and exactly twice.** This is the assertion that tells the
	// read side from the write side: a delivery counter reading the
	// arrivals field would say 20 here, which is the shape of the mistake
	// worth catching, and it is the only reason there are two subscribers.
	if n := got["saguin_deliveries_sent_total"]; n != 2*sent {
		t.Errorf("the broker counts %v deliveries going out for %d publishes to "+
			"two subscribers, want %d - this is the read side, and nothing else "+
			"in the catalogue counts it", n, sent, 2*sent)
	}
	// Bytes are everything on the wire, so the floor is what the payloads
	// alone come to: a real count is larger, and one that is smaller is
	// counting something other than bytes.
	floor := float64(sent * len("payload-00"))
	if n := got["saguin_bytes_received_total"]; n <= floor {
		t.Errorf("the broker counts %v bytes read, and the payloads alone come to "+
			"%v before a single header", n, floor)
	}
	if n := got["saguin_bytes_sent_total"]; n <= floor {
		t.Errorf("the broker counts %v bytes written, and the payloads alone come "+
			"to %v", n, floor)
	}
	// **And the two are not the same number**, which no floor can say. Each
	// payload crosses in once and out twice here, so the write side must
	// exceed the read side by more than the acknowledgements going the
	// other way - and a scrape reading one field for both would report them
	// equal, which is the shape of the mistake worth catching.
	if in, out := got["saguin_bytes_received_total"], got["saguin_bytes_sent_total"]; out <= in {
		t.Errorf("the broker counts %v bytes in and %v out, with every payload "+
			"delivered to two subscribers: the two are the same counter", in, out)
	}

	// **And they move on**, which is what tells a counter from a constant.
	// A rate over a number that never changes is a flat line at zero, and
	// it reads exactly like a quiet broker.
	before := got
	for i := range sent {
		pub.Pub(t, "events/wire", fmt.Sprintf("again-%02d", i))
	}
	for _, sub := range subs {
		for range sent {
			if _, ok := sub.Await(t, 5*time.Second); !ok {
				t.Fatal("the second round did not arrive")
			}
		}
	}
	after := scrape(t)
	for _, name := range []string{
		"saguin_bytes_received_total", "saguin_bytes_sent_total",
		"saguin_publishes_received_total", "saguin_deliveries_sent_total",
	} {
		if after[name] <= before[name] {
			t.Errorf("%s was %v and is %v after twenty more publishes: it is not "+
				"advancing, so every rate drawn from it is a flat zero",
				name, before[name], after[name])
		}
	}
}

// **What arrives is counted, and what the broker injects is not**
// (RFC 0005 saguin_publishes_received_total). The engine counted every
// injected PUBLISH as received, so a queue's offer to its worker counted a
// second time: five jobs sent read as ten received against five published,
// a queue working perfectly looking like half of what was sent landing.
// Two arms, each with nothing else arriving: a queue whose five jobs are all
// taken by a worker, which must read five; and an inbound bridge carrying
// three records from an upstream, which arrived over its connection and
// must read three.
func TestWhatArrivesIsCountedAndWhatTheBrokerOffersIsNot(t *testing.T) {
	received := func(t *testing.T, h *harness) float64 {
		t.Helper()
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		if err != nil {
			t.Fatalf("pick a port: %v", err)
		}
		ops := ln.Addr().String()
		_ = ln.Close()
		stop, err := h.B.ServeOperations(tcpOnly(ops), time.Nanosecond, nil, nil)
		if err != nil {
			t.Fatalf("serve operations: %v", err)
		}
		defer stop()
		resp, err := http.Get("http://" + ops + "/metrics")
		if err != nil {
			t.Fatalf("scrape: %v", err)
		}
		defer resp.Body.Close()
		raw, err := io.ReadAll(resp.Body)
		if err != nil {
			t.Fatalf("read the scrape: %v", err)
		}
		for _, line := range strings.Split(string(raw), "\n") {
			if f := strings.Fields(line); len(f) == 2 && f[0] == "saguin_publishes_received_total" {
				v, err := strconv.ParseFloat(f[1], 64)
				if err != nil {
					t.Fatalf("%q: %v", line, err)
				}
				return v
			}
		}
		t.Fatalf("the scrape has no saguin_publishes_received_total:\n%s", raw)
		return 0
	}

	t.Run("a queue's jobs, offered to a worker", func(t *testing.T) {
		h := start(t)
		w := connect(t, h, "worker-1", true, false)
		w.Sub(t, "$saguin/queue/jobs", 1)
		subscribed(t, w.C)
		p := connect(t, h, "producer", true, false)
		const sent = 5
		for i := range sent {
			p.Pub(t, "jobs/build", fmt.Sprintf("job-%d", i))
		}
		for i := range sent {
			if _, ok := w.Await(t, 3*time.Second); !ok {
				t.Fatalf("the worker was offered %d of %d jobs, so the count below is about a "+
					"run that did not finish", i, sent)
			}
		}
		if got := received(t, h); got != sent {
			t.Errorf("%d jobs sent and all offered to a worker read %v received, want %d: the "+
				"offers are counted as arrivals", sent, got, sent)
		}
	})

	t.Run("records an inbound bridge carried in", func(t *testing.T) {
		upstream, upstreamAddr := startUpstream(t)
		h := start(t)
		cfg := bridgeConfig(t, upstreamAddr)
		br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits,
			slog.New(slog.NewTextHandler(io.Discard, nil)), nil)
		ctx, cancel := context.WithCancel(context.Background())
		done := make(chan struct{})
		go func() { defer close(done); _ = br.Run(ctx) }()
		t.Cleanup(func() {
			cancel()
			select {
			case <-done:
			case <-time.After(5 * time.Second):
				t.Error("the bridge did not stop")
			}
		})
		reader := connect(t, h, "reader", true, false)
		reader.Sub(t, "events/#", 1)
		waitForBridge(t, upstream, cfg.ClientID)

		prod := dialUpstream(t, upstreamAddr, "vessel-sensor")
		const carried = 3
		for i := range carried {
			ack, err := prod.Publish(context.Background(), &paho.Publish{
				Topic: "fleet/vessel-07/telemetry/hold/psi", QoS: 1, Payload: fmt.Appendf(nil, "reading-%d", i),
			})
			if err != nil || ack == nil || ack.ReasonCode > 1 {
				t.Fatalf("publish %d upstream: %v", i, err)
			}
		}
		if got := collect(t, reader, carried, 5*time.Second); len(got) != carried {
			t.Fatalf("%d of %d records crossed the bridge, so the count below is about a run "+
				"that did not finish", len(got), carried)
		}
		if got := received(t, h); got != carried {
			t.Errorf("%d records carried in by the bridge read %v received, want %d: they "+
				"arrived over its connection", carried, got, carried)
		}
	})
}

// RFC 0005 "saguin_sessions_offline"
//
// **The question saguin_connections cannot answer.** Three hundred devices
// with two hundred connected is either a rota or a hundred that have
// stopped calling, and a connection count alone reads the same either way.
//
// Derived rather than read, because the substrate derives it inside the
// `$SYS` tree saguin silences - so this is the test that says the
// arithmetic is right, and it is driven over a socket because what it
// counts is sessions the substrate is holding.
func TestASessionNobodyIsConnectedToIsCounted(t *testing.T) {
	h := start(t)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(ops), time.Nanosecond, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	defer stop()

	read := func(t *testing.T, name string) float64 {
		t.Helper()
		resp, err := http.Get("http://" + ops + "/metrics")
		if err != nil {
			t.Fatalf("scrape: %v", err)
		}
		defer resp.Body.Close()
		raw, err := io.ReadAll(resp.Body)
		if err != nil {
			t.Fatalf("read the scrape: %v", err)
		}
		for _, line := range strings.Split(string(raw), "\n") {
			if v, ok := strings.CutPrefix(line, name+" "); ok {
				f, err := strconv.ParseFloat(strings.TrimSpace(v), 64)
				if err != nil {
					t.Fatalf("%s is not a number: %q", name, v)
				}
				return f
			}
		}
		t.Fatalf("the scrape does not carry %s at all\n%s", name, raw)
		return 0
	}

	// **A session that outlives its connection and one that does not, so
	// the two are told apart.** Counting every disconnected client would
	// make this a number about clients that have gone rather than sessions
	// that are held, and the second one is what proves the difference.
	//
	// **It is the Session Expiry Interval that decides, not clean start**,
	// which is why the second uses connectExpiring rather than passing
	// cleanStart. Under MQTT 5 a clean start says what to do with a session
	// that already exists; the expiry says whether this one survives the
	// connection. connect() gives every client an hour, so two clients
	// connected the ordinary way both leave a session behind - which is
	// correct, and is what this test asserted wrongly before it was run.
	durable := connect(t, h, "keeps-its-session", false, false)
	fleeting := connectExpiring(t, h, "brings-nothing-back")
	// The counter this shape owes: both really connected, so what changes
	// below is a disconnect rather than a client that never arrived.
	if n := read(t, "saguin_connections"); n < 2 {
		t.Fatalf("the broker reports %v connections with two clients on it", n)
	}
	if n := read(t, "saguin_sessions_offline"); n != 0 {
		t.Fatalf("%v sessions are already offline with both clients connected", n)
	}

	durable.Close()
	fleeting.Close()
	// A disconnect is one-way, so nothing comes back to say the broker has
	// finished with the session. Poll the number this test is about rather
	// than sleeping a guess.
	deadline := time.Now().Add(5 * time.Second)
	for read(t, "saguin_connections") != 0 {
		if time.Now().After(deadline) {
			t.Fatalf("the connection count is still %v five seconds after both "+
				"clients closed", read(t, "saguin_connections"))
		}
		time.Sleep(20 * time.Millisecond)
	}

	// One, not two: the clean session was discarded when it disconnected
	// and is not a session anybody is coming back for.
	if n := read(t, "saguin_sessions_offline"); n != 1 {
		t.Errorf("the broker reports %v sessions offline after one client with an "+
			"hour's session expiry and one with none disconnected, want 1: a session "+
			"that expired with its connection is not one anybody is coming back for", n)
	}
}

// RFC 0005 "saguin_connections_by_protocol"
//
// **The split is of the connections, so it sums to them.** It did not: the
// substrate keeps an inline client of its own in the client table - the one
// it publishes on its own behalf with - and the walk that counts protocol
// versions counted it. A broker with a single MQTT 5 subscriber reported
// one connection and two clients speaking MQTT 5, and the panel drawn from
// the split was over by one on every saguin there has been.
//
// It is one client, so the error is small and constant, which is what made
// it survive: a dashboard reading three hundred against three hundred and
// one has nothing about it that looks wrong.
//
// Written as the sum rather than as "do not count the inline client",
// because the sum is the property an operator relies on and it holds
// against whatever the substrate puts in that table next.
func TestTheProtocolSplitSumsToTheConnectionCount(t *testing.T) {
	h := start(t)

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("pick a port: %v", err)
	}
	ops := ln.Addr().String()
	_ = ln.Close()
	stop, err := h.B.ServeOperations(tcpOnly(ops), time.Nanosecond, nil, nil)
	if err != nil {
		t.Fatalf("serve operations: %v", err)
	}
	defer stop()

	clients := []*client{
		connect(t, h, "five-a", true, false),
		connect(t, h, "five-b", true, false),
	}
	defer func() {
		for _, c := range clients {
			c.Close()
		}
	}()

	resp, err := http.Get("http://" + ops + "/metrics")
	if err != nil {
		t.Fatalf("scrape: %v", err)
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read the scrape: %v", err)
	}

	var connections, split float64
	for _, line := range strings.Split(string(raw), "\n") {
		if v, ok := strings.CutPrefix(line, "saguin_connections "); ok {
			if connections, err = strconv.ParseFloat(strings.TrimSpace(v), 64); err != nil {
				t.Fatalf("saguin_connections is not a number: %q", v)
			}
		}
		if strings.HasPrefix(line, "saguin_connections_by_protocol{") {
			f := strings.Fields(line)
			v, err := strconv.ParseFloat(f[len(f)-1], 64)
			if err != nil {
				t.Fatalf("a protocol count is not a number: %q", line)
			}
			split += v
		}
	}

	// The counter this shape owes: two clients really are on it, so an
	// agreement below is between two numbers that had something to count.
	if connections != float64(len(clients)) {
		t.Fatalf("the broker reports %v connections with %d clients on it",
			connections, len(clients))
	}
	if split != connections {
		t.Errorf("the protocol split comes to %v and the broker reports %v "+
			"connections. They are the same clients counted twice over, so a "+
			"difference is one of the walks counting something that is not a "+
			"connection\n%s", split, connections, raw)
	}
}

// **Hanging up a client, driven the way an operator would** (RFC 0002
// "Hanging up a client").
//
// **What it is for is the second half of withdrawing access**, never the
// whole of it: the device comes back with whatever the two files say then.
// The signal that re-reads them is tested in cmd/saguin, where the signal
// lives; what is tested here is the hang-up itself.
//
// **What is asserted is the connection ending and the session surviving**,
// because those are two different things and only one of them is wanted. A
// verb that took the session with it would drop a durable consumer's stored
// position, and the next connection would start wherever the channel's
// `start` says - replaying or skipping. So the victim here holds a position
// first, and resumes on it afterwards.
func TestAnOperatorHangsUpAClientAndItsSessionSurvives(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  on-call:
    - broker: sessions
      allow: [disconnect]
  reader:
    - channel: events
      allow: [read]
  everyday:
    - channel: events
      allow: [write, read]
users:
  oncall: [on-call]
  device: [reader]
  # The harness's own clients carry no user name, and an anonymous
  # identity is the empty string. Without this the producer below is
  # refused and the test fails for a reason that is not its own.
  "*": [everyday]
`)

	// **Two records now and the third after the hang-up.** Paho
	// acknowledges on receipt, so a client left to read "two of three" has
	// in fact acknowledged all three and its position is at the end - the
	// resume below would then find nothing whether the session survived or
	// not, and pass for the wrong reason. A record published while the
	// client is away is the assertion: a session that survived is handed it,
	// and one that did not starts at the channel's floor and is handed r-1.
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 2; i++ {
		p.Pub(t, fmt.Sprintf("events/%d", i), fmt.Sprintf("r-%d", i))
	}

	// The victim: a durable session that reads two of the three.
	brokertest.DialUsername = "device"
	victim := connect(t, h, "victim", false, false)
	brokertest.DialUsername = ""
	victim.Sub(t, "events/#", 1)
	for i := 1; i <= 2; i++ {
		if r, ok := victim.Await(t, 3*time.Second); !ok || r.Payload != fmt.Sprintf("r-%d", i) {
			t.Fatalf("before the disconnect: record %d is %+v", i, r)
		}
	}
	if extra, more := victim.Await(t, 300*time.Millisecond); more {
		t.Fatalf("a third record arrived before it was published: %q", extra.Payload)
	}
	// A position is stored on the broker's tick rather than on the delivery
	// path, so the resume below is about what was stored rather than about
	// how promptly it was.
	time.Sleep(500 * time.Millisecond)

	operator := dialWithUser(t, h, "operator", "oncall")
	code, said := askDisconnect(t, operator, "victim")
	if code != 0x00 {
		t.Fatalf("hanging up a connected client was answered 0x%02X, want 0x00", code)
	}
	if said != "hung-up" {
		t.Fatalf("the reply was %q, want hung-up: an operator cannot tell a client that "+
			"was hung up from an id that named nobody", said)
	}

	// **And the victim is told why.** `0x98` is MQTT 5's Administrative
	// action, and it is the difference between a device whose operator hung
	// it up and one whose link broke: a client that retries on the second
	// and gives up on the first cannot tell them apart without it.
	select {
	case d := <-victim.Gone:
		if d.ReasonCode != 0x98 {
			t.Errorf("the client was disconnected with 0x%02X, want 0x98 Administrative "+
				"action", d.ReasonCode)
		}
	case <-time.After(5 * time.Second):
		t.Error("no DISCONNECT reached the client, so it learns only that its socket " +
			"closed and cannot tell an operator's action from a broken link")
	}

	// **The connection ends**, which is the whole verb. Asked of the broker
	// rather than of the victim's socket: the client library notices a
	// closed connection when it next reads, and what this is about is what
	// the broker did.
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		if cl, ok := h.Srv.Clients.Get("victim"); !ok || cl.Closed() {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if cl, ok := h.Srv.Clients.Get("victim"); ok && !cl.Closed() {
		t.Fatal("the client is still connected after an authorized disconnect")
	}

	// **And the session is untouched.** A record published while it was away,
	// then a reconnect: it is handed that record and not the two it had
	// already read, so its position survived the hang-up.
	p.Pub(t, "events/3", "r-3")

	brokertest.DialUsername = "device"
	back := connect(t, h, "victim", false, false)
	brokertest.DialUsername = ""
	back.Sub(t, "events/#", 1)
	r, ok := back.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("after reconnecting, the client received nothing: its position was lost " +
			"forwards, so the records it had not read are gone")
	}
	if r.Payload != "r-3" {
		t.Errorf("it resumed at %q, want r-3 - a disconnect that moves a consumer's "+
			"position replays or skips work, which is the cost this verb exists not to "+
			"have", r.Payload)
	}
}

// **The refusal, and the property the rule kind exists for.** A role holding
// every verb on every channel and the widest topic rule there is cannot hang
// anybody up: nothing written as a filter reaches a `broker:` rule.
//
// The ACL's filter matcher has no `$` exclusion - `#` matches
// `$saguin/anything` - so a control topic spelled into an acl_file would
// have been granted by `topic: "#"`, which is in RFC 0002's own example
// role. That is why this verb is not gated by a topic.
func TestOnlyABrokerRuleCanHangAClientUp(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  everything:
    - channel: events
      allow: [write, read, seek]
    - channel: state
      allow: [write, read, delete]
    - channel: jobs
      allow: [write, consume]
    - topic: "#"
      allow: [write, read]
users:
  greedy: [everything]
`)

	victim := connect(t, h, "victim", true, false)
	_ = victim

	greedy := dialWithUser(t, h, "greedy", "greedy")
	ack, err := greedy.C.Publish(context.Background(), &paho.Publish{
		Topic: "$saguin/sessions/disconnect", QoS: 1, Payload: []byte("victim"),
	})
	if ack == nil {
		t.Fatalf("no acknowledgement: %v", err)
	}
	if ack.ReasonCode != 0x87 {
		t.Errorf("a role with every channel verb and topic: \"#\" was answered 0x%02X on a "+
			"disconnect, want 0x87 - a filter has reached a rule kind no filter is "+
			"supposed to reach", ack.ReasonCode)
	}
	if cl, ok := h.Srv.Clients.Get("victim"); !ok || cl.Closed() {
		t.Error("the client was hung up on by a role that may not do it")
	}
}

// **An id nothing is connected under is answered out loud**, because
// otherwise "that device disconnected an hour ago" and "you have misspelled
// the id" are the same packet - and the second is the one an operator
// actually sends.
//
// A held session with no socket behind it is the case worth having: the
// substrate keeps a durable session in the same table until it expires, so
// an id read off a dashboard may well be there with nothing to hang up.
func TestADisconnectSaysWhenItFoundNobody(t *testing.T) {
	h := start(t)
	writeACL(t, h, "roles:\n  on-call:\n    - broker: sessions\n      allow: [disconnect]\n"+
		"users:\n  oncall: [on-call]\n")

	// A durable session, then gone: the id is in the table and closed.
	held := connect(t, h, "held", false, false)
	_ = held.C.Disconnect(&paho.Disconnect{ReasonCode: 0})
	// **Proved rather than assumed.** The case is "a session in the table
	// with no socket behind it", and a session that had ended instead would
	// answer 0x10 for the other reason - the test would pass while checking
	// nothing it claims to. The harness connects with an hour's expiry, so
	// this session outlives its connection.
	heldDeadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(heldDeadline) {
		if cl, ok := h.Srv.Clients.Get("held"); ok && cl.Closed() {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if cl, ok := h.Srv.Clients.Get("held"); !ok || !cl.Closed() {
		t.Fatalf("the session was not held with its connection closed (present=%v), so "+
			"the case below is not the one it says it is", ok)
	}

	operator := dialWithUser(t, h, "operator", "oncall")
	for name, id := range map[string]string{
		"an id nothing was ever connected under": "never-existed",
		"a session held with nothing connected":  "held",
	} {
		t.Run(name, func(t *testing.T) {
			code, said := askDisconnect(t, operator, id)
			if code != 0x00 {
				t.Fatalf("a disconnect naming %q was refused 0x%02X: it is a request the "+
					"broker took and found nothing for, not one it turned down", id, code)
			}
			if said != "no-such-client" {
				t.Errorf("a disconnect naming %q replied %q, want no-such-client: an "+
					"operator cannot tell a device that has gone from an id they typed "+
					"wrong", id, said)
			}
		})
	}

	t.Run("a request with nowhere to answer is refused", func(t *testing.T) {
		// **Refused rather than acted on silently**, and it is the point
		// read's rule rather than a new one: the outcome that matters is a
		// payload, so a request naming no reply topic is one whose answer
		// would be thrown away. Acting on it would hang a client up and
		// tell nobody.
		ack, err := operator.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/sessions/disconnect", QoS: 1, Payload: []byte("victim"),
		})
		if ack == nil {
			t.Fatalf("no acknowledgement: %v", err)
		}
		if ack.ReasonCode != 0x83 {
			t.Errorf("a disconnect naming no Response Topic was answered 0x%02X, want "+
				"0x83", ack.ReasonCode)
		}
	})

	t.Run("an empty payload names nobody at all", func(t *testing.T) {
		ack, err := operator.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/sessions/disconnect", QoS: 1, Payload: nil,
			Properties: &paho.PublishProperties{ResponseTopic: "ops/reply"},
		})
		if ack == nil {
			t.Fatalf("no acknowledgement: %v", err)
		}
		if ack.ReasonCode != 0x83 {
			t.Errorf("a disconnect with no client id was answered 0x%02X, want 0x83",
				ack.ReasonCode)
		}
	})
}

// **The broker's own in-process publisher is not a session**, and hanging it
// up would stop the broker publishing on its own behalf - a Will, a queue
// delivery, a bridge. It sits in the same table as everybody else, so it is
// reachable by name and has to be refused by name.
func TestTheBrokersOwnPublisherCannotBeHungUp(t *testing.T) {
	h := start(t)
	// The harness's own clients are anonymous, and the publish at the end is
	// the assertion that the broker still works - so the empty identity has
	// to be able to make it, or that check fails for a reason of its own.
	writeACL(t, h, `
roles:
  on-call:
    - broker: sessions
      allow: [disconnect]
  everyday:
    - channel: events
      allow: [write, read]
users:
  oncall: [on-call]
  "*": [everyday]
`)

	inline, ok := h.Srv.Clients.Get(mqtt.InlineClientId)
	if !ok {
		t.Skip("this substrate has no inline client, so there is nothing to protect")
	}

	operator := dialWithUser(t, h, "operator", "oncall")
	code, said := askDisconnect(t, operator, mqtt.InlineClientId)
	if code != 0x00 {
		t.Fatalf("naming the broker's own publisher was refused 0x%02X", code)
	}
	if said != "no-such-client" {
		t.Errorf("naming the broker's own publisher replied %q, want no-such-client", said)
	}
	if inline.Closed() {
		t.Error("the broker's own in-process publisher was hung up, so the broker can no " +
			"longer deliver a Will, a queue job or a bridge's records")
	}

	// It still publishes, which is the thing the refusal is protecting.
	reader := connect(t, h, "reader", true, false)
	reader.Sub(t, "events/#", 1)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/after", "still working")
	if r, ok := reader.Await(t, 3*time.Second); !ok || r.Payload != "still working" {
		t.Errorf("the broker stopped delivering after the refusal: %+v", r)
	}
}

// **A client cannot hang itself up**, and the reason is that the verb
// cannot answer for it: the acknowledgement is written after the handler
// returns, so a connection ended inside it never receives one. Allowed, the
// caller's library reports a publish that was never acknowledged and the
// operator cannot tell that from a broker that has failed.
//
// Nothing is taken away by refusing. Ending its own connection is something
// every client can already do with the DISCONNECT its protocol defines, and
// that one is acknowledged by being the last packet on the connection.
func TestAClientCannotHangItselfUp(t *testing.T) {
	h := start(t)
	writeACL(t, h, "roles:\n  on-call:\n    - broker: sessions\n      allow: [disconnect]\n"+
		"users:\n  oncall: [on-call]\n")

	operator := dialWithUser(t, h, "operator", "oncall")
	code, _ := askDisconnect(t, operator, "operator")
	if code != 0x83 {
		t.Errorf("a client naming itself was answered 0x%02X, want 0x83", code)
	}

	// **Still connected, and still able to work** - the refusal is the whole
	// of what happened, rather than a refusal reported after the connection
	// had already gone.
	if cl, ok := h.Srv.Clients.Get("operator"); !ok || cl.Closed() {
		t.Fatal("the client was hung up despite the refusal")
	}
	select {
	case d := <-operator.Gone:
		t.Errorf("a DISCONNECT 0x%02X reached a client whose request was refused",
			d.ReasonCode)
	case <-time.After(500 * time.Millisecond):
	}

	// And the verb still works on somebody else from the same connection, so
	// the refusal is about the id and not about the client that asked.
	victim := connect(t, h, "victim", true, false)
	_ = victim
	if code, said := askDisconnect(t, operator, "victim"); code != 0x00 || said != "hung-up" {
		t.Errorf("after refusing a self-disconnect the verb answered 0x%02X %q for "+
			"another client, want 0x00 hung-up", code, said)
	}
}

// **What the two protocols and the two qualities of service each get**, and
// they are three different answers rather than one.
//
// It is asked here rather than reasoned about, because the answer depends on
// what the substrate does with a code the hook returns - which differs by
// protocol version and by QoS, and is not visible from this package's own
// code at all.
func TestWhoCanAskForADisconnectAndWhatTheyAreTold(t *testing.T) {
	// **QoS 0 works, and that falls out of the answer being a reply.** A
	// verb whose outcome rode on the acknowledgement would be unusable at
	// QoS 0, because there is no acknowledgement; this one is not.
	t.Run("qos 0 acts and is answered", func(t *testing.T) {
		h := start(t)
		writeACL(t, h, "roles:\n  on-call:\n    - broker: sessions\n      allow: [disconnect]\n"+
			"users:\n  oncall: [on-call]\n")
		victim := connect(t, h, "victim", true, false)
		_ = victim

		operator := dialWithUser(t, h, "operator", "oncall")
		if _, err := operator.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/sessions/disconnect", QoS: 0, Payload: []byte("victim"),
			Properties: &paho.PublishProperties{ResponseTopic: "ops/reply"},
		}); err != nil {
			t.Fatalf("publish at QoS 0: %v", err)
		}
		r, ok := operator.Await(t, 5*time.Second)
		if !ok {
			t.Fatal("a QoS 0 disconnect was never answered: the reply is the whole " +
				"answer at this quality of service, since there is no acknowledgement")
		}
		if r.Topic != "ops/reply" || r.Payload != "hung-up" {
			t.Errorf("the reply is %q on %q, want hung-up on ops/reply", r.Payload, r.Topic)
		}
		deadline := time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			if cl, ok := h.Srv.Clients.Get("victim"); !ok || cl.Closed() {
				return
			}
			time.Sleep(20 * time.Millisecond)
		}
		t.Error("the client is still connected after a QoS 0 disconnect that replied hung-up")
	})

	// **A refused QoS 0 request is dropped rather than answered**, which is
	// the trade the reserved space already makes everywhere: there is no
	// acknowledgement to carry a refusal, and returning a code for one
	// leaves the substrate with no branch to take - the packet then carries
	// on down the publish path as though it had been accepted.
	t.Run("qos 0 refused is dropped, and nothing happens", func(t *testing.T) {
		h := start(t)
		writeACL(t, h, "roles:\n  on-call:\n    - broker: sessions\n      allow: [disconnect]\n"+
			"users:\n  oncall: [on-call]\n")
		operator := dialWithUser(t, h, "operator", "oncall")
		// Retained on purpose, because a control packet kept in the
		// retained store would be the visible residue of one that carried
		// on down the publish path. **Nothing is retained either way**, so
		// this assertion holds rather than proves: the refusal is dropped
		// here, and a retained publish in the reserved space has other
		// things refusing it too. It is checked because the cost is a line
		// and the alternative is assuming.
		if _, err := operator.C.Publish(context.Background(), &paho.Publish{
			Topic: "$saguin/sessions/disconnect", QoS: 0, Payload: []byte("operator"),
			Retain:     true,
			Properties: &paho.PublishProperties{ResponseTopic: "ops/reply"},
		}); err != nil {
			t.Fatalf("publish at QoS 0: %v", err)
		}
		time.Sleep(200 * time.Millisecond)
		if kept := h.Srv.Topics.Messages("$saguin/sessions/disconnect"); len(kept) != 0 {
			t.Errorf("a refused request was retained: %d message(s) sit under the "+
				"reserved topic, so the packet carried on down the publish path as "+
				"though it had been accepted", len(kept))
		}
		if r, more := operator.Await(t, 500*time.Millisecond); more {
			t.Errorf("a refused QoS 0 request was answered %q, and it has nowhere to be "+
				"answered", r.Payload)
		}
		if cl, ok := h.Srv.Clients.Get("operator"); !ok || cl.Closed() {
			t.Error("the client that named itself was hung up at QoS 0, where it could " +
				"not even be told")
		}
	})

	// **A 3.1.1 client cannot ask for this verb at all**, and is hung up for
	// trying rather than told it worked. A Response Topic is an MQTT 5
	// property, so the request is refused - and a 3.1.1 `PUBACK` carries no
	// reason code, which is the case saguin already answers by ending the
	// connection rather than acknowledging a refusal as success.
	//
	// Hand-encoded rather than driven by the client library, because the
	// library this suite uses speaks MQTT 5 only - and a claim about what
	// 3.1.1 gets, made through a client that cannot send 3.1.1, is a claim
	// about nothing.
	t.Run("a 3.1.1 client is refused and hung up", func(t *testing.T) {
		h := start(t)
		writeACL(t, h, "roles:\n  anyone:\n    - broker: sessions\n      allow: [disconnect]\n"+
			"users:\n  \"*\": [anyone]\n")
		victim := connect(t, h, "victim", true, false)
		_ = victim

		conn, err := net.Dial("tcp", h.Addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		defer conn.Close()
		str := func(v string) []byte {
			return append([]byte{byte(len(v) >> 8), byte(len(v))}, v...)
		}
		var body []byte
		body = append(body, str("MQTT")...)
		body = append(body, 0x04, 0x02, 0x00, 0x1E) // level 4, clean session, keepalive 30
		body = append(body, str("old-operator")...)
		if _, err := conn.Write(append([]byte{0x10, byte(len(body))}, body...)); err != nil {
			t.Fatalf("write the CONNECT: %v", err)
		}
		buf := make([]byte, 64)
		_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
		n, err := conn.Read(buf)
		if err != nil {
			t.Fatalf("read the CONNACK: %v", err)
		}
		// 0x20 CONNACK, remaining length 2, flags, return code 0.
		if n < 4 || buf[0] != 0x20 || buf[3] != 0x00 {
			t.Fatalf("the 3.1.1 client did not connect: % x", buf[:n])
		}

		var pub []byte
		pub = append(pub, str("$saguin/sessions/disconnect")...)
		pub = append(pub, 0x00, 0x07)
		pub = append(pub, []byte("victim")...)
		if _, err := conn.Write(append([]byte{0x32, byte(len(pub))}, pub...)); err != nil {
			t.Fatalf("write the PUBLISH: %v", err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
		if n, err := conn.Read(buf); err == nil {
			t.Errorf("the 3.1.1 client was answered % x rather than hung up: a PUBACK it "+
				"cannot read a reason code from says the request succeeded", buf[:n])
		}

		// **And the victim is untouched**, which is the half that matters:
		// the request was refused rather than half-performed.
		time.Sleep(300 * time.Millisecond)
		if cl, ok := h.Srv.Clients.Get("victim"); !ok || cl.Closed() {
			t.Error("a client was hung up by a request the broker refused")
		}
	})
}

// **A `latest` channel's current state reaches a subscriber whose window is
// already full of somebody else's history.**
//
// This is the shape every wildcard subscriber has: `#` reaches the append
// channels and the `latest` ones together, the appends are pumped first, and
// on a channel with any backlog they fill the in-flight window before a
// snapshot is looked at. The snapshot is then queued whole - nothing goes
// out, so nothing about that channel is ever acknowledged, so the resume
// keyed to its own acknowledgements never fires. The subscriber is
// connected, its subscription is granted `0x00`, and the current state it
// asked for never arrives.
//
// Found on a demonstration broker holding 70,000 records, where a schema
// registry's six values never appeared at QoS 1 and appeared immediately at
// QoS 0 - which has no window to fill.
func TestCurrentStateArrivesBehindAnAppendChannelsBacklog(t *testing.T) {
	h := start(t)

	// The backlog. More than the window this subscriber will offer, so the
	// pump is guaranteed to fill it before any snapshot is reached.
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 40; i++ {
		p.Pub(t, fmt.Sprintf("events/orders/%d", i), fmt.Sprintf("order-%d", i))
	}
	// And the state, on a channel whose values are what this test is about.
	p.Pub(t, "state/boat-7/fuel", "40")
	p.Pub(t, "state/boat-8/fuel", "12")

	// **A small Receive Maximum makes the window fill at four rather than at
	// eight thousand**, which is the same condition a real subscriber meets
	// on a channel with real history - reached here without publishing tens
	// of thousands of records.
	sub := connectRx(t, h, "reader", true, false, 4)
	sub.Sub(t, "#", 1)

	// Everything the channel holds, whatever else is being replayed beside
	// it. Collected by topic, because the two are current state and their
	// order against the backlog is the broker's business.
	want := map[string]string{"state/boat-7/fuel": "40", "state/boat-8/fuel": "12"}
	got := map[string]string{}
	deadline := time.Now().Add(15 * time.Second)
	for len(got) < len(want) && time.Now().Before(deadline) {
		r, ok := sub.Await(t, 3*time.Second)
		if !ok {
			break
		}
		if _, isState := want[r.Topic]; isState {
			got[r.Topic] = r.Payload
		}
	}
	for topic, value := range want {
		if got[topic] != value {
			t.Errorf("the current value of %s never arrived (got %q): a subscriber whose "+
				"window filled with an append channel's backlog is served no current "+
				"state at all, and is told nothing - its subscription was granted and "+
				"the broker simply stops", topic, got[topic])
		}
	}
}

// **An acl_file replaced under a connected client** (RFC 0002, "What a
// client may do" - re-read on SIGUSR1).
//
// The signal itself lives in cmd/saguin and is tested there, against the
// real binary. What is tested here is what the broker does when the rules
// are swapped while clients are using them, which that test cannot see: it
// drives a subprocess, and the race detector only watches this one.
//
// Two claims, and they failed in different ways before this:
//
//   - **The new rules answer the connection that never went away.** A
//     narrowed role refuses the very next publish, with nothing
//     reconnecting.
//   - **A cached answer follows the file.** The per-client publish budget
//     resolves its numbers from the acl_file once and keys that on the
//     client id - so a re-read that narrowed a rate applied to every client
//     except the one it was written about, which is the client the operator
//     was thinking of.
func TestReplacingTheACLUnderALiveClient(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  wide:
    - topic: "site/#"
      allow: [write, read]
users:
  "device-*": [wide]
`)
	c := dialWithUser(t, h, "live", "device-3")
	ack, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: "site/x", QoS: 1, Payload: []byte("before"),
	})
	if ack == nil {
		t.Fatalf("no PUBACK before the swap: %v", err)
	}
	if ack.ReasonCode != 0x00 {
		t.Fatalf("the publish was refused 0x%02X before anything was narrowed, so "+
			"nothing below would prove the swap did it", ack.ReasonCode)
	}

	// The same client, the same connection, a file that no longer names it.
	writeACL(t, h, `
roles:
  wide:
    - topic: "site/#"
      allow: [write, read]
users:
  "operator-*": [wide]
`)
	ack, err = c.C.Publish(context.Background(), &paho.Publish{
		Topic: "site/x", QoS: 1, Payload: []byte("after"),
	})
	if ack == nil {
		t.Fatalf("no PUBACK after the swap: %v", err)
	}
	if ack.ReasonCode != 0x87 {
		t.Errorf("after the acl_file was replaced the same connection published with "+
			"0x%02X, want 0x87: rules that only reach the next connection are rules an "+
			"operator cannot use to stop anything", ack.ReasonCode)
	}
}

// **A publish budget resolved from one acl_file is re-resolved from the
// next**, which is the cache the swap above would otherwise walk past.
//
// The budget's numbers are read from the file once per client and kept
// against the client id, because walking the patterns per publish would put
// a string match per pattern on the hot path. That was sound while the file
// could not change; it stopped being sound the moment SIGUSR1 could replace
// it, and the failure is silent - the client goes on at the old rate and the
// refusal log names the old number.
func TestANarrowedPublishRateReachesAClientAlreadyConnected(t *testing.T) {
	var mu sync.Mutex
	var lines []string
	h := startLoggingDebug(t, func(line string) {
		if strings.Contains(line, "refusing publish: over the client's publish rate") {
			mu.Lock()
			lines = append(lines, line)
			mu.Unlock()
		}
	})
	writeACL(t, h, `
roles:
  publisher:
    - topic: "loose/#"
      allow: [write, read]
users:
  "device-*":
    roles: [publisher]
    limits:
      publish_rate: 1000
`)
	c := dialWithUser(t, h, "budgeted", "device-3")
	// Spends nothing worth counting, and is what makes the budget resolve:
	// an unread cache is not the cache this test is about.
	if ack, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: "loose/x", QoS: 1, Payload: []byte("first"),
	}); ack == nil || ack.ReasonCode != 0x00 {
		t.Fatalf("the first publish did not go through: %v (%v)", ack, err)
	}

	writeACL(t, h, `
roles:
  publisher:
    - topic: "loose/#"
      allow: [write, read]
users:
  "device-*":
    roles: [publisher]
    limits:
      publish_rate: 2
`)
	for i := 0; i < 12; i++ {
		_, _ = c.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/x", QoS: 1, Payload: []byte("x"),
		})
	}

	mu.Lock()
	defer mu.Unlock()
	if len(lines) == 0 {
		t.Fatal("twelve publishes against a re-read limit of 2/s were never throttled: " +
			"the budget is still resolved from the acl_file this client connected under")
	}
	for _, l := range lines {
		if !strings.Contains(l, "rate=2") {
			t.Errorf("a refusal after the re-read logged %q: it holds the client to the "+
				"numbers from the file the broker was carrying when it connected", l)
		}
	}
	t.Logf("%d refusals, all naming the re-read rate", len(lines))
}

// **A narrowed acl_file stops a subscription that was already granted**
// (RFC 0002, "Withdrawing a device's access").
//
// Worth pinning because the answer is not the one MQTT's shape suggests. A
// grant is decided at SUBSCRIBE, so a reasonable reading is that an existing
// subscription goes on delivering until the client reconnects - and that
// reading went into a draft of the RFC before it was run. It is wrong here:
// the file is asked on delivery too, so re-reading it stops the messages
// as well as the publishes.
//
// Which is the difference between "the operator must hang the device up
// before it stops receiving" and "hanging it up is about the connection and
// the lease". Only one of those is true, and a document that got it wrong
// would have operators hurrying a step whose reason they had been told
// wrongly.
func TestANarrowedACLStopsDeliveryToASubscriptionAlreadyGranted(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  wide:
    - topic: "site/#"
      allow: [write, read]
users:
  "device-*": [wide]
  "pub-*": [wide]
`)
	got := make(chan string, 8)
	sub := dialWithUser(t, h, "listener", "device-3")
	sub.C.AddOnPublishReceived(func(p paho.PublishReceived) (bool, error) {
		got <- string(p.Packet.Payload)
		return true, nil
	})
	if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "site/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	pub := dialWithUser(t, h, "sender", "pub-1")
	send := func(what string) {
		t.Helper()
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "site/x", QoS: 1, Payload: []byte(what),
		}); err != nil {
			t.Fatalf("publish %s: %v", what, err)
		}
	}

	// **The strand proves it drove something**: a test that never delivered
	// anything would pass the assertion below while checking nothing.
	send("one")
	select {
	case <-got:
	case <-time.After(2 * time.Second):
		t.Fatal("nothing arrived while the subscriber was still granted, so the " +
			"silence below would say nothing about the acl_file")
	}

	writeACL(t, h, `
roles:
  wide:
    - topic: "site/#"
      allow: [write, read]
users:
  "pub-*": [wide]
`)
	send("two")
	select {
	case m := <-got:
		t.Errorf("the acl_file no longer grants this client read, and it received %q on "+
			"a subscription granted under the old file: withdrawing a role would leave "+
			"the data flowing until the device happened to reconnect", m)
	case <-time.After(2 * time.Second):
	}
}

// **A re-read reaches a client that authenticated with a certificate**
// (RFC 0002, "Withdrawing a device's access" - the mTLS paragraph).
//
// The two halves of a withdrawal fall differently here, and the difference
// is the whole reason this is its own test. A certificate client has no
// entry in a password file - the authority has already made the statement
// that file exists to make - so there is nothing there to delete, and the
// signal's password half is not what stops it. What stops it is the
// `acl_file`, which is written about the Common Name like any other
// identity, and which the same signal re-reads.
//
// Both moments are asserted:
//
//   - **What it may do**, on the connection it already holds: the rules are
//     replaced and its next publish is refused, with nothing reconnecting.
//   - **Whether it may connect at all**, which for a certificate client is
//     `client_ids:` and nothing else - saguin has no certificate
//     revocation, so an entry that no longer admits the device's id is the
//     only thing that refuses it at CONNECT. That check reads the same
//     replaced rules, which is what makes it part of the same act.
func TestAReReadReachesAClientAuthenticatedByItsCertificate(t *testing.T) {
	certFile, keyFile, serverPool := selfSigned(t, "localhost")
	serverPair, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		t.Fatalf("server pair: %v", err)
	}
	// The Common Name is the identity every rule below is written about.
	client, clientCAs := clientCert(t, "device-7")

	reg, err := channel.NewRegistry([]*channel.Channel{
		{Name: "events", Type: channel.Append, Filter: "events/+"},
	})
	if err != nil {
		t.Fatalf("registry: %v", err)
	}
	srv, b, err := broker.NewServer(reg, config.Limits{}.Resolve(),
		slog.New(slog.NewTextHandler(io.Discard, nil)))
	if err != nil {
		t.Fatalf("server: %v", err)
	}
	// **No password file at all**, so nothing here can be credited to one:
	// every answer below comes from the certificate and the acl_file.
	b.SetCredentials(nil, false)
	l := listeners.NewTCP(listeners.Config{
		ID: "mtls", Address: "127.0.0.1:0",
		TLSConfig: &tls.Config{
			Certificates: []tls.Certificate{serverPair},
			MinVersion:   tls.VersionTLS12,
			ClientCAs:    clientCAs,
			ClientAuth:   tls.RequireAndVerifyClientCert,
		},
	})
	if err := srv.AddListener(l); err != nil {
		t.Fatalf("add listener: %v", err)
	}
	go func() { _ = srv.Serve() }()
	t.Cleanup(func() { _ = srv.Close(); b.Stop() })
	addr := l.Address()

	// rules replaces the acl_file the way SIGUSR1 does: loaded from a file,
	// installed on a running broker.
	rules := func(body string) {
		t.Helper()
		path := filepath.Join(t.TempDir(), "acl.yaml")
		if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
			t.Fatalf("write the acl file: %v", err)
		}
		f, err := authz.Load(path, reg, 0)
		if err != nil {
			t.Fatalf("the test's own acl file does not load: %v", err)
		}
		b.Authorize(authz.New(f, reg))
	}
	connect := func(id string) (*paho.Client, byte, error) {
		t.Helper()
		conn, err := tls.Dial("tcp", addr, &tls.Config{
			RootCAs: serverPool, MinVersion: tls.VersionTLS12,
			Certificates: []tls.Certificate{client},
		})
		if err != nil {
			return nil, 0, err
		}
		t.Cleanup(func() { _ = conn.Close() })
		c := paho.NewClient(paho.ClientConfig{Conn: conn})
		var expiry uint32
		ca, err := c.Connect(context.Background(), &paho.Connect{
			ClientID: id, CleanStart: true, KeepAlive: 0,
			Properties: &paho.ConnectProperties{SessionExpiryInterval: &expiry},
		})
		if ca == nil {
			return nil, 0, err
		}
		return c, ca.ReasonCode, nil
	}
	publishes := func(c *paho.Client) byte {
		t.Helper()
		ack, err := c.Publish(context.Background(), &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte("hello"),
		})
		if ack == nil {
			t.Fatalf("no PUBACK: %v", err)
		}
		return ack.ReasonCode
	}

	rules(`
roles:
  device:
    - channel: events
      allow: [write, read]
users:
  "device-*": [device]
`)
	cert, code, err := connect("gateway-1")
	if err != nil {
		t.Fatalf("connect with a client certificate: %v", err)
	}
	if code != 0x00 {
		t.Fatalf("the certificate was refused 0x%02X before anything was withdrawn", code)
	}
	if got := publishes(cert); got != 0x00 {
		t.Fatalf("the publish was refused 0x%02X before anything was withdrawn, so "+
			"nothing below would prove the re-read did it", got)
	}

	// The withdrawal: the file no longer names this identity.
	rules(`
roles:
  device:
    - channel: events
      allow: [write, read]
users:
  "operator-*": [device]
`)
	if got := publishes(cert); got != 0x87 {
		t.Errorf("after the acl_file stopped naming this certificate's Common Name, its "+
			"publish answered 0x%02X, want 0x87: a device holding a certificate would go "+
			"on writing until it happened to reconnect", got)
	}
	// **And it can still connect**, which is the honest limit and the reason
	// the document says so: the authority still vouches for the certificate,
	// and saguin has no revocation. What it comes back to is no grants.
	back, code, err := connect("gateway-1")
	if err != nil {
		t.Fatalf("reconnect with the certificate: %v", err)
	}
	if code != 0x00 {
		t.Fatalf("the certificate was refused 0x%02X at CONNECT: saguin has no "+
			"certificate revocation, so this should still be admitted and merely "+
			"unable to do anything", code)
	}
	if got := publishes(back); got != 0x87 {
		t.Errorf("a certificate client that reconnected after the withdrawal published "+
			"with 0x%02X, want 0x87", got)
	}

	// **The CONNECT-time half**: an entry that no longer admits this client
	// id refuses the connection itself, and it reads the replaced rules.
	rules(`
roles:
  device:
    - channel: events
      allow: [write, read]
users:
  "device-*":
    roles: [device]
    client_ids: ["approved-*"]
`)
	if _, code, err := connect("gateway-1"); err == nil && code == 0x00 {
		t.Error("after client_ids stopped admitting this client id, the certificate " +
			"connected anyway: the CONNECT-time check is reading rules the signal " +
			"replaced, so it must follow them")
	}
	// The same file admits the id it does name, so the refusal above is
	// about the client id rather than about a broker that stopped
	// accepting this certificate.
	if _, code, err := connect("approved-9"); err != nil || code != 0x00 {
		t.Errorf("a client id the acl_file does admit was refused 0x%02X (%v)", code, err)
	}
}

// **A grant taken away stops every delivery route, not the two the
// substrate happens to write** (RFC 0002, "Withdrawing a device's access").
//
// The shape of the defect is the reason
// it is one table rather than four tests. invariants.md already splits the
// routes: "an `append` or `latest` delivery, a dead-letter record and
// every control reply are written by saguin; a queue offer and a broadcast
// delivery are written by the substrate". The substrate asks the acl_file on
// every delivery it makes; saguin's own pump asked at SUBSCRIBE and never
// again. So re-reading the file stopped the broadcast and the queue offer -
// which is what the first version of this test drove, and passed - while the
// channel data went on flowing.
//
// **An operator following the documented workflow saw every promised
// success and kept leaking**: the broadcast stopped in front of them, the
// hang-up replied `hung-up`, and the device resumed its durable session and
// went on receiving. The enumeration is the whole lesson: one route of four
// was tested, and the rule was about the routes.
func TestANarrowedACLStopsEveryDeliveryRoute(t *testing.T) {
	for _, tc := range []struct {
		name    string
		filter  string
		topic   string
		granted string // the role that lets the reader have it
	}{
		{"append", "events/#", "events/x", "- channel: events\n      allow: [read]"},
		{"latest", "state/#", "state/x", "- channel: state\n      allow: [read]"},
		{"broadcast", "bc/#", "bc/x", "- topic: \"bc/#\"\n      allow: [read]"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			writeACL(t, h, `
roles:
  writer:
    - channel: events
      allow: [write]
    - channel: state
      allow: [write]
    - channel: jobs__dlq
      allow: [write]
    - topic: "bc/#"
      allow: [write]
  reader:
    `+tc.granted+`
users:
  pub: [writer]
  dev: [reader]
`)
			got := make(chan string, 8)
			sub := dialWithUser(t, h, "reader-1", "dev")
			sub.C.AddOnPublishReceived(func(p paho.PublishReceived) (bool, error) {
				got <- string(p.Packet.Payload)
				return true, nil
			})
			if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
				Subscriptions: []paho.SubscribeOptions{{Topic: tc.filter, QoS: 1}},
			}); err != nil {
				t.Fatalf("subscribe %s: %v", tc.filter, err)
			}
			pub := dialWithUser(t, h, "writer-1", "pub")
			send := func(what string) {
				t.Helper()
				if _, err := pub.C.Publish(context.Background(), &paho.Publish{
					Topic: tc.topic, QoS: 1, Payload: []byte(what),
				}); err != nil {
					t.Fatalf("publish %s: %v", what, err)
				}
			}

			// **The strand proves it drove something.** A route that never
			// delivered would pass the silence below while testing nothing,
			// and three of these four routes are exactly the kind a test
			// gets wrong by not arriving in the first place.
			send("one")
			select {
			case <-got:
			case <-time.After(3 * time.Second):
				t.Fatalf("%s: nothing arrived while the grant was in force, so the "+
					"silence below would say nothing about the acl_file", tc.name)
			}

			// The grant taken away, exactly as SIGUSR1 does it.
			writeACL(t, h, `
roles:
  writer:
    - channel: events
      allow: [write]
    - channel: state
      allow: [write]
    - channel: jobs__dlq
      allow: [write]
    - topic: "bc/#"
      allow: [write]
  reader:
    - topic: "keep/#"
      allow: [read]
users:
  pub: [writer]
  dev: [reader]
`)
			send("two")
			select {
			case m := <-got:
				t.Errorf("%s: the acl_file no longer grants this client read, and it "+
					"received %q - a route saguin writes itself asked the file at "+
					"SUBSCRIBE and never again, so withdrawing a role left the data "+
					"flowing", tc.name, m)
			case <-time.After(2 * time.Second):
			}
		})
	}
}

// **And it stays stopped across the hang-up**, which is what makes the
// finding a leak rather than a delay.
//
// Step 3 of the workflow ends the connection; the device reconnects on its
// durable session, is told Session Present, and sends no SUBSCRIBE - so
// there is nothing for the broker to refuse, and a check that only runs at
// SUBSCRIBE never runs again for the life of that session. The act meant to
// close the gap re-opened it, indefinitely.
func TestAWithdrawnReaderStaysStoppedWhenItsSessionResumes(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  writer:
    - channel: events
      allow: [write]
  reader:
    - channel: events
      allow: [read]
users:
  pub: [writer]
  dev: [reader]
`)
	got := make(chan string, 8)
	receive := func(c *client) {
		c.C.AddOnPublishReceived(func(p paho.PublishReceived) (bool, error) {
			got <- string(p.Packet.Payload)
			return true, nil
		})
	}
	sub := dialSession(t, h, "resumer", "dev")
	receive(sub)
	if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "events/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	pub := dialWithUser(t, h, "writer-1", "pub")
	send := func(what string) {
		t.Helper()
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte(what),
		}); err != nil {
			t.Fatalf("publish %s: %v", what, err)
		}
	}
	send("one")
	select {
	case <-got:
	case <-time.After(3 * time.Second):
		t.Fatal("nothing arrived while the grant was in force")
	}

	writeACL(t, h, `
roles:
  writer:
    - channel: events
      allow: [write]
  reader:
    - topic: "keep/#"
      allow: [read]
users:
  pub: [writer]
  dev: [reader]
`)
	// The hang-up: the connection ends and the session stays, which is what
	// the verb is for.
	sub.C.Disconnect(&paho.Disconnect{ReasonCode: 0x04})
	back := dialSession(t, h, "resumer", "dev")
	receive(back)

	send("two")
	select {
	case m := <-got:
		t.Errorf("after the withdrawal and a resumed session, the client received %q: "+
			"it sent no SUBSCRIBE, so a check that only runs at SUBSCRIBE never runs "+
			"again - and the hang-up that was supposed to close the gap re-opened it",
			m)
	case <-time.After(2 * time.Second):
	}
}

// **A stalled consumer loses nothing**, which is the other half of what the
// refusal claims: its position is not advanced past a record it may not
// read, so restoring the grant delivers what it missed rather than skipping
// it.
//
// Skipping would be invariant 1's failure with the report going to the
// operator instead of the consumer: everything after the gap processed in
// order, and success reported over a record nobody received.
func TestAConsumerStalledByTheACLResumesWhereItStopped(t *testing.T) {
	h := start(t)
	const granted = `
roles:
  writer:
    - channel: events
      allow: [write]
  reader:
    - channel: events
      allow: [read]
users:
  pub: [writer]
  dev: [reader]
`
	writeACL(t, h, granted)
	got := make(chan string, 16)
	sub := dialWithUser(t, h, "stalled", "dev")
	sub.C.AddOnPublishReceived(func(p paho.PublishReceived) (bool, error) {
		got <- string(p.Packet.Payload)
		return true, nil
	})
	if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "events/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	pub := dialWithUser(t, h, "writer-1", "pub")
	send := func(what string) {
		t.Helper()
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte(what),
		}); err != nil {
			t.Fatalf("publish %s: %v", what, err)
		}
	}
	send("before")
	select {
	case <-got:
	case <-time.After(3 * time.Second):
		t.Fatal("nothing arrived while the grant was in force")
	}

	writeACL(t, h, `
roles:
  writer:
    - channel: events
      allow: [write]
  reader:
    - topic: "keep/#"
      allow: [read]
users:
  pub: [writer]
  dev: [reader]
`)
	for _, m := range []string{"gone-1", "gone-2", "gone-3"} {
		send(m)
	}
	select {
	case m := <-got:
		t.Fatalf("a withdrawn reader received %q", m)
	case <-time.After(time.Second):
	}

	// The grant comes back, and so does everything published without it.
	writeACL(t, h, granted)
	send("after")
	var arrived []string
	deadline := time.After(5 * time.Second)
	for len(arrived) < 4 {
		select {
		case m := <-got:
			arrived = append(arrived, m)
		case <-deadline:
			t.Fatalf("after the grant was restored the consumer received %v, want all "+
				"four in order: a position advanced past a record the consumer may not "+
				"read loses it, and nothing says so", arrived)
		}
	}
	want := []string{"gone-1", "gone-2", "gone-3", "after"}
	for i := range want {
		if arrived[i] != want[i] {
			t.Errorf("record %d was %q, want %q - the order is the consumer's own log",
				i, arrived[i], want[i])
		}
	}
}

// **The dead-letter route, driven rather than reasoned about.**
//
// The leak was found on `append` and `latest`, and a
// dead-letter delivery "leaks by shape" - the same pump over an append
// channel - without driving it. That is a sound reading and it is still a
// claim about a route, which is a thing to run: a derived channel is exactly
// where "the same code path" stops being obvious to whoever reads this next,
// and a client cannot publish to one, so nothing else in this file gets a
// record onto it the way the broker does.
//
// So the record is a real dead letter: a worker returns the job until its
// attempts are exhausted, and the reader holding `read` on `jobs__dlq`
// watches it arrive - then has that grant taken away and must stop.
func TestANarrowedACLStopsADeadLetterDelivery(t *testing.T) {
	h := start(t)
	const granted = `
roles:
  producer:
    - channel: jobs
      allow: [write]
  worker:
    - channel: jobs
      allow: [consume]
  auditor:
    - channel: jobs__dlq
      allow: [read]
users:
  prod: [producer]
  work: [worker]
  audit: [auditor]
`
	writeACL(t, h, granted)

	got := make(chan string, 8)
	reader := dialWithUser(t, h, "dlq-reader", "audit")
	reader.C.AddOnPublishReceived(func(p paho.PublishReceived) (bool, error) {
		got <- string(p.Packet.Payload)
		return true, nil
	})
	if _, err := reader.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "jobs/__dlq/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe to the dead-letter channel: %v", err)
	}

	// A worker that returns every job it is handed, so each one burns its
	// attempts and lands on the dead-letter channel.
	w := dialWithUser(t, h, "worker-returns", "work")
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)
	p := dialWithUser(t, h, "producer-1", "prod")

	deadLetter := func(payload string) {
		t.Helper()
		p.Pub(t, "jobs/failing", payload)
		for attempt := 1; attempt <= maxAttempts; attempt++ {
			r, ok := w.Await(t, 4*time.Second)
			if !ok {
				t.Fatalf("%s: attempt %d was never offered to the worker", payload, attempt)
			}
			w.Respond(t, r.RespTopic, "return", r.CorrData)
		}
	}

	deadLetter("job-one")
	select {
	case <-got:
	case <-time.After(5 * time.Second):
		t.Fatal("no dead letter reached the reader while its grant was in force, so " +
			"the silence below would say nothing about the acl_file")
	}

	writeACL(t, h, `
roles:
  producer:
    - channel: jobs
      allow: [write]
  worker:
    - channel: jobs
      allow: [consume]
  auditor:
    - topic: "keep/#"
      allow: [read]
users:
  prod: [producer]
  work: [worker]
  audit: [auditor]
`)
	deadLetter("job-two")
	select {
	case m := <-got:
		t.Errorf("after the acl_file stopped granting read on the dead-letter channel, "+
			"the reader received %q: a dead letter goes out through the same pump as "+
			"any other append record, so a gate on that pump has to cover it", m)
	case <-time.After(2 * time.Second):
	}
}

// **A job offered to a worker the acl_file no longer allows goes back to the
// queue** (invariant 2, invariant 7).
//
// The queue route never leaked - the substrate asks per delivery, so the
// withdrawn worker never received the job. What nobody had asked is what
// became of the job it was refused about: the record stayed `delivering`
// with no holder and no lease clock, for ever. Invariant 7's deadline starts
// at the PUBACK, which cannot arrive for a packet that was never written, and
// the offer loop only feeds what is waiting. So the job was acknowledged
// `0x00` to its publisher and then never processed, never returned, never
// dead-lettered - and in the queue view it reads like work in hand.
//
// **Two workers make it a running loss rather than a window**, which is what
// this test drives: the shared-group selection keeps handing the withdrawn
// worker its share while the healthy one sits idle, so a steady stream of
// jobs bleeds away a fraction at a time.
func TestAJobOfferedToAWithdrawnWorkerGoesBackToTheQueue(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  producer:
    - channel: jobs
      allow: [write]
  worker:
    - channel: jobs
      allow: [consume]
users:
  prod: [producer]
  keeps: [worker]
  loses: [worker]
`)
	healthy := dialWithUser(t, h, "worker-keeps", "keeps")
	healthy.Sub(t, "$saguin/queue/jobs", 1)
	withdrawn := dialWithUser(t, h, "worker-loses", "loses")
	withdrawn.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, healthy.C)
	subscribed(t, withdrawn.C)

	p := dialWithUser(t, h, "producer-1", "prod")

	// **Both workers are fed first**, so the selection is proved to be
	// handing work to each of them: a test where only one ever received
	// anything would pass the count below without the round-robin ever
	// choosing the withdrawn one.
	seen := map[string]bool{}
	for i := 0; i < 6 && len(seen) < 2; i++ {
		p.Pub(t, fmt.Sprintf("jobs/warm-%d", i), fmt.Sprintf("warm-%d", i))
		for _, w := range []*client{healthy, withdrawn} {
			if r, ok := w.Await(t, 300*time.Millisecond); ok {
				seen[w.ID] = true
				w.Respond(t, r.RespTopic, "ack", r.CorrData)
			}
		}
	}
	if len(seen) < 2 {
		t.Fatalf("only %v was offered work, so this test would not notice the "+
			"selection handing a job to a worker that cannot have it", seen)
	}

	// One worker loses its grant. The other keeps it.
	writeACL(t, h, `
roles:
  producer:
    - channel: jobs
      allow: [write]
  worker:
    - channel: jobs
      allow: [consume]
  nothing:
    - topic: "keep/#"
      allow: [read]
users:
  prod: [producer]
  keeps: [worker]
  loses: [nothing]
`)

	const jobs = 6
	for i := 0; i < jobs; i++ {
		p.Pub(t, fmt.Sprintf("jobs/j-%d", i), fmt.Sprintf("j-%d", i))
	}

	got := map[string]bool{}
	deadline := time.Now().Add(15 * time.Second)
	for len(got) < jobs && time.Now().Before(deadline) {
		r, ok := healthy.Await(t, time.Second)
		if !ok {
			continue
		}
		// "ack", which resolves the job. A worker holds one job from a queue
		// until it answers (RFC 0003 "Delivery"), and an answer the broker
		// does not read - this said "done" - leaves it holding each job for
		// its whole visibility timeout.
		healthy.Respond(t, r.RespTopic, "ack", r.CorrData)
		// **Only the jobs this half of the test published.** A warm-up
		// record arriving late would otherwise be counted as one of them,
		// and six late warm-ups would mask six stranded jobs - the count
		// standing in for the thing it is supposed to prove.
		if strings.HasPrefix(r.Payload, "j-") {
			got[r.Payload] = true
		}
	}
	if len(got) != jobs {
		var missing []string
		for i := 0; i < jobs; i++ {
			if name := fmt.Sprintf("j-%d", i); !got[name] {
				missing = append(missing, name)
			}
		}
		t.Errorf("the worker that kept its grant received %d of %d jobs; %v never "+
			"arrived. A job the acl_file refused the other worker is left in "+
			"`delivering` with no holder and no lease clock - acknowledged to its "+
			"publisher, offered to nobody again, and never dead-lettered",
			len(got), jobs, missing)
	}
	if r, ok := withdrawn.Await(t, 200*time.Millisecond); ok {
		t.Errorf("the withdrawn worker received %q", r.Payload)
	}
}

// **A grant that comes back wakes what it stalled**, on a channel where
// nothing else is happening (RFC 0002: it "resumes from there and receives
// what it missed, in order").
//
// A stall is keyed to traffic: a refused consumer keeps its position and is
// pumped again on the next append. On a busy channel the backlog therefore
// moves the moment the file is re-read, and the first version of this rule's
// test could not tell the difference - it published after restoring the
// grant, which is itself the wake. On an idle channel - a schema registry, a
// configuration channel - the operator signals, the log says the file was
// re-read, and the consumer sits connected and silent holding records it is
// now allowed to have.
//
// **The third of this shape the project has paid for**: a retained-store
// lookup and a snapshot drain keyed to the wrong event came before it, which is why the wake is on the authorizer
// changing rather than in the signal handler.
func TestRestoringAGrantWakesAStalledConsumerWithNoFurtherTraffic(t *testing.T) {
	h := start(t)
	const granted = `
roles:
  producer:
    - channel: events
      allow: [write]
  reader:
    - channel: events
      allow: [read]
users:
  pub: [producer]
  dev: [reader]
`
	writeACL(t, h, granted)
	got := make(chan string, 8)
	sub := dialWithUser(t, h, "waker", "dev")
	sub.C.AddOnPublishReceived(func(p paho.PublishReceived) (bool, error) {
		got <- string(p.Packet.Payload)
		return true, nil
	})
	if _, err := sub.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "events/#", QoS: 1}},
	}); err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	pub := dialWithUser(t, h, "writer-1", "pub")
	send := func(what string) {
		t.Helper()
		if _, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "events/x", QoS: 1, Payload: []byte(what),
		}); err != nil {
			t.Fatalf("publish %s: %v", what, err)
		}
	}
	send("before")
	select {
	case <-got:
	case <-time.After(3 * time.Second):
		t.Fatal("nothing arrived while the grant was in force")
	}

	writeACL(t, h, `
roles:
  producer:
    - channel: events
      allow: [write]
  reader:
    - topic: "keep/#"
      allow: [read]
users:
  pub: [producer]
  dev: [reader]
`)
	send("missed-1")
	send("missed-2")
	select {
	case m := <-got:
		t.Fatalf("a withdrawn reader received %q", m)
	case <-time.After(time.Second):
	}

	// **The grant comes back and nothing else happens.** No publish, no
	// reconnect, no subscribe - the whole point is that none of those is
	// available on an idle channel.
	writeACL(t, h, granted)
	var arrived []string
	deadline := time.After(5 * time.Second)
	for len(arrived) < 2 {
		select {
		case m := <-got:
			arrived = append(arrived, m)
		case <-deadline:
			t.Fatalf("five seconds after the grant was restored the consumer had "+
				"received %v of [missed-1 missed-2]: the stall is woken by traffic, and "+
				"a restored grant is not traffic - so on a channel nobody publishes to, "+
				"'receives what it missed' waits indefinitely", arrived)
		}
	}
	if arrived[0] != "missed-1" || arrived[1] != "missed-2" {
		t.Errorf("the backlog arrived as %v, want them in the order they were published",
			arrived)
	}
}

// RFC 0002 "Asking what a channel is"
//
// A client addresses a channel by name everywhere except when it publishes
// or subscribes, where it must name topics - and only the operator's
// configuration says which topics a channel claims. This is how a client
// asks, over the credential it already has.
func TestACatalogueAnswerSaysWhatAChannelIs(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "readings", Type: channel.Append, Filter: "iot/+/{device,sensor}/#"},
		{Name: "state", Type: channel.Latest, Filter: "iot/+/state/+"},
		{Name: "work", Type: channel.Queue, Filter: "jobs/+/task/+",
			VisibilityTimeout: 30, MaxAttempts: 3},
	})
	c := connect(t, h, "asker", true, false)

	// **The filter comes back as the operator wrote it, braces and all.**
	// `{a,b}` is a level with a fixed set of spellings, which is exactly
	// what a caller composing a topic needs; the plain filters it expands
	// to are the broker's own business and would tell the caller less.
	got := readCatalogue(t, c.Catalogue(t, "readings", nil))
	if got.Filter != "iot/+/{device,sensor}/#" {
		t.Errorf("readings answered filter %q, want it as written with its braces", got.Filter)
	}
	if got.Name != "readings" || got.Type != "append" {
		t.Errorf("readings answered %+v, want name readings and type append", got)
	}
	// Every verb the type has, since no acl_file is configured and the
	// client may indeed do all of it.
	if want := []string{"write", "read", "seek"}; !slices.Equal(got.Verbs, want) {
		t.Errorf("readings answered verbs %v, want %v", got.Verbs, want)
	}
	if got.Pin != "" {
		t.Errorf("an append channel answered a pin %q; only a queue has one", got.Pin)
	}

	if got := readCatalogue(t, c.Catalogue(t, "state", nil)); got.Type != "latest" ||
		!slices.Equal(got.Verbs, []string{"write", "read", "delete"}) {
		t.Errorf("state answered %+v, want type latest with write, read and delete", got)
	}

	// **A queue answers its pin too**, which is the one addressing answer a
	// caller cannot build from the filter: a queue is consumed through this
	// exact string and every other spelling is refused.
	q := readCatalogue(t, c.Catalogue(t, "work", nil))
	if q.Type != "queue" || !slices.Equal(q.Verbs, []string{"write", "consume"}) {
		t.Errorf("work answered %+v, want type queue with write and consume", q)
	}
	if q.Pin != "$saguin/queue/work" {
		t.Errorf("work answered pin %q, want $saguin/queue/work", q.Pin)
	}

	// A dead-letter channel is a channel like any other and is asked about
	// by name, which is how a client learns the filter to read it with.
	if got := readCatalogue(t, c.Catalogue(t, "work__dlq", nil)); got.Type != "append" ||
		got.Filter != "jobs/+/task/+/__dlq" {
		t.Errorf("work__dlq answered %+v, want an append channel filtered jobs/+/task/+/__dlq", got)
	}
}

// RFC 0002 "Asking what a channel is"
//
// **The answer is scoped to what the asking client may use, and the two
// kinds of no are the same no.** A channel this client holds no verb on and
// a channel that does not exist are both the empty reply, so asking cannot
// be used to discover what is there - which is the whole reason this verb
// can be answered over an MQTT credential rather than an operator's.
func TestACatalogueAnswerIsScopedToWhatTheClientMayUse(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "readings", Type: channel.Append, Filter: "iot/+/{device,sensor}/#"},
		{Name: "secret", Type: channel.Append, Filter: "hq/+/payroll/#"},
	})

	acl := filepath.Join(t.TempDir(), "acl.yaml")
	// `*` matches the empty identity these clients connect with, which is
	// what makes a role reach them at all here.
	if err := os.WriteFile(acl, []byte(`
roles:
  reader:
    - channel: readings
      allow: [read]
  narrowed:
    - channel: readings
      allow: [write]
      filter: iot/site42/{device,sensor}/#
users:
  "*": [reader, narrowed]
`), 0o600); err != nil {
		t.Fatalf("write acl: %v", err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	c := connect(t, h, "asker", true, false)

	// **A grant narrowed to part of the channel still learns what the
	// channel is**, and that is deliberate: this is a disclosure rule, not
	// a permission one. The narrowing is enforced where it decides
	// something - on the publish that leaves it - and hiding the filter
	// would only stop the client composing a topic it is allowed to send.
	got := readCatalogue(t, c.Catalogue(t, "readings", nil))
	if !slices.Equal(got.Verbs, []string{"write", "read"}) {
		t.Errorf("readings answered verbs %v, want the write and read these roles grant", got.Verbs)
	}
	if got.Filter != "iot/+/{device,sensor}/#" {
		t.Errorf("readings answered filter %q, want the channel's own", got.Filter)
	}

	// The two kinds of no, and they must be indistinguishable.
	real := c.Catalogue(t, "secret", nil)
	invented := c.Catalogue(t, "no-such-channel-at-all", nil)
	if real.Payload != "" {
		t.Errorf("a channel this client holds nothing on answered %q, want an empty reply", real.Payload)
	}
	if invented.Payload != "" {
		t.Errorf("a channel that does not exist answered %q, want an empty reply", invented.Payload)
	}
}

// RFC 0002 "Asking what a channel is"
//
// Every refusal rides the PUBACK, for the reason a point read's does: the
// reply carries an answer and nothing else, so an empty one can mean one
// thing. Which also means the request must be QoS 1, since QoS 0 has no
// PUBACK to be refused in.
func TestACatalogueRequestRefusesWhatItCannotAnswer(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "readings", Type: channel.Append, Filter: "iot/+/{device,sensor}/#"},
	})
	c := connect(t, h, "asker", true, false)
	c.Sub(t, catalogueReply, 1)

	ack, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: channel.CatalogueTopic("readings"), QoS: 1,
	})
	if ack == nil {
		t.Fatalf("no PUBACK for a catalogue request with no Response Topic: %v", err)
	}
	if ack.ReasonCode != 0x83 {
		t.Errorf("a request with no Response Topic answered 0x%02X, want 0x83", ack.ReasonCode)
	}

	if _, err := c.C.Publish(context.Background(), &paho.Publish{
		Topic: channel.CatalogueTopic("readings"), QoS: 0,
		Properties: &paho.PublishProperties{ResponseTopic: catalogueReply},
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	if r, ok := c.Await(t, time.Second); ok {
		t.Errorf("a QoS 0 catalogue request was answered with %q; it has no PUBACK "+
			"to be refused in", r.Payload)
	}

	// A name with a `/` in it is no channel that could exist, so it is not a
	// catalogue request at all and falls to the reserved-space refusal.
	ack, err = c.C.Publish(context.Background(), &paho.Publish{
		Topic: "$saguin/catalogue/two/levels", QoS: 1,
		Properties: &paho.PublishProperties{ResponseTopic: catalogueReply},
	})
	if ack == nil {
		t.Fatalf("no PUBACK for a catalogue request naming two levels: %v", err)
	}
	if ack.ReasonCode != 0x90 {
		t.Errorf("a name holding a `/` answered 0x%02X, want 0x90", ack.ReasonCode)
	}

	// And the same request done properly still works, so every refusal
	// above is about what was wrong with it rather than about the verb.
	if got := readCatalogue(t, c.Catalogue(t, "readings", nil)); got.Name != "readings" {
		t.Errorf("a well-formed request answered %+v", got)
	}
}

// RFC 0002 "Asking what a channel is"
//
// Every reply carries Correlation Data: the caller's when it set some, and
// otherwise the name it asked about. A client with several questions
// outstanding can tell the answers apart without keeping a table.
func TestACatalogueAnswerAlwaysSaysWhatItIsAnswering(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "readings", Type: channel.Append, Filter: "iot/+/{device,sensor}/#"},
	})
	c := connect(t, h, "asker", true, false)

	if got := string(c.Catalogue(t, "readings", nil).CorrData); got != "readings" {
		t.Errorf("a request that set no Correlation Data was answered with %q, want the name", got)
	}
	if got := string(c.Catalogue(t, "readings", []byte("mine-7")).CorrData); got != "mine-7" {
		t.Errorf("a request that set Correlation Data was answered with %q, want mine-7", got)
	}
	// An empty answer says what it is about too, or a client asking about
	// several channels cannot tell which of them it was told nothing about.
	if got := string(c.Catalogue(t, "nothing-here", nil).CorrData); got != "nothing-here" {
		t.Errorf("an empty answer carried %q, want the name asked about", got)
	}
}

// RFC 0002 "Asking what a channel is"
//
// The reply goes to the session that asked and to nobody else: it is written
// to the asking connection, so the asker needs no subscription to its own
// response topic and a third party subscribed to that topic is told nothing.
//
// **This needs a test of its own because the obvious one cannot see it.** A
// client that both asks and subscribes passes whichever way the broker sends
// the answer, and that is every other test here.
func TestACatalogueAnswerReachesOnlyTheSessionThatAsked(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "readings", Type: channel.Append, Filter: "iot/+/{device,sensor}/#"},
	})
	asker := connect(t, h, "asker", true, false)
	listener := connect(t, h, "listener", true, false)
	listener.Sub(t, catalogueReply, 1)

	// The asker never subscribes, and is answered anyway.
	if got := readCatalogue(t, asker.Catalogue(t, "readings", nil)); got.Name != "readings" {
		t.Errorf("the asker was answered %+v", got)
	}
	if r, ok := listener.Await(t, time.Second); ok {
		t.Errorf("a third client subscribed to the reply topic received %q on %q",
			r.Payload, r.Topic)
	}
}

// RFC 0003 "Durable consumers", invariant 1
//
// **A replay steps over records that match none of the consumer's filters**,
// necessarily: a record for somebody else would otherwise be re-read for
// ever. What that made possible was a gap served in silence - one SUBSCRIBE
// naming two filters was fed inside the loop that recorded them, so the
// first filter's replay walked the whole channel while it was the only
// filter recorded, stepped over every record that only the second matched,
// and moved the position past them. The consumer then received everything
// after the gap and could only conclude it had seen the lot.
//
// **This is the ordinary shape rather than an odd one.** A channel whose
// filter carries a `{a,b}` level is read with one filter per alternative,
// because a `+` there would also reach topics beside the channel - so any
// client reading such a channel by name does exactly this.
//
// The controls are what make it a test of the gap rather than of delivery:
// each filter alone still receives only its own records, and the two
// spellings of the pair agree, which is the property that was missing -
// the answer depended on which filter was processed first.
func TestAConsumerReachingOneChannelThroughTwoFiltersIsServedEveryRecord(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "readings", Type: channel.Append, Filter: "iot/+/{device,sensor}/#"},
	})
	p := connect(t, h, "producer", true, false)

	// Published before anybody subscribes, so every read below is a replay
	// from the retention floor rather than a live delivery - which is the
	// path this is about. Live delivery was correct throughout.
	p.Pub(t, "iot/s1/device/a", "A")
	p.Pub(t, "iot/s1/sensor/b", "B")
	p.Pub(t, "iot/s1/device/c", "C")
	time.Sleep(300 * time.Millisecond)

	replay := func(t *testing.T, id string, filters []string) []string {
		t.Helper()
		c := connectDurable(t, h, id)
		if len(filters) == 1 {
			c.Sub(t, filters[0], 1)
		} else {
			for i, code := range c.SubMany(t, filters, 1) {
				if code > 2 {
					t.Fatalf("filter %d (%s) was refused 0x%02X", i, filters[i], code)
				}
			}
		}
		var got []string
		for {
			r, ok := c.Await(t, 2*time.Second)
			if !ok {
				return got
			}
			got = append(got, r.Payload)
		}
	}

	t.Run("both filters in one SUBSCRIBE", func(t *testing.T) {
		if got := replay(t, "both", []string{"iot/s1/device/#", "iot/s1/sensor/#"}); !slices.Equal(
			got, []string{"A", "B", "C"}) {
			t.Errorf("received %v, want every record in offset order: [A B C]", got)
		}
	})

	// **The same two filters, named the other way round.** The defect was
	// an order dependency, so a test that only ever sends them one way
	// passes against half of it.
	t.Run("the same two, named in the other order", func(t *testing.T) {
		if got := replay(t, "reversed", []string{"iot/s1/sensor/#", "iot/s1/device/#"}); !slices.Equal(
			got, []string{"A", "B", "C"}) {
			t.Errorf("received %v, want every record in offset order: [A B C]", got)
		}
	})

	t.Run("one filter covering both", func(t *testing.T) {
		if got := replay(t, "wide", []string{"iot/s1/#"}); !slices.Equal(
			got, []string{"A", "B", "C"}) {
			t.Errorf("received %v, want [A B C]", got)
		}
	})

	// The controls: a consumer is still served only what its filters reach.
	t.Run("one filter is served only its own records", func(t *testing.T) {
		if got := replay(t, "device-only", []string{"iot/s1/device/#"}); !slices.Equal(
			got, []string{"A", "C"}) {
			t.Errorf("received %v, want only the device records: [A C]", got)
		}
		if got := replay(t, "sensor-only", []string{"iot/s1/sensor/#"}); !slices.Equal(
			got, []string{"B"}) {
			t.Errorf("received %v, want only the sensor record: [B]", got)
		}
	})
}

// RFC 0003 "The reserved prefix on a
// client's own packets"
//
// **The prefix is the broker's, and a publisher was able to write it.** A
// channel delivery has always stripped `saguin-` and restamped its own, so
// a consumer can trust `saguin-offset`. Broadcast did not: the strip lived
// below fanOut's first return and a broadcast publish left through it, so
// a client could publish `saguin-offset 999` and have a subscriber receive
// it as though saguin had written it. A wide filter spans channel and
// broadcast space and a delivery does not say which half it came from,
// which is what makes the forgery worth anything.
//
// **Both paths, because the store kept what the wire carried.** The stored
// copy deliberately matched the live one, so the retained handover put the
// same forgery in front of every later subscriber - the lie outliving the
// connection that told it. The test gap was that nothing
// published a reserved property to a plain broadcast topic and read what
// came back.
func TestAPublisherCannotForgeBrokerMetadataOnBroadcast(t *testing.T) {
	h := startRetaining(t, 0)

	forged := &paho.PublishProperties{User: paho.UserProperties{
		{Key: "saguin-forged", Value: "x"},
		{Key: "saguin-channel", Value: "events"},
		{Key: "saguin-offset", Value: "999"},
		{Key: "saguin-id", Value: "not-a-message-id"},
		{Key: "app-key", Value: "kept"},
	}}

	// **Live fan-out.**
	live := connect(t, h, "forge-live", true, false)
	live.Sub(t, "loose/#", 1)
	subscribed(t, live.C)

	p := connect(t, h, "forge-pub", true, false)
	if _, err := p.C.Publish(context.Background(), &paho.Publish{
		Topic: "loose/forge", QoS: 1, Retain: true,
		Payload: []byte("r"), Properties: forged,
	}); err != nil {
		t.Fatalf("publish: %v", err)
	}
	awaitCount(t, live, 1, 5*time.Second)

	got := live.All()
	if len(got) != 1 {
		t.Fatalf("the live subscriber received %d messages, want 1: this test "+
			"asserts what a delivery carries and needs one to look at", len(got))
	}
	assertNoForgery(t, "the live fan-out", got[0].User)

	// **The retained handover**, which is the same forgery to every
	// subscriber that arrives later.
	late := connect(t, h, "forge-late", true, false)
	late.Sub(t, "loose/#", 1)
	awaitCount(t, late, 1, 5*time.Second)

	got = late.All()
	if len(got) != 1 {
		t.Fatalf("the late subscriber received %d retained messages, want 1: "+
			"without one the assertion below examines nothing", len(got))
	}
	assertNoForgery(t, "the retained handover", got[0].User)
}

// A Will armed over a WebSocket fires when that connection drops, and
// arrives carrying every property it declared.
//
// **The transport is the point.** TestAWillKeepsEveryPublishPropertyItCarried
// holds the properties over TCP, across broadcast and a channel, immediate
// and delayed. Nothing held them over a WebSocket, and a Will is not
// published by anything the client does: it is published because the broker
// noticed the connection end. On TCP that is a read returning an error;
// over a WebSocket it is gorilla reporting a closed frame stream, one layer
// up and a different piece of code. A regression there would mean Wills
// silently never firing for browser clients, and nothing else would notice
// - the connection closes either way, and what goes missing is a message
// nobody is waiting for.
func TestAWillOverAWebSocketFiresWithItsProperties(t *testing.T) {
	h := startWith(t, "ws", "", "")

	watch, err := dialWS(h.Addr)
	if err != nil {
		t.Fatalf("dial the watcher: %v", err)
	}
	defer watch.Close()

	const topic = "house/ws/status"
	expect := func(conn net.Conn, want byte, what string) []byte {
		t.Helper()
		_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
		fh, body, err := readRawPacket(conn)
		if err != nil {
			t.Fatalf("read %s: %v", what, err)
		}
		if fh>>4 != want {
			t.Fatalf("expected %s, got packet type %d", what, fh>>4)
		}
		return body
	}

	if _, err := watch.Write(willConnectBytes("ws-watcher", "", 0)); err != nil {
		t.Fatalf("watcher connect: %v", err)
	}
	expect(watch, packets.Connack, "the watcher's CONNACK")

	// SUBSCRIBE: packet id 1, no properties, one filter at QoS 0.
	sub := []byte{0x00, 0x01, 0x00}
	sub = append(sub, byte(len(topic)>>8), byte(len(topic)))
	sub = append(sub, topic...)
	sub = append(sub, 0x00)
	if _, err := watch.Write(mqttPacket(0x82, sub)); err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	expect(watch, packets.Suback, "the SUBACK")

	dier, err := dialWS(h.Addr)
	if err != nil {
		t.Fatalf("dial the dying client: %v", err)
	}
	if _, err := dier.Write(willConnectBytes("ws-dier", topic, 0)); err != nil {
		t.Fatalf("will client connect: %v", err)
	}
	expect(dier, packets.Connack, "the will client's CONNACK")

	// The frame stream ends with no WebSocket close and no MQTT DISCONNECT,
	// which is what a browser tab closing looks like.
	if wc, ok := dier.(*wsConn); ok {
		_ = wc.UnderlyingConn().Close()
	} else {
		_ = dier.Close()
	}

	body := expect(watch, packets.Publish, "the Will")
	var pk packets.Packet
	pk.ProtocolVersion = 5
	pk.FixedHeader = packets.FixedHeader{Type: packets.Publish, Remaining: len(body)}
	if err := pk.PublishDecode(body); err != nil {
		t.Fatalf("the delivered Will did not decode: %v", err)
	}

	if pk.TopicName != topic {
		t.Fatalf("the Will reached %q, want %q", pk.TopicName, topic)
	}
	if string(pk.Payload) != "i-died" {
		t.Fatalf("payload %q, want \"i-died\"", pk.Payload)
	}

	// Every property willConnectBytes declared, the same list the TCP test
	// asserts one transport down.
	pr := pk.Properties
	if pr.ContentType != "application/json" {
		t.Errorf("content type %q: these bytes cannot find out what they are", pr.ContentType)
	}
	if !pr.PayloadFormatFlag || pr.PayloadFormat != 1 {
		t.Errorf("payload format indicator %v/%d, want set and UTF-8",
			pr.PayloadFormatFlag, pr.PayloadFormat)
	}
	if pr.ResponseTopic != "where/to/answer" {
		t.Errorf("response topic %q: this Will has nowhere to answer", pr.ResponseTopic)
	}
	if string(pr.CorrelationData) != "ticket-7" {
		t.Errorf("correlation data %q, want ticket-7", pr.CorrelationData)
	}
	if pr.MessageExpiryInterval != 60 {
		t.Errorf("message expiry %d, want 60: a Will asking to expire became one that never does",
			pr.MessageExpiryInterval)
	}
	if len(pr.User) != 1 || pr.User[0].Key != "tenant" || pr.User[0].Val != "acme" {
		t.Errorf("user properties %v, want one tenant=acme", pr.User)
	}
}

// RFC 0003 "Last Will", MQTT 5 section 3.1.3.2.2: a server delays a Will
// "until the Will Delay Interval has passed or the Session ends, whichever
// happens first". Both halves are the rule, and the second was missing.
//
// **A session that ends with its connection ends at the disconnect**, so its
// Will is due then however long its interval says. Without this a device
// connecting with Clean Start and a five-minute delay is announced dead five
// minutes later, on a session the broker threw away at the disconnect - an
// announcement about a session that no longer exists, arriving long after
// anything could act on it. Measured before the fix: a 30-second delay, the
// connection cut, and nothing published in the five seconds after.
//
// **A session shorter than the interval ends first too**, which is the same
// rule read the other way: a Will held past its session is a Will held for
// nobody. The substrate caps the interval at the expiry the client asked for;
// what it cannot know is `limits.max_session_expiry`, which is what the
// session was actually granted - so a client asking for an hour on a broker
// that grants a minute had its Will held for the hour.
func TestAWillIsDueWhenItsSessionEndsIfThatIsSooner(t *testing.T) {
	for _, tc := range []struct {
		name   string
		expiry uint32
		delay  uint32
	}{
		// The first is the half saguin had to add: a client that sends no
		// Session Expiry Interval at all, whose session therefore ends with
		// its connection. The second is the substrate's own cap, which is
		// here because the rule is one rule and a test for half of it
		// would go green on a broker that lost the other half.
		{"a session that ends with its connection", 0, 30},
		{"a session shorter than the delay", 1, 30},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := startRetaining(t, 0)
			watch := dialProps(t, h, "watcher")
			watch.Sub(t, "house/#", 1)
			time.Sleep(200 * time.Millisecond)

			conn := willConnectWithExpiry(t, h, "device", "house/device/gone", tc.delay, tc.expiry)
			time.Sleep(200 * time.Millisecond)
			kill(t, conn)

			// Well inside the interval the client asked for, and outside the
			// session's own life.
			select {
			case r := <-watch.Ch:
				if r.Topic != "house/device/gone" {
					t.Fatalf("received %q, want the Will", r.Topic)
				}
			case <-time.After(8 * time.Second):
				t.Fatalf("no Will within 8s of the session ending, on a %d second delay: it is "+
					"waiting out an interval its session will not outlive", tc.delay)
			}
		})
	}

	// And the one the substrate cannot cap, because it is saguin's: a client
	// asking for a long session on a broker that grants a short one. The
	// session ends when the grant says, so the Will is due then.
	t.Run("a session the broker shortened", func(t *testing.T) {
		brokertest.MaxSessionExpiry = 1
		t.Cleanup(func() { brokertest.MaxSessionExpiry = 0 })
		h := startRetaining(t, 0)
		watch := dialProps(t, h, "watcher")
		watch.Sub(t, "house/#", 1)
		time.Sleep(200 * time.Millisecond)

		conn := willConnectWithExpiry(t, h, "device", "house/device/gone", 30, 3600)
		time.Sleep(200 * time.Millisecond)
		kill(t, conn)

		select {
		case r := <-watch.Ch:
			if r.Topic != "house/device/gone" {
				t.Fatalf("received %q, want the Will", r.Topic)
			}
		case <-time.After(8 * time.Second):
			t.Fatal("no Will within 8s: the client asked for an hour of session and was granted " +
				"a second, and its Will is being held for the hour it asked for")
		}
	})
}

// TestWhatARestartServesAgainIsOnlyWhatWasNeverAcknowledged forces the
// duplicate `TestA311DurableConsumerResumesAcrossARestart` produced once
// during the Wills work, where a durable consumer was served its first
// record live and again after a restart. That run was timing-dependent and
// never reproduced, which is why nothing was concluded from it: this pair
// asks the question by construction instead.
//
// **The two arms are the whole question.** A record the consumer never
// acknowledged must be served again, because that is at-least-once doing
// its job and the stored position is the lowest offset not yet
// acknowledged (RFC 0003). A record it acknowledged, whose position reached
// the store, must never be served again - that one is a duplicate
// delivery, and the dangerous half.
//
// Both assert on `saguin-offset` rather than on the payload, because a
// duplicate is the same record arriving twice and only the offset says so.
// The committed position is read back from the store rather than waited
// for by sleeping, so the arm that must not duplicate cannot pass by
// having crashed before the acknowledgement was ever going to land.
func TestWhatARestartServesAgainIsOnlyWhatWasNeverAcknowledged(t *testing.T) {
	const consumer = "durable-consumer"

	// arm runs the whole shape once and answers what the restart served,
	// or "" where it served nothing.
	arm := func(t *testing.T, acknowledge bool) (delivered, afterRestart string) {
		t.Helper()
		path := filepath.Join(t.TempDir(), "saguin.db")
		h := startDurableSQLite(t, path)

		p := connect(t, h, "producer", true, false)
		c := connect(t, h, consumer, false, true) // durable session, manual PUBACK
		c.Sub(t, "events/#", 1)
		p.Pub(t, "events/orders/1", "first")

		r, ok := c.Await(t, 5*time.Second)
		if !ok {
			t.Fatal("the durable consumer was served nothing while connected")
		}
		delivered = r.User["saguin-offset"]
		if delivered == "" {
			t.Fatal("the delivery carried no saguin-offset, so nothing here can tell " +
				"a duplicate from a second record")
		}

		if acknowledge {
			r.Ack()
			// Proof from the store, not a sleep: the position is the lowest
			// offset not yet acknowledged, so it passes this record once the
			// acknowledgement is durable.
			want, err := strconv.ParseUint(delivered, 10, 64)
			if err != nil {
				t.Fatalf("saguin-offset %q: %v", delivered, err)
			}
			lg, err := h.DB.Log("events")
			if err != nil {
				t.Fatalf("opening the events log: %v", err)
			}
			deadline := time.After(10 * time.Second)
			for {
				pos, ok, err := lg.Position(store.MQTTReader(consumer))
				if err != nil {
					t.Fatalf("reading the stored position: %v", err)
				}
				if ok && pos.Offset > want {
					break
				}
				select {
				case <-deadline:
					t.Fatalf("the position never passed offset %d after the acknowledgement "+
						"(stored ok=%v offset=%d): an acknowledged record whose position "+
						"never reaches the store is served again by every restart",
						want, ok, pos.Offset)
				case <-time.After(50 * time.Millisecond):
				}
			}
		}

		// No orderly shutdown: what is served now came from the store.
		h.Crash()
		h2 := startDurableSQLite(t, path)

		c2 := connect(t, h2, consumer, false, true)
		if !c2.SessionPresent {
			t.Fatal("the restart did not put the consumer's session back, so nothing " +
				"below is about what a resumed session is served")
		}
		c2.Sub(t, "events/#", 1)
		if again, ok := c2.Await(t, 3*time.Second); ok {
			afterRestart = again.User["saguin-offset"]
			again.Ack()
		}

		// **What makes "nothing was served" mean anything.** A consumer that
		// cannot be served at all would look exactly like one correctly not
		// served its own acknowledged record, so the arm proves the pipe is
		// open before it reports the silence: a record published now must
		// arrive, and at a different offset.
		p2 := connect(t, h2, "producer-after", true, false)
		p2.Pub(t, "events/orders/2", "after the restart")
		fresh, ok := c2.Await(t, 5*time.Second)
		if !ok {
			t.Fatal("nothing reached the consumer after the restart at all, so this arm " +
				"proves nothing about what a restart does or does not serve again")
		}
		if got := fresh.User["saguin-offset"]; got == delivered {
			t.Fatalf("the record published after the restart arrived at offset %q, the "+
				"same offset as the one before it: the offsets cannot tell two records "+
				"apart, and neither can this test", got)
		}
		fresh.Ack()
		return delivered, afterRestart
	}

	t.Run("never acknowledged, so it is served again", func(t *testing.T) {
		delivered, afterRestart := arm(t, false)
		if afterRestart != delivered {
			t.Errorf("a record the consumer never acknowledged was at offset %q and the "+
				"restart served %q: at-least-once owes it that record again",
				delivered, afterRestart)
		}
	})

	t.Run("acknowledged and committed, so it is never served again", func(t *testing.T) {
		delivered, afterRestart := arm(t, true)
		if afterRestart != "" {
			t.Errorf("offset %q was acknowledged and its position reached the store, and "+
				"the restart served offset %q: a committed record delivered twice is a "+
				"duplicate, not at-least-once", delivered, afterRestart)
		}
	})
}

// TestAGroupHoldsWhatItsAbsentMembersAreOwed is step 12's whole promise: a
// shared group whose members are away is owed the work that matched it, and
// the first member back is served it in order.
//
// **On both providers**, because where a backlog lives is the operator's
// decision and the promise cannot differ between them.
func TestAGroupHoldsWhatItsAbsentMembersAreOwed(t *testing.T) {
	eachSessionProvider(t, func(t *testing.T, h *harness) {
		// **A broadcast topic, claimed by no channel, which is the whole of
		// what a backlog is for.** A shared group over a channel is served
		// from that channel, whose records are already kept; a broadcast
		// delivery has nowhere else to live, so an absent group either
		// holds it or loses it.
		const group = "$share/fleet/alerts/#"

		// A member with a session that outlives its connection, then gone.
		worker := connect(t, h, "worker-a", false, false)
		worker.Sub(t, group, 1)
		worker.Close()
		// Gone before the publish, or it goes live to the member leaving.
		sessionGone(t, h, "worker-a")

		p := connect(t, h, "producer", true, false)
		for _, payload := range []string{"one", "two", "three"} {
			p.Pub(t, "alerts/door", payload)
		}

		// Held rather than dropped, and held in the store rather than in
		// memory: the test reads the store, not a counter.
		backlog := waitForBacklog(t, group, 3)
		if got := backlogPayloads(backlog); got != "one two three " {
			t.Fatalf("the group holds %q, want the three deliveries in order", got)
		}

		// And the first member back is served them, in that order.
		back := connect(t, h, "worker-a", false, false)
		var got []string
		for i := 0; i < 3; i++ {
			r, ok := back.Await(t, 5*time.Second)
			if !ok {
				t.Fatalf("the member back from an outage was served %d of 3 held deliveries: %v",
					i, got)
			}
			got = append(got, r.Payload)
		}
		if strings.Join(got, " ") != "one two three" {
			t.Errorf("the member was served %v, want them in the order they were held", got)
		}
		if left := waitForBacklog(t, group, 0); len(left) != 0 {
			t.Errorf("%d deliveries are still held after the member took them: a drain that "+
				"does not remove what it served serves it again at every restart", len(left))
		}
	})
}

// TestWhatAGroupHoldsDependsOnWhetherAnybodyIsComingBack is the ruling that
// decides what a backlog is for: a hold needs a session that can come back
// to collect it.
//
// **Both arms keep the member connected and unable to take the delivery**,
// its in-flight window full with one it has not acknowledged. That is the
// case the ruling actually governs: a member whose session ends with its
// connection leaves the subscription index when it goes, so a group with
// nobody left is not a group the publish path can even see - a test that
// disconnected such a member would pass whatever the rule said.
func TestWhatAGroupHoldsDependsOnWhetherAnybodyIsComingBack(t *testing.T) {
	for _, arm := range []struct {
		name       string
		expiry     uint32
		wantHeld   int
		wantReason string
	}{
		{"a session that outlives its connection", 3600, 1,
			"its member is coming back for it"},
		{"a session that ends with its connection", 0, 0,
			"nobody it belongs to will ever collect it"},
	} {
		t.Run(arm.name, func(t *testing.T) {
			eachSessionProvider(t, func(t *testing.T, h *harness) {
				const group = "$share/one/alerts/#"

				// Receive Maximum 1 and a manual acknowledgement: the first
				// delivery fills the window and the member can take no more.
				member := dial(t, h, "only-member", true, true, 1, arm.expiry, 0)
				member.Sub(t, group, 1)

				p := connect(t, h, "producer", true, false)
				p.Pub(t, "alerts/door", "first")
				first, ok := member.Await(t, 5*time.Second)
				if !ok {
					t.Fatal("the member was served nothing, so its window is not full and " +
						"nothing below is about a group that cannot be served")
				}

				p.Pub(t, "alerts/door", "second")

				// **Read through the member rather than only the store**, so
				// that "nothing was held" cannot pass by being read before
				// the publish was processed: the window is opened, and what
				// the group was holding either arrives or never existed.
				first.Ack()
				second, served := member.Await(t, 2*time.Second)

				backlog, err := brokertest.HarnessShares.Backlog(group)
				if err != nil {
					t.Fatal(err)
				}
				if arm.wantHeld == 0 {
					if served {
						t.Errorf("the member was served %q after its window opened, so the "+
							"delivery was held: %s", second.Payload, arm.wantReason)
					}
					if len(backlog) != 0 {
						t.Errorf("the group holds %d deliveries, want none: %s",
							len(backlog), arm.wantReason)
					}
					return
				}
				if !served {
					t.Errorf("the member was served nothing after its window opened, and the "+
						"group holds %d: a backlog nothing drains is work lost quietly",
						len(backlog))
				} else if second.Payload != "second" {
					t.Errorf("the member was served %q, want the delivery held while it was "+
						"full", second.Payload)
				}
				if len(backlog) != 0 {
					t.Errorf("%d deliveries are still held after the member took them: a drain "+
						"that does not remove what it served serves it again", len(backlog))
				}
			})
		})
	}
}

// TestAGroupHoldsNothingAtQoS0 is the other half of the same rule. A QoS 0
// delivery is owed to nobody by anything, so holding one would invent a
// promise MQTT does not make.
func TestAGroupHoldsNothingAtQoS0(t *testing.T) {
	eachSessionProvider(t, func(t *testing.T, h *harness) {
		const group = "$share/fleet/alerts/#"

		worker := connect(t, h, "worker-q0", false, false)
		worker.Sub(t, group, 1)
		worker.Close()

		p := connect(t, h, "producer", true, false)
		if _, err := p.C.Publish(context.Background(), &paho.Publish{
			Topic: "alerts/door", QoS: 0, Payload: []byte("reading"),
		}); err != nil {
			t.Fatalf("publish at QoS 0: %v", err)
		}

		time.Sleep(300 * time.Millisecond)
		if backlog, err := brokertest.HarnessShares.Backlog(group); err != nil || len(backlog) != 0 {
			t.Errorf("a group holds %d QoS 0 deliveries (err=%v), want none", len(backlog), err)
		}
	})
}

// TestAGroupsBacklogGoesWhenItsLastMemberSessionEnds is the running
// broker's own door, the one the Wills taught: the sweep that ends the last
// member's session takes the backlog with it at that moment, not at the
// next restart. A door that ends the last member and leaves its backlog
// behind is a leak only a restart would ever report.
func TestAGroupsBacklogGoesWhenItsLastMemberSessionEnds(t *testing.T) {
	eachSessionProvider(t, func(t *testing.T, h *harness) {
		const group = "$share/short/alerts/#"

		// A session that outlives its connection by two seconds, no longer.
		worker := dial(t, h, "worker-short", false, false, 0, 2, 0)
		worker.Sub(t, group, 1)
		worker.Close()
		// Gone before the publish, or it goes live to the member leaving.
		sessionGone(t, h, "worker-short")

		p := connect(t, h, "producer", true, false)
		p.Pub(t, "alerts/door", "work")
		if backlog := waitForBacklog(t, group, 1); len(backlog) != 1 {
			t.Fatalf("the group holds %d deliveries, want the one its absent member is owed",
				len(backlog))
		}

		// When that session expires, nobody is owed the backlog any more.
		deadline := time.After(10 * time.Second)
		for {
			backlog, err := brokertest.HarnessShares.Backlog(group)
			if err != nil {
				t.Fatal(err)
			}
			if len(backlog) == 0 {
				return
			}
			select {
			case <-deadline:
				t.Fatalf("the group still holds %d deliveries after its last member session "+
					"expired: the backlog outlived everybody who could collect it", len(backlog))
			case <-time.After(100 * time.Millisecond):
			}
		}
	})
}

// TestAGroupsBacklogIsServedOnceWhenItsMembersComeBackTogether is the rule
// a shared group exists for: MQTT 5 §4.8.2 sends a message on a shared
// subscription to one member of the group, and a backlog held while the
// fleet was away does not suspend that. Two members returning in the same
// instant must not each be served the whole of it.
//
// **The duplicate this forbids is silent.** Every counter agrees with
// itself while it happens - drained rises with what went out, nothing is
// dropped, the backlog empties - so the only instrument that can see it is
// one that counts what the members actually received, across the group
// rather than per member.
//
// Four members rather than two: the drain reads the whole backlog before
// it serves any of it, so what returns together is what multiplies, and a
// pair would measure the smallest version of it.
func TestAGroupsBacklogIsServedOnceWhenItsMembersComeBackTogether(t *testing.T) {
	eachSessionProvider(t, func(t *testing.T, h *harness) {
		const (
			group   = "$share/together/alerts/#"
			members = 4
			held    = 200
		)

		ids := make([]string, members)
		for i := range ids {
			ids[i] = fmt.Sprintf("together-%d", i)
			w := dial(t, h, ids[i], true, false, 0, 3600, 0)
			w.Sub(t, group, 1)
			w.Close()
			sessionGone(t, h, ids[i])
		}

		p := connect(t, h, "together-producer", true, false)
		for i := 0; i < held; i++ {
			p.Pub(t, "alerts/door", fmt.Sprintf("job-%03d", i))
		}
		if backlog := waitForBacklog(t, group, held); len(backlog) != held {
			t.Fatalf("the group holds %d deliveries, want the %d its absent members are owed: "+
				"nothing below is about a backlog several members come back to", len(backlog), held)
		}

		// **The same instant, as a fleet behind one link coming back is.**
		// Each member connects on its own goroutine, all released together,
		// and a resumed session drains without a SUBSCRIBE - so these are
		// four drains over one backlog rather than four in a queue.
		start := make(chan struct{})
		back := make([]*client, members)
		var wg sync.WaitGroup
		for i := range ids {
			wg.Add(1)
			go func(i int) {
				defer wg.Done()
				<-start
				back[i] = dial(t, h, ids[i], false, false, 0, 3600, 0)
			}(i)
		}
		close(start)
		wg.Wait()

		for i, c := range back {
			if !c.SessionPresent {
				t.Fatalf("member %s came back to no session, so it was never owed the backlog "+
					"and this test is not about several members draining one", ids[i])
			}
		}

		// Deliveries stop arriving before they are counted: the total is
		// read until it stands still, so a count taken mid-drain cannot
		// read as agreement.
		total, stable := 0, 0
		deadline := time.After(30 * time.Second)
		for {
			n := 0
			for _, c := range back {
				n += c.Count()
			}
			if n == total {
				stable++
			} else {
				total, stable = n, 0
			}
			if stable >= 10 && total > 0 {
				break
			}
			select {
			case <-deadline:
				t.Fatalf("deliveries were still arriving after 30s (%d so far)", n)
			case <-time.After(100 * time.Millisecond):
			}
		}

		// Counted across the group, never per member: a member's own tally
		// says nothing about whether its neighbour was served the same work.
		at := map[string][]string{}
		for i, c := range back {
			for _, r := range c.Payloads() {
				at[r] = append(at[r], ids[i])
			}
		}
		twice := 0
		example := ""
		for payload, who := range at {
			if len(who) > 1 {
				twice++
				if example == "" {
					sort.Strings(who)
					example = fmt.Sprintf("%s reached %v", payload, who)
				}
			}
		}
		if twice > 0 {
			t.Errorf("%d of %d held deliveries were served to more than one member of the group "+
				"(for example %s): a shared subscription sends a message to one member "+
				"[MQTT 5 §4.8.2], so this is work done twice by a fleet that was told nothing",
				twice, held, example)
		}
		if total != held {
			t.Errorf("the group received %d deliveries of the %d it was owed: a backlog served "+
				"more times than it was held is duplicated work, and served fewer is work lost",
				total, held)
		}
		if len(at) != held {
			t.Errorf("%d distinct deliveries reached the group, want %d: the backlog was not "+
				"served whole", len(at), held)
		}
		if backlog, err := brokertest.HarnessShares.Backlog(group); err != nil || len(backlog) != 0 {
			t.Errorf("the group still holds %d deliveries after every member came back (err=%v)",
				len(backlog), err)
		}
	})
}

// **A link that came back says so at the level it said it was down.**
//
// `bridge link down` is a Warn and its retraction was an Info, so an
// operator running at `broker.log_level: warn` - a level the configuration
// offers - was told the link had failed and never told it had returned. The
// log then asserted a broken bridge for the life of the process: a reader
// looking at a week-old broker found a warning about an outage that ended in
// the first minute.
//
// The rule this pins is general rather than about these two lines: a line
// that retracts another is written at the level of the line it retracts,
// because a level is a severity filter and not a subject one. Driven through
// a real cut link, because what is asserted is which lines an operator
// actually sees.
func TestALinkThatCameBackSaysSoAtTheLevelItSaidItWasDown(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)
	link := newProxy(t, upstreamAddr)
	cfg := bridgeConfig(t, link.Addr)

	var mu sync.Mutex
	var logged strings.Builder
	log := slog.New(slog.NewTextHandler(&lockedWriter{Mu: &mu, W: &logged},
		&slog.HandlerOptions{Level: slog.LevelWarn}))
	read := func() string {
		mu.Lock()
		defer mu.Unlock()
		return logged.String()
	}
	await := func(what string) bool {
		for deadline := time.Now().Add(20 * time.Second); time.Now().Before(deadline); {
			if strings.Contains(read(), what) {
				return true
			}
			time.Sleep(20 * time.Millisecond)
		}
		return false
	}

	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits, log, nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})
	waitForBridge(t, upstream, cfg.ClientID)

	// Cut it, and wait for the broker to say so.
	link.Cut()
	if !await("bridge link down") {
		t.Fatalf("nothing said the link was down at `warn`, so the assertion below is "+
			"about a pair whose first half never happened. The log was:\n%s", read())
	}

	// Restore it. The line that takes the warning back must be readable
	// here, at the level that reported it.
	link.Restore()
	if !await("bridge link up again") {
		t.Errorf("the link came back and nothing said so at `warn`: an operator at this "+
			"level is left holding a warning that stopped being true. The log was:\n%s",
			read())
	}
}

// **A bridge whose rules only write connects, and exports.**
//
// A SUBSCRIBE must carry at least one topic filter [MQTT-3.8.3-2]. An
// out-only bridge built its SUBSCRIBE from the rules that *read*, found
// none, and sent the empty packet anyway - so the peer hung up on a
// protocol violation and the link never came up. Measured against saguin
// ("protocol violation: must contain at least one filter") and against
// mosquitto 2.0.22 ("disconnected due to malformed packet"), each looping
// every ten seconds for ever while nothing was exported.
//
// **It is the topology RFC 0002 recommends**: edge to hub to cloud works
// when the links dial toward the cloud, which is out-only rules at the edge
// and the hub. `--check-config` accepted such a file and printed what it
// would reach, and the only sign anything was wrong was a warning loop.
//
// What hid it: every other bridge test uses `in` or `both`, and the
// outbound unit tests drive the drain against an in-process stand-in that
// never sends a SUBSCRIBE at a listener enforcing the rule. So this one is
// deliberately end-to-end against a real listener - the assertion is that
// the peer accepted the connection and the record arrived, which is exactly
// what an empty SUBSCRIBE prevents.
func TestABridgeThatOnlyWritesConnectsAndExports(t *testing.T) {
	upstream, upstreamAddr := startUpstream(t)
	h := start(t)

	yaml := fmt.Sprintf(`broker:
  id: t
`+memStorage+`channels:
  events:
    type: append
bridges:
  to-cloud:
    peer: tcp://%s
    client_id: edge-exporter
    topics:
      - filter: events/#
        topic: from-edge/$#
        direction: out
`, upstreamAddr)
	path := filepath.Join(t.TempDir(), "saguin.yaml")
	if err := os.WriteFile(path, []byte(yaml), 0o600); err != nil {
		t.Fatalf("write the configuration: %v", err)
	}
	f, _, err := config.Load(path)
	if err != nil {
		t.Fatalf("the test's own configuration does not load: %v", err)
	}
	cfg := f.BridgeSet()[0]

	// What the peer was sent, read at the peer rather than inferred from
	// this side: the defect was invisible from here, where every publish
	// was acknowledged and the position stayed honest.
	var mu sync.Mutex
	var got []string
	if err := upstream.Subscribe("from-edge/#", 1, func(_ *mqtt.Client, _ packets.Subscription, pk packets.Packet) {
		mu.Lock()
		defer mu.Unlock()
		got = append(got, pk.TopicName+" "+string(pk.Payload))
	}); err != nil {
		t.Fatalf("subscribe at the peer: %v", err)
	}
	seen := func() []string {
		mu.Lock()
		defer mu.Unlock()
		return append([]string(nil), got...)
	}

	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	if testing.Verbose() {
		log = slog.New(slog.NewTextHandler(newTestWriter(t), &slog.HandlerOptions{Level: slog.LevelInfo}))
	}
	link := h.B.NewBridgeClient(cfg.Name)
	br := bridge.New(cfg, link, limits, log, link)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})

	// The connection itself is the first assertion: with the empty
	// SUBSCRIBE the peer refused it and this never arrived.
	awaitRegistered(t, upstream, cfg.ClientID, 10*time.Second)

	p := connect(t, h, "edge-device", true, false)
	p.Pub(t, "events/fire/kitchen", "smoke")

	for deadline := time.Now().Add(10 * time.Second); time.Now().Before(deadline); {
		if len(seen()) > 0 {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	want := []string{"from-edge/fire/kitchen smoke"}
	if g := seen(); !slices.Equal(g, want) {
		t.Errorf("the peer was sent %v, want %v - an out-only bridge that cannot "+
			"subscribe must still connect and publish, or the pure exporter RFC 0002 "+
			"recommends carries nothing and only a warning loop says so", g, want)
	}
}

// docs/invariants.md 1, and RFC 0003 "`latest`"
//
// A superseded connection's teardown must not take the deliveries the live
// session's SUBSCRIBE has just earned.
//
// **The deliveries a SUBSCRIBE earns wait for its SUBACK** - a latest
// channel's current state, an append channel's replay, the retained
// messages - from the moment they are decided until the SUBACK is on the
// wire, and OnPacketSent sends them. OnDisconnect clears the entry for a
// SUBACK that never reached the wire, which is the bound that keeps a
// closure from outliving the connection that made it. Keyed by client id
// and asked of no owner, that clearing reached the *successor*: a
// superseded teardown landing between the new connection's OnSubscribed
// and its SUBACK deleted what the live session was about to be sent. The
// SUBACK said granted, the client was connected, and the catch-up never
// happened - silently, until it subscribed again, which a device with a
// standing subscription never does. The entry is keyed by the connection
// now, and this holds it there.
//
// **The interleaving is not raced for.** A test hook added after saguin's
// runs inside that window by construction - the substrate stores the entry
// in OnSubscribed, lets go of the id's session lock, encodes and writes the
// SUBACK, then calls OnPacketSent, so a hook on the SUBACK's encode is after
// the entry is stored and before it is read - and it drives a stale
// connection's OnDisconnect there, which takes that lock. The hook says
// whether the entry was still pending when it ran, so a round that missed
// the window cannot pass. The round count below is what the window costs end
// to end otherwise: seen once in ten minutes under `-race`, across 217 cuts.
//
// The value is in the store throughout, which is what tells this apart
// from storage losing state: the same broker answers a point read for the
// same topic in the same round.
func TestASupersededTeardownKeepsTheNewSubscribersCatchUp(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)
	p.Pub(t, "state/device/alpha", "current")

	stale := &staleTeardownHook{b: h.B, id: "device"}
	if err := h.Srv.AddHook(stale, nil); err != nil {
		t.Fatalf("stale teardown hook: %v", err)
	}

	const rounds = 10
	for round := 1; round <= rounds; round++ {
		c := connect(t, h, "device", true, false)
		c.Sub(t, "state/#", 1)

		r, ok := c.Await(t, 3*time.Second)
		if !ok {
			// The value is still there; only the delivery went. Said with
			// the point read beside it, because "never served" and "not
			// stored" are different defects and the failure has to name
			// which one this is.
			got := string(p.KvGet(t, "state/device/alpha", nil).Payload)
			t.Fatalf("round %d: the subscriber was granted state/# and served no "+
				"current state, while a point read of state/device/alpha answered "+
				"%q. A superseded connection's teardown took the deliveries this "+
				"SUBSCRIBE earned", round, got)
		}
		if r.Topic != "state/device/alpha" || r.Payload != "current" {
			t.Fatalf("round %d: served %q on %q, want \"current\" on "+
				"state/device/alpha", round, r.Payload, r.Topic)
		}
		c.Close()
	}

	// What the instrument has to prove about itself: every round drove a
	// stale teardown into the window. Without this the test passes on a
	// build where the hook never fired, which is a test asserting that an
	// ordinary subscribe works.
	if n, in := stale.Fired(); n != rounds || in != rounds {
		t.Fatalf("the stale teardown ran %d times in %d rounds, %d of them while the "+
			"SUBSCRIBE's deliveries were still pending, so this asserted nothing about the "+
			"window it exists to drive", n, rounds, in)
	}
}

// staleTeardownHook runs a superseded connection's OnDisconnect inside the
// window between a live connection's OnSubscribed and its SUBACK.
//
// The client it hands over is a connection that no longer owns the id -
// which is what every superseded teardown is, and is the only thing the
// ownership check can tell apart. It is built here rather than taken from a
// real connection because a real one's teardown cannot be placed: the
// substrate runs it on that connection's own goroutine, whenever the read
// loop notices, which is the coin flip this replaces.
type staleTeardownHook struct {
	mqtt.HookBase
	b  *broker.Broker
	id string

	mu       sync.Mutex
	n        int
	inWindow int
}

func (h *staleTeardownHook) ID() string { return "test-stale-teardown" }

// On the SUBACK's encode rather than in OnSubscribed: the engine holds the
// client id's session lock across OnSubscribed, and a teardown takes it.
func (h *staleTeardownHook) Provides(b byte) bool { return b == mqtt.OnPacketEncode }

func (h *staleTeardownHook) OnPacketEncode(cl *mqtt.Client, pk packets.Packet) packets.Packet {
	if pk.FixedHeader.Type != packets.Suback || cl.ID != h.id {
		return pk
	}
	pending := h.b.SubackPending(cl)
	h.b.OnDisconnect(&mqtt.Client{ID: h.id}, io.EOF, false)
	h.mu.Lock()
	h.n++
	if pending {
		h.inWindow++
	}
	h.mu.Unlock()
	return pk
}

// Fired is how many times the stale teardown ran, and how many of those with
// the SUBSCRIBE's deliveries still pending.
func (h *staleTeardownHook) Fired() (n, inWindow int) {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.n, h.inWindow
}

// docs/invariants.md 3, 4 and 7, and RFC 0003 "`queue` - Attempts, timeout,
// and redelivery"
//
// A superseded connection's teardown returns its own leased work and none
// of the successor's.
//
// **Two live deliveries of one record, out of no configuration and no
// client behaviour.** The teardown asked `d.holder == cl.ID`, and a holder
// is a client id rather than a connection - so a stale teardown answered
// yes for a job the live worker had been handed since the takeover. The
// record went back while that worker was still doing it, the queue offered
// it again, and invariant 3 then discarded whichever of the two answers
// arrived second as superseded and logged it. The job is done twice, one
// result is thrown away, and the acknowledgement, the metrics and the queue
// depth all report success. That is invariant 4's failure with invariant 3
// papering over it.
//
// **The stale connection is built rather than raced for**, which is what
// TestASupersededTeardownRemovesNothing does for the same rule at the
// subscription index: a real takeover runs the old connection's teardown on
// its own goroutine whenever the read loop notices, so placing it inside
// the lease is a coin flip. What a teardown *is* here is a connection that
// no longer owns the id, and that is the only thing the marker can tell
// apart.
func TestASupersededTeardownLeavesTheLiveWorkersJobAlone(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	w := connect(t, h, "worker-1", true, false)
	w.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, w.C)

	p.Pub(t, "jobs/lease", "job-1")

	first, ok := w.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the worker was offered nothing, so nothing was leased to it")
	}
	if first.Payload != "job-1" {
		t.Fatalf("offered %q, want job-1", first.Payload)
	}

	// The live worker holds the record, unanswered. A connection that no
	// longer owns the id tears down - which is every superseded teardown,
	// and is what a takeover leaves behind.
	h.B.OnDisconnect(&mqtt.Client{ID: "worker-1"}, io.EOF, false)

	// Nothing more, and the wait is the whole point: a second offer is what
	// two live deliveries look like from the worker's side. Well inside the
	// visibility timeout, so a redelivery here is the teardown's doing and
	// not the deadline's.
	if again, ok := w.Await(t, visibility-500*time.Millisecond); ok {
		t.Fatalf("the live worker was offered %q a second time while it still held "+
			"job-1: a superseded connection's teardown returned the record it was "+
			"working, so one record has two live deliveries and whichever answer "+
			"lands second is discarded as superseded", again.Payload)
	}

	// And it can still finish the one it has - the delivery the teardown
	// left alone is the delivery it is holding, not a stale twin of it.
	w.Respond(t, first.RespTopic, "ack", first.CorrData)
	if _, ok := w.Await(t, 1500*time.Millisecond); ok {
		t.Fatal("the job came back after the worker acknowledged it, so the " +
			"acknowledgement resolved something other than what it held")
	}
}

// docs/invariants.md 7, and RFC 0003 "`queue` - Attempts, timeout, and
// redelivery"
//
// The other half, or the rule is satisfied by returning nothing: a
// connection that really goes still gives back everything it was holding.
//
// **This is the failure the ownership guard alone would have caused.** A
// superseded connection's own leased records are exactly the ones nobody
// can rescue - the worker can never acknowledge them, and a Delivering
// record has no visibility deadline by design - so a teardown that returns
// nothing once it has lost the id strands them until the session ends. The
// marker returns its own and nothing else, and this is the "its own" half.
func TestADepartingWorkerStillReturnsEverythingItHeld(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	going := connect(t, h, "worker-going", true, false)
	going.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, going.C)

	p.Pub(t, "jobs/lease", "job-1")
	held, ok := going.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the worker was offered nothing, so nothing was leased to it")
	}
	if held.Payload != "job-1" {
		t.Fatalf("offered %q, want job-1", held.Payload)
	}

	// A second worker, waiting. It must be offered the record the first was
	// holding, and well inside the visibility timeout: the return is the
	// disconnect's doing, not the deadline's - a Delivering record has no
	// deadline to wait for (invariant 7).
	taking := connect(t, h, "worker-taking", true, false)
	taking.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, taking.C)

	going.Close()

	next, ok := taking.Await(t, visibility-500*time.Millisecond)
	if !ok {
		t.Fatal("a worker disconnected holding job-1 and the record was never " +
			"offered to anybody else: a Delivering record has no visibility " +
			"deadline to rescue it, so it is stranded until the session ends")
	}
	if next.Payload != "job-1" {
		t.Fatalf("the waiting worker was offered %q, want job-1", next.Payload)
	}
}

// docs/invariants.md 7, and RFC 0003 "`queue` - Attempts, timeout, and
// redelivery"
//
// The half a teardown must not stop doing: a connection that has lost its
// id still gives back what it was holding.
//
// **This is the failure the ownership guard alone would have caused**, and
// it is the reason the fix is a marker rather than the guard the rest of
// the teardown uses. A superseded connection's leased records are exactly
// the ones nobody can rescue: the worker can never acknowledge them, and a
// Delivering record has no visibility deadline by design (invariant 7), so
// a teardown that returns nothing once it has lost the id strands them
// until the session ends.
//
// **A real takeover, and deterministic because of where ownership is
// claimed.** OnSessionEstablish claims the id before the substrate
// disconnects the connection being superseded, so on this path the
// superseded teardown always runs having already lost it. Nothing here has
// to be timed.
func TestATakenOverWorkersHeldJobStillGoesBack(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	first := connect(t, h, "worker-1", true, false)
	first.Sub(t, "$saguin/queue/jobs", 1)
	subscribed(t, first.C)

	p.Pub(t, "jobs/lease", "job-1")
	held, ok := first.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the worker was offered nothing, so nothing was leased to it")
	}
	if held.Payload != "job-1" {
		t.Fatalf("offered %q, want job-1", held.Payload)
	}

	// Same id, so this is a takeover: the new connection owns the id before
	// the old one's teardown can run, which is the state the marker has to
	// answer for.
	second := connect(t, h, "worker-1", true, false)
	second.Sub(t, "$saguin/queue/jobs", 1)

	// Well inside the visibility timeout, because there is no deadline to
	// wait for: a Delivering record has none, which is what makes the
	// teardown the only thing that can return it.
	next, ok := second.Await(t, visibility-500*time.Millisecond)
	if !ok {
		t.Fatal("a worker was taken over while holding job-1 and the record was " +
			"never offered again: the superseded connection's teardown declined " +
			"to return its own work because it no longer held the id, so the job " +
			"is stranded with no worker and no deadline to rescue it")
	}
	if next.Payload != "job-1" {
		t.Fatalf("the worker that took over was offered %q, want job-1", next.Payload)
	}
}

// MQTT-3.8.4, and docs/invariants.md 13
//
// A re-SUBSCRIBE replaces the subscription and its options; it does not add
// a second one.
//
// > If a Server receives a SUBSCRIBE packet containing a Topic Filter that
// > is identical to a Non-shared Subscription's Topic Filter for the current
// > Session, then it MUST replace that existing Subscription with a new
// > Subscription. [MQTT-3.8.4-3]
//
// **saguin's own index appended.** `track` adds an entry per channel a
// filter reaches and never replaces one, and `forgetFilters` - the only
// thing that removes by filter - runs solely from OnUnsubscribed. So every
// re-SUBSCRIBE of a filter left the previous entry beside the new one.
//
// Two costs, and the wire shows the first. `identifiersForLocked` appends
// one identifier per matching entry with no dedupe, so a delivery carried
// the subscription's identifier once per duplicate - and after a
// re-SUBSCRIBE that changed it, the *old* identifier as well, which is a
// client being told a delivery answers a subscription it has replaced. The
// second cost is the index itself: nothing removes those entries before the
// connection ends, so a client that re-subscribes N times holds N sets,
// keyed by a client id and grown by a packet the client chooses, which is
// what invariant 13 refuses.
//
// **The identifier is the oracle rather than a count**, because it is the
// one thing MQTT makes observable from outside: 3.8.4 says the replacement
// subscription is the one in force, so its identifier is the one a delivery
// carries and the replaced one must not appear.
//
// Raw packets rather than paho, for the reason the test above this gives:
// paho.golang surfaces one identifier where MQTT allows a list, so a
// duplicate would read as a single and the defect would be invisible.
func TestResubscribingReplacesTheSubscriptionRatherThanAddingOne(t *testing.T) {
	h := start(t)

	conn, err := net.Dial("tcp", h.Addr)
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	connectPacket := []byte{
		0x10, 0x14,
		0x00, 0x04, 'M', 'Q', 'T', 'T',
		0x05, 0x02, 0x00, 0x3c, 0x00,
		0x00, 0x07, 'r', 'e', 's', 'u', 'b', 'e', 'r',
	}
	if _, err := conn.Write(connectPacket); err != nil {
		t.Fatalf("write connect: %v", err)
	}
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	if _, _, err := readRawPacket(conn); err != nil {
		t.Fatalf("no CONNACK: %v", err)
	}

	// The same filter twice, under two identifiers and two QoS settings. The
	// second SUBSCRIBE is the replacement, so 9 at QoS 0 is the subscription
	// in force and 7 at QoS 1 is gone - both halves of "replace that
	// existing Subscription with a new Subscription", since the QoS is an
	// option of the subscription exactly as the identifier is.
	//
	// **The QoS is the half a duplicate gets wrong in the other direction.**
	// The delivery paths take the first matching entry, so an entry
	// surviving from the first SUBSCRIBE wins - and a client that asked to
	// be downgraded to QoS 0 goes on being sent acknowledged deliveries,
	// holding packet identifiers it never asked to hold.
	for i, opt := range []struct {
		id   byte
		opts byte
	}{{7, 0x01}, {9, 0x00}} {
		const filter = "events/+"
		id := opt.id
		var body []byte
		body = append(body, 0x00, byte(i+1))
		body = append(body, 0x02, 0x0B, id)
		body = append(body, byte(len(filter)>>8), byte(len(filter)))
		body = append(body, filter...)
		body = append(body, opt.opts)
		if _, err := conn.Write(append([]byte{0x82, byte(len(body))}, body...)); err != nil {
			t.Fatalf("write subscribe %d: %v", id, err)
		}
		_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
		typ, sub, err := readRawPacket(conn)
		if err != nil {
			t.Fatalf("no SUBACK for identifier %d: %v", id, err)
		}
		if typ>>4 != 9 {
			t.Fatalf("answered packet type %d for a SUBSCRIBE, want a SUBACK", typ>>4)
		}
		if code := sub[len(sub)-1]; code > 2 {
			t.Fatalf("subscribe under identifier %d refused 0x%02X", id, code)
		}
	}

	pub := connect(t, h, "resub-writer", true, false)
	pub.Pub(t, "events/one", "x")

	_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	typ, body, err := readRawPacket(conn)
	if err != nil {
		t.Fatalf("no delivery: %v", err)
	}
	if typ>>4 != 3 {
		t.Fatalf("packet type %d, want a PUBLISH", typ>>4)
	}
	ids := subscriptionIdentifiersIn(t, body, (typ>>1)&0x03 > 0)
	if qos := (typ >> 1) & 0x03; qos != 0 {
		t.Errorf("the delivery arrived at QoS %d, want 0: the second SUBSCRIBE "+
			"replaced the subscription's options (MQTT-3.8.4-3), so the QoS in "+
			"force is the one it asked for - a surviving entry from the first "+
			"means a subscriber that asked to be downgraded is still sent "+
			"acknowledged deliveries", qos)
	}
	sort.Ints(ids)
	if len(ids) != 1 || ids[0] != 9 {
		t.Fatalf("the delivery carried identifiers %v, want [9]: a re-SUBSCRIBE "+
			"replaces the subscription (MQTT-3.8.4-3), so the replacement's "+
			"identifier is the one in force and the replaced one must not appear. "+
			"Two entries for one filter also means the index grows by a packet "+
			"the client chooses, which nothing removes until it disconnects",
			ids)
	}

	// One copy, or the assertion above is about the wrong half of 3.3.4 -
	// the same guard the overlapping-filter test keeps.
	_ = conn.SetReadDeadline(time.Now().Add(700 * time.Millisecond))
	if _, extra, err := readRawPacket(conn); err == nil {
		t.Errorf("a second copy arrived (%d bytes), so the duplicate entry is "+
			"delivering twice rather than tagging once", len(extra))
	}
}

// RFC 0003 "`latest`", and docs/invariants.md 1
//
// A resumed session is not held by a value that stopped being true while it
// was away.
//
// **The channel already made this choice everywhere else.** A live update
// for a subscriber with no room waits, and a newer one for its topic replaces
// it, because the value it would have missed is no longer current and it
// receives whatever is current when it catches up. A resume *is* catching up - and it
// was the one path that did the opposite: MQTT restores the session's
// unacknowledged packets and re-sends them, so a superseded value went back
// on the wire as though it were current and held a slot of the window until
// it was acknowledged.
//
// **The slot is the defect, not the stale value.** An acknowledgement cannot
// arrive for a delivery re-sent into a socket a link cut has already killed,
// so the session keeps that packet and re-sends it on the next resume too.
// One is stranded per cut that lands in the wrong moment, and at the
// client's Receive Maximum the window is shut for good: the current-state
// pass waits in the `latest` list behind values that are both stale and
// immovable, and the device holds state nothing can correct. That is the
// link-churn soak's failure, which took four packets against a Receive
// Maximum of four to produce - offsets 3042, 3429, 11928 and 381, four
// different records accumulated across 259 cuts.
//
// **Receive Maximum 1 is what makes this deterministic**: one unacknowledged
// delivery is a closed window, so the jam needs no churn to reproduce. The
// manual acknowledgement stands in for the acknowledgement that cannot
// arrive, the way TestASupersededTeardownRemovesNothing builds its state
// rather than racing for it.
//
// **The superseded value must not appear at all**, which is stronger than
// "the subscriber ends up current" and is the assertion that holds the fix
// in the right place. Taken back after the substrate had written it, the
// value reaches the client and its packet identifier is freed while the
// client still owes an acknowledgement for it - and a freed identifier is
// handed straight back out, so the catch-up could send the *current* value
// under it and have the stale value's acknowledgement credited to the
// current one, advancing the mark over a value the client may never have
// read. The drop therefore runs before the substrate clones the session,
// and nothing stale is ever written; this assertion is what would notice if
// it moved back.
func TestAResumedSessionIsNotHeldByASupersededLatestValue(t *testing.T) {
	h := start(t)
	p := connect(t, h, "producer", true, false)

	p.Pub(t, "state/device/a", "v1")
	time.Sleep(200 * time.Millisecond)

	// Receive Maximum 1 and manual acknowledgement: one delivery fills the
	// window and nothing frees it.
	c := brokertest.Dial(t, h, "jammed", false, true, 1, 300, 0)
	c.Sub(t, "state/#", 1)
	first, ok := c.Await(t, 3*time.Second)
	if !ok {
		t.Fatal("the subscriber was served no current state at all")
	}
	if first.Payload != "v1" {
		t.Fatalf("first delivery was %q, want v1", first.Payload)
	}

	// The link dies with that delivery unacknowledged, and the topic is
	// written again while the client is away.
	c.Close()
	time.Sleep(300 * time.Millisecond)
	p.Pub(t, "state/device/a", "v2")
	time.Sleep(200 * time.Millisecond)

	again := brokertest.Dial(t, h, "jammed", false, true, 1, 300, 0)
	again.Sub(t, "state/#", 1)

	var got []string
	held, stale := false, false
	deadline := time.Now().Add(4 * time.Second)
	for time.Now().Before(deadline) {
		r, ok := again.Await(t, 700*time.Millisecond)
		if !ok {
			break
		}
		got = append(got, r.Payload)
		if r.Topic == "state/device/a" {
			switch r.Payload {
			case "v2":
				held = true
			case "v1":
				stale = true
			}
		}
	}
	if stale {
		t.Errorf("the resumed subscriber was sent the superseded value v1 again "+
			"(it received %v): taken back only after the write, its packet "+
			"identifier is freed while the client still owes an acknowledgement "+
			"for it, and a freed identifier is reissued - so that acknowledgement "+
			"can be credited to whatever is sent under it next", got)
	}
	if !held {
		t.Fatalf("the resumed subscriber was never served v2, the current value "+
			"of state/device/a; it holds %v. The superseded value it was still "+
			"owed took the only slot of its in-flight window, and nothing can "+
			"acknowledge a delivery re-sent to a connection that had already "+
			"gone - so the current-state pass waits behind it for ever and the "+
			"device holds state that cannot be corrected", got)
	}
}

// positionLostRows reads /v1/operations/position-lost as an operator does,
// keyed by client id and channel so a test can ask about one reader.
func positionLostRows(t *testing.T, opsAddr string) (map[[2]string]struct {
	Kind          string `json:"kind"`
	Reported      bool   `json:"reported"`
	Count         uint64 `json:"count"`
	RecordsMissed uint64 `json:"records_missed"`
	LastPosition  uint64 `json:"last_position"`
	LastFloor     uint64 `json:"last_floor"`
	LastSeen      string `json:"last_seen"`
}, int, uint64) {
	t.Helper()
	type row struct {
		Reader        string `json:"reader"`
		Channel       string `json:"channel"`
		Kind          string `json:"kind"`
		Reported      bool   `json:"reported"`
		Count         uint64 `json:"count"`
		RecordsMissed uint64 `json:"records_missed"`
		LastPosition  uint64 `json:"last_position"`
		LastFloor     uint64 `json:"last_floor"`
		LastSeen      string `json:"last_seen"`
	}
	var body struct {
		Readers  []row  `json:"readers"`
		Returned int    `json:"returned"`
		Tracked  int    `json:"tracked"`
		Beyond   uint64 `json:"beyond"`
	}
	resp, err := http.Get("http://" + opsAddr + "/v1/operations/position-lost")
	if err != nil {
		t.Fatalf("GET the route: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("/v1/operations/position-lost answered %d, want 200", resp.StatusCode)
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		t.Fatalf("decode the route: %v", err)
	}
	if body.Returned != len(body.Readers) {
		t.Errorf("the body says it returned %d rows and carries %d", body.Returned, len(body.Readers))
	}
	out := map[[2]string]struct {
		Kind          string `json:"kind"`
		Reported      bool   `json:"reported"`
		Count         uint64 `json:"count"`
		RecordsMissed uint64 `json:"records_missed"`
		LastPosition  uint64 `json:"last_position"`
		LastFloor     uint64 `json:"last_floor"`
		LastSeen      string `json:"last_seen"`
	}{}
	for _, r := range body.Readers {
		out[[2]string{r.Reader, r.Channel}] = struct {
			Kind          string `json:"kind"`
			Reported      bool   `json:"reported"`
			Count         uint64 `json:"count"`
			RecordsMissed uint64 `json:"records_missed"`
			LastPosition  uint64 `json:"last_position"`
			LastFloor     uint64 `json:"last_floor"`
			LastSeen      string `json:"last_seen"`
		}{r.Kind, r.Reported, r.Count, r.RecordsMissed, r.LastPosition, r.LastFloor, r.LastSeen}
	}
	return out, body.Tracked, body.Beyond
}

// RFC 0005 "The /v1 routes", invariant 1
//
// **A counter says how much and never which one**, and this is that rule
// on the loss invariant 1 is about. The counter says a channel passed its
// readers; the operator's next question is which device has a hole in its
// history, and until this route there was no answer but the log.
//
// The consumer is held still rather than raced, the way the connected-
// consumer test above holds one: Receive Maximum 1 and a handler that does
// not return leave it holding offset 1 with a full window, so no timing
// decides how far behind it is.
//
// **`reported` is the field this case exists to set.** The consumer is
// connected and reading, so MQTT gives the broker no way to tell it: the
// operator reading this route is the only party who will ever know.
func TestTheRouteNamesAConnectedConsumerTheFloorPassed(t *testing.T) {
	brokertest.Retain = map[string]int64{"events": 200}
	t.Cleanup(func() { brokertest.Retain = nil })
	h := startOn(t, "tcp")
	ops := operationsAt(t, h)

	p := connect(t, h, "producer", true, false)
	c := connectRx(t, h, "held", false, false, 1)
	c.Hold = make(chan struct{})
	c.HoldPayload = "first"
	c.Sub(t, "events/#", 1)
	var once sync.Once
	release := func() { once.Do(func() { close(c.Hold) }) }
	t.Cleanup(release)

	p.Pub(t, "events/a/1", "first")
	if r, ok := c.Await(t, 3*time.Second); !ok || r.Payload != "first" {
		t.Fatalf("the consumer never got the record it is held on: %v %q", ok, r.Payload)
	}

	if rows, tracked, _ := positionLostRows(t, ops); tracked != 0 {
		t.Fatalf("the route already names %d readers before the floor moved, so a row "+
			"afterwards would prove nothing: %v", tracked, rows)
	}

	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past its position
	release()

	// The held read resumes and meets the floor, and the route records it.
	rows, tracked, beyond := positionLostRows(t, ops)
	for deadline := time.Now().Add(5 * time.Second); tracked == 0 && time.Now().Before(deadline); {
		time.Sleep(10 * time.Millisecond)
		rows, tracked, beyond = positionLostRows(t, ops)
	}
	if tracked == 0 {
		t.Fatalf("the floor passed a connected consumer and the route names nobody")
	}
	if beyond != 0 {
		t.Errorf("beyond is %d on a broker with one reader, so the record dropped a row "+
			"it had room for", beyond)
	}
	r, ok := rows[[2]string{"mqtt:held", "events"}]
	if !ok {
		t.Fatalf("the route does not name the consumer the floor passed; it names %v", rows)
	}
	if r.Kind != "consumer" {
		t.Errorf("the row's kind is %q, want \"consumer\": it was overtaken while connected "+
			"and reading", r.Kind)
	}
	if r.Reported {
		t.Error("the row says the consumer was told. It was connected and reading, so there " +
			"was no CONNACK to carry Session Present = 0 and MQTT offers nothing else - " +
			"reported = true here would tell an operator the device knows when it does not")
	}
	if r.RecordsMissed == 0 {
		t.Error("the row reports a passing that lost nothing")
	}
	if r.Count == 1 && r.RecordsMissed != r.LastFloor-r.LastPosition {
		t.Errorf("one passing lost %d records with position %d and floor %d, which do not "+
			"agree", r.RecordsMissed, r.LastPosition, r.LastFloor)
	}

	// **The route and the counter are two instruments on the same events**,
	// and the whole value of the pair is that they can be checked against
	// each other. Every row is counted, so with nothing evicted the counts
	// sum to the counter exactly.
	const lost = `saguin_channel_position_lost_total{channel="events"}`
	var summed uint64
	for k, row := range rows {
		if k[1] == "events" {
			summed += row.Count
		}
	}
	if got := metricValue(t, ops, lost); uint64(got) != summed {
		t.Errorf("%s is %v and the route's rows for that channel count %d occurrences.\n\t"+
			"Nothing was evicted (beyond %d, tracked %d), so these are two readings of "+
			"one set of events and they disagree", lost, got, summed, beyond, tracked)
	}
}

// RFC 0005 "The /v1 routes", invariant 1
//
// The other kind, and the field that tells them apart. A consumer whose
// stored position had already been passed when it came back **is** told,
// with Session Present = 0, so it knows to start fresh rather than reading
// on over the hole. An operator triaging the route needs that distinction:
// `reported` false is the row where nothing downstream knows anything is
// missing, and so nothing downstream will ever ask for it again.
func TestTheRouteTellsAToldReaderFromOneThatCannotBe(t *testing.T) {
	brokertest.Retain = map[string]int64{"events": 200}
	t.Cleanup(func() { brokertest.Retain = nil })
	h := startOn(t, "tcp")
	ops := operationsAt(t, h)

	p := connect(t, h, "producer", true, false)
	c := connect(t, h, "awayer", false, false)
	c.Sub(t, "events/#", 1)
	p.Pub(t, "events/a/1", "first")
	if _, ok := c.Await(t, 3*time.Second); !ok {
		t.Fatal("no delivery, so the consumer never had a position to lose")
	}
	awaitStoredPosition(t, h, "events", 2, 5*time.Second) // its position stored

	linkCut(t, c)
	for i := range 30 {
		p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
	}
	awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past it

	again := connect(t, h, "awayer", false, false)
	if again.SessionPresent {
		t.Fatal("the broker kept a session whose position retention had removed, so this " +
			"test never reached the loss it is about")
	}
	// Recorded by the CONNECT that found it; read until it shows.
	rows, _, _ := positionLostRows(t, ops)
	r, ok := rows[[2]string{"mqtt:awayer", "events"}]
	for deadline := time.Now().Add(5 * time.Second); !ok && time.Now().Before(deadline); {
		time.Sleep(10 * time.Millisecond)
		rows, _, _ = positionLostRows(t, ops)
		r, ok = rows[[2]string{"mqtt:awayer", "events"}]
	}
	if !ok {
		t.Fatalf("the route does not name a consumer whose stored position was passed "+
			"while it was away; it names %v", rows)
	}
	if r.Kind != "session" {
		t.Errorf("the row's kind is %q, want \"session\"", r.Kind)
	}
	if !r.Reported {
		t.Error("the row says the consumer was not told, but it reconnected and was " +
			"answered Session Present = 0, which is exactly the telling. Reported = " +
			"false here would put a device an operator need not chase at the top of " +
			"the list of ones they must")
	}
	if r.RecordsMissed != r.LastFloor-r.LastPosition {
		t.Errorf("records_missed %d does not agree with position %d and floor %d",
			r.RecordsMissed, r.LastPosition, r.LastFloor)
	}
}

// RFC 0005 "The /v1 routes", invariant 1
//
// **The third kind of reader, and the one no MQTT client can drive.** An
// outbound bridge rule holds a stored position like any durable consumer
// and retention passes it the same way, which is why it has always shared
// the counter - "the same loss, and an operator watching for it should not
// have to know which kind of reader it was". It has to share the route for
// the same reason.
//
// Driven through the broker's own bridge client rather than over MQTT,
// because that is the only door this path has: a bridge publishes in
// process and there is no packet that makes one lose its position.
//
// **It is here because the site was wired and unobserved.** Swapping the
// two offsets at the call site - `PositionLost(name, reader, floor, at)` -
// left every test in the package passing while `add`'s own guard silently
// dropped every bridge row: the counter still moved, the route showed
// nothing, and the identity between them broke with no test to say so.
func TestTheRouteNamesAnOutboundBridgeRuleTheFloorPassed(t *testing.T) {
	h := startOn(t, "tcp")
	ops := operationsAt(t, h)

	bc := h.B.NewBridgeClient("head-office")
	bc.PositionLost("events", brokertest.BridgeReaderName("head-office"), 40, 1040)

	rows, tracked, beyond := positionLostRows(t, ops)
	if tracked != 1 || beyond != 0 {
		t.Fatalf("one bridge rule was passed and the route holds %d rows with beyond %d, "+
			"want 1 and 0: %v", tracked, beyond, rows)
	}
	r, ok := rows[[2]string{"bridge:head-office", "events"}]
	if !ok {
		t.Fatalf("the route does not name the outbound rule under its own scheme; it "+
			"names %v.\n\tA row keyed by the bare rule name would share a key with any "+
			"client calling itself that", rows)
	}
	if r.Kind != "bridge" {
		t.Errorf("the row's kind is %q, want \"bridge\"", r.Kind)
	}
	if r.Reported {
		t.Error("the row says the rule was told. A bridge resumes at the floor and the " +
			"peer across the link hears nothing, so nothing downstream knows those " +
			"records are missing")
	}
	if r.RecordsMissed != 1000 || r.LastPosition != 40 || r.LastFloor != 1040 {
		t.Errorf("the row is missed=%d position=%d floor=%d, want 1000, 40 and 1040.\n\t"+
			"The two offsets reaching this row in the wrong order is invisible to every "+
			"other test in this package", r.RecordsMissed, r.LastPosition, r.LastFloor)
	}
	if r.Count != 1 {
		t.Errorf("count is %d after one passing, want 1", r.Count)
	}

	const lost = `saguin_channel_position_lost_total{channel="events"}`
	if got := metricValue(t, ops, lost); got != 1 {
		t.Errorf("%s is %v after a bridge rule was passed, want 1: the counter and the "+
			"route must move together at this site as they do at the other two", lost, got)
	}
}

// RFC 0003 "Broadcast": **a broadcast publish at QoS 1 or 2 is acknowledged
// once it is written to the broadcast log**, which is where every session it
// is owed is served it from, and not before: a broker that stopped between an
// acknowledgement and the write would have told the publisher a message was
// accepted that no session it was owed would ever receive. The log's write is
// held open here, and the publisher must not be answered until it completes.
func TestABroadcastIsAcknowledgedOnlyOnceItsSessionsHaveKeptIt(t *testing.T) {
	h := start(t)
	lg := &holdsAppends{entered: make(chan struct{}), release: make(chan struct{})}
	t.Cleanup(lg.let) // after start, so it runs before the harness stops
	attachDrainWith(t, h, func(l drainReads) drainReads {
		lg.drainReads = l
		return lg
	}, func(s drainSessions) drainSessions { return s })
	sub := dial(t, h, "subscriber", false, false, 0, 3600, 0) // a session that outlives its connection
	sub.Sub(t, "loose/#", 1)
	pub := connect(t, h, "publisher", true, false)

	lg.armed.Store(true)
	acked := make(chan error, 1)
	go func() {
		_, err := pub.C.Publish(context.Background(), &paho.Publish{
			Topic: "loose/kept", QoS: 1, Payload: []byte("kept")})
		acked <- err
	}()
	select {
	case <-lg.entered:
	case <-time.After(3 * time.Second):
		t.Fatal("the publish never reached the broadcast log, so nothing was held open")
	}
	select {
	case err := <-acked:
		t.Fatalf("the publisher was answered (%v) while the log had not yet written the message: "+
			"a broker stopping now would have acknowledged a broadcast no session holds", err)
	case <-time.After(500 * time.Millisecond):
	}
	lg.let()
	select {
	case err := <-acked:
		if err != nil {
			t.Fatalf("the publish failed once the log had written it: %v", err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the publisher was never answered after the log wrote the message")
	}
	if !waitUntil(3*time.Second, func() bool { return sub.Count() == 1 }) {
		t.Fatalf("the subscriber received %v, want the message", sub.Payloads())
	}
}

// holdsAppends is a broadcast log that, once armed, holds its next append
// open until it is let go.
type holdsAppends struct {
	drainReads
	armed   atomic.Bool
	entered chan struct{}
	release chan struct{}
	once    sync.Once
}

func (l *holdsAppends) Append(r store.Record) (store.Record, error) {
	if l.armed.CompareAndSwap(true, false) {
		close(l.entered)
		<-l.release
	}
	return l.drainReads.Append(r)
}

func (l *holdsAppends) let() { l.once.Do(func() { close(l.release) }) }

// holdsRemoves is a broadcast log that, once armed, holds its next removal of
// messages nobody owes open until it is let go.
type holdsRemoves struct {
	drainReads
	armed   atomic.Bool
	entered chan struct{}
	release chan struct{}
	once    sync.Once
}

func (l *holdsRemoves) Remove(offsets ...uint64) (int, int64, error) {
	if l.armed.CompareAndSwap(true, false) {
		close(l.entered)
		<-l.release
	}
	return l.drainReads.Remove(offsets...)
}

func (l *holdsRemoves) let() { l.once.Do(func() { close(l.release) }) }

// Invariant 16 on broadcast: the publisher waits for the one write of its
// message to the broadcast log, and for nothing else another client does. A
// subscriber at its limits.session_queue_bytes gives up the oldest it is owed
// for each new message, and a message given up by the last session owed it
// leaves the log - a store write, another client's clean-up. Those writes are
// held open here; the publisher's acknowledgements must not wait for them.
func TestABroadcastPublisherDoesNotWaitForAnotherSessionsGiveUps(t *testing.T) {
	brokertest.SessionQueueBytes = 8 << 10 // a handful of the messages below
	t.Cleanup(func() { brokertest.SessionQueueBytes = 0 })
	h := start(t)
	lg := &holdsRemoves{entered: make(chan struct{}), release: make(chan struct{})}
	t.Cleanup(lg.let) // after start, so it runs before the harness stops
	attachDrainWith(t, h, func(l drainReads) drainReads {
		lg.drainReads = l
		return lg
	}, func(s drainSessions) drainSessions { return s })
	// One-wide, and never acknowledging: everything past the first waits in
	// its session, which fills and starts giving up the oldest.
	slow := dial(t, h, "slow", false, true, 1, 3600, 0)
	slow.Sub(t, "loose/#", 1)
	pub := connect(t, h, "publisher", true, false)
	lg.armed.Store(true)

	payload := []byte(strings.Repeat("x", 1024))
	publish := func(i int) time.Duration {
		t.Helper()
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		at := time.Now()
		if _, err := pub.C.Publish(ctx, &paho.Publish{Topic: "loose/x", QoS: 1, Payload: payload}); err != nil {
			t.Fatalf("publish %d was not answered within 2s (%v): the publisher waited for the "+
				"slow subscriber's session to give up what it held", i, err)
		}
		return time.Since(at)
	}
	// **Held open first, then timed.** A give-up's removal reaches the log
	// with the next gathered batch, up to ack_commit_interval after the
	// publish that caused it (bdrain.release): publishes timed before it
	// arrives are timed with nothing held open.
	primed := 0
	for held := false; !held; primed++ {
		if primed == 200 {
			t.Fatal("200 publishes and no give-up reached the log, so nothing was held open and " +
				"the publisher's speed says nothing")
		}
		publish(primed)
		select {
		case <-lg.entered:
			held = true
		case <-time.After(20 * time.Millisecond):
		}
	}
	var worst time.Duration
	for i := 0; i < 40; i++ {
		worst = max(worst, publish(primed+i))
	}
	if worst >= time.Second {
		t.Errorf("the slowest acknowledgement took %v while the slow subscriber's give-ups were "+
			"held open", worst.Round(time.Millisecond))
	}
	t.Logf("%d publishes until a give-up's removal was held open, then 40, the slowest acknowledged in %v",
		primed, worst.Round(time.Millisecond))
}

// dyingAppends is a broadcast log whose append of a message on topic never
// finishes: the goroutine making it stops there, as a broker stopping would.
type dyingAppends struct {
	drainReads
	topic string
	once  sync.Once
	died  chan struct{}
}

func (d *dyingAppends) Append(r store.Record) (store.Record, error) {
	if r.Topic == d.topic {
		d.once.Do(func() { close(d.died) })
		runtime.Goexit()
	}
	return d.drainReads.Append(r)
}

// **Acknowledged means it arrives**, across a crash at the worst moment: the
// broker stops while it is keeping a publish in the sessions it is owed. A
// publisher that was answered will not send it again, so an answered publish
// the sessions never kept is lost for good; one that was not answered is sent
// again, which MQTT obliges the publisher to do, and arrives. The property is
// asserted either way, and holds only because the answer comes after the
// message is kept (RFC 0003 "Broadcast").
//
// Both routes a publish reaches a session by: a durable subscriber to a
// broadcast topic, and a member of a shared group over a channel, each kept in
// the broadcast log - the second as a copy owed to the member alone, and the
// one where the channel's own store might have been thought to carry the
// record. It does not: a shared group keeps no position on the channel, so the
// member's session is the only thing that would ever deliver it again.
func TestAnAcknowledgedPublishReachesItsSessionsAcrossACrash(t *testing.T) {
	for _, c := range []struct{ name, filter, topic string }{
		{"a durable broadcast subscriber", "loose/#", "loose/x"},
		{"a shared member on a channel", "$share/g/events/#", "events/x"},
	} {
		t.Run(c.name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "sessions.db")
			died := make(chan struct{})
			h := startDurableSQLite(t, path)
			dl := &dyingAppends{topic: c.topic, died: died}
			attachDrainWith(t, h, func(l drainReads) drainReads {
				dl.drainReads = l
				return dl
			}, func(s drainSessions) drainSessions { return s })
			member := dial(t, h, "member", false, false, 0, 3600, 0)
			member.Sub(t, c.filter, 1)
			pub := dial(t, h, "publisher", false, false, 0, 3600, 0)

			acked := make(chan bool, 1)
			go func() {
				ctx, cancel := context.WithTimeout(context.Background(), 1500*time.Millisecond)
				defer cancel()
				_, err := pub.C.Publish(ctx, &paho.Publish{Topic: c.topic, QoS: 1, Payload: []byte("must-arrive")})
				acked <- err == nil
			}()
			select {
			case <-died:
			case <-time.After(3 * time.Second):
				t.Fatal("the publish never reached the store that keeps it, so the broker did not stop " +
					"where this test is about")
			}
			wasAcked := <-acked
			h.Crash()

			h2 := startDurableSQLite(t, path)
			back := dial(t, h2, "member", false, false, 0, 3600, 0)
			if !wasAcked {
				// Not answered, so the publisher sends it again.
				p2 := dial(t, h2, "publisher", false, false, 0, 3600, 0)
				p2.Pub(t, c.topic, "must-arrive")
			}
			if !waitUntil(3*time.Second, func() bool {
				for _, m := range back.All() {
					if m.Payload == "must-arrive" {
						return true
					}
				}
				return false
			}) {
				t.Fatalf("the publisher was answered=%v and the member never received the message "+
					"after the restart: an acknowledged publish lost to a crash (received %v)",
					wasAcked, back.Payloads())
			}
			t.Logf("answered before the crash: %v; the member received it after the restart", wasAcked)
		})
	}
}

// RFC 0002: a session at limits.session_queue_bytes gives up the oldest of
// what it holds, so a device that comes back is sent the most recent. A
// connection that takes a session over starts its packet identifiers again,
// and the table used to order a session's deliveries by identifier within a
// second - so the new connection's deliveries, under lower identifiers, were
// taken for the oldest and given up, and the device was sent the stale ones.
func TestAResumedSessionAtItsBoundGivesUpTheOldestNotTheNewest(t *testing.T) {
	brokertest.SessionQueueBytes = 8 << 10
	t.Cleanup(func() { brokertest.SessionQueueBytes = 0 })
	h := start(t)
	old := dial(t, h, "device", false, true, 1, 3600, 0)
	old.Sub(t, "loose/#", 1)
	pub := connect(t, h, "publisher", true, false)
	payload := strings.Repeat("x", 1024)
	for i := 0; i < 20; i++ {
		pub.Pub(t, "loose/old", payload)
	}
	kill(t, old.Conn)

	back := dial(t, h, "device", false, true, 1, 3600, 0)
	for i := 0; i < 3; i++ {
		pub.Pub(t, "loose/new", fmt.Sprintf("new-%d", i))
	}
	acked := 0
	var got []string
	for deadline := time.Now().Add(5 * time.Second); time.Now().Before(deadline); time.Sleep(20 * time.Millisecond) {
		all := back.All()
		for ; acked < len(all); acked++ {
			all[acked].Ack()
		}
		got = got[:0]
		for _, r := range all {
			if strings.HasPrefix(r.Payload, "new-") {
				got = append(got, r.Payload)
			}
		}
		if len(got) == 3 {
			break
		}
	}
	if len(got) != 3 {
		var all []string
		for _, r := range back.All() {
			all = append(all, r.Payload[:min(len(r.Payload), 6)])
		}
		t.Fatalf("the resumed session was sent %v of the three newest: its bound gave up new "+
			"deliveries in place of old ones\n\treceived: %v", got, all)
	}
}

// RFC 0003 "Reading one value" - the payload is the topic to read
//
// **A point read is asked about the key it reads**: the exact topic in its
// payload, edge whitespace and all, because a topic with a trailing space is
// a different topic. The key used to be trimmed for the permission check and
// read as sent, so `state/x/public ` was checked against the channel `public`
// holds and answered from the one `private` holds - a value the role may not
// read, disclosed by a space.
func TestAPointReadIsCheckedAgainstTheKeyItReads(t *testing.T) {
	h := startRandom(t, []*channel.Channel{
		{Name: "public", Type: channel.Latest, Filter: "state/+/public"},
		{Name: "private", Type: channel.Latest, Filter: "state/#"},
	})
	writeACL(t, h, `
roles:
  reader:
    - channel: public
      allow: [read]
  writer:
    - channel: public
      allow: [write]
    - channel: private
      allow: [write]
users:
  reader: [reader]
  writer: [writer]
`)
	w := dialWithUser(t, h, "w", "writer")
	w.Pub(t, "state/x/public", "open")
	w.Pub(t, "state/x/public ", "SECRET")

	r := dialWithUser(t, h, "r", "reader")
	if got := string(r.KvGet(t, "state/x/public", nil).Payload); got != "open" {
		t.Fatalf("the readable key answered %q, want open, so this proves nothing", got)
	}
	ack, err := r.C.Publish(context.Background(), &paho.Publish{
		Topic: brokertest.ChannelKVGet, QoS: 1, Payload: []byte("state/x/public "),
		Properties: &paho.PublishProperties{ResponseTopic: "kv-reply"},
	})
	if ack == nil {
		t.Fatalf("no PUBACK for the point read: %v", err)
	}
	if ack.ReasonCode != 0x87 {
		t.Errorf("a point read of a key in the channel the role may not read was answered 0x%02X, "+
			"want 0x87", ack.ReasonCode)
	}
	if got, ok := r.Await(t, time.Second); ok {
		t.Errorf("a role with read on public only was sent %q from private", got.Payload)
	}
}

// RFC 0002 "Hanging up a client" - the payload is the client id to hang up
//
// **The hang-up names exactly the client it hangs up.** A client id is
// whatever the device sent, and admission bounds only its length, so `dev`
// and `dev ` can both be connected. The id used to be trimmed: asking for
// `dev ` hung up `dev` and answered hung-up, and the device the operator
// meant stayed connected - the one verb "withdrawing a device's access" rests
// on, reporting success for the wrong device.
func TestAHangUpNamesExactlyTheClientItHangsUp(t *testing.T) {
	h := start(t)
	writeACL(t, h, `
roles:
  on-call:
    - broker: sessions
      allow: [disconnect]
  everyday:
    - channel: events
      allow: [write, read]
users:
  oncall: [on-call]
  "*": [everyday]
`)
	plain := connect(t, h, "dev", true, false)
	spaced := connect(t, h, "dev ", true, false)
	_, _ = plain, spaced

	operator := dialWithUser(t, h, "operator", "oncall")
	if code, said := askDisconnect(t, operator, "dev "); code != 0x00 || said != "hung-up" {
		t.Fatalf("hanging up %q was answered 0x%02X %q, want hung-up", "dev ", code, said)
	}
	select {
	case <-spaced.Gone:
	case <-time.After(3 * time.Second):
		t.Error(`the client "dev " was reported hung up and is still connected`)
	}
	if cl, ok := h.Srv.Clients.Get("dev"); !ok || cl.Closed() {
		t.Error(`the client "dev" was hung up by a request naming "dev "`)
	}
}

// RFC 0003 "`append`" - invariant 1: a consumer is never stepped past a record
//
// A consumer the broker has no packet identifier left for is stalled at the
// record it could not send, never moved past it: the pump stops there, says
// so, and serves the record once identifiers free up. Every identifier is
// claimed on the consumer's own session here - the state a client that never
// acknowledges reaches at 65,535.
func TestAConsumerWithNoIdentifierLeftIsStalledNotSkipped(t *testing.T) {
	var warned atomic.Int64
	h := startLogging(t, func(line string) {
		if strings.Contains(line, "packet identifiers exhausted") {
			warned.Add(1)
		}
	})
	sub := connectDurable(t, h, "sub")
	sub.Sub(t, "events/#", 1)
	cl, ok := h.Srv.Clients.Get("sub")
	if !ok {
		t.Fatal("the subscriber is not connected")
	}
	var claimed []uint16
	for id, ok := cl.State.Inflight.Claim(0, 65535); ok; id, ok = cl.State.Inflight.Claim(id, 65535) {
		claimed = append(claimed, uint16(id))
	}
	if len(claimed) < 65000 {
		t.Fatalf("claimed %d identifiers, so the consumer is not out of them", len(claimed))
	}

	p := connect(t, h, "producer", true, false)
	p.Pub(t, "events/x", "r1")
	if r, got := sub.Await(t, 700*time.Millisecond); got {
		t.Fatalf("%q was delivered with every identifier taken", r.Payload)
	}
	if !waitUntil(3*time.Second, func() bool { return warned.Load() > 0 }) {
		t.Fatal("the pump never met the exhausted identifiers, so this proves nothing")
	}

	for _, id := range claimed {
		cl.State.Inflight.Unclaim(id)
	}
	p.Pub(t, "events/x", "r2")
	for _, want := range []string{"r1", "r2"} {
		if r, got := sub.Await(t, 3*time.Second); !got || r.Payload != want {
			t.Fatalf("after the identifiers came back the consumer was served %q (%v), want %q: "+
				"the record it could not be sent was stepped over", r.Payload, got, want)
		}
	}
}

// RFC 0003 "Moving a consumer's position" - invariant 1
//
// A time retention has passed is refused while the channel still holds
// records, not only once it is empty. This is the refusal at its most
// tempting: there is an oldest survivor to serve, and serving it would have
// the consumer read on from there and report success over the gap. The
// retention keeps the newest few of twenty - a stored record is larger than
// its topic and payload, so the bound is a multiple of that - and the control
// counts what the channel still serves.
func TestSeekingToATimeRetentionHasPassedIsRefusedWhileRecordsRemain(t *testing.T) {
	size := store.RecordSize(store.Record{Topic: "events/trimmed", Payload: []byte("r0")})
	h := startTrimming(t, map[string]int64{"events": 8 * size})
	before := time.Now().Add(-time.Second).UTC().Format(time.RFC3339)

	pub := connect(t, h, "publisher", true, false)
	for i := range 20 {
		pub.Pub(t, "events/trimmed", fmt.Sprintf("r%d", i))
	}
	// Long enough for the size sweep, which runs every second.
	time.Sleep(1500 * time.Millisecond)

	reader := dial(t, h, "reader", false, false, 0, 3600, 0)
	reader.Sub(t, "events/#", 1)
	time.Sleep(500 * time.Millisecond)
	t.Logf("the channel serves %d of 20 records", reader.Count())
	if n := reader.Count(); n == 0 || n == 20 {
		t.Fatalf("the channel serves %d of 20 records, so retention has not left some behind "+
			"and this proves nothing", n)
	}

	c := dial(t, h, "late-seeker", false, false, 0, 3600, 0)
	reply := c.Seek(t, "events", before)
	if reply.Payload != "below-floor" {
		t.Fatalf("seeking to a time before records retention removed answered %q while newer "+
			"ones survive, want below-floor", reply.Payload)
	}
}

// RFC 0004 "Memory, with a snapshot" - every failure is reported
//
// A snapshot that cannot be written says so for each thing that was not
// written, not only the first: an operator told one provider failed fixes
// that one and restarts into the next failure, having lost what the others
// held. The directory is made read-only, so every write into it fails -
// channels, with the exactly-once publishes they hold, and sessions alike.
func TestASnapshotThatCannotBeWrittenReportsEveryFailure(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root writes into a read-only directory, so nothing here would fail")
	}
	dir := t.TempDir()
	h := startDurable(t, dir)
	p := connect(t, h, "publisher", true, false)
	p.Pub(t, "events/x", "one")
	if err := h.B.SaveSnapshots(); err != nil {
		t.Fatalf("a snapshot into a writable directory failed (%v), so this proves nothing", err)
	}

	if err := os.Chmod(dir, 0o500); err != nil {
		t.Fatalf("make the directory read-only: %v", err)
	}
	t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
	err := h.B.SaveSnapshots()
	if err == nil {
		t.Fatal("a snapshot into a read-only directory reported success")
	}
	if !strings.Contains(err.Error(), "sessions") {
		t.Errorf("the failure does not name the sessions that were not written: %v", err)
	}
	if !strings.Contains(err.Error(), "could not be written") {
		t.Errorf("more than one failure was reported as one: %v", err)
	}
}

// headGate holds the Next that skipToHead makes while armed. skipToHead reads
// the head before it takes any lock, so a no-replay subscription held there
// holds nothing else. It counts the positions skipToHead stores for one
// reader.
type headGate struct {
	broker.LogStore
	reader  string
	saved   atomic.Int64
	mu      sync.Mutex
	armed   bool
	entered chan struct{}
	release chan struct{}
}

// Unwrap is the store behind the gate, for the broker's type questions.
func (g *headGate) Unwrap() broker.LogStore { return g.LogStore }

func (g *headGate) Next() uint64 {
	g.mu.Lock()
	hold := g.armed && calledFrom("skipToHead")
	if hold {
		g.armed = false
	}
	g.mu.Unlock()
	if hold {
		close(g.entered)
		<-g.release
	}
	return g.LogStore.Next()
}

func (g *headGate) SavePosition(p store.Position) error {
	if p.Reader == g.reader && calledFrom("skipToHead") {
		g.saved.Add(1)
	}
	return g.LogStore.SavePosition(p)
}

// calledFrom reports whether the function of that name is on the caller's
// stack, so a gate on a method many paths call holds only the one it is for.
func calledFrom(name string) bool {
	pcs := make([]uintptr, 64)
	frames := runtime.CallersFrames(pcs[:runtime.Callers(2, pcs)])
	for {
		f, more := frames.Next()
		if strings.HasSuffix(f.Function, "."+name) {
			return true
		}
		if !more {
			return false
		}
	}
}

// RFC 0003 "Moving a consumer's position" - invariant 1
//
// **A subscription asking for no replay moves only the session of the
// connection that made it.** Retain Handling 2 on an append channel stores
// the head as the consumer's position, after the SUBACK. A device that
// subscribed so and reconnected with a clean start before that ran had the
// old connection's head planted for the new session - one that asked for
// every record from the floor, and was served none of them, with nothing
// said.
//
// The old subscription is held at the log until the new session holds the
// id, and what it did is read off the log and the broker's line, so a run
// where it never reached the check cannot pass.
func TestANoReplaySubscriptionFromASupersededConnectionMovesNothing(t *testing.T) {
	var refused atomic.Int64
	g := &headGate{reader: store.MQTTReader("dev"), entered: make(chan struct{}),
		release: make(chan struct{})}
	gateLog(t, "events", func(lg broker.LogStore) broker.LogStore { g.LogStore = lg; return g })
	h := startLogging(t, func(line string) {
		if strings.Contains(line, "a subscription asking for no replay moved nothing") {
			refused.Add(1)
		}
	})
	p := connect(t, h, "producer", true, false)
	for i := 1; i <= 10; i++ {
		p.Pub(t, "events/x", fmt.Sprintf("r%d", i))
	}
	var once sync.Once
	let := func() { once.Do(func() { close(g.release) }) }
	t.Cleanup(let)

	old := dial(t, h, "dev", true, false, 0, 3600, 0)
	g.mu.Lock()
	g.armed = true
	g.mu.Unlock()
	go func() {
		_, _ = old.C.Subscribe(context.Background(), &paho.Subscribe{
			Subscriptions: []paho.SubscribeOptions{{Topic: "events/#", QoS: 1, RetainHandling: 2}}})
	}()
	select {
	case <-g.entered:
	case <-time.After(3 * time.Second):
		t.Fatal("the old connection's no-replay subscription never read the head, so this proves nothing")
	}

	// A clean start: a new session, owed every record from the floor. The old
	// subscription is let go once the new connection has let go of the id's
	// session lock, which is after its clean start ended the old session.
	fresh := dial(t, h, "dev", true, true, 1, 3600, 0)
	if !waitUntil(3*time.Second, func() bool { return h.Srv.SessionLockWaiters("dev") == 0 }) {
		t.Fatal("the new connection never let go of the id's session lock")
	}
	let()
	if !waitUntil(3*time.Second, func() bool { return refused.Load() > 0 || g.saved.Load() > 0 }) {
		t.Fatal("the old subscription neither moved the position nor said it moved nothing")
	}
	fresh.Sub(t, "events/#", 1)
	acked := 0
	for deadline := time.Now().Add(3 * time.Second); time.Now().Before(deadline); time.Sleep(20 * time.Millisecond) {
		all := fresh.All()
		for ; acked < len(all); acked++ {
			all[acked].Ack()
		}
		if acked == 10 {
			break
		}
	}
	var got []string
	for _, r := range fresh.All() {
		got = append(got, r.Payload)
	}
	if want := "[r1 r2 r3 r4 r5 r6 r7 r8 r9 r10]"; fmt.Sprint(got) != want {
		t.Errorf("the new session, which asked for every record, received %v, want %s: the old "+
			"connection's no-replay subscription moved it", got, want)
	}
	if n := g.saved.Load(); n != 0 {
		t.Errorf("the old connection stored %d positions for the id another connection held", n)
	}
	if n := refused.Load(); n != 1 {
		t.Errorf("the old subscription said %d times that it moved nothing, want 1", n)
	}
}

// floorGate holds the first Floor while armed. handleSeek reads the floor
// before it takes any lock, so a seek held there holds nothing else.
type floorGate struct {
	broker.LogStore
	mu      sync.Mutex
	armed   bool
	entered chan struct{}
	release chan struct{}
}

// Unwrap is the store behind the gate, for the broker's type questions.
func (g *floorGate) Unwrap() broker.LogStore { return g.LogStore }

func (g *floorGate) Floor() uint64 {
	g.mu.Lock()
	hold := g.armed
	g.armed = false
	g.mu.Unlock()
	if hold {
		close(g.entered)
		<-g.release
	}
	return g.LogStore.Floor()
}

// RFC 0003 "Moving a consumer's position" - invariant 1
//
// **A seek moves only the session of the connection that sent it.** A device
// sends a seek and reconnects with a clean start while its old connection's
// seek is still being handled: the engine reads that packet before the
// takeover and handles it after. The seek used to move the new session's
// position - one that asked for nothing and starts from the floor. Landing
// after the new session subscribed, it moved the cursor it was reading from
// and the session received r1 and then nothing; landing between its CONNACK
// and its SUBSCRIBE, it was stored for it and the session received none of
// the ten. Nothing said so.
//
// The old seek is held at the log until the successor is where each row
// wants it, and the refusal it meets is read off the log, so a row where it
// never reached the check cannot pass. The control sends no seek.
func TestASeekFromASupersededConnectionMovesNothing(t *testing.T) {
	for _, tc := range []struct {
		name string
		seek bool
		// before is whether the old seek is let go before the successor
		// subscribes, rather than after.
		before bool
	}{
		{"no seek from the old connection (control)", false, false},
		{"the old seek lands after the successor subscribed", true, false},
		{"the old seek lands between the successor's CONNACK and SUBSCRIBE", true, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var refused atomic.Int64
			g := &floorGate{entered: make(chan struct{}), release: make(chan struct{})}
			gateLog(t, "events", func(lg broker.LogStore) broker.LogStore { g.LogStore = lg; return g })
			h := startLogging(t, func(line string) {
				if strings.Contains(line, "refused a seek") && strings.Contains(line, "reason=no-session") {
					refused.Add(1)
				}
			})
			p := connect(t, h, "producer", true, false)
			for i := 1; i <= 10; i++ {
				p.Pub(t, "events/x", fmt.Sprintf("r%d", i))
			}
			old := dial(t, h, "dev", true, false, 0, 3600, 0)
			old.Sub(t, "events/#", 1)
			for i := 0; i < 10; i++ {
				if _, ok := old.Await(t, 2*time.Second); !ok {
					t.Fatalf("the first connection read %d of the 10 records", i)
				}
			}

			var once sync.Once
			let := func() { once.Do(func() { close(g.release) }) }
			t.Cleanup(let)
			if tc.seek {
				g.mu.Lock()
				g.armed = true
				g.mu.Unlock()
				go func() {
					_, _ = old.C.Publish(context.Background(), &paho.Publish{
						Topic: "$saguin/consumer/events/seek", QoS: 1, Payload: []byte("-1")})
				}()
				select {
				case <-g.entered:
				case <-time.After(3 * time.Second):
					t.Fatal("the old connection's seek never reached the log, so this proves nothing")
				}
			}

			// A clean start: a new session, owed every record from the floor.
			fresh := dial(t, h, "dev", true, true, 1, 3600, 0)
			if tc.before {
				let()
				waitUntil(3*time.Second, func() bool { return refused.Load() > 0 })
			}
			fresh.Sub(t, "events/#", 1)
			if _, ok := fresh.Await(t, 2*time.Second); !ok {
				t.Fatal("the new session was sent nothing from the floor")
			}
			if tc.seek && !tc.before {
				let()
				waitUntil(3*time.Second, func() bool { return refused.Load() > 0 })
			}
			acked := 0
			for deadline := time.Now().Add(3 * time.Second); time.Now().Before(deadline); time.Sleep(20 * time.Millisecond) {
				all := fresh.All()
				for ; acked < len(all); acked++ {
					all[acked].Ack()
				}
				if acked == 10 {
					break
				}
			}
			var got []string
			for _, r := range fresh.All() {
				got = append(got, r.Payload)
			}
			if want := "[r1 r2 r3 r4 r5 r6 r7 r8 r9 r10]"; fmt.Sprint(got) != want {
				t.Errorf("the new session, which asked for nothing, received %v, want %s: the old "+
					"connection's seek moved it", got, want)
			}
			if want := map[bool]int64{true: 1, false: 0}[tc.seek]; refused.Load() != want {
				t.Errorf("the old seek was refused no-session %d times, want %d", refused.Load(), want)
			}
		})
	}
}

// takeoverWillConn connects id with a Will of payload on loose/will, delayed
// by delay seconds, in a session of an hour, and returns once it is accepted.
func takeoverWillConn(t *testing.T, addr, id string, clean bool, payload string, delay uint32) net.Conn {
	t.Helper()
	c, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = c.Close() })
	cp := pahopackets.NewControlPacket(pahopackets.CONNECT)
	cn := cp.Content.(*pahopackets.Connect)
	expiry := uint32(3600)
	cn.ClientID, cn.CleanStart, cn.KeepAlive = id, clean, 0
	cn.Properties.SessionExpiryInterval = &expiry
	cn.WillFlag, cn.WillQOS, cn.WillTopic, cn.WillMessage = true, 0, "loose/will", []byte(payload)
	cn.WillProperties = &pahopackets.Properties{WillDelayInterval: &delay}
	if _, err := cp.WriteTo(c); err != nil {
		t.Fatal(err)
	}
	_ = c.SetReadDeadline(time.Now().Add(3 * time.Second))
	ack, err := pahopackets.ReadPacket(c)
	if err != nil {
		t.Fatalf("no CONNACK for %s: %v", payload, err)
	}
	if ca, ok := ack.Content.(*pahopackets.Connack); !ok || ca.ReasonCode != 0 {
		t.Fatalf("%s was refused: %v", payload, ack)
	}
	_ = c.SetReadDeadline(time.Time{})
	return c
}

// RFC 0003 "Sessions: one owner, one ending" - the Will row
//
// **A Will belongs to the session of the connection that armed it.** When
// another connection takes the client id, MQTT 5's note on taking a session
// over says what the old Will does: a delay of 0 publishes it at once; a
// resume inside the delay drops it [MQTT-3.1.3-9]; a clean start publishes
// it, because its session has ended. The same holds for a Will already
// waiting when the device comes back. And the connection that took over
// keeps its own Will on its session.
//
// Measured before: a delayed Will was read back from the id's record when
// its delay ran out, which by then was the new connection's - so the broker
// announced the new connection dead two seconds after it arrived, still
// connected. A clean start cancelled a waiting Will rather than publish it.
// And a resume over a waiting Will took the new connection's own Will off its
// session, so that client's death would never have been announced.
//
// The control is a connection cut with nobody coming back.
func TestAWillIsItsOwnSessionsAcrossATakeover(t *testing.T) {
	for _, tc := range []struct {
		name     string
		delay    uint32
		cutFirst bool   // the old connection is cut first, its Will left waiting
		takeover string // "", "resume" or "clean"
		// want is what the watcher receives, and early whether it arrives
		// inside the first second rather than after the delay.
		want  string
		early bool
	}{
		{"cut, nobody returns (control)", 2, true, "", "OLD", false},
		{"open, taken over by a resume inside the delay", 2, false, "resume", "", false},
		{"open, taken over by a clean start", 2, false, "clean", "OLD", true},
		{"open with no delay, taken over by a resume", 0, false, "resume", "OLD", true},
		{"waiting, the session resumed", 3, true, "resume", "", false},
		{"waiting, a clean start", 3, true, "clean", "OLD", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			w := connect(t, h, "watcher", true, false)
			w.Sub(t, "loose/#", 1)
			old := takeoverWillConn(t, h.Addr, "dev", false, "OLD", tc.delay)
			if tc.cutFirst {
				_ = old.Close()
				time.Sleep(300 * time.Millisecond)
			}
			began := time.Now()
			switch tc.takeover {
			case "resume":
				takeoverWillConn(t, h.Addr, "dev", false, "NEW", 60)
			case "clean":
				takeoverWillConn(t, h.Addr, "dev", true, "NEW", 60)
			}
			var got []string
			var first time.Duration
			for {
				r, ok := w.Await(t, 4*time.Second)
				if !ok {
					break
				}
				if len(got) == 0 {
					first = time.Since(began)
				}
				got = append(got, r.Payload)
			}
			want := []string{}
			if tc.want != "" {
				want = []string{tc.want}
			}
			if fmt.Sprint(got) != fmt.Sprint(want) {
				t.Fatalf("the watcher received %v, want %v", got, want)
			}
			if tc.want != "" && tc.early != (first < time.Second) {
				t.Errorf("%s arrived after %v: want it at once %v", tc.want, first, tc.early)
			}
			if tc.takeover != "" {
				sess, ok, err := brokertest.HarnessSessions.Get("dev")
				if err != nil || !ok || sess.Will == nil || string(sess.Will.Payload) != "NEW" {
					var held string
					if sess.Will != nil {
						held = string(sess.Will.Payload)
					}
					t.Errorf("the connection that took over holds Will %q on its session (%v, %v), want NEW",
						held, ok, err)
				}
			}
		})
	}
}

// RFC 0003 "Sessions" - a clean start's own Will outlives the Will delay of
// the session it ended.
//
// The ended session's Will is published at the clean start (the test above).
// Its delay used to arm the engine's own delayed path with an emptied copy
// anyway, and when the takeover's CONNACK beat the old connection's teardown
// the entry survived: at the delay it cleared the Will of the connection now
// holding the id, which then died with no Will - 14 of 40 runs before the
// fix. This waits past the delay once, so without the fix it fails about one
// run in three; TestAWillItsHookTookLeavesNothingArmed is the deterministic
// half, in the engine.
func TestACleanStartsWillOutlivesTheEndedSessionsDelay(t *testing.T) {
	h := start(t)
	w := connect(t, h, "watcher", true, false)
	w.Sub(t, "loose/#", 1)
	takeoverWillConn(t, h.Addr, "dev", false, "OLD", 1)
	nw := takeoverWillConn(t, h.Addr, "dev", true, "NEW", 0)
	if r, ok := w.Await(t, 3*time.Second); !ok || r.Payload != "OLD" {
		t.Fatalf("the ended session's Will was not published at the clean start: %q, %v", r.Payload, ok)
	}
	time.Sleep(2500 * time.Millisecond) // past OLD's delay, when a stale entry would fall due
	_ = nw.Close()
	if r, ok := w.Await(t, 3*time.Second); !ok || r.Payload != "NEW" {
		t.Errorf("the connection that took the id died and its Will was not published (got %q, %v)",
			r.Payload, ok)
	}
}

// backlogAfter polls a group's backlog until it has want deliveries or a few
// seconds pass, and returns what it last read.
func backlogAfter(t *testing.T, group string, want int) int {
	t.Helper()
	var n int
	for deadline := time.Now().Add(4 * time.Second); ; time.Sleep(50 * time.Millisecond) {
		backlog, err := brokertest.HarnessShares.Backlog(group)
		if err != nil {
			t.Fatal(err)
		}
		n = len(backlog)
		if n == want || time.Now().After(deadline) {
			return n
		}
	}
}

// RFC 0003 "Sessions: one owner, one ending" - a shared group's backlog row
//
// **A backlog left with no member is dropped however the last member's
// session ends**, not only when it expires: a clean start, a disconnect that
// ends the session, and the discard at a stored position retention has
// passed are each an ending, and each used to leave the backlog in the store,
// counted against the provider, for a group nobody could come back to.
// TestAGroupsBacklogGoesWhenItsLastMemberSessionEnds is the expiry.
//
// Each row holds a backlog first, so a row where nothing was held cannot
// pass. The control ends one member's session while another is away with a
// session to come back to, and the backlog stays for it.
func TestAGroupsBacklogGoesHoweverItsLastMemberSessionEnds(t *testing.T) {
	const group = "$share/fleet/alerts/#"
	t.Run("a clean start", func(t *testing.T) {
		h := start(t)
		w := dial(t, h, "worker", false, false, 0, 3600, 0)
		w.Sub(t, group, 1)
		w.Close()
		sessionGone(t, h, "worker")
		p := connect(t, h, "producer", true, false)
		p.Pub(t, "alerts/door", "work")
		if n := backlogAfter(t, group, 1); n != 1 {
			t.Fatalf("the group holds %d, want the one its away member is owed", n)
		}
		dial(t, h, "worker", true, false, 0, 3600, 0)
		if n := backlogAfter(t, group, 0); n != 0 {
			t.Errorf("a clean start ended the group's last member session and the group still "+
				"holds %d", n)
		}
	})
	t.Run("a clean start while another member is away (control)", func(t *testing.T) {
		h := start(t)
		for _, id := range []string{"worker", "other"} {
			w := dial(t, h, id, false, false, 0, 3600, 0)
			w.Sub(t, group, 1)
			w.Close()
			sessionGone(t, h, id)
		}
		p := connect(t, h, "producer", true, false)
		p.Pub(t, "alerts/door", "work")
		if n := backlogAfter(t, group, 1); n != 1 {
			t.Fatalf("the group holds %d, want the one its away members are owed", n)
		}
		dial(t, h, "worker", true, false, 0, 3600, 0)
		time.Sleep(time.Second)
		if n := backlogAfter(t, group, 1); n != 1 {
			t.Errorf("the group holds %d after one member started clean, want 1: another "+
				"member is coming back for it", n)
		}
	})
	t.Run("a disconnect that ends the session", func(t *testing.T) {
		h := start(t)
		w := dial(t, h, "worker", false, false, 0, 3600, 0)
		w.Sub(t, group, 1)
		w.Close()
		sessionGone(t, h, "worker")
		p := connect(t, h, "producer", true, false)
		for i := range 3 {
			p.Pub(t, "alerts/door", fmt.Sprintf("work-%d", i))
		}
		if n := backlogAfter(t, group, 3); n != 3 {
			t.Fatalf("the group holds %d, want the three its away member is owed", n)
		}
		// Back with a session that ends with this connection, and a window of
		// one it does not acknowledge: one delivery goes out, two stay held.
		back := dial(t, h, "worker", false, true, 1, 0, 0)
		if _, ok := back.Await(t, 3*time.Second); !ok {
			t.Fatal("the member was served nothing on its return")
		}
		if n := backlogAfter(t, group, 2); n != 2 {
			t.Fatalf("the group holds %d with the member's window full, want 2", n)
		}
		back.Close()
		if n := backlogAfter(t, group, 0); n != 0 {
			t.Errorf("the group's last member session ended at its disconnect and the group "+
				"still holds %d", n)
		}
	})
	t.Run("a stored position retention passed", func(t *testing.T) {
		h := startTrimming(t, map[string]int64{"events": 200})
		p := connect(t, h, "producer", true, false)
		c := connect(t, h, "worker", false, false)
		c.Sub(t, "events/#", 1)
		c.Sub(t, group, 1)
		p.Pub(t, "events/a/1", "first")
		if _, ok := c.Await(t, 3*time.Second); !ok {
			t.Fatal("no delivery before the link dropped")
		}
		awaitStoredPosition(t, h, "events", 2, 5*time.Second) // the position is stored
		linkCut(t, c)
		p.Pub(t, "alerts/door", "work")
		if n := backlogAfter(t, group, 1); n != 1 {
			t.Fatalf("the group holds %d, want the one its away member is owed", n)
		}
		for i := range 30 {
			p.Pub(t, "events/a/x", fmt.Sprintf("record-%02d-padded-out-to-push-the-floor-along", i))
		}
		awaitFloorPast(t, h, "events", 2, 5*time.Second) // the size sweep past it
		if again := connect(t, h, "worker", false, false); again.SessionPresent {
			t.Fatal("the session was kept, so the floor's discard never ran and this proves nothing")
		}
		if n := backlogAfter(t, group, 0); n != 0 {
			t.Errorf("the floor's discard ended the group's last member session and the group "+
				"still holds %d", n)
		}
	})
}

// positionGate holds the first position a connection's disconnect stores for
// one reader (flushPositionsOf) while armed, and can drop it, as a process
// dying before the write lands would.
type positionGate struct {
	broker.LogStore
	reader  string
	armed   atomic.Bool
	drop    atomic.Bool
	entered chan struct{}
	release chan struct{}
	once    sync.Once
}

// Unwrap is the store behind the gate, for the broker's type questions.
func (g *positionGate) Unwrap() broker.LogStore { return g.LogStore }

func (g *positionGate) SavePosition(p store.Position) error {
	if p.Reader == g.reader && calledFrom("flushPositionsOf") && g.armed.CompareAndSwap(true, false) {
		close(g.entered)
		<-g.release
		if g.drop.Load() {
			return errors.New("the process died before this write")
		}
	}
	return g.LogStore.SavePosition(p)
}

func (g *positionGate) let() { g.once.Do(func() { close(g.release) }) }

// RFC 0003 "A stored position may lag, and never leads"
//
// **After a clean DISCONNECT the position is stored before the connection is
// closed.** A durable consumer acknowledges its last record and disconnects,
// and a broker that dies once the consumer has seen its connection close
// must not send that record again. The engine used to close the socket as it
// handled the DISCONNECT and the position was stored after, so a crash in
// between did exactly that: 8 of 10 on the real binary with kill -9 at the
// consumer's EOF.
//
// The disconnect's position write is held, and the consumer's connection is
// read while it is: it must not be closed yet. Then, with sqlite sessions, the
// broker crashes once the consumer has seen the close - dropping the held
// write if the close came first, as a dying process would - restarts, and the
// resumed consumer must be sent nothing it had acknowledged. Channels are on
// sqlite in both arms, since a memory channel keeps nothing across a crash.
func TestAConsumerThatSawItsConnectionCloseHasItsPositionStored(t *testing.T) {
	for _, arm := range []struct {
		name           string
		memorySessions bool
	}{
		{"sqlite sessions", false},
		{"memory sessions", true},
	} {
		t.Run(arm.name, func(t *testing.T) {
			brokertest.SessionsInMemory = arm.memorySessions
			t.Cleanup(func() { brokertest.SessionsInMemory = false })
			path := filepath.Join(t.TempDir(), "s.db")
			g := &positionGate{reader: store.MQTTReader("dev"), entered: make(chan struct{}),
				release: make(chan struct{})}
			gateLog(t, "events", func(lg broker.LogStore) broker.LogStore { g.LogStore = lg; return g })
			h := startDurableSQLite(t, path)
			p := connect(t, h, "producer", true, false)
			for i := 1; i <= 3; i++ {
				p.Pub(t, "events/x", fmt.Sprintf("r%d", i))
			}
			t.Cleanup(g.let)

			dev, _ := qos2Dial(t, h.Addr, "dev", true, 300)
			dev.Subscribe("events/#", 1)
			var last uint16
			for n := 0; n < 3; {
				pub, ok := dev.Next(3 * time.Second).Content.(*pahopackets.Publish)
				if !ok {
					continue
				}
				n++
				if n < 3 {
					dev.Puback(pub.PacketID)
				} else {
					last = pub.PacketID
				}
			}
			// The last acknowledgement and the DISCONNECT together, as a
			// consumer leaving sends them.
			g.armed.Store(true)
			dev.Puback(last)
			if _, err := dev.C.Write([]byte{0xE0, 0x00}); err != nil {
				t.Fatalf("write DISCONNECT: %v", err)
			}
			select {
			case <-g.entered:
			case <-time.After(5 * time.Second):
				t.Fatal("the disconnect stored no position for the consumer, so this proves nothing")
			}
			_ = dev.C.SetReadDeadline(time.Now().Add(300 * time.Millisecond))
			_, err := pahopackets.ReadPacket(dev.C)
			var ne net.Error
			closed := err != nil && !(errors.As(err, &ne) && ne.Timeout())
			if closed {
				t.Errorf("the consumer's connection was closed while its position was still being "+
					"stored (%v): a broker dying now sends it what it acknowledged again", err)
				g.drop.Store(true)
			}
			g.let()
			_ = dev.C.SetReadDeadline(time.Now().Add(5 * time.Second))
			for {
				if _, err := pahopackets.ReadPacket(dev.C); err != nil {
					break
				}
			}
			if arm.memorySessions {
				return // a memory session does not survive the crash below
			}

			h.Crash()
			h2 := startDurableSQLite(t, path)
			back, ca := qos2Dial(t, h2.Addr, "dev", false, 300)
			defer back.Close()
			if !ca.SessionPresent {
				t.Fatal("the consumer's session was not restored after the crash")
			}
			p2 := connect(t, h2, "producer-2", true, false)
			p2.Pub(t, "events/x", "marker")
			var again []string
			for {
				pub, ok := back.Next(3 * time.Second).Content.(*pahopackets.Publish)
				if !ok {
					continue
				}
				back.Puback(pub.PacketID)
				if string(pub.Payload) == "marker" {
					break
				}
				again = append(again, string(pub.Payload))
			}
			if len(again) != 0 {
				t.Errorf("after the crash the consumer was sent %v again, which it had acknowledged "+
					"before its DISCONNECT", again)
			}
		})
	}
}

// refusedTotal is every saguin_connections_refused_total series summed.
func refusedTotal(t *testing.T, ops string) float64 {
	t.Helper()
	var total float64
	for name, v := range scrapeGauges(t, ops) {
		if strings.HasPrefix(name, "saguin_connections_refused_total{") {
			total += v
		}
	}
	return total
}

// MQTT 5 section 4.13.1, and RFC 0005 "What these two cover"
//
// **A packet refused while it is decoded is answered with its reason code
// before the connection is closed, and counted as a refused connection.**
// The server must close the connection; for a packet after the CONNECT it
// should send a DISCONNECT carrying the reason first, and for a CONNECT it
// may send a CONNACK carrying it - which is what mosquitto and EMQX do,
// measured and read. A client below MQTT 5, and one refused before its
// CONNECT said which version it speaks, is closed with nothing written.
// Every arm is counted in saguin_connections_refused_total, and listed on
// /v1/operations/refused where the refusal came after the client id. Each
// packet is written as bytes, since a client library refuses to build one
// this malformed, and what the broker sent back is read off the wire.
func TestAPacketRefusedWhileItIsDecodedIsAnsweredWithItsReasonCode(t *testing.T) {
	connect := func(version byte, props ...byte) []byte {
		body := []byte{0x00, 0x04, 'M', 'Q', 'T', 'T', version, 0x02, 0x00, 0x3c}
		if version >= 5 {
			body = append(body, byte(len(props)))
			body = append(body, props...)
		}
		body = append(body, 0x00, 0x04, 'w', 'i', 'r', 'e')
		return append([]byte{0x10, byte(len(body))}, body...)
	}
	const nothing, connack, disconnect = "nothing", "CONNACK", "DISCONNECT"
	for _, tc := range []struct {
		name    string
		connect []byte
		packet  []byte // after an accepted CONNECT, or nil where the CONNECT itself is refused
		answer  string
		code    byte   // the answer's reason code
		reason  string // the saguin_connections_refused_total label
		listed  bool   // the refusal came after the client id
	}{{
		name:    "a SUBSCRIBE with Retain Handling 3",
		connect: connect(5),
		// packet id 1, no properties, filter "a", options: Retain Handling 3, QoS 1
		packet: []byte{0x82, 0x07, 0x00, 0x01, 0x00, 0x00, 0x01, 'a', 0x31},
		answer: disconnect, code: 0x82, reason: "protocol error", listed: true, // 3.8.3.1: a Protocol Error
	}, {
		name:    "a PUBLISH with both QoS bits set",
		connect: connect(5),
		// topic "a", packet id 1, no properties, payload "x"
		packet: []byte{0x36, 0x07, 0x00, 0x01, 'a', 0x00, 0x01, 0x00, 'x'},
		answer: disconnect, code: 0x81, reason: "malformed packet", listed: true,
	}, {
		name:    "a PUBLISH whose topic runs past the packet",
		connect: connect(5),
		// a topic of five bytes declared, and none sent: the decoder wraps its code
		packet: []byte{0x30, 0x02, 0x00, 0x05},
		answer: disconnect, code: 0x81, reason: "malformed packet", listed: true,
	}, {
		name:    "a 3.1.1 PUBLISH with both QoS bits set",
		connect: connect(4),
		// topic "a", packet id 1, payload "x"
		packet: []byte{0x36, 0x06, 0x00, 0x01, 'a', 0x00, 0x01, 'x'},
		answer: nothing, reason: "malformed packet", listed: true,
	}, {
		name:    "a CONNECT carrying a Topic Alias",
		connect: connect(5, 0x23, 0x00, 0x01),
		answer:  connack, code: 0x81, reason: "malformed packet",
	}, {
		name:    "a first packet that is not a CONNECT",
		connect: []byte{0xC0, 0x00}, // PINGREQ
		answer:  nothing, reason: "protocol error",
	}} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			ops := operationsAt(t, h)
			before := h.Disconnects.Snapshot("wire")
			conn, err := net.DialTimeout("tcp", h.Addr, 3*time.Second)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			defer conn.Close()
			_ = conn.SetDeadline(time.Now().Add(5 * time.Second))
			if _, err := conn.Write(tc.connect); err != nil {
				t.Fatalf("write CONNECT: %v", err)
			}
			if tc.packet != nil {
				if tc.connect[8] >= 5 {
					cp, err := pahopackets.ReadPacket(conn)
					if err != nil {
						t.Fatalf("the CONNECT was not answered: %v", err)
					}
					if ca, ok := cp.Content.(*pahopackets.Connack); !ok || ca.ReasonCode != 0 {
						t.Fatalf("the CONNECT was answered %s, want an accepting CONNACK", cp)
					}
				} else {
					ack := make([]byte, 4) // 20 02 00 00 accepts it below MQTT 5
					if _, err := io.ReadFull(conn, ack); err != nil || ack[0] != 0x20 || ack[3] != 0 {
						t.Fatalf("the CONNECT was answered % x (%v), want an accepting CONNACK", ack, err)
					}
				}
				if _, err := conn.Write(tc.packet); err != nil {
					t.Fatalf("write the packet: %v", err)
				}
			}
			if tc.answer == nothing {
				if got, err := io.ReadAll(conn); err != nil || len(got) != 0 {
					t.Fatalf("answered % x (%v), want the connection closed with nothing written",
						got, err)
				}
			} else {
				cp, err := pahopackets.ReadPacket(conn)
				if err != nil {
					t.Fatalf("the refused packet was answered by the connection closing (%v), with no "+
						"reason code; want %s 0x%02X", err, tc.answer, tc.code)
				}
				var got string
				var code byte
				switch c := cp.Content.(type) {
				case *pahopackets.Connack:
					got, code = connack, c.ReasonCode
				case *pahopackets.Disconnect:
					got, code = disconnect, c.ReasonCode
				default:
					t.Fatalf("answered %s, want %s 0x%02X", cp, tc.answer, tc.code)
				}
				if got != tc.answer || code != tc.code {
					t.Fatalf("answered %s 0x%02X, want %s 0x%02X", got, code, tc.answer, tc.code)
				}
				if _, err := pahopackets.ReadPacket(conn); err == nil {
					t.Fatal("the connection stayed open after the refusal")
				}
			}

			// Counted before the connection is closed, so read at once; the
			// sum once the connection is torn down, so a second count has
			// had its chance.
			series := `saguin_connections_refused_total{reason="` + tc.reason + `"}`
			if got := scrapeGauges(t, ops)[series]; got != 1 {
				t.Errorf("%s is %v, want 1: the refusal was not counted", series, got)
			}
			if tc.packet != nil {
				sessionGoneAfter(t, h, "wire", before)
			}
			if got := refusedTotal(t, ops); got != 1 {
				t.Errorf("saguin_connections_refused_total sums to %v over every reason, want 1", got)
			}
			row, ok := refusalRecord(t, ops)["wire"]
			switch {
			case tc.listed && !ok:
				t.Errorf("/v1/operations/refused does not name the client: %+v", refusalRecord(t, ops))
			case tc.listed && (row.Count != 1 || row.Reason != tc.reason):
				t.Errorf("/v1/operations/refused has %+v, want one refusal for %q", row, tc.reason)
			case !tc.listed && ok:
				t.Errorf("/v1/operations/refused names a client the broker never read: %+v", row)
			}
		})
	}
}

// RFC 0005 "What these two cover"
//
// **A connection ended for something other than a refusal is not counted as
// one.** The engine counts a connection it ends for a refusal (the test
// above), and ends connections for two reasons that are not refusals and
// send a reason code too: a takeover, 0x8E, and a shutdown, 0x8B. Neither is
// counted, and neither is listed.
func TestAConnectionEndedByATakeoverOrAShutdownIsNotCountedAsRefused(t *testing.T) {
	h := start(t)
	ops := operationsAt(t, h)
	connectDev := func() net.Conn {
		t.Helper()
		conn, err := net.DialTimeout("tcp", h.Addr, 3*time.Second)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		t.Cleanup(func() { _ = conn.Close() })
		_ = conn.SetDeadline(time.Now().Add(5 * time.Second))
		body := []byte{0x00, 0x04, 'M', 'Q', 'T', 'T', 0x05, 0x02, 0x00, 0x3c, 0x00, 0x00, 0x03, 'd', 'e', 'v'}
		if _, err := conn.Write(append([]byte{0x10, byte(len(body))}, body...)); err != nil {
			t.Fatalf("write CONNECT: %v", err)
		}
		cp, err := pahopackets.ReadPacket(conn)
		if err != nil {
			t.Fatalf("read CONNACK: %v", err)
		}
		if ca, ok := cp.Content.(*pahopackets.Connack); !ok || ca.ReasonCode != 0 {
			t.Fatalf("the CONNECT was answered %s, want an accepting CONNACK", cp)
		}
		return conn
	}
	ended := func(conn net.Conn, want byte) {
		t.Helper()
		cp, err := pahopackets.ReadPacket(conn)
		if err != nil {
			t.Fatalf("the connection closed (%v) without its DISCONNECT 0x%02X", err, want)
		}
		if d, ok := cp.Content.(*pahopackets.Disconnect); !ok || d.ReasonCode != want {
			t.Fatalf("the connection was sent %s, want DISCONNECT 0x%02X", cp, want)
		}
	}

	before := h.Disconnects.Snapshot("dev")
	old := connectDev()
	current := connectDev()
	ended(old, 0x8E)
	sessionGoneAfter(t, h, "dev", before) // the taken-over connection has been torn down
	if got := refusedTotal(t, ops); got != 0 {
		t.Errorf("after a takeover saguin_connections_refused_total sums to %v, want 0", got)
	}

	h.Stop()
	ended(current, 0x8B)
	if got := refusedTotal(t, ops); got != 0 {
		t.Errorf("after a shutdown saguin_connections_refused_total sums to %v, want 0", got)
	}
	if rows := refusalRecord(t, ops); len(rows) != 0 {
		t.Errorf("/v1/operations/refused lists %+v, want nobody", rows)
	}
}

// RFC 0005 "What these two cover"
//
// **A connection the engine ends for a refusal once a packet is read is
// counted once, on either protocol.** The packet is decoded and then
// refused: a publish topic carrying a wildcard, which the read loop ends the
// connection for, and a publish naming a topic alias its connection never
// registered or a 3.1.1 publish into $SYS at QoS 1, which the publish path
// ends the connection for itself and then returns its code to the read loop.
// An MQTT 5 client is answered with a DISCONNECT and a 3.1.1 one closed. The
// count is read once the connection is torn down, when a second would have
// landed.
func TestAConnectionEndedForARefusedPacketIsCountedOnce(t *testing.T) {
	v5 := []byte{0x10, 0x11, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x05, 0x02, 0x00, 0x3c, 0x00,
		0x00, 0x04, 'w', 'i', 'r', 'e'}
	v311 := []byte{0x10, 0x10, 0x00, 0x04, 'M', 'Q', 'T', 'T', 0x04, 0x02, 0x00, 0x3c,
		0x00, 0x04, 'w', 'i', 'r', 'e'}
	for _, tc := range []struct {
		name    string
		connect []byte
		packet  []byte
		answer  byte // the DISCONNECT's reason, or 0 for a close with nothing written
		reason  string
	}{{
		name:    "an MQTT 5 publish whose topic carries a wildcard",
		connect: v5,
		// topic "a/#", no properties, payload "x"
		packet: []byte{0x30, 0x07, 0x00, 0x03, 'a', '/', '#', 0x00, 'x'},
		answer: 0x82, reason: "protocol error",
	}, {
		name:    "a 3.1.1 publish whose topic carries a wildcard",
		connect: v311,
		// topic "a/#", payload "x"
		packet: []byte{0x30, 0x06, 0x00, 0x03, 'a', '/', '#', 'x'},
		reason: "protocol error",
	}, {
		name:    "an MQTT 5 publish naming an alias never registered",
		connect: v5,
		// QoS 1, no topic, packet id 1, Topic Alias 1, payload "x"
		packet: []byte{0x32, 0x09, 0x00, 0x00, 0x00, 0x01, 0x03, 0x23, 0x00, 0x01, 'x'},
		answer: 0x82, reason: "protocol error",
	}, {
		name:    "a 3.1.1 publish into $SYS at QoS 1",
		connect: v311,
		// topic "$SYS/x", packet id 1, payload "x"
		packet: []byte{0x32, 0x0b, 0x00, 0x06, '$', 'S', 'Y', 'S', '/', 'x', 0x00, 0x01, 'x'},
		reason: "not authorized",
	}} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			ops := operationsAt(t, h)
			before := h.Disconnects.Snapshot("wire")
			conn, err := net.DialTimeout("tcp", h.Addr, 3*time.Second)
			if err != nil {
				t.Fatalf("dial: %v", err)
			}
			defer conn.Close()
			_ = conn.SetDeadline(time.Now().Add(5 * time.Second))
			if _, err := conn.Write(tc.connect); err != nil {
				t.Fatalf("write CONNECT: %v", err)
			}
			if tc.connect[8] >= 5 {
				cp, err := pahopackets.ReadPacket(conn)
				if err != nil {
					t.Fatalf("the CONNECT was not answered: %v", err)
				}
				if ca, ok := cp.Content.(*pahopackets.Connack); !ok || ca.ReasonCode != 0 {
					t.Fatalf("the CONNECT was answered %s, want an accepting CONNACK", cp)
				}
			} else {
				ack := make([]byte, 4)
				if _, err := io.ReadFull(conn, ack); err != nil || ack[0] != 0x20 || ack[3] != 0 {
					t.Fatalf("the CONNECT was answered % x (%v), want an accepting CONNACK", ack, err)
				}
			}
			if _, err := conn.Write(tc.packet); err != nil {
				t.Fatalf("write the packet: %v", err)
			}
			if tc.answer == 0 {
				if got, err := io.ReadAll(conn); err != nil || len(got) != 0 {
					t.Fatalf("answered % x (%v), want the connection closed with nothing written",
						got, err)
				}
			} else {
				cp, err := pahopackets.ReadPacket(conn)
				if err != nil {
					t.Fatalf("the connection closed (%v) without its DISCONNECT 0x%02X", err, tc.answer)
				}
				if d, ok := cp.Content.(*pahopackets.Disconnect); !ok || d.ReasonCode != tc.answer {
					t.Fatalf("answered %s, want DISCONNECT 0x%02X", cp, tc.answer)
				}
			}
			sessionGoneAfter(t, h, "wire", before)

			series := `saguin_connections_refused_total{reason="` + tc.reason + `"}`
			if got := scrapeGauges(t, ops)[series]; got != 1 {
				t.Errorf("%s is %v, want 1", series, got)
			}
			if got := refusedTotal(t, ops); got != 1 {
				t.Errorf("saguin_connections_refused_total sums to %v over every reason, want 1", got)
			}
			if row := refusalRecord(t, ops)["wire"]; row.Count != 1 || row.Reason != tc.reason {
				t.Errorf("/v1/operations/refused has %+v for the client, want one refusal for %q",
					row, tc.reason)
			}
		})
	}
}

// RFC 0002 "Publishing": a publish into the reserved `$saguin/` space that
// is neither a seek nor a response is refused 0x90 - **and a topic whose
// prefix and suffix overlap is neither**. The
// control-topic parsers sliced between a prefix and a suffix they had
// asked of the whole topic, and `$saguin/consumer/seek` - where the two
// share a `/` - panicked: one PUBLISH from any client a door admitted, before
// any permission was asked, and the broker exited. The subscribe path's
// SeekReplyChannel reached the same code. Each is sent here by a real
// client, and then the broker must still be serving another.
func TestAnOverlappingControlTopicIsRefusedAndTheBrokerKeepsServing(t *testing.T) {
	h := start(t)
	c := connect(t, h, "prober", true, false)
	for _, topic := range []string{"$saguin/consumer/seek", "$saguin/queue/response"} {
		if code := pubCode(t, c, topic, []byte("x")); code != 0x90 {
			t.Errorf("a publish to %s was answered 0x%02X, want 0x90: it is not a control topic "+
				"saguin defines", topic, code)
		}
	}
	sa, err := c.C.Subscribe(context.Background(), &paho.Subscribe{
		Subscriptions: []paho.SubscribeOptions{{Topic: "$saguin/consumer/seek/reply", QoS: 1}}})
	if sa == nil {
		t.Fatalf("no SUBACK for the overlapping reply topic: %v", err)
	}

	// Still serving: a new connection, a subscription and a delivery.
	r := connect(t, h, "reader", true, false)
	r.Sub(t, "check/#", 1)
	c.Pub(t, "check/alive", "yes")
	if got, ok := r.Await(t, 3*time.Second); !ok || got.Payload != "yes" {
		t.Fatalf("the broker did not deliver after the overlapping control topics (got %q, %v)",
			got.Payload, ok)
	}
}

// **A bridge peer's empty-topic PUBLISH is dropped, and the broker keeps
// serving**. A `both` rule is an identity rule,
// and `#` matches the empty topic; the identity branch read the topic's
// first byte without asking whether there was one, the bridge's worker
// panicked, and the broker exited. A zero-length topic is a malformed
// PUBLISH that a conforming broker never sends, but the bridge is a client
// and paho hands one on unchecked, so a foreign or broken peer is enough.
//
// The peer here is a few lines of raw MQTT 5, because no library will send
// the packet: it answers CONNECT and SUBSCRIBE, then sends an empty-topic
// PUBLISH and, behind it, an ordinary one. The ordinary one arriving at a
// local subscriber is the proof that the worker lived past the first, and
// the drop is counted where every covered-and-unplaceable record is
// (saguin_bridge_unstored_total{cause="unmappable"}).
func TestABridgePeersEmptyTopicIsDroppedAndTheBrokerKeepsServing(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = ln.Close() })
	sent := make(chan error, 1)
	go func() {
		conn, err := ln.Accept()
		if err != nil {
			sent <- err
			return
		}
		defer conn.Close()
		// read one packet: its first byte and its body.
		read := func() (byte, []byte, error) {
			var hdr [1]byte
			if _, err := io.ReadFull(conn, hdr[:]); err != nil {
				return 0, nil, err
			}
			n, shift := 0, 0
			for {
				var b [1]byte
				if _, err := io.ReadFull(conn, b[:]); err != nil {
					return 0, nil, err
				}
				n |= int(b[0]&0x7f) << shift
				if b[0]&0x80 == 0 {
					break
				}
				shift += 7
			}
			body := make([]byte, n)
			_, err := io.ReadFull(conn, body)
			return hdr[0], body, err
		}
		if typ, _, err := read(); err != nil || typ>>4 != 1 {
			sent <- fmt.Errorf("expected CONNECT, got 0x%02X (%v)", typ, err)
			return
		}
		_, _ = conn.Write([]byte{0x20, 0x03, 0x00, 0x00, 0x00}) // CONNACK: no session, success, no properties
		// A PINGREQ may come first - MQTT allows one at any time - and is
		// answered; anything else before the SUBSCRIBE is a failure.
		var body []byte
		for {
			typ, b, err := read()
			if err == nil && typ>>4 == 12 {
				_, _ = conn.Write([]byte{0xD0, 0x00})
				continue
			}
			if err != nil || typ>>4 != 8 || len(b) < 2 {
				sent <- fmt.Errorf("expected SUBSCRIBE, got 0x%02X (%v)", typ, err)
				return
			}
			body = b
			break
		}
		_, _ = conn.Write([]byte{0x90, 0x04, body[0], body[1], 0x00, 0x00}) // SUBACK: granted QoS 0
		publish := func(topic, payload string) []byte {
			rem := 2 + len(topic) + 1 + len(payload)
			p := []byte{0x30, byte(rem), byte(len(topic) >> 8), byte(len(topic))}
			p = append(p, topic...)
			p = append(p, 0x00) // no properties
			return append(p, payload...)
		}
		if _, err := conn.Write(append(publish("", "empty"), publish("check/alive", "yes")...)); err != nil {
			sent <- err
			return
		}
		sent <- nil
		for { // answer keepalives, and read whatever else until the test ends
			typ, _, err := read()
			if err != nil {
				return
			}
			if typ>>4 == 12 {
				_, _ = conn.Write([]byte{0xD0, 0x00})
			}
		}
	}()

	h := start(t)
	path := filepath.Join(t.TempDir(), "saguin.yaml")
	if err := os.WriteFile(path, []byte(fmt.Sprintf(`broker:
  id: t
`+brokertest.MemStorage+`channels:
  events:
    type: append
bridges:
  mirror:
    peer: tcp://%s
    client_id: mirror
    topics:
      - filter: "#"
        direction: both
`, ln.Addr())), 0o600); err != nil {
		t.Fatal(err)
	}
	f, _, err := config.Load(path)
	if err != nil {
		t.Fatalf("the test's own bridge configuration does not load: %v", err)
	}
	cfg := f.BridgeSet()[0]
	r := connect(t, h, "reader", true, false)
	r.Sub(t, "check/#", 0)
	br := bridge.New(cfg, h.B.NewBridgeClient(cfg.Name), limits,
		slog.New(slog.NewTextHandler(io.Discard, nil)), nil)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { defer close(done); _ = br.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		select {
		case <-done:
		case <-time.After(5 * time.Second):
			t.Error("the bridge did not stop")
		}
	})

	select {
	case err := <-sent:
		if err != nil {
			t.Fatalf("the fake peer: %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the bridge never connected and subscribed to the fake peer, so nothing below is about it")
	}
	if got, ok := r.Await(t, 3*time.Second); !ok || got.Payload != "yes" {
		t.Fatalf("the record behind the empty-topic PUBLISH never arrived (got %q, %v): the bridge's "+
			"worker did not survive it", got.Payload, ok)
	}
	if n := br.UnstoredUnmappable(); n != 1 {
		t.Errorf("the empty-topic record was counted unstored{unmappable} %d times, want 1", n)
	}
}

// seriesSum is the sum of every series of one metric in a scrape.
func seriesSum(g map[string]float64, metric string) float64 {
	var n float64
	for k, v := range g {
		if k == metric || strings.HasPrefix(k, metric+"{") {
			n += v
		}
	}
	return n
}

// RFC 0003 "What is refused, and when": "One question is asked again when
// the Will fires: may its client still publish there ... Nothing else is
// refused when the Will fires."
//
// **The publish rate is not a question a Will is asked.** Every Will is
// published as the one Will client, so a budget keyed by client id made
// every client's Will share one: at publish_rate 2, six clients dying
// together had two Wills delivered and four refused and lost, each client
// having been answered 0x00 at CONNECT.
func TestEveryClientsWillIsPublishedWhateverThePublishRate(t *testing.T) {
	for _, rate := range []int{0, 2} {
		t.Run(fmt.Sprintf("publish_rate %d", rate), func(t *testing.T) {
			brokertest.PublishCeiling = rate
			t.Cleanup(func() { brokertest.PublishCeiling = 0 })
			h := start(t)
			ops := operationsAt(t, h)
			w := connect(t, h, "watcher", true, false)
			w.Sub(t, "loose/#", 1)
			var conns []net.Conn
			for i := range 6 {
				conn, code := connectWithWill(t, h, fmt.Sprintf("dev-%d", i),
					fmt.Sprintf("loose/will/%d", i), false, 0, 1)
				if code != 0 {
					t.Fatalf("CONNECT %d: 0x%02X", i, code)
				}
				conns = append(conns, conn)
			}
			for _, c := range conns {
				kill(t, c)
			}
			got := map[string]bool{}
			for {
				r, ok := w.Await(t, 1500*time.Millisecond)
				if !ok {
					break
				}
				got[r.Topic] = true
			}
			g := scrapeGauges(t, ops)
			if len(got) != 6 {
				t.Errorf("%d of 6 Wills were delivered at publish_rate %d (publishes refused: %v): "+
					"the Wills of different clients shared one budget", len(got), rate,
					seriesSum(g, "saguin_publish_refused_total"))
			}
			if n := seriesSum(g, "saguin_wills_published_total"); n != 6 {
				t.Errorf("saguin_wills_published_total reads %v for 6 Wills delivered", n)
			}
		})
	}
}

// RFC 0003 "What is refused, and when": a Will the publish path refuses
// when it fires - a full channel, a storage failure - "is logged and no
// more", and RFC 0005's saguin_wills_published_total counts "Wills this
// broker published on a client's behalf".
//
// **Counted on the injection's nil, it counted Wills nobody received.** The
// server answers a refusal with an acknowledgement to the Will client, which
// has no connection, so InjectPacket returns nil either way: a Will refused
// by a full channel read as published.
func TestAWillTheChannelRefusesIsNotCountedPublished(t *testing.T) {
	one := store.RecordSize(store.Record{
		MessageID: "0123456789012345678901234567890123456",
		Topic:     "events/orders/1",
		Payload:   []byte("0123456789"),
	})
	for _, full := range []bool{false, true} {
		name := "room"
		if full {
			name = "full"
		}
		t.Run(name, func(t *testing.T) {
			h := startBounded(t, "", map[string]int64{"events": one + one/2})
			ops := operationsAt(t, h)
			reader := connect(t, h, "reader", true, false)
			reader.Sub(t, "events/#", 1)
			if full {
				c := connect(t, h, "producer", true, false)
				ack, _ := c.C.Publish(context.Background(), &paho.Publish{
					Topic: "events/orders/1", QoS: 1, Payload: []byte("0123456789")})
				if ack == nil || ack.ReasonCode != 0 {
					t.Fatalf("the filling publish: %v", ack)
				}
				ack, _ = c.C.Publish(context.Background(), &paho.Publish{
					Topic: "events/orders/2", QoS: 1, Payload: []byte("0123456789")})
				if ack == nil || ack.ReasonCode != 0x97 {
					t.Fatalf("the channel is not full, so nothing below is about the class: "+
						"a second publish was answered %v", ack)
				}
				_, _ = reader.Await(t, time.Second) // the one that fit
			}
			conn, code := connectWithWill(t, h, "dying", "events/orders/will", false, 0, 1)
			if code != 0 {
				t.Fatalf("CONNECT 0x%02X", code)
			}
			kill(t, conn)
			_, delivered := reader.Await(t, 1500*time.Millisecond)
			published := seriesSum(scrapeGauges(t, ops), "saguin_wills_published_total")
			if delivered != !full {
				t.Fatalf("with the channel %s the Will was delivered: %v", name, delivered)
			}
			if want := map[bool]float64{false: 1, true: 0}[full]; published != want {
				t.Errorf("with the channel %s, saguin_wills_published_total reads %v, want %v",
					name, published, want)
			}
		})
	}
}

// RFC 0003 "What is refused, and when": 0x90 at CONNECT for a Will on "a
// topic name nothing may publish to at all", which RFC 0002 "Publishing"
// says includes one beginning `$share/`.
//
// **The Will asked a different question from the publish path.** It asked
// the substrate's filter check alone, which accepts `$share/g/x`, so the
// CONNECT was answered 0x00 and the Will refused when it fired, reaching
// nobody: a device told its death announcement was armed when it could never
// be sent.
func TestAWillOnAShareTopicIsRefusedAtConnect(t *testing.T) {
	for _, tc := range []struct {
		name, topic string
		want        byte
	}{
		{"control, a broadcast topic", "loose/from-a-will", 0x00},
		{"control, the reserved space", "$saguin/x", 0x90},
		{"$share, a broadcast filter", "$share/g/loose/from-a-will", 0x90},
		{"$share, on a channel", "$share/g/events/from-a-will", 0x90},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := start(t)
			conn, code := connectWithWill(t, h, "dying", tc.topic, false, 0, 1)
			defer conn.Close()
			if code != tc.want {
				t.Errorf("a CONNECT with a Will on %q was answered 0x%02X, want 0x%02X",
					tc.topic, code, tc.want)
			}
		})
	}
}

// RFC 0002 "How fast one client may publish": the entry that applies to a
// client's user name supplies its figures, and "a budget belongs to the
// client" - the client id.
//
// **The figures were cached per client id, and so never re-read when a
// different user took the id over.** A client could exceed its own limit by
// taking over a faster client's id: device-1 (3/s) taking an id device-7
// (200/s) held sent 20 with none refused, and device-7 reconnecting under
// an id device-1 had used was held to 3/s.
func TestPublishLimitsFollowTheUserNotTheClientID(t *testing.T) {
	h := start(t)
	acl := filepath.Join(t.TempDir(), "acl.yaml")
	if err := os.WriteFile(acl, []byte(`
roles:
  publisher:
    - topic: "loose/#"
      allow: [write, read]
users:
  "device-*":
    roles: [publisher]
    limits:
      publish_rate: 3
  "device-7":
    roles: [publisher]
    limits:
      publish_rate: 200
`), 0o600); err != nil {
		t.Fatal(err)
	}
	f, err := authz.Load(acl, h.B.Registry(), 0)
	if err != nil {
		t.Fatalf("load acl: %v", err)
	}
	h.B.Authorize(authz.New(f, h.B.Registry()))

	refusedOf := func(c *client, n int) int {
		t.Helper()
		refused := 0
		for i := range n {
			resp, _ := c.C.Publish(context.Background(), &paho.Publish{
				Topic: "loose/x", QoS: 1, Payload: []byte("x")})
			switch {
			case resp == nil:
				t.Fatalf("publish %d: no PUBACK", i)
			case resp.ReasonCode == 0x97:
				refused++
			case resp.ReasonCode != 0:
				t.Fatalf("publish %d answered 0x%02X", i, resp.ReasonCode)
			}
		}
		return refused
	}

	// The controls, each user on an id nobody has used: 3/s refuses most of
	// a burst of twenty and 200/s none, so the rest can tell them apart.
	c := dialWithUser(t, h, "fresh-1", "device-1")
	if r := refusedOf(c, 20); r == 0 {
		t.Fatal("device-1 (3/s) was refused none of 20, so nothing below can be told apart")
	}
	c.Close()
	c = dialWithUser(t, h, "fresh-7", "device-7")
	if r := refusedOf(c, 20); r != 0 {
		t.Fatalf("device-7 (200/s) was refused %d of 20 on a fresh id", r)
	}
	c.Close()

	t.Run("a faster user under an id a slower one used", func(t *testing.T) {
		c := dialWithUser(t, h, "shared-a", "device-1")
		refusedOf(c, 20)
		c.Close()
		c = dialWithUser(t, h, "shared-a", "device-7")
		defer c.Close()
		refusedOf(c, 20)
		// The budget is the id's and carries over, so a full second later
		// the bucket is full at whatever rate was resolved.
		time.Sleep(1200 * time.Millisecond)
		if r := refusedOf(c, 20); r != 0 {
			t.Errorf("device-7 (200/s) was refused %d of 20 a second after its burst, under an "+
				"id device-1 (3/s) had used: the figures followed the client id", r)
		}
	})
	t.Run("a slower user taking over a faster one's id", func(t *testing.T) {
		c7 := dialWithUser(t, h, "shared-b", "device-7")
		refusedOf(c7, 1)
		c1 := dialWithUser(t, h, "shared-b", "device-1")
		defer c1.Close()
		if r := refusedOf(c1, 20); r == 0 {
			t.Errorf("device-1 (3/s) sent 20 with none refused after taking over an id device-7 " +
				"(200/s) held: it published at the figures of the client it replaced")
		}
	})
}

// MQTT 3.1.1 [MQTT-3.1.2-2]: a server answers `0x01` (unacceptable protocol
// level) to a Protocol Level it does not support, and RFC 0002's CONNACK row
// says MQTT 3.1 is always answered `0x01`.
//
// **"MQTT" at level 3 was answered `0x05`.** The substrate refuses it as a
// name that does not match its level, `0x82`, and the translation to a
// 3.1.1 return code rewrote `0x82` to `0x01` only for levels 0 and above 5,
// so level 3 fell to the clamp: a device told it was not authorized when
// the fix is its protocol.
func TestAnUnsupportedProtocolLevelIsAnswered0x01(t *testing.T) {
	h := start(t)
	for _, tc := range []struct {
		name  string
		level byte
		want  byte
	}{
		{"MQTT", 3, 0x01},
		{"MQIsdp", 3, 0x01}, // control: MQTT 3.1, refused by saguin's own gate
		{"MQTT", 0, 0x01},   // control: the level the first branch was written for
		{"MQTT", 4, 0x00},   // control: MQTT 3.1.1 is admitted
	} {
		t.Run(fmt.Sprintf("%s level %d", tc.name, tc.level), func(t *testing.T) {
			conn, err := net.Dial("tcp", h.Addr)
			if err != nil {
				t.Fatal(err)
			}
			defer conn.Close()
			vh := []byte{0x00, byte(len(tc.name))}
			vh = append(vh, tc.name...)
			vh = append(vh, tc.level, 0x02, 0x00, 0x3c)
			id := fmt.Sprintf("lvl-%d", tc.level)
			body := append(vh, 0x00, byte(len(id)))
			body = append(body, id...)
			if _, err := conn.Write(append([]byte{0x10, byte(len(body))}, body...)); err != nil {
				t.Fatal(err)
			}
			_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
			ack := make([]byte, 4)
			if _, err := io.ReadFull(conn, ack); err != nil || ack[0] != 0x20 {
				t.Fatalf("no CONNACK: % x (%v)", ack, err)
			}
			if ack[3] != tc.want {
				t.Errorf("%s at level %d was answered 0x%02X, want 0x%02X", tc.name, tc.level, ack[3], tc.want)
			}
		})
	}
}

// MQTT 5 section 3.1.3.4 and 3.1.1 section 3.1.3.3: a Will Payload is
// Binary Data, "zero or more bytes". RFC 0003: deleting a `latest` value is
// publishing an empty payload to its topic, so an empty retained Will is how
// a device has its value deleted when it dies.
//
// **The engine refused it as a protocol violation**, `0x82` to MQTT 5 and
// `0x05` to 3.1.1, reading [MQTT-3.1.2-9]'s "present" as "not empty" - a
// check from upstream mochi's v5 rewrite.
func TestAnEmptyWillIsAcceptedAndDeletesALatestValue(t *testing.T) {
	for _, version := range []byte{5, 4} {
		t.Run(fmt.Sprintf("MQTT level %d", version), func(t *testing.T) {
			h := start(t)
			p := connect(t, h, "setter", true, false)
			p.PubRetainedAt(t, "state/dev-1", "online", 1)
			// The control: the value is there to be deleted.
			before := connect(t, h, "before", true, false)
			before.Sub(t, "state/#", 1)
			if got, ok := before.Await(t, 2*time.Second); !ok || got.Payload != "online" {
				t.Fatalf("the latest value was not stored before the Will (got %q, %v), so nothing "+
					"below is about the class", got.Payload, ok)
			}
			before.Close()

			conn, err := net.Dial("tcp", h.Addr)
			if err != nil {
				t.Fatal(err)
			}
			topic, id := "state/dev-1", "dev-1"
			// Clean start, a retained QoS 1 Will, keepalive 60.
			vh := []byte{0x00, 0x04, 'M', 'Q', 'T', 'T', version, 0x02 | 0x04 | 0x08 | 0x20, 0x00, 0x3c}
			if version == 5 {
				vh = append(vh, 0x00) // no CONNECT properties
			}
			vh = append(vh, byte(len(id)>>8), byte(len(id)))
			vh = append(vh, id...)
			if version == 5 {
				vh = append(vh, 0x00) // no Will properties
			}
			vh = append(vh, byte(len(topic)>>8), byte(len(topic)))
			vh = append(vh, topic...)
			vh = append(vh, 0x00, 0x00) // a Will Payload of zero bytes
			if _, err := conn.Write(mqttPacket(0x10, vh)); err != nil {
				t.Fatal(err)
			}
			_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
			ack := make([]byte, 4)
			if _, err := io.ReadFull(conn, ack); err != nil || ack[0] != 0x20 || ack[3] != 0x00 {
				t.Fatalf("a CONNECT with an empty Will was answered % x (%v), want CONNACK 0x00", ack, err)
			}
			_ = conn.Close() // no DISCONNECT: the Will fires
			sessionGone(t, h, id)

			r := connect(t, h, "reader", true, false)
			r.Sub(t, "state/#", 1)
			if got, ok := r.Await(t, time.Second); ok {
				t.Errorf("the empty Will fired and a reader of state/# was still served %q on %s",
					got.Payload, got.Topic)
			}
		})
	}
}
